import sys

# ── Windows reload supervisor + single-instance guard (2026-10-16) ─────
# On Windows os.execv does not replace the process (it spawns a new one and the
# old exits), so the console goes back to the shell and a launcher can end up
# with TWO engines. On Windows this file now starts as a small supervisor that
# stays in the console and runs the engine as a CHILD. A live-update reload makes
# the child exit with SNIPER_RELOAD_EXIT_CODE and the supervisor starts the new
# code in the SAME window. Ctrl+C stops the engine, then the supervisor (twice
# forces). bots/sniper.py sets SNIPER_SUPERVISED=1 and does this job itself.
# SNIPER_NO_SUPERVISOR=1 opts out. Linux/Mac keep os.execv.
SNIPER_RELOAD_EXIT_CODE = 75


def _sniper_supervise():
    import subprocess as _sv_sp, time as _sv_t
    _env = dict(os.environ, SNIPER_SUPERVISED="1")
    _cmd = [sys.executable, os.path.abspath(__file__)] + sys.argv[1:]
    _reloads = []
    while True:
        _child = _sv_sp.Popen(_cmd, env=_env)
        _stopping, _rc = False, None
        while _rc is None:
            try:
                _rc = _child.wait(timeout=1.0)
            except _sv_sp.TimeoutExpired:
                continue
            except KeyboardInterrupt:
                if _stopping:
                    print("[supervisor] second Ctrl+C - force-stopping the engine")
                    try:
                        _child.kill()
                    except Exception:
                        pass
                else:
                    _stopping = True
                    print("[supervisor] Ctrl+C - engine is shutting down (Ctrl+C again to force)")
        if _stopping:
            return 0
        if _rc == SNIPER_RELOAD_EXIT_CODE:
            _now = _sv_t.time()
            _reloads = [t for t in _reloads if _now - t < 300] + [_now]
            if len(_reloads) > 5:
                print("[supervisor] 6 reloads inside 5 min - stopping to avoid a reload loop")
                return 1
            print("[supervisor] live-update reload - starting the new code in this window")
            continue
        return _rc


_SNIPER_LOCK_FH = None


def _sniper_single_instance():
    """Hold an exclusive OS lock for the engine's whole life. A second engine on
    the same install refuses to start. The OS frees the lock when the process
    exits (or execs), so a crash never leaves it stuck."""
    global _SNIPER_LOCK_FH
    _d = os.path.join(os.path.dirname(os.path.abspath(__file__)), "bot_logs")
    os.makedirs(_d, exist_ok=True)
    _lp, _pp = os.path.join(_d, "meme_sniper.engine.lock"), os.path.join(_d, "meme_sniper.engine.pid")
    _fh = open(_lp, "a+")
    try:
        if os.name == "nt":
            import msvcrt
            _fh.seek(0)
            msvcrt.locking(_fh.fileno(), msvcrt.LK_NBLCK, 1)
        else:
            import fcntl
            fcntl.flock(_fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError:
        _fh.close()
        try:
            _other = open(_pp, encoding="utf-8").read().strip()
        except Exception:
            _other = "?"
        print(f"[meme_sniper] another Sniper engine is already running (pid {_other}); refusing to start a second one.")
        raise SystemExit(3)
    _SNIPER_LOCK_FH = _fh
    try:
        with open(_pp, "w", encoding="utf-8") as _f:
            _f.write(str(os.getpid()))
    except Exception:
        pass


if __name__ == "__main__" and "--help" not in sys.argv[1:]:
    if (os.name == "nt" and os.environ.get("SNIPER_SUPERVISED") != "1"
            and _envv("SNIPER_NO_SUPERVISOR", "").strip().lower() not in ("1", "true", "yes")):
        raise SystemExit(_sniper_supervise() or 0)
    _sniper_single_instance()

