# ── DEXSCREENER SHARED LIMITER (2026-10-14 livefix) ──────────────────────────
# Every api.dexscreener.com call (async httpx AND the threaded urllib digest)
# goes through one process-wide token bucket. Profiles/boosts/orders = 60/min
# plan -> DEX_MAX_RPM; tokens/pairs/search = 300/min -> DEX_PAIRS_MAX_RPM.
# Max DEX_MAX_CONCURRENT in flight, small jitter, and a 429 pauses ALL callers.
import random as _dx_random
DEX_MAX_RPM        = float(_envv("DEX_MAX_RPM", "50"))
DEX_PAIRS_MAX_RPM  = float(_envv("DEX_PAIRS_MAX_RPM", "240"))
DEX_MAX_CONCURRENT = int(_envv("DEX_MAX_CONCURRENT", "2"))
_DX_LOCK = threading.Lock()
_DX = {"slow": [DEX_MAX_RPM / 60.0, min(5.0, DEX_MAX_RPM / 60.0 * 5), time.monotonic()],
       "pairs": [DEX_PAIRS_MAX_RPM / 60.0, min(10.0, DEX_PAIRS_MAX_RPM / 60.0 * 3), time.monotonic()],
       "inflight": 0, "backoff_until": 0.0, "n429": 0, "last_log": 0.0}


def _dx_kind(url: str) -> str:
    u = str(url)
    return "slow" if any(k in u for k in ("/token-profiles", "/token-boosts", "/orders/",
                                           "/community-takeovers", "/ads/")) else "pairs"


def _dx_is_dex(url) -> bool:
    return "api.dexscreener.com" in str(url)


def _dx_short(url) -> str:
    """path only; a comma batch becomes '<n> mints'."""
    try:
        p = str(url).split("api.dexscreener.com", 1)[-1].split("?", 1)[0]
        head, _, tail = p.rpartition("/")
        if "," in tail:
            return f"{head}/<{tail.count(',') + 1} mints>"
        return p if len(p) < 90 else p[:87] + "..."
    except Exception:
        return "dexscreener"


def _dx_try(kind: str) -> float:
    """0 = acquired; else seconds to wait."""
    with _DX_LOCK:
        now = time.monotonic()
        if now < _DX["backoff_until"]:
            return _DX["backoff_until"] - now
        if _DX["inflight"] >= max(1, DEX_MAX_CONCURRENT):
            return 0.05
        b = _DX[kind]
        rate, cap = b[0], max(1.0, b[0] * 5)
        b[1] = min(cap, b[1] + (now - b[2]) * rate)
        b[2] = now
        if b[1] >= 1.0:
            b[1] -= 1.0
            _DX["inflight"] += 1
            return 0.0
        return (1.0 - b[1]) / max(rate, 1e-6)


def _dx_release(status: Optional[int], retry_after=None) -> None:
    with _DX_LOCK:
        _DX["inflight"] = max(0, _DX["inflight"] - 1)
        if status == 429:
            try:
                wait = float(retry_after) if retry_after else _dx_random.uniform(20, 60)
            except (TypeError, ValueError):
                wait = _dx_random.uniform(20, 60)
            now = time.monotonic()
            _DX["backoff_until"] = max(_DX["backoff_until"], now + wait)
            _DX["n429"] += 1
            if now - _DX["last_log"] > 60:
                _DX["last_log"] = now
                try:
                    _log(f"dexscreener 429 - all dex calls paused {wait:.0f}s "
                         f"({_DX['n429']} 429s this run)", prefix="dex")
                except Exception:
                    pass


async def _dx_acquire_async(url) -> None:
    kind = _dx_kind(url)
    while True:
        w = _dx_try(kind)
        if w <= 0:
            break
        await asyncio.sleep(min(w, 5.0))
    await asyncio.sleep(_dx_random.uniform(0.02, 0.15))


def _dx_acquire_sync(url) -> None:
    kind = _dx_kind(url)
    while True:
        w = _dx_try(kind)
        if w <= 0:
            break
        time.sleep(min(w, 5.0))
    time.sleep(_dx_random.uniform(0.02, 0.15))


_dx_orig_send = httpx.AsyncClient.send


async def _dx_send(self, request, *a, **kw):
    if not _dx_is_dex(request.url):
        return await _dx_orig_send(self, request, *a, **kw)
    await _dx_acquire_async(request.url)
    st, ra = None, None
    try:
        resp = await _dx_orig_send(self, request, *a, **kw)
        st, ra = resp.status_code, resp.headers.get("Retry-After")
        return resp
    finally:
        _dx_release(st, ra)


httpx.AsyncClient.send = _dx_send

import urllib.request as _dx_urlreq
_dx_orig_urlopen = _dx_urlreq.urlopen


def _dx_urlopen(req, *a, **kw):
    url = req.full_url if hasattr(req, "full_url") else req
    if not _dx_is_dex(url):
        return _dx_orig_urlopen(req, *a, **kw)
    _dx_acquire_sync(url)
    st, ra = None, None
    try:
        r = _dx_orig_urlopen(req, *a, **kw)
        st = getattr(r, "status", 200)
        return r
    except Exception as e:
        st = getattr(e, "code", None)
        try:
            ra = e.headers.get("Retry-After")
        except Exception:
            pass
        raise
    finally:
        _dx_release(st, ra)


_dx_urlreq.urlopen = _dx_urlopen


