def _upg_pre_gate(pair, mint) -> dict:
    if _upg is None:
        return {}
    try:
        sig = _upg.pre_gate(pair, mint)
    except Exception as _e:
        sig = {"error": str(_e)[:120]}
    _UPG_CTX[mint] = sig
    if len(_UPG_CTX) > 4000:
        for _k in list(_UPG_CTX)[:2000]:
            _UPG_CTX.pop(_k, None)
    return sig


async def _upg_launch(mint, age_minutes):
    sig = _UPG_CTX.get(mint)
    if _upg is None:
        return sig
    sig = sig if isinstance(sig, dict) else {}
    try:
        _upg.ensure_moonshot_listener(helius_rpc,
                                      lambda m: watchlist_add(m, {"source": "moonshot_listener"}),
                                      lambda t: _log(t, prefix="moon"))
        b = await _upg.launch_signals(mint, helius_rpc, age_minutes)
        if b:
            sig["bundle"] = b
    except Exception as _e:
        sig["bundle_error"] = type(_e).__name__
    return sig or None


