HOLD_BENCHMARK_DEFAULT_FILE  = _BOT_LOGS / "hold_benchmark.json"   # agent-curated custom benchmark (never shipped)
_HOLD_BM_WARNED: set = set()
import re as _re_hb
_B58_CA = _re_hb.compile(r"^[1-9A-HJ-NP-Za-km-z]{32,44}$")


def _hold_benchmark_custom():
    """The owner's custom hold benchmark, or None.

    SNIPER_HOLD_BENCHMARK in bots/.env names a JSON file (relative to the workspace root,
    e.g. bot_logs/hold_benchmark.json) in the same shape as gork_standard.json. It is used
    only when valid: same criteria ids and load-bearing flags as the code rubric, bands and
    rules present, and `_benchmark` carrying BOTH a ticker and a Solana CA. A ticker-only
    value, a missing file or a bad file is ignored (logged once) and $GORK stays in force."""
    raw = str(_envv("SNIPER_HOLD_BENCHMARK", "") or "").strip()
    if not raw:
        return None
    def _warn(why):
        if why not in _HOLD_BM_WARNED:
            _HOLD_BM_WARNED.add(why)
            print(f"[hold] SNIPER_HOLD_BENCHMARK ignored ({why}); using $GORK (bot_logs/gork_standard.json)")
        return None
    p = Path(raw)
    if not p.is_absolute():
        p = Path(WS_ROOT) / raw
    if p.suffix.lower() != ".json":
        return _warn("must point to a benchmark .json file; a ticker alone is not enough")
    try:
        d = json.loads(p.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return _warn(f"{raw} not found")
    except Exception as e:
        return _warn(f"{raw} unreadable: {type(e).__name__}")
    if not isinstance(d, dict):
        return _warn("not a JSON object")
    bm = d.get("_benchmark") if isinstance(d.get("_benchmark"), dict) else {}
    tk, ca = str(bm.get("ticker") or "").strip(), str(bm.get("ca") or "").strip()
    if not tk or not _B58_CA.match(ca):
        return _warn("_benchmark needs both a ticker and a valid CA")
    want = [(c["id"], bool(c.get("load_bearing"))) for c in _GORK_STANDARD["criteria"]]
    crit = d.get("criteria")
    if not isinstance(crit, list) or [(c.get("id"), bool(c.get("load_bearing"))) for c in crit if isinstance(c, dict)] != want:
        return _warn("criteria must keep the same ids c1-c10 and load-bearing flags as gork_standard.json")
    if not all(k in d for k in ("bands", "rules", "load_bearing_law")):
        return _warn("missing bands / rules / load_bearing_law")
    return d


def load_gork_standard() -> dict:
    """The hold-score rubric. A valid custom benchmark file (SNIPER_HOLD_BENCHMARK) wins;
    otherwise the code rubric with the benchmark from bot_logs/gork_standard.json ($GORK),
    which is written on first use."""
    try:
        if not GORK_STANDARD_FILE.exists():
            _save_json_atomic(GORK_STANDARD_FILE, _GORK_STANDARD)
    except Exception:
        pass
    custom = _hold_benchmark_custom()
    if custom is not None:
        return custom
    std = dict(_GORK_STANDARD)
    try:   # no custom benchmark: the seed file's benchmark ($GORK by default)
        disk = json.loads(GORK_STANDARD_FILE.read_text(encoding="utf-8"))
        bm = disk.get("_benchmark") if isinstance(disk, dict) else None
        if isinstance(bm, dict) and bm.get("ticker"):
            std["_benchmark"] = bm
    except Exception:
        pass
    return std


def score_to_band(scores: dict, load_bearing_fail: bool = None) -> dict:
    """Map a hold-score card to a band + rope. Enforces the load-bearing law.

    THE KILL SWITCH IS NOT AVERAGEABLE. A token with C1=1 (three days old, no storm
    survived) and C5-C10 all 9s has a raw average of ~7.4 — 'patient' band, wide rope,
    real money. That is precisely the token a cabal builds: everything a scammer CAN
    manufacture, scored high; the one thing they CANNOT (time under fire), scored low.
    So the average is computed, reported, and then OVERRULED. Fail a load-bearing
    criterion and you are NOT-A-HOLD. Full stop.
    """
    std = load_gork_standard()
    lb_ids = std["load_bearing_law"]["criteria"]
    vals = {}
    for c in std["criteria"]:
        v = scores.get(c["id"]) if isinstance(scores, dict) else None
        if v is None:
            v = scores.get(c["name"]) if isinstance(scores, dict) else None
        vals[c["id"]] = _safe_num(v)

    present = [v for v in vals.values() if v is not None]
    raw_avg = round(sum(present) / len(present), 1) if present else None

    # a load-bearing FAIL = scored <= 2 on c1/c2/c4 (or explicitly flagged)
    fails = [cid for cid in lb_ids if (vals.get(cid) is not None and vals[cid] <= 2)]
    if load_bearing_fail:
        fails = fails or ["explicit"]

    if fails:
        return {
            "raw_avg": raw_avg,
            "load_bearing_fails": fails,
            "band": "not-a-hold",
            "auto_reject": True,
            "rope": "No hold capital. Flip rules only, if traded at all.",
            "rescore_hours": None,
            "verdict": (
                f"NOT-A-HOLD — load-bearing fail on {', '.join(fails).upper()}. "
                f"Raw average was {raw_avg} but that number is IRRELEVANT: you do not average "
                f"away a kill switch. "
                + ("C1 (time under fire) is the one axis a scammer cannot fake — without a "
                   "completed storm you have no evidence of a people, only a launch costume. "
                   if "c1" in fails else "")
                + ("C2 (red-tape output) failing means the conviction was RENTED — green spam is "
                   "cheap, red speech is expensive, and this community doesn't speak when it hurts. "
                   if "c2" in fails else "")
                + ("C4 (origin integrity) failing means you'd be funding their exit. Origin is destiny. "
                   if "c4" in fails else "")
                + "The snipe lane is still open. The HOLD lane is closed."
            ),
        }

    band = next((b for b in std["bands"]
                 if raw_avg is not None and b["score"][0] <= raw_avg <= b["score"][1]),
                std["bands"][0])
    return {
        "raw_avg": raw_avg,
        "load_bearing_fails": [],
        "band": band["band"],
        "auto_reject": band["auto_reject"],
        "rope": band["rope"],
        "rescore_hours": band["rescore_hours"],
        "verdict": f"{band['band'].upper()} ({raw_avg}/10) — {band['rope']}",
    }



