# Sprint 32+: meeting files runtime state with expiry tracking.
# Storage shape: {param: {"value": v, "expires_at": iso_or_None, "applied_at": iso, "reason": str}}
# Public API get_override(name, fallback) unwraps ["value"] for callers so existing
# decision-code callsites keep working unchanged.
_ACTIVE_OVERRIDES: dict = {}
_ACTIVE_OVERRIDES_LOCK: Optional[asyncio.Lock] = None  # initialized in main()


def _get_active_overrides_lock() -> asyncio.Lock:
    """Lazy init for the global lock (asyncio.Lock can't be created at module load)."""
    global _ACTIVE_OVERRIDES_LOCK
    if _ACTIVE_OVERRIDES_LOCK is None:
        _ACTIVE_OVERRIDES_LOCK = asyncio.Lock()
    return _ACTIVE_OVERRIDES_LOCK


def _unwrap_override_entry(entry, fallback):
    """Sprint 32+: unwrap the new dict-shape entry to its value, or fall back."""
    if entry is None:
        return fallback
    if isinstance(entry, dict) and "value" in entry:
        return entry["value"]
    return entry  # legacy raw value, return as-is


async def get_override(param_name: str, fallback):
    """
    Read an active override for a tunable parameter.
    
    All loops use this to fetch parameter values instead of reading the constant
    directly. Returns the override value if set; otherwise returns fallback.
    
    Sprint 32+: entries are dict-shaped {value, expires_at, applied_at, reason}.
    This helper unwraps ["value"] for callers so all existing get_override callsites
    in trade-decision code keep working unchanged.
    
    Lock-free read for performance (dict reads are atomic in CPython).
    """
    return _unwrap_override_entry(_ACTIVE_OVERRIDES.get(param_name), fallback)


def get_override_sync(param_name: str, fallback):
    """Sync version of get_override for use in non-async contexts. Same unwrap behavior."""
    return _unwrap_override_entry(_ACTIVE_OVERRIDES.get(param_name), fallback)


def _knob_f(name: str) -> float:
    try:
        return float(get_override_sync(name, 0) or 0)
    except Exception:
        return 0.0


def _owner_buy_size_sol() -> float:
    """SNIPER_BUY_SIZE_SOL (0 = unset)."""
    return max(0.0, _knob_f("SNIPER_BUY_SIZE_SOL"))


def _base_size_cap() -> float:
    """Base entry cap: the owner's buy size when set, else SIZE_CAP_BASE_SOL (unchanged)."""
    b = _owner_buy_size_sol()
    return b if b > 0 else float(get_override_sync("SIZE_CAP_BASE_SOL", SIZE_CAP_BASE_SOL))


def _size_tier_factor() -> float:
    """Tier ladder scale when the owner's buy size is set below SIZE_CAP_BASE_SOL (never scales up)."""
    b = _owner_buy_size_sol()
    base = float(get_override_sync("SIZE_CAP_BASE_SOL", SIZE_CAP_BASE_SOL) or 0)
    if b <= 0 or base <= 0:
        return 1.0
    return min(1.0, b / base)


def _tier_cap(name: str, const: float) -> float:
    v = float(get_override_sync(name, const))
    f = _size_tier_factor()
    return v if f >= 1.0 else max(v * f, _base_size_cap())


# bots/.env -> filter knob seeding. The owner's .env value wins whenever it CHANGES
# (wizard, Settings .env row, hand edit); in between, the agent / Settings filter row /
# learning mode own the knob. Last-seeded values live in WIZARD_SEED_STATE.
WIZARD_SEED_STATE = Path(WS_BOT_LOGS) / "wizard_env_seed.json"
_WIZARD_SEED_MTIME = {"m": None}


def _wizard_env_values() -> dict:
    vals = {}
    try:
        from dotenv import dotenv_values
        vals = {k: v for k, v in (dotenv_values(str(_BASE / ".env")) or {}).items() if v not in (None, "")}
    except Exception:
        vals = {}
    keys = {
        "SNIPER_BUY_SIZE_SOL": vals.get("SNIPER_BUY_SIZE_SOL", os.getenv("SNIPER_BUY_SIZE_SOL")),
        "SNIPER_DEFAULT_SL_PCT": vals.get("SNIPER_DEFAULT_SL_PCT", os.getenv("SNIPER_DEFAULT_SL_PCT")),
        "SNIPER_DEFAULT_TP_PCT": vals.get("SNIPER_DEFAULT_TP_PCT", os.getenv("SNIPER_DEFAULT_TP_PCT")),
        "SNIPER_LEARNING_MODE": vals.get("SNIPER_LEARNING_MODE", os.getenv("SNIPER_LEARNING_MODE")),
        "SNIPER_LEARN_REST": vals.get("SNIPER_LEARN_REST", os.getenv("SNIPER_LEARN_REST")),
        "SNIPER_LEARN_COOLDOWN_H": vals.get("SNIPER_LEARN_COOLDOWN_H", os.getenv("SNIPER_LEARN_COOLDOWN_H")),
        "SNIPER_LEARN_MIN_TRADES": vals.get("SNIPER_LEARN_MIN_TRADES", os.getenv("SNIPER_LEARN_MIN_TRADES")),
        "SNIPER_LEARN_STEP_PCT": vals.get("SNIPER_LEARN_STEP_PCT", os.getenv("SNIPER_LEARN_STEP_PCT")),
    }
    return {k: str(v).strip() for k, v in keys.items() if v not in (None, "") and str(v).strip() != ""}


def _seed_wizard_knobs_from_env(force: bool = False) -> list:
    """Copy changed bots/.env wizard keys into the filter file (by=owner_env). Returns changed keys."""
    try:
        ep = _BASE / ".env"
        m = ep.stat().st_mtime if ep.exists() else 0
    except Exception:
        m = 0
    if not force and _WIZARD_SEED_MTIME["m"] == m:
        return []
    _WIZARD_SEED_MTIME["m"] = m
    try:
        seen = json.loads(WIZARD_SEED_STATE.read_text(encoding="utf-8")) if WIZARD_SEED_STATE.exists() else {}
    except Exception:
        seen = {}
    changed = []
    for k, raw in _wizard_env_values().items():
        if seen.get(k) == raw:
            continue
        spec = TUNABLE_PARAMS.get(k) or {}
        try:
            if spec.get("type") == "bool":
                v = raw.lower() in ("1", "true", "yes", "on")
            else:
                v = float(raw)
                if spec.get("min") is not None:
                    v = max(float(spec["min"]), v)
                if spec.get("max") is not None:
                    v = min(float(spec["max"]), v)
        except Exception:
            _log(f"wizard seed: {k}={raw!r} is not valid; ignored", prefix="filter")
            seen[k] = raw
            continue
        try:
            ok, err = apply_filter_change(k, v, by="owner_env", reason=f"bots/.env {k}={raw}")
        except Exception as e:
            ok, err = False, str(e)
        if ok:
            changed.append(k)
            seen[k] = raw
        else:
            _log(f"wizard seed: {k} not applied: {err}", prefix="filter")
    try:
        WIZARD_SEED_STATE.write_text(json.dumps(seen, indent=1), encoding="utf-8")
    except Exception:
        pass
    return changed


# ============================================================================
#   LIVE-UPDATE (element e) - TRADING-EXECUTOR variant, STRICT safe-point
# ============================================================================
# meme_sniper executes on-chain buys/sells, so it must NEVER re-exec mid-swap. A
# _MEME_OP_IN_FLIGHT counter (raised by @_meme_inflight) gates the reload.
# Decorated submit paths (must stay in sync with @_meme_inflight sites):
#   execute_buy_signal, execute_sell_signal, execute_sell_holding,
#   execute_ledger_sweep, jupiter_swap_execute, _sell_chunked, _dust_sweep,
#   plus any panic_* that submits. os.execv only when inflight==0 AND no
#   has_inflight_sell(*) pending row AND past min-uptime.
# Floor: reload only a owner-applied patch on disk; never fetch/self-modify.
import sys as _lu_sys
import shutil as _lu_shutil
import hashlib as _lu_hashlib
import time as _lu_time

_MEME_OP_IN_FLIGHT = 0


def _meme_inflight(fn):
    async def _w(*a, **k):
        global _MEME_OP_IN_FLIGHT
        _MEME_OP_IN_FLIGHT += 1
        try:
            return await fn(*a, **k)
        finally:
            _MEME_OP_IN_FLIGHT -= 1
    _w.__name__ = getattr(fn, "__name__", "wrapped")
    _w.__doc__ = fn.__doc__
    return _w


_LU_SELF     = os.path.abspath(__file__)
_LU_MARKER   = os.path.join(WS_BOT_LOGS, "meme_sniper_reload.json")
_LU_LASTGOOD = _LU_SELF + ".last-good"
_LU_MIN_UPTIME_S = 120
_LU_POLL_S = 30


def _lu_mtime(pp):
    try:
        return os.path.getmtime(pp)
    except Exception:
        return 0.0


def _lu_hash(pp):
    try:
        with open(pp, "rb") as f:
            return _lu_hashlib.sha256(f.read()).hexdigest()[:8]
    except Exception:
        return ""


_LU_BOOT_MTIME = _lu_mtime(_LU_SELF)
_LU_BOOT_HASH  = _lu_hash(_LU_SELF)
_LU_BOOT_TS    = _lu_time.time()


def _lu_snapshot_last_good():
    try:
        _lu_shutil.copy2(_LU_SELF, _LU_LASTGOOD)
    except Exception:
        pass


def _lu_write_report(kind, severity, summary, extra=None):
    try:
        _dest = _INBOX
        _dest.mkdir(parents=True, exist_ok=True)
        ts = datetime.now(EST).strftime("%Y%m%d_%H%M%S")
        fpath = _dest / f"meme_sniper - {kind}_{ts}.md"
        fm = {"kind": kind, "severity": severity, "dedupe_key": f"meme_sniper:{kind}",
              "source_skill": "meme_sniper", "summary": summary}
        lines = ["---"] + [f"{k}: {v}" for k, v in fm.items()] + ["---", "",
                 f"# meme_sniper {kind}", summary]
        if extra:
            lines += ["", "```json", json.dumps(extra, indent=2, default=str), "```"]
        fpath.write_text("\n".join(lines), encoding="utf-8")
    except Exception as e:
        _log(f"[live-update] report failed: {e}", prefix="live-update")


def _lu_on_boot():
    marker = None
    try:
        if os.path.exists(_LU_MARKER):
            with open(_LU_MARKER, "r", encoding="utf-8") as f:
                marker = json.load(f)
    except Exception:
        marker = None
    if isinstance(marker, dict):
        _lu_write_report("bot_restart", "info",
                         f"meme_sniper reloaded {marker.get('from_hash')} -> {marker.get('to_hash')} (live-update, healthy)",
                         marker)
        try:
            os.remove(_LU_MARKER)
        except Exception:
            pass
    _lu_snapshot_last_good()


def _lu_reload_now():
    new_hash = _lu_hash(_LU_SELF)
    _lu_snapshot_last_good()
    try:
        with open(_LU_MARKER, "w", encoding="utf-8") as f:
            json.dump({"from_hash": _LU_BOOT_HASH, "to_hash": new_hash,
                       "detected_at": datetime.now(EST).isoformat(), "lastgood": _LU_LASTGOOD}, f)
    except Exception:
        pass
    _log(f"[live-update] reloading {_LU_BOOT_HASH} -> {new_hash} (safe point, no op in flight, re-exec)", prefix="live-update")
    # 2026-10-16: under a supervisor (this file's own, or bots/sniper.py) exit with
    # the reload code; the supervisor restarts the new code in the SAME console.
    if os.environ.get("SNIPER_SUPERVISED") == "1":
        try:
            _ui_deactivate()
        except Exception:
            pass
        _log("[live-update] handing back to the supervisor for a same-window restart", prefix="live-update")
        try:
            _lu_sys.stdout.flush()
        except Exception:
            pass
        os._exit(SNIPER_RELOAD_EXIT_CODE)
    try:
        _argv = [_lu_sys.executable, _LU_SELF] + _lu_sys.argv[1:]
        if os.name == "nt":  # execv does not quote: "GitHub Launches" would split
            _argv = [f'"{a}"' if (" " in a and not a.startswith('"')) else a for a in _argv]
        os.execv(_lu_sys.executable, _argv)
    except Exception as e:
        _log(f"[live-update] os.execv failed, staying on current code: {e}", prefix="live-update")
        _lu_write_report("bot_restart_failed", "high",
                         f"meme_sniper patch {new_hash} detected but re-exec failed; STILL RUNNING old {_LU_BOOT_HASH}",
                         {"error": str(e)[:200]})
        try:
            os.remove(_LU_MARKER)
        except Exception:
            pass


async def live_update_watcher_loop():
    """Trading-executor safe-point reload. Reloads ONLY when a patch is on disk AND no
    on-chain op is in flight AND past min-uptime. Reload with OPEN positions but no op
    in flight is safe: positions live on-chain + in positions.json; reloaded bot resumes."""
    _log(f"[live-update] watcher online (poll {_LU_POLL_S}s, boot {_LU_BOOT_HASH})", prefix="live-update")
    while True:
        try:
            _any_pending_sell = False
            try:
                _prows = _load_pending_confirmations() or {}
                if _PENDING_READ_FAILED:
                    _any_pending_sell = True
                else:
                    for _pr in _prows.values():
                        if ((_pr.get("side") in ("sell", "swap") or _pr.get("direction") == "sell")
                                and _pr.get("state") == "pending"
                                and _now_ts() - (_pr.get("submitted_ts") or 0) < _PENDING_INFLIGHT_GUARD_S):
                            _any_pending_sell = True
                            break
            except Exception:
                _any_pending_sell = True
            if ((_lu_time.time() - _LU_BOOT_TS) >= _LU_MIN_UPTIME_S
                    and _MEME_OP_IN_FLIGHT == 0
                    and not _any_pending_sell
                    and _lu_mtime(_LU_SELF) > _LU_BOOT_MTIME
                    and _lu_hash(_LU_SELF) != _LU_BOOT_HASH):
                _lu_reload_now()
        except Exception as e:
            _log(f"[live-update] watcher err: {e}", prefix="live-update")
        await asyncio.sleep(_LU_POLL_S)


# ════════════════════════════════════════════════════════════════════════════
#                   v13.0 FILTER FILE SYSTEM (smart self-documenting)
# ════════════════════════════════════════════════════════════════════════════
# 
# bots/tuner/meme_sniper_filter.json is the persistent source of truth for
# every tunable parameter. Schema per knob:
#
#   "KNOB_NAME": {
#     "value": <current active value>,
#     "default": <revert target on expires_at>,
#     "code_default": <original code-shipped default, preserved>,
#     "expires_at": null | "2026-05-25T18:00:00-04:00",
#     "unit": "USD" | "seconds" | "ratio" | ...,
#     "description": "what this knob does",
#     "tunable": true | false,
#     "type": "int" | "float" | "bool" | "usd",
#     "min": <lower bound or null>,
#     "max": <upper bound or null>,
#     "history": [
#       {"changed_at": iso, "from": <old>, "to": <new>,
#        "change_type": "value_update"|"default_promotion"|"expires_set"|"reverted",
#        "by": "meeting_watcher"|"file_watcher"|"first_boot", "reason": "..."}
#     ]
#   }
#
# Three write paths converge on the file (all use save_filter_file_atomic):
#   1) meeting_watcher_loop interprets directives and writes _ACTIVE_OVERRIDES.
#      CORRECTED 2026-08-16: it does NOT call apply_filter_change(). It never
#      has. That function's only caller is the tune_response path, where
#      The agent answers a tune invitation. So a meeting note is a RUNTIME change
#      that dies at the next restart, and a tune response is the durable one
#      that reaches the file with a history entry. Two routes that look alike
#      from the outside and differ in whether the change still exists tomorrow.
#   2) the agent edits the file directly; file_watcher_loop detects mtime change,
#      reloads _ACTIVE_OVERRIDES from disk
#   3) Tune-up cron writes a sniper_meeting.json (path 1 from above)
#
# Bootstrap behavior: if MEME_SNIPER_FILTER_FILE doesn't exist on boot, the
# bot auto-generates it from TUNABLE_PARAMS defaults. Existing file with
# missing tunables (after a code update added new TUNABLE_PARAMS) gets
# the new knobs added at defaults, preserving existing values.
#
# Per-knob inline history is capped at FILTER_HISTORY_INLINE_CAP entries.
# When a knob exceeds the cap, the oldest entries are rotated to
# meme_sniper_filter_history.jsonl (append-only).


def build_filter_entry_from_spec(name: str, spec: dict, *, value=None) -> dict:
    """Build a fresh filter-file entry for a given TUNABLE_PARAMS knob."""
    code_default = spec.get("default")
    initial_value = value if value is not None else code_default
    return {
        "value": initial_value,
        "default": code_default,
        "code_default": code_default,
        "expires_at": None,
        "unit": spec.get("unit"),
        "description": spec.get("description"),
        "tunable": True,
        "type": spec.get("type"),
        "min": spec.get("min"),
        "max": spec.get("max"),
        "history": [],
    }


def generate_filter_file_from_tunable_params() -> dict:
    """Build a fresh meme_sniper_filter.json structure from current TUNABLE_PARAMS."""
    return {
        "_meta": {
            "schema_version": "v1.0",
            "bot": "meme_sniper",
            "created_at": _now_iso(),
            "last_modified_at": _now_iso(),
            "last_modified_by": "first_boot_autogen",
            "doc": (
                "Source of truth for every tunable parameter in meme_sniper. "
                "Edit directly (file watcher reloads on mtime change) OR write "
                "natural-language directive to bots/json_relay/sniper_meeting.json. "
                "Hardcoded floors (bonded dexId, freeze/mint authority null) live in "
                "code, not here — they are never tunable."
            ),
        },
        "knobs": {
            name: build_filter_entry_from_spec(name, spec)
            for name, spec in TUNABLE_PARAMS.items()
        },
    }


def load_filter_file() -> Optional[dict]:
    """Read the filter file from disk. Returns None if missing/corrupt."""
    if not MEME_SNIPER_FILTER_FILE.exists():
        return None
    try:
        with open(MEME_SNIPER_FILTER_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict) or "knobs" not in data:
            _log(f"filter_file: shape invalid ({MEME_SNIPER_FILTER_FILE}); ignoring", prefix="filter")
            return None
        return data
    except Exception as e:
        _log(f"filter_file load err: {e}", prefix="filter")
        return None


def save_filter_file_atomic(data: dict) -> None:
    """Write the filter file atomically (.tmp + os.replace)."""
    if "_meta" not in data:
        data["_meta"] = {}
    data["_meta"]["last_modified_at"] = _now_iso()
    _save_json_atomic(MEME_SNIPER_FILTER_FILE, data)


def _rotate_knob_history_if_needed(knob_entry: dict, knob_name: str) -> None:
    """If a knob's inline history exceeds the cap, roll older entries to
    the JSONL history log. Mutates knob_entry in place."""
    history = knob_entry.get("history") or []
    if len(history) <= FILTER_HISTORY_INLINE_CAP:
        return
    keep = history[-FILTER_HISTORY_INLINE_CAP:]
    rotate = history[:-FILTER_HISTORY_INLINE_CAP]
    for entry in rotate:
        try:
            _append_jsonl(MEME_SNIPER_FILTER_HISTORY, {
                "rotated_at": _now_iso(),
                "knob": knob_name,
                **entry,
            })
        except Exception:
            pass
    knob_entry["history"] = keep


def apply_filter_change(
    knob_name: str,
    new_value,
    *,
    new_default=None,
    new_expires_at: Optional[str] = None,
    change_type: str = "value_update",
    by: str = "meeting_watcher",
    reason: str = "",
) -> tuple[bool, str]:
    """Apply a single knob change to the filter file. Atomic.
    
    change_type:
      - "value_update":     change the current value (default unchanged unless new_default given)
      - "default_promotion":  also change default to the new value (permanent shift)
      - "expires_set":      sets an expires_at on the current value
      - "reverted":         the expiry_watcher reverted value→default
    
    Returns (success, error_msg). On failure, no state changes.
    """
    data = load_filter_file()
    if data is None:
        return False, "filter_file_missing"
    
    knobs = data.get("knobs") or {}
    knob = knobs.get(knob_name)
    if knob is None:
        return False, f"unknown_knob: {knob_name}"
    
    if not knob.get("tunable", True):
        return False, f"knob_not_tunable: {knob_name}"
    
    # Bounds check
    if knob.get("min") is not None and new_value is not None:
        try:
            if float(new_value) < float(knob["min"]):
                return False, f"below_min: {knob_name} new_value={new_value} min={knob['min']}"
        except (TypeError, ValueError):
            pass
    if knob.get("max") is not None and new_value is not None:
        try:
            if float(new_value) > float(knob["max"]):
                return False, f"above_max: {knob_name} new_value={new_value} max={knob['max']}"
        except (TypeError, ValueError):
            pass
    
    old_value = knob.get("value")
    old_default = knob.get("default")
    
    # Apply the change
    knob["value"] = new_value
    if change_type == "default_promotion":
        knob["default"] = new_value if new_default is None else new_default
        knob["expires_at"] = None
    elif new_default is not None:
        knob["default"] = new_default
    if new_expires_at is not None:
        knob["expires_at"] = new_expires_at
    
    # Record history
    entry = {
        "changed_at": _now_iso(),
        "from": old_value,
        "to": new_value,
        "change_type": change_type,
        "by": by,
        "reason": reason,
    }
    if change_type == "default_promotion" and old_default != new_value:
        entry["default_from"] = old_default
        entry["default_to"] = new_value
    knob.setdefault("history", []).append(entry)
    _rotate_knob_history_if_needed(knob, knob_name)
    
    data["_meta"]["last_modified_by"] = by
    save_filter_file_atomic(data)
    
    # Update _ACTIVE_OVERRIDES immediately so the change takes effect without
    # waiting for the file watcher to fire.
    _ACTIVE_OVERRIDES[knob_name] = {
        "value": new_value,
        "expires_at": knob.get("expires_at"),
        "applied_at": _now_iso(),
        "reason": reason,
    }
    
    _log(
        f"filter: {knob_name} {old_value} → {new_value} "
        f"(change_type={change_type}, by={by}, reason={reason!r})",
        prefix="filter",
    )
    return True, ""


def reload_active_overrides_from_filter_file() -> int:
    """Read the filter file and rebuild _ACTIVE_OVERRIDES from it. Returns the
    count of knobs loaded into runtime state."""
    data = load_filter_file()
    if data is None:
        return 0
    
    knobs = data.get("knobs") or {}
    new_overrides: dict = {}
    for knob_name, knob in knobs.items():
        if not isinstance(knob, dict):
            continue
        value = knob.get("value")
        if value is None:
            continue
        new_overrides[knob_name] = {
            "value": value,
            "expires_at": knob.get("expires_at"),
            "applied_at": _now_iso(),
            "reason": "loaded_from_filter_file",
        }
    
    global _ACTIVE_OVERRIDES
    _ACTIVE_OVERRIDES = new_overrides
    return len(new_overrides)


def _write_filter_schema_stale_packet(drifted: list, knobs: dict) -> None:
    """FIX 1 (2026-08-15): a stale default that nobody chose is a decision request.

    The drift detector stamps the knob and logs. A log line at boot is read by
    nobody. TRENDING_TICK ran at 1h/2h for weeks with the const saying 15min and
    the only evidence was a number in a json file that agreed with itself.

    So the never-hand-tuned drifts - the ones where the value in effect is a
    stale default rather than somebody's decision - become an inbox packet with
    the promotion named and NOT taken. Hand-tuned knobs are listed separately and
    explicitly left alone: a knob the owner moved on purpose must never be reset by a
    code change, and the packet says so instead of quietly skipping it.

    Never raises. A packet failure must not stop the bot booting.
    """
    try:
        untouched = [d for d in drifted if not d[3]]
        hand_tuned = [d for d in drifted if d[3]]
        packet = {
            "type": "filter_schema_stale",
            "from": "meme_sniper",
            "to": "agent",
            "fired_at": _now_iso(),
            "severity": "decision_request",
            "headline": (f"{len(untouched)} knob(s) are running a code default that is no "
                          f"longer the code default. Nobody chose these numbers."),
            "what_happened": (
                "The filter file is generated from TUNABLE_PARAMS and the loops read the "
                "FILE. When a code change moves a const, the file keeps the old number and "
                "the new one never goes live. Boot sync adds and retires knobs; it does not "
                "and must not silently rewrite a value."
            ),
            "stale_defaults_nobody_chose": [
                {
                    "knob": n,
                    "value_in_effect": (knobs.get(n) or {}).get("value"),
                    "file_code_default": old,
                    "current_code_default": new,
                    "promotion": f"set {n} = {new}",
                }
                for n, old, new, _t in untouched
            ],
            "hand_tuned_leave_alone": [
                {
                    "knob": n,
                    "value_in_effect": (knobs.get(n) or {}).get("value"),
                    "file_code_default": old,
                    "current_code_default": new,
                    "note": "you tuned this deliberately. The code default moved under it. "
                             "Your value stands unless you say otherwise.",
                }
                for n, old, new, _t in hand_tuned
            ],
            "actions_taken": [],
            "_doctrine": (
                "This packet changes nothing. Promotion is a deliberate act - write a "
                "meeting note to json_relay/sniper_meeting.json naming the knob and the "
                "number. A boot that silently reset values would be a worse bug than the "
                "one it fixes."
            ),
        }
        write_inbox_packet_generic(packet, prefix="meme_sniper",
                                    identifier=f"filter_schema_stale_{len(drifted)}")
        _log(f"filter_file: filter_schema_stale packet written "
             f"({len(untouched)} unchosen, {len(hand_tuned)} hand-tuned)", prefix="filter")
    except Exception as e:
        _log(f"filter_file: filter_schema_stale packet failed (non-fatal): {e}",
             prefix="filter")


def ensure_filter_file_initialized() -> None:
    """First-boot bootstrap: if the filter file doesn't exist, generate it
    from TUNABLE_PARAMS defaults. If it exists but is missing knobs (after
    a code update added new TUNABLE_PARAMS), add the new knobs at defaults
    without disturbing existing values."""
    existing = load_filter_file()
    if existing is None:
        fresh = generate_filter_file_from_tunable_params()
        save_filter_file_atomic(fresh)
        _log(
            f"filter_file: first-boot generation complete "
            f"({len(fresh['knobs'])} knobs at defaults) → {MEME_SNIPER_FILTER_FILE.name}",
            prefix="filter",
        )
        return
    
    existing_knobs = existing.get("knobs") or {}

    # ── RETIRE knobs the code no longer has (2026-07-27) ────────────────────
    # This function only ever ADDED. Retired knobs stayed in the file forever,
    # still marked "tunable": true, so the file advertised controls the bot did
    # not have — and the agent could tune one, see it applied, and change nothing.
    # Observed: SCAN_TICK_OFFHOURS_SECONDS survived Sprint 45 removing the very
    # behavior it described. The boot log even COMPUTED removed_tunables and
    # then used it only in a print.
    # Retired knobs are ARCHIVED, not deleted — the agent's tuning history is real
    # evidence and outlives the knob. They move to _retired with a stamp.
    retired = [k for k in list(existing_knobs.keys()) if k not in TUNABLE_PARAMS]
    if retired:
        arch = existing.setdefault("_retired", {})
        for k in retired:
            entry = existing_knobs.pop(k)
            entry["retired_at"] = _now_iso()
            entry["tunable"] = False
            entry["retired_reason"] = "no longer in TUNABLE_PARAMS (code removed the knob)"
            arch[k] = entry
        _log(f"filter_file: RETIRED {len(retired)} knob(s) the code no longer has "
             f"-> _retired (history preserved): {', '.join(retired)}", prefix="filter")

    added = []
    drifted = []                    # F2: knobs whose code_default moved under them
    meta_refreshed = set()          # FIX 1: knobs whose captions were re-synced from schema
    for name, spec in TUNABLE_PARAMS.items():
        if name not in existing_knobs:
            existing_knobs[name] = build_filter_entry_from_spec(name, spec)
            existing_knobs[name]["history"].append({
                "changed_at": _now_iso(),
                "from": None,
                "to": existing_knobs[name]["value"],
                "change_type": "first_boot_add",
                "by": "bootstrap",
                "reason": "knob added to TUNABLE_PARAMS in newer code version",
            })
            added.append(name)
        else:
            # ── F2 (2026-08-15): CODE_DEFAULT DRIFT WAS INVISIBLE ────────────
            # This function adds missing knobs and retires unknown ones, and never
            # looks at an EXISTING knob again. So when a Sprint changes a const,
            # the filter file keeps the old code_default forever and - because the
            # loop reads the FILE - the new const never takes effect.
            #
            # That is exactly how TRENDING_TICK sat at 1h/2h while the const said
            # 15min (F1), and it is the same bug trail hit on 2026-08-05, which
            # needed a hand-written `default_promotion` to stop 15/25 overriding
            # 12/20. Two instances, same mechanism, both found by audit rather than
            # by the system.
            #
            # NOT auto-applied: a knob the owner tuned by hand must not be silently
            # reset by a code change. Detection only - the drift is stamped on the
            # knob and logged loudly, so a stale default is visible instead of
            # winning quietly. Promotion stays a deliberate act.
            try:
                _cur_cd = existing_knobs[name].get("code_default")
                _new_cd = spec.get("default")
                if _cur_cd != _new_cd and _new_cd is not None:
                    _was_tuned = bool([h for h in (existing_knobs[name].get("history") or [])
                                       if h.get("change_type") not in
                                       ("first_boot_add", "code_default_drift",
                                        "code_default_refresh")])
                    existing_knobs[name]["code_default_drift"] = {
                        "file_code_default": _cur_cd,
                        "current_code_default": _new_cd,
                        "detected_at": _now_iso(),
                        "value_in_effect": existing_knobs[name].get("value"),
                        "hand_tuned": _was_tuned,
                        "resolved": True,
                        "note": ("the code's default changed and this file was carrying the "
                                 "old one. The LOOP READS THIS FILE's `value`, so the new code "
                                 "default is NOT in effect. `code_default` has been corrected "
                                 "to the current code default so `value` now reads honestly as "
                                 "an override; `value` itself was NOT touched. If this knob was "
                                 "never hand-tuned, the value in effect is a stale default "
                                 "nobody chose - promote it deliberately (default_promotion) "
                                 "rather than assuming the const is live."),
                    }
                    # ── FIX 1 (2026-08-15): DETECTION THAT NEVER CLEARS IS AN ALARM
                    # NOBODY HEARS. The first cut of this stamped the drift and left
                    # `code_default` stale, which meant the condition stayed true and
                    # the boot fired the same finding on every restart forever. An
                    # alert that repeats identically becomes furniture.
                    #
                    # `code_default` is a REFERENCE field: what the code ships today.
                    # Nothing reverts to it (expiry reverts to `default`), nothing
                    # else reads it, and leaving it stale is what made `is_overridden`
                    # lie in both directions. Correcting it is the honest move: a
                    # `value` of 3600 against a `code_default` of 900 now reads as
                    # what it is - a live number that disagrees with the code.
                    #
                    # The OLD value is not lost. It goes into `history` as its own
                    # entry, which is where "was 3600" belonged all along.
                    existing_knobs[name].setdefault("history", []).append({
                        "changed_at": _now_iso(),
                        "from": _cur_cd,
                        "to": _new_cd,
                        "change_type": "code_default_refresh",
                        "by": "bootstrap",
                        "reason": ("code default moved; reference field corrected. The live "
                                   "`value` was NOT changed."),
                    })
                    existing_knobs[name]["code_default"] = _new_cd
                    drifted.append((name, _cur_cd, _new_cd, _was_tuned))
            except Exception:
                pass

            # ── FIX 1 (2026-08-15): THE CAPTIONS WENT STALE TOO ──────────────
            # Drift detection above covers the NUMBER. It does not cover the
            # words wrapped around it, and those words are what the meeting
            # interpreter and the tune invitation actually read.
            #
            # Live proof: trail values were reconciled to 12/20 on 2026-08-05
            # and the file descriptions still advertised "Default 15" and
            # "Default 25" ten days later. A tune invitation quoting that file
            # argues with a caption instead of the knob, and the LLM matching a
            # directive to a param matches on `description`. EDGE_LIQ was worse:
            # its schema copy said "to pass the owner's edge filter" for months after
            # A1 took liquidity off the gate path entirely.
            #
            # description / unit / min / max / type are DERIVED from the schema.
            # Nobody hand-edits them, so refreshing them destroys nothing and
            # keeps the file's prose honest. `value` is never touched here -
            # that is the number, and only a deliberate promotion moves it.
            try:
                _e = existing_knobs[name]
                for _meta_key in ("description", "unit", "min", "max", "type"):
                    _new_meta = spec.get(_meta_key)
                    if _e.get(_meta_key) != _new_meta:
                        _e[_meta_key] = _new_meta
                        meta_refreshed.add(name)
            except Exception:
                pass
    # Persist a retirement even when nothing was ADDED. My own bug, 2026-07-27:
    # the save below is gated on `added`, so a boot that only retired knobs
    # mutated the dict and never wrote it — the log said RETIRED twice on two
    # consecutive boots and the override count stayed at 73 against a 71-knob
    # file. Retirement is a write in its own right.
    if retired and not added:
        existing["knobs"] = existing_knobs
        save_filter_file_atomic(existing)
        _log(f"filter_file: retirement persisted ({len(existing_knobs)} active knobs)",
             prefix="filter")

    # F2: drift is a write of its own, for the same reason retirement is - the
    # 2026-07-27 scar above is exactly this bug (a mutation gated behind someone
    # else's flag never reaching disk).
    # A caption-only refresh is a write in its own right. Same scar as the
    # retirement bug above: a mutation gated behind another flag never lands.
    if meta_refreshed and not drifted and not added:
        existing["knobs"] = existing_knobs
        save_filter_file_atomic(existing)
        _log(f"filter_file: refreshed captions on {len(meta_refreshed)} knob(s) from "
             f"TUNABLE_PARAMS (description/unit/min/max/type). No values changed.",
             prefix="filter")

    if drifted:
        existing["knobs"] = existing_knobs
        save_filter_file_atomic(existing)
        if meta_refreshed:
            _log(f"filter_file: refreshed captions on {len(meta_refreshed)} knob(s) "
                 f"from TUNABLE_PARAMS. No values changed.", prefix="filter")
        for _n, _old, _new, _tuned in drifted:
            _log(f"filter_file: CODE_DEFAULT DRIFT on {_n} — file says {_old}, code says "
                 f"{_new}, IN EFFECT: {existing_knobs[_n].get('value')}"
                 + ("  (hand-tuned, leave it alone unless you mean to change it)"
                    if _tuned else
                    "  (never hand-tuned — this is a stale default nobody chose)"),
                 prefix="filter")
        _log(f"filter_file: {len(drifted)} knob(s) drifted from code defaults. The LOOPS "
             f"READ THIS FILE, so the new consts are NOT live. Promote deliberately.",
             prefix="filter")
        _write_filter_schema_stale_packet(drifted, existing_knobs)

    if added:
        existing["knobs"] = existing_knobs
        existing["_meta"]["last_modified_by"] = "bootstrap_knob_sync"
        save_filter_file_atomic(existing)
        _log(
            f"filter_file: synced {len(added)} new knob(s) into existing file: "
            f"{', '.join(added[:5])}{'...' if len(added) > 5 else ''}",
            prefix="filter",
        )
    else:
        _log(
            f"filter_file: already current ({len(existing_knobs)} knobs), no sync needed",
            prefix="filter",
        )


def is_meeting_already_applied(proposed_changes: dict) -> tuple[bool, dict]:
    """v13.0 meeting watcher reconciliation. Given a dict of proposed changes
    (knob_name -> new_value), check whether each proposed value already matches
    the current state in the filter file.
    
    Returns (all_already_applied, diff_dict)."""
    data = load_filter_file()
    if data is None:
        return False, {}
    knobs = data.get("knobs") or {}
    diff: dict = {}
    all_match = True
    for knob_name, proposed_value in proposed_changes.items():
        current = (knobs.get(knob_name) or {}).get("value")
        match = current == proposed_value
        diff[knob_name] = {
            "current": current,
            "proposed": proposed_value,
            "match": match,
        }
        if not match:
            all_match = False
    return all_match, diff


# v13.0: file watcher loop — polls mtime on the filter file, reloads
# _ACTIVE_OVERRIDES when the agent edits the file directly.
_FILTER_FILE_LAST_MTIME: dict = {"mtime": 0.0}


async def filter_file_watcher_loop() -> None:
    """v13.0: watches MEME_SNIPER_FILTER_FILE for direct-edit changes.
    
    On mtime change, reloads _ACTIVE_OVERRIDES from the new file content.
    
    Race vs apply_filter_change: that function's caller (the tune_response
    path, where the agent answers a tune invitation) ALSO calls
    reload_active_overrides_from_filter_file() right after writing, so this
    watcher firing a moment later and re-reading the same file is a harmless
    no-op.

    CORRECTED 2026-08-16: this docstring used to say "when the meeting watcher
    writes the file via apply_filter_change". The meeting watcher does not
    write the file and never calls that function - it mutates _ACTIVE_OVERRIDES
    only. That is why a meeting change vanishes on restart while a tune
    response survives, and why this watcher never sees a meeting change at
    all: there is no mtime to notice."""
    _log("filter_file_watcher: starting", prefix="filter")
    try:
        if MEME_SNIPER_FILTER_FILE.exists():
            _FILTER_FILE_LAST_MTIME["mtime"] = MEME_SNIPER_FILTER_FILE.stat().st_mtime
    except Exception:
        pass
    
    while True:
        try:
            if MEME_SNIPER_FILTER_FILE.exists():
                _seeded = _seed_wizard_knobs_from_env()
                if _seeded:
                    _log(f"filter_file_watcher: seeded from bots/.env: {_seeded}", prefix="filter")
                mtime = MEME_SNIPER_FILTER_FILE.stat().st_mtime
                if mtime > _FILTER_FILE_LAST_MTIME["mtime"]:
                    _FILTER_FILE_LAST_MTIME["mtime"] = mtime
                    try:
                        n = reload_active_overrides_from_filter_file()
                        _agent_memo("filter_edit", True, f"filter file change applied: {n} override(s) reloaded",
                                    request_id=f"mtime_{int(mtime)}")
                    except Exception as _fe:
                        _agent_memo("filter_edit", False, "filter file change NOT applied",
                                    request_id=f"mtime_{int(mtime)}", reason=f"{type(_fe).__name__}: {str(_fe)[:200]}")
                        raise
                    _log(
                        f"filter_file_watcher: detected mtime change, reloaded "
                        f"{n} override(s) into runtime state",
                        prefix="filter",
                    )
                    await write_heartbeat("filter_file_watcher", "reloaded", {
                        "knobs_loaded": n,
                        "mtime": mtime,
                    })
                else:
                    await write_heartbeat("filter_file_watcher", "idle", {"last_mtime": mtime})
            else:
                ensure_filter_file_initialized()
                reload_active_overrides_from_filter_file()
        except Exception as e:
            _log(f"filter_file_watcher cycle err: {e}", prefix="filter")
            await write_heartbeat("filter_file_watcher", "error", {"last_error": str(e)[:200]})
        
        await asyncio.sleep(FILTER_FILE_WATCH_TICK_S)


def _validate_expires_at(expires_at_iso) -> tuple:
    """Sprint 32+: sanity-check the LLM's expires_at output before applying.
    Returns (is_valid, parsed_dt_or_None, error_message).
    Rules: must be parseable ISO datetime, must be >30s in the future."""
    if not expires_at_iso:
        return (True, None, "")  # null = permanent override, valid
    if not isinstance(expires_at_iso, str):
        return (False, None, f"expires_at must be ISO string or null, got {type(expires_at_iso).__name__}")
    try:
        dt = datetime.fromisoformat(expires_at_iso)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=EST)
        now = datetime.now(EST)
        if dt <= now + timedelta(seconds=30):
            return (False, None, f"expires_at {expires_at_iso} is in the past or too soon (must be >30s in the future)")
        return (True, dt, "")
    except (ValueError, TypeError) as e:
        return (False, None, f"expires_at not parseable as ISO datetime: {e}")


