def _now_iso() -> str:
    return datetime.now(EST).isoformat(timespec="seconds")


def _iso_from_ts(ts) -> Optional[str]:
    """Unix seconds -> ET ISO string. None-safe (returns None on missing/bad input)."""
    try:
        if not ts:
            return None
        return datetime.fromtimestamp(float(ts), EST).isoformat(timespec="seconds")
    except Exception:
        return None


def _now_ts() -> float:
    return time.time()


def _short_mint(mint: str, n: int = 8) -> str:
    if not mint or len(mint) < n + 4:
        return mint or "?"
    return f"{mint[:n]}...{mint[-4:]}"




# ── OWNER/AGENT RULING 2026-07-27: TWO LANES, NOT FIVE PRIORITIES ────────────
# "high/critical makes everything feel like an interrupt. half of it is just
# 'look at this.' not every high packet is a war room." Decorative priority
# trained him to treat the inbox as a fire alarm, so real fires stopped
# reading as fires.
#
#   interrupt = open position risk that needs a DECISION, a param_request
#               deadline, or a real signal failure on LIVE MONEY.
#   queue     = everything else. candidates, charts, research, acks, digests,
#               confirmations, autopsies. Sequential. No alarm.
#
# `lane` is authoritative. `priority` is derived from it for back-compat with
# existing readers so the two can never disagree — and because it's derived,
# "high" now means exactly one thing instead of being sprinkled for emphasis.
_INTERRUPT_TYPES = {
    "meme_exit_signal",   # open position, live risk, needs a call
    "param_request",      # has a deadline
    "pvp_alert",          # someone is in the trade against him right now
    "signal_rejected",    # his call did NOT execute — live money didn't move
    "signal_failure",     # execution failed on live money
}


def _lane_for(packet_type: str, escalate: bool = False) -> str:
    """interrupt | queue. `escalate` is for the narrow real exceptions —
    e.g. a trade_confirmation where the fill did NOT match intent."""
    if escalate:
        return "interrupt"
    return "interrupt" if packet_type in _INTERRUPT_TYPES else "queue"


def _lane_fields(packet_type: str, escalate: bool = False) -> dict:
    """Spread into a packet: `**_lane_fields("chart_packet")`."""
    lane = _lane_for(packet_type, escalate)
    return {"lane": lane, "priority": "high" if lane == "interrupt" else "normal"}


def _decision_inputs(options, note=None):
    """OWNER/AGENT RULING 2026-07-27 — packets publish INPUTS, never a menu.

    The old `suggested_action_options` read like a multiple-choice test, and
    The agent said so plainly: "i pick from the list instead of writing the real
    call. same disease as EXIT_FULL." A named list of verbs collapses a blank
    page into a row selection.

    So every option set now ships wrapped: binding=False, an explicit note that
    a blank page is valid, and `when_this_fits` (a CONDITION) in place of
    `reasoning` (which read as advocacy). The bot describes shapes. The agent
    writes the action.
    """
    opts = []
    for o in (options or []):
        if not isinstance(o, dict):
            continue
        o = dict(o)
        if "reasoning" in o and "when_this_fits" not in o:
            o["when_this_fits"] = o.pop("reasoning")
        opts.append(o)
    return {
        "binding": False,
        "note": (note or
                 "INPUTS ONLY — not a menu, not a recommendation. These describe when "
                 "each shape tends to fit. You write the real action, and writing none "
                 "is valid. The bot has no opinion on which."),
        "options": opts,
    }
def _sha8(s: str) -> str:
    return hashlib.sha256(s.encode()).hexdigest()[:8]


_ATOMIC_WRITE_SEQ = 0


def _save_json_atomic(path: Path, data: Any, _retries: int = 5) -> None:
    """Atomic write with tmp+rename, UTF-8, no BOM.

    ── Sprint 54 BUGFIX: THE SHARED-TEMPFILE RACE ──────────────────────────────
    This used a SINGLE, PREDICTABLE temp name:

        tmp = path.with_suffix(path.suffix + ".tmp")    # -> heartbeat.json.tmp

    Every writer of a given file therefore used the SAME tmp path. With ~20 supervised
    loops all heartbeating into meme_sniper_heartbeat.json concurrently, this happens:

        loop A: open heartbeat.json.tmp, write
        loop B: open heartbeat.json.tmp  <-- SAME FILE, clobbers A's handle
        loop A: os.replace(tmp, path)    <-- B still holds it open
        WINDOWS: WinError 32 — "the process cannot access the file because it is being
                 used by another process"
        WINDOWS: Errno 13 — permission denied (tmp locked at open time)

    On Linux this mostly works by luck (renaming over an open file is legal there), so
    the bug is invisible until it runs on Windows — and then it fires under exactly the
    conditions you least want: high concurrency, right after boot, when every loop is
    starting at once.

    THE FIX: a UNIQUE temp file per write (pid + monotonic counter). Writers can no
    longer collide because they are never touching the same tmp path. Plus a short retry
    on os.replace, because Windows can still transiently lock the DESTINATION if a reader
    has it open — that one is unavoidable on Windows and is what retries are for.
    """
    path.parent.mkdir(parents=True, exist_ok=True)
    global _ATOMIC_WRITE_SEQ
    _ATOMIC_WRITE_SEQ += 1
    tmp = path.with_suffix(f"{path.suffix}.{os.getpid()}.{_ATOMIC_WRITE_SEQ}.tmp")
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False, default=str)
        last_err = None
        for attempt in range(_retries):
            try:
                os.replace(tmp, path)
                return
            except PermissionError as e:
                # Windows: a READER may hold the destination open. Transient — back off.
                last_err = e
                time.sleep(0.05 * (attempt + 1))
        raise last_err
    finally:
        # never leave a stray tmp behind if we failed
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass


def _append_jsonl(path: Path, record: Any) -> None:
    """Append one JSON record to a .jsonl-style log file."""
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "a", encoding="utf-8") as f:
        f.write(json.dumps(record, ensure_ascii=False, default=str) + "\n")


def _log(msg: str, *, prefix: str = "sniper") -> None:
    """Console log with timestamp prefix."""
    line = f"[{prefix}] [{_now_iso()}] {msg}"
    try:
        print(line, flush=True)
    except UnicodeEncodeError:
        # Windows exec consoles are often cp1252. A boot checkmark must not kill the process.
        print(line.encode("ascii", "backslashreplace").decode("ascii"), flush=True)


