_telegram_client: Optional[httpx.AsyncClient] = None

_ALERTS_MOD = None


def _alerts_mod():
    """bots/sub-bots/alerts.py (2026-10-15 pluggable alerts). None = fall back to direct Telegram."""
    global _ALERTS_MOD
    if _ALERTS_MOD is None:
        try:
            import importlib.util as _ilu
            _p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "sub-bots/alerts.py")
            _spec = _ilu.spec_from_file_location("ms_alerts", _p)
            _m = _ilu.module_from_spec(_spec); _spec.loader.exec_module(_m)
            _ALERTS_MOD = _m
        except Exception:
            _ALERTS_MOD = False
    return _ALERTS_MOD or None



async def _get_telegram_client() -> Optional[httpx.AsyncClient]:
    global _telegram_client
    if not TELEGRAM_TOKEN or not TELEGRAM_CHAT_ID:
        return None
    if _telegram_client is None or _telegram_client.is_closed:
        _telegram_client = httpx.AsyncClient(timeout=10)
    return _telegram_client


_ALERT_WARNED: set = set()
_ALERT_WARN_ONCE = True


async def send_telegram(msg: str, *, silent: bool = False) -> None:
    """Fire-and-forget alert. Name kept for the ~all call sites: since 2026-10-15 it goes
    through the pluggable dispatcher (ALERT_CHANNELS: telegram/discord/email/ntfy/off).
    Telegram payload is unchanged. Falls back to the direct Telegram call below."""
    _am = _alerts_mod()
    if _am is not None:
        if PAPER_MODE and not str(msg).startswith("[PAPER]"):
            msg = "[PAPER] " + str(msg)
        res = await _am.send(msg, source="engine", silent=silent)
        _prev = _re.sub(r"<[^>]+>", "", str(msg)).replace("\n", " ")[:80]
        for _ch, _st in (res or {}).items():
            if _st == "sent":
                _log(f"{_ch} sent ok: {_prev}", prefix="tg" if _ch == "telegram" else "alert")
            elif str(_st).startswith("failed: missing") and _ALERT_WARN_ONCE \
                    and str(os.environ.get("ALERT_MISSING_WARN_ONCE", "1")).strip().lower() not in ("0", "false", "off", "no"):
                if _ch not in _ALERT_WARNED:   # missing channel key: warn once per run, not on every alert
                    _ALERT_WARNED.add(_ch)
                    _log(f"alert {_ch} {_st} (set it in bots/.env; this warning shows once per run)", prefix="alert")
            else:
                _log(f"alert {_ch} {_st}", prefix="alert")
        return
    client = await _get_telegram_client()
    if client is None:
        return
    
    url = f"https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendMessage"
    if PAPER_MODE and not str(msg).startswith("[PAPER]"):
        msg = "[PAPER] " + str(msg)
    payload = {
        "chat_id": TELEGRAM_CHAT_ID,
        "text": msg,
        "disable_web_page_preview": True,
        "disable_notification": silent,
    }
    
    try:
        r = await client.post(url, json=payload)
        if r.status_code != 200:
            _log(f"telegram returned {r.status_code}: {r.text[:200]}")
        else:
            _prev = _re.sub(r"<[^>]+>", "", str(msg)).replace("\n", " ")[:80]
            _log(f"telegram sent ok: {_prev}", prefix="tg")
    except Exception as e:
        _log(f"telegram send error: {e}")


def send_telegram_sync(msg: str) -> None:
    """Sync wrapper for places that can't await (e.g., signal handlers)."""
    try:
        loop = asyncio.get_event_loop()
        if loop.is_running():
            asyncio.create_task(send_telegram(msg))
        else:
            asyncio.run(send_telegram(msg))
    except Exception:
        pass


