def is_active_hours(now: Optional[datetime] = None) -> bool:
    """
    The owner's active hours per Sprint 28 schedule.
    
    Mon-Fri: 5am-6pm ET + 9pm-1am ET (with 6pm-9pm dinner gap, 1am-5am sleep)
    Sat-Sun: 11am-9pm ET
    """
    now = now or datetime.now(EST)
    weekday = now.weekday()  # 0=Mon, 6=Sun
    t = now.time()
    
    if weekday < 5:  # Mon-Fri
        # Sleep zone: 1am-5am
        if dtime(1, 0) <= t < dtime(5, 0):
            return False
        # Morning block: 5am-6pm
        if dtime(5, 0) <= t < dtime(18, 0):
            return True
        # Evening block: 9pm-1am (wrap around midnight)
        if t >= dtime(21, 0) or t < dtime(1, 0):
            return True
        # Dinner gap: 6pm-9pm
        return False
    else:  # Sat-Sun
        return dtime(11, 0) <= t < dtime(21, 0)


def next_scan_interval_seconds(now: Optional[datetime] = None) -> int:
    """Returns the scanner sleep interval.

    Base cadence = SCAN_TICK_SECONDS (agent-owned via meeting). Sprint 45: the
    bot invents no clock-based off-hours schedule — if the tape is dead, AGENT
    raises SCAN_TICK_SECONDS through his meeting channel.

    2026-07-31 (The agent's patch): if reduced-throughput mode is active, multiply
    the base by REDUCED_THROUGHPUT_MULT (default 3). reduced_mode is set by
    evaluate_throughput_mode / a sticky dead-market hold — and THIS function is
    the only place that consumes it. Until this fix it was a flag with no effect:
    the trip set reduced_mode=true and asked a question, but the scanner kept
    sleeping at the base cadence, so a junk week stuffed the inbox at 15m forever.
    The base stays the agent's; the multiplier is the bot enforcing its own trip.
    """
    base = int(get_override_sync("SCAN_TICK_SECONDS", SCAN_TICK_SECONDS_DEFAULT) or SCAN_TICK_SECONDS_DEFAULT)
    base = max(60, base)   # hard floor matches the TUNABLE min
    try:
        state = load_throughput_state()
        if state.get("reduced_mode"):
            mult = float(get_override_sync("REDUCED_THROUGHPUT_MULT", REDUCED_THROUGHPUT_MULT_DEFAULT)
                         or REDUCED_THROUGHPUT_MULT_DEFAULT)
            mult = max(1.0, min(mult, 12.0))
            return int(base * mult)
    except Exception as e:
        _log(f"throughput sleep read err (non-fatal): {e}", prefix="throughput")
    return base


