#                              SUPERVISOR
# ═══════════════════════════════════════════════════════════════════════════

class SupervisedTask:
    """
    Wraps a coroutine factory so it auto-restarts on crash.
    Catches all exceptions, logs, alerts via Telegram, sleeps 30s, restarts.
    
    Usage:
        await SupervisedTask("scanner", scanner_loop).run()
    
    Or as a top-level gather:
        await asyncio.gather(
            SupervisedTask("scanner", scanner_loop).run(),
            SupervisedTask("monitor", position_monitor_loop).run(),
        )
    """
    
    def __init__(
        self,
        name: str,
        coroutine_factory: Callable[[], Awaitable[None]],
        *,
        restart_backoff_s: int = 30,
        max_restart_burst: int = 5,
        burst_window_s: int = 300,
    ):
        self.name = name
        self.coroutine_factory = coroutine_factory
        self.restart_backoff_s = restart_backoff_s
        self.max_restart_burst = max_restart_burst
        self.burst_window_s = burst_window_s
        
        self._restart_history: list[float] = []
        self._restart_count: int = 0
    
    def _record_restart(self) -> bool:
        """
        Track restarts. Returns True if we're in a healthy restart pattern,
        False if we're flapping (5+ restarts in 5min) , caller should give up.
        """
        now = _now_ts()
        self._restart_history.append(now)
        self._restart_count += 1
        
        # Drop old restarts outside the burst window
        cutoff = now - self.burst_window_s
        self._restart_history = [t for t in self._restart_history if t > cutoff]
        
        return len(self._restart_history) <= self.max_restart_burst
    
    async def run(self) -> None:
        if LEAGUE_MODE and self.name in _league.SKIP_TASKS:
            _log(f"supervisor: {self.name} off in LEAGUE_MODE (mainnet-only or moves money)", prefix="league")
            return
        _log(f"supervisor: starting {self.name}", prefix="super")
        try:
            await write_heartbeat(self.name, "starting")
        except Exception:
            pass
        
        while True:
            _stop = asyncio.Event()
            async def _pulse():
                while not _stop.is_set():
                    try:
                        await write_heartbeat(self.name, "polling")
                    except Exception:
                        pass
                    try:
                        await asyncio.wait_for(_stop.wait(), timeout=60)
                    except asyncio.TimeoutError:
                        continue
            _pulse_task = asyncio.create_task(_pulse())
            try:
                await self.coroutine_factory()
                # Coroutine returned cleanly , that's unexpected for a daemon loop, restart it
                _log(f"supervisor: {self.name} returned cleanly, restarting", prefix="super")
            except asyncio.CancelledError:
                _log(f"supervisor: {self.name} cancelled, exiting", prefix="super")
                try:
                    await write_heartbeat(self.name, "cancelled")
                except Exception:
                    pass
                raise
            except Exception as e:
                tb = traceback.format_exc()
                _log(f"supervisor: {self.name} CRASHED: {e}", prefix="super")
                _log(f"supervisor: traceback: {tb[:500]}", prefix="super")
                try:
                    await write_heartbeat(self.name, "error", extra={"error": str(e)[:150]})
                except Exception:
                    pass
                
                # Telegram alert
                try:
                    await send_telegram(
                        f"⚠️ {self.name} crashed (restart #{self._restart_count + 1}): {str(e)[:150]}"
                    )
                except Exception:
                    pass
                
                # Track restart, check for flapping
                healthy_pattern = self._record_restart()
                if not healthy_pattern:
                    _log(
                        f"supervisor: {self.name} flapping , {len(self._restart_history)} crashes "
                        f"in {self.burst_window_s}s; backing off LONGER",
                        prefix="super",
                    )
                    try:
                        await send_telegram(
                            f"🚨 {self.name} flapping! {len(self._restart_history)} crashes in "
                            f"{self.burst_window_s//60}min. Investigate!"
                        )
                    except Exception:
                        pass
                    # Long backoff to prevent thrashing
                    await asyncio.sleep(self.restart_backoff_s * 4)
                else:
                    await asyncio.sleep(self.restart_backoff_s)
            finally:
                _stop.set()
                _pulse_task.cancel()
                try:
                    await _pulse_task
                except (asyncio.CancelledError, Exception):
                    pass


# ═══════════════════════════════════════════════════════════════════════════
#                              HEARTBEAT
# ═══════════════════════════════════════════════════════════════════════════

async def write_heartbeat(component: str, status: str, extra: Optional[dict] = None) -> None:
    """Write a heartbeat record per component into the unified heartbeat file.
    Merge window 900s (ops FIX 2). rows older than 900s flip to stale."""
    try:
        existing = load_json_with_staleness(SNIPER_HEARTBEAT_FILE, max_age_seconds=900, default={"components": {}}, alert_on_stale=False)
        if not isinstance(existing, dict):
            existing = {"components": {}}
        existing.pop("_meta", None)
        existing.setdefault("components", {})
        now_dt = datetime.now(EST)
        for _cname, _crow in list(existing["components"].items()):
            if not isinstance(_crow, dict):
                continue
            _lu = _crow.get("last_update")
            if not _lu:
                _crow["status"] = "stale"
                continue
            try:
                _age = (now_dt - datetime.fromisoformat(str(_lu))).total_seconds()
            except Exception:
                continue
            if _age > 900 and _cname != component:
                _crow["status"] = "stale"
        
        existing["components"][component] = {
            "status": status,
            "last_update": _now_iso(),
            **(extra or {}),
        }
        existing["last_overall_update"] = _now_iso()
        
        _save_json_atomic(SNIPER_HEARTBEAT_FILE, existing)
    except Exception as e:
        _log(f"heartbeat write error for {component}: {e}")


