# Shared httpx clients for connection pooling
_dex_client: Optional[httpx.AsyncClient] = None
_rpc_client: Optional[httpx.AsyncClient] = None


async def _get_dex_client() -> httpx.AsyncClient:
    global _dex_client
    if _dex_client is None or _dex_client.is_closed:
        _dex_client = httpx.AsyncClient(
            timeout=15,
            headers={"User-Agent": "AgentEmpire/1.0 (autonomous-trading-system)"},
        )
    return _dex_client


async def _get_rpc_client() -> httpx.AsyncClient:
    global _rpc_client
    if _rpc_client is None or _rpc_client.is_closed:
        _rpc_client = httpx.AsyncClient(timeout=20)
    return _rpc_client


async def fetch_bonded_pairs() -> list[dict]:
    """
    Fetch latest bonded/graduated tokens from DexScreener token-profiles endpoint.
    
    v13.0: Filters tightened. Returns ONLY Solana profiles whose underlying token
    pair is on one of the BONDED_DEXIDS_ALLOWED DEXes (raydium, meteora, pumpswap,
    orca). This excludes tokens still on launchpad bonding curves (pre-graduation),
    enforcing the "bonded means graduated to a real DEX" hardcoded floor.
    
    Note: the DexScreener token-profiles endpoint doesn't always include the
    dexId on the profile itself — for some entries we get a chainId-only profile.
    For those we fall through to the caller's downstream enrichment (fetch_token_data),
    which DOES return dexId, and the dexId check is enforced there as a backstop.
    This function applies the filter when the data is available; the downstream
    check guarantees no bonding-curve token ever passes the full pipeline.
    """
    try:
        client = await _get_dex_client()
        r = await client.get(DEXSCREENER_BONDED_API)
        if r.status_code != 200:
            _log(f"bonded fetch returned {r.status_code}")
            return []
        data = r.json()
        if not isinstance(data, list):
            return []
        # Filter to Solana
        solana_profiles = [p for p in data if p.get("chainId") == SOLANA_CHAIN_ID]
        
        # v13.0: where dexId is available on the profile, enforce whitelist.
        # token-profiles endpoint generally has 'dexId' or nested 'pairData' with
        # dexId — when present, gate-1 filter applies. When absent, the profile
        # passes through here and downstream fetch_token_data confirms dexId.
        filtered = []
        n_dropped_dexid = 0
        for p in solana_profiles:
            dex_id = (p.get("dexId") or "").lower()
            if not dex_id:
                # Try nested locations DexScreener sometimes uses
                pair_data = p.get("pairData") or {}
                dex_id = (pair_data.get("dexId") or "").lower()
            if dex_id and dex_id not in BONDED_DEXIDS_ALLOWED:
                n_dropped_dexid += 1
                continue
            filtered.append(p)
        if n_dropped_dexid:
            _log(
                f"bonded fetch: dropped {n_dropped_dexid} non-allowed-dexid profiles "
                f"(allowed: {sorted(BONDED_DEXIDS_ALLOWED)})",
                prefix="scanner",
            )
        return filtered
    except Exception as e:
        _log(f"fetch_bonded_pairs error: {e}")
        return []


def is_bonded_dexid(token_data: dict) -> bool:
    """v13.0 hardcoded floor: a fully-enriched token dict must have a dexId
    in the allowed whitelist to be considered bonded/graduated. Returns False
    if the dexId is missing or not in the whitelist.
    
    Used downstream of fetch_bonded_pairs as a backstop — fetch_token_data
    returns dexId reliably, so this is the final gate.
    """
    if not isinstance(token_data, dict):
        return False
    # Standard DexScreener pair-level location
    dex_id = (token_data.get("dexId") or "").lower()
    if not dex_id:
        # Some callers pass the nested {pair: {...}} shape
        pair = token_data.get("pair") or {}
        dex_id = (pair.get("dexId") or "").lower()
    return bool(dex_id) and dex_id in BONDED_DEXIDS_ALLOWED


def _base_side_pairs(pairs: list, mint: str) -> list:
    """v1.0.6: keep only DexScreener pairs whose BASE token is `mint`. Pairs without
    a baseToken.address are kept (older/mocked payloads) so nothing silently empties."""
    out = []
    for p in pairs or []:
        addr = ((p or {}).get("baseToken") or {}).get("address")
        if addr is None or addr == mint:
            out.append(p)
    return out


async def fetch_token_data(mint: str) -> Optional[dict]:
    """
    Fetch full DEX data for a specific token. Returns the highest-liquidity pair.
    """
    if LEAGUE_MODE:                      # devnet league tokens: price from the league executor only
        return await _league.price(LEAGUE_CFG, mint)
    try:
        client = await _get_dex_client()
        r = await _dex_get(client, f"{DEXSCREENER_TOKEN_API}/{mint}")
        if r.status_code != 200:
            return None
        data = r.json() or {}
        pairs = data.get("pairs", []) or []
        if not pairs:
            return None
        # v1.0.6: DexScreener /tokens/<mint> also returns pairs where this mint is the
        # QUOTE side (OTHER/<mint>). Their priceUsd/symbol belong to the other token -
        # that is how a $0.09 SPCX bag got marked as $1,711 'ORE'. Only base-side pairs.
        pairs = _base_side_pairs(pairs, mint)
        if not pairs:
            return None
        # Sort by liquidity, return primary pair (highest liq)
        pairs.sort(key=lambda p: (p.get("liquidity") or {}).get("usd", 0) or 0, reverse=True)
        return pairs[0]
    except Exception as e:
        _log(f"fetch_token_data error for {_short_mint(mint)}: {_err_detail(e)}")
        return None


# v13.1 Drop 2: rugcheck full-report fetcher for lpLockedPct + supplementary fields
# Cached per-mint for 6h. The existing rugcheck call in smart_rug_check uses the
# /v1/tokens/{mint}/report/summary endpoint, which doesn't include lpLockedPct.
# This separate function hits /v1/tokens/{mint}/report for the richer data.
_RUGCHECK_LP_CACHE: dict = {}
_RUGCHECK_LP_CACHE_TTL_S = 6 * 60 * 60  # 6h


async def fetch_rugcheck_lp_lock(mint: str) -> dict:
    """v13.1 Drop 2: Fetch lpLockedPct + supplementary rugcheck fields.
    
    Returns dict with:
      - lp_locked_pct:  float (0-100) or None if data unavailable
      - lp_burned:      bool (LP is burned-to-zero, equivalent to 100% locked)
      - token_program:  str (spl-token vs token-2022)
      - fetched_at:     iso timestamp of fetch
      - _source:        "rugcheck_full_report" | "cached" | "error"
    
    Cached 6h per mint. Failures cache an "error" marker for 5min to avoid
    hammering rugcheck on persistent failures.
    """
    cache = _RUGCHECK_LP_CACHE.get(mint)
    if cache and (_now_ts() - cache.get("fetched_at_ts", 0)) < _RUGCHECK_LP_CACHE_TTL_S:
        # Short error TTL (5min) for failures to allow retry
        _age = _now_ts() - cache.get("fetched_at_ts", 0)
        if cache.get("_source") == "error" and _age < 300:
            return cache
        if cache.get("_source") == "pending_index" and _age < 60:
            return cache
        elif cache.get("_source") not in ("error", "pending_index"):
            return {**cache, "_source": "cached"}
    
    result = {
        "lp_locked_pct": None,
        "lp_burned": False,
        "token_program": None,
        "fetched_at": _now_iso(),
        "fetched_at_ts": _now_ts(),
        "_source": "error",
    }
    
    try:
        client = await _get_dex_client()
        r = await client.get(f"https://api.rugcheck.xyz/v1/tokens/{mint}/report")
        if r.status_code == 200:
            data = r.json() or {}
            
            # lpLockedPct can appear in multiple places depending on response shape
            lp_locked = data.get("lpLockedPct")
            if lp_locked is None:
                # Try nested locations
                markets = data.get("markets") or []
                if markets and isinstance(markets, list):
                    primary = markets[0] if markets else {}
                    lp = primary.get("lp") or {}
                    lp_locked = lp.get("lpLockedPct")
            
            if lp_locked is not None:
                try:
                    result["lp_locked_pct"] = float(lp_locked)
                except (TypeError, ValueError):
                    pass
            
            # LP burned = 100% locked equivalent
            result["lp_burned"] = bool(data.get("lpBurned") or data.get("lp_burned") or False)
            if result["lp_burned"] and result["lp_locked_pct"] is None:
                result["lp_locked_pct"] = 100.0
            
            # Token program (spl-token vs token-2022)
            result["token_program"] = data.get("tokenProgram") or data.get("token_program")
            
            result["_source"] = "rugcheck_full_report"
        elif r.status_code in (400, 404):
            result["_source"] = "pending_index"   # fresh mint not indexed yet; retried after 60s
        else:
            _log(f"rugcheck_lp: {_short_mint(mint)} returned {r.status_code}", prefix="rugcheck")
    except Exception as e:
        _log(f"rugcheck_lp: {_short_mint(mint)} err: {type(e).__name__} {e}", prefix="rugcheck")
    
    _RUGCHECK_LP_CACHE[mint] = result
    return result


async def fetch_dex_search(query: str) -> list[dict]:
    """Search DexScreener by name/symbol/CA. Used by PvP scanner."""
    try:
        client = await _get_dex_client()
        r = await _dex_get(client, DEXSCREENER_SEARCH_API, params={"q": query})
        if r.status_code != 200:
            return []
        data = r.json() or {}
        return data.get("pairs", []) or []
    except Exception as e:
        _log(f"fetch_dex_search error for '{query}': {_err_detail(e)}")
        return []


async def fetch_dex_boosts() -> list[dict]:
    """Fetch top boosted tokens (used for boost_count enrichment)."""
    try:
        client = await _get_dex_client()
        r = await client.get(DEXSCREENER_BOOSTS_API)
        if r.status_code != 200:
            return []
        data = r.json() or []
        return [p for p in data if p.get("chainId") == SOLANA_CHAIN_ID]
    except Exception as e:
        _log(f"fetch_dex_boosts error: {e}")
        return []


# ── AGENT'S PATCH #3 (2026-07-25, Nenem stuck open behind a dead submit) ────
# His diagnosis, verified line by line: this wrapper returned ONLY
# data.get("result") and threw away the http body, the json-rpc error object,
# and the status code — so every submit death collapsed to the useless
# "rpc_send_failed: no signature returned". You cannot tell a preflight
# rejection from a rate limit from a node drop. The error now survives: logged
# in full and stashed for the caller to surface. An exit path that can't say
# WHY it failed can't be fixed while money is live.
_LAST_RPC_ERROR = {"method": None, "detail": None, "at": None}

def last_rpc_error_str() -> str:
    e = _LAST_RPC_ERROR
    return f"{e.get('method')}: {e.get('detail')}" if e.get("detail") else ""

# ══════════════════════════════════════════════════════════════════════════════
# RPC GOVERNOR + 429 METER (2026-07-27)
# ══════════════════════════════════════════════════════════════════════════════
# The owner asked "how often has this been 429 limited?" and the bot could not answer,
# because _LAST_RPC_ERROR only ever kept the MOST RECENT one. Rate limiting has
# been happening for an unknown duration at an unknown rate with no counter —
# the same silent-failure shape as the presweep leak and the carried grades.
# You cannot tune what you do not measure, so the meter comes first.
#
# ROOT CAUSE of the burst: ~25 subsystems start simultaneously and each calls RPC
# independently. There is no shared budget. Helius's own docs name this exactly:
# "Rate limiting can occur due to ... making requests from too many concurrent
# connections." A boot storm of 25 coroutines will trip a 10 RPS plan instantly
# and will dent a 50 RPS plan.
#
# IMPORTANT — RPS IS A PLAN PROPERTY, NOT A CREDIT PROPERTY. Prepaid credits buy
# more CALLS, not faster ones. Free 10/s · Developer 50/s · Business 200/s ·
# Professional 500/s. Buying credits will not stop 429s. Two separate meters.
#
# Batching is also NOT a credit saver: Helius counts each sub-request in a batch
# toward the total. It saves round trips, not quota.
#
# So the fix is pacing, not purchasing:
#   1. SEMAPHORE  — cap concurrent in-flight RPC calls (the "too many concurrent
#                   connections" cause).
#   2. MIN INTERVAL — a global spacer so sustained rate stays under plan RPS.
#                   A semaphore alone bounds concurrency, not rate.
#   3. RETRY-AFTER — honour the header Helius actually sends instead of guessing.
#   4. JITTER     — linear un-jittered backoff makes parallel callers retry in
#                   lockstep, turning one burst into a standing wave.
# Plan is 10 RPC req/s (Free/Agent tier) and 1 sendTransaction/s.
# 0.14s spacing => ~7.1/s sustained, leaving ~30% headroom for the priority lane
# and for the fact that our clock and Helius's are not the same clock.
_RPC_MAX_CONCURRENT = int(_envv("SNIPER_RPC_MAX_CONCURRENT", "3"))
_RPC_MIN_INTERVAL_S = float(_envv("SNIPER_RPC_MIN_INTERVAL_S", "0.14"))
_RPC_SEMAPHORE: Optional[asyncio.Semaphore] = None
_RPC_PACE_LOCK: Optional[asyncio.Lock] = None
_RPC_LAST_CALL_TS = 0.0

# ── PRIORITY LANE (2026-07-27) ───────────────────────────────────────────────
# THE THROTTLE ITSELF IS A RISK. 25 background subsystems share the same 10 req/s
# budget as the exit path. A watchlist recheck across 484 mints or an autopsy
# across 136 can be mid-flight when a position needs to be closed — and a plain
# FIFO throttle would queue the SELL behind the RESEARCH. Being late to an exit
# to save a rate limit is a catastrophically bad trade.
#
# So money calls get their own reserved capacity that background work cannot
# touch, and they skip the pacing spacer entirely. At 10 req/s the spacer is
# 0.14s — trivial for a scanner, potentially the whole ballgame on a dump.
#
# sendTransaction is separately capped at 1/s by the plan, so it gets its own
# 1-wide lane: serialise it here rather than discover the limit mid-exit.
_RPC_CRITICAL_METHODS = {
    "sendTransaction",        # the trade itself
    "getSignatureStatuses",   # did the trade land
    "getLatestBlockhash",     # required to build the trade
    "simulateTransaction",    # pre-flight for the trade
}
_RPC_PRIORITY_SEMAPHORE: Optional[asyncio.Semaphore] = None
_RPC_SEND_LOCK: Optional[asyncio.Lock] = None
_RPC_SEND_LAST_TS = 0.0
_RPC_SEND_MIN_INTERVAL_S = float(_envv("SNIPER_RPC_SEND_MIN_INTERVAL_S", "1.05"))  # plan: 1/s

_RPC_STATS = {
    "calls": 0, "http_429": 0, "jsonrpc_429": 0, "other_err": 0,
    "by_method": {}, "by_method_429": {},
    "first_call_at": None, "last_429_at": None,
    "throttled_wait_s": 0.0,
}


def _rpc_stat(method: str, *, limited: bool = False, jsonrpc: bool = False) -> None:
    st = _RPC_STATS
    st["calls"] += 1
    st["by_method"][method] = st["by_method"].get(method, 0) + 1
    if st["first_call_at"] is None:
        st["first_call_at"] = _now_iso()
    if limited:
        st["jsonrpc_429" if jsonrpc else "http_429"] += 1
        st["by_method_429"][method] = st["by_method_429"].get(method, 0) + 1
        st["last_429_at"] = _now_iso()


def rpc_health() -> dict:
    """Answers 'how often are we being rate limited?' — the question the bot
    previously could not answer about itself."""
    st = _RPC_STATS
    total_429 = st["http_429"] + st["jsonrpc_429"]
    calls = max(st["calls"], 1)
    worst = sorted(st["by_method_429"].items(), key=lambda kv: -kv[1])[:5]
    return {
        "calls": st["calls"],
        "rate_limited": total_429,
        "rate_limited_pct": round(total_429 / calls * 100, 2),
        "http_429": st["http_429"],
        "jsonrpc_429": st["jsonrpc_429"],
        "worst_methods": [{"method": m, "count_429": c,
                           "pct_of_its_calls": round(c / max(st["by_method"].get(m, 1), 1) * 100, 1)}
                          for m, c in worst],
        "total_throttle_wait_s": round(st["throttled_wait_s"], 1),
        "concurrency_cap": _RPC_MAX_CONCURRENT,
        "min_interval_s": _RPC_MIN_INTERVAL_S,
        "since": st["first_call_at"],
        "last_429_at": st["last_429_at"],
        "note": ("RPS is a PLAN limit, not a credit limit — prepaid credits do not raise it. "
                 "If rate_limited_pct stays high with concurrency at 4, the plan tier is the "
                 "constraint, not the pacing."),
    }


def _rpc_is_critical(method: str) -> bool:
    # getBalance rides the reserved lane (2026-10-14): a wallet read that loses
    # to background 429s made every buy-side loop think the wallet was empty.
    return method in _RPC_CRITICAL_METHODS or method == "getBalance"


async def _rpc_gate(method: str = ""):
    """Acquire a slot. Money calls use a RESERVED lane and skip the pacer;
    background calls share the throttled lane."""
    global _RPC_SEMAPHORE, _RPC_PACE_LOCK, _RPC_LAST_CALL_TS
    global _RPC_PRIORITY_SEMAPHORE, _RPC_SEND_LOCK, _RPC_SEND_LAST_TS
    if _RPC_SEMAPHORE is None:
        _RPC_SEMAPHORE = asyncio.Semaphore(_RPC_MAX_CONCURRENT)
        _RPC_PACE_LOCK = asyncio.Lock()
        _RPC_PRIORITY_SEMAPHORE = asyncio.Semaphore(2)   # reserved for money
        _RPC_SEND_LOCK = asyncio.Lock()

    if _rpc_is_critical(method):
        # Reserved capacity. No pacing spacer — an exit does not wait 0.14s
        # behind a scanner. This is deliberate: we would rather eat a 429 and
        # retry than be late to a sell.
        await _RPC_PRIORITY_SEMAPHORE.acquire()
        if method == "sendTransaction":
            # Plan caps this at 1/s. Serialise so we discover the limit here,
            # in a controlled spacer, instead of as a failed exit.
            async with _RPC_SEND_LOCK:
                gap = time.monotonic() - _RPC_SEND_LAST_TS
                if gap < _RPC_SEND_MIN_INTERVAL_S:
                    await asyncio.sleep(_RPC_SEND_MIN_INTERVAL_S - gap)
                _RPC_SEND_LAST_TS = time.monotonic()
        return

    await _RPC_SEMAPHORE.acquire()
    async with _RPC_PACE_LOCK:
        gap = time.monotonic() - _RPC_LAST_CALL_TS
        if gap < _RPC_MIN_INTERVAL_S:
            wait = _RPC_MIN_INTERVAL_S - gap
            _RPC_STATS["throttled_wait_s"] += wait
            await asyncio.sleep(wait)
        _RPC_LAST_CALL_TS = time.monotonic()


def _rpc_release(method: str = ""):
    sem = _RPC_PRIORITY_SEMAPHORE if _rpc_is_critical(method) else _RPC_SEMAPHORE
    if sem is not None:
        try:
            sem.release()
        except ValueError:
            pass


# ── RPC FAILOVER + HEALTH (2026-10-14) ────────────────────────────────────────
_RPC_BENCH: dict = {}            # url -> monotonic time it may be used again
_RPC_HEALTH = {"consec_fail": 0, "unhealthy_since": None, "last_ok_at": None,
               "last_endpoint": None}
_RPC_SIG_CACHE: dict = {}        # key -> (monotonic ts, result)
_RPC_LAST_FAIL_KIND = {"kind": None}   # set by _helius_rpc_one: "limited" | "http" | "transport" | "jsonrpc"


def _sig_cursor_dead() -> bool:
    """True when the last RPC error was -32020 / 'Transaction ... not found'
    (a before/until cursor the node no longer knows)."""
    d = str((_LAST_RPC_ERROR or {}).get("detail") or "")
    return "-32020" in d or ("not found" in d.lower() and "transaction" in d.lower())


async def _dex_get(client, url, **kw):
    """DexScreener GET with one quiet retry (jitter) on transport blips."""
    try:
        return await client.get(url, **kw)
    except (httpx.ConnectTimeout, httpx.ReadTimeout, httpx.RemoteProtocolError, httpx.ConnectError):
        await asyncio.sleep(0.4 + (time.monotonic() * 1000 % 800) / 1000.0)
        return await client.get(url, **kw)


def _err_detail(e: BaseException) -> str:
    """livefix: never log a blank error. Type name + repr + HTTP status if any."""
    st = None
    try:
        st = getattr(getattr(e, "response", None), "status_code", None)
    except Exception:
        pass
    return _redact(f"{type(e).__name__}{f' HTTP {st}' if st else ''}: {e!r}")[:300]


def _redact(text: str) -> str:
    """Strip key material from anything we log (URLs carry api-key=...)."""
    try:
        import re
        return re.sub(r"(api[-_]?key=)[^&\s'\"]+", r"\1***", str(text), flags=re.I)
    except Exception:
        return "***"


def _rpc_label(url: str) -> str:
    if url == RPC_URL:
        return "primary"
    if RPC_FREE_URL and url == RPC_FREE_URL:
        return "free"
    if RPC_URL_FALLBACK and url == RPC_URL_FALLBACK:
        return "fallback"
    if RPC_PUBLIC_FALLBACK and url == RPC_PUBLIC_FALLBACK:
        return "public"
    return "override"


def _rpc_endpoints() -> list:
    out = []
    for u in (RPC_URL, RPC_URL_FALLBACK, RPC_PUBLIC_FALLBACK):
        if u and u not in out:
            out.append(u)
    return out


def _is_helius_url(u: str) -> bool:
    return bool(u) and "helius" in u.lower()


def _rpc_endpoints_for(method: str, free_only: bool = False) -> list:
    """v14 routing: trades + wallet reads Helius-first, everything else free-first.
    The other side is always the fallback. free_only / a tripped credit cap drop
    Helius for background reads (never for trade or wallet calls)."""
    # 2026-10-14 livefix: order is free -> paid Helius -> public (RPC_URL_FALLBACK,
    # then RPC_PUBLIC_FALLBACK). Money calls: Helius -> free -> public.
    paid = [u for u in (RPC_URL,) if u]
    free = [u for u in (RPC_FREE_URL,) if u]
    public = [u for u in (RPC_URL_FALLBACK, RPC_PUBLIC_FALLBACK) if u]
    if method in RPC_INDEXED_METHODS:
        # publicnode answers these with 403 "Indexed requests require a personal token"
        public = [u for u in public if "publicnode" not in u.lower()]
    money = method in RPC_PAID_METHODS or _rpc_is_critical(method)
    if money or not RPC_READS_FREE_FIRST:
        order = paid + free + public
    else:
        order = free + paid + public
    if not money and (free_only or helius_budget_restricted()):
        order = [u for u in order if not _is_helius_url(u)]
    out = []
    for u in order:
        if u not in out:
            out.append(u)
    return out


_HM_LOCK = threading.Lock()
_HM = {"day": None, "total": 0.0, "by_source": {}, "by_method": {}, "calls": 0, "last_flush": 0.0}
HELIUS_METER_FILE = _BOT_LOGS / "helius_meter.json"


def _hm_day() -> str:
    return datetime.now().strftime("%Y-%m-%d")


def _hm_flush(force: bool = False) -> None:
    now = time.monotonic()
    if not force and now - _HM["last_flush"] < 60:
        return
    _HM["last_flush"] = now
    try:
        hist = {}
        try:
            with open(HELIUS_METER_FILE, encoding="utf-8") as f:
                hist = json.load(f) or {}
        except Exception:
            hist = {}
        days = hist.get("days") or {}
        days[_HM["day"]] = {
            "total_credits_est": round(_HM["total"], 1),
            "calls": _HM["calls"],
            "by_source": {k: round(v, 1) for k, v in sorted(_HM["by_source"].items(), key=lambda kv: -kv[1])},
            "by_method": {k: round(v, 1) for k, v in sorted(_HM["by_method"].items(), key=lambda kv: -kv[1])},
        }
        for d in sorted(days)[:-14]:
            days.pop(d, None)
        hist = {"updated_at": _now_iso(), "cap": HELIUS_DAILY_CREDIT_CAP, "cap_mode": HELIUS_CAP_MODE,
                "budget_state": helius_budget_state(),
                "note": "estimates from per-call cost table HELIUS_CREDIT_COSTS; compare with the Helius dashboard",
                "days": days}
        _save_json_atomic(HELIUS_METER_FILE, hist)
    except Exception:
        pass


def helius_meter(method: str, source: str = "?", credits: Optional[float] = None) -> None:
    """Count estimated Helius credits per day / source / method."""
    try:
        if credits is None:
            credits = float(HELIUS_CREDIT_COSTS.get(method, HELIUS_CREDIT_COSTS.get("default", 1)))
        with _HM_LOCK:
            day = _hm_day()
            if _HM["day"] != day:
                if _HM["day"] is not None:
                    _hm_flush(force=True)
                _HM.update({"day": day, "total": 0.0, "by_source": {}, "by_method": {}, "calls": 0})
                try:   # resume today's numbers after a restart
                    with open(HELIUS_METER_FILE, encoding="utf-8") as f:
                        prev = ((json.load(f) or {}).get("days") or {}).get(day) or {}
                    _HM["total"] = float(prev.get("total_credits_est") or 0)
                    _HM["calls"] = int(prev.get("calls") or 0)
                    _HM["by_source"] = dict(prev.get("by_source") or {})
                    _HM["by_method"] = dict(prev.get("by_method") or {})
                except Exception:
                    pass
            _HM["total"] += credits
            _HM["calls"] += 1
            _HM["by_source"][source] = _HM["by_source"].get(source, 0.0) + credits
            _HM["by_method"][method] = _HM["by_method"].get(method, 0.0) + credits
        _hm_flush()
    except Exception:
        pass


def helius_budget_state() -> str:
    if HELIUS_DAILY_CREDIT_CAP <= 0:
        return "off"
    used = _HM["total"] if _HM["day"] == _hm_day() else 0.0
    if used >= HELIUS_DAILY_CREDIT_CAP:
        return "over"
    if used >= HELIUS_DAILY_CREDIT_CAP * HELIUS_SOFT_CAP_PCT / 100.0:
        return "soft"
    return "ok"


def helius_budget_restricted() -> bool:
    """True when background Helius use should stop (trades/wallet never stop)."""
    st = helius_budget_state()
    if HELIUS_CAP_MODE == "log":
        return False
    if HELIUS_CAP_MODE == "soft":
        return st in ("soft", "over")
    return st == "over"


def _rpc_mark_ok(url: str) -> None:
    if _RPC_HEALTH["unhealthy_since"]:
        _log(f"rpc: healthy again via {_rpc_label(url)} (was down since "
             f"{_RPC_HEALTH['unhealthy_since']})", prefix="rpc")
    _RPC_HEALTH.update({"consec_fail": 0, "unhealthy_since": None,
                        "last_ok_at": _now_iso(), "last_endpoint": _rpc_label(url)})
    # livefix: do NOT pop an active bench. A call that started before the bench
    # and then succeeded used to un-bench the endpoint, so the next burst hit the
    # same 429 again (the bench/429 storm). Benches simply expire.
    if _RPC_BENCH.get(url, 0) <= time.monotonic():
        _RPC_BENCH.pop(url, None)


def _rpc_mark_bad(url: str, why: str) -> None:
    first = url not in _RPC_BENCH or _RPC_BENCH[url] <= time.monotonic()
    _RPC_BENCH[url] = time.monotonic() + RPC_FAILOVER_COOLDOWN_S
    if first:
        _log(f"rpc: benching {_rpc_label(url)} for {RPC_FAILOVER_COOLDOWN_S:.0f}s ({why})", prefix="rpc")


def _rpc_note_call_failed() -> None:
    _RPC_HEALTH["consec_fail"] += 1
    if _RPC_HEALTH["consec_fail"] >= RPC_UNHEALTHY_FAILS and not _RPC_HEALTH["unhealthy_since"]:
        _RPC_HEALTH["unhealthy_since"] = _now_iso()
        _log(f"rpc: UNHEALTHY after {_RPC_HEALTH['consec_fail']} failed calls; "
             f"observer/recheck loops pause until a call succeeds", prefix="rpc")


def rpc_is_unhealthy() -> bool:
    if _RPC_HEALTH["unhealthy_since"]:
        return True
    eps = _rpc_endpoints()
    now = time.monotonic()
    return bool(eps) and all(_RPC_BENCH.get(u, 0) > now for u in eps)


async def _rpc_pause_if_unhealthy(label: str, sleep_s: float = 60.0) -> bool:
    """Background observers call this at the top of each cycle. Returns True
    (after sleeping) when RPC is unhealthy so the loop should `continue`."""
    if not rpc_is_unhealthy():
        return False
    try:
        await write_heartbeat(label, "paused", {"paused_via": "rpc_unhealthy",
                                                "since": _RPC_HEALTH["unhealthy_since"]})
    except Exception:
        pass
    _log(f"{label}: RPC down, pausing {sleep_s:.0f}s", prefix="rpc")
    await asyncio.sleep(sleep_s)
    return True


# ── v14 (2026-10-14): 100-credit Enhanced Transactions calls, cached ─────────
# Funder clusters never change, so they are cached for the life of the process.
# Holder hold-time is computed once per card and then at most every
# HOLD_TIME_CACHE_S (30m) while a coin is held. A tripped daily cap skips them.
_FUNDER_CACHE: dict = {}
_SENT_BACK_CACHE: dict = {}
_WALLET_SWAPS_CACHE: dict = {}
_HOLD_TIME_CACHE: dict = {}


async def _identify_funder(deployer: str) -> Optional[str]:
    if deployer in _FUNDER_CACHE:
        return _FUNDER_CACHE[deployer]
    res = await _identify_funder_raw(deployer)
    if len(_FUNDER_CACHE) > FUNDER_CACHE_MAX:
        _FUNDER_CACHE.clear()
    _FUNDER_CACHE[deployer] = res
    return res


async def _wallet_sent_sol_back_to(wallet: str, funder: str) -> bool:
    k = (wallet, funder)
    if k in _SENT_BACK_CACHE:
        return _SENT_BACK_CACHE[k]
    if helius_budget_restricted():
        return False
    res = await _wallet_sent_sol_back_to_raw(wallet, funder)
    if len(_SENT_BACK_CACHE) > FUNDER_CACHE_MAX:
        _SENT_BACK_CACHE.clear()
    _SENT_BACK_CACHE[k] = res
    return res


async def fetch_wallet_swaps(address: str, limit: int = 100) -> list:
    k = (address, limit)
    hit = _WALLET_SWAPS_CACHE.get(k)
    if hit and time.monotonic() - hit[0] < WALLET_SWAPS_CACHE_S:
        return hit[1]
    if helius_budget_restricted():
        return hit[1] if hit else []
    res = await _fetch_wallet_swaps_raw(address, limit)
    if len(_WALLET_SWAPS_CACHE) > 1000:
        _WALLET_SWAPS_CACHE.clear()
    _WALLET_SWAPS_CACHE[k] = (time.monotonic(), res)
    return res


HOLD_TIME_CACHE_FILE = _BOT_LOGS / "hold_time_cache.json"   # survives restarts (2026-10-17)
_HOLD_TIME_PERSIST = {"loaded": False, "dirty": 0, "saved": 0.0}


def _hold_time_cache_load() -> None:
    if _HOLD_TIME_PERSIST["loaded"]:
        return
    _HOLD_TIME_PERSIST["loaded"] = True
    try:
        import atexit as _ax
        _ax.register(_hold_time_cache_save, True)
    except Exception:
        pass
    try:
        with open(HOLD_TIME_CACHE_FILE, encoding="utf-8") as f:
            d = (json.load(f) or {}).get("cache") or {}
        now = time.time()
        for m, (ts, res) in d.items():
            if now - float(ts) < HOLD_TIME_CACHE_S:
                _HOLD_TIME_CACHE[m] = (float(ts), res)
    except Exception:
        pass


def _hold_time_cache_save(force: bool = False) -> None:
    if not force:
        _HOLD_TIME_PERSIST["dirty"] += 1
        if _HOLD_TIME_PERSIST["dirty"] < 5 and time.time() - _HOLD_TIME_PERSIST["saved"] < 60:
            return
    elif not _HOLD_TIME_PERSIST["dirty"]:
        return
    _HOLD_TIME_PERSIST.update({"dirty": 0, "saved": time.time()})
    try:
        now = time.time()
        keep = {m: [ts, res] for m, (ts, res) in _HOLD_TIME_CACHE.items() if now - ts < HOLD_TIME_CACHE_S}
        _save_json_atomic(HOLD_TIME_CACHE_FILE, {"updated_at": _now_iso(), "cache": keep})
    except Exception:
        pass


async def compute_holder_hold_time(mint: str, holder_count: int) -> Optional[dict]:
    _hold_time_cache_load()
    hit = _HOLD_TIME_CACHE.get(mint)
    if hit and time.time() - hit[0] < HOLD_TIME_CACHE_S:
        return hit[1]
    if helius_budget_restricted():
        return hit[1] if hit else None
    res = await _compute_holder_hold_time_raw(mint, holder_count)
    if len(_HOLD_TIME_CACHE) > 2000:
        _HOLD_TIME_CACHE.clear()
    _HOLD_TIME_CACHE[mint] = (time.time(), res)
    _hold_time_cache_save()
    return res


# ── CREDIT-LEAK FIX (2026-10-14 03:45): raw-RPC first, Enhanced API last ─────
# Enhanced /v0/transactions costs 100 credits per call. The funder lookup alone
# burned ~8.8k credits in 20 min. Everything below now uses plain
# getSignaturesForAddress + getTransaction (routed free RPC first, Helius ~1
# credit fallback). Enhanced runs only if HELIUS_ENHANCED_FALLBACK=true AND the
# per-source daily budget HELIUS_ENHANCED_DAILY_MAX is not spent.
HELIUS_ENHANCED_FALLBACK  = _envv("HELIUS_ENHANCED_FALLBACK", "false").lower() in ("true", "1", "yes")
HELIUS_ENHANCED_DAILY_MAX = int(_envv("HELIUS_ENHANCED_DAILY_MAX", "10"))   # per source per day
FUNDER_MAP_FILE           = _BOT_LOGS / "deployer_funder_map.json"   # deployer -> funder, persistent
FUNDER_MAP_NONE_RETRY_S   = float(_envv("FUNDER_MAP_NONE_RETRY_S", "86400"))
RAW_SENTBACK_MAX_TX       = int(_envv("RAW_SENTBACK_MAX_TX", "20"))
RAW_WALLET_SWAPS_MAX_TX   = int(_envv("RAW_WALLET_SWAPS_MAX_TX", "30"))
HOLDTIME_RAW_MAX_TX       = int(_envv("HOLDTIME_RAW_MAX_TX", "60"))     # new txs per mint per refresh
HOLDTIME_MAX_PER_HOUR     = int(_envv("HOLDTIME_MAX_PER_HOUR", "20"))   # mint computations per hour
_ENH_COUNT = {"day": None, "by_source": {}, "warned": set()}
_HOLDTIME_RUNS: list = []
_HOLDTIME_ACQ: dict = {}      # mint -> {"seen": set(sigs), "first": {owner: ts}}


def _enhanced_allow(source: str) -> bool:
    """Gate every 100-credit Enhanced call: knob + per-source daily budget."""
    if not HELIUS_ENHANCED_FALLBACK or helius_budget_restricted():
        return False
    day = _hm_day()
    if _ENH_COUNT["day"] != day:
        _ENH_COUNT.update({"day": day, "by_source": {}, "warned": set()})
    n = _ENH_COUNT["by_source"].get(source, 0)
    if n >= HELIUS_ENHANCED_DAILY_MAX:
        if source not in _ENH_COUNT["warned"]:
            _ENH_COUNT["warned"].add(source)
            _log(f"helius enhanced budget hit for {source} ({HELIUS_ENHANCED_DAILY_MAX}/day); "
                 f"raw RPC only until tomorrow", prefix="rpc")
        return False
    _ENH_COUNT["by_source"][source] = n + 1
    return True




# ── Transaction disk cache (2026-10-17, HELIUS_AUDIT) ───────────────────────────
# A confirmed transaction never changes, so a getTransaction result is cached on
# disk by signature (bot_logs/tx_cache.sqlite, zlib-compressed, oldest rows pruned
# past TX_CACHE_MAX_ROWS). Only complete results (meta + blockTime) are stored;
# misses and errors are never cached. Same data back, fewer RPC calls, across restarts.
TX_CACHE_ENABLED  = (os.getenv("TX_CACHE_ENABLED", "true") or "true").strip().lower() in ("true", "1", "yes", "on")
TX_CACHE_MAX_ROWS = int(float(os.getenv("TX_CACHE_MAX_ROWS", "20000") or 20000))
_TXC_FILE = _BOT_LOGS / "tx_cache.sqlite"
_TXC = {"db": None, "lock": threading.Lock(), "puts": 0, "hits": 0, "miss": 0, "broken": False}


def _txc_db():
    if _TXC["db"] is not None or _TXC["broken"] or not TX_CACHE_ENABLED:
        return _TXC["db"]
    try:
        import sqlite3 as _sq
        _TXC_FILE.parent.mkdir(parents=True, exist_ok=True)
        db = _sq.connect(str(_TXC_FILE), timeout=5, check_same_thread=False)
        db.execute("CREATE TABLE IF NOT EXISTS tx (sig TEXT PRIMARY KEY, ts REAL, data BLOB)")
        db.execute("CREATE INDEX IF NOT EXISTS tx_ts ON tx(ts)")
        db.commit()
        _TXC["db"] = db
    except Exception as e:
        _TXC["broken"] = True
        _log(f"tx cache disabled (non-fatal): {e}", prefix="rpc")
    return _TXC["db"]


def _txc_get(sig: str) -> Optional[dict]:
    db = _txc_db()
    if db is None or not sig:
        return None
    try:
        import zlib as _z
        with _TXC["lock"]:
            row = db.execute("SELECT data FROM tx WHERE sig=?", (sig,)).fetchone()
        if not row:
            _TXC["miss"] += 1
            return None
        _TXC["hits"] += 1
        return json.loads(_z.decompress(row[0]).decode("utf-8"))
    except Exception:
        return None


def _txc_put(sig: str, tx) -> None:
    db = _txc_db()
    if db is None or not sig or not isinstance(tx, dict):
        return
    if not tx.get("meta") or not tx.get("blockTime"):
        return   # incomplete / unconfirmed: never cache
    try:
        import zlib as _z
        blob = _z.compress(json.dumps(tx, separators=(",", ":")).encode("utf-8"), 6)
        with _TXC["lock"]:
            db.execute("INSERT OR REPLACE INTO tx (sig, ts, data) VALUES (?, ?, ?)", (sig, time.time(), blob))
            _TXC["puts"] += 1
            if _TXC["puts"] % 500 == 0:
                n = db.execute("SELECT COUNT(*) FROM tx").fetchone()[0]
                if n > TX_CACHE_MAX_ROWS:
                    db.execute("DELETE FROM tx WHERE sig IN (SELECT sig FROM tx ORDER BY ts ASC LIMIT ?)",
                               (n - int(TX_CACHE_MAX_ROWS * 0.9),))
            db.commit()
    except Exception:
        pass

# Routine tx lookups (hold-time, wallet swaps, sent-back checks) read the free
# RPC only. When it cannot serve several of a batch, ONE Helius
# getTransactionsForAddress call (10 credits per 100 txs) fills the cache instead
# of N single getTransaction calls. RAW_TX_HELIUS_FALLBACK=true restores the old
# per-tx Helius fallback. Single persisted lookups (deployer funder) may still use
# one 1-credit Helius getTransaction.
RAW_TX_HELIUS_FALLBACK = (_envv("RAW_TX_HELIUS_FALLBACK", "false") or "false").strip().lower() in ("true", "1", "yes", "on")
RAW_TX_GTFA_FALLBACK   = (_envv("RAW_TX_GTFA_FALLBACK", "true") or "true").strip().lower() in ("true", "1", "yes", "on")
RAW_TX_GTFA_MIN_MISS   = int(_envv("RAW_TX_GTFA_MIN_MISS", "3"))
RAW_TX_GTFA_LIMIT      = max(1, min(100, int(_envv("RAW_TX_GTFA_LIMIT", "100"))))   # 100 = one 10-credit page


async def _raw_tx(sig: str, helius_ok: bool = False) -> Optional[dict]:
    hit = _txc_get(sig)
    if hit is not None:
        return hit
    tx = await helius_rpc("getTransaction", [sig, {"encoding": "jsonParsed",
                                                   "maxSupportedTransactionVersion": TX_MAX_VERSION,
                                                   "commitment": "confirmed"}], retries=1,
                          free_only=not (helius_ok or RAW_TX_HELIUS_FALLBACK))
    _txc_put(sig, tx)
    return tx


async def _gtfa_fill(address: str, limit: int) -> int:
    """One Helius getTransactionsForAddress page (full, jsonParsed) into the tx cache.
    Returns how many txs were cached. Skipped when RPC_URL is not Helius, the
    credit cap is restricting, or RAW_TX_GTFA_FALLBACK is off."""
    if not (RAW_TX_GTFA_FALLBACK and address and _is_helius_url(RPC_URL)) or helius_budget_restricted():
        return 0
    res = await helius_rpc("getTransactionsForAddress", [address, {
        "transactionDetails": "full", "encoding": "jsonParsed", "sortOrder": "desc",
        "maxSupportedTransactionVersion": TX_MAX_VERSION, "commitment": "confirmed",
        "limit": max(1, min(RAW_TX_GTFA_LIMIT, int(limit or RAW_TX_GTFA_LIMIT)))}], retries=1, rpc_url=RPC_URL)
    rows = (res or {}).get("data") if isinstance(res, dict) else None
    n = 0
    for tx in rows or []:
        try:
            sig = ((tx.get("transaction") or {}).get("signatures") or [None])[0]
        except Exception:
            sig = None
        if sig:
            _txc_put(sig, tx)
            n += 1
    return n


async def _raw_txs(address: str, sigs: list) -> dict:
    """sig -> tx for a batch: cache, then free RPC, then one getTransactionsForAddress
    page for the misses (or per-tx Helius if RAW_TX_HELIUS_FALLBACK)."""
    out, miss = {}, []
    for sig in sigs:
        tx = await _raw_tx(sig)
        if tx:
            out[sig] = tx
        else:
            miss.append(sig)
    if miss and not RAW_TX_HELIUS_FALLBACK and len(miss) >= RAW_TX_GTFA_MIN_MISS:
        if await _gtfa_fill(address, len(sigs)):
            for sig in miss:
                tx = _txc_get(sig)
                if tx:
                    out[sig] = tx
    return out


def _raw_tx_keys(tx: dict) -> list:
    keys = (((tx or {}).get("transaction") or {}).get("message") or {}).get("accountKeys") or []
    return [k.get("pubkey") if isinstance(k, dict) else k for k in keys]


def _raw_sol_deltas(tx: dict) -> dict:
    """account -> lamport delta (post - pre) for a jsonParsed getTransaction."""
    meta = (tx or {}).get("meta") or {}
    pre, post = meta.get("preBalances") or [], meta.get("postBalances") or []
    out = {}
    for i, k in enumerate(_raw_tx_keys(tx)):
        if i < len(pre) and i < len(post) and k:
            out[k] = int(post[i]) - int(pre[i])
    return out


def _raw_token_deltas(tx: dict, owner: Optional[str] = None) -> dict:
    """(owner, mint) -> ui-amount delta from pre/postTokenBalances."""
    meta = (tx or {}).get("meta") or {}
    acc = {}
    for side, sign in (("preTokenBalances", -1), ("postTokenBalances", 1)):
        for b in meta.get(side) or []:
            o, m = b.get("owner"), b.get("mint")
            if not o or not m or (owner and o != owner):
                continue
            amt = float(((b.get("uiTokenAmount") or {}).get("uiAmount")) or 0)
            acc[(o, m)] = acc.get((o, m), 0.0) + sign * amt
    return acc


_FUNDER_MAP_LOADED = {"ok": False, "dirty": 0}


def _funder_map_load() -> None:
    if _FUNDER_MAP_LOADED["ok"]:
        return
    _FUNDER_MAP_LOADED["ok"] = True
    try:
        with open(FUNDER_MAP_FILE, encoding="utf-8") as f:
            d = json.load(f) or {}
        for dep, rec in (d.get("map") or {}).items():
            _FUNDER_PERSIST[dep] = rec
    except Exception:
        pass


def _funder_map_save(force: bool = False) -> None:
    _FUNDER_MAP_LOADED["dirty"] += 1
    if not force and _FUNDER_MAP_LOADED["dirty"] < 10:
        return
    _FUNDER_MAP_LOADED["dirty"] = 0
    try:
        if len(_FUNDER_PERSIST) > 50000:
            for k in sorted(_FUNDER_PERSIST, key=lambda k: _FUNDER_PERSIST[k].get("ts", 0))[:10000]:
                _FUNDER_PERSIST.pop(k, None)
        _save_json_atomic(FUNDER_MAP_FILE, {"updated_at": _now_iso(), "map": _FUNDER_PERSIST})
    except Exception:
        pass


_FUNDER_PERSIST: dict = {}    # deployer -> {"funder": str|None, "ts": epoch, "via": "raw"|"enhanced"}


async def _identify_funder_raw(deployer: str) -> Optional[str]:
    """Funder = biggest SOL sender in the deployer's earliest tx (raw RPC)."""
    _funder_map_load()
    rec = _FUNDER_PERSIST.get(deployer)
    if rec:
        if rec.get("funder") or time.time() - float(rec.get("ts") or 0) < FUNDER_MAP_NONE_RETRY_S:
            return rec.get("funder")
    funder, via = None, "raw"
    try:
        sigs = await helius_rpc("getSignaturesForAddress", [deployer, {"limit": 1000}])
        ok = [s for s in (sigs or []) if isinstance(s, dict) and s.get("blockTime") and s.get("signature")]
        if ok:
            earliest = min(ok, key=lambda s: s["blockTime"])["signature"]
            tx = await _raw_tx(earliest, helius_ok=True)
            if tx:
                d = _raw_sol_deltas(tx)
                if d.get(deployer, 0) > 0:
                    cands = [(v, k) for k, v in d.items()
                             if k != deployer and v < 0 and k != "11111111111111111111111111111111"]
                    if cands:
                        funder = min(cands)[1]
            elif _enhanced_allow("_identify_funder"):
                helius_meter("enhanced", "_identify_funder")
                funder, via = await _identify_funder_enhanced(deployer), "enhanced"
    except Exception as e:
        _log(f"funder raw lookup error: {_err_detail(e)}")
    _FUNDER_PERSIST[deployer] = {"funder": funder, "ts": time.time(), "via": via}
    _funder_map_save()
    return funder


async def _wallet_sent_sol_back_to_raw(wallet: str, funder: str) -> bool:
    try:
        sigs = await helius_rpc("getSignaturesForAddress", [wallet, {"limit": RAW_SENTBACK_MAX_TX}])
        _ok = [s for s in (sigs or [])[:RAW_SENTBACK_MAX_TX]
               if isinstance(s, dict) and s.get("signature") and not s.get("err")]
        _txm = await _raw_txs(wallet, [s["signature"] for s in _ok])
        for s in _ok:
            tx = _txm.get(s["signature"])
            if not tx:
                continue
            d = _raw_sol_deltas(tx)
            if d.get(wallet, 0) < 0 and d.get(funder, 0) > 0:
                return True
        return False
    except Exception:
        return False


async def _fetch_wallet_swaps_raw(address: str, limit: int = 100) -> list:
    """Raw-RPC swap reader: token delta for the wallet + its SOL delta per tx."""
    n = min(limit, RAW_WALLET_SWAPS_MAX_TX)
    try:
        sigs = await helius_rpc("getSignaturesForAddress", [address, {"limit": n}])
        swaps = []
        _ok = [s for s in (sigs or [])[:n] if isinstance(s, dict) and s.get("signature") and not s.get("err")]
        _txm = await _raw_txs(address, [s["signature"] for s in _ok])
        for s in _ok:
            tx = _txm.get(s["signature"])
            if not tx:
                continue
            ts = tx.get("blockTime") or s.get("blockTime") or 0
            sol = _raw_sol_deltas(tx).get(address, 0) / 1e9
            for (o, mint), dt in _raw_token_deltas(tx, address).items():
                if mint in _NON_TOKEN_MINTS or abs(dt) <= 0:
                    continue
                if dt > 0 and sol <= -0.0005:
                    swaps.append({"ts": ts, "mint": mint, "direction": "buy", "sig": s["signature"],
                                  "sol_amount": round(-sol, 6), "token_amount": dt})
                elif dt < 0 and sol >= 0.0005:
                    swaps.append({"ts": ts, "mint": mint, "direction": "sell", "sig": s["signature"],
                                  "sol_amount": round(sol, 6), "token_amount": -dt})
        swaps.sort(key=lambda x: x.get("ts", 0))
        return swaps
    except Exception as e:
        _log(f"fetch_wallet_swaps raw err {_short_mint(address)}: {_err_detail(e)}", prefix="wallet")
        return []


async def _compute_holder_hold_time_raw(mint: str, holder_count: int) -> Optional[dict]:
    """Raw-RPC hold time. Per-mint cache of (holder -> first acquire ts) and seen
    sigs, so a refresh only reads NEW txs (max HOLDTIME_RAW_MAX_TX). Capped at
    HOLDTIME_MAX_PER_HOUR mint computations."""
    if not mint:
        return None
    now = time.time()
    while _HOLDTIME_RUNS and now - _HOLDTIME_RUNS[0] > 3600:
        _HOLDTIME_RUNS.pop(0)
    if len(_HOLDTIME_RUNS) >= HOLDTIME_MAX_PER_HOUR:
        return None
    _HOLDTIME_RUNS.append(now)
    try:
        st = _HOLDTIME_ACQ.setdefault(mint, {"seen": set(), "first": {}})
        if len(_HOLDTIME_ACQ) > 500:
            for k in list(_HOLDTIME_ACQ)[:100]:
                if k != mint:
                    _HOLDTIME_ACQ.pop(k, None)
        sigs = await helius_rpc("getSignaturesForAddress", [mint, {"limit": 200}])
        new = [s for s in (sigs or []) if isinstance(s, dict) and s.get("signature")
               and not s.get("err") and s["signature"] not in st["seen"]][:HOLDTIME_RAW_MAX_TX]
        _txm = await _raw_txs(mint, [s["signature"] for s in new])
        for s in new:
            st["seen"].add(s["signature"])
            tx = _txm.get(s["signature"])
            if not tx:
                continue
            ts = tx.get("blockTime") or s.get("blockTime") or 0
            for (o, m), dt in _raw_token_deltas(tx).items():
                if m == mint and dt > 0 and ts and (o not in st["first"] or ts < st["first"][o]):
                    st["first"][o] = ts
        sample_target = min(HOLDER_HOLDTIME_MAX_SAMPLE,
                            max(20, int((holder_count or 50) * HOLDER_HOLDTIME_SAMPLE_PCT)))
        holds = sorted((now - ts) / 60.0 for ts in st["first"].values() if ts)[:sample_target]
        if not holds:
            return None
        n = len(holds)
        return {"avg_hold_minutes": round(sum(holds) / n, 1),
                "median_hold_minutes": round(holds[n // 2], 1), "sample_n": n,
                "note": "proxy (raw RPC): time since first acquisition of sampled holders; reference not directive"}
    except Exception as e:
        _log(f"compute_holder_hold_time raw err {_short_mint(mint)}: {_err_detail(e)}", prefix="wallet")
        return None


async def helius_rpc(method: str, params: list, *, retries: int = 2,
                      rpc_url: Optional[str] = None, free_only: bool = False) -> Optional[Any]:
    """Solana RPC with endpoint failover (2026-10-14).
    rpc_url pins one endpoint (send-path fallback keeps using that). Otherwise
    walk primary -> RPC_URL_FALLBACK -> public, skipping benched endpoints.
    sendTransaction stays on the primary only."""
    _dop = _DEX_ONLY_PATH.get()
    if _dop:   # 2026-10-15: dex-only polling paths never reach Helius
        _HELIUS_BLOCKED[_dop] = _HELIUS_BLOCKED.get(_dop, 0) + 1
        _log(f"[dex-only] refused helius {method} from {_dop} path", prefix="dexcount")
        return None
    if PAPER_MODE and method in _PAPER_BLOCKED_METHODS:
        _PAPER_BLOCKED_SENDS["n"] += 1
        _log(f"PAPER MODE: refused {method} (no transaction is ever sent in paper mode)", prefix="paper")
        return None
    try:
        _src = sys._getframe(1).f_code.co_name
    except Exception:
        _src = "?"
    if method == "getTransaction":
        params = _txver_params(params)
    if rpc_url:
        _RPC_LAST_FAIL_KIND["kind"] = None
        _r = await _helius_rpc_one(method, params, retries=retries, url=rpc_url)
        if _RPC_LAST_FAIL_KIND["kind"] == "txver":
            params = _txver_params(params)
            _RPC_LAST_FAIL_KIND["kind"] = None
            _r = await _helius_rpc_one(method, params, retries=0, url=rpc_url)
            if _RPC_LAST_FAIL_KIND["kind"] == "txver":
                _txver_summary()
        if _is_helius_url(rpc_url) and _RPC_LAST_FAIL_KIND["kind"] in (None, "jsonrpc"):
            helius_meter(method, _src)
        return _r

    cache_key = None
    if method == "getSignaturesForAddress" and RPC_SIG_CACHE_TTL_S > 0:
        try:
            cache_key = json.dumps(params, sort_keys=True, default=str)
            hit = _RPC_SIG_CACHE.get(cache_key)
            if hit and time.monotonic() - hit[0] < RPC_SIG_CACHE_TTL_S:
                return hit[1]
        except Exception:
            cache_key = None

    eps = [RPC_URL] if method == "sendTransaction" else _rpc_endpoints_for(method, free_only)
    if not eps or not eps[0]:
        return None
    now = time.monotonic()
    live = [u for u in eps if _RPC_BENCH.get(u, 0) <= now]
    if not live:
        if _rpc_is_critical(method):
            live = eps[:1]          # money/wallet calls still get one shot on primary
        else:
            _LAST_RPC_ERROR.update({"method": method, "at": _now_iso(),
                                     "detail": "all rpc endpoints benched"})
            _rpc_note_call_failed()
            return None
    for i, url in enumerate(live):
        last = (i == len(live) - 1)
        # Re-check the bench right before use: a parallel call may have benched
        # this endpoint while we were waiting (never storm a benched endpoint).
        if not last and _RPC_BENCH.get(url, 0) > time.monotonic():
            continue
        _RPC_LAST_FAIL_KIND["kind"] = None
        # Fail over fast: one attempt per endpoint while another is still
        # available, full retries only on the last one. Free/public endpoints
        # never sleep on Retry-After: a 429 there goes straight to the next one.
        _tries = retries if (last and _is_helius_url(url)) else (min(retries, 1) if last else 0)
        res = await _helius_rpc_one(method, params, retries=_tries, url=url)
        kind = _RPC_LAST_FAIL_KIND["kind"]
        if kind == "txver":
            # quiet one-shot retry with the version the node asked for
            params = _txver_params(params)
            _RPC_LAST_FAIL_KIND["kind"] = None
            res = await _helius_rpc_one(method, params, retries=0, url=url)
            kind = _RPC_LAST_FAIL_KIND["kind"]
            if kind == "txver":
                _txver_summary()
                kind = "jsonrpc"
        if _is_helius_url(url) and kind in (None, "jsonrpc"):
            # Credits Helius spent as a fallback for a free-first read are tagged
            # "<caller>:fallback" in helius_meter.json by_source.
            helius_meter(method, _src if url == eps[0] else f"{_src}:fallback")
        if kind == "jsonrpc" and res is None and not last and not _is_helius_url(url):
            continue    # free node refused the method; ask the next endpoint, no bench
        if res is not None or kind in (None, "jsonrpc"):
            # success, or an application-level error (bad params etc.) that a
            # different endpoint would answer the same way
            if kind is None:
                _rpc_mark_ok(url)
                if cache_key is not None and res is not None:
                    _RPC_SIG_CACHE[cache_key] = (time.monotonic(), res)
                    if len(_RPC_SIG_CACHE) > 500:
                        for k in sorted(_RPC_SIG_CACHE, key=lambda k: _RPC_SIG_CACHE[k][0])[:250]:
                            _RPC_SIG_CACHE.pop(k, None)
            return res
        _rpc_mark_bad(url, kind)
    _rpc_note_call_failed()
    return None


TX_MAX_VERSION = int(_envv("TX_MAX_VERSION", "1"))   # highest tx version we request; raised on -32015
_TXVER_FAILS = {"n": 0, "last_log": 0.0}


def _txver_from_error(detail: str) -> Optional[int]:
    """-32015 says 'Transaction version (N) is not supported ... maxSupportedTransactionVersion: N'."""
    if "-32015" not in detail and "not supported by the requesting client" not in detail:
        return None
    import re
    m = re.search(r"version \((\d+)\)", detail) or re.search(r"maxSupportedTransactionVersion\D+(\d+)", detail)
    return int(m.group(1)) if m else None


def _txver_params(params: list) -> list:
    """Force maxSupportedTransactionVersion >= TX_MAX_VERSION on a getTransaction call."""
    try:
        p = list(params)
        cfg = dict(p[1]) if len(p) > 1 and isinstance(p[1], dict) else {"encoding": "json"}
        if int(cfg.get("maxSupportedTransactionVersion", -1)) < TX_MAX_VERSION:
            cfg["maxSupportedTransactionVersion"] = TX_MAX_VERSION
        if len(p) > 1:
            p[1] = cfg
        else:
            p.append(cfg)
        return p
    except Exception:
        return params


_FREE_RPC_SEM: Optional[asyncio.Semaphore] = None
_FREE_RPC_PACE: Optional[asyncio.Lock] = None
_FREE_RPC_LAST = 0.0
RPC_FREE_MAX_CONCURRENT = int(_envv("RPC_FREE_MAX_CONCURRENT", "2"))
RPC_FREE_MIN_INTERVAL_S = float(_envv("RPC_FREE_MIN_INTERVAL_S", "0.25"))


class _free_rpc_gate:
    """livefix 2026-10-14: own limiter for free/public RPC. Bursts of
    getTransaction / getTokenLargestAccounts were tripping 429 together."""
    async def __aenter__(self):
        global _FREE_RPC_SEM, _FREE_RPC_PACE, _FREE_RPC_LAST
        if _FREE_RPC_SEM is None:
            _FREE_RPC_SEM = asyncio.Semaphore(max(1, RPC_FREE_MAX_CONCURRENT))
            _FREE_RPC_PACE = asyncio.Lock()
        await _FREE_RPC_SEM.acquire()
        try:
            async with _FREE_RPC_PACE:
                gap = time.monotonic() - _FREE_RPC_LAST
                if gap < RPC_FREE_MIN_INTERVAL_S:
                    await asyncio.sleep(RPC_FREE_MIN_INTERVAL_S - gap)
                _FREE_RPC_LAST = time.monotonic()
        except BaseException:
            _FREE_RPC_SEM.release()
            raise
        return self

    async def __aexit__(self, *a):
        _FREE_RPC_SEM.release()
        return False


def _txver_summary() -> None:
    now = time.monotonic()
    if now - _TXVER_FAILS["last_log"] >= 60:
        _TXVER_FAILS["last_log"] = now
        _log(f"getTransaction: tx-version mismatch persisted after retry "
             f"({_TXVER_FAILS['n']} version errors so far; now requesting v{TX_MAX_VERSION})", prefix="rpc")


async def _helius_rpc_one(method: str, params: list, *, retries: int = 2,
                          url: Optional[str] = None) -> Optional[Any]:
    """Single-endpoint RPC call with retry on 429 (the pre-2026-10-14 body)."""
    url = url or RPC_URL
    if not url:
        return None
    
    payload = {"jsonrpc": "2.0", "id": 1, "method": method, "params": params}
    
    client = await _get_rpc_client()
    for attempt in range(retries + 1):
        # The gate is acquired INSIDE try/finally. An earlier draft released the
        # semaphore only on the 429 path, so every success and every error leaked
        # a slot — after _RPC_MAX_CONCURRENT calls the bot would have deadlocked
        # on RPC forever. A throttle that can hang the bot is worse than the 429s
        # it was built to prevent. Caught by predeploy; never let it near the wallet.
        await _rpc_gate(method)
        _gate_held = True
        try:
            _r_t0 = time.monotonic()
            if _is_helius_url(url):
                r = await client.post(url, json=payload)
            else:
                async with _free_rpc_gate():
                    r = await client.post(url, json=payload)
            if r.status_code == 429:
                _rpc_stat(method, limited=True)
                _LAST_RPC_ERROR.update({"method": method, "at": _now_iso(),
                                         "detail": f"HTTP 429 rate-limited (attempt {attempt + 1})"})
                # Honour Retry-After when Helius sends it (their own sample code
                # reads this header). Fall back to EXPONENTIAL backoff with
                # jitter — the old linear 1.5s*attempt made every parallel caller
                # sleep and wake together, converting a burst into a wave.
                _ra = r.headers.get("Retry-After")
                try:
                    _delay = float(_ra) if _ra else (1.5 * (2 ** attempt))
                except (TypeError, ValueError):
                    _delay = 1.5 * (2 ** attempt)
                _delay += (time.monotonic() * 1000) % 400 / 1000.0   # de-sync jitter (clock-derived, no new
                                                    # import): parallel callers must not wake together
                try:
                    _b429 = _redact((r.text or "")[:160]).replace("\n", " ")
                except Exception:
                    _b429 = ""
                _final = attempt == retries
                _log(f"helius_rpc({method}) 429 on attempt {attempt + 1} [{_rpc_label(url)}] "
                     + ("— failing over" if _final else f"— backing off {_delay:.2f}s"
                        + (" (Retry-After)" if _ra else ""))
                     + (f" body={_b429}" if _b429 else ""), prefix="rpc")
                _RPC_LAST_FAIL_KIND["kind"] = "limited"
                _rpc_release(method); _gate_held = False   # free the slot BEFORE sleeping
                if attempt == retries:
                    break                                   # no sleep after the final try; caller fails over
                await asyncio.sleep(_delay)
                continue
            if r.status_code != 200:
                body = ""
                try:
                    body = (r.text or "")[:500]
                except Exception:
                    pass
                _LAST_RPC_ERROR.update({"method": method, "at": _now_iso(),
                                         "detail": f"HTTP {r.status_code}: {body}"})
                _log(f"helius_rpc({method}) HTTP {r.status_code} (attempt {attempt + 1}): {_redact(body)}", prefix="rpc")
                _RPC_LAST_FAIL_KIND["kind"] = "http"
                return None
            data = r.json()
            if isinstance(data, dict) and data.get("error") is not None:
                err = data["error"]
                detail = err if isinstance(err, str) else json.dumps(err)[:500]
                _v = _txver_from_error(detail) if method == "getTransaction" else None
                if _v is not None:
                    global TX_MAX_VERSION
                    if _v > TX_MAX_VERSION:
                        TX_MAX_VERSION = _v
                    _TXVER_FAILS["n"] += 1
                    _RPC_LAST_FAIL_KIND["kind"] = "txver"
                    _rpc_stat(method)
                    return None          # silent; caller retries with the new version
                _LAST_RPC_ERROR.update({"method": method, "at": _now_iso(),
                                         "detail": f"json-rpc error: {detail}"})
                _log(f"helius_rpc({method}) json-rpc error (attempt {attempt + 1}): {_redact(detail)}", prefix="rpc")
                _RPC_LAST_FAIL_KIND["kind"] = ("limited" if ("429" in detail or "rate" in detail.lower())
                                               else "jsonrpc")
                return None
            _rpc_stat(method)
            _health_note("rpc", {"ms": (time.monotonic() - _r_t0) * 1000.0, "label": _rpc_label(url), "method": method, "at": _now_iso()})
            return data.get("result")
        except Exception as e:
            if attempt == retries:
                _LAST_RPC_ERROR.update({"method": method, "at": _now_iso(),
                                         "detail": _redact(f"transport: {e!r}")})
                _log(f"helius_rpc({method}) error: {_redact(repr(e))}", prefix="rpc")
                _RPC_LAST_FAIL_KIND["kind"] = "transport"
                return None
            _rpc_release(method); _gate_held = False        # free before the retry sleep
            await asyncio.sleep(0.5 * (attempt + 1))
        finally:
            if _gate_held:
                _rpc_release(method)
    _LAST_RPC_ERROR.update({"method": method, "at": _now_iso(),
                             "detail": "exhausted retries (429 loop)"})
    return None


async def get_mint_account_info(mint: str) -> Optional[dict]:
    """Get raw mint account info , used for freeze auth check."""
    result = await helius_rpc(
        "getAccountInfo",
        [mint, {"encoding": "jsonParsed"}],
    )
    if not result or not isinstance(result, dict):
        return None
    val = result.get("value")
    if not val:
        return None
    parsed = ((val.get("data") or {}).get("parsed") or {}).get("info") or {}
    return parsed


# Sprint 28.8.1 , cached mint decimals lookup. Most pump.fun tokens use 6,
# but some use 9. Without this, buy log shows raw smallest-unit (e.g.
# "147,370,550,083 tokens" when actual is ~147,370 with 6 decimals).
_MINT_DECIMALS_CACHE: dict[str, int] = {}

async def get_mint_decimals(mint: str) -> int:
    """Returns decimals for a mint. Defaults to 6 (pump.fun convention) on lookup failure."""
    if mint in _MINT_DECIMALS_CACHE:
        return _MINT_DECIMALS_CACHE[mint]
    try:
        info = await get_mint_account_info(mint)
        if info and "decimals" in info:
            d = int(info["decimals"])
            _MINT_DECIMALS_CACHE[mint] = d
            return d
    except Exception:
        pass
    # Fallback: pump.fun uses 6 by default
    _MINT_DECIMALS_CACHE[mint] = 6
    return 6


def format_token_amount(raw_amount: float, decimals: int) -> str:
    """Format raw smallest-unit token amount for human display."""
    actual = raw_amount / (10 ** decimals)
    if actual >= 1_000_000:
        return f"{actual:,.0f}"
    elif actual >= 1:
        return f"{actual:,.2f}"
    else:
        return f"{actual:,.6f}"


async def get_deployer_history(mint: str) -> dict:
    """
    Identify the deployer wallet for this mint and return their reputation.
    
    Returns:
      {
        address: deployer wallet (str or None),
        funder: wallet that funded the deployer (str or None),
        prior_launches: int,
        prior_rugs: int,
        prior_winners: int,
        rep: "unknown" | "clean" | "mixed" | "scammer",
        rep_via: "deployer" | "funder",  # which graph triggered scammer flag
        first_seen: ISO timestamp of first launch,
      }
    
    Sprint 28.3 fresh-wallet rugger defense:
      Bad actors farm fresh wallets per launch. We now check both the deployer's
      direct history AND the FUNDER's history (whoever sent the deployer their
      first SOL). If the funder has scammer rep, we tag the deployer as scammer
      via inheritance , same rugger, fresh wallet, blocked.
    
    Caching: results cached to deployer_cache.json + funder_cache.json,
    refreshed only when entry is missing or >7 days old.
    """
    default_unknown = {
        "address": None,
        "funder": None,
        "prior_launches": 0,
        "prior_rugs": 0,
        "prior_winners": 0,
        "rep": "unknown",
        "rep_via": None,
        "first_seen": None,
    }
    
    if not HELIUS_API_KEY:
        return default_unknown
    
    # Step 1: identify deployer from earliest mint signature
    deployer = await _identify_deployer(mint)
    if not deployer:
        return default_unknown
    
    # Step 2: check deployer cache
    cache = load_json_with_staleness(DEPLOYER_CACHE_FILE, max_age_seconds=86400 * 365, default={}, alert_on_stale=False)
    if not isinstance(cache, dict):
        cache = {}
    cache.pop("_meta", None)
    
    cached = cache.get(deployer)
    if cached:
        cached_at = cached.get("_cached_at_ts", 0)
        if (_now_ts() - cached_at) < 86400 * 7:
            return {**cached, "address": deployer}
    
    # Step 3: enumerate deployer's prior token launches via autopsy_reports
    autopsies = load_json_with_staleness(AUTOPSY_REPORTS_FILE, max_age_seconds=86400 * 365, default=[], alert_on_stale=False)
    prior_launches = 0
    prior_rugs = 0
    prior_winners = 0
    first_seen = None
    
    if isinstance(autopsies, list):
        for record in autopsies:
            if not isinstance(record, dict):
                continue
            if record.get("deployer_address") == deployer:
                prior_launches += 1
                pnl = record.get("pnl_pct", 0) or 0
                if pnl < -50:
                    prior_rugs += 1
                elif pnl > 50:
                    prior_winners += 1
                ts = record.get("closed_at") or record.get("timestamp")
                if ts and (first_seen is None or ts < first_seen):
                    first_seen = ts
    
    # Step 4: classify direct deployer rep
    if prior_launches == 0:
        rep = "unknown"
        rep_via = None
    elif prior_rugs >= 3 and prior_rugs >= prior_winners * 2:
        rep = "scammer"
        rep_via = "deployer"
    elif prior_winners > prior_rugs:
        rep = "clean"
        rep_via = "deployer"
    else:
        rep = "mixed"
        rep_via = "deployer"
    
    # Step 5: FUNDER GRAPH , fresh-wallet rugger defense
    # Only check funder if deployer is "unknown" (fresh wallet with no history).
    # If deployer is already tagged via direct history, we don't need funder check.
    funder = None
    if rep == "unknown":
        funder = await _identify_funder(deployer)
        if funder:
            funder_rep = await _check_funder_rep(funder, autopsies)
            if funder_rep == "scammer":
                rep = "scammer"
                rep_via = "funder"  # inherited via funding graph
    
    result = {
        "address": deployer,
        "funder": funder,
        "prior_launches": prior_launches,
        "prior_rugs": prior_rugs,
        "prior_winners": prior_winners,
        "rep": rep,
        "rep_via": rep_via,
        "first_seen": first_seen,
        "_cached_at": _now_iso(),
        "_cached_at_ts": _now_ts(),
    }
    
    # Step 6: write back to cache
    cache[deployer] = result
    try:
        _save_json_atomic(DEPLOYER_CACHE_FILE, cache)
    except Exception as e:
        _log(f"deployer cache write error: {e}")
    
    return result


async def _identify_funder_enhanced(deployer: str) -> Optional[str]:
    """
    Find the wallet that funded the deployer with their first SOL.
    
    Approach: get the deployer's earliest signature, look at the transaction's
    SOL transfers, find the inbound SOL source. That's the funder.
    
    Returns funder address or None.
    """
    if not HELIUS_API_KEY:
        return None
    
    try:
        # Get the deployer's earliest signature
        sigs_result = await helius_rpc(
            "getSignaturesForAddress",
            [deployer, {"limit": 1000}],
        )
        if not sigs_result or not isinstance(sigs_result, list) or not sigs_result:
            return None
        
        sorted_sigs = sorted(
            [s for s in sigs_result if isinstance(s, dict) and s.get("blockTime")],
            key=lambda s: s.get("blockTime", 0),
        )
        if not sorted_sigs:
            return None
        
        earliest_sig = sorted_sigs[0].get("signature")
        if not earliest_sig:
            return None
        
        # Pull the transaction; find the source of the first SOL transfer to deployer
        client = await _get_rpc_client()
        url = f"https://api.helius.xyz/v0/transactions"
        r = await client.post(
            url,
            params={"api-key": HELIUS_API_KEY},
            json={"transactions": [earliest_sig]},
        )
        if r.status_code != 200:
            return None
        
        data = r.json() or []
        if not isinstance(data, list) or not data:
            return None
        
        tx = data[0]
        native_xfers = tx.get("nativeTransfers") or []
        # Find inbound SOL transfer to the deployer
        for xfer in native_xfers:
            if xfer.get("toUserAccount") == deployer:
                amount = float(xfer.get("amount") or 0)
                if amount > 0:
                    funder = xfer.get("fromUserAccount")
                    # Skip system program / well-known faucets
                    if funder and funder != "11111111111111111111111111111111":
                        return funder
        return None
    except Exception as e:
        _log(f"funder identification error: {e}")
        return None


async def _check_funder_rep(funder: str, autopsies: list) -> str:
    """
    Check the funder's reputation by looking up which deployers they've funded
    and whether those deployers' tokens rugged.
    
    Returns "scammer" if the funder has bankrolled 3+ rugs, else "unknown"/"clean".
    """
    funder_cache = load_json_with_staleness(FUNDER_CACHE_FILE, max_age_seconds=86400 * 365, default={}, alert_on_stale=False)
    if not isinstance(funder_cache, dict):
        funder_cache = {}
    funder_cache.pop("_meta", None)
    
    cached = funder_cache.get(funder)
    if cached:
        cached_at = cached.get("_cached_at_ts", 0)
        if (_now_ts() - cached_at) < 86400 * 7:
            return cached.get("rep", "unknown")
    
    # Cross-reference: which deployers in autopsy_reports were funded by this funder?
    funded_deployers_with_rugs = 0
    funded_deployers_with_wins = 0
    
    if isinstance(autopsies, list):
        for record in autopsies:
            if not isinstance(record, dict):
                continue
            # Check if record has funder field directly OR look up deployer's funder
            record_funder = record.get("deployer_funder") or record.get("funder")
            if record_funder == funder:
                pnl = record.get("pnl_pct", 0) or 0
                if pnl < -50:
                    funded_deployers_with_rugs += 1
                elif pnl > 50:
                    funded_deployers_with_wins += 1
    
    # Classify funder
    if funded_deployers_with_rugs >= 3 and funded_deployers_with_rugs >= funded_deployers_with_wins * 2:
        rep = "scammer"
    elif funded_deployers_with_wins > funded_deployers_with_rugs and funded_deployers_with_wins >= 2:
        rep = "clean"
    else:
        rep = "unknown"
    
    funder_cache[funder] = {
        "rep": rep,
        "funded_rugs": funded_deployers_with_rugs,
        "funded_wins": funded_deployers_with_wins,
        "_cached_at": _now_iso(),
        "_cached_at_ts": _now_ts(),
    }
    try:
        _save_json_atomic(FUNDER_CACHE_FILE, funder_cache)
    except Exception:
        pass
    
    return rep


async def _identify_deployer(mint: str) -> Optional[str]:
    """
    Identify the deployer wallet for a mint by finding the earliest signature
    and pulling the fee payer.
    
    Returns the deployer address or None on failure.
    """
    # Get oldest signatures (limit + sort by old)
    result = await helius_rpc(
        "getSignaturesForAddress",
        [mint, {"limit": 1000}],  # ~1000 signatures, oldest at the end
    )
    if not result or not isinstance(result, list) or not result:
        return None
    
    # Sort by blockTime ascending , earliest first
    sorted_sigs = sorted(
        [s for s in result if isinstance(s, dict) and s.get("blockTime")],
        key=lambda s: s.get("blockTime", 0),
    )
    if not sorted_sigs:
        return None
    
    earliest_sig = sorted_sigs[0].get("signature")
    if not earliest_sig:
        return None
    
    # Fetch the earliest transaction and pull the fee payer
    tx_result = await helius_rpc(
        "getTransaction",
        [earliest_sig, {"encoding": "jsonParsed", "maxSupportedTransactionVersion": TX_MAX_VERSION}],
    )
    if not tx_result or not isinstance(tx_result, dict):
        return None
    
    msg = ((tx_result.get("transaction") or {}).get("message") or {})
    accounts = msg.get("accountKeys") or []
    if not accounts:
        return None
    
    # Fee payer is always the first signer account
    first_acc = accounts[0]
    if isinstance(first_acc, dict):
        return first_acc.get("pubkey")
    if isinstance(first_acc, str):
        return first_acc
    return None


async def get_holders_top10(mint: str) -> Optional[dict]:
    """
    Returns {top10_pct, dev_holding_pct, holder_count, top_holders[]}.
    
    Fixes from v11.0:
      - total_supply is now the REAL mint supply (via getTokenSupply), not
        the sum of the top-20 accounts (which made top10_pct wrong)
      - holder_count is now the REAL total holder count (via Helius enhanced
        API), not the API page size (which was always 20)
    
    Returns None if RPC fails entirely.
    """
    # 1. Get top-20 largest accounts (for top10_pct + dev_pct)
    largest_result = await helius_rpc("getTokenLargestAccounts", [mint])
    if not largest_result or not isinstance(largest_result, dict):
        return None
    
    accounts = largest_result.get("value", []) or []
    if not accounts:
        return None
    
    # 2. Get the REAL mint supply (was bug: summing top-20 doesn't equal total supply)
    supply_result = await helius_rpc("getTokenSupply", [mint])
    real_total_supply = 0
    if isinstance(supply_result, dict):
        val = supply_result.get("value") or {}
        real_total_supply = int(val.get("amount") or 0)
    
    # Fall back to top-20 sum if getTokenSupply failed
    if real_total_supply <= 0:
        real_total_supply = sum(int(a.get("amount", 0)) for a in accounts if a.get("amount"))
    
    if real_total_supply <= 0:
        return None
    
    top10 = accounts[:10]
    top10_amount = sum(int(a.get("amount", 0)) for a in top10 if a.get("amount"))
    top10_pct = (top10_amount / real_total_supply) * 100
    
    dev_amount = int(accounts[0].get("amount", 0))
    dev_pct = (dev_amount / real_total_supply) * 100
    
    # 3. Get REAL holder count via Helius enhanced API (was bug: hardcoded to 20)
    real_holder_count = await _fetch_real_holder_count(mint)
    if real_holder_count is None or real_holder_count <= 0:
        # Fallback: report known minimum, flag uncertainty
        real_holder_count = max(len(accounts), 20)  # at least the page size we saw
    
    # v14.2: resolve token-account -> owner wallet (one getMultipleAccounts read,
    # free RPC first). The wallet funnel needs owners, not token accounts.
    _owners = {}
    if WALLET_OWNER_RESOLVE:
        try:
            _addrs = [a.get("address") for a in accounts if a.get("address")][:20]
            _res = await helius_rpc("getMultipleAccounts", [_addrs, {"encoding": "jsonParsed"}])
            for _a, _v in zip(_addrs, (_res or {}).get("value") or []):
                try:
                    _owners[_a] = ((((_v or {}).get("data") or {}).get("parsed") or {}).get("info") or {}).get("owner")
                except Exception:
                    pass
        except Exception:
            _owners = {}
    return {
        "top10_pct": round(top10_pct, 1),
        "dev_holding_pct": round(dev_pct, 1),
        "holder_count": real_holder_count,
        # Return the full cheap set (~20 from getTokenLargestAccounts). top10_pct/dev
        # still computed off the top 10 above; this list carries the top 20 so the
        # wallet funnel sees the real mover set, not just 10. Concentration analysis
        # that wants only 10 can slice [:10].
        "top_holders": [
            {
                "address": a.get("address"),
                "owner": _owners.get(a.get("address")),
                "amount": a.get("amount"),
                "pct": round((int(a.get("amount", 0)) / real_total_supply) * 100, 2),
            }
            for a in accounts[:20]
        ],
    }


async def _fetch_real_holder_count(mint: str) -> Optional[int]:
    """
    Get the REAL holder count for a mint using Helius getTokenAccounts (DAS API).
    
    Bug fix from v11.1:
      Old code used limit:1, expecting a 'total' field that represented the
      dataset count. But Helius returns 'total' = count of accounts IN THIS
      RESPONSE, not the dataset total. So limit:1 → total:1.
    
    Correct approach: use limit=1000 (the API max), count actual accounts returned.
    For pump.fun memecoins this is sufficient , they almost never have >1000 holders
    at the sizes we scan. Over 1000 we paginate (rare for our use case).
    
    Returns the holder count, or None if Helius unavailable.
    """
    if not HELIUS_API_KEY:
        return None
    
    try:
        client = await _get_rpc_client()
        url = "https://mainnet.helius-rpc.com/"
        
        # First page (limit=1000)
        body = {
            "jsonrpc": "2.0",
            "id": "holder-count",
            "method": "getTokenAccounts",
            "params": {
                "mint": mint,
                "limit": 1000,
                "page": 1,
            },
        }
        r = await client.post(
            url,
            params={"api-key": HELIUS_API_KEY},
            json=body,
        )
        if r.status_code != 200:
            return None
        data = r.json() or {}
        result = data.get("result") or {}
        token_accounts = result.get("token_accounts") or []
        first_page_count = len(token_accounts)
        
        # If we got <1000, that's the full count , token has fewer than 1000 holders
        if first_page_count < 1000:
            return first_page_count
        
        # Got 1000 , need pagination. Cap at 5 pages (5000 holders) to bound cost.
        # Tokens with >5000 holders are mature, get reported as "5000+".
        total_count = first_page_count
        for page in range(2, 6):
            body["params"]["page"] = page
            r = await client.post(url, params={"api-key": HELIUS_API_KEY}, json=body)
            if r.status_code != 200:
                break
            page_data = r.json() or {}
            page_accounts = (page_data.get("result") or {}).get("token_accounts") or []
            total_count += len(page_accounts)
            if len(page_accounts) < 1000:
                return total_count  # last page , return exact count
        
        return total_count  # 5000+ holders, return what we counted
    except Exception as e:
        _log(f"holder count fetch error: {e}")
        return None


# ═══════════════════════════════════════════════════════════════════════════
#         WALLET INTELLIGENCE FUNNEL (Sprint 65) — the wallets find us
# ═══════════════════════════════════════════════════════════════════════════

def _wallet_load(path: Path) -> dict:
    """Load a wallet store (scan or matched). Always returns a dict."""
    try:
        d = load_json_with_staleness(path, max_age_seconds=86400 * 30,
                                     default={}, alert_on_stale=False)
        if isinstance(d, dict):
            d.pop("_meta", None)     # v14.2: the staleness stamp was saved back as a fake wallet
        return d if isinstance(d, dict) else {}
    except Exception as e:
        _log(f"_wallet_load {path.name} err: {e}", prefix="wallet")
        return {}


def _wallet_scan_prune(scan: dict) -> dict:
    """Keep wallet_scan bounded: drop single-sighting wallets older than the expiry
    window (seen once, never recurred = noise), then hard-cap at WALLET_SCAN_CAP by
    dropping the oldest last_seen. Wallets that recur graduate OUT to matched before
    this ever touches them, so pruning only ever removes genuine one-offs."""
    now = time.time()
    cutoff = now - WALLET_SCAN_EXPIRE_DAYS * 86400
    pruned = {a: r for a, r in scan.items()
              if (r.get("last_seen", 0) >= cutoff)}
    if len(pruned) > WALLET_SCAN_CAP:
        ordered = sorted(pruned.items(), key=lambda kv: kv[1].get("last_seen", 0))
        for addr, _ in ordered[:len(pruned) - WALLET_SCAN_CAP]:
            pruned.pop(addr, None)
    return pruned


def wallet_funnel_ingest(mint: str, ticker: str, top_holders: list) -> dict:
    """Feed a scanned token's top holders into the wallet net. This is the whole
    'wallets find us' engine, and it rides FOR FREE on the holder data every scan
    already pulls — no extra API calls.

    For each top-holder wallet:
      - first sighting -> recorded in wallet_scan
      - second sighting -> GRADUATES to wallet_matched: removed from scan (saves room),
        seeded with tally=2, ready for the agent to name + for us to track its PnL.
      - already matched -> tally++ and note this token.

    Returns {new_matches: [...], updated_matches: [...]} for the caller to surface.
    """
    if not top_holders:
        return {"new_matches": [], "updated_matches": []}
    try:
        now = time.time()
        scan = _wallet_load(WALLET_SCAN_FILE)
        matched = _wallet_load(WALLET_MATCHED_FILE)
        new_matches, updated_matches = [], []

        for h in top_holders[:WALLET_TRACK_PER_TOKEN]:
            # v14.2 ROOT CAUSE of "wallet tracker holds 1 wallet": top_holders are TOKEN
            # ACCOUNTS (one per mint), so the same trader could never recur across tokens.
            # Use the resolved OWNER; skip rows we could not resolve.
            if isinstance(h, dict):
                addr = h.get("owner") if WALLET_OWNER_RESOLVE else h.get("address")
            else:
                addr = None if WALLET_OWNER_RESOLVE else h
            if not addr or not isinstance(addr, str) or addr in WALLET_EXCLUDE_OWNERS:
                continue
            if addr in matched and int(matched[addr].get("tally") or 0) >= WALLET_INFRA_TOKEN_COUNT:
                matched[addr]["infra"] = True     # pool/program authority, not a trader
                continue

            if addr in matched:
                m = matched[addr]
                toks = m.setdefault("tokens", [])
                # Only a DIFFERENT token counts as recurrence. Re-scanning the same
                # token (its holders reappear every scan) is NOT edge — it's just the
                # token being scanned again. Tally bumps only on a new distinct token.
                if mint not in toks:
                    m["tally"] = int(m.get("tally", 1)) + 1
                    toks.append(mint)
                    toks[:] = toks[-50:]
                    m["last_seen"] = now
                    updated_matches.append(addr)
                continue

            if addr in scan:
                prior = scan.get(addr)
                prior_tokens = prior.get("tokens", [])
                # Same token re-scanned = not recurrence. Refresh, don't advance.
                if mint in prior_tokens:
                    prior["last_seen"] = now
                    continue
                # New distinct token — accumulate it in scan. Only graduate to matched
                # (and fire a packet) once the wallet has appeared across
                # WALLET_GRADUATE_MIN_TOKENS *different* tokens. Below that it keeps
                # building in scan, silently. This is the bar that stops the flood.
                prior_tokens.append(mint)
                prior["tokens"] = prior_tokens[-50:]
                prior["last_seen"] = now
                if len(prior_tokens) >= WALLET_GRADUATE_MIN_TOKENS:
                    scan.pop(addr)
                    matched[addr] = {
                        "address": addr,
                        "tally": len(prior_tokens),
                        "first_seen": prior.get("first_seen", now),
                        "last_seen": now,
                        "tokens": prior_tokens[-50:],
                        "name": None,
                        "tracking": None,
                    }
                    new_matches.append(addr)
                # else: stays in scan, accumulating distinct tokens
                continue

            scan[addr] = {
                "address": addr,
                "first_seen": now,
                "last_seen": now,
                "tokens": [mint],
            }

        scan = _wallet_scan_prune(scan)
        _save_json_atomic(WALLET_SCAN_FILE, scan)
        _save_json_atomic(WALLET_MATCHED_FILE, matched)

        if new_matches:
            _log(f"wallet funnel: {len(new_matches)} new match(es) on ${ticker} "
                 f"({', '.join(_short_mint(a) for a in new_matches[:3])}"
                 f"{'...' if len(new_matches) > 3 else ''})", prefix="wallet")
        return {"new_matches": new_matches, "updated_matches": updated_matches}
    except Exception as e:
        _log(f"wallet_funnel_ingest err: {e}", prefix="wallet")
        return {"new_matches": [], "updated_matches": []}


# ─── wallet trade history + PnL tracking (Sprint 65) ───

async def _fetch_wallet_swaps_enhanced(address: str, limit: int = 100) -> list:
    """A wallet's recent SWAP transactions via Helius enhanced API. Returns a list of
    {ts, mint, direction (buy|sell), sol_amount, token_amount} — the raw material for
    PnL. Reuses the same enhanced endpoint the funder-tracer uses. Bounded (one call,
    `limit` txns) so polling the tracked set stays cheap."""
    if not HELIUS_API_KEY or not address:
        return []
    try:
        sigs = await helius_rpc("getSignaturesForAddress", [address, {"limit": limit}])
        if not sigs or not isinstance(sigs, list):
            return []
        client = await _get_dex_client()
        url = "https://api.helius.xyz/v0/transactions"
        helius_meter("enhanced", "fetch_wallet_swaps")
        sig_list = [s.get("signature") for s in sigs if isinstance(s, dict) and s.get("signature")]
        swaps = []
        # enhanced endpoint takes up to 100 sigs per call
        for i in range(0, len(sig_list), 100):
            batch = sig_list[i:i + 100]
            try:
                r = await client.post(url, params={"api-key": HELIUS_API_KEY},
                                      json={"transactions": batch})
                data = r.json() or []
            except Exception:
                continue
            for tx in data:
                if not isinstance(tx, dict):
                    continue
                if tx.get("type") not in ("SWAP", "UNKNOWN"):  # UNKNOWN sometimes carries swaps
                    continue
                ts = tx.get("timestamp") or 0
                _sig = tx.get("signature") or ""
                tok_xfers = tx.get("tokenTransfers") or []
                nat_xfers = tx.get("nativeTransfers") or []
                sol_in = sum(float(x.get("amount") or 0) for x in nat_xfers
                             if x.get("fromUserAccount") == address) / 1e9
                sol_out = sum(float(x.get("amount") or 0) for x in nat_xfers
                              if x.get("toUserAccount") == address) / 1e9
                for tx_t in tok_xfers:
                    mint = tx_t.get("mint")
                    if not mint:
                        continue
                    # skip the money leg (wSOL/USDC/USDT/etc) — it's the OTHER side of
                    # the swap, not a traded token. Counting it poisons PnL.
                    if mint in _NON_TOKEN_MINTS:
                        continue
                    got_token = tx_t.get("toUserAccount") == address
                    sent_token = tx_t.get("fromUserAccount") == address
                    amt = float(tx_t.get("tokenAmount") or 0)
                    # require a real SOL amount — a 0.0000 SOL leg means we couldn't read
                    # the money side (routed oddly); skip it rather than log a phantom.
                    MIN_SOL = 0.0005
                    if got_token and sol_in >= MIN_SOL:      # spent SOL, received token = BUY
                        swaps.append({"ts": ts, "mint": mint, "direction": "buy", "sig": _sig,
                                      "sol_amount": round(sol_in, 6), "token_amount": amt})
                    elif sent_token and sol_out >= MIN_SOL:  # sent token, received SOL = SELL
                        swaps.append({"ts": ts, "mint": mint, "direction": "sell", "sig": _sig,
                                      "sol_amount": round(sol_out, 6), "token_amount": amt})
        # livefix 2026-10-14: one tx can carry several token legs for the same
        # mint (routed swaps) -> it was logged/packeted 2-3x. Collapse per
        # (signature, mint, side), summing token legs; SOL side is per-tx already.
        _dd = {}
        for _s in swaps:
            _k = (_s.get("sig") or f"ts{_s.get('ts')}", _s.get("mint"), _s.get("direction"))
            if _k in _dd:
                _dd[_k]["token_amount"] = (_dd[_k].get("token_amount") or 0) + (_s.get("token_amount") or 0)
            else:
                _dd[_k] = dict(_s)
        swaps = sorted(_dd.values(), key=lambda s: s.get("ts", 0))
        return swaps
    except Exception as e:
        _log(f"fetch_wallet_swaps err {_short_mint(address)}: {e}", prefix="wallet")
        return []


def _compute_wallet_pnl(swaps: list, since_ts: float) -> dict:
    """Compute a wallet's realized PnL and hit rate from its swaps AFTER since_ts (we
    track from the moment we START, not old history — old success ≠ current edge).
    Pairs buys→sells per mint (FIFO-ish average) to get per-token round trips.

    Returns {trades, wins, hit_rate, avg_pnl_pct, total_sol_pnl, ready}. `ready` is True
    only once trades ≥ WALLET_TRACK_MIN_TRADES — below that we don't judge."""
    from collections import defaultdict
    pos = defaultdict(lambda: {"sol_in": 0.0, "tok": 0.0})
    round_trips = []
    for s in swaps:
        if s.get("ts", 0) < since_ts:
            continue
        mint = s.get("mint")
        if s["direction"] == "buy":
            pos[mint]["sol_in"] += s["sol_amount"]
            pos[mint]["tok"] += s["token_amount"]
        else:  # sell
            p = pos[mint]
            if p["tok"] <= 0:
                continue  # sell with no tracked buy (pre-tracking bag) — skip
            frac = min(1.0, s["token_amount"] / p["tok"]) if p["tok"] else 0
            cost_basis = p["sol_in"] * frac
            proceeds = s["sol_amount"]
            # require a meaningful cost basis (≥0.0005 SOL) — a near-zero basis makes the
            # % explode (this is what produced the 1.6M% in the first live test). The SOL
            # PnL still counts; we just don't let a dust basis create a nonsense percent.
            if cost_basis >= 0.0005:
                pnl_pct = (proceeds - cost_basis) / cost_basis * 100
                # clamp per-trade % to a sane band — a single memecoin can genuinely 50x,
                # but anything past ~+5000%/-100% is almost always a parsing artifact.
                pnl_pct = max(-100.0, min(5000.0, pnl_pct))
                round_trips.append({"mint": mint, "pnl_pct": pnl_pct,
                                    "sol_pnl": proceeds - cost_basis})
            p["sol_in"] -= cost_basis
            p["tok"] -= s["token_amount"] * frac
    n = len(round_trips)
    wins = sum(1 for r in round_trips if r["pnl_pct"] > 0)
    return {
        "trades": n,
        "wins": wins,
        "hit_rate": round(100 * wins / n, 1) if n else None,
        "avg_pnl_pct": round(sum(r["pnl_pct"] for r in round_trips) / n, 1) if n else None,
        "total_sol_pnl": round(sum(r["sol_pnl"] for r in round_trips), 4) if n else 0,
        "ready": n >= WALLET_TRACK_MIN_TRADES,
    }


def classify_wallet_archetype(track: dict, swaps: list) -> Optional[str]:
    """Auto-label a tracked wallet from its behavior — so 'a rugger just bought' and 'a
    diamond-hand accumulator just bought' read as opposite signals. Derived from the
    wallet's own hold times (buy→sell gaps) + win pattern. SUGGESTION only; the agent's
    name overrides. Returns one of: sniper | holder | accumulator | rugger | mixed, or
    None if too little data.

    - sniper: in and out fast (short median hold), decent hit rate — the flip specialist
    - holder: long holds, patient — conviction plays
    - accumulator: buys far more than it sells (building bags, rarely exits)
    - rugger: consistent fast exits with the token dying after (proceeds >> re-entry) —
      a wallet that dumps ON people. Flagged conservatively.
    - mixed: no dominant pattern
    """
    if not track or not track.get("ready"):
        return None
    try:
        # buy→sell gaps per mint (median hold in minutes)
        from collections import defaultdict
        buys = defaultdict(list)
        gaps = []
        buy_count = sell_count = 0
        for s in sorted(swaps, key=lambda x: x.get("ts", 0)):
            if s["direction"] == "buy":
                buys[s["mint"]].append(s["ts"])
                buy_count += 1
            else:
                sell_count += 1
                if buys.get(s["mint"]):
                    entry_ts = buys[s["mint"]].pop(0)
                    gaps.append((s["ts"] - entry_ts) / 60.0)
        if buy_count == 0:
            return None
        sell_ratio = sell_count / buy_count
        median_hold = sorted(gaps)[len(gaps) // 2] if gaps else None
        hit = track.get("hit_rate") or 0

        # accumulator: buys a lot, rarely sells
        if sell_ratio < 0.4:
            return "accumulator"
        # holder: long median hold
        if median_hold is not None and median_hold >= 180:  # 3h+
            return "holder"
        # sniper: fast holds + winning
        if median_hold is not None and median_hold <= 20 and hit >= 55:
            return "sniper"
        # rugger: fast exits, and it's NOT winning for others (proxy: our own scans of
        # its tokens tend to die). Flagged conservatively — only very fast + high sell.
        if median_hold is not None and median_hold <= 10 and sell_ratio >= 0.9 and hit < 45:
            return "rugger"
        return "mixed"
    except Exception:
        return None


async def trace_wallet_anchor(address: str, swaps: list = None) -> dict:
    """Sprint 65 — the LEAN anchor layer. Work BACKWARD from a wallet that traded: trace
    its funder up to 2 hops to find a private anchor (the durable identity behind fresh
    trade-wallets). We never forward-track anchors — the trade comes to us, we trace back.

    Confidence ladder:
      - 'round_trip'  : this wallet sent SOL BACK to a wallet that funded it → strongest
                        'same operator' tell. High confidence.
      - 'funded'      : one-way funding from a private (non-exchange) wallet within 2 hops.
                        Low confidence.
      - 'unattributed': funder is an exchange/service, or >2 hops, or none found. We do
                        NOT cluster — track the wallet standalone.

    Returns {anchor, confidence, hops}. Cheap: reuses _identify_funder + the swaps we
    already fetched for PnL."""
    result = {"anchor": None, "confidence": "unattributed", "hops": 0}
    try:
        # hop 1: direct funder
        f1 = await _identify_funder(address)
        if not f1:
            return result
        if f1 in _EXCHANGE_ANCHOR_BLOCKLIST:
            return result  # exchange-funded — do not cluster

        # round-trip check (strongest signal): did THIS wallet send SOL back to f1?
        # We already have its swaps; native transfers back to the funder show reuse.
        if swaps is not None:
            for s in swaps:
                # swaps only carry token legs; do a light native-transfer check instead
                pass
        round_trip = await _wallet_sent_sol_back_to(address, f1)
        if round_trip:
            return {"anchor": f1, "confidence": "round_trip", "hops": 1}

        # hop 2: funder's funder (in case f1 is an intermediate, not the anchor)
        f2 = await _identify_funder(f1)
        if f2 and f2 not in _EXCHANGE_ANCHOR_BLOCKLIST:
            rt2 = await _wallet_sent_sol_back_to(f1, f2)
            if rt2:
                return {"anchor": f2, "confidence": "round_trip", "hops": 2}
            return {"anchor": f2, "confidence": "funded", "hops": 2}

        # only a one-hop private funder, no round trip
        return {"anchor": f1, "confidence": "funded", "hops": 1}
    except Exception as e:
        _log(f"trace_wallet_anchor err {_short_mint(address)}: {e}", prefix="wallet")
        return result


async def _wallet_sent_sol_back_to_enhanced(wallet: str, funder: str) -> bool:
    """Did `wallet` send SOL back to `funder` (who funded it)? Funds returning to the
    funder is the strongest 'same operator' tell — you don't send your profits to a
    stranger. Checks recent native transfers. Bounded (one sig pull)."""
    if not HELIUS_API_KEY:
        return False
    try:
        sigs = await helius_rpc("getSignaturesForAddress", [wallet, {"limit": 100}])
        if not sigs or not isinstance(sigs, list):
            return False
        client = await _get_rpc_client()
        url = "https://api.helius.xyz/v0/transactions"
        helius_meter("enhanced", "_wallet_sent_sol_back_to")
        sig_list = [s.get("signature") for s in sigs if isinstance(s, dict) and s.get("signature")]
        for i in range(0, min(len(sig_list), 100), 100):
            batch = sig_list[i:i + 100]
            try:
                r = await client.post(url, params={"api-key": HELIUS_API_KEY},
                                      json={"transactions": batch})
                data = r.json() or []
            except Exception:
                continue
            for tx in data:
                for xf in (tx.get("nativeTransfers") or []):
                    if (xf.get("fromUserAccount") == wallet and
                            xf.get("toUserAccount") == funder and
                            float(xf.get("amount") or 0) > 0):
                        return True
        return False
    except Exception:
        return False


def _rollup_wallet_under_anchor(child_addr: str, anchor_info: dict, track: dict) -> None:
    """Roll a trade-wallet up under its anchor — this is the payoff of the anchor layer.
    An operator's fresh wallets all point at one anchor, so we aggregate their combined
    trading into ONE operator record. Stores {anchor: {children, confidence, combined}}.
    Reference only — a clustered operator is a stronger read than any single wallet, but
    still a lead to reason with, not an order."""
    try:
        anchor = anchor_info.get("anchor")
        if not anchor:
            return
        anchors = _wallet_load(WALLET_ANCHORS_FILE)
        rec = anchors.get(anchor) or {
            "anchor": anchor, "children": [], "confidence": anchor_info.get("confidence"),
            "first_seen": _now_iso(),
        }
        if child_addr not in rec["children"]:
            rec["children"].append(child_addr)
            rec["children"] = rec["children"][-100:]
        # keep the strongest confidence we've seen for this anchor
        if anchor_info.get("confidence") == "round_trip":
            rec["confidence"] = "round_trip"
        # combined stats across children (from each child's tracking snapshot we have now)
        rec["child_count"] = len(rec["children"])
        rec["last_updated"] = _now_iso()
        # fold this child's PnL contribution
        rec.setdefault("combined_sol_pnl", 0.0)
        rec["combined_sol_pnl"] = round(rec["combined_sol_pnl"] + (track.get("total_sol_pnl") or 0), 4)
        anchors[anchor] = rec
        _save_json_atomic(WALLET_ANCHORS_FILE, anchors)
        if rec["child_count"] >= 2:
            _log(f"anchor cluster: {_short_mint(anchor)} now has {rec['child_count']} "
                 f"trade-wallets ({rec['confidence']})", prefix="wallet")
    except Exception as e:
        _log(f"_rollup_wallet_under_anchor err: {e}", prefix="wallet")


async def update_wallet_tracking(address: str) -> dict:
    """Refresh one matched wallet's tracking stats. Called when we decide to evaluate a
    wallet (on promotion, and on the tracked-poll cadence). Fetches swaps, computes PnL
    from the tracking-start timestamp, updates the wallet_matched record. Returns the
    tracking block. DATA ONLY — this never decides to trade, it profiles a wallet."""
    try:
        matched = _wallet_load(WALLET_MATCHED_FILE)
        m = matched.get(address)
        if not m:
            return {}
        track = m.get("tracking") or {}
        # v14.2: 100-credit swap pull at most every WALLET_TRACK_REFRESH_S per wallet
        try:
            _le = track.get("last_eval_ts") or 0
            if _le and time.time() - float(_le) < WALLET_TRACK_REFRESH_S:
                return track
        except Exception:
            pass
        # tracking-start = when we first promoted it; default to now on first eval
        since = track.get("started_ts") or time.time()
        swaps = await fetch_wallet_swaps(address, limit=100)
        pnl = _compute_wallet_pnl(swaps, since)
        track.update({
            "started_ts": since,
            "started_at": track.get("started_at") or _now_iso(),
            "last_eval_at": _now_iso(),
            "last_eval_ts": time.time(),
            "trades": pnl["trades"],
            "hit_rate": pnl["hit_rate"],
            "avg_pnl_pct": pnl["avg_pnl_pct"],
            "total_sol_pnl": pnl["total_sol_pnl"],
            "ready": pnl["ready"],
            "recent_swaps": swaps[-10:],
        })
        track["archetype"] = classify_wallet_archetype(track, swaps)
        _bot = wallet_bot_pattern(swaps)
        track["bot_like"] = _bot
        if _bot:
            track["archetype"] = "bot"
        try:
            track["rank"] = rank_tier({**pnl, "rug_rate": 0.0, "kind": "wallet"},
                                      archetype=track.get("archetype"))
            track["rank_weight"] = 0 if _bot else RANK_TIER_WEIGHTS.get(track["rank"], 1)
        except Exception:
            pass

        # Sprint 65 lean anchor layer: trace this wallet's anchor ONCE (backward, ≤2
        # hops), store it. Fresh trade-wallets behind one operator roll up to the same
        # anchor — turning "50 fresh wallets" into "one operator". Only traced once
        # (cached on the record) to keep it cheap.
        if "anchor_info" not in m:
            try:
                anchor_info = await trace_wallet_anchor(address, swaps)
                m["anchor_info"] = anchor_info
                if anchor_info.get("anchor"):
                    _rollup_wallet_under_anchor(address, anchor_info, track)
            except Exception as _ae:
                _log(f"anchor trace skipped {_short_mint(address)}: {_ae}", prefix="wallet")
        m["tracking"] = track
        matched[address] = m
        _save_json_atomic(WALLET_MATCHED_FILE, matched)
        return track
    except Exception as e:
        _log(f"update_wallet_tracking err {_short_mint(address)}: {e}", prefix="wallet")
        return {}


def _apply_wallet_commands(cmds: dict) -> None:
    """Receiver for the agent's wallet decisions — this is what makes `name_and_track`
    actually persist instead of evaporating. Accepts:
      {"name": {"<address>": "<chosen name>", ...}}     — name a matched wallet
      {"untrack": ["<address>", ...]}                    — stop tracking (demote to matched)
      {"track": ["<address>", ...]}                      — force-promote to tracking
    Any subset. Silently ignores addresses not in the matched store."""
    try:
        matched = _wallet_load(WALLET_MATCHED_FILE)
        changed = False
        for addr, name in (cmds.get("name") or {}).items():
            if addr in matched and name:
                matched[addr]["name"] = str(name)[:40]
                changed = True
                _log(f"wallet named: {_short_mint(addr)} -> '{name}'", prefix="wallet")
        for addr in (cmds.get("untrack") or []):
            if addr in matched and matched[addr].get("tracking"):
                matched[addr]["tracking"] = None
                changed = True
                _log(f"wallet untracked: {matched[addr].get('name') or _short_mint(addr)}", prefix="wallet")
        for addr in (cmds.get("track") or []):
            if addr in matched and not matched[addr].get("tracking"):
                matched[addr]["tracking"] = {"started_ts": time.time(), "started_at": _now_iso(),
                                             "forced": True}
                changed = True
                _log(f"wallet force-tracked: {_short_mint(addr)}", prefix="wallet")
        if changed:
            _save_json_atomic(WALLET_MATCHED_FILE, matched)
    except Exception as e:
        _log(f"_apply_wallet_commands err: {e}", prefix="wallet")
        return False


WALLET_BOT_FILTER        = _envv("WALLET_BOT_FILTER", "true").lower() in ("true", "1", "yes")
WALLET_BOT_BURST_S       = float(_envv("WALLET_BOT_BURST_S", "5"))      # same-mint buys inside this many seconds
WALLET_BOT_BURST_BUYS    = int(_envv("WALLET_BOT_BURST_BUYS", "3"))     # ...this many separate txs = bundler/bot
WALLET_BOT_TINY_SELL_SOL = float(_envv("WALLET_BOT_TINY_SELL_SOL", "0.005"))
WALLET_BOT_TINY_SELLS    = int(_envv("WALLET_BOT_TINY_SELLS", "6"))     # this many tiny sells in the window = bot


def wallet_bot_pattern(swaps: list) -> Optional[str]:
    """livefix 2026-10-14: flag bundler/bot wallets (many same-mint buys within
    seconds, or lots of tiny repeated sells). Returns a reason or None.
    Flagged wallets are not promoted and get rank weight 0."""
    if not WALLET_BOT_FILTER or not swaps:
        return None
    try:
        by_mint = {}
        for s in swaps:
            if s.get("direction") == "buy":
                by_mint.setdefault(s.get("mint"), []).append(float(s.get("ts") or 0))
        for mint, tss in by_mint.items():
            tss.sort()
            j = 0
            for i in range(len(tss)):
                while tss[i] - tss[j] > WALLET_BOT_BURST_S:
                    j += 1
                if i - j + 1 >= WALLET_BOT_BURST_BUYS:
                    return f"burst: {i - j + 1} buys of {_short_mint(mint)} within {WALLET_BOT_BURST_S:.0f}s"
        tiny = sum(1 for s in swaps if s.get("direction") == "sell"
                   and float(s.get("sol_amount") or 0) < WALLET_BOT_TINY_SELL_SOL)
        if tiny >= WALLET_BOT_TINY_SELLS:
            return f"tiny sells: {tiny} sells < {WALLET_BOT_TINY_SELL_SOL} SOL"
    except Exception:
        return None
    return None


def wallet_should_stay_tracked(track: dict) -> bool:
    """The 'maintain good PnL to stay tracked' gate. Before the 5-trade floor we give
    it grace (still proving out). After the floor, it must be net-positive to keep its
    slot — a wallet that's shown ≥5 trades and is underwater has earned removal. This
    is REFERENCE for the drop decision, not a trading signal."""
    if not track:
        return True
    if track.get("bot_like"):
        return False  # livefix: bundler/bot pattern never earns a slot
    if not track.get("ready"):
        return True  # still under the 5-trade floor — grace period
    avg = track.get("avg_pnl_pct")
    hit = track.get("hit_rate")
    # keep if it's making money on average OR hitting more than half its trades
    if (avg is not None and avg > 0) or (hit is not None and hit >= 50):
        return True
    return False


# ─── holder hold-time + per-token folders (Sprint 65 ①+②) ───

async def _compute_holder_hold_time_enhanced(mint: str, holder_count: int) -> Optional[dict]:
    """Average hold time of a TOKEN'S holders — a market-structure signal about the
    token itself (diamond hands vs 3-minute paper hands?). Samples the top ~42% of
    holders (bounded) and derives acquisition time from ONE token transaction-history
    pull, not per-wallet calls.

    Returns {avg_hold_minutes, median_hold_minutes, sample_n} or None. DATA to reason
    with: a 10-second average does NOT mean 'sell in 10 seconds' — it tells you what
    KIND of token this is (casino vs conviction)."""
    if not HELIUS_API_KEY or not mint:
        return None
    try:
        sample_target = min(HOLDER_HOLDTIME_MAX_SAMPLE,
                            max(20, int((holder_count or 50) * HOLDER_HOLDTIME_SAMPLE_PCT)))
        sigs = await helius_rpc("getSignaturesForAddress", [mint, {"limit": 1000}])
        if not sigs or not isinstance(sigs, list):
            return None
        client = await _get_dex_client()
        url = "https://api.helius.xyz/v0/transactions"
        helius_meter("enhanced", "compute_holder_hold_time")
        sig_list = [s.get("signature") for s in sigs if isinstance(s, dict) and s.get("signature")]
        first_acquire = {}
        now = time.time()
        for i in range(0, min(len(sig_list), 500), 100):  # cap 500 txns (5 calls) — bound cost
            batch = sig_list[i:i + 100]
            try:
                r = await client.post(url, params={"api-key": HELIUS_API_KEY},
                                      json={"transactions": batch})
                data = r.json() or []
            except Exception:
                continue
            for tx in data:
                if not isinstance(tx, dict):
                    continue
                ts = tx.get("timestamp") or 0
                for t in (tx.get("tokenTransfers") or []):
                    if t.get("mint") != mint:
                        continue
                    holder = t.get("toUserAccount")
                    if holder and (holder not in first_acquire or ts < first_acquire[holder]):
                        first_acquire[holder] = ts
            if len(first_acquire) >= sample_target:
                break
        if not first_acquire:
            return None
        holds = sorted((now - ts) / 60.0 for ts in first_acquire.values() if ts)
        if not holds:
            return None
        holds = holds[:sample_target]
        n = len(holds)
        return {
            "avg_hold_minutes": round(sum(holds) / n, 1),
            "median_hold_minutes": round(holds[n // 2], 1),
            "sample_n": n,
            "note": "proxy: time since first acquisition of sampled holders; reference not directive",
        }
    except Exception as e:
        _log(f"compute_holder_hold_time err {_short_mint(mint)}: {e}", prefix="wallet")
        return None


def token_folder_append(mint: str, ticker: str, reading: dict) -> None:
    """Append a hold-time (or other) reading to a token's folder — its own memory. Lets
    The agent see the TREND: is avg holder hold time dropping over successive scans (holders
    starting to bail) or holding? A single number is noise; the trend is the signal."""
    try:
        TOKEN_FOLDERS_DIR.mkdir(parents=True, exist_ok=True)
        fp = TOKEN_FOLDERS_DIR / f"{mint}.json"
        folder = {}
        if fp.exists():
            try:
                folder = json.loads(fp.read_text(encoding="utf-8")) or {}
            except Exception:
                folder = {}
        folder.setdefault("mint", mint)
        folder.setdefault("ticker", ticker)
        folder.setdefault("readings", [])
        folder["readings"].append({"at": _now_iso(), "ts": time.time(), **reading})
        folder["readings"] = folder["readings"][-200:]
        avgs = [r.get("avg_hold_minutes") for r in folder["readings"] if r.get("avg_hold_minutes")]
        if len(avgs) >= 2:
            folder["hold_time_trend"] = {
                "first": avgs[0], "latest": avgs[-1],
                "direction": "dropping" if avgs[-1] < avgs[0] * 0.8 else
                             "rising" if avgs[-1] > avgs[0] * 1.2 else "stable",
                "readings_count": len(avgs),
            }
        _save_json_atomic(fp, folder)
    except Exception as e:
        _log(f"token_folder_append err {_short_mint(mint)}: {e}", prefix="wallet")


def token_folder_archive(mint: str) -> None:
    """When a token is sold/closed, move its folder to the archive — stops being live but
    stays as corpus (so 'hold time was dropping before it died' is learnable later). Same
    persist-then-archive lifecycle as the discovery findings."""
    try:
        src = TOKEN_FOLDERS_DIR / f"{mint}.json"
        if not src.exists():
            return
        TOKEN_FOLDERS_ARCHIVE.mkdir(parents=True, exist_ok=True)
        dst = TOKEN_FOLDERS_ARCHIVE / f"{mint}.json"
        folder = json.loads(src.read_text(encoding="utf-8"))
        folder["archived_at"] = _now_iso()
        _save_json_atomic(dst, folder)
        src.unlink()
        _log(f"token folder archived: {_short_mint(mint)}", prefix="wallet")
    except Exception as e:
        _log(f"token_folder_archive err {_short_mint(mint)}: {e}", prefix="wallet")


async def get_wallet_sol_value(address: str = None) -> float:
    """
    Get current SOL balance of a wallet (in SOL, not lamports).
    
    Sprint 28.8.1: use 'confirmed' commitment instead of default 'finalized'.
    Default finalized takes 13-32s to land , caused post-buy wallet reads to
    show STALE pre-tx balance even though the buy already confirmed. Confirmed
    is good enough for our use cases (~400ms after tx lands).
    """
    address = address or HOT_WALLET_ADDR
    if PAPER_MODE and address == HOT_WALLET_ADDR:
        return float(_paper_wallet_load()["sol"])
    result = await helius_rpc("getBalance", [address, {"commitment": "confirmed"}])
    # A missed RPC is not an empty wallet. Returning 0 here stamped a fake
    # outflow and paused buys. Callers that need fail-closed must catch.
    if result is None:
        raise RuntimeError("wallet balance rpc returned none")
    if isinstance(result, dict):
        lamports = result.get("value", 0) or 0
    else:
        lamports = result or 0
    sol = lamports / 1_000_000_000
    if address == HOT_WALLET_ADDR:
        _LAST_WALLET_SOL.update({"sol": sol, "at": _now_iso()})
    return sol


# 2026-10-14: last good hot-wallet read. A failed read is never a 0 balance;
# callers that must report a number use this, flagged as last-known.
_LAST_WALLET_SOL = {"sol": None, "at": None}
_WALLET_READ = {"ok": True, "reason": None}


# Sprint 28.7 , CoinGecko SOL price (free tier, 30 calls/min). 60s cache so a
# packet batch doesn't make 11 separate API calls , first packet fetches, rest reuse.
# Sprint 28.7.1 , added 429 backoff (5min lockout) so a single rate-limit doesn't
# cause every subsequent packet in the batch to also slam the API.
# Sprint 28.7.1 , added asyncio.Lock to deduplicate CONCURRENT calls. Without it,
# 8 packets running in parallel all hit the empty cache simultaneously and fire 8
# separate requests to CoinGecko, immediately tripping the 429 limit. With the
# lock, only 1 fetches; the rest await and reuse.
_SOL_PRICE_CACHE = {
    "price": None,
    "fetched_at_ts": 0,
    "rate_limited_until_ts": 0,  # if > now_ts(), don't retry CoinGecko
}
_SOL_PRICE_CACHE_TTL_S = 60
_SOL_PRICE_RATE_LIMIT_BACKOFF_S = 300  # 5min lockout after 429
_SOL_PRICE_FETCH_LOCK: Optional[asyncio.Lock] = None  # lazy-init in get_sol_price_usd


_SOL_MINT = "So11111111111111111111111111111111111111112"


async def _sol_price_from_jupiter() -> Optional[float]:
    """Jupiter's price API. Tries the current v3 endpoint, then the legacy v4/v6 shapes.

    NOTE (Sprint 55, honest): I could not reach jup.ag from the sandbox to verify the
    exact response shape — the egress allowlist blocked it. So this parser is written to
    tolerate EVERY shape Jupiter has used, and returns None rather than guessing if none
    of them match. If Jupiter is silently failing you'll see "sol price: jupiter failed"
    in the log and the chain will fall through to Binance, which is fine — that is what a
    fallback chain is FOR. Better a source that degrades loudly than one that guesses.
    """
    endpoints = [
        ("https://api.jup.ag/price/v3",      {"ids": _SOL_MINT}),   # Oct 2026: current, x-api-key
        ("https://lite-api.jup.ag/price/v3", {"ids": _SOL_MINT}),   # being phased out, kept as fallback
        ("https://api.jup.ag/price/v2",      {"ids": _SOL_MINT}),
        ("https://price.jup.ag/v4/price",    {"ids": "SOL"}),
    ]
    for url, params in endpoints:
        try:
            async with httpx.AsyncClient(timeout=6) as c:
                _h = ({"x-api-key": JUPITER_API_KEY}
                      if JUPITER_API_KEY and url.startswith("https://api.jup.ag") else None)
                r = await c.get(url, params=params, headers=_h)
                if r.status_code != 200:
                    continue
                d = r.json() or {}
                # every shape Jupiter has shipped:
                #   v3:  { "<mint>": {"usdPrice": 123.4} }
                #   v2:  { "data": { "<mint>": {"price": "123.4"} } }
                #   v4:  { "data": { "SOL":    {"price": 123.4} } }
                cand = None
                node = d.get(_SOL_MINT) or (d.get("data") or {}).get(_SOL_MINT) \
                       or (d.get("data") or {}).get("SOL")
                if isinstance(node, dict):
                    cand = node.get("usdPrice") or node.get("price")
                if cand:
                    p = float(cand)
                    if p > 0:
                        return p
        except Exception:
            continue
    return None


async def _sol_price_from_dexscreener() -> Optional[float]:
    """DexScreener. We already hit this every 15 minutes for the scanner, so it's a
    source we know is reachable and rate-limit-tolerant from this box."""
    try:
        async with httpx.AsyncClient(timeout=6) as c:
            r = await c.get(f"https://api.dexscreener.com/latest/dex/tokens/{_SOL_MINT}")
            if r.status_code == 200:
                pairs = (r.json() or {}).get("pairs") or []
                # take the deepest SOL/USDC-ish pair — deepest liquidity = truest price
                best, best_liq = None, 0
                for p in pairs:
                    liq = ((p.get("liquidity") or {}).get("usd")) or 0
                    px = p.get("priceUsd")
                    if px and liq > best_liq:
                        try:
                            best, best_liq = float(px), liq
                        except (TypeError, ValueError):
                            continue
                if best and best > 0:
                    return best
    except Exception:
        pass
    return None


async def _sol_price_from_binance() -> Optional[float]:
    """Binance public ticker. No key, extremely high limits, and it is the venue that
    actually SETS the price most of the time."""
    try:
        async with httpx.AsyncClient(timeout=6) as c:
            r = await c.get("https://api.binance.com/api/v3/ticker/price",
                            params={"symbol": "SOLUSDT"})
            if r.status_code == 200:
                p = float((r.json() or {}).get("price") or 0)
                if p > 0:
                    return p
    except Exception:
        pass
    return None


async def _sol_price_from_coinbase() -> Optional[float]:
    """Coinbase spot (no key). Binance.com often 451-blocks US IPs."""
    try:
        async with httpx.AsyncClient(timeout=6) as c:
            r = await c.get("https://api.coinbase.com/v2/prices/SOL-USD/spot")
            if r.status_code == 200:
                p = float(((r.json() or {}).get("data") or {}).get("amount") or 0)
                if p > 0:
                    return p
    except Exception:
        pass
    return None


async def get_sol_price_usd() -> Optional[float]:
    """
    SOL/USD with a MULTI-SOURCE FALLBACK CHAIN. Cached 60s, single-flight locked.

    ── Sprint 55: COINGECKO WAS A SINGLE POINT OF FAILURE ──────────────────────────
    The old version had ONE source. On a 429 it set a 5-minute lockout and served stale
    — or `None` if the cache was cold (e.g. right after boot, which is exactly when the
    log shows it failing).

    WHAT ACTUALLY DEPENDS ON IT (checked, not assumed):
      - USD figures in the packet (display)
      - conviction sizing when the agent reasons in dollars
    And, importantly, what does NOT:
      - the 30%-of-wallet cap, the 0.1 SOL floor, the capital floor and the Sunday sweep
        are ALL SOL-DENOMINATED — they read the on-chain balance directly and never touch
        a USD price. So a price outage degrades the DISPLAY, not the money math. That is
        good architecture and it was already there; worth stating plainly so nobody
        "fixes" it later by converting those to USD.

    Still worth a fallback chain: a bot that can't tell you what its own position is
    worth is a bot you stop trusting, and the fix was cheap.

    And the fix was sitting right there: we ALREADY depend on Jupiter (every swap),
    DexScreener (every scan), and Binance is a free public ticker. Leaning the entire
    money-math of the bot on the one API that rate-limits hardest, when three better
    sources were already in the stack, was just an accident of history.

    ORDER (fastest/most-reliable first):
      1. Jupiter      — we route swaps through it; if it's down we can't trade anyway
      2. Binance      — the venue that actually sets the price; huge limits
      3. DexScreener  — already in our request budget
      4. CoinGecko    — LAST. It is the one that 429s.
    """
    global _SOL_PRICE_FETCH_LOCK
    now_ts = _now_ts()

    if (_SOL_PRICE_CACHE.get("price") is not None and
            now_ts - _SOL_PRICE_CACHE.get("fetched_at_ts", 0) < _SOL_PRICE_CACHE_TTL_S):
        return _SOL_PRICE_CACHE["price"]

    if _SOL_PRICE_FETCH_LOCK is None:
        _SOL_PRICE_FETCH_LOCK = asyncio.Lock()

    async with _SOL_PRICE_FETCH_LOCK:
        now_ts = _now_ts()
        if (_SOL_PRICE_CACHE.get("price") is not None and
                now_ts - _SOL_PRICE_CACHE.get("fetched_at_ts", 0) < _SOL_PRICE_CACHE_TTL_S):
            return _SOL_PRICE_CACHE["price"]

        sources = [
            ("jupiter",     _sol_price_from_jupiter),
            ("binance",     _sol_price_from_binance),
            ("coinbase",    _sol_price_from_coinbase),
            ("dexscreener", _sol_price_from_dexscreener),
        ]
        # CoinGecko goes LAST, and only if it isn't in a rate-limit lockout.
        if _SOL_PRICE_CACHE.get("rate_limited_until_ts", 0) <= now_ts:
            sources.append(("coingecko", _sol_price_from_coingecko))

        for name, fn in sources:
            try:
                p = await fn()
            except Exception:
                p = None
            if p and p > 0:
                _SOL_PRICE_CACHE["price"] = float(p)
                _SOL_PRICE_CACHE["fetched_at_ts"] = now_ts
                _SOL_PRICE_CACHE["source"] = name
                if name != "coingecko":
                    # a working alternate means we don't care that CG is limited
                    _SOL_PRICE_CACHE["rate_limited_until_ts"] = 0
                return float(p)
            _log(f"sol price: {name} failed, trying next", prefix="price")

        # EVERY source failed. Serve stale if we have it, and say so loudly — a missing
        # price silently becoming None is how sizing math goes wrong without anyone noticing.
        stale = _SOL_PRICE_CACHE.get("price")
        if stale:
            _age = round(now_ts - _SOL_PRICE_CACHE.get("fetched_at_ts", now_ts))
            _log(f"⚠ ALL {len(sources)} SOL price sources failed — serving STALE "
                 f"${stale:.2f} ({_age}s old). Sizing math is running on old data.",
                 prefix="price")
        else:
            _log("⚠ ALL SOL PRICE SOURCES FAILED AND THE CACHE IS EMPTY. USD figures will "
                 "be null this cycle. The money math (0.1 min, 30% cap, capital floor) is "
                 "SOL-denominated and is UNAFFECTED — but the agent will be sizing without "
                 "dollar context, so he should stick to SOL reasoning until this clears.",
                 prefix="price")
        return stale


async def _sol_price_from_coingecko() -> Optional[float]:
    """CoinGecko — kept as the LAST fallback. It is the one that rate-limits."""
    now_ts = _now_ts()
    try:
        async with httpx.AsyncClient(timeout=8) as c:
            r = await c.get(
                "https://api.coingecko.com/api/v3/simple/price",
                params={"ids": "solana", "vs_currencies": "usd"},
            )
            if r.status_code == 429:
                _SOL_PRICE_CACHE["rate_limited_until_ts"] = now_ts + _SOL_PRICE_RATE_LIMIT_BACKOFF_S
                _log(f"coingecko 429 — locking it out for {_SOL_PRICE_RATE_LIMIT_BACKOFF_S}s "
                     f"(harmless now: it is the LAST fallback, not the primary)",
                     prefix="price")
                return None
            if r.status_code != 200:
                return None
            price = ((r.json() or {}).get("solana") or {}).get("usd")
            return float(price) if price and float(price) > 0 else None
    except Exception:
        return None


async def get_wallet_status_block() -> dict:
    """v13.0 — comprehensive wallet snapshot the agent reads on every packet.

    Returns:
      {
        "wallet_sol": float,
        "wallet_usd": float | None,
        "sol_price_usd": float | None,
        "size_scale_anchor_sol": float,       # v13.0: renamed from baseline_sol
        "size_scale_anchor_usd": float | None,
        "current_max_entry_sol": float,
        "current_max_entry_usd": float | None,
        "pnl_pct": float,                     # signed PnL vs anchor (NOTE: includes external transfers)
        "wallet_floor_sol": float,            # v13.0: WALLET_FLOOR_SOL threshold
        "wallet_floor_active": bool,          # v13.0: True if wallet <= floor (scanner paused)
        "open_positions": int,
        "fetched_at": ISO,
        "_price_source": "coingecko" | "stale" | "unavailable" | "rate_limited"
      }

    v13.0 changes from v12.x:
      - DELETED: drawdown_pct, drawdown_halt_threshold_pct, halt_status, halt_reason
        The drawdown halt system is gone. See WALLET_FLOOR_SOL doctrine.
      - RENAMED: baseline_sol → size_scale_anchor_sol (clarifies the field's purpose
        is sizing math, not a halt trigger)
      - ADDED: wallet_floor_sol + wallet_floor_active so the agent can see the buy-side
        pause state on every packet read.

    Sign convention:
      pnl_pct: wallet 0.5 SOL on 1.0 anchor → -50.0 (drawn down half)
               wallet 2.0 SOL on 1.0 anchor → +100.0 (doubled)
      NOTE: this is "vs anchor," not "trading PnL." External SOL transfers in/out
      of the wallet show up in this number. Drop 3 will add a separate trading-only
      PnL field via wallet_pnl_tracker.

    Whenever sol_price_usd is None, all *_usd fields are also None and the agent
    should size in SOL terms only.
    """
    try:
        wallet_sol = await get_wallet_sol_value()
        wallet_read_ok = True
    except Exception as e:
        # Missed RPC is not an empty wallet and must not kill boot.
        _log(f"get_wallet_status_block: balance read failed ({e}), not treating as 0", prefix="wallet")
        wallet_sol = None
        wallet_read_ok = False
    sol_price = await get_sol_price_usd()

    anchor = load_size_scale_anchor() or {}
    anchor_sol = float(anchor.get("size_scale_anchor_sol", 0) or anchor.get("baseline_sol", 0) or 0)

    try:
        current_max_entry_sol = await get_current_max_entry_sol()
    except Exception:
        current_max_entry_sol = 1.0  # safe default

    # v13.0: wallet floor state (replaces halt_status entirely)
    floor = float(get_override_sync("WALLET_FLOOR_SOL", WALLET_FLOOR_SOL))
    wallet_floor_active = (not wallet_read_ok) or (wallet_sol is not None and wallet_sol <= floor)

    # ── FIX 4 (2026-08-16): THERE ARE THREE FLOORS AND THEY ARE NOT THE SAME ──
    # This block showed exactly one - wallet_floor_sol - so every packet the agent
    # reads implied "the floor" is a single line at 0.05. It is not:
    #
    #   WALLET_FLOOR_SOL (0.05)            gas. Buys pause below it, sells never do.
    #                                       This is the ONLY one that gates a buy.
    #   _LEDGER_SWEEP_MIN_RESERVE_SOL (0.5) what a sweep must leave behind.
    #                                       Touches the vault path, never entry.
    #   capital_floor.floor_sol (live)      the paycheck line / high-water mark.
    #                                       Profit = wallet - this, when it is > 0.
    #
    # A wallet can sit far above 0.05, be "fine" by this block, and still be
    # under the capital floor - which is what "no sweep this week" actually
    # means. Reporting one number for three concepts is how that reads as a
    # contradiction instead of a fact.
    #
    # READ-ONLY. No math changed, no new gate: a buy still gates on
    # WALLET_FLOOR_SOL alone.
    _capital_floor_sol = None
    try:
        _cf = load_capital_floor() or {}
        _capital_floor_sol = float(_cf.get("floor_sol", 0) or 0) or None
    except Exception:
        pass

    # Signed PnL: positive = gain, negative = loss (standard PnL convention).
    # NOTE: this is vs the size-scale anchor, NOT trading-only PnL. External
    # SOL transfers will show up here. Drop 3's wallet_pnl_tracker provides
    # the accurate trading-only number.
    pnl_pct = 0.0
    if anchor_sol > 0:
        pnl_pct = round(((wallet_sol - anchor_sol) / anchor_sol) * 100, 2) if wallet_sol is not None else 0.0

    # Open positions count
    open_positions = 0
    try:
        pos = load_json_with_staleness(POSITIONS_FILE, max_age_seconds=86400,
                                        default={}, alert_on_stale=False)
        if isinstance(pos, dict):
            open_positions = len([k for k, v in pos.items()
                                   if isinstance(v, dict) and v.get("status") == "open"])
    except Exception:
        pass

    # Source label for transparency
    if sol_price is not None:
        cache_age_s = _now_ts() - _SOL_PRICE_CACHE.get("fetched_at_ts", 0)
        if cache_age_s < _SOL_PRICE_CACHE_TTL_S:
            price_source = "coingecko"
        elif _SOL_PRICE_CACHE.get("rate_limited_until_ts", 0) > _now_ts():
            price_source = "rate_limited"  # 429-backoff stale
        else:
            price_source = "stale"
    else:
        if _SOL_PRICE_CACHE.get("rate_limited_until_ts", 0) > _now_ts():
            price_source = "rate_limited"
        else:
            price_source = "unavailable"

    # v13.2 Drop 3: trading-only PnL from wallet_pnl_tracker
    try:
        pnl_state = _load_wallet_pnl_state()
        lifetime_trading_profit_sol = float(pnl_state.get("lifetime_trading_profit_sol", 0))
        lifetime_external_in_sol = float(pnl_state.get("lifetime_external_in_sol", 0))
        lifetime_external_out_sol = float(pnl_state.get("lifetime_external_out_sol", 0))
        pnl_history_trusted = _wallet_pnl_history_trusted(pnl_state)
        pnl_first_snapshot_ts = pnl_state.get("first_snapshot_ts", 0)
        pnl_first_snapshot_iso = (
            datetime.fromtimestamp(pnl_first_snapshot_ts, tz=EST).isoformat()
            if pnl_first_snapshot_ts else None
        )
    except Exception:
        lifetime_trading_profit_sol = 0.0
        lifetime_external_in_sol = 0.0
        lifetime_external_out_sol = 0.0
        pnl_history_trusted = False
        pnl_first_snapshot_iso = None
    
    return {
        "wallet_sol": round(wallet_sol, 4) if wallet_sol is not None else None,
        "wallet_usd": round(wallet_sol * sol_price, 2) if (sol_price and wallet_sol is not None) else None,
        # FIX 4: the other two floors, labelled. Neither gates a buy.
        "capital_floor_sol": _capital_floor_sol,
        "wallet_minus_capital_floor_sol": (round(wallet_sol - _capital_floor_sol, 4)
                                            if (_capital_floor_sol and wallet_sol is not None) else None),
        "sweep_reserve_sol": _LEDGER_SWEEP_MIN_RESERVE_SOL,
        "floors_doc": ("THREE different floors. wallet_floor_sol gates buys (sells always "
                        "run). sweep_reserve_sol is what a vault sweep must leave behind. "
                        "capital_floor_sol is the paycheck high-water mark - profit is "
                        "wallet minus that when it is above zero, and a negative "
                        "wallet_minus_capital_floor_sol means Sunday sends nothing. Only "
                        "wallet_floor_sol is an entry gate."),
        "sol_price_usd": round(sol_price, 2) if sol_price else None,
        "size_scale_anchor_sol": round(anchor_sol, 4),
        "size_scale_anchor_usd": round(anchor_sol * sol_price, 2) if (sol_price and anchor_sol) else None,
        "current_max_entry_sol": round(current_max_entry_sol, 4),
        "current_max_entry_usd": round(current_max_entry_sol * sol_price, 2) if sol_price else None,
        "pnl_pct": pnl_pct,
        # v13.2 Drop 3: trading-only PnL block (separate from anchor-based pnl_pct).
        # NOTE: pnl_pct above includes external transfers. Use these fields for
        # accurate trading-only PnL once the history is trusted (24h+ of operation).
        "trading_pnl": {
            "lifetime_trading_profit_sol": round(lifetime_trading_profit_sol, 4),
            "lifetime_trading_profit_usd": round(lifetime_trading_profit_sol * sol_price, 2) if sol_price else None,
            "lifetime_external_in_sol": round(lifetime_external_in_sol, 4),
            "lifetime_external_out_sol": round(lifetime_external_out_sol, 4),
            "history_trusted": pnl_history_trusted,
            "first_snapshot_at": pnl_first_snapshot_iso,
            "_doc": "trading-only PnL excludes external transfers and ledger sweeps. history_trusted is False during first 24h of operation; ledger sweep falls back to anchor math until True.",
        },
        "wallet_floor_sol": floor,
        "wallet_floor_active": wallet_floor_active,
        "open_positions": open_positions,
        "fetched_at": _now_iso(),
        "_price_source": price_source,
    }


async def _wallet_sol_balance() -> Optional[float]:
    """v13.3 — hot wallet SOL balance in SOL. None on RPC failure (callers must
    fall back to quote-derived numbers, never fabricate)."""
    if PAPER_MODE:
        return float(_paper_wallet_load()["sol"])
    try:
        result = await helius_rpc("getBalance", [HOT_WALLET_ADDR, {"commitment": "confirmed"}])
        if isinstance(result, dict) and result.get("value") is not None:
            return int(result["value"]) / 1_000_000_000
    except Exception:
        pass
    return None


async def _wallet_token_raw(mint: str) -> tuple[float, int]:
    """v13.3 — (raw_amount, decimals) of `mint` held by the hot wallet. (0, 0) when
    absent or on failure — callers treat 0-delta as 'use the quote fallback'."""
    try:
        for b in await get_wallet_token_balances():
            if b.get("mint") == mint:
                return float(b.get("amount_raw") or 0), int(b.get("decimals") or 0)
    except Exception:
        pass
    return 0.0, 0


async def get_wallet_token_balances(address: str = None) -> list[dict]:
    """Get all SPL token balances of a wallet."""
    address = address or HOT_WALLET_ADDR
    if PAPER_MODE and address == HOT_WALLET_ADDR:
        return _paper_token_balances()
    # ── TOKEN-2022 FIX 2026-07-27 ───────────────────────────────────────────
    # This queried ONLY the legacy SPL Token program, so every Token-2022 mint
    # read as EXACTLY ZERO. Consequences, both live:
    #   1. position_wallet_reconcile_loop ghosted the bag on every check —
    #      "wallet: 0.0000" with a real position sitting in the wallet.
    #   2. WORSE: the full-exit hard gate treats _wallet_token_raw(mint) <= 0 as
    #      "confirmed empty" and closes the book as ghost_reconcile. On a
    #      Token-2022 bag that is ALWAYS true, so the safety gate would have
    #      closed real positions.
    # The agent named this in his 2026-07-26 patch as hardening item #1. Query BOTH
    # programs and merge. A wallet read that can't see half the token standards
    # is not a wallet read.
    _PROGRAMS = (
        "TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA",   # SPL Token (legacy)
        "TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb",   # Token-2022 (Token Extensions)
        # 2026-07-27: this constant was WRONG until today. It read
        # ...VEabAFSbm1N8VDsMHBHknNhP5qYq — identical for 17 chars, then garbage.
        # Helius answered every call with "unrecognized Token program id", so the
        # Token-2022 half of this wallet read had NEVER returned a single account
        # since the 2026-07-26 hardening that added it. The hardening looked done
        # and was not: the comment above says "a wallet read that can't see half
        # the token standards is not a wallet read", and that was the live state.
        # Verified against the official spl-token docs before changing.
        # It also burned 2 doomed RPC calls per wallet read, feeding the 429s.
    )
    accounts = []
    _seen_prog = []
    for _prog in _PROGRAMS:
        try:
            _r = await helius_rpc(
                "getTokenAccountsByOwner",
                [address, {"programId": _prog}, {"encoding": "jsonParsed"}],
            )
            if _r and isinstance(_r, dict):
                _vals = _r.get("value", []) or []
                accounts.extend(_vals)
                _seen_prog.append(f"{_prog[:4]}:{len(_vals)}")
        except Exception as _pe:
            _log(f"token balances: {_prog[:4]} query failed: {_pe!r}", prefix="wallet")
    if not accounts:
        return []
    balances = []
    for acc in accounts:
        try:
            info = ((acc.get("account") or {}).get("data") or {}).get("parsed") or {}
            inf = info.get("info") or {}
            mint = inf.get("mint")
            amount_raw = ((inf.get("tokenAmount") or {}).get("amount") or "0")
            decimals = ((inf.get("tokenAmount") or {}).get("decimals") or 0)
            ui_amount = ((inf.get("tokenAmount") or {}).get("uiAmount") or 0)
            if mint and float(amount_raw) > 0:
                balances.append({
                    "mint": mint,
                    "amount_raw": amount_raw,
                    "decimals": decimals,
                    "ui_amount": ui_amount,
                })
        except Exception:
            continue
    return balances


    return balances


