#               SPRINT 28.3 , TRACKING & MISS-ANALYSIS MODULES
# ═══════════════════════════════════════════════════════════════════════════
#
# These modules implement the architectural gaps the owner flagged:
#   - watchlist: every passed-filter token gets re-checked at 2h/24h boundaries
#   - trending track: top-10 boosted tokens tracked over time → 8h+ = hold candidate
#   - passed_filter log: feeds missed-runner autopsy
#   - skip log: feeds autoagent calibration (DEFER)
#   - shiller track: KOL outcomes + rug-pattern recognition for front-run defense
#   - dex_paid watch: socially-thin tokens monitored for boost events
#
# All state files use atomic write + idempotent updates (write-back the whole dict).
# ═══════════════════════════════════════════════════════════════════════════


# ─── watchlist ───────────────────────────────────────────────────────────────
def load_watchlist() -> dict:
    data = load_json_with_staleness(WATCHLIST_FILE, max_age_seconds=86400 * 7, default={}, alert_on_stale=False)
    if isinstance(data, dict):
        data.pop("_meta", None)
        return data
    return {}


def watchlist_add(mint: str, scan_data: dict) -> None:
    """
    Add a mint to the watchlist with its initial scan snapshot.
    Idempotent , if already present, refreshes last_seen_at but keeps scan_mcap.
    Frozen first-scan scan_price + scan_mcap persist when available.
    """
    wl = load_watchlist()
    now = _now_iso()
    _sp = _safe_num(
        scan_data.get("price_usd")
        if scan_data.get("price_usd") not in (None, "", 0, "0")
        else (scan_data.get("priceUsd") or scan_data.get("price") or scan_data.get("scan_price"))
    )
    _sm = _safe_num(
        scan_data.get("mcap")
        if scan_data.get("mcap") not in (None, "", 0, "0")
        else (scan_data.get("marketCap") or scan_data.get("scan_mcap")
              or scan_data.get("scan_mcap_usd") or scan_data.get("fdv"))
    )
    if mint in wl:
        wl[mint]["last_seen_at"] = now
        # don't overwrite scan_mcap or first_seen_at , those are the baseline
        # backfill frozen first-scan fields only when they were never stored
        if not _safe_num(wl[mint].get("scan_price")) and _sp:
            wl[mint]["scan_price"] = _sp
        if not _safe_num(wl[mint].get("scan_mcap_usd")) and _sm:
            wl[mint]["scan_mcap_usd"] = _sm
    else:
        wl[mint] = {
            "mint": mint,
            "ticker": scan_data.get("ticker"),
            "name": scan_data.get("name"),
            "scan_mcap_usd": _sm if _sm is not None else scan_data.get("mcap"),
            "scan_liq_usd": scan_data.get("liquidity_usd"),
            "scan_holder_count": scan_data.get("holder_count"),
            "first_seen_at": now,
            "first_seen_at_ts": _now_ts(),
            "last_seen_at": now,
            "last_recheck_at": None,
            "last_recheck_mcap": None,
            "peak_mcap_seen": _sm if _sm is not None else scan_data.get("mcap"),
            "runner_alerts_fired": 0,
            "edge_passed": scan_data.get("edge_passed", False),
            "scan_price": _sp,
        }
    # Auto-tag the potential tier on EVERY candidate, new or repeat. Repeat is the
    # important half: a mint already on the list from an earlier scan is exactly the
    # case where the baseline must stay frozen at the first sighting.
    try:
        _edge = scan_data.get("edge_filter") or {}
        if _edge:
            _potential_tag(mint, wl[mint], _edge, scan_data.get("pattern"),
                           source="auto_candidate")
    except Exception as _pte:
        _log(f"potential tag on add err: {_pte}")
    try:
        _save_json_atomic(WATCHLIST_FILE, wl)
    except Exception as e:
        _log(f"watchlist_add error: {e}")


# ════════════════════════════════════════════════════════════════════════════
# POTENTIAL_WATCH TIER (2026-08-08)
# ════════════════════════════════════════════════════════════════════════════
# The owner's order: tokens will not look pretty. 5/6 and 3/6 can still be buys, 6/6 is
# size-up, liq should not auto-fail, and even a 3/6 you SKIP should hit the
# watchlist so we can see how it performs.
#
# TOAD receipt: added to the watchlist at 10:22 with last_recheck_at NULL for
# hours while it did ~143x. The ignore lane refired at a $6.2M baseline instead of
# the $71.5k first scan, so the alert arrived after the only window that mattered.
#
# This tier is INTEL, never a buy. Nothing here fires a signal, sizes anything, or
# touches a capital knob.
POTENTIAL_RECHECK_MIN_NORMAL = 10
POTENTIAL_RECHECK_MIN_HIGH   = 5
POTENTIAL_EXPIRES_HOURS      = 12
POTENTIAL_GENERIC_CAP        = 80    # oldest-by-last_recheck per cycle


def _potential_should_tag(edge: dict, pattern: dict = None, ignore_sig: dict = None) -> tuple:
    """(should_tag, priority, why). Never tags through a hard safety kill."""
    edge = edge or {}
    pattern = pattern or {}
    credit = edge.get("credit_sum")
    if credit is None:
        # pre-graded-score packets: fall back to counting hard gates
        credit = sum(1 for g in (edge.get("hard_gates") or {}).values() if g.get("pass"))
    credit = float(credit or 0)

    # HARD SAFETY KILLS never get tagged, whatever the structure looks like.
    # A honeypot with beautiful volume is still a honeypot.
    rug = (edge.get("rug") or {}) if isinstance(edge.get("rug"), dict) else {}
    if rug.get("honeypot") or rug.get("mint_authority_active") or rug.get("freeze_authority_active"):
        return (False, "normal", "hard safety kill (honeypot/authority)")
    if (edge.get("deployer_rug_count") or 0) >= 3:
        return (False, "normal", "deployer 3+ rugs")

    vol_liq = 0.0
    try:
        vol_liq = float(str((edge.get("hard_gates") or {})
                            .get("vol_liq_ratio_6x", {}).get("value", "0")).rstrip("x"))
    except Exception:
        pass
    pconf = float(pattern.get("confidence") or 0)
    pcls = str(pattern.get("classification") or "").lower()
    family = any(k in pcls for k in ("twin_green", "staircase", "unbroken", "climb"))

    if credit >= 3:
        why = f"credit_sum {credit:.1f} >= 3"
    elif credit >= 2 and (vol_liq >= 6 or pconf >= 0.7 or family):
        why = f"credit_sum {credit:.1f} + (vol/liq {vol_liq:.1f}x, pattern {pconf:.2f} {pcls})"
    elif ignore_sig and (ignore_sig.get("would_have_bought_if") or "").strip():
        _wb = str(ignore_sig.get("would_have_bought_if")).lower()
        # A pure late-chase regret is not potential - it is hindsight. Tagging it
        # would fill the tier with tokens whose only merit is that they already ran.
        if any(k in _wb for k in ("too late", "late chase", "already ran", "missed it", "chased")):
            return (False, "normal", "would_have_bought_if is late-chase language")
        why = "agent ignore carried a would_have_bought_if"
    else:
        return (False, "normal", f"credit_sum {credit:.1f} below tag threshold")

    priority = "high" if (credit >= 5 or pconf >= 0.8) else "normal"
    return (True, priority, why)


def _potential_tag(mint: str, entry: dict, edge: dict, pattern: dict = None,
                   source: str = "auto_candidate", ignore_sig: dict = None) -> bool:
    """Attach/refresh the potential_watch tier on a watchlist entry, in place.

    BASELINE RULE (the TOAD fix): the baseline is the FIRST SCAN, forever. A later
    ignore may enrich decline_reason / would_buy_if but must NEVER move the
    baseline up - that is exactly how the ignored-runner lane ended up measuring
    2x from $6.2M instead of from the $71.5k where the desk first saw it.
    """
    try:
        ok, priority, why = _potential_should_tag(edge, pattern, ignore_sig)
        pw = entry.get("potential_watch") or {}
        if not ok and not pw:
            return False
        if not ok and pw:
            return False        # never downgrade an existing tier on a later look

        first_time = not pw
        if first_time:
            pw = {
                "tier": "potential",
                "tagged_at": _now_iso(),
                "tagged_at_ts": _now_ts(),
                "source": source,
                # FIRST SCAN, and never moved again.
                "baseline_mcap": entry.get("scan_mcap_usd"),
                "baseline_price": entry.get("scan_price"),
                "baseline_liq": entry.get("scan_liq_usd"),
                "baseline_edge_credit": (edge or {}).get("credit_sum"),
                "baseline_failed_gates": [k for k, g in ((edge or {}).get("hard_gates") or {}).items()
                                          if not g.get("pass")],
                "fired": {},
                "last_checked_ts": 0,
                "no_auto_buy": True,
                "_baseline_note": ("first scan snapshot, frozen. A later ignore enriches the "
                                   "reasoning but never moves this - measuring 2x from a late "
                                   "ignore price is how the only window gets missed."),
            }
        # these DO refresh on a later look
        pw["priority"] = priority
        pw["why_tagged"] = why
        pw["recheck_minutes"] = (POTENTIAL_RECHECK_MIN_HIGH if priority == "high"
                                 else POTENTIAL_RECHECK_MIN_NORMAL)
        pw["expires_hours"] = POTENTIAL_EXPIRES_HOURS
        pw["expires_at_ts"] = (pw.get("tagged_at_ts") or _now_ts()) + POTENTIAL_EXPIRES_HOURS * 3600
        if ignore_sig:
            pw["source"] = pw.get("source") or source
            if ignore_sig.get("reason"):
                pw["decline_reason"] = str(ignore_sig.get("reason"))[:400]
            if ignore_sig.get("would_have_bought_if"):
                pw["would_buy_if"] = str(ignore_sig.get("would_have_bought_if"))[:400]
        entry["potential_watch"] = pw
        if first_time:
            _log(f"[potential] tagged {_short_mint(mint)} ({priority}) - {why}", prefix="potential")
        return True
    except Exception as e:
        _log(f"[potential] tag err {_short_mint(mint)}: {e}", prefix="potential")
        return False


async def _potential_evaluate(mint: str, entry: dict, pair: dict) -> int:
    """Fire potential_watch_hit packets for newly-met triggers. Returns count fired.

    Every trigger measures against the FROZEN first-scan baseline, fires ONCE, and
    carries no_auto_buy. Nothing here submits a signal.
    """
    fired = 0
    try:
        pw = entry.get("potential_watch") or {}
        if not pw or not pair:
            return 0
        # 2026-10-15: an ignore/dismiss mute silences watch hits too; nothing is
        # marked fired, so a still-true trigger fires after the mute ends.
        if is_mint_dismissed(mint):
            return 0
        base_mcap = float(pw.get("baseline_mcap") or 0)
        base_liq = float(pw.get("baseline_liq") or 0)
        base_credit = float(pw.get("baseline_edge_credit") or 0)
        cur_mcap = float(pair.get("marketCap") or pair.get("fdv") or 0)
        cur_liq = float(((pair.get("liquidity") or {}) or {}).get("usd") or 0)
        pc = pair.get("priceChange") or {}
        h1 = float(pc.get("h1") or 0); h6 = float(pc.get("h6") or 0)
        already = pw.get("fired") or {}
        hits = []

        ratio = (cur_mcap / base_mcap) if base_mcap > 0 else 0
        if base_mcap > 0 and ratio >= 2 and "early_2x" not in already:
            hits.append(("early_2x", f"{ratio:.1f}x from the first-scan baseline"))
        if base_mcap > 0 and ratio >= 5 and "early_5x" not in already:
            hits.append(("early_5x", f"{ratio:.1f}x from the first-scan baseline"))
        if base_liq > 0 and cur_liq >= base_liq * 2 and "liq_doubled" not in already:
            hits.append(("liq_doubled", f"book thickened ${base_liq/1000:.1f}K -> ${cur_liq/1000:.1f}K"))
        if base_liq < 5000 <= cur_liq and "liq_fill_5k" not in already:
            hits.append(("liq_fill_5k", f"liq filled to ${cur_liq/1000:.1f}K from a thin base"))
        if h6 < 0 and h1 > 0 and "pullback_reclaim" not in already:
            hits.append(("pullback_reclaim", f"6h {h6:+.0f}% then 1h {h1:+.0f}% - non-chase second look"))

        # ── STRUCTURE-IMPROVEMENT TRIGGERS (2026-08-09) ─────────────────────
        # The five remaining triggers from the spec. Three are effectively free -
        # dex_paid/socials ride the recheck payload, and edge credit is a pure
        # recompute. The other three need an RPC holders call, so the re-enrich is
        # BOUNDED two ways: at most once every RE_ENRICH_MIN per mint, and ONLY
        # when the baseline actually flagged that lane as dirty.
        #
        # That second bound is the important one. "Did dev clean up" is a
        # meaningless question about a token whose dev was never the problem, and
        # asking it anyway would spend an RPC call per mint per cycle to learn
        # nothing. The trigger exists to tell you a KNOWN blocker cleared.
        RE_ENRICH_MIN = 30
        base_failed = set(pw.get("baseline_failed_gates") or [])
        _wb = (pw.get("would_buy_if") or "").lower()
        _dr = (pw.get("decline_reason") or "").lower()

        # social_pop - free, straight off the pair payload
        _info = (pair.get("info") or {}) if isinstance(pair.get("info"), dict) else {}
        _dex_paid = bool(_info.get("dex_paid") or pair.get("dex_paid"))
        _socials = _info.get("socials") or []
        _real_x = any(str((sc or {}).get("type", "")).lower() in ("twitter", "x")
                      for sc in _socials if isinstance(sc, dict))
        if (_dex_paid or _real_x) and "social_pop" not in already:
            if not pw.get("baseline_social"):
                hits.append(("social_pop",
                             f"catalyst lane woke up (dex_paid={_dex_paid}, x={_real_x})"))
        pw["baseline_social"] = pw.get("baseline_social") or bool(_dex_paid or _real_x)

        # edge_credit_up - a recompute, no network
        if "edge_credit_up" not in already and base_credit:
            try:
                _tok = {
                    "liquidity_usd": cur_liq, "mcap": cur_mcap,
                    "volume_24h": float(((pair.get("volume") or {}) or {}).get("h24") or 0),
                    "price_change_1h": h1,
                    "narrative": entry.get("narrative") or "",
                    "twitter_followers": entry.get("twitter_followers") or 0,
                    "x_account_age_days": entry.get("x_account_age_days"),
                    "x_dex_paid": _dex_paid,
                }
                _now_credit = float((compute_edge_filter(_tok) or {}).get("credit_sum") or 0)
                if _now_credit >= base_credit + 1.0 or _now_credit >= 5.0:
                    hits.append(("edge_credit_up",
                                 f"structure improved {base_credit:.1f} -> {_now_credit:.1f}"))
            except Exception:
                pass

        # dev_cleared / holders_ok / rug_cleared - need holders, so gate hard
        _dev_dirty = ("dev" in _wb or "dev" in _dr
                      or float(pw.get("baseline_dev_pct") or 0) > 15)
        _holders_dirty = ("holder" in _wb or "top10" in _wb
                          or "holder" in _dr or "top10" in _dr)
        _rug_dirty = ("rug" in _wb or "rug" in _dr or "clone" in _dr)
        _want = ((_dev_dirty and "dev_cleared" not in already)
                 or (_holders_dirty and "holders_ok" not in already)
                 or (_rug_dirty and "rug_cleared" not in already))
        _due = (_now_ts() - float(pw.get("last_enrich_ts") or 0)) >= RE_ENRICH_MIN * 60
        if _want and _due:
            pw["last_enrich_ts"] = _now_ts()
            try:
                _hold = await get_holders_top10(mint) or {}
                _devp = _hold.get("dev_holding_pct")
                _top10 = _hold.get("top10_pct")
                _hc = _hold.get("holder_count")
                if _dev_dirty and _devp is not None and _devp <= 15 and "dev_cleared" not in already:
                    hits.append(("dev_cleared", f"dev down to {_devp:.1f}%"))
                if (_holders_dirty and _hc and _top10 is not None
                        and _hc >= 200 and _top10 <= 40 and "holders_ok" not in already):
                    hits.append(("holders_ok",
                                 f"distribution improved - {_hc} holders, top10 {_top10:.1f}%"))
                if _rug_dirty and "rug_cleared" not in already:
                    _rc = await smart_rug_check(mint, _hold) or {}
                    if str(_rc.get("verdict") or "").lower() in ("clean", "pass"):
                        hits.append(("rug_cleared", "rug lane went clean on recheck"))
            except Exception as _ee:
                _log(f"[potential] re-enrich err {_short_mint(mint)}: {_ee}", prefix="potential")

        if not hits:
            return 0

        # CHASE GUARD: already 3x+ with no reclaim structure means the move happened
        # without us. Say so in the packet and refuse to lead with a market buy -
        # same spirit as opportunity_refire's anti-chase rule.
        chase = (ratio >= 3) and not any(h[0] == "pullback_reclaim" for h in hits)

        for trig, detail in hits:
            pkt = {
                "type": "potential_watch_hit",
                "lane": "queue",
                "priority": pw.get("priority", "normal"),
                "mint": mint,
                "ticker": entry.get("ticker"),
                "trigger_fired": trig,
                "chase_risk": chase,
                "no_auto_buy": True,
                "baseline": {"mcap": base_mcap, "liq": base_liq,
                             "edge_credit": base_credit,
                             "failed_gates": pw.get("baseline_failed_gates") or [],
                             "tagged_at": pw.get("tagged_at")},
                "now": {"mcap": cur_mcap, "liq": cur_liq,
                        "ratio_vs_baseline": round(ratio, 2),
                        "h1": h1, "h6": h6},
                "would_buy_if": pw.get("would_buy_if"),
                "decline_reason": pw.get("decline_reason"),
                "summary": (f"{entry.get('ticker') or _short_mint(mint)}: {trig} - {detail}. "
                            f"Not bought. Your call."),
                "_doctrine": (
                    "POTENTIAL WATCH, not a buy signal. You passed on this and it moved from "
                    "the price you first SAW it, not from where you declined it. Re-run the "
                    "dual-gate and the map fresh - the tag is a reason to look, never a reason "
                    "to buy." + (" CHASE RISK: already 3x+ with no reclaim structure - the move "
                                 "happened without us; watch or reclaim, do not lead with a "
                                 "market buy." if chase else "")),
                "decision_inputs": {
                    "binding": False,
                    "options": [
                        {"action_type": "fire_buy_signal",
                         "when_this_fits": "only if dual-gate + map still work AND not chase_risk"},
                        {"action_type": "watch_for", "when_this_fits": "extend with a tighter trigger"},
                        {"action_type": "ignore", "when_this_fits": "thesis still dead - log why"},
                        {"action_type": "log_lesson", "when_this_fits": "missed window / wrong baseline"},
                    ],
                },
            }
            try:
                write_inbox_packet_generic(
                    pkt, prefix=f"potential_watch_hit_{(entry.get('ticker') or mint[:6])}",
                    identifier=f"{mint[:8]}_{trig}")
                already[trig] = _now_iso()
                fired += 1
                _log(f"[potential] {trig} {_short_mint(mint)} - {detail}"
                     + (" [chase_risk]" if chase else ""), prefix="potential")
            except Exception as _pe:
                _log(f"[potential] packet err {_short_mint(mint)}: {_pe}", prefix="potential")
        pw["fired"] = already
        entry["potential_watch"] = pw
    except Exception as e:
        _log(f"[potential] eval err {_short_mint(mint)}: {e}", prefix="potential")
    return fired


def watchlist_remove(mint: str) -> None:
    wl = load_watchlist()
    if mint in wl:
        del wl[mint]
        try:
            _save_json_atomic(WATCHLIST_FILE, wl)
        except Exception:
            pass


def watchlist_prune_expired() -> int:
    """Drop watchlist entries older than WATCHLIST_TRACKING_HOURS. Returns count dropped."""
    wl = load_watchlist()
    cutoff_ts = _now_ts() - (WATCHLIST_TRACKING_HOURS * 3600)
    to_drop = [m for m, e in wl.items() if e.get("first_seen_at_ts", 0) < cutoff_ts]
    for m in to_drop:
        del wl[m]
    if to_drop:
        try:
            _save_json_atomic(WATCHLIST_FILE, wl)
        except Exception:
            pass
    return len(to_drop)


# ─── trending track ──────────────────────────────────────────────────────────
def load_trending_track() -> dict:
    data = load_json_with_staleness(TRENDING_TRACK_FILE, max_age_seconds=86400 * 7, default={}, alert_on_stale=False)
    if isinstance(data, dict):
        data.pop("_meta", None)
        return data
    return {}


def trending_track_record_appearance(mint: str, ticker: str, rank: int, scanned_at_ts: int) -> None:
    """
    Record a mint's appearance in the top-boosted list at a given rank.
    Each entry tracks: appearances list, total_hours_in_top_10, first/last seen.
    """
    tt = load_trending_track()
    
    if mint not in tt:
        tt[mint] = {
            "mint": mint,
            "ticker": ticker,
            "appearances": [],   # list of {ts, rank}
            "first_seen_ts": scanned_at_ts,
            "last_seen_ts": scanned_at_ts,
            "total_appearances": 0,
            "consecutive_top_10_hours": 0.0,
            "is_hold_candidate": False,
        }
    
    entry = tt[mint]
    try:  # v1.0.7 fix 6: a stale/mislabelled ticker self-heals from the base-side pair
        import v107_rules as _v107
        _v107.heal_ticker(entry, ticker)
    except Exception:
        pass
    entry["appearances"].append({"ts": scanned_at_ts, "rank": rank})
    entry["last_seen_ts"] = scanned_at_ts
    entry["total_appearances"] += 1
    
    # Cap appearances list at last 100 entries to bound file size
    if len(entry["appearances"]) > 100:
        entry["appearances"] = entry["appearances"][-100:]
    
    # Compute consecutive_top_10_hours: span between first appearance and now,
    # IF we've been appearing consistently (last 4 scans all in top 10).
    appearances = entry["appearances"]
    if len(appearances) >= 1:
        # time span from first to last
        span_hours = (entry["last_seen_ts"] - entry["first_seen_ts"]) / 3600.0
        # check we've been continuously surfacing , last 4 ticks all present
        # (a tick gap of >2.5h would suggest we dropped out and came back)
        is_continuous = True
        if len(appearances) >= 4:
            recent_4 = appearances[-4:]
            for i in range(len(recent_4) - 1):
                gap_h = (recent_4[i + 1]["ts"] - recent_4[i]["ts"]) / 3600.0
                if gap_h > 2.5:  # bigger than off-hours scan interval = dropped out
                    is_continuous = False
                    break
        
        if is_continuous:
            entry["consecutive_top_10_hours"] = round(span_hours, 2)
        else:
            # Reset: token dropped out then came back; restart the clock from latest re-entry
            entry["first_seen_ts"] = scanned_at_ts
            entry["consecutive_top_10_hours"] = 0.0
        
        # Set hold candidate flag (Sprint 32: tunable via meeting override)
        hold_threshold = get_override_sync("TRENDING_HOLD_THRESHOLD_HOURS", TRENDING_HOLD_THRESHOLD_HOURS)
        entry["is_hold_candidate"] = entry["consecutive_top_10_hours"] >= hold_threshold
        entry["hold_reason"] = "persistent_8h" if entry["is_hold_candidate"] else None
        try:  # v1.0.7 fix 1: top-3 for 1h+ is a candidate too (TREND_FAST)
            import v107_rules as _v107
            if not entry["is_hold_candidate"] and _v107.trend_fast(entry, scanned_at_ts):
                entry["is_hold_candidate"] = True
                entry["hold_reason"] = "top3_1h"
        except Exception:
            pass
    
    try:
        _save_json_atomic(TRENDING_TRACK_FILE, tt)
    except Exception as e:
        _log(f"trending_track write error: {e}")


def _stamp_trending_boost_board(mint: str, entry: dict = None) -> bool:
    """FIX 3 option A (2026-08-15): put the trending top-N onto the digest board.

    The trending scanner returns "tracked_only" for anything short of the 8h
    hold-candidate threshold, on the stated grounds that "digest has it". The
    digest did not have it - it is built from boosts+profiles on its own cadence
    and never learned a mint's trending rank or how long it had persisted.

    So the operator saw a board with no trending signal on it, the skill described
    candidates that were not being written, and "the scanner showed it" meant a row
    in scanned_mints.json rather than anything visible.

    This writes a `trending_boost_board` block onto the CURRENT digest packet:
    rank, consecutive hours, hold-candidate flag. No new packets, no per-token
    spam - the spec is explicit that restoring a full candidate every 15m is the
    wrong fix.

    Returns True when the board was updated.
    """
    try:
        _digest = _INBOX / "meme_sniper - dex_top_digest.json"
        if not _digest.exists():
            _hits = sorted(_INBOX.glob("meme_sniper - *dex_top_digest*.json"),
                           key=lambda p: p.stat().st_mtime, reverse=True)
            if not _hits:
                return False          # no live digest to stamp; nothing to do
            _digest = _hits[0]
        with open(_digest, encoding="utf-8") as f:
            pkt = json.load(f)
        _tt = load_trending_track()
        _e = entry if isinstance(entry, dict) else {}
        _tr = _tt.get(mint, {}) or {}
        board = pkt.setdefault("trending_boost_board", {
            "_doctrine": ("mints currently in the trending top-N. This is a BOARD, not a "
                          "candidate list: no 1+2+3 gate, no projection, no rug read. A row "
                          "here means 'trending right now', nothing more. Only an 8h "
                          "hold_candidate gets a full candidate packet."),
            "rows": {},
        })
        board["rows"][mint] = {
            "ticker": (_e.get("ticker") or _e.get("symbol") or _tr.get("ticker") or "?"),
            "rank": _e.get("rank") or _e.get("boost_rank"),
            "consecutive_top_10_hours": _tr.get("consecutive_top_10_hours"),
            "hold_candidate": bool(_tr.get("is_hold_candidate")),
            "mcap": _e.get("market_cap") or _e.get("mcap"),
            "seen_at": _now_iso(),
        }
        board["updated_at"] = _now_iso()
        board["count"] = len(board["rows"])
        _save_json_atomic(_digest, pkt)
        return True
    except Exception:
        return False


def _buys_paused_global() -> bool:
    """v1.0.7: TTL fallback respects a buy pause (BUYS_PAUSED override)."""
    try:
        return bool(get_override_sync("BUYS_PAUSED", False))
    except Exception:
        return False


def trending_is_hold_candidate(mint: str) -> bool:
    """Check if a mint has been trending in top 10 for 8h+ continuously."""
    tt = load_trending_track()
    entry = tt.get(mint, {})
    return bool(entry.get("is_hold_candidate"))


def trending_track_prune() -> int:
    """Drop trending_track entries that haven't appeared in 24h."""
    tt = load_trending_track()
    cutoff_ts = _now_ts() - 86400  # 24h
    to_drop = [m for m, e in tt.items() if e.get("last_seen_ts", 0) < cutoff_ts]
    for m in to_drop:
        del tt[m]
    if to_drop:
        try:
            _save_json_atomic(TRENDING_TRACK_FILE, tt)
        except Exception:
            pass
    return len(to_drop)


# ─── current meta (computed from trending_track narratives) ─────────────────
def load_current_meta() -> dict:
    """
    Read current_meta.json. Defaults to {"categories": [], "dominance": {}}
    when absent or stale.
    """
    data = load_json_with_staleness(CURRENT_META_FILE, max_age_seconds=3600, default={}, alert_on_stale=False)
    if not isinstance(data, dict):
        return {"categories": [], "dominance": {}, "updated_at": None}
    data.pop("_meta", None)
    return data


def compute_current_meta() -> dict:
    """
    Read trending_track.json + walk the corresponding inbox packets to compute
    what's currently the dominant narrative(s) on Solana.
    
    Algorithm:
      1. Load trending_track entries with consecutive_top_10_hours > 0
      2. For each, find the corresponding inbox packet
      3. Pull the packet's narrative.narrative field (animal/ai/political/food/war/etc.)
      4. Count occurrences
      5. A category becomes "the meta" if 2+ tokens share it (META_DOMINANCE_THRESHOLD)
      6. Return top META_MAX_CATEGORIES categories sorted by count
    
    Cheap operation , runs locally, no network calls. Refreshed every 30min by
    meta_refresh_loop.
    
    Returns:
      {
        "categories": ["animal", "ai"],         # the meta(s) right now
        "dominance": {"animal": 4, "ai": 3, "random": 1},  # full count
        "sample_size": 8,
        "updated_at": "<iso>",
        "_source": "trending_track.json"
      }
    """
    tt = load_trending_track()
    if not tt:
        return {"categories": [], "dominance": {}, "sample_size": 0, "updated_at": _now_iso(), "_source": "trending_track_empty"}
    
    category_counts: dict = {}
    sample_size = 0
    
    for mint, entry in tt.items():
        # Only count tokens with at least 2 trending appearances (not noise)
        if entry.get("total_appearances", 0) < 2:
            continue
        
        # Look up the inbox packet for this mint
        packet_path = _inbox_path_for_mint(mint)
        if not packet_path.exists():
            continue
        
        try:
            with open(packet_path, "r", encoding="utf-8") as f:
                packet = json.load(f)
            
            ctx = packet.get("context") or {}
            narrative_block = ctx.get("narrative_intelligence") or {}
            narrative = narrative_block.get("narrative")
            
            # Filter out failure-stub labels , they shouldn't pollute meta detection.
            # Sprint 28.7 broadened this from a hardcoded list to a "stub_*" prefix
            # check + the legacy values, so new failure modes added later get filtered
            # too. Also filters error _source values that accidentally land in narrative.
            FAILURE_NARRATIVES = {
                "ollama_parse_error", "ollama_unavailable", "unknown",
                "narrative_intel_failed", "grok_unavailable",
                "all_paths_failed", "all_paths_failed_grok_and_ollama",
            }
            if not narrative or narrative in FAILURE_NARRATIVES:
                continue
            # Also skip if narrative happens to match one of the _source error labels
            if str(narrative).lower().startswith(("grok+ollama_", "ollama+grok_", "stub_")):
                continue
            
            # Normalize: lowercase, strip
            cat = str(narrative).strip().lower()
            if not cat:
                continue
            
            category_counts[cat] = category_counts.get(cat, 0) + 1
            sample_size += 1
        except Exception:
            continue
    
    # Determine meta: categories with count >= threshold, sorted by count desc
    sorted_cats = sorted(category_counts.items(), key=lambda x: x[1], reverse=True)
    meta_cats = [cat for cat, count in sorted_cats if count >= META_DOMINANCE_THRESHOLD][:META_MAX_CATEGORIES]
    
    result = {
        "categories": meta_cats,
        "dominance": dict(sorted_cats),
        "sample_size": sample_size,
        "updated_at": _now_iso(),
        "updated_at_ts": _now_ts(),
        "_source": "trending_track.json",
        "_threshold": META_DOMINANCE_THRESHOLD,
    }
    
    try:
        _save_json_atomic(CURRENT_META_FILE, result)
    except Exception as e:
        _log(f"current_meta write error: {e}")
    
    try:
        compute_meta_shift()
    except Exception as e:
        _log(f"meta_shift write error: {e}")

    return result


def load_meta_shift() -> dict:
    """Type-share rollup. Absent or stale is empty, never a buy."""
    data = load_json_with_staleness(META_SHIFT_FILE, max_age_seconds=3600, default={}, alert_on_stale=False)
    if not isinstance(data, dict):
        return {"windows": {}, "shifts": [], "buy": False, "updated_at": None}
    data.pop("_meta", None)
    data["buy"] = False
    return data


def compute_meta_shift() -> dict:
    """
    Bucket trending mints into token types and roll 1h/4h/24h share.
    A shift is a type gaining 4h share, not one coin printing.
    Output: bot_logs/meta_shift.json. Never a buy signal.
    """
    from meta_tracker import atomic_write, classify, roll

    tt = load_trending_track() or {}
    prev = {}
    if META_SHIFT_FILE.exists():
        try:
            prev = json.loads(META_SHIFT_FILE.read_text(encoding="utf-8"))
        except Exception:
            prev = {}

    events = []
    for mint, entry in tt.items():
        if not isinstance(entry, dict):
            continue
        appearances = entry.get("appearances") or []
        ts = 0
        if appearances and isinstance(appearances[-1], dict):
            ts = float(appearances[-1].get("ts") or 0)
        ts = ts or float(entry.get("last_seen_ts") or 0)
        ticker = entry.get("ticker") or ""
        narrative = None
        volume = 0
        name = entry.get("name") or ""
        clone_of = entry.get("clone_of")
        packet_path = _inbox_path_for_mint(mint, ticker or None)
        if packet_path.exists():
            try:
                with open(packet_path, "r", encoding="utf-8") as f:
                    packet = json.load(f)
                ctx = packet.get("context") or {}
                narrative_block = ctx.get("narrative_intelligence") or {}
                narrative = narrative_block.get("narrative")
                name = name or packet.get("name") or ctx.get("name") or ""
                ticker = ticker or packet.get("ticker") or ""
                dex = ctx.get("dex_data") or {}
                volume = float(ctx.get("v1h") or dex.get("v1h") or dex.get("volume_1h") or 0)
                brand = ctx.get("brand_resolution") or {}
                clone_of = clone_of or brand.get("canonical_mint")
            except Exception:
                pass
        events.append({
            "mint": mint,
            "ts": ts,
            "ticker": ticker,
            "type": classify(narrative, ticker, name),
            "volume": volume,
            "clone_of": clone_of if clone_of and clone_of != mint else None,
        })

    result = roll(events, now=_now_ts(), prev=prev if isinstance(prev, dict) else None)
    result["buy"] = False
    result["operator_note"] = (
        "2026-10-09 owner: quantum meta may be the shift. "
        "types are quantum-born / qday-game / privacy-hedge / ticker-beta, not the word quantum."
    )
    try:
        atomic_write(META_SHIFT_FILE, result)
        with open(META_SHIFT_HISTORY_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps({
                "ts": result.get("updated_at"),
                "shifts": result.get("shifts"),
                "leaders_4h": (result.get("windows") or {}).get("4h", {}).get("leaders"),
                "sample_size": result.get("sample_size"),
            }) + "\n")
    except Exception as e:
        _log(f"meta_shift write error: {e}")
    return result


def is_token_meta_aligned(token_narrative: Optional[str]) -> bool:
    """
    Check if a token's narrative matches the current meta.
    Used by edge_filter to compute meta_alignment (unicorn combo input).
    """
    if not token_narrative:
        return False
    
    cat = str(token_narrative).strip().lower()
    if not cat or cat in ("unknown", "ollama_parse_error", "ollama_unavailable"):
        return False
    
    meta = load_current_meta()
    return cat in (meta.get("categories") or [])


# ─── deep_research dedup + cache (Sprint 28.4) ──────────────────────────────
def load_deep_research_dedup() -> dict:
    data = load_json_with_staleness(DEEP_RESEARCH_DEDUP_FILE, max_age_seconds=86400 * 7, default={}, alert_on_stale=False)
    if isinstance(data, dict):
        data.pop("_meta", None)
        return data
    return {}


# ── FIX 2 (2026-08-16): THE DEDUP WAS A JAMMED MAG ──────────────────────────
# The doctrine is two-step: fire ["x","web"], read it, then fire
# ["chart_vision","vibe_check"] on the ones worth the spend. The dedup was keyed
# on MINT ALONE, so step two came back `ignored_dedup` for thirty minutes. The
# retry rule ("scopes_failed=['x'], retry x only") was unreachable for the same
# reason, and cache could not rescue either case because stubs are not cached.
#
# So the mechanism built to stop wasting research was the mechanism preventing
# the research from ever being finished. Per-scope timestamps make the grain
# match the doctrine: a scope you already asked for is blocked, a scope you have
# not asked for goes through.
#
# The file's old shape was {mint: {...}} and the new one is
# {mint: {"scopes": {scope: {...}}}}. Old rows are read as "all scopes locked at
# that timestamp" so a live file mid-upgrade degrades to exactly the old
# behaviour instead of throwing.
def _dedup_scope_entries(entry) -> dict:
    """Normalise a dedup row to {scope: {...}}, tolerating the pre-FIX-2 shape."""
    if not isinstance(entry, dict):
        return {}
    scoped = entry.get("scopes")
    if isinstance(scoped, dict):
        return scoped
    # Legacy row: one timestamp covering whatever scope list it recorded.
    ts = entry.get("requested_at_ts", 0)
    legacy_scopes = scoped if isinstance(scoped, list) else []
    return {
        s: {"requested_at_ts": ts, "request_id": entry.get("request_id"), "_legacy": True}
        for s in legacy_scopes
    }


def deep_research_check_dedup(mint: str, scopes: Optional[list] = None) -> Optional[float]:
    """Minutes since these scopes were last requested, or None if they are free.

    Returns a number ONLY when EVERY requested scope is still inside the window -
    that is the case where the caller would learn nothing new. If even one scope
    is unasked, the request proceeds and `deep_research_unlocked_scopes` says
    which ones to actually send.
    """
    entries = _dedup_scope_entries(load_deep_research_dedup().get(mint))
    if not entries:
        return None
    want = [s for s in (scopes or list(entries.keys()))]
    if not want:
        return None

    now = _now_ts()
    ages = []
    for s in want:
        e = entries.get(s)
        ts = e.get("requested_at_ts", 0) if isinstance(e, dict) else 0
        if not ts:
            return None                      # this scope was never asked - go
        age = (now - ts) / 60.0
        if age >= DEEP_RESEARCH_DEDUP_MINUTES:
            return None                      # this scope aged out - go
        ages.append(age)
    return min(ages) if ages else None


def deep_research_unlocked_scopes(mint: str, scopes: list) -> list:
    """The subset of `scopes` not currently inside the dedup window."""
    entries = _dedup_scope_entries(load_deep_research_dedup().get(mint))
    now = _now_ts()
    out = []
    for s in scopes:
        e = entries.get(s)
        ts = e.get("requested_at_ts", 0) if isinstance(e, dict) else 0
        if not ts or (now - ts) / 60.0 >= DEEP_RESEARCH_DEDUP_MINUTES:
            out.append(s)
    return out


def deep_research_record_dedup(mint: str, scopes: list[str], request_id: str) -> None:
    """Record that these scopes were just fired for this mint."""
    dedup = load_deep_research_dedup()
    row = dedup.get(mint)
    entries = _dedup_scope_entries(row)
    now_ts, now_iso = _now_ts(), _now_iso()
    for s in scopes:
        entries[s] = {
            "request_id": request_id,
            "requested_at": now_iso,
            "requested_at_ts": now_ts,
        }
    dedup[mint] = {
        "request_id": request_id,
        "requested_at": now_iso,
        "requested_at_ts": now_ts,
        "scopes": entries,
    }
    
    # Prune entries older than 1 day to keep file bounded
    cutoff_ts = _now_ts() - 86400
    dedup = {m: e for m, e in dedup.items() if isinstance(e, dict) and e.get("requested_at_ts", 0) >= cutoff_ts}
    
    try:
        _save_json_atomic(DEEP_RESEARCH_DEDUP_FILE, dedup)
    except Exception as e:
        _log(f"deep_research dedup write error: {e}")


def deep_research_release_dedup(mint: str, scopes: list, why: str = "stub") -> None:
    """FIX 2 (2026-08-16): a stub is not an answer, so it must not hold the lock.

    A stub means the research responder has no handler yet: no data was fetched, nothing was
    cached (the apply path skips caching stubs on purpose), and nothing was
    learned. Holding the mint for thirty minutes after one bought the agent a window
    in which he could not even re-ask the question. Same for a scope that came
    back in `scopes_failed`.

    Releasing the exact scopes that produced nothing leaves every scope that DID
    produce something still locked.
    """
    try:
        dedup = load_deep_research_dedup()
        row = dedup.get(mint)
        entries = _dedup_scope_entries(row)
        if not entries:
            return
        freed = [s for s in scopes if s in entries]
        if not freed:
            return
        for s in freed:
            entries.pop(s, None)
        if entries:
            dedup[mint] = {**(row if isinstance(row, dict) else {}), "scopes": entries}
        else:
            dedup.pop(mint, None)
        _save_json_atomic(DEEP_RESEARCH_DEDUP_FILE, dedup)
        _log(f"deep_research: released dedup on {_short_mint(mint)} scopes={freed} "
             f"({why} produced nothing, so it does not get to hold the lock)", prefix="dr")
    except Exception as e:
        _log(f"deep_research dedup release error: {e}", prefix="dr")


def load_deep_research_cache() -> dict:
    data = load_json_with_staleness(DEEP_RESEARCH_CACHE_FILE, max_age_seconds=86400 * 30, default={}, alert_on_stale=False)
    if isinstance(data, dict):
        data.pop("_meta", None)
        return data
    return {}


def deep_research_cache_get(mint: str, scope: str) -> Optional[dict]:
    """
    Get cached research result for a mint + scope. Returns None if absent or stale.
    
    TTL by scope:
      - x:           6h
      - web:         30min
      - chart_vision: 5min
      - vibe_check:  7 days
    """
    cache = load_deep_research_cache()
    entry = cache.get(mint)
    if not isinstance(entry, dict):
        return None
    
    scope_data = entry.get(scope)
    if not isinstance(scope_data, dict):
        return None
    
    cached_at_ts = scope_data.get("_cached_at_ts", 0)
    if not cached_at_ts:
        return None
    
    ttl_map = {
        "x": DEEP_RESEARCH_CACHE_TTL_X_S,
        "web": DEEP_RESEARCH_CACHE_TTL_WEB_S,
        "chart_vision": DEEP_RESEARCH_CACHE_TTL_VISION_S,
        "vibe_check": DEEP_RESEARCH_CACHE_TTL_VIBE_S,
    }
    ttl = ttl_map.get(scope, 3600)
    
    if (_now_ts() - cached_at_ts) > ttl:
        return None  # stale
    
    return scope_data


def deep_research_cache_set(mint: str, scope: str, data: dict) -> None:
    """Cache a research result for a mint + scope."""
    cache = load_deep_research_cache()
    if mint not in cache:
        cache[mint] = {}
    
    cache[mint][scope] = {
        **data,
        "_cached_at": _now_iso(),
        "_cached_at_ts": _now_ts(),
    }
    
    # Bound the cache: keep only last 200 mints (newest by any cached_at_ts)
    if len(cache) > 200:
        all_mints = list(cache.items())
        # Sort by most-recent any-scope cache time
        all_mints.sort(
            key=lambda x: max(
                (s.get("_cached_at_ts", 0) for s in x[1].values() if isinstance(s, dict)),
                default=0
            ),
            reverse=True,
        )
        cache = dict(all_mints[:200])
    
    try:
        _save_json_atomic(DEEP_RESEARCH_CACHE_FILE, cache)
    except Exception as e:
        _log(f"deep_research cache write error: {e}")


# ─── passed_filter log (feeds missed-runner autopsy) ────────────────────────
def passed_filter_record(packet: dict) -> None:
    """
    Append a passed-filter entry. Used by missed-runner autopsy to find
    tokens that ran 2x+ but the agent never traded.
    
    Stored as JSONL , one line per entry.
    """
    ctx = packet.get("context") or {}
    dex_data = ctx.get("dex_data") or {}
    entry = {
        "mint": ctx.get("mint"),
        "ticker": ctx.get("ticker"),
        "scan_mcap": dex_data.get("mcap"),
        "scan_liq": dex_data.get("liquidity_usd"),
        "scan_at": ctx.get("scanned_at"),
        "scan_at_ts": _now_ts(),
        "edge_passed": (ctx.get("edge_filter") or {}).get("passes_full_filter"),
        "edge_verdict": (ctx.get("edge_filter") or {}).get("owner_edge_verdict"),  # Sprint 45+: per-gate funnel for tune invitation
        "packet_id": packet.get("id"),
    }
    try:
        _append_jsonl(PASSED_FILTER_LOG_FILE, entry)
    except Exception as e:
        _log(f"passed_filter log error: {e}")


def passed_filter_load_recent(lookback_hours: int = 48) -> list:
    """Load passed_filter entries from the last N hours."""
    if not PASSED_FILTER_LOG_FILE.exists():
        return []
    cutoff_ts = _now_ts() - (lookback_hours * 3600)
    entries = []
    try:
        with open(PASSED_FILTER_LOG_FILE, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    e = json.loads(line)
                    if e.get("scan_at_ts", 0) >= cutoff_ts:
                        entries.append(e)
                except json.JSONDecodeError:
                    continue
    except Exception as e:
        _log(f"passed_filter read error: {e}")
    return entries


