# ─── shiller track (rug pattern recognition) ─────────────────────────────────
def load_shiller_track() -> dict:
    data = load_json_with_staleness(SHILLER_TRACK_FILE, max_age_seconds=86400 * 365, default={}, alert_on_stale=False)
    if isinstance(data, dict):
        data.pop("_meta", None)
        return data
    return {}


def shiller_track_get(handle: str) -> dict:
    """Get shiller's full track record. Returns empty dict if unknown."""
    if not handle:
        return {}
    handle = handle.lstrip("@").lower()
    track = load_shiller_track()
    return track.get(handle, {})


def load_shiller_pending() -> dict:
    """Pending shills awaiting outcome resolution."""
    data = load_json_with_staleness(SHILLER_PENDING_FILE, max_age_seconds=86400 * 30, default={}, alert_on_stale=False)
    if isinstance(data, dict):
        data.pop("_meta", None)
        return data
    return {}


def shiller_pending_record(mint: str, shillers: list[str], shill_at_ts: int = None) -> None:
    # v14.2: every observed promoter also lands in the unified ranking log.
    try:
        for _h in shillers or []:
            record_promoter_mention(_h, mint, source="shiller_observed", at_ts=shill_at_ts)
    except Exception:
        pass
    """
    Record observed shillers for a mint. Resolved later when mint hits autopsy.
    
    shillers: list of X handles (@user) seen shilling this token
    """
    if not shillers:
        return
    shill_at_ts = shill_at_ts or _now_ts()
    pending = load_shiller_pending()
    
    if mint not in pending:
        pending[mint] = {
            "mint": mint,
            "shillers": [],
            "shill_at_ts": shill_at_ts,
            "first_recorded_at": _now_iso(),
        }
    
    # Merge in new shillers (deduped)
    existing_handles = {s.lstrip("@").lower() for s in pending[mint]["shillers"]}
    for s in shillers:
        h = s.lstrip("@").lower()
        if h and h not in existing_handles:
            pending[mint]["shillers"].append(h)
            existing_handles.add(h)
    
    try:
        _save_json_atomic(SHILLER_PENDING_FILE, pending)
    except Exception as e:
        _log(f"shiller_pending write error: {e}")


def shiller_resolve_outcome(mint: str, pnl_pct: float, time_to_peak_min: int = None,
                             time_peak_to_dump_min: int = None, dump_severity_pct: float = None) -> None:
    """
    When a token closes (autopsy), resolve outcomes back to all shillers tagged
    against that mint. Updates shiller_track with each shiller's accumulated history.
    
    Auto-update only , no tier mutations (those go to kol_list_proposals.json).
    """
    pending = load_shiller_pending()
    if mint not in pending:
        return  # no shillers were tracked for this mint
    
    entry = pending[mint]
    shillers = entry.get("shillers", [])
    shill_at_ts = entry.get("shill_at_ts") or _now_ts()
    
    if not shillers:
        return
    
    track = load_shiller_track()
    
    # Determine outcome category
    if pnl_pct < -50:
        outcome_label = "rug"
    elif pnl_pct > 50:
        outcome_label = "win"
    else:
        outcome_label = "neutral"
    
    for handle in shillers:
        h = handle.lstrip("@").lower()
        if not h:
            continue
        
        if h not in track:
            track[h] = {
                "handle": h,
                "shills_observed": [],
                "rug_count": 0,
                "win_count": 0,
                "neutral_count": 0,
                "rug_rate": 0.0,
                "rug_pattern": {},
                "first_seen": _now_iso(),
                "last_updated": _now_iso(),
            }
        
        s = track[h]
        s["shills_observed"].append({
            "mint": mint,
            "shilled_at_ts": shill_at_ts,
            "outcome": outcome_label,
            "pnl_pct": round(pnl_pct, 1),
            "time_to_peak_min": time_to_peak_min,
            "time_peak_to_dump_min": time_peak_to_dump_min,
            "dump_severity_pct": dump_severity_pct,
        })
        
        # Cap observation list at last 50 to bound file size
        if len(s["shills_observed"]) > 50:
            s["shills_observed"] = s["shills_observed"][-50:]
        
        if outcome_label == "rug":
            s["rug_count"] += 1
        elif outcome_label == "win":
            s["win_count"] += 1
        else:
            s["neutral_count"] += 1
        
        total = s["rug_count"] + s["win_count"] + s["neutral_count"]
        s["rug_rate"] = round(s["rug_count"] / total, 3) if total > 0 else 0.0
        s["last_updated"] = _now_iso()
        
        # Compute rug_pattern from rug-tagged observations
        rug_obs = [o for o in s["shills_observed"] if o.get("outcome") == "rug"]
        if len(rug_obs) >= 3:
            ttps = [o.get("time_to_peak_min") for o in rug_obs if o.get("time_to_peak_min")]
            tpds = [o.get("time_peak_to_dump_min") for o in rug_obs if o.get("time_peak_to_dump_min")]
            dsps = [o.get("dump_severity_pct") for o in rug_obs if o.get("dump_severity_pct") is not None]
            
            s["rug_pattern"] = {
                "sample_size": len(rug_obs),
                "typical_shill_to_peak_min": int(sum(ttps) / len(ttps)) if ttps else None,
                "typical_peak_to_dump_min": int(sum(tpds) / len(tpds)) if tpds else None,
                "typical_dump_severity_pct": round(sum(dsps) / len(dsps), 1) if dsps else None,
            }
    
    # Save track + remove pending entry
    try:
        _save_json_atomic(SHILLER_TRACK_FILE, track)
    except Exception as e:
        _log(f"shiller_track write error: {e}")
    
    del pending[mint]
    try:
        _save_json_atomic(SHILLER_PENDING_FILE, pending)
    except Exception:
        pass


# ─── dex_paid watch (socially-thin tokens) ───────────────────────────────────
def load_dex_paid_watch() -> dict:
    data = load_json_with_staleness(DEX_PAID_WATCH_FILE, max_age_seconds=86400, default={}, alert_on_stale=False)
    if isinstance(data, dict):
        data.pop("_meta", None)
        return data
    return {}


def dex_paid_watch_add(mint: str, scan_data: dict) -> None:
    """
    Add a socially-thin mint to the dex_paid watch list.
    Background loop checks if this mint ever gets dex_paid OR socials populate.
    """
    watch = load_dex_paid_watch()
    if mint in watch:
        return  # already tracked
    
    watch[mint] = {
        "mint": mint,
        "ticker": scan_data.get("ticker"),
        "added_at": _now_iso(),
        "added_at_ts": _now_ts(),
        "checks": 0,
        "last_check_at": None,
        "fired_event": False,
    }
    try:
        _save_json_atomic(DEX_PAID_WATCH_FILE, watch)
    except Exception:
        pass


def dex_paid_watch_remove(mint: str) -> None:
    watch = load_dex_paid_watch()
    if mint in watch:
        del watch[mint]
        try:
            _save_json_atomic(DEX_PAID_WATCH_FILE, watch)
        except Exception:
            pass


def dex_paid_watch_prune() -> int:
    """Drop dex_paid_watch entries older than DEX_PAID_WATCH_HOURS."""
    watch = load_dex_paid_watch()
    cutoff_ts = _now_ts() - (DEX_PAID_WATCH_HOURS * 3600)
    to_drop = [m for m, e in watch.items() if e.get("added_at_ts", 0) < cutoff_ts]
    for m in to_drop:
        del watch[m]
    if to_drop:
        try:
            _save_json_atomic(DEX_PAID_WATCH_FILE, watch)
        except Exception:
            pass
    return len(to_drop)


# ─── mint-level enrichment lock (prevent dupe between scanner + trending) ────
_MINT_ENRICHMENT_LOCKS: dict[str, asyncio.Lock] = {}
_MINT_LOCK_GUARD = asyncio.Lock()


async def acquire_mint_lock(mint: str) -> asyncio.Lock:
    """
    Get-or-create a lock for a specific mint. Used to prevent main scanner +
    trending scanner from both enriching the same mint simultaneously.
    """
    async with _MINT_LOCK_GUARD:
        lock = _MINT_ENRICHMENT_LOCKS.get(mint)
        if lock is None:
            lock = asyncio.Lock()
            _MINT_ENRICHMENT_LOCKS[mint] = lock
            # Garbage-collect old locks if dict grows too big
            if len(_MINT_ENRICHMENT_LOCKS) > 500:
                # Drop unlocked entries (they're idle)
                free = [m for m, l in _MINT_ENRICHMENT_LOCKS.items() if not l.locked()]
                for m in free[:200]:
                    _MINT_ENRICHMENT_LOCKS.pop(m, None)
        return lock


# ═══════════════════════════════════════════════════════════════════════════
#                          STATE MANAGEMENT
# ═══════════════════════════════════════════════════════════════════════════

# ─── Sprint 53: THE HOLD SYSTEM (conviction holds + living doc) ───
def _safe_num(v):
    try:
        return float(v) if v is not None else None
    except (TypeError, ValueError):
        return None


# ─── Sprint 53: DISCOVERY LEDGER + NEVER_SEEN AUTOPSY (the agent's #1 + #3) ───
# THE PROBLEM: the missed_runner observer only watches mints we ALREADY SCANNED and
# declined. A token that never entered the scan set at all — a pure discovery miss,
# the $febu class — can never be autopsied, because it has no scan_mcap to compare
# against. So the system can only learn "my filters were wrong"; it can NEVER learn
# "my discovery was blind." That's the deeper failure, and it's invisible by design.
#
# THE FIX: keep a ledger of every mint we've EVER seen (scanned, skipped, filtered —
# doesn't matter, we SAW it). Then sample external runners (trending/boosted). Any
# runner that is NOT in the ledger is a pure discovery miss — we never even looked at
# it. Autopsy THOSE. That's how you train discovery, not just filter tuning.

def load_scanned_mints() -> dict:
    return load_json_with_staleness(SCANNED_MINTS_FILE, max_age_seconds=999999,
                                    default={}, alert_on_stale=False) or {}


def record_seen_mint(mint: str, source: str, ticker: str = None, mcap: float = None) -> None:
    """Record that we SAW this mint — regardless of what we then did with it (scanned,
    filtered, skipped, declined). This is the discovery ledger: the set of everything
    that ever entered our field of view. Anything NOT in here that later runs is a
    pure discovery miss."""
    try:
        seen = load_scanned_mints()
        if mint in seen:
            e = seen[mint]
            e["last_seen"] = _now_iso()
            e["seen_count"] = e.get("seen_count", 1) + 1
            if mcap:
                e["last_mcap"] = mcap
        else:
            seen[mint] = {
                "mint": mint, "ticker": ticker, "source": source,
                "first_seen": _now_iso(), "first_seen_ts": _now_ts(),
                "last_seen": _now_iso(), "seen_count": 1,
                "first_mcap": mcap, "last_mcap": mcap,
            }
        # keep it bounded — 14 days of discovery memory is plenty
        if len(seen) > 5000:
            cutoff = _now_ts() - (14 * 86400)
            seen = {k: v for k, v in seen.items()
                    if (v.get("first_seen_ts") or 0) >= cutoff}
        _save_json_atomic(SCANNED_MINTS_FILE, seen)
    except Exception as e:
        _log(f"record_seen_mint err: {e}", prefix="discovery")


def load_never_seen() -> dict:
    return load_json_with_staleness(NEVER_SEEN_FILE, max_age_seconds=999999,
                                    default={}, alert_on_stale=False) or {}


async def _write_never_seen_autopsy(mint: str, pair: dict, why: dict) -> None:
    """Write a NEVER_SEEN autopsy to the agent's inbox. This is a DIFFERENT class of
    miss from a missed_runner: we didn't decline this token, we never SAW it. The
    question isn't 'why did my filters reject it' — it's 'why was my discovery blind
    to it, and what lane would have caught it?'"""
    ticker = (pair.get("baseToken") or {}).get("symbol") or "?"
    mcap = _safe_num(pair.get("marketCap") or pair.get("fdv")) or 0
    liq = _safe_num((pair.get("liquidity") or {}).get("usd")) or 0
    vol = _safe_num((pair.get("volume") or {}).get("h24")) or 0
    created = pair.get("pairCreatedAt")
    age_h = ((_now_ts() * 1000 - created) / 3_600_000) if created else None

    packet = {
        "type": "never_seen_autopsy",
        "_doctrine": (
            "A PURE DISCOVERY MISS. This token ran and we never scanned it — it never "
            "entered our field of view at all. This is NOT a filter-tuning lesson (we "
            "didn't reject it, we never saw it). The question is: WHAT LANE WOULD HAVE "
            "CAUGHT IT? Was it never bonded? Never boosted? Did it come from a source we "
            "don't poll? Was it a branded/midcap token that our early-band discovery "
            "structurally cannot see? Answer that, and you fix discovery — which is a "
            "bigger win than any filter tweak, because a filter can only reject what "
            "discovery surfaces."
        ),
        "mint": mint,
        "ticker": ticker,
        "written_at": _now_iso(),
        "token_now": {
            "mcap": mcap, "liquidity": liq, "volume_24h": vol,
            "age_hours": round(age_h, 1) if age_h else None,
            "price_usd": pair.get("priceUsd"),
            "chart": f"https://dexscreener.com/solana/{mint}",
        },
        "why_we_missed_it": why,
        # Sprint 54 — RE-SCAN IT NOW. For a never_seen we have NO scan data at all, so
        # the recheck is the ONLY way to learn anything from it. Run every check we have
        # against the token as it stands, and ask the two questions that matter: what is
        # it about this token that our discovery could not see — and is there still an
        # entry here? A higher mcap does not disqualify it. If we were blind to something
        # real, the real thing is probably still there.
        "recheck": await _missed_runner_recheck(mint, {}, pair),
        "questions_for_agent": [
            "What discovery lane would have surfaced this token BEFORE it ran?",
            "Was it in a band our scanner structurally cannot see (branded/midcap)?",
            "Is this a source gap (not bonded, not boosted) or a timing gap (we scan too slowly)?",
            "Is there a same-ticker/clone problem — did we scan a LOOKALIKE instead of this one?",
            "What ONE change to discovery would have caught it? (be specific, not 'scan more')",
        ],
    }
    try:
        write_inbox_packet_generic(packet, prefix="never_seen", identifier=mint[:8])
        append_miss_book("never_seen_autopsy", mint, {"ticker": ticker, "mcap": mcap})
        _log(f"NEVER_SEEN autopsy: {ticker} ({_short_mint(mint)}) mcap=${mcap:,.0f} "
             f"— we never scanned this at all", prefix="discovery")
    except Exception as e:
        _log(f"never_seen autopsy write err: {e}", prefix="discovery")


# ── CANONICAL STABILITY (2026-10-15, owner-approved) ─────────────────────────
# The canonical label flipped between rebuilds of the SAME card (NIHILISM: clone at
# 01:13, canonical at 01:30) because the DEX search returns a different slice of a
# 20+ clone flood each time and the score moves with the tape. Now:
#   - deterministic order: score, then earliest pair creation, then deeper liquidity,
#     then mint (a total order - equal inputs give the same answer every time);
#   - hysteresis: the held canonical for a ticker stays unless a challenger beats it
#     by BRAND_CANON_HYSTERESIS points;
#   - a held canonical that just dropped out of one search stays held for
#     BRAND_CANON_STICKY_H hours of absence.
# Persisted per ticker in bot_logs/brand_canonical.json (pruned after 7d / 5000).
_BRAND_CANON_FILE = _BOT_LOGS / "brand_canonical.json"
BRAND_CANON_HYSTERESIS = float(_envv("BRAND_CANON_HYSTERESIS", "10"))
BRAND_CANON_STICKY_H = float(_envv("BRAND_CANON_STICKY_H", "6"))


def _brand_rank_key(score_fn):
    def _k(c):
        return (-round(score_fn(c), 1), c.get("pair_created_at") or float("inf"),
                -(c.get("liquidity_usd") or 0), str(c.get("mint") or ""))
    return _k


def _brand_canon_load() -> dict:
    try:
        if _BRAND_CANON_FILE.exists():
            d = json.loads(_BRAND_CANON_FILE.read_text(encoding="utf-8"))
            if isinstance(d, dict):
                d.pop("_meta", None)
                return d
    except Exception:
        pass
    return {}


def _brand_canon_stable(tl: str, ranked: list, score_fn) -> dict:
    top = ranked[0]
    if not tl:
        return top
    now = _now_ts()
    store = _brand_canon_load()
    prev = store.get(tl) if isinstance(store.get(tl), dict) else {}
    chosen, why = top, "top"
    if prev.get("mint") and prev["mint"] != top["mint"]:
        held = next((c for c in ranked if c.get("mint") == prev["mint"]), None)
        if held is not None:
            if score_fn(top) - score_fn(held) < BRAND_CANON_HYSTERESIS:
                chosen, why = held, "held_hysteresis"
        elif now - float(prev.get("seen_ts") or 0) < BRAND_CANON_STICKY_H * 3600:
            chosen = {"mint": prev["mint"], "symbol": prev.get("symbol"),
                      "exact_ticker_match": True,
                      "pair_created_at": prev.get("pair_created_at"),
                      "liquidity_usd": prev.get("liquidity_usd") or 0,
                      "volume_24h": prev.get("volume_24h") or 0,
                      "mcap": prev.get("mcap") or 0, "txns_24h": 0,
                      "_from_memory": True}
            why = "held_absent_from_search"
    chosen["_canon_why"] = why
    try:
        rec = dict(prev) if prev.get("mint") == chosen["mint"] else {
            "since": now, "switched_from": prev.get("mint")}
        rec["mint"] = chosen["mint"]
        rec["why"] = why
        if not chosen.get("_from_memory"):
            rec.update({"symbol": chosen.get("symbol"),
                        "pair_created_at": chosen.get("pair_created_at"),
                        "liquidity_usd": chosen.get("liquidity_usd"),
                        "volume_24h": chosen.get("volume_24h"),
                        "mcap": chosen.get("mcap"), "seen_ts": now})
        store[tl] = rec
        cut = now - 7 * 86400
        store = {k: v for k, v in store.items()
                 if isinstance(v, dict) and float(v.get("seen_ts") or v.get("since") or 0) > cut}
        if len(store) > 5000:
            store = dict(sorted(store.items(),
                                key=lambda kv: -float(kv[1].get("seen_ts") or 0))[:5000])
        _save_json_atomic(_BRAND_CANON_FILE, store)
    except Exception:
        pass
    return chosen


# ── CLONE COLLAPSE (2026-10-15, owner-approved) ──────────────────────────────
# One card per ticker cluster. A non-canonical clone with dead social never gets
# its own inbox card; a non-canonical clone with live social folds into the
# cluster's existing card (context.clone_fold). Exempt: the narrative vehicle and
# runner_alert / dex_paid_event surfaces. Nothing is deleted: every suppressed or
# folded clone is a row in bot_logs/clone_suppressed.jsonl for the autopsy.
CLONE_CLUSTER_WINDOW_S = float(_envv("CLONE_CLUSTER_WINDOW_S", "7200"))
_CLONE_SUPPRESSED_FILE = _BOT_LOGS / "clone_suppressed.jsonl"
_CLONE_CLUSTER_CARD: dict = {}      # ticker -> {"path": str, "mint": str, "ts": float}
_CLONE_SUPPRESS_COUNTS: dict = {}   # ticker -> count since boot


# ── CLONE RUNNER (2026-10-15, owner-approved) ─────────────────────────────────
# The canonical (OG) pick is unchanged. A non-canonical clone that CLEARLY outpaces
# the canonical becomes a "runner": volume >= RUNNER_VOL_RATIO x the canonical's
# (1h volume when both sides have it, else 24h), liquidity above the canonical's,
# held for RUNNER_SUSTAIN_MIN minutes, plus a clean smart_rug_check and live social
# (bullish/mixed, the clone gate's social_vibe). A runner is exempt from clone
# suppression and gets its own "Clone Running" card. No buy bypass: every normal
# filter and safety rule still applies and the agent decides.
CLONE_RUNNER_ENABLED = _envv("CLONE_RUNNER_ENABLED", "on").strip().lower() in ("on", "true", "1", "yes")
RUNNER_VOL_RATIO = float(_envv("RUNNER_VOL_RATIO", "3"))
RUNNER_SUSTAIN_MIN = float(_envv("RUNNER_SUSTAIN_MIN", "60"))
RUNNER_HIT_PCT = 50.0          # outcome: mcap +50% vs promotion at the 24h check = a hit
_CLONE_RUNNER_STATE_FILE = _BOT_LOGS / "clone_runner_state.json"
_CLONE_RUNNERS_LOG = _BOT_LOGS / "clone_runners.jsonl"
_CLONE_RUNNER_REVIEW_FILE = _BOT_LOGS / "clone_runner_review.json"


def _clone_runner_state() -> dict:
    try:
        d = json.loads(_CLONE_RUNNER_STATE_FILE.read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def _clone_runner_log(event: str, **kw) -> None:
    try:
        with open(_CLONE_RUNNERS_LOG, "a", encoding="utf-8") as fh:
            fh.write(json.dumps({"ts": _now_iso(), "event": event, **kw}, default=str) + "\n")
    except Exception:
        pass


def _clone_runner_canon_stats(br: dict, ticker: str = "") -> dict:
    cm = br.get("canonical_mint")
    for c in br.get("candidates") or []:
        if isinstance(c, dict) and c.get("mint") == cm:
            return c
    try:   # canonical held from memory (absent from this search)
        mem = json.loads(_BRAND_CANON_FILE.read_text(encoding="utf-8"))
        rec = mem.get(str(ticker or br.get("ticker") or "").lower().strip().lstrip("$")) or {}
        if rec.get("mint") == cm:
            return rec
    except Exception:
        pass
    return {}


def _clone_runner_eval(packet: dict, mint: str, now: Optional[float] = None) -> Optional[dict]:
    """Track sustain per mint and return the runner context once every rule holds."""
    ctx = packet.get("context") or {}
    br = ctx.get("brand_resolution") or {}
    if br.get("is_canonical") is not False or not br.get("canonical_mint"):
        return None
    now = _now_ts() if now is None else now
    dd = ctx.get("dex_data") or {}
    _tk = br.get("ticker") or ctx.get("ticker") or packet.get("ticker") or ""
    canon = _clone_runner_canon_stats(br, _tk)
    c_liq, k_liq = _safe_num(dd.get("liquidity_usd")) or 0, _safe_num(canon.get("liquidity_usd")) or 0
    c1, k1 = _safe_num(dd.get("volume_1h")) or 0, _safe_num(canon.get("volume_1h")) or 0
    if c1 > 0 and k1 > 0:
        vol_basis, c_vol, k_vol = "1h", c1, k1
    else:
        vol_basis = "24h"
        c_vol, k_vol = _safe_num(dd.get("volume_24h")) or 0, _safe_num(canon.get("volume_24h")) or 0
    vol_ratio = (c_vol / k_vol) if k_vol > 0 else (float("inf") if c_vol > 0 else 0.0)
    liq_ratio = (c_liq / k_liq) if k_liq > 0 else (float("inf") if c_liq > 0 else 0.0)
    outpacing = bool(canon) and vol_ratio >= RUNNER_VOL_RATIO and c_liq > k_liq
    st = _clone_runner_state()
    rec = st.get(mint) or {}
    if not outpacing:
        if rec.get("first_qualified_ts") and not rec.get("promoted_at"):
            st.pop(mint, None)
            _save_json_atomic(_CLONE_RUNNER_STATE_FILE, st)
        return None
    if not rec.get("first_qualified_ts"):
        rec = {"first_qualified_ts": now, "first_qualified_at": _now_iso(),
               "ticker": _tk, "canonical_mint": br["canonical_mint"]}
    rec["last_qualified_ts"] = now
    rug_ok = (ctx.get("rug_check") or {}).get("smart_check_verdict") == "clean"
    vibe = (ctx.get("social_sentiment") or {}).get("overall_vibe")
    social_ok = vibe in ("bullish", "mixed")
    sustained = (now - float(rec["first_qualified_ts"])) >= RUNNER_SUSTAIN_MIN * 60
    runner = None
    if sustained and rug_ok and social_ok:
        runner = {"canonical_mint": br["canonical_mint"],
                  "vol_ratio": (round(vol_ratio, 2) if vol_ratio != float("inf") else None),
                  "liq_ratio": (round(liq_ratio, 2) if liq_ratio != float("inf") else None),
                  "vol_basis": vol_basis, "since": rec.get("first_qualified_at"),
                  "sustained_min": round((now - float(rec["first_qualified_ts"])) / 60, 1),
                  "social_vibe": vibe, "rug": "clean"}
        if not rec.get("promoted_at"):
            rec.update(promoted_at=_now_iso(), promoted_ts=now,
                       promo_mcap=_safe_num(dd.get("mcap")), runner=runner, outcomes={})
            _clone_runner_log("promoted", mint=mint, ticker=rec.get("ticker"), mcap=rec["promo_mcap"],
                              liquidity_usd=c_liq, **runner)
            _log(f"[clone] RUNNER {str(rec.get('ticker') or '').upper()} {_short_mint(mint)} "
                 f"vol x{runner['vol_ratio']} ({vol_basis}) liq x{runner['liq_ratio']} vs canonical "
                 f"{_short_mint(br['canonical_mint'])}, sustained {runner['sustained_min']}m", prefix="clone")
    st[mint] = rec
    cut = now - 7 * 86400
    st = {k: v for k, v in st.items() if float(v.get("last_qualified_ts") or v.get("promoted_ts") or 0) > cut}
    _save_json_atomic(_CLONE_RUNNER_STATE_FILE, st)
    return runner


def _clone_runner_mark(packet: dict, runner: dict) -> None:
    ctx = packet.setdefault("context", {})
    ctx["runner"] = runner
    ctx["card_label"] = "Clone Running"
    sv = list(ctx.get("surfaced_via") or [])
    if "clone_running" not in sv:
        sv.append("clone_running")
    ctx["surfaced_via"] = sv
    jc = packet.get("agent_card")
    if isinstance(jc, dict):
        jc["label"] = "Clone Running"
        jc["headline"] = "CLONE RUNNING | " + str(jc.get("headline") or "")
        jc.setdefault("flags", []).insert(0, (
            f"Clone Running: vol x{runner.get('vol_ratio')} ({runner.get('vol_basis')}), liq x{runner.get('liq_ratio')} "
            f"vs canonical {_short_mint(runner.get('canonical_mint') or '')} since {runner.get('since')}. "
            f"No buy bypass: normal filters and safety rules apply."))


def _clone_runner_flags(mint: str, pnl_pct=None) -> dict:
    """Autopsy fields for a traded mint that was a promoted runner (+ outcome row)."""
    rec = _clone_runner_state().get(mint) or {}
    if not rec.get("promoted_at"):
        return {}
    _clone_runner_log("trade_outcome", mint=mint, ticker=rec.get("ticker"), pnl_pct=pnl_pct,
                      canonical_mint=rec.get("canonical_mint"))
    return {"clone_runner": True, "clone_runner_promoted_at": rec.get("promoted_at"),
            "clone_runner_ctx": rec.get("runner")}


def _clone_runner_review(st: Optional[dict] = None) -> dict:
    st = _clone_runner_state() if st is None else st
    prom = {m: r for m, r in st.items() if r.get("promoted_at")}
    res24 = [r for r in prom.values() if "24h" in (r.get("outcomes") or {})]
    hits = [r for r in res24 if (r["outcomes"]["24h"].get("change_pct") or -1e9) >= RUNNER_HIT_PCT]
    out = {"_updated": _now_iso(), "promoted": len(prom), "resolved_24h": len(res24), "hits_24h": len(hits),
           "hit_rate_pct": round(100 * len(hits) / len(res24), 1) if res24 else None,
           "hit_rule": f"mcap +{RUNNER_HIT_PCT:g}% vs promotion at the 24h check",
           "rows": [{"mint": m, "ticker": r.get("ticker"), "promoted_at": r.get("promoted_at"),
                     "promo_mcap": r.get("promo_mcap"), "outcomes": r.get("outcomes"),
                     "runner": r.get("runner")} for m, r in list(prom.items())[-50:]]}
    _save_json_atomic(_CLONE_RUNNER_REVIEW_FILE, out)
    return out


async def clone_runner_outcome_loop() -> None:
    """Every 30 min: mark promoted runners at 6h and 24h (DexScreener mcap), log the
    outcome rows and refresh clone_runner_review.json (runner hit rate)."""
    while True:
        try:
            st = _clone_runner_state()
            now = _now_ts(); changed = False
            for m, r in st.items():
                if not r.get("promoted_ts"):
                    continue
                for label, h in (("6h", 6), ("24h", 24)):
                    if label in (r.get("outcomes") or {}) or now - float(r["promoted_ts"]) < h * 3600:
                        continue
                    mc = None
                    try:
                        pair = await fetch_token_data(m)
                        mc = _safe_num((pair or {}).get("marketCap") or (pair or {}).get("fdv"))
                    except Exception:
                        pass
                    pm = r.get("promo_mcap")
                    chg = round((mc / pm - 1) * 100, 1) if (mc and pm) else None
                    r.setdefault("outcomes", {})[label] = {"mcap": mc, "change_pct": chg, "at": _now_iso()}
                    _clone_runner_log("outcome", mint=m, ticker=r.get("ticker"), horizon=label,
                                      promo_mcap=pm, mcap=mc, change_pct=chg,
                                      hit=(None if chg is None else chg >= RUNNER_HIT_PCT) if label == "24h" else None)
                    changed = True
            if changed:
                _save_json_atomic(_CLONE_RUNNER_STATE_FILE, st)
            _clone_runner_review(st)
        except Exception as e:
            _log(f"clone runner outcome err: {e!r}", prefix="clone")
        await asyncio.sleep(1800)


def _clone_gate(packet: dict, mint: str, path) -> Optional[str]:
    ctx = packet.get("context") or {}
    br = ctx.get("brand_resolution") or {}
    tkr = str(br.get("ticker") or ctx.get("ticker") or "").lower().strip()
    if not tkr:
        return None
    now = _now_ts()
    held = _CLONE_CLUSTER_CARD.get(tkr) or {}
    if held and now - float(held.get("ts") or 0) > CLONE_CLUSTER_WINDOW_S:
        held = {}
    sv = ctx.get("surfaced_via") or []
    exempt = (br.get("is_canonical") is not False or br.get("is_narrative_vehicle")
              or any(s in ("runner_alert", "dex_paid_event") for s in sv))
    if exempt:
        _CLONE_CLUSTER_CARD[tkr] = {"path": str(path), "mint": mint, "ts": now}
        return None
    if CLONE_RUNNER_ENABLED:
        try:
            _rn = _clone_runner_eval(packet, mint)
        except Exception as _rne:
            _rn = None
            _log(f"clone runner eval err {_short_mint(mint)}: {_rne}", prefix="clone")
        if _rn:
            _clone_runner_mark(packet, _rn)
            return None      # own "Clone Running" card; the cluster card is left as is
    try:  # v1.0.7 fix 2: the 'clone' that is actually running passes (CLONE_RUNNER_OVERRIDE)
        import v107_rules as _v107
        _ovr = _v107.clone_override(ctx, br, mint, MISS_BOOK_FILE)
    except Exception:
        _ovr = None
    if _ovr:
        ctx["clone_override"] = _ovr
        _log(f"clone gate override {tkr} {_short_mint(mint)}: {_ovr}", prefix="clone")
        _CLONE_CLUSTER_CARD[tkr] = {"path": str(path), "mint": mint, "ts": now}
        return None
    vibe = (ctx.get("social_sentiment") or {}).get("overall_vibe")
    hp = Path(held["path"]) if held.get("path") else None
    if vibe == "dead":
        reason = "dead_social_clone"
    elif hp is not None and hp.exists() and held.get("mint") != mint:
        reason = "folded_into_cluster_card"
    else:
        _CLONE_CLUSTER_CARD[tkr] = {"path": str(path), "mint": mint, "ts": now}
        return None
    dd = ctx.get("dex_data") or {}
    row = {"ts": _now_iso(), "reason": reason, "mint": mint, "ticker": tkr,
           "canonical_mint": br.get("canonical_mint"), "clone_count": br.get("clone_count"),
           "canonical_why": (br.get("canonical_why") or None), "social_vibe": vibe,
           "mcap": dd.get("mcap") or ctx.get("mcap"), "liquidity_usd": dd.get("liquidity_usd"),
           "surfaced_via": sv, "base_mcap_zone": ctx.get("base_mcap_zone"),
           "launch_spike_peak": (ctx.get("launch_spike") or {}).get("peak_mcap"),
           "drop2_pass": (ctx.get("drop2_filters") or {}).get("pass_count"),
           "rug": (ctx.get("rug_check") or {}).get("smart_check_verdict"),
           "cluster_card": hp.name if hp is not None else None}
    try:
        with open(_CLONE_SUPPRESSED_FILE, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(row, default=str) + "\n")
    except Exception:
        pass
    if reason == "folded_into_cluster_card":
        try:
            card = json.loads(hp.read_text(encoding="utf-8"))
            card.pop("_meta", None)
            c2 = card.setdefault("context", {})
            fold = [f for f in (c2.get("clone_fold") or []) if f.get("mint") != mint]
            fold.append({"mint": mint, "mcap": row["mcap"], "social_vibe": vibe,
                         "liquidity_usd": row["liquidity_usd"], "at": row["ts"]})
            c2["clone_fold"] = fold[-20:]
            c2["clone_fold_count"] = int(c2.get("clone_fold_count") or 0) + 1
            _save_json_atomic(hp, card)
        except Exception:
            pass
    _CLONE_SUPPRESS_COUNTS[tkr] = _CLONE_SUPPRESS_COUNTS.get(tkr, 0) + 1
    _log(f"[clone] {reason} {tkr.upper()} {_short_mint(mint)} -> no inbox card "
         f"(ticker {_CLONE_SUPPRESS_COUNTS[tkr]}, total {sum(_CLONE_SUPPRESS_COUNTS.values())} "
         f"since boot; row kept in clone_suppressed.jsonl)", prefix="clone")
    return reason


async def resolve_ticker_brand(ticker: str, mint: str) -> dict:
    """Sprint 53 — BRAND / SAME-TICKER RESOLUTION (the agent's #2).

    THE PROBLEM: when a token runs, clones spawn instantly with the same or near-
    identical ticker. We burn cycles scanning lookalikes ($FEBUISM, $blackfebu,
    $febull) while the OG ($febu) runs untouched. Worse, a clone can LOOK better on
    our metrics (fresher, tighter chart) precisely because it's a parasite riding
    attention it didn't earn.

    THE FIX: when we see a ticker, search for ALL active tokens with that/near that
    symbol, and rank them. The canonical token is the one with the REAL claim to the
    brand — oldest pair, deepest liquidity, most volume, most holders. Clones get
    explicitly demoted in the packet so the agent doesn't waste a decision on them.

    Returns a resolution block for the packet. Never auto-vetoes — it INFORMS. A clone
    can still be a trade (they sometimes run); the agent just needs to KNOW it's a clone
    rather than mistaking it for the OG.
    """
    result = {
        "ticker": ticker, "mint": mint,
        "is_canonical": None, "canonical_mint": None,
        "clone_count": 0, "candidates": [], "note": None,
    }
    if not ticker or ticker == "?":
        return result
    try:
        pairs = await fetch_dex_search(ticker) or []
    except Exception as e:
        result["note"] = f"search failed: {str(e)[:80]}"
        return result

    # gather every Solana token whose symbol matches (or near-matches) this ticker
    tl = ticker.lower().strip()
    cands = {}
    # ── #1 (2026-08-12): MULTI-CHAIN READ-ONLY PASS ─────────────────────────
    # The Solana filter below is CORRECT for execution ranking - we trade Solana,
    # and a BNB token cannot be the canonical Solana mint. But it also threw the
    # foreign-chain rows away before anyone could count them, and the owner's kill
    # reason for the BOT/SpaceXai thesis started with exactly that: "first it was
    # bnb and sol version, now copycats everywhere."
    #
    # The system was structurally incapable of seeing the first half of the death
    # thesis. The dex search already returns every chain; the filter was discarding
    # evidence, not noise. Collected here for INTEL only - foreign chains never
    # touch is_canonical or any Solana ranking.
    _other_chain = {}
    for p in pairs:
        _ch = (p.get("chainId") or "").lower()
        if _ch and _ch != "solana":
            _b = p.get("baseToken") or {}
            _sym = (_b.get("symbol") or "").lower().strip()
            if not _sym or not ((_sym == tl) or (tl in _sym) or (_sym in tl)):
                continue
            _key = f"{_ch}:{_b.get('address')}"
            if _key in _other_chain:
                continue
            _other_chain[_key] = {
                "chain": _ch, "mint": _b.get("address"), "symbol": _b.get("symbol"),
                "mcap": _safe_num(p.get("marketCap") or p.get("fdv")) or 0,
                "volume_24h": _safe_num((p.get("volume") or {}).get("h24")) or 0,
                "liquidity_usd": _safe_num((p.get("liquidity") or {}).get("usd")) or 0,
            }
    for p in pairs:
        if (p.get("chainId") or "").lower() != "solana":
            continue
        base = p.get("baseToken") or {}
        sym = (base.get("symbol") or "").lower().strip()
        addr = base.get("address")
        if not addr or not sym:
            continue
        # exact match, or one contains the other (febu / febuism / blackfebu / febull)
        near = (sym == tl) or (tl in sym) or (sym in tl)
        if not near:
            continue
        if addr in cands:
            continue
        cands[addr] = {
            "mint": addr,
            "symbol": base.get("symbol"),
            "exact_ticker_match": sym == tl,
            "pair_created_at": p.get("pairCreatedAt"),
            "liquidity_usd": _safe_num((p.get("liquidity") or {}).get("usd")) or 0,
            "volume_24h": _safe_num((p.get("volume") or {}).get("h24")) or 0,
            "volume_1h": _safe_num((p.get("volume") or {}).get("h1")) or 0,   # runner check only
            "mcap": _safe_num(p.get("marketCap") or p.get("fdv")) or 0,
            "txns_24h": sum((p.get("txns", {}).get("h24", {}) or {}).values())
                        if isinstance(p.get("txns", {}).get("h24"), dict) else 0,
        }

    if len(cands) <= 1:
        result["is_canonical"] = True
        result["canonical_mint"] = mint
        result["note"] = "no same-ticker competition detected — this is the only one."
        return result

    # RANK: the canonical token is the one with the strongest real claim to the brand.
    # Age is the single hardest signal to fake (a clone cannot be older than the OG),
    # so it dominates; depth and real activity break ties. A clone can out-pump the OG
    # on a fresh chart, but it cannot out-AGE it.
    def _score(c):
        created = c.get("pair_created_at") or 0
        age_days = ((_now_ts() * 1000 - created) / 86_400_000) if created else 0
        s = 0.0
        s += min(age_days, 60) * 2.0                      # age dominates (capped)
        s += min(c["liquidity_usd"] / 10_000, 20)        # depth
        s += min(c["volume_24h"] / 50_000, 15)           # real activity
        s += min(c["txns_24h"] / 200, 10)                # real participants
        if c["exact_ticker_match"]:
            s += 15                                       # exact symbol beats a near-match
        return s

    ranked = sorted(cands.values(), key=_brand_rank_key(_score))   # 2026-10-15 total order
    for r in ranked:
        r["brand_score"] = round(_score(r), 1)
    canonical = _brand_canon_stable(tl, ranked, _score)   # 2026-10-15 sticky
    result["canonical_why"] = canonical.get("_canon_why")
    result["canonical_mint"] = canonical["mint"]
    result["is_canonical"] = (canonical["mint"] == mint)
    result["clone_count"] = len(ranked) - 1
    result["candidates"] = ranked[:6]
    # ── #7 (2026-08-12): the count and the list must not disagree ───────────
    result["candidates_shown"] = f"{min(6, len(ranked))} of {len(ranked)}"

    # ── #2 (2026-08-12): DEAD-OG DEMOTION ───────────────────────────────────
    # Age weight is min(age_days,60)*2 = up to +120, which swamps liq (max 20),
    # vol (15) and txns (10) combined. So the oldest pair wins the "canonical"
    # label even when its tape is a corpse. Live receipts from 2026-08-11:
    #   BOT     - "canonical" 63bpn: 1.3k vol, score 140. Huka: $13.4M vol, score 57.
    #   GrokBOT - "canonical" DRFE: $0 LIQUIDITY, $805 vol, score 135.
    # Fifteen dead-canon patterns in one day's sample.
    #
    # Age is still the right ANTI-FAKE signal - a clone cannot be older than the OG,
    # and that is worth keeping. It is the wrong answer to a different question:
    # who carries the narrative NOW. Those are two facts and the resolver was
    # collapsing them into one label. Both are reported; neither is deleted.
    try:
        _DEAD_VOL = float(_envv("BRAND_DEAD_OG_VOL_24H", "5000"))
        _DEAD_LIQ = float(_envv("BRAND_DEAD_OG_LIQ", "10000"))
        _og_dead = (canonical.get("volume_24h", 0) < _DEAD_VOL
                    or canonical.get("liquidity_usd", 0) < _DEAD_LIQ)
        _live = [c for c in ranked
                 if c.get("volume_24h", 0) >= _DEAD_VOL * 4
                 and c.get("liquidity_usd", 0) >= _DEAD_LIQ]
        _vehicle = max(_live, key=lambda c: c.get("volume_24h", 0)) if _live else None
        result["age_canonical_mint"] = canonical["mint"]
        result["canonical_status"] = "live_brand"
        if _og_dead and _vehicle and _vehicle["mint"] != canonical["mint"]:
            result["canonical_status"] = "age_trophy_dead"
            result["narrative_vehicle_mint"] = _vehicle["mint"]
            result["narrative_vehicle"] = {
                "mint": _vehicle["mint"], "symbol": _vehicle.get("symbol"),
                "mcap": _vehicle.get("mcap"), "volume_24h": _vehicle.get("volume_24h"),
                "liquidity_usd": _vehicle.get("liquidity_usd"),
            }
            result["is_narrative_vehicle"] = (_vehicle["mint"] == mint)
        elif not _og_dead:
            result["is_narrative_vehicle"] = result["is_canonical"]
        else:
            # 2026-10-16 chair fix: a dead OG with no live vehicle is not a "live_brand".
            result["canonical_status"] = "dead_og_no_vehicle"
    except Exception:
        pass

    # ── #3 (2026-08-12): A GRADE, NOT A RAW INT ────────────────────────────
    # "clone_count: 12" on a generic ticker is close to a constant, so the operator
    # learns to skip the number. A band says what to DO with it.
    _cc = result["clone_count"]
    result["clone_grade"] = ("solo" if _cc == 0 else "rival" if _cc <= 2
                             else "crowd" if _cc <= 7 else "flood")
    result["clone_flood"] = (_cc >= 8)

    # ── #1 output: the bnb+sol tell, surfaced ──────────────────────────────
    result["other_chain_clones"] = sorted(_other_chain.values(),
                                          key=lambda c: -(c.get("volume_24h") or 0))[:8]
    result["other_chain_clone_count"] = len(_other_chain)
    result["other_chains_seen"] = sorted({c["chain"] for c in _other_chain.values()})
    result["multi_chain_flood"] = bool(len(_other_chain) >= 2
                                       and len(result["other_chains_seen"]) >= 1)
    result["_multi_chain_note"] = (
        "foreign-chain hits are INTEL ONLY - they never set is_canonical and never "
        "rank against Solana. They exist because 'same ticker on bnb AND sol' is the "
        "exact tell that killed the SpaceXai thesis, and the resolver used to discard "
        "it before anyone could count it.")

    if result["is_canonical"]:
        result["note"] = (
            f"CANONICAL — this is the OG ${ticker}. {result['clone_count']} clone(s)/"
            f"lookalike(s) are active alongside it. Judge THIS one; ignore the copies."
        )
    else:
        c = canonical
        result["note"] = (
            f"⚠ CLONE / LOOKALIKE — this is NOT the canonical ${ticker}. The OG is "
            f"{c['symbol']} ({_short_mint(c['mint'])}): older pair, ${c['liquidity_usd']:,.0f} liq, "
            f"${c['volume_24h']:,.0f} 24h vol. You are looking at a copy riding its attention. "
            f"A clone CAN still run — but know what you're buying, and never mistake it for "
            f"the brand. If you want the brand, buy the brand."
        )

    # ── #2 note honesty: say BOTH facts when they differ ────────────────────
    # "the OG is X" is a lie of omission when X has $0 liquidity and something else
    # is carrying the narrative. Two sentences, two facts, neither deleted.
    if result.get("canonical_status") == "age_trophy_dead":
        _nv = result.get("narrative_vehicle") or {}
        result["note"] = (
            f"⚠ DEAD OG — the oldest ${ticker} ({_short_mint(canonical['mint'])}) is an AGE "
            f"TROPHY: ${canonical.get('volume_24h', 0):,.0f} 24h vol, "
            f"${canonical.get('liquidity_usd', 0):,.0f} liq. It holds the history and carries "
            f"nothing. The live vehicle right now is {_nv.get('symbol')} "
            f"({_short_mint(_nv.get('mint') or '')}): ${_nv.get('volume_24h', 0):,.0f} vol, "
            f"${_nv.get('mcap', 0):,.0f} mcap. "
            + ("THIS token IS that vehicle. " if result.get("is_narrative_vehicle")
               else "This token is neither the OG nor the vehicle. ")
            + "Buying 'the brand' here means buying a museum piece - the attention is "
              "somewhere else. Age proves what a clone cannot fake; it does not prove "
              "who the market is trading today.")
    # ── #3 flood, said at the top not buried ────────────────────────────────
    if result.get("clone_flood"):
        result["note"] = (f"🚨 CLONE FLOOD ({result['clone_count']} same-ticker on Solana"
                          + (f", plus {result['other_chain_clone_count']} on "
                             f"{'/'.join(result['other_chains_seen'])}"
                             if result.get("other_chain_clone_count") else "")
                          + "). At this density the ticker is not a brand any more, it is a "
                            "queue. " + result["note"])
    elif result.get("other_chain_clone_count"):
        result["note"] += (f" MULTI-CHAIN: {result['other_chain_clone_count']} same-ticker "
                           f"token(s) also live on {'/'.join(result['other_chains_seen'])} - "
                           f"the same tell that killed the SpaceXai thesis.")
    return result


def _never_seen_skip_reason(mint: str, pair: dict, mcap: float) -> str:
    """Return a reason string when a never_seen candidate is NOT a real discovery miss."""
    try:
        sym = str((pair.get("baseToken") or {}).get("symbol") or "").strip().upper().lstrip("$")
        if mint == "So11111111111111111111111111111111111111112" or sym in ("SOL", "WSOL"):
            return "sol_ticker"
        max_age_d = float(get_override_sync("NEVER_SEEN_MAX_AGE_DAYS", 7))
        created = pair.get("pairCreatedAt")
        if created:
            age_d = (_now_ts() * 1000 - float(created)) / 86_400_000
            if age_d > max_age_d:
                return "older_than_max_age"
        ceiling = float(get_override_sync("NEVER_SEEN_MAX_MCAP_USD", 10_000_000))
        if mcap and mcap > ceiling:
            return "above_continuation_band"
        liq = _safe_num((pair.get("liquidity") or {}).get("usd")) or 0
        if mcap and liq and abs(mcap - liq) / max(mcap, 1) < 0.01:
            return "mcap_equals_liquidity"
    except Exception:
        return ""
    return ""


async def never_seen_sweep() -> dict:
    """Find runners that are NOT in our discovery ledger — pure blind spots.

    CRITICAL DESIGN POINT: this MUST sample from a source INDEPENDENT of the feeds we
    already poll. Sampling the boosts list would be circular — we record every boost we
    fetch into the ledger, so nothing from boosts can ever be "never seen." The blind
    spot we're hunting is precisely the token that appears in NEITHER bonded-profiles
    NOR boosts, which is exactly the class the $febu-style branded runner falls into.
    So we search independently (DexScreener search), and anything that turns up hot and
    is absent from the ledger is a genuine discovery failure.

    This trains DISCOVERY. The missed_runner observer trains FILTERS (tokens we saw and
    declined). Nothing before this trained the layer above — the thing deciding what we
    even look at. A blind spot stays blind forever unless something is built to notice it.
    """
    NEVER_SEEN_MIN_MCAP = get_override_sync("NEVER_SEEN_MIN_MCAP_USD", 1_000_000)
    NEVER_SEEN_MIN_VOL  = get_override_sync("NEVER_SEEN_MIN_VOL_24H_USD", 250_000)
    WATCH_MIN_MCAP = get_override_sync("NEVER_SEEN_WATCH_MIN_MCAP_USD", 80_000)
    WATCH_MIN_VOL = get_override_sync("NEVER_SEEN_WATCH_MIN_VOL_USD", 80_000)
    WATCH_CAP = int(get_override_sync("NEVER_SEEN_WATCH_CAP", 3))
    out = {"checked": 0, "never_seen": 0, "autopsies": 0, "watch_packets": 0}

    seen_ledger = load_scanned_mints()
    already = load_never_seen()
    changed = False

    # Independent probes: broad Solana queries that surface active pairs regardless of
    # whether they ever bonded or bought a boost. This is the whole point — a different
    # window onto the market than the two feeds we already watch.
    probes = get_override_sync("NEVER_SEEN_PROBES", None) or ["SOL", "pump", "bonk", "wif"]
    candidates = {}
    for q in probes:
        try:
            pairs = await fetch_dex_search(q) or []
        except Exception:
            continue
        for pair in pairs:
            if (pair.get("chainId") or "").lower() != "solana":
                continue
            mint = (pair.get("baseToken") or {}).get("address")
            if not mint:
                continue
            # 2026-10-16 chair fix: keep the DEEPEST pair per mint (same rule as
            # fetch_token_data) so autopsy/card liquidity agree across packets.
            _prev = candidates.get(mint)
            if _prev is not None and (_safe_num((_prev.get("liquidity") or {}).get("usd")) or 0) >= \
                    (_safe_num((pair.get("liquidity") or {}).get("usd")) or 0):
                continue
            candidates[mint] = pair
        await asyncio.sleep(0.3)   # be polite to the API

    for mint, pair in candidates.items():
        out["checked"] += 1
        if mint in seen_ledger:
            continue          # we saw it — that's a FILTER question, not a discovery one
        if mint in already:
            continue          # this blind spot is already autopsied

        mcap = _safe_num(pair.get("marketCap") or pair.get("fdv")) or 0
        vol  = _safe_num((pair.get("volume") or {}).get("h24")) or 0
        # 2026-10-16 chair fix: skip established tokens and SOL lookalikes. Older than
        # NEVER_SEEN_MAX_AGE_DAYS, above the continuation band ceiling, a 'SOL'/'WSOL'
        # ticker or wrapped-SOL mint, or mcap==liquidity (search-result artifact) is not
        # a discovery miss. These were the PUMP/Bonk/'SOL' false positives.
        _skip = _never_seen_skip_reason(mint, pair, mcap)
        if _skip:
            continue
        # Only care about things that actually RAN. A token we never saw that also never
        # went anywhere isn't a miss — it's just noise we correctly ignored.
        live_ok = mcap >= WATCH_MIN_MCAP and vol >= WATCH_MIN_VOL
        autopsy_ok = mcap >= NEVER_SEEN_MIN_MCAP and vol >= NEVER_SEEN_MIN_VOL
        if not live_ok and not autopsy_ok:
            continue

        out["never_seen"] += 1
        liq = _safe_num((pair.get("liquidity") or {}).get("usd")) or 0
        if live_ok and out["watch_packets"] < WATCH_CAP:
            try:
                profile = {
                    "tokenAddress": mint,
                    "chainId": "solana",
                    "url": pair.get("url"),
                    "description": "never_seen_organic",
                }
                packet = await build_meme_candidate_packet(profile, surfaced_via="never_seen_organic")
                if packet:
                    ctx = packet.get("context") or {}
                    ctx["discovery_source"] = "never_seen_organic"
                    ctx["never_seen"] = True
                    packet["context"] = ctx
                    write_meme_candidate_packet(packet)
                    out["watch_packets"] += 1
                    try:
                        record_seen_mint(
                            mint,
                            source="never_seen_organic",
                            ticker=(pair.get("baseToken") or {}).get("symbol"),
                            mcap=mcap,
                        )
                    except Exception:
                        pass
            except Exception as e:
                _log(f"never_seen watch emit err {str(mint)[:8]}: {e}", prefix="discovery")
        why = {
            "not_in_scan_ledger": True,
            "mcap_now": mcap,
            "volume_24h": vol,
            "liquidity_now": liq,
            "above_early_band_ceiling": mcap > EDGE_MCAP_MAX_USD,
            "in_continuation_band": 1_000_000 <= mcap <= 10_000_000,
            "hypothesis": (
                "Above the early-band mcap ceiling — early discovery structurally cannot "
                "surface this. The continuation band (1M-10M) is the lane meant to catch it. "
                "Check: is the continuation lane actually scanning, or only classifying?"
                if mcap > EDGE_MCAP_MAX_USD else
                "Inside the early band yet never scanned — this is a SOURCE or TIMING gap, "
                "not a band gap. It never bonded and never boosted, so neither feed saw it. "
                "That's the real hole."
            ),
        }
        await _write_never_seen_autopsy(mint, pair, why)
        already[mint] = {"mint": mint, "autopsied_at": _now_iso(), "mcap": mcap}
        changed = True
        out["autopsies"] += 1

    if changed:
        try:
            _save_json_atomic(NEVER_SEEN_FILE, already)
        except Exception:
            pass
    if out["autopsies"]:
        _log(f"never_seen sweep: {out['checked']} candidates, {out['never_seen']} never-seen, "
             f"{out['autopsies']} autopsies fired", prefix="discovery")
    return out


async def never_seen_loop() -> None:
    """Run the never_seen discovery sweep periodically. Slow cadence — this is a
    learning loop, not a trading loop."""
    _log("never_seen_observer: starting", prefix="discovery")
    while True:
        if await _rpc_pause_if_unhealthy("never_seen_observer"):   # 2026-10-14
            continue
        try:
            if await get_override("NEVER_SEEN_PAUSED", False):
                await asyncio.sleep(300)
                continue
            await never_seen_sweep()
        except Exception as e:
            _log(f"never_seen loop err: {e}", prefix="discovery")
        await asyncio.sleep(get_override_sync("NEVER_SEEN_TICK_SECONDS", 900))


# ─── PENDING CONFIRMATIONS (2026-07-26, the exit-path P1) ───────────────────
# The agent escalated "sell success 5/17 = 22.7%". Root cause found in the swap
# path: on confirmation timeout the executor returned success=False with the
# comment "tx may still land later , caller can check" — and NO CALLER EVER
# CHECKED. A sell that confirms at second 35 was filed as a permanent failure.
# A phantom failure: the book says failed while the chain SOLD. It
# also poisons the stat the agent is standing down on, and invites a retry into a
# bag that is already gone. Truth is on the chain — go back and ask it.
PENDING_CONFIRM_FILE = _BOT_LOGS / "pending_confirmations.json"
PENDING_CONFIRM_MAX_AGE_S = 180        # blockhash validity (~90s) + slack
_PENDING_INFLIGHT_GUARD_S = 120        # don't fire a second sell on the same mint inside this

# F11 (2026-08-15): set when the pending file could not be READ (as opposed to
# being legitimately absent/empty). The in-flight sell guards below are the only
# thing standing between a retry and a DOUBLE SELL, and they read this file - so
# "I could not read it" must never look the same as "there is nothing in it".
_PENDING_READ_FAILED = False


def _load_pending_confirmations() -> dict:
    global _PENDING_READ_FAILED
    try:
        if not PENDING_CONFIRM_FILE.exists():
            _PENDING_READ_FAILED = False      # genuinely nothing pending
            return {}
        with open(PENDING_CONFIRM_FILE, encoding="utf-8-sig") as f:
            _d = json.load(f) or {}
        _PENDING_READ_FAILED = False
        return _d
    except Exception as _pe:
        # corrupt / locked / half-written. Returning {} here reads as "no sells in
        # flight" to every caller, which is the exact wrong answer: the guard opens
        # and a second sell can go out against a bag that already has one pending.
        _PENDING_READ_FAILED = True
        try:
            _log(f"pending_confirmations UNREADABLE ({_pe}) — treating as SELLS IN FLIGHT "
                 f"(fail closed). A read failure is not an empty book.", prefix="exec")
        except Exception:
            pass
        return {}

def _save_pending_confirmations(d: dict) -> bool:
    """Persist the pending book. Returns True only if it actually landed.

    ── F3 (2026-08-15): A SWALLOWED SAVE UNTRACKS A LIVE SIGNATURE ─────────────
    _record_pending_confirmation's own docstring says a timed-out submit "stops
    being a mystery and becomes a tracked question". That is true only if this
    write succeeds. It returned None and logged one line on failure, so a disk
    error silently put the signature BACK to being a mystery: a real, possibly
    landing transaction with nothing tracking it, and callers with no way to know.
    
    Two changes: report success, and write ATOMICALLY. The old path truncated the
    file with open(...,"w") before dumping, so a crash mid-write destroyed the
    whole pending book - which is exactly the corrupt-file case the F11 guards now
    have to fail closed on. Not creating the corruption beats detecting it.
    """
    try:
        PENDING_CONFIRM_FILE.parent.mkdir(parents=True, exist_ok=True)
        _tmp = PENDING_CONFIRM_FILE.with_suffix(PENDING_CONFIRM_FILE.suffix + ".tmp")
        with open(_tmp, "w", encoding="utf-8") as f:
            json.dump(d, f, indent=2)
            f.flush()
            os.fsync(f.fileno())
        os.replace(_tmp, PENDING_CONFIRM_FILE)
        return True
    except Exception as e:
        _log(f"pending_confirm save FAILED: {e} — a timed-out signature may now be "
             f"UNTRACKED. Check the wallet against the position book before trusting "
             f"any sell verdict.", prefix="pending")
        return False

def _record_pending_confirmation(sig: str, meta: dict) -> None:
    """Called the moment a submit times out — the signature is REAL and may
    still land; it stops being a mystery and becomes a tracked question."""
    if not sig:
        return
    try:
        d = _load_pending_confirmations()
        d[sig] = {**meta, "submitted_at": _now_iso(), "submitted_ts": _now_ts(),
                   "checks": 0, "state": "pending"}
        # F3: only claim "tracking" if the write actually landed. Logging tracking
        # on a failed save is how an untracked live signature reads as handled.
        if _save_pending_confirmations(d):
            _log(f"pending: {sig[:8]}.. unconfirmed at timeout — tracking (NOT calling it failed yet)",
                 prefix="pending")
        else:
            _log(f"pending: {sig[:8]}.. unconfirmed at timeout and COULD NOT BE PERSISTED. "
                 f"This signature is live on chain and NOT tracked - it will not be "
                 f"reconciled, and the in-flight guards cannot see it. Check the wallet.",
                 prefix="pending")
    except Exception as e:
        _log(f"pending_confirm record err: {e} — signature {str(sig)[:8]}.. may be "
             f"UNTRACKED", prefix="pending")

def has_inflight_sell(mint: str) -> bool:
    """Guard against stacking a second sell on a bag whose first sell may
    already be landing — the double-sell that turns one timeout into two
    'failures' and can dump a position twice.

    ── F11 (2026-08-15): FAILS CLOSED NOW ──────────────────────────────────────
    This is FILE state, not chain state, and every failure path returned False -
    which means "no sell in flight, go ahead". So a corrupt, locked or
    half-written pending_confirmations.json opened the guard rather than closing
    it, on the one function whose own docstring says the failure mode is dumping
    a position twice.
    
    Absence of evidence was being read as evidence of absence, with money on it.
    A read failure now returns True: refuse the second sell, log loudly, and let a
    human or the next clean read decide. The cost of a false block is a delayed
    exit; the cost of a false open is selling the same bag twice.
    """
    try:
        _rows = _load_pending_confirmations() or {}
        if _PENDING_READ_FAILED:
            _log(f"has_inflight_sell({_short_mint(mint)}): pending file unreadable — "
                 f"BLOCKING the sell (fail closed). Fix or delete the file to clear.",
                 prefix="exec")
            return True
        for sig, row in _rows.items():
            # Accept side "sell" OR legacy "swap" rows (pre-2026-07-27 rows were
            # written with side="swap"); the TOKEN mint is the real discriminator.
            if (row.get("mint") == mint
                    and (row.get("side") in ("sell", "swap")
                         or row.get("direction") == "sell")
                    and row.get("state") == "pending"
                    and _now_ts() - (row.get("submitted_ts") or 0) < _PENDING_INFLIGHT_GUARD_S):
                return True
    except Exception as _ie:
        # F11: an exception here is NOT "no sell in flight". Same reasoning as the
        # read failure above - unknown state blocks, it does not wave through.
        _log(f"has_inflight_sell({_short_mint(mint)}) errored ({_ie}) — BLOCKING "
             f"(fail closed)", prefix="exec")
        return True
    return False

def _mint_has_live_pending_sell(mint: str) -> bool:
    """Like has_inflight_sell but over the FULL tracking window (180s, not the
    120s double-sell guard). Used by the escalation ladder: a rung fired early
    can still be unconfirmed by the time the ladder exhausts 2-3 rungs later, and
    that leg may land late. If one is live, the ladder must report
    pending_confirmation instead of a settled failure — the pending tracker owns
    the verdict, and booking sell_failed here is the miscount we just killed."""
    try:
        for sig, row in (_load_pending_confirmations() or {}).items():
            if (row.get("mint") == mint
                    and (row.get("side") in ("sell", "swap") or row.get("direction") == "sell")
                    and row.get("state") == "pending"
                    and _now_ts() - (row.get("submitted_ts") or 0) < PENDING_CONFIRM_MAX_AGE_S):
                return True
        # F11: same fail-closed rule as has_inflight_sell - an unreadable pending
        # file is UNKNOWN state, and unknown blocks a second sell.
        if _PENDING_READ_FAILED:
            _log(f"_mint_has_live_pending_sell({_short_mint(mint)}): pending file "
                 f"unreadable — reporting LIVE PENDING (fail closed)", prefix="exec")
            return True
    except Exception as _me:
        _log(f"_mint_has_live_pending_sell({_short_mint(mint)}) errored ({_me}) — "
             f"reporting LIVE PENDING (fail closed)", prefix="exec")
        return True
    return False

async def pending_confirmation_loop() -> None:
    """Every 20s: ask the chain what actually happened to timed-out submits.
    Landed clean → LATE LANDED (the sale is real, stop calling it a failure).
    Landed with an error → a true failure, now with the on-chain reason.
    Never seen past the blockhash window → genuinely dropped, safe to retry."""
    _log("pending_confirmations: starting (a timeout is a question, not a verdict)", prefix="pending")
    while True:
        try:
            d = _load_pending_confirmations()
            if d:
                changed = False
                for sig, row in list(d.items()):
                    if row.get("state") != "pending":
                        if _now_ts() - (row.get("submitted_ts") or 0) > 3600:
                            d.pop(sig, None); changed = True
                        continue
                    row["checks"] = int(row.get("checks", 0)) + 1
                    age = _now_ts() - (row.get("submitted_ts") or 0)
                    st = None
                    try:
                        r = await helius_rpc("getSignatureStatuses", [[sig], {"searchTransactionHistory": True}])
                        st = ((r or {}).get("value") or [None])[0]
                    except Exception:
                        st = None
                    # REBROADCAST while the blockhash can still be valid (~90s).
                    # "sent-unconfirmed" is a different state from "never sent",
                    # and the cure for the first one is to say it again.
                    if not st and age < 90 and row.get("signed_tx_b64") and not row.get("rebroadcast_at"):
                        try:
                            await helius_rpc("sendTransaction", [row["signed_tx_b64"], {
                                "skipPreflight": True, "encoding": "base64", "maxRetries": 0}])
                            if RPC_URL_FALLBACK:
                                await helius_rpc("sendTransaction", [row["signed_tx_b64"], {
                                    "skipPreflight": True, "encoding": "base64", "maxRetries": 0}],
                                    rpc_url=RPC_URL_FALLBACK)
                            row["rebroadcast_at"] = _now_iso(); changed = True
                            _log(f"pending: {sig[:8]}.. REBROADCAST at {age:.0f}s (both endpoints)",
                                 prefix="pending")
                        except Exception as _rb:
                            _log(f"pending: rebroadcast err {_rb!r}", prefix="pending")
                    if st:
                        err = st.get("err")
                        if err is None:
                            row["state"] = "landed_late"; changed = True
                            _log(f"pending: {sig[:8]}.. LANDED LATE ({age:.0f}s) — "
                                 f"{row.get('side')} {row.get('ticker') or row.get('mint','')[:8]} "
                                 f"was NOT a failure", prefix="pending")
                            try:
                                await send_telegram(
                                    f"✅ <b>LATE LANDED</b> — {row.get('side','swap')} "
                                    f"{row.get('ticker') or (row.get('mint') or '')[:8]}\n"
                                    f"confirmed {age:.0f}s after submit (timeout said failed; the chain says done)\n"
                                    f"tx: {sig[:16]}...\n"
                                    f"Book this as a FILL — the bag moved. "
                                    f"The position row is NOT closed automatically; "
                                    f"see the packet's needs_book_close.")
                            except Exception:
                                pass
                            try:
                                # ── F6 (2026-08-15): LINK THE CORRECTION TO WHAT IT CORRECTS ──
                                # The ledger already dedupes via _ledger_episode_written, so
                                # this is not double-BOOKING. It is double-TELLING: the desk
                                # got a signal_ack (or a timeout "failed") minutes ago, and
                                # now gets this - two verdicts about one bag with nothing
                                # connecting them. An operator reading the second in
                                # isolation cannot tell whether it replaces the first or
                                # describes a different leg.
                                #
                                # A correction has to name what it corrects. supersedes /
                                # original_signal_id / prior_verdict make this a REVISION of
                                # a known row instead of a fresh event competing with it.
                                # ── FIX 3 (2026-08-16): DOES THE BOOK STILL SHOW THE BAG? ──
                                # The ledger gets its `sell` from the late-land path, so
                                # sell-success heals here. `remove_position` lives only on
                                # the happy-path exit (~21398), so the ROW does not. That is
                                # two UIs over one ATA: the exit meter reads healthy while
                                # position monitors keep working a bag that is gone, and the
                                # ghost loop only screams 10 minutes later with no link back
                                # to this signature.
                                #
                                # Not auto-closing. A silent book rewrite off a background
                                # loop is exactly the class of move that needs the owner to bless
                                # it, and a wrong auto-close invents a fill price. What this
                                # does is refuse to let the packet imply the book is settled.
                                _pm = row.get("mint")  # this leg's mint (was read before assignment)
                                _book_status, _needs_close, _booked_raw, _held_raw = "unknown", None, None, None
                                try:
                                    _prow = (load_positions() or {}).get(_pm) or {}
                                    if _prow and _prow.get("status", "open") == "open":
                                        _booked_raw = float(_prow.get("token_amount") or 0)
                                        try:
                                            _rows = await get_wallet_token_balances() or []
                                            _held_raw = float(next(
                                                (b.get("amount_raw") for b in _rows
                                                 if b.get("mint") == _pm), 0) or 0)
                                        except Exception:
                                            _held_raw = None
                                        # raw vs raw, same unit basis the reconcile loop uses
                                        # after the SimonCat unit bug.
                                        if _held_raw is not None and _booked_raw > 0:
                                            if _held_raw < _booked_raw * 0.02:
                                                _book_status, _needs_close = "still_open", True
                                            else:
                                                _book_status, _needs_close = "still_open_bag_present", False
                                        else:
                                            _book_status, _needs_close = "still_open", True
                                    elif _prow:
                                        _book_status, _needs_close = "already_closed", False
                                    else:
                                        _book_status, _needs_close = "no_row", False
                                except Exception as _be:
                                    _log(f"pending: book check failed for {str(_pm)[:8]}: {_be}",
                                         prefix="pending")

                                if (str(row.get("side") or "").lower() == "sell"
                                        and _book_status != "still_open_bag_present"):
                                    _prow2 = (load_positions() or {}).get(_pm) or {}
                                    if _prow2:
                                        _close, _why = book_should_close(
                                            _pm, _prow2, held_raw=_held_raw)
                                        if _close:
                                            remove_position(_pm)
                                            _book_status = "closed_on_fill"
                                            _needs_close = False

                                pkt = {"_type": "late_landed_swap", "generated_at": _now_iso(),
                                        "tx_signature": sig, "seconds_to_confirm": round(age),
                                        **{k: row.get(k) for k in ("mint", "ticker", "side", "amount", "reason")},
                                        "book_status": _book_status,
                                        "needs_book_close": bool(_needs_close),
                                        "book_evidence": {
                                            "booked_token_amount_raw": _booked_raw,
                                            "wallet_holds_raw": _held_raw,
                                            "unit_basis": "raw",
                                            "threshold": "wallet < 2% of booked = bag gone",
                                        },
                                        "book_doctrine": (
                                            "The LEDGER now counts this as a landed sell, so sell-success "
                                            "healed. The POSITION BOOK was not touched - remove_position "
                                            "only runs on the happy-path exit. Nothing here auto-closes a "
                                            "row: that would be a silent rewrite off a background loop and "
                                            "would have to invent a fill price. If needs_book_close is "
                                            "true, close it deliberately with the real fill, or the exit "
                                            "monitor keeps working a bag that is not there and the "
                                            "position_ghost packet will repeat this in ~10min."),
                                        "supersedes": {
                                            "signal_id": row.get("signal_id") or row.get("id"),
                                            "ack_id": row.get("ack_id"),
                                            "prior_verdict": "sell_failed (30s confirmation timeout)",
                                            "prior_at": row.get("timeout_at") or row.get("submitted_at"),
                                        },
                                        "correction": True,
                                        "note": ("This swap was reported FAILED on a 30s confirmation timeout "
                                                  "and then landed. THIS PACKET REPLACES that verdict - it is not "
                                                  "a second event. Your sell-success stat undercounts by every "
                                                  "one of these. Re-sync the position from the wallet's real "
                                                  "token balance before acting on it."),
                                        "ask": "confirm the position book matches the chain, then continue"}
                                fn = _INBOX / f"meme_sniper - late_landed_{(row.get('ticker') or 'swap')}_{sig[:8]}.json"
                                with open(fn, "w", encoding="utf-8") as f:
                                    json.dump(pkt, f, indent=2)
                            except Exception:
                                pass
                        else:
                            row["state"] = "failed_onchain"; row["onchain_error"] = str(err)[:300]
                            changed = True
                            _log(f"pending: {sig[:8]}.. failed ON CHAIN: {str(err)[:160]}", prefix="pending")
                    elif age > PENDING_CONFIRM_MAX_AGE_S:
                        row["state"] = "dropped"; changed = True
                        _log(f"pending: {sig[:8]}.. never landed ({age:.0f}s) — dropped, safe to retry",
                             prefix="pending")

                    # ── RULER FIX: SINGLE TERMINAL LEDGER WRITE, PER MINT-EPISODE ──
                    # The old code fired a LATE-LANDED telegram admitting the stat
                    # undercounts, then never touched the ledger the stat reads.
                    # The tracker is now the SOLE terminal writer for timed-out
                    # sells: once EVERY timed-out leg for a mint has resolved, book
                    # exactly ONE event — `sell` if any leg landed, else
                    # `sell_failed`. Grouping by mint + firing only when nothing is
                    # still pending makes it order-independent, so a chunked or
                    # escalated exit that lands one of several legs counts as a
                    # single success and its dropped siblings add no extra failure.
                    _pm = row.get("mint")
                    _is_sell_leg = (row.get("side") in ("sell", "swap")
                                    or row.get("direction") == "sell")
                    if (_pm and _is_sell_leg
                            and row.get("state") in ("landed_late", "failed_onchain", "dropped")):
                        _legs = [r for r in d.values()
                                 if r.get("mint") == _pm
                                 and (r.get("side") in ("sell", "swap")
                                      or r.get("direction") == "sell")]
                        _still_pending = any(r.get("state") == "pending" for r in _legs)
                        _already = any(r.get("_ledger_episode_written") for r in _legs)
                        if not _still_pending and not _already:
                            _landed = any(r.get("state") == "landed_late" for r in _legs)
                            try:
                                if _landed:
                                    # F6: the detail line is what an analyzer reads back
                                    # months later. Say REVISES, not just "late-landed",
                                    # so a row that overturns an earlier verdict is
                                    # legible as an overturn.
                                    exec_log("sell", ticker=row.get("ticker"), mint=_pm, tx=sig,
                                             detail=f"REVISES an earlier sell_failed: late-landed "
                                                    f"{age:.0f}s after submit (the 30s timeout had "
                                                    f"called it failed). One bag, one outcome - this "
                                                    f"is the true one.",
                                             late_landed=True)
                                    _log(f"pending: {_pm[:8]} episode → booked SELL (late-landed); "
                                         f"sell-success now counts it", prefix="pending")
                                else:
                                    exec_log("sell_failed", ticker=row.get("ticker"), mint=_pm, tx=sig,
                                             detail="all timed-out legs resolved without landing",
                                             failure_class="timeout_resolved")
                                    _log(f"pending: {_pm[:8]} episode → booked SELL_FAILED "
                                         f"(no leg landed)", prefix="pending")
                                    try:
                                        _pos = {}
                                        try:
                                            _pos = (load_positions() or {}).get(_pm) or {}
                                        except Exception:
                                            _pos = {}
                                        await queue_exit_failed_autopsy(
                                            _pm, _pos, {"tx_signature": sig, "trigger": "sell_failed"})
                                    except Exception as _pfe:
                                        _log(f"pending: exit_failed autopsy queue err: {_pfe}",
                                             prefix="pending")
                            except Exception:
                                pass
                            for r in _legs:
                                r["_ledger_episode_written"] = True
                            changed = True
                    await asyncio.sleep(0.4)
                if changed:
                    _save_pending_confirmations(d)
        except Exception as e:
            _log(f"pending_confirmation_loop err: {e!r}", prefix="pending")
        await asyncio.sleep(20)


# ─── SELL-SUCCESS MONITOR (2026-07-30, the agent's exit item #4) ───────────────
# Sell-success is a FIRST-CLASS metric — an entry you cannot exit is a donation,
# and the number should reach the agent BETWEEN tune windows, not only when the 6h
# invitation fires. Every ~10min this reads the rolling 2h execution health and,
# if a real sample of sells is landing below threshold, drops a packet in his
# inbox (the owner's call: a packet, not a telegram). Timed-out submits that haven't
# resolved are `sell_pending` and are excluded from the rate, so this can't cry
# off unconfirmed sells the way the old 48% ruler did.
SELL_SUCCESS_ALERT_STATE     = _BOT_LOGS / "sell_success_alert_state.json"
SELL_SUCCESS_ALERT_THRESHOLD = 70        # the agent's <70%-over-2h bar
SELL_SUCCESS_ALERT_MIN_SAMPLE = 5        # need a real sample before alerting
SELL_SUCCESS_ALERT_COOLDOWN_S = 2 * 3600 # one bad hour shouldn't spam

async def sell_success_monitor_loop() -> None:
    _log("sell_success_monitor: starting (2h rolling; packet to inbox when <70% of a real sample)",
         prefix="exec")
    while True:
        try:
            eh = analyze_execution_health(hours=2)
            if eh.get("enough_data"):
                s = eh.get("sells", {}) or {}
                landed = int(s.get("landed") or 0)
                failed = int(s.get("FAILED") or 0)
                total  = landed + failed
                rate   = s.get("success_rate_pct")
                pending = int(eh.get("pending_confirmations") or 0)
                if (total >= SELL_SUCCESS_ALERT_MIN_SAMPLE and rate is not None
                        and rate < SELL_SUCCESS_ALERT_THRESHOLD):
                    _st = {}
                    try:
                        with open(SELL_SUCCESS_ALERT_STATE, encoding="utf-8-sig") as f:
                            _st = json.load(f) or {}
                    except Exception:
                        _st = {}
                    if _now_ts() - int(_st.get("last_alert_ts") or 0) >= SELL_SUCCESS_ALERT_COOLDOWN_S:
                        pkt = {
                            "_type": "sell_success_alert",
                            "lane": "queue",
                            "generated_at": _now_iso(),
                            "window_hours": 2,
                            "sell_success_pct": rate,
                            "sells_landed": landed,
                            "sells_failed": failed,
                            "sells_pending": pending,
                            "threshold_pct": SELL_SUCCESS_ALERT_THRESHOLD,
                            "note": ("Rolling 2h sell-success is below threshold — the EXIT PATH is the "
                                     "constraint this window, not entry filters. Timed-out submits still "
                                     "confirming are NOT counted here (sell_pending), so this is real "
                                     "landed-vs-failed. An entry you cannot exit is a donation."),
                            "operating_lean": ("probe-only size / skip clean edge passes until sell "
                                               "success recovers — but verify against the ledger, not "
                                               "one bad hour; the recent-24h headline is the honest read"),
                            "ask": "confirm the exit path is the issue this window; size accordingly",
                        }
                        try:
                            write_inbox_packet_generic(
                                pkt, prefix="meme_sniper",
                                identifier=f"sell_success_alert_{_now_ts()}")
                            _save_json_atomic(SELL_SUCCESS_ALERT_STATE,
                                              {"last_alert_ts": _now_ts(), "last_rate": rate})
                            _log(f"sell_success_monitor: ALERT packet written — 2h rate {rate}% "
                                 f"({landed}/{total} landed, {pending} pending)", prefix="exec")
                        except Exception as _we:
                            _log(f"sell_success_monitor: packet write err: {_we}", prefix="exec")
        except Exception as e:
            _log(f"sell_success_monitor loop err: {e!r}", prefix="exec")
        await asyncio.sleep(600)   # 10 min


# ─── BOOK-vs-WALLET RECONCILE (2026-07-26, the other half of the exit fix) ──
# The agent checked pnl.json: 31 closes, ALL pre-patch, post-patch sample empty.
# The consequence nobody has walked out yet: if a pre-patch sell was reported
# "failed" on a confirmation timeout but actually LANDED, then the bag is gone
# from the wallet while positions.json still shows it OPEN — a GHOST POSITION.
# Those ghosts are why the historical record can be wrong in BOTH directions:
# closes missing from pnl.json (understating the trade count) and phantom bags
# inflating the open book (so exit monitors chase air and "failures" repeat on
# a position that no longer exists). The pending tracker catches this going
# forward; this catches the ones that already happened. Truth is the wallet.
def load_hold_theses() -> dict:
    """All structured hold theses, keyed by mint. {} when absent or unreadable.

    RESTORED 2026-07-27. HOLD_THESES_FILE was declared at module level and this
    function was called from ten places — but it, save_hold_theses and
    get_hold_thesis were never defined anywhere in this file. The whole
    hold-thesis subsystem was wired in and had no implementation, so
    hold_theses.json has never been written or read. Worst site was the position
    manager, where get_hold_thesis() sat OUTSIDE a try block right after
    upsert_position(): the position was written, then the function died, so
    _write_horizon_decision_packet has never once fired. Found by pyflakes.
    """
    try:
        with open(HOLD_THESES_FILE, encoding="utf-8-sig") as f:
            return json.load(f) or {}
    except Exception:
        return {}


def save_hold_theses(theses: dict) -> bool:
    """Persist the thesis book. Atomic write — a torn hold_theses.json would
    silently empty the book on next read, which is exactly the failure this
    subsystem exists to prevent."""
    try:
        _tmp = str(HOLD_THESES_FILE) + ".tmp"
        with open(_tmp, "w", encoding="utf-8") as f:
            json.dump(theses or {}, f, indent=2, default=str)
        os.replace(_tmp, HOLD_THESES_FILE)
        return True
    except Exception as e:
        _log(f"save_hold_theses failed: {e!r}", prefix="hold")
        return False


def get_hold_thesis(mint: str) -> dict:
    """The thesis for one mint, or {} — callers use `get_hold_thesis(m) or {}`."""
    try:
        return (load_hold_theses() or {}).get(mint) or {}
    except Exception:
        return {}


GHOST_SETTLE_GRACE_S = 90      # don't ghost a book younger than this (chain settle)
GHOST_CONFIRM_READS  = 3       # consecutive empty reads before believing it
_GHOST_EMPTY_STREAK: dict = {}  # mint -> consecutive empty reads


def _ghost_state() -> dict:
    try:
        with open(_BOT_LOGS / "position_ghosts.json", encoding="utf-8-sig") as f:
            return json.load(f) or {}
    except Exception:
        return {}

async def position_wallet_reconcile_loop() -> None:
    """Every 10min: every OPEN position must still be in the wallet. If the
    tokens are gone, the bag was sold and the book missed it. Flags with the
    evidence — never invents a fill price, never silently rewrites the book
    (decision requests travel to the decider)."""
    _log("position_reconcile: starting (an open position must exist in the wallet)", prefix="reconcile")
    await asyncio.sleep(45)   # let the first scans settle
    while True:
        try:
            positions = load_positions() or {}
            open_pos = {m: p for m, p in positions.items()
                         if isinstance(p, dict) and p.get("status", "open") == "open"}
            if open_pos:
                # BUG 1 FIX 2026-07-27 (SimonCat): this compared the BOOKED RAW
                # amount against the wallet's UI amount — different units. SimonCat
                # booked 61,027,044,336 raw (~61k UI at 6dp), so the 2% threshold
                # was 1.22e9 and a FULL bag could never clear it. Every position
                # ghosted, guaranteed, the moment this loop looked at it.
                # Compare raw to raw. Keep UI only for human-readable output.
                _bal_rows = await get_wallet_token_balances() or []
                balances_raw = {b.get("mint"): float(b.get("amount_raw") or 0) for b in _bal_rows}
                balances_ui  = {b.get("mint"): float(b.get("ui_amount") or 0) for b in _bal_rows}
                ghosts = _ghost_state()
                changed = False
                for mint, pos in open_pos.items():
                    booked = float(pos.get("token_amount") or 0)   # RAW units
                    held = float(balances_raw.get(mint) or 0)      # RAW units
                    held_ui = float(balances_ui.get(mint) or 0)
                    if booked <= 0:
                        continue

                    # SETTLE GRACE (2026-07-27). A position is booked from the
                    # QUOTE the instant the buy returns; the token account can
                    # take a moment to appear to the RPC. Ghosting inside that
                    # window is guaranteed noise — the STEPAN buy ghosted seconds
                    # after landing. Give the chain a minute before disbelieving
                    # a fresh book.
                    try:
                        _opened = float(pos.get("bought_at_ts") or pos.get("opened_at_ts") or 0)
                        if not _opened and pos.get("bought_at"):
                            _opened = datetime.fromisoformat(
                                str(pos["bought_at"]).replace("Z", "")).timestamp()
                        if _opened and (_now_ts() - _opened) < GHOST_SETTLE_GRACE_S:
                            continue
                    except Exception:
                        pass

                    # CONSECUTIVE-READ REQUIREMENT. One empty read is an RPC
                    # opinion, not a fact. Require several in a row before
                    # calling a bag gone — a single lagging response used to be
                    # enough to flag a live position as a ghost.
                    if held < booked * 0.02:
                        _streak = _GHOST_EMPTY_STREAK.get(mint, 0) + 1
                        _GHOST_EMPTY_STREAK[mint] = _streak
                        if _streak < GHOST_CONFIRM_READS:
                            _log(f"reconcile: {pos.get('ticker') or mint[:8]} reads empty "
                                 f"({_streak}/{GHOST_CONFIRM_READS}) — waiting for confirmation",
                                 prefix="reconcile")
                            continue
                    else:
                        _GHOST_EMPTY_STREAK.pop(mint, None)
                    if held >= booked * 0.02:
                        if mint in ghosts:
                            ghosts.pop(mint, None); changed = True   # bag came back into view
                        continue
                    if mint in ghosts:
                        continue                                     # already reported
                    tick = pos.get("ticker") or mint[:8]
                    # look for the sell that actually landed, so the flag carries proof
                    evidence = []
                    try:
                        for sig, row in (_load_pending_confirmations() or {}).items():
                            if row.get("mint") == mint:
                                evidence.append({"tx": sig, "state": row.get("state"),
                                                  "submitted_at": row.get("submitted_at"),
                                                  # FIX 3: a late-landed leg is not just
                                                  # "evidence" - it is THE answer to why the
                                                  # bag is gone, and the late_landed packet
                                                  # this ghost repeats already named it.
                                                  "is_late_land": row.get("state") == "landed_late"})
                        evidence.sort(key=lambda e: not e.get("is_late_land"))
                    except Exception:
                        pass
                    ghosts[mint] = {"flagged_at": _now_iso(), "ticker": tick,
                                     "booked_tokens": booked, "wallet_tokens": held,
                                     "booked_raw": booked, "held_raw": held,
                                     "held_ui": held_ui, "unit_basis": "raw"}
                    changed = True
                    _log(f"reconcile: GHOST POSITION {tick} — book says {booked:.4f} tokens, "
                         f"wallet holds {held:.4f}. The bag is gone; the book missed the exit.",
                         prefix="reconcile")
                    try:
                        pkt = {"_type": "position_ghost", "generated_at": _now_iso(),
                                "mint": mint, "ticker": tick,
                                "book_says_open_tokens": booked, "wallet_actually_holds": held,
                                "landed_tx_evidence": evidence,
                                "late_landed_signatures": [e["tx"] for e in evidence
                                                            if e.get("is_late_land")],
                                "see_also": ("If late_landed_signatures is non-empty, a "
                                              "`late_landed_swap` packet was already written for "
                                              "that signature with needs_book_close set. This is "
                                              "the same bag, not a second incident."),
                                "why_this_happens": ("a sell reported FAILED on a confirmation timeout "
                                                      "that actually landed — the chain sold, the book "
                                                      "never heard. Pre-patch exits are the likely source."),
                                "ask": ("confirm from the tx evidence (or Solscan) and close this position "
                                         "in the book with the real fill, or tell me it's dust. Until it's "
                                         "closed, exit monitors are chasing a bag that isn't there and "
                                         "your close-count undercounts by one.")}
                        fn = _INBOX / f"meme_sniper - position_ghost_{tick}_{mint[:8]}.json"
                        with open(fn, "w", encoding="utf-8") as f:
                            json.dump(pkt, f, indent=2)
                        await send_telegram(
                            f"👻 <b>GHOST POSITION — {tick}</b>\n"
                            f"book: {booked:.4f} tokens · wallet: {held:.4f}\n"
                            f"The bag is gone — a reported 'failed' sell landed. "
                            f"Packet in inbox with tx evidence; close the book with the real fill.")
                    except Exception as _ge:
                        _log(f"ghost packet err: {_ge}", prefix="reconcile")
                if changed:
                    try:
                        with open(_BOT_LOGS / "position_ghosts.json", "w", encoding="utf-8") as f:
                            json.dump(ghosts, f, indent=2)
                    except Exception:
                        pass
        except Exception as e:
            _log(f"position_reconcile err: {e!r}", prefix="reconcile")
        await asyncio.sleep(600)


# ─── TREASURY LEDGER + LIQ-ZERO RECHECK (2026-07-24, the owner's holding system) ──
# The owner's design: ammo (SOL) is working capital; HOLDINGS are treasury. Tokens
# can arrive from anywhere (bought and converted to hold, or SENT directly —
# 1M GORK incoming). The ledger sees every SPL token in the wallet, marks it to
# market, shows it in packets, and gives the agent a sell_holding lane so the
# treasury can refund ammo — a LAST RESORT funding loop, his call, in words.
LIQ_ZERO_RECHECK_FILE = _BOT_LOGS / "liq_zero_recheck.json"
HOLDINGS_FILE = _BOT_LOGS / "holdings.json"
WALLET_BALANCE_FILE = _BOT_LOGS / "wallet_balance.json"
_TREASURY_CACHE = {"summary": None, "at": 0}
_WSOL_MINT = "So11111111111111111111111111111111111111112"

def _read_open_position_mints() -> set:
    try:
        import importlib
        # positions store read via the module's own loader if present
        return set((load_positions() or {}).keys()) if "load_positions" in globals() else set()
    except Exception:
        return set()

async def _read_home_base() -> Optional[dict]:
    """OWNER'S HOME BASE (2026-07-24): the hardcoded ledger wallet — where
    weekly profits get swept (ledger_sweep, manual-fire). Not ammo, not the
    in-wallet treasury: this is the VAULT, the scoreboard of banked wins.
    Wherever the agent sees his wallet balance, he sees home base beside it."""
    # 2026-10-15: LEDGER_ADDRESS is optional - unset meant getBalance("") +
    # getTokenAccountsByOwner("") -> RPC "WrongSize" errors every packet build.
    if not LEDGER_ADDR:
        return None
    try:
        hb = {"address": LEDGER_ADDR[:6] + ".." + LEDGER_ADDR[-4:], "sol_balance": None,
               "holdings": [], "total_holdings_usd": 0.0,
               "meaning": ("HOME BASE — the empire's vault. Weekly realized profits get swept "
                            "here (ledger_sweep, your manual fire). It is NOT ammo and the bot "
                            "cannot spend it. Watching it grow is the scoreboard that matters.")}
        r = await helius_rpc("getBalance", [LEDGER_ADDR, {"commitment": "confirmed"}])
        if isinstance(r, dict) and r.get("value") is not None:
            hb["sol_balance"] = round(int(r["value"]) / 1_000_000_000, 4)
        tr = await helius_rpc("getTokenAccountsByOwner",
                                [LEDGER_ADDR, {"programId": "TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA"},
                                 {"encoding": "jsonParsed", "commitment": "confirmed"}])
        toks = (tr or {}).get("value") or []
        total = 0.0
        for t in toks[:12]:
            try:
                info = t["account"]["data"]["parsed"]["info"]
                amt = float(info["tokenAmount"].get("uiAmount") or 0)
                mint = info.get("mint")
                if amt <= 0 or not mint:
                    continue
                px = None; tick = mint[:6]
                try:
                    pairs = await fetch_dex_search(mint)
                    if pairs:
                        px = _safe_num(pairs[0].get("priceUsd"))
                        tick = (pairs[0].get("baseToken") or {}).get("symbol", tick)
                except Exception:
                    pass
                usd = round(amt * px, 2) if px else None
                if usd is not None and usd < 1.0:
                    continue
                hb["holdings"].append({"ticker": tick, "mint": mint[:8], "amount_ui": amt, "est_usd": usd})
                if usd:
                    total += usd
                await asyncio.sleep(0.4)
            except Exception:
                continue
        hb["total_holdings_usd"] = round(total, 2)
        return hb
    except Exception as e:
        _log(f"home_base read err: {e!r}", prefix="treasury")
        return None


async def holdings_treasury_loop() -> None:
    """Every 30min: enumerate wallet SPL tokens (minus open positions, wSOL,
    dust), mark to market, write holdings.json + the wallet_balance heartbeat
    (The agent's ops patch 1 — the april-frozen file gets a live writer again).
    Every 12h: a holdings_report packet so the treasury is never invisible."""
    _log("treasury: ledger loop starting (holdings are the treasury)", prefix="treasury")
    _last_report = 0.0
    # 2026-10-15: honor the 12h across reloads - seed from the newest report on disk
    try:
        _rep_files = list(_INBOX.glob("meme_sniper - holdings_report_*.json"))
        _rep_files += list((_INBOX.parent / "inbox_results" / "done").glob("meme_sniper - holdings_report_*.json"))
        if _rep_files:
            _last_report = max(p.stat().st_mtime for p in _rep_files)
    except Exception as _lre:
        _log(f"holdings report seed err: {_lre}", prefix="treasury")
    while True:
        try:
            toks = await get_wallet_token_balances()
            pos_mints = _read_open_position_mints()
            holdings = {}
            try:
                with open(HOLDINGS_FILE, encoding="utf-8-sig") as f:
                    holdings = json.load(f) or {}
            except Exception:
                pass
            seen = set()
            total_usd = 0.0
            _prev_snapshot = dict(holdings)   # snapshot for event detection after the sweep
            for b in toks or []:
                mint = b.get("mint")
                if not mint or mint == _WSOL_MINT:
                    continue
                if mint in pos_mints:
                    # 2026-10-20: an own-launch treasury row shares its mint with the open
                    # sellable position; keep it instead of dropping it below.
                    if (holdings.get(mint) or {}).get("own_launch"):
                        seen.add(mint)
                    continue
                amt = float(b.get("amount_ui") or (float(b.get("amount_raw") or 0) / (10 ** int(b.get("decimals") or 0)) if b.get("decimals") is not None else 0))
                if amt <= 0:
                    continue
                prev = holdings.get(mint) or {}
                _is_stable = mint in _STABLECOIN_MINTS
                px = None; tick = _STABLECOIN_MINTS.get(mint, "?")
                try:
                    # Token CA endpoint first (highest-liq pair); search is fallback only.
                    pair = await fetch_token_data(mint)
                    if not pair:
                        _pairs = await fetch_dex_search(mint)
                        pair = _pairs[0] if _pairs else None
                    if pair:
                        px = _safe_num(pair.get("priceUsd"))
                        _t = (pair.get("baseToken") or {}).get("symbol", "?")
                        # ── FIX 6 (2026-08-16): A STABLE KEEPS ITS NAME ─────────
                        # `tick` is seeded correctly from _STABLECOIN_MINTS, then
                        # this overwrote it with whatever symbol the Dex lookup
                        # returned. On a TRUMP/USDC pair that resolves USDC as the
                        # base leg, the USDC mint gets relabelled TRUMP - which is
                        # what holdings.json actually shows right now. treasury_usd
                        # is then a dollar balance wearing a memecoin ticker, and a
                        # treasury read looks like a concentrated meme bag.
                        # The mint is the identity; a pair symbol is not allowed to
                        # rename it.
                        if _t and _t != "?" and not _is_stable:
                            tick = _t
                except Exception:
                    pass
                if _is_stable:
                    px = 1.0   # livefix: stables are $1. The top pair often has the stable
                               # as QUOTE, so priceUsd was the other coin's price (USDC=$0.005).
                # MTM quality (the agent B4): DexScreener → last good mark; a miss is a
                # tracked mark_fail_streak, not a silent zero. Ticker is sticky —
                # never overwrite a real symbol with "?".
                _mark_fail = int(prev.get("mark_fail_streak", 0))
                if px is None:
                    px = prev.get("est_price")   # last good mark
                    _mark_fail += 1
                else:
                    _mark_fail = 0
                usd = round(amt * px, 2) if px else None
                # dust drop only on a REAL mark under $1 (a null-mark bag stays as a
                # residual candidate rather than vanishing between reports).
                if usd is not None and usd < 1.0 and not _is_stable:
                    continue
                _fsp = prev.get("first_seen_price")
                if _fsp is None and px:
                    _fsp = px
                _peak = prev.get("peak_price") or 0
                if px and px > (_peak or 0):
                    _peak = px
                _cls = prev.get("class") or ("stablecoin" if _is_stable else "watch_bag")
                holdings[mint] = {
                    "ticker": tick if tick != "?" else prev.get("ticker", "?"),
                    "amount_ui": amt,
                    "est_price": px,
                    "est_usd": usd,
                    "first_seen": prev.get("first_seen") or _now_iso(),
                    "first_seen_ts": prev.get("first_seen_ts") or _now_ts(),
                    "first_seen_price": _fsp,
                    "peak_price": _peak or px,
                    "class": _cls,
                    "thesis": prev.get("thesis", ""),         # the agent's words survive re-marks
                    "falsifier": prev.get("falsifier", ""),
                    "source": prev.get("source", "wallet_sync"),
                    "mark_fail_streak": _mark_fail,
                    "last_event": prev.get("last_event"),
                    "last_event_at": prev.get("last_event_at"),
                    "last_mtm": _now_iso(),
                    **{k: prev[k] for k in _OL_HOLDING_EXTRA_KEYS if k in prev},
                }
                seen.add(mint)
                if usd:
                    total_usd += usd
                await asyncio.sleep(0.5)
            # drop holdings no longer in the wallet
            for m in [m for m in holdings if m not in seen]:
                holdings.pop(m, None)
            HOLDINGS_FILE.parent.mkdir(parents=True, exist_ok=True)
            with open(HOLDINGS_FILE, "w", encoding="utf-8") as f:
                json.dump(holdings, f, indent=2)
            # The agent B2: the treasury's interrupt surface — pop/dump/residual/new/
            # thesis-missing packets between the 12h reports.
            await _emit_holding_events(_prev_snapshot, holdings)
            try:
                await _owner_pos_scan(_prev_snapshot, holdings)
            except Exception as _ope:
                _log(f"owner_position scan err: {_ope!r}", prefix="owner_pos")
            _TREASURY_CACHE["summary"] = {
                "total_usd": round(total_usd, 2),
                "n_holdings": len(holdings),
                "top": sorted(({"ticker": (h.get("ticker") if h.get("ticker") not in (None, "", "?") else m[:8]),
                                  "est_usd": h.get("est_usd"),
                                  "mint": m[:8], **({} if h.get("est_price") else {"note": "no price/pool"})}
                                 for m, h in holdings.items()),
                                key=lambda x: x.get("est_usd") or 0, reverse=True)[:5],
                "note": ("treasury is the agent's bag: hold indefinitely; sell_holding "
                          "refunds ammo as a LAST RESORT (his call, in words)"),
            }
            _TREASURY_CACHE["at"] = _now_ts()
            # HOME BASE rides beside the wallet everywhere (the owner 2026-07-24)
            try:
                _TREASURY_CACHE["home_base"] = await _read_home_base()
            except Exception:
                pass
            # wallet_balance heartbeat (the agent's ops patch 1)
            try:
                # FIX 6 (2026-08-16): was a raw open(..., "w"). positions.json has
                # used _save_json_atomic for exactly this reason - a crash or a
                # concurrent read mid-write leaves a truncated file, and the
                # reader of THIS one is the ammo number. A torn balance parses as
                # missing (or worse, as a smaller number) on the file every
                # sizing decision consults. Same write, atomic.
                sol = await _wallet_sol_balance()
                _save_json_atomic(WALLET_BALANCE_FILE, {
                    "balance_sol": sol, "updated_at": _now_iso(),
                    "source": "sniper_treasury_heartbeat",
                    "treasury_usd": round(total_usd, 2),
                    "home_base": _TREASURY_CACHE.get("home_base"),
                    "note": "live writer restored 2026-07-24 (the agent ops patch 1); age >60m = treat as untrusted",
                })
            except Exception as _we:
                _log(f"wallet heartbeat err: {_we}", prefix="treasury")
            # 12h report packet
            if _now_ts() - _last_report > 12 * 3600 and holdings:
                _last_report = _now_ts()
                try:
                    rep_pkt = {"_type": "holdings_report", "generated_at": _now_iso(),
                                "treasury": _TREASURY_CACHE["summary"], "holdings": holdings,
                                "home_base": _TREASURY_CACHE.get("home_base"),
                                "ask": ("weekly-style review: for each holding, one line — still hold "
                                         "(why) or trim. A thesis-less bag is a zombie; write the thesis "
                                         "into your response and it persists on the ledger.")}
                    fn = _INBOX / f"meme_sniper - holdings_report_{datetime.now().strftime('%Y%m%d_%H%M')}.json"
                    with open(fn, "w", encoding="utf-8") as f:
                        json.dump(rep_pkt, f, indent=2)
                except Exception:
                    pass
        except Exception as e:
            _log(f"treasury loop err: {e!r}", prefix="treasury")
        await asyncio.sleep(get_override_sync("TREASURY_TICK_SECONDS", 1800))

HEAL_WATCH_FILE = _BOT_LOGS / "heal_watch.json"
HEAL_WATCH_MAX = 80
HEAL_WATCH_TTL_HOURS = 48          # hours to 2 days, NOT 3x5min death
HEAL_WATCH_FIRST_CHECK_S = 15 * 60
HEAL_WATCH_RECHECK_S = 30 * 60
HEAL_WATCH_REASONS = ("liq_zero", "liq_zero_pending_recheck", "mcap_below_floor")


def _heal_named_gate_inputs(extra_note: Optional[str] = None) -> dict:
    return _decision_inputs(
        [
            {"action_type": "fire_buy_signal",
             "when_this_fits": "named dual-gate: structure + map still work after heal"},
            {"action_type": "ignore",
             "when_this_fits": "named ignore: write why this still does not qualify"},
        ],
        note=(extra_note or
              "HEAL RECHECK — requires a named dual-gate call or a named ignore. "
              "Silent pass is not valid."),
    )


def _load_heal_watch() -> dict:
    try:
        with open(HEAL_WATCH_FILE, encoding="utf-8-sig") as f:
            data = json.load(f) or {}
        if isinstance(data, dict):
            data.pop("_meta", None)
            return data
    except Exception:
        pass
    return {}


def _save_heal_watch(state: dict) -> None:
    _save_json_atomic(HEAL_WATCH_FILE, state)


def _enqueue_heal_watch(mint: str, *, ticker: str = None, scan_mcap=None,
                        scan_price=None, skip_reason: str = None) -> None:
    """Frozen first-scan baseline. Hours-to-2-days heal, not a 3x5min death."""
    if not mint:
        return
    # livefix: no pool yet (mcap 0 AND no price) = nothing to heal or observe.
    if not _safe_num(scan_mcap) and not _safe_num(scan_price):
        return
    if not _ticker_clone_ok(ticker, mint):
        return
    try:
        state = _load_heal_watch()
        prev = state.get(mint) or {}
        now_iso, now_ts = _now_iso(), _now_ts()
        if prev:
            # keep the first-scan freeze; only refresh last_seen
            prev["last_seen"] = now_iso
            if skip_reason and not prev.get("skip_reason"):
                prev["skip_reason"] = skip_reason
            if (prev.get("scan_mcap") in (None, 0, 0.0)) and scan_mcap:
                prev["scan_mcap"] = _safe_num(scan_mcap)
            if (prev.get("scan_price") in (None, 0, 0.0)) and scan_price:
                prev["scan_price"] = _safe_num(scan_price)
            if ticker and (not prev.get("ticker") or prev.get("ticker") == "?"):
                prev["ticker"] = ticker
            state[mint] = prev
        else:
            if len(state) >= HEAL_WATCH_MAX:
                oldest = sorted(state, key=lambda m: state[m].get("first_ts") or 0)
                for k in oldest[: max(1, len(state) - HEAL_WATCH_MAX + 1)]:
                    state.pop(k, None)
            state[mint] = {
                "mint": mint,
                "ticker": ticker or "?",
                "scan_mcap": _safe_num(scan_mcap),
                "scan_price": _safe_num(scan_price),
                "skip_reason": skip_reason,
                "first_seen": now_iso,
                "first_ts": now_ts,
                "last_seen": now_iso,
                "last_recheck_at": None,
                "last_recheck_ts": 0,
                "attempts": 0,
            }
        _save_heal_watch(state)
        try:
            watchlist_add(mint, {
                "ticker": ticker,
                "mcap": scan_mcap,
                "price_usd": scan_price,
            })
        except Exception:
            pass
        _log(f"heal_watch queued {ticker or mint[:8]} reason={skip_reason} "
             f"mcap={scan_mcap} price={scan_price}", prefix="lzrc")
        try:
            subscribe_missed_runner(mint, {
                "scan_mcap": _safe_num(scan_mcap) or 0,
                "ticker": ticker or "?",
                "_source": "heal",
            }, float(_safe_num(scan_mcap) or 0))
            append_miss_book("heal_recovery", mint, {
                "ticker": ticker or "?",
                "source": "heal",
                "skip_reason": skip_reason,
            })
        except Exception as _hse:
            _log(f"heal_watch subscribe/miss_book err: {_hse!r}", prefix="lzrc")
    except Exception as e:
        _log(f"heal_watch enqueue err: {e!r}", prefix="lzrc")


async def _why_builder_skipped(mint: str, pair: dict = None) -> str:
    try:
        if pair is None:
            pair = await fetch_token_data(mint)
    except Exception:
        pair = None
    if not pair:
        return "no_dex_pair_data"
    mcap = float(pair.get("marketCap") or pair.get("fdv") or 0)
    liq = float((pair.get("liquidity") or {}).get("usd") or 0)
    try:
        floor = float(get_override_sync("MCAP_FLOOR_USD", MCAP_FLOOR_USD) or MCAP_FLOOR_USD)
    except Exception:
        floor = float(MCAP_FLOOR_USD)
    if mcap < floor:
        return "mcap_below_floor"
    if liq < 1.0:
        return "liq_zero_pending_recheck" if mcap >= floor else "liq_zero"
    return "builder_returned_none"


async def _emit_heal_recovery_packet(mint: str, w: dict, pair: dict, *, via: str) -> None:
    """Real meme_candidate / heal_recheck packet. Never a thin _type stub. Never silent None."""
    ticker = (
        ((pair.get("baseToken") or {}).get("symbol") if pair else None)
        or w.get("ticker")
        or "?"
    )
    liq = _safe_num((pair.get("liquidity") or {}).get("usd")) if pair else 0
    mcap = _safe_num(pair.get("marketCap") or pair.get("fdv")) if pair else 0
    price = _safe_num(pair.get("priceUsd")) if pair else None
    why = None
    pkt = None
    try:
        pkt = await build_meme_candidate_packet({"tokenAddress": mint}, surfaced_via=via)
    except Exception as e:
        why = f"builder_exception:{e!r}"[:180]
        pkt = None
    if pkt:
        ctx = pkt.setdefault("context", {})
        ctx[via] = {
            "mint": mint,
            "ticker": ticker,
            "skip_reason": w.get("skip_reason") or via,
            "scan_mcap": w.get("scan_mcap") or w.get("mcap_at_skip"),
            "scan_price": w.get("scan_price"),
            "first_seen": w.get("first_seen"),
            "now_liq": liq,
            "now_mcap": mcap,
            "now_price": price,
        }
        existing = pkt.get("decision_inputs") or {}
        opts = list(existing.get("options") or [])
        have = {o.get("action_type") for o in opts if isinstance(o, dict)}
        if "fire_buy_signal" not in have:
            opts.append({"action_type": "fire_buy_signal",
                         "when_this_fits": "named dual-gate: structure + map still work after heal"})
        if "ignore" not in have:
            opts.append({"action_type": "ignore",
                         "when_this_fits": "named ignore: write why this still does not qualify"})
        pkt["decision_inputs"] = _decision_inputs(
            opts,
            note="HEAL RECHECK — requires a named dual-gate call or a named ignore. "
                 "Silent pass is not valid.",
        )
        pkt["priority"] = "high"
        write_meme_candidate_packet(pkt)
        _log(f"heal RECOVERED {ticker} via={via} liq=${(liq or 0):,.0f} "
             f"mcap=${(mcap or 0):,.0f}", prefix="lzrc")
        return
    if not why:
        why = await _why_builder_skipped(mint, pair)
    write_inbox_packet_generic({
        "id": f"x_evt_heal_recheck_{mint[:8]}_{int(_now_ts())}",
        "type": "meme_candidate",
        "owner_rules": _owner_rules_ctx(),
        "subtype": "heal_recheck",
        "via": via,
        "generated_at": _now_iso(),
        "received_at": _now_iso(),
        "priority": "high",
        "mint": mint,
        "ticker": ticker,
        "skip_reason": w.get("skip_reason"),
        "why_builder_skipped": why,
        "first_scan": {
            "mcap": w.get("scan_mcap") or w.get("mcap_at_skip"),
            "price": w.get("scan_price"),
            "first_seen": w.get("first_seen"),
            "skip_reason": w.get("skip_reason"),
        },
        "now": {
            "mcap": mcap,
            "liq": liq,
            "price": price,
            "vol_24h": _safe_num((pair.get("volume") or {}).get("h24")) if pair else None,
            "chg_1h": _safe_num((pair.get("priceChange") or {}).get("h1")) if pair else None,
        },
        "context": {
            "mint": mint,
            "ticker": ticker,
            "heal_recheck": True,
            "why_builder_skipped": why,
            # 2026-10-15: heal cards carry the projection map too (doctrine: no map, no buy)
            **_phase_map_fields({
                "mcap": mcap,
                "price_change_5m": _safe_num((pair.get("priceChange") or {}).get("m5")) if pair else None,
                "price_change_1h": _safe_num((pair.get("priceChange") or {}).get("h1")) if pair else None,
                "price_change_24h": _safe_num((pair.get("priceChange") or {}).get("h24")) if pair else None,
                "volume_1h": _safe_num((pair.get("volume") or {}).get("h1")) if pair else None,
                "volume_24h": _safe_num((pair.get("volume") or {}).get("h24")) if pair else None,
                "peak_mcap": w.get("scan_mcap") or w.get("mcap_at_skip"),
            }),
        },
        "decision_inputs": _heal_named_gate_inputs(),
        "_doctrine": (
            "HEAL RECHECK. First-scan baseline is frozen. This is a second look after "
            "liq/mcap recovered, not a thin stub and not a silent skip. Named dual-gate "
            "or named ignore required."
        ),
    }, prefix=f"heal_recheck_{ticker}", identifier=f"{mint[:8]}_{int(_now_ts())}")
    _log(f"heal RECOVERED (builder none) {ticker} why={why}", prefix="lzrc")


def _lzrc_enqueue(mint: str, ticker: Optional[str], reason: str) -> bool:
    try:
        _lz = {}
        try:
            with open(LIQ_ZERO_RECHECK_FILE, encoding="utf-8-sig") as _lf:
                _lz = json.load(_lf) or {}
        except Exception:
            pass
        if mint in _lz or len(_lz) >= LZRC_MAX_QUEUE:
            return False
        _lz[mint] = {"first_seen": _now_iso(), "first_ts": _now_ts(), "attempts": 0,
                     "ticker": ticker or "?", "skip_reason": reason}
        _save_json_atomic(LIQ_ZERO_RECHECK_FILE, _lz)
        _log(f"lzrc: queued {ticker or mint[:8]} for re-card when liquidity returns ({reason})", prefix="lzrc")
        return True
    except Exception as e:
        _log(f"lzrc enqueue err: {e}", prefix="lzrc")
        return False


async def liq_zero_recheck_loop() -> None:
    """Bond-race short look + hours-to-2-day heal watch.
    Recovered → real meme_candidate/heal_recheck via builder. Never 3x5min death."""
    _log("liq_zero_recheck: starting (a bond race is not a death; heal watch is hours-to-2d)", prefix="lzrc")
    while True:
        if await _rpc_pause_if_unhealthy("liq_zero_recheck"):   # 2026-10-14
            continue
        try:
            _lz = {}
            try:
                with open(LIQ_ZERO_RECHECK_FILE, encoding="utf-8-sig") as f:
                    _lz = json.load(f) or {}
            except Exception:
                pass
            changed = False
            recovered = confirmed = 0
            for mint, w in list(_lz.items()):
                if _now_ts() - (w.get("first_ts") or 0) < 300 * (w.get("attempts", 0) + 1):
                    continue   # not due yet (5min spacing per attempt)
                w["attempts"] = int(w.get("attempts", 0)) + 1
                changed = True
                pair = None
                try:
                    pairs = await fetch_dex_search(mint)
                    pair = pairs[0] if pairs else None
                except Exception:
                    pass
                liq = _safe_num((pair.get("liquidity") or {}).get("usd")) if pair else 0
                if pair and liq and liq >= LIQ_RECARD_MIN_USD:
                    recovered += 1
                    w.setdefault("skip_reason", "liq_zero_pending_recheck")
                    w.setdefault("scan_mcap", w.get("mcap_at_skip"))
                    await _emit_heal_recovery_packet(mint, w, pair, via="liq_zero_recheck")
                    _lz.pop(mint, None)
                elif w["attempts"] >= 3:
                    # not a death - hand off to hours-to-2-day heal watch
                    confirmed += 1
                    _enqueue_heal_watch(
                        mint,
                        ticker=w.get("ticker"),
                        scan_mcap=w.get("scan_mcap") or w.get("mcap_at_skip"),
                        scan_price=w.get("scan_price"),
                        skip_reason=w.get("skip_reason") or "liq_zero_pending_recheck",
                    )
                    _log(f"lzrc handoff to heal_watch: {w.get('ticker')} ({mint[:8]}) after {w['attempts']} short looks",
                         prefix="lzrc")
                    _lz.pop(mint, None)
                await asyncio.sleep(1.0)
            if changed:
                _save_json_atomic(LIQ_ZERO_RECHECK_FILE, _lz)
            # HEAL WATCH (hours to 2 days)
            hw = _load_heal_watch()
            hw_changed = False
            hw_recovered = hw_expired = 0
            try:
                floor = float(get_override_sync("MCAP_FLOOR_USD", MCAP_FLOOR_USD) or MCAP_FLOOR_USD)
            except Exception:
                floor = float(MCAP_FLOOR_USD)
            now_ts = _now_ts()
            for mint, w in list(hw.items()):
                age = now_ts - float(w.get("first_ts") or 0)
                if age > HEAL_WATCH_TTL_HOURS * 3600:
                    hw.pop(mint, None)
                    hw_expired += 1
                    hw_changed = True
                    continue
                last = float(w.get("last_recheck_ts") or 0)
                first_due = age >= HEAL_WATCH_FIRST_CHECK_S
                rec_due = (now_ts - last) >= HEAL_WATCH_RECHECK_S
                if not first_due or (last and not rec_due):
                    continue
                pair = None
                try:
                    pair = await fetch_token_data(mint)
                    if not pair:
                        pairs = await fetch_dex_search(mint)
                        pair = pairs[0] if pairs else None
                except Exception:
                    pair = None
                w["attempts"] = int(w.get("attempts", 0)) + 1
                w["last_recheck_at"] = _now_iso()
                w["last_recheck_ts"] = now_ts
                hw_changed = True
                liq = _safe_num((pair.get("liquidity") or {}).get("usd")) if pair else 0
                mcap = _safe_num(pair.get("marketCap") or pair.get("fdv")) if pair else 0
                if pair and (liq or 0) >= LIQ_RECARD_MIN_USD and (mcap or 0) >= floor:
                    await _emit_heal_recovery_packet(mint, w, pair, via="heal_recheck")
                    hw.pop(mint, None)
                    hw_recovered += 1
                await asyncio.sleep(1.0)
            if hw_changed:
                _save_heal_watch(hw)
            if recovered or confirmed or hw_recovered or hw_expired:
                _log(f"lzrc cycle: recovered={recovered} heal_handoff={confirmed} "
                     f"heal_recovered={hw_recovered} heal_expired={hw_expired}", prefix="lzrc")
        except Exception as e:
            _log(f"liq_zero_recheck err: {e!r}", prefix="lzrc")
        await asyncio.sleep(300)

@_meme_inflight
async def execute_sell_holding(sig: dict) -> None:
    """The owner's funding loop: The agent sells treasury → SOL ammo. LAST RESORT lane —
    the doctrine lives in the skill; this just executes his words faithfully."""
    mint = sig.get("mint"); frac = float(sig.get("fraction", 1.0))
    try:
        holdings = {}
        try:
            with open(HOLDINGS_FILE, encoding="utf-8-sig") as f:
                holdings = json.load(f) or {}
        except Exception:
            pass
        h = holdings.get(mint)
        if not h:
            await write_signal_response(sig.get("signal_id", _now_iso()), "sell_holding_failed",
                                          error=f"{mint} not on the holdings ledger")
            return {"ok": False, "error": "not_on_ledger"}
        if mint in _read_open_position_mints() and h.get("own_launch") and frac >= 0.999:
            # 2026-10-20: own launch full exit = close the sellable position, then the
            # wallet-raw sell below takes everything left (treasury included).
            _sub = f"{sig.get('signal_id', _now_iso())}-pos"
            try:
                _SIGNAL_META[_sub] = {"ticker": h.get("ticker"), "mint": mint, "fraction": 1.0}
            except Exception:
                pass
            await execute_sell_signal({"signal_id": _sub, "mint": mint, "amount_pct": 100,
                                       "reason": "forced: own-launch full exit via sell_holding"})
            await asyncio.sleep(3)
        if mint in _read_open_position_mints():
            await write_signal_response(sig.get("signal_id", _now_iso()), "sell_holding_failed",
                                          error="that mint is an OPEN POSITION — use the normal sell lane")
            return {"ok": False, "error": "open_position"}
        # ── RAW-UNIT FIX + PROOF GATE (2026-08-09) ──────────────────────────
        # THE BUG: this fed `amount_ui` straight into jupiter_swap_sell, whose
        # contract is RAW UNITS. For a 6-decimal pump token that is off by 1e6 - a
        # "full" residual sell became a dust-sized raw order. It then acked
        # sell_holding_executed off a success-ish dict while the bag sat untouched.
        #
        # Tusk receipt: harvest acked executed, ~103,556 ui (~$4.59) stayed on the
        # wallet, and a later force chain-raw sell landed +0.051447 SOL for real.
        # A FALSE SUCCESS IS WORSE THAN A HARD FAIL - a hard fail gets retried, a
        # false success gets believed, and the ledger drifts from the chain.
        #
        # Two fixes, and the second matters as much as the first: sell in RAW, and
        # do not call it executed until the CHAIN says the bag actually moved.
        frac = max(0.0, min(1.0, frac))
        _ui_ledger = float(h.get("amount_ui") or 0)

        # 1. CHAIN TRUTH FIRST. The wallet knows what is really there; the ledger
        #    only knows what it was told. When they disagree, the wallet wins.
        raw_before, _dec = await _wallet_token_raw(mint)
        decimals = int(_dec or 0)
        if raw_before > 0:
            sell_raw = raw_before * frac
            _size_src = "wallet_raw"
        else:
            # 2. Ledger fallback, converted properly this time.
            if not decimals:
                try:
                    decimals = int(await get_mint_decimals(mint) or 6)
                except Exception:
                    decimals = 6
            _raw_ledger = float(h.get("amount_raw") or 0)   # optional future field
            if _raw_ledger > 0:
                sell_raw = _raw_ledger * frac
                _size_src = "ledger_raw"
            else:
                sell_raw = (_ui_ledger * frac) * (10 ** decimals)
                _size_src = f"ledger_ui_x10^{decimals}"

        if sell_raw <= 0:
            await write_signal_response(sig.get("signal_id", _now_iso()), "sell_holding_failed",
                                          error=(f"nothing to sell at fraction {frac} "
                                                 f"(wallet raw {raw_before}, ledger ui {_ui_ledger})"))
            return {"ok": False, "error": "nothing_to_sell"}

        # force=True: residual / harvest / funding-loop exits are forced outs, same
        # as a full position exit - the preflight veto exists to stop a bad ENTRY,
        # not to argue with the owner about leaving.
        res = await jupiter_swap_sell(mint, sell_raw, force=True)
        _tx = (res or {}).get("tx") or (res or {}).get("signature") or (res or {}).get("tx_signature")
        _claimed = bool(res and (res.get("success") or _tx))

        # 3. PROOF GATE. Never trust the swap's own word. Re-read the wallet and
        #    require the bag to have actually moved by roughly what we asked for.
        raw_after, _ = await _wallet_token_raw(mint)
        _dust_raw = max(1.0, (10 ** max(0, decimals - 4)))   # ~0.0001 of a token
        _moved = max(0.0, raw_before - raw_after) if raw_before > 0 else 0.0
        if frac >= 0.99:
            _proved = (raw_after <= _dust_raw) or (_moved >= sell_raw * 0.90)
        else:
            _proved = _moved >= sell_raw * 0.80      # fees/rounding tolerance
        ok = bool(_claimed and _tx and _proved)

        _detail = {
            "amount_ui_ledger":  _ui_ledger,
            "amount_raw_sold":   round(sell_raw, 2),
            "amount_raw_before": round(raw_before, 2),
            "amount_raw_after":  round(raw_after, 2),
            "amount_raw_moved":  round(_moved, 2),
            "decimals":          decimals,
            "size_source":       _size_src,
            "fraction":          frac,
            "tx_signature":      _tx,
            "sol_received":      (res or {}).get("sol_received"),
            "sol_received_source": (res or {}).get("sol_received_source"),
        }
        _log(f"sell_holding {h.get('ticker')} frac={frac} raw={sell_raw:.0f} "
             f"({_size_src}) before={raw_before:.0f} after={raw_after:.0f} "
             f"-> {'OK' if ok else 'FAILED'} tx={str(_tx)[:16]}", prefix="treasury")

        _sol = (res or {}).get("sol_received")
        try:
            _sol_f = float(_sol) if _sol is not None else None
        except (TypeError, ValueError):
            _sol_f = None
        _price = None
        if _sol_f and _moved > 0 and decimals >= 0:
            _ui_moved = _moved / (10 ** decimals)
            if _ui_moved > 0:
                _price = _sol_f / _ui_moved
        try:
            exec_log(
                "sell" if ok else "sell_failed",
                ticker=h.get("ticker"),
                mint=mint,
                amount_sol=_sol_f,
                price=_price,
                tx=_tx,
                detail=(
                    f"sell_holding fraction={frac} proved={ok} "
                    f"raw_moved={_moved:.0f} src={_size_src}"
                ),
            )
        except Exception:
            pass
        if ok:
            try:
                _ui_left = (raw_after / (10 ** decimals)) if decimals >= 0 else None
                h["amount_raw"] = raw_after
                if _ui_left is not None:
                    h["amount_ui"] = _ui_left
                if h.get("est_usd") and raw_before > 0:
                    h["est_usd"] = round(float(h["est_usd"]) * (raw_after / raw_before), 4)
                h["last_event"] = "harvest_partial" if frac < 0.99 else "harvest_full"
                h["last_event_at"] = _now_iso()
                h["last_harvest_tx"] = _tx
                holdings[mint] = h
                _save_holdings(holdings)
            except Exception as _he:
                _log(f"sell_holding holdings update err: {_he!r}", prefix="treasury")
            await write_signal_response(sig.get("signal_id", _now_iso()),
                                          "sell_holding_executed", details=_detail)
        else:
            # Name WHICH failure. "claimed success but the bag is still here" is a
            # completely different problem from "the swap errored", and collapsing
            # them is how the Tusk false-success hid for a full cycle.
            if _claimed and not _proved:
                _err = (f"sell_success_without_proof - swap reported success but the bag is "
                        f"still held: raw before {raw_before:.0f} -> after {raw_after:.0f} "
                        f"(intended {sell_raw:.0f}). Holdings row KEPT. tx={_tx}")
            elif _claimed and not _tx:
                _err = "sell_success_without_proof - success flag with no tx signature"
            else:
                _err = f"swap failed: {str(res)[:250]}"
            await write_signal_response(sig.get("signal_id", _now_iso()),
                                          "sell_holding_failed", error=_err, details=_detail)
        return {
            "ok": ok,
            "tx": _tx,
            "sol_received": _sol_f,
            "price": _price,
            "fraction": frac,
            "raw_moved": _moved,
        }
    except Exception as e:
        _log(f"sell_holding err: {e!r}", prefix="treasury")
        return {"ok": False, "error": repr(e)}


# ═══════════════════════════════════════════════════════════════════════════
# HOLDINGS BRIDGE (2026-07-30, the agent's P2 proposal) — treasury ↔ positions
# ═══════════════════════════════════════════════════════════════════════════
# A holding is a wallet SPL with no sniper buy-book — NOT a position. The bridge
# gives the agent a nervous system (holding_event alerts between the 12h reports)
# and a way to ACT on a bag: classify it, write a thesis, harvest it to ammo, or
# PROMOTE it into a managed position from chain-truth balance — never a fake buy.
# Doctrine (auto-buy off, home base untouchable, edge=reference, hold-mode gates)
# is unchanged; this is a mechanism for authority the owner already granted.
# 2026-08-07: `treasury` added (code_tuner patch, LOW risk, allowlist expand only).
# The agent fired classify_holding with class=treasury for $GORK and the sniper
# rejected it as unknown - the intent was right and the word was already the
# doctrine language this whole section uses ("holdings are the treasury", every
# _log here carries prefix="treasury"). The label just did not exist as a value.
#
# SEMANTICS: an empire/community vault bag. NOT sniper ammo, NOT a managed
# position, NOT residual cleanup. Harvest only on an explicit sell_holding.
# Verified inert against every class branch in this file before landing:
#   - thesis_missing nag fires only on watch_bag, so a treasury bag is never nagged
#   - the residual sweep needs _residual_worthy (3 mark failures or -95%), so a
#     healthy treasury bag is never swept
#   - the stablecoin skip does not cover it, so pop/dump alerts STILL fire on a
#     treasury bag - deliberate, the owner wants to know if the empire bag rips or dies
#   - nothing in the holdings loop sells; it only writes holding_event packets
_HOLDING_CLASSES  = ("watch_bag", "active_hold", "residual", "stablecoin", "promoted",
                     "treasury")
_STABLECOIN_MINTS = {
    "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v": "USDC",
    "Es9vMFrzaCERmJfrF4H2FYD4KCoNkY11McCe8BenwNYB": "USDT",
}
HOLDING_EVENT_STATE    = _BOT_LOGS / "holding_event_state.json"
HOLDING_EVENT_COOLDOWN_S = 30 * 60   # per-mint per-tier, so choppy bags don't spam

def _load_holdings() -> dict:
    try:
        with open(HOLDINGS_FILE, encoding="utf-8-sig") as f:
            return json.load(f) or {}
    except Exception:
        return {}

def _save_holdings(d: dict) -> None:
    try:
        HOLDINGS_FILE.parent.mkdir(parents=True, exist_ok=True)
        with open(HOLDINGS_FILE, "w", encoding="utf-8") as f:
            json.dump(d, f, indent=2)
    except Exception as e:
        _log(f"holdings save err: {e}", prefix="treasury")

async def execute_set_holding_thesis(sig: dict) -> None:
    """Write thesis/falsifier/class onto a holdings bag. Does NOT open a position."""
    sid = sig.get("signal_id", _now_iso()); mint = sig.get("mint")
    d = _load_holdings(); h = d.get(mint)
    if not h:
        await write_signal_response(sid, "rejected", error=f"{mint} not on holdings ledger"); return
    h["thesis"]    = str(sig.get("thesis", ""))[:500]
    h["falsifier"] = str(sig.get("falsifier", ""))[:500]
    _cls = str(sig.get("class") or "active_hold").lower()
    if _cls in _HOLDING_CLASSES:
        h["class"] = _cls
    h["thesis_set_at"] = _now_iso()
    d[mint] = h; _save_holdings(d)
    _log(f"treasury: thesis set on {h.get('ticker','?')} (class={h.get('class')})", prefix="treasury")
    await write_signal_response(sid, "executed",
                                details={"mint": mint, "class": h.get("class"), "thesis": h["thesis"]})

async def execute_classify_holding(sig: dict) -> None:
    sid = sig.get("signal_id", _now_iso()); mint = sig.get("mint")
    _cls = str(sig.get("class") or "").lower()
    if _cls not in _HOLDING_CLASSES:
        await write_signal_response(sid, "rejected", error=f"unknown class {_cls!r}"); return
    d = _load_holdings(); h = d.get(mint)
    if not h:
        await write_signal_response(sid, "rejected", error=f"{mint} not on holdings ledger"); return
    h["class"] = _cls; h["classified_at"] = _now_iso()
    d[mint] = h; _save_holdings(d)
    _log(f"treasury: {h.get('ticker','?')} classified {_cls}", prefix="treasury")
    await write_signal_response(sid, "executed", details={"mint": mint, "class": _cls})

async def execute_harvest_holding(sig: dict) -> None:
    """sell_holding with a REQUIRED reason, tagged treasury_harvest so ammo refills
    stop looking like mystery external transfers in the wallet-pnl tracker."""
    sid = sig.get("signal_id", _now_iso())
    reason = str(sig.get("reason") or "").lower()
    if reason not in ("ammo_refill", "take_profit", "residual_cleanup"):
        await write_signal_response(sid, "rejected",
                                    error="harvest_holding requires reason ∈ "
                                          "{ammo_refill, take_profit, residual_cleanup}")
        return
    _tick = (_load_holdings().get(sig.get("mint")) or {}).get("ticker")
    sold = await execute_sell_holding(sig) or {}
    # 2026-10-07: the wrapper used to log the intent and drop the fill.
    # TITS half-skim landed on chain (tx + sol in the signal response) while
    # execution_ledger.treasury_harvest kept tx/amount/pnl null.
    try:
        _ok = bool(sold.get("ok"))
        exec_log(
            "treasury_harvest" if _ok else "treasury_harvest_failed",
            ticker=_tick,
            mint=sig.get("mint"),
            amount_sol=sold.get("sol_received"),
            price=sold.get("price"),
            tx=sold.get("tx"),
            detail=(
                f"reason={reason} fraction={sig.get('fraction', 1.0)} "
                f"proved={_ok} {str(sig.get('note', ''))[:120]}"
            ),
        )
    except Exception:
        pass


# ── OWNER POSITIONS (2026-10-15) ────────────────────────────────────────────
# A bag in the wallet that the bot did not buy (bought by hand, elsewhere, or
# arrived with no bot buy on record) is an OWNER POSITION. The bot does not
# manage it on sight. It tags it, writes an inbox packet, pings, and asks:
# manage it or leave it to the owner?
#   manage -> booked as a normal flip position (normal SL / TP / trail / time
#             rules, the same as promote_holding with mode=flip)
#   leave  -> stays on the holdings ledger; holding alerts only, never sold
#   no answer within OWNER_POS_TIMEOUT_MIN -> auto-manage, announced
# Replies: relay {"action": "owner_position", "id"|"mint"|"ticker": ..,
# "decision": "manage"|"leave"} or the owner command /manage <ticker> or
# /leave <ticker> (written to owner_position_decisions.jsonl).
# Every detection, decision and timeout goes to owner_positions.jsonl.
OWNER_POS_ENABLED     = _envv("OWNER_POS_ENABLED", "true").lower() in ("true", "1", "yes")
OWNER_POS_TIMEOUT_MIN = float(_envv("OWNER_POS_TIMEOUT_MIN", "30"))
OWNER_POS_MIN_USD     = float(_envv("OWNER_POS_MIN_USD", "10"))
# Taken-over owner positions skip the max-hold time exit unless this is on:
# they exit on SL, TP and trail only.
OWNER_POS_TIME_EXIT   = _envv("OWNER_POS_TIME_EXIT", "off").strip().lower() in ("on", "true", "1", "yes")
# Light owner-position check: one getTokenAccountsByOwner call per run, alternating
# the SPL Token and Token-2022 programs, every OWNER_POS_SCAN_MIN minutes. Separate
# from the 30-min holdings sweep, which is unchanged.
OWNER_POS_SCAN_MIN    = float(_envv("OWNER_POS_SCAN_MIN", "5"))
_OWNER_POS_PROGRAMS   = ("TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA",
                         "TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb")
_OWNER_POS_LIGHT      = {"turn": 0, "last": 0.0, "skip": {}}
OWNER_POS_STATE_FILE  = _BOT_LOGS / "owner_positions_sniper.json"
OWNER_POS_LOG_FILE    = _BOT_LOGS / "owner_positions.jsonl"
OWNER_POS_DECISIONS_FILE = Path(os.getenv("OWNER_POS_DECISIONS_FILE") or (_BOT_LOGS / "owner_position_decisions.jsonl"))


def _owner_pos_state() -> dict:
    try:
        with open(OWNER_POS_STATE_FILE, encoding="utf-8-sig") as f:
            d = json.load(f) or {}
            d.setdefault("records", {})
            return d
    except Exception:
        return {"records": {}, "baseline_done": False}


def _owner_pos_save(st: dict) -> None:
    try:
        _save_json_atomic(OWNER_POS_STATE_FILE, st)
    except Exception as e:
        _log(f"owner_position state save err: {e}", prefix="owner_pos")


def _owner_pos_log(event: str, rec: dict, **extra) -> None:
    try:
        row = {"ts": _now_iso(), "bot": "sniper", "event": event,
               "id": rec.get("id"), "ticker": rec.get("ticker"), "mint": rec.get("mint"),
               "state": rec.get("state"), **extra}
        with open(OWNER_POS_LOG_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps(row, default=str) + "\n")
    except Exception as e:
        _log(f"owner_positions.jsonl write err: {e}", prefix="owner_pos")


def _bot_bought_mint(mint: str) -> bool:
    """True when the execution ledger shows the bot buying this mint (a leftover
    from the bot's own trade is not an owner position)."""
    try:
        if not EXEC_LEDGER_FILE.exists():
            return False
        with open(EXEC_LEDGER_FILE, encoding="utf-8", errors="ignore") as f:
            for ln in f:
                if mint in ln and '"buy' in ln:
                    return True
    except Exception:
        pass
    return False


async def _owner_pos_scan(prev: dict, cur: dict) -> None:
    """Called after each holdings sweep. A mint new to the ledger, worth at least
    OWNER_POS_MIN_USD, not a stable, and never bought by the bot -> owner position.
    First run seeds a baseline: bags already present are not asked about."""
    if not OWNER_POS_ENABLED:
        return
    st = _owner_pos_state()
    recs = st["records"]
    if not st.get("baseline_done"):
        st["baseline_done"] = True
        st["baseline_at"] = _now_iso()
        st["baseline_mints"] = sorted(cur.keys())
        _owner_pos_save(st)
        _log(f"owner_position: baseline seeded with {len(cur)} existing bags (not asked about)", prefix="owner_pos")
        return
    base = set(st.get("baseline_mints") or [])
    for mint, h in cur.items():
        if mint in prev or mint in base or mint in recs:
            continue
        if (h.get("class") == "stablecoin") or (mint in _STABLECOIN_MINTS):
            continue
        usd = float(h.get("est_usd") or 0)
        if usd < OWNER_POS_MIN_USD:
            continue
        if _bot_bought_mint(mint):
            continue
        await _owner_pos_register(mint, h, st, via="holdings_sweep")


async def _owner_pos_register(mint: str, h: dict, st: dict, via: str) -> None:
    """Tag one bag as a pending owner position: record, log, inbox packet, ping."""
    recs = st["records"]
    usd = float(h.get("est_usd") or 0)
    if True:
        tick = h.get("ticker") or mint[:8]
        rec = {"id": f"op_{tick}_{mint[:6]}_{int(_now_ts())}", "mint": mint, "ticker": tick, "via": via,
               "est_usd": usd, "amount_ui": h.get("amount_ui"), "est_price": h.get("est_price"), "source": "unknown",
               "tag": "owner_position", "state": "pending",
               "detected_at": _now_iso(), "detected_ts": _now_ts(),
               "timeout_min": OWNER_POS_TIMEOUT_MIN}
        recs[mint] = rec
        _owner_pos_save(st)
        _owner_pos_log("detected", rec, est_usd=usd)
        msg = (f"I see a ${usd:,.0f} {tick} position I didn't open. "
               f"Manage it or leave it to you?")
        try:
            write_inbox_packet_generic({
                "_type": "owner_position", "generated_at": _now_iso(), "bot": "sniper",
                "id": rec["id"], "mint": mint, "ticker": tick, "est_usd": usd,
                "amount_ui": h.get("amount_ui"), "source": "unknown", "state": "pending",
                "question": msg,
                "reply": {"relay": {"action": "owner_position", "id": rec["id"], "decision": "manage | leave"},
                          "owner_command": f"/manage {tick}  or  /leave {tick}"},
                "timeout": (f"No answer in {OWNER_POS_TIMEOUT_MIN:g} min -> the bot manages it with its "
                            f"normal flip SL / TP / trail."),
                "leave_means": "holding alerts only; the bot never sells it",
            }, prefix="meme_sniper", identifier=f"owner_position_{tick}_{mint[:8]}")
        except Exception as e:
            _log(f"owner_position packet err: {e}", prefix="owner_pos")
        try:
            await send_telegram(f"👤 <b>Owner position: {tick}</b>\n{msg}\n"
                                f"Reply /manage {tick} or /leave {tick}. "
                                f"Auto-manage in {OWNER_POS_TIMEOUT_MIN:g} min if no answer.")
        except Exception:
            pass


def _owner_pos_match(rec: dict, target: str) -> bool:
    t = str(target or "").strip().lstrip("$").lower()
    if not t:
        return False
    return t in (str(rec.get("id") or "").lower(), str(rec.get("ticker") or "").lower()) or \
        (len(t) >= 4 and str(rec.get("mint") or "").lower().startswith(t))


async def _owner_pos_apply(rec: dict, decision: str, source: str, st: dict) -> bool:
    decision = str(decision or "").strip().lower()
    if decision not in ("manage", "leave") or rec.get("state") != "pending":
        return False
    if decision == "leave":
        rec["state"] = "leave"; rec["decided_at"] = _now_iso(); rec["decided_by"] = source
        _owner_pos_save(st)
        _owner_pos_log("decision", rec, decision="leave", source=source)
        try:
            await send_telegram(f"👤 {rec['ticker']}: left to you. Alerts only; I won't sell it.")
        except Exception:
            pass
        return True
    return await _owner_pos_take_over(rec, source, st, reason=f"owner said manage ({source})")


# v1.0.6 takeover price guard. Entry for an adopted owner bag comes from a LIVE
# Jupiter sell quote of the wallet's actual raw balance, never from the detection
# mark. Dust (< OWNER_POS_ADOPT_MIN_USD) or no quote -> not adopted, just logged.
# Detection mark vs live off by more than OWNER_POS_PRICE_MAX_RATIO -> repriced
# to the live quote and flagged.
OWNER_POS_ADOPT_MIN_USD   = float(os.getenv("OWNER_POS_ADOPT_MIN_USD", "1") or 1)
OWNER_POS_PRICE_MAX_RATIO = float(os.getenv("OWNER_POS_PRICE_MAX_RATIO", "3") or 3)


def _owner_pos_price_check(est_usd, live_usd) -> tuple:
    """Pure: (adopt?, verdict). verdict in ok | repriced | dust | no_live_quote."""
    if live_usd is None:
        return False, "no_live_quote"
    live_usd = float(live_usd)
    if live_usd < OWNER_POS_ADOPT_MIN_USD:
        return False, "dust"
    try:
        est = float(est_usd or 0)
    except Exception:
        est = 0.0
    if est > 0:
        hi, lo = max(est, live_usd), min(est, live_usd)
        if lo <= 0 or hi / lo > OWNER_POS_PRICE_MAX_RATIO:
            return True, "repriced"
    return True, "ok"


async def _owner_pos_live_quote(mint: str) -> Optional[dict]:
    """Jupiter sell quote (mint -> SOL) of the wallet's actual raw balance, in USD.
    Decimals come from the token account, price = usd / (raw / 10**decimals)."""
    raw, dec = 0, None
    for b in (await get_wallet_token_balances() or []):
        if b.get("mint") == mint:
            raw = int(float(b.get("amount_raw") or 0))
            dec = b.get("decimals")
            break
    if raw <= 0 or dec is None:
        return None
    ui = raw / (10 ** int(dec))
    q = await jupiter_quote_fresh(mint, SOL_MINT, raw, 1000)
    if not q or not q.get("outAmount"):
        return None
    sol_out = int(q["outAmount"]) / 1e9
    solusd = await get_sol_price_usd()
    if not solusd:
        return None
    usd = sol_out * float(solusd)
    return {"raw": raw, "decimals": int(dec), "amount_ui": ui, "sol_out": sol_out,
            "usd": round(usd, 6), "price": (usd / ui) if ui > 0 else None}


async def _owner_pos_take_over(rec: dict, source: str, st: dict, reason: str) -> bool:
    live = None
    try:
        live = await _owner_pos_live_quote(rec["mint"])
    except Exception as _lq:
        _log(f"owner_position live quote err {rec.get('ticker')}: {_lq!r}", prefix="owner_pos")
    adopt, verdict = _owner_pos_price_check(rec.get("est_usd"), (live or {}).get("usd"))
    rec["live_usd"] = (live or {}).get("usd"); rec["price_verdict"] = verdict
    if not adopt:
        rec["state"] = "skipped_dust" if verdict == "dust" else "skipped_no_quote"
        rec["decided_at"] = _now_iso(); rec["decided_by"] = source
        _owner_pos_save(st)
        _owner_pos_log("take_over_refused", rec, source=source, reason=reason, verdict=verdict,
                       est_usd=rec.get("est_usd"), live_usd=rec.get("live_usd"))
        try:
            await send_telegram(f"\U0001F4BC {rec['ticker']}: not taking it over ({verdict}; live "
                                f"value ${float(rec.get('live_usd') or 0):,.2f}). Left alone, logged only.")
        except Exception:
            pass
        return False
    if verdict == "repriced":
        _owner_pos_log("price_flag", rec, est_usd=rec.get("est_usd"), live_usd=live["usd"],
                       est_price=rec.get("est_price"), live_price=live["price"])
    rec["est_price"], rec["est_usd"], rec["amount_ui"] = live["price"], round(live["usd"], 2), live["amount_ui"]
    try:   # ledger row must carry the LIVE mark - promote books entry from it
        _hd0 = _load_holdings()
        if rec["mint"] in _hd0:
            _hd0[rec["mint"]].update({"est_price": live["price"], "est_usd": round(live["usd"], 2),
                                      "amount_ui": live["amount_ui"]})
            _save_holdings(_hd0)
    except Exception as _hu:
        _log(f"owner_position holdings reprice err: {_hu}", prefix="owner_pos")
    try:   # the light check may find a bag before the sweep has put it on the ledger
        _hd = _load_holdings()
        if rec["mint"] not in _hd:
            _hd[rec["mint"]] = {"ticker": rec.get("ticker"), "amount_ui": rec.get("amount_ui"),
                                "est_price": rec.get("est_price"), "est_usd": rec.get("est_usd"),
                                "class": "watch_bag", "source": "owner_position",
                                "first_seen": rec.get("detected_at"), "first_seen_ts": rec.get("detected_ts")}
            _save_holdings(_hd)
    except Exception as _he:
        _log(f"owner_position holdings row err: {_he}", prefix="owner_pos")
    sig = {"signal_id": f"{rec['id']}_manage", "mint": rec["mint"], "mode": "flip",
           "force": True, "reason": f"owner_position: {reason}"}
    try:
        await execute_promote_holding(sig)
    except Exception as e:
        _log(f"owner_position take-over err {rec.get('ticker')}: {e!r}", prefix="owner_pos")
    managed = rec["mint"] in _read_open_position_mints()
    if managed and not OWNER_POS_TIME_EXIT:
        try:
            _pp = load_positions().get(rec["mint"])
            if _pp:
                _pp["owner_no_time_exit"] = True
                _pp["owner_position"] = rec.get("id")
                upsert_position(rec["mint"], _pp)
        except Exception as _te:
            _log(f"owner_position no-time-exit flag err: {_te}", prefix="owner_pos")
    rec["state"] = "managed" if managed else "manage_failed"
    rec["decided_at"] = _now_iso(); rec["decided_by"] = source
    _owner_pos_save(st)
    _owner_pos_log("take_over" if managed else "take_over_failed", rec, source=source, reason=reason)
    try:
        await send_telegram(
            (f"🤖 <b>Managing {rec['ticker']}</b>\n{reason}. Booked as a flip position: exits on "
             f"SL / TP / trail{' and the max-hold clock' if OWNER_POS_TIME_EXIT else ' (no max-hold time exit)'}. "
             f"Cost basis unknown, so P&L is measured from the mark.")
            if managed else
            (f"⚠️ {rec['ticker']}: tried to take it over ({reason}) but the booking failed. "
             f"It stays unmanaged; check the bag."))
    except Exception:
        pass
    return managed


async def execute_owner_position_signal(sig: dict) -> None:
    """Relay action: {"action": "owner_position", "id"|"mint"|"ticker": .., "decision": manage|leave}."""
    sid = sig.get("signal_id", _now_iso())
    st = _owner_pos_state()
    target = sig.get("id") or sig.get("mint") or sig.get("ticker")
    for rec in st["records"].values():
        if rec.get("state") == "pending" and _owner_pos_match(rec, target):
            ok = await _owner_pos_apply(rec, sig.get("decision"), "relay", st)
            await write_signal_response(sid, "executed" if ok else "rejected",
                                        details={"id": rec["id"], "decision": sig.get("decision"),
                                                 "state": rec.get("state")},
                                        error=None if ok else "decision must be manage or leave")
            return
    await write_signal_response(sid, "rejected", error=f"no pending owner position matches {target!r}")


def _owner_pos_read_decisions() -> list:
    try:
        if not OWNER_POS_DECISIONS_FILE.exists():
            return []
        out = []
        with open(OWNER_POS_DECISIONS_FILE, encoding="utf-8-sig") as f:
            for ln in f:
                try:
                    out.append(json.loads(ln))
                except Exception:
                    continue
        return out
    except Exception:
        return []


async def _owner_pos_light_check() -> int:
    """One getTokenAccountsByOwner call (programs alternate per run). Mints not on
    the ledger, not open, not baseline and not bot-bought are priced (DexScreener,
    not RPC) and registered. Returns how many were registered."""
    st = _owner_pos_state()
    if not st.get("baseline_done") or not HOT_WALLET_ADDR:
        return 0     # the first full sweep seeds the baseline
    prog = _OWNER_POS_PROGRAMS[_OWNER_POS_LIGHT["turn"] % 2]
    _OWNER_POS_LIGHT["turn"] += 1
    r = await helius_rpc("getTokenAccountsByOwner",
                         [HOT_WALLET_ADDR, {"programId": prog}, {"encoding": "jsonParsed"}])
    seen = {}
    for acc in ((r or {}).get("value") or []) if isinstance(r, dict) else []:
        try:
            info = acc["account"]["data"]["parsed"]["info"]
            ui = float((info.get("tokenAmount") or {}).get("uiAmount") or 0)
            if ui > 0:
                seen[info["mint"]] = seen.get(info["mint"], 0) + ui
        except Exception:
            continue
    held, opn = _load_holdings(), _read_open_position_mints()
    base, recs = set(st.get("baseline_mints") or []), st["records"]
    now = _now_ts()
    cands = [m for m in seen if m != _WSOL_MINT and m not in _STABLECOIN_MINTS and m not in held
             and m not in opn and m not in base and m not in recs
             and now - float(_OWNER_POS_LIGHT["skip"].get(m, 0)) > 1800]
    if not cands:
        return 0
    await asyncio.sleep(60)    # let a bot buy finish booking before calling it the owner's
    opn = _read_open_position_mints()
    n = 0
    for m in cands:
        if m in opn or _bot_bought_mint(m):
            continue
        tick, px = m[:8], None
        try:
            pair = await fetch_token_data(m)
            if pair:
                px = _safe_num(pair.get("priceUsd"))
                tick = (pair.get("baseToken") or {}).get("symbol") or tick
        except Exception:
            pass
        usd = round(seen[m] * px, 2) if px else 0
        if usd < OWNER_POS_MIN_USD:
            _OWNER_POS_LIGHT["skip"][m] = now      # re-price at most every 30 min
            continue
        st = _owner_pos_state()
        if m in st["records"]:
            continue
        await _owner_pos_register(m, {"ticker": tick, "est_usd": usd, "amount_ui": seen[m],
                                      "est_price": px}, st, via="light_check")
        n += 1
    return n


def _owner_pos_should_mark_gone(chain_raw: Optional[float]) -> bool:
    """2026-10-20 (FLOW): 'gone' only on a CONFIRMED on-chain balance of 0.
    None = the read failed -> never gone."""
    return chain_raw is not None and float(chain_raw) <= 0


async def _owner_pos_chain_raw(mint: str) -> Optional[float]:
    """Raw balance of `mint` in the hot wallet straight from chain (both token programs,
    via getTokenAccountsByOwner {mint}). One retry on RPC error; None if both reads fail."""
    if not HOT_WALLET_ADDR:
        return None
    for attempt in (1, 2):
        try:
            r = await helius_rpc("getTokenAccountsByOwner",
                                 [HOT_WALLET_ADDR, {"mint": mint}, {"encoding": "jsonParsed"}])
            if isinstance(r, dict) and isinstance(r.get("value"), list):
                tot = 0.0
                for acc in r["value"]:
                    tot += float(acc["account"]["data"]["parsed"]["info"]["tokenAmount"]["amount"] or 0)
                return tot
        except Exception:
            pass
        if attempt == 1:
            await asyncio.sleep(2)
    return None


async def owner_position_loop() -> None:
    """Every 60s: apply owner-command decisions, then auto-manage pending owner
    positions whose timeout passed. A bag that left the wallet is closed out."""
    _log(f"owner_position: loop starting (timeout {OWNER_POS_TIMEOUT_MIN:g} min)", prefix="owner_pos")
    while True:
        try:
            if OWNER_POS_ENABLED and _now_ts() - _OWNER_POS_LIGHT["last"] >= OWNER_POS_SCAN_MIN * 60:
                _OWNER_POS_LIGHT["last"] = _now_ts()
                try:
                    await _owner_pos_light_check()
                except Exception as _le:
                    _log(f"owner_position light check err: {_le!r}", prefix="owner_pos")
            if OWNER_POS_ENABLED:
                st = _owner_pos_state()
                pend = [r for r in st["records"].values() if r.get("state") == "pending"]
                if pend:
                    decs = _owner_pos_read_decisions()
                    held = _load_holdings()
                    for rec in pend:
                        if rec["mint"] not in held and rec["mint"] not in _read_open_position_mints():
                            # 2026-10-20 fix: being off the holdings ledger is NOT proof the bag
                            # left (light_check registers mints that are not on the ledger yet,
                            # so FLOW was marked gone 1s after detection). Ask the chain.
                            _chain_raw = await _owner_pos_chain_raw(rec["mint"])
                            if _owner_pos_should_mark_gone(_chain_raw):
                                rec["state"] = "gone"; _owner_pos_save(st)
                                _owner_pos_log("gone", rec, note="bag left the wallet before a decision (chain balance 0)")
                                continue
                            if _chain_raw is None:
                                _log(f"owner_position: {rec.get('ticker')} chain read failed twice - not marking gone",
                                     prefix="owner_pos")
                        mine = [d for d in decs if float(d.get("ts") or 0) >= float(rec.get("detected_ts") or 0)
                                and _owner_pos_match(rec, d.get("target"))]
                        if mine:
                            await _owner_pos_apply(rec, mine[-1].get("decision"), "owner_command", st)
                            continue
                        if _now_ts() - float(rec.get("detected_ts") or 0) >= OWNER_POS_TIMEOUT_MIN * 60:
                            _owner_pos_log("timeout", rec, timeout_min=OWNER_POS_TIMEOUT_MIN)
                            await _owner_pos_take_over(rec, "timeout", st,
                                                       reason=f"no answer in {OWNER_POS_TIMEOUT_MIN:g} min")
        except Exception as e:
            _log(f"owner_position loop err: {e!r}", prefix="owner_pos")
        await asyncio.sleep(60)


async def execute_promote_holding(sig: dict) -> None:
    """THE BRIDGE: book a holdings bag as a managed position from the WALLET's real
    token balance — no fake buy fill. flip → flip defaults; hold → requires thesis
    + falsifier (GORK standard). Unknown cost basis is flagged, never faked."""
    sid = sig.get("signal_id", _now_iso()); mint = sig.get("mint")
    mode = str(sig.get("mode") or "flip").lower()
    d = _load_holdings(); h = d.get(mint)
    if not h:
        await write_signal_response(sid, "rejected", error=f"{mint} not on holdings ledger"); return
    if mint in _read_open_position_mints():
        await write_signal_response(sid, "rejected", error="already an open position"); return
    if mode == "hold" and not (sig.get("thesis") and sig.get("falsifier")):
        await write_signal_response(sid, "rejected",
                                    error="hold-mode promote requires thesis AND falsifier (GORK standard)")
        return
    # chain truth: book from what the WALLET actually holds
    raw_ui = None
    try:
        for b in (await get_wallet_token_balances() or []):
            if b.get("mint") == mint:
                raw_ui = float(b.get("amount_ui") or (float(b.get("amount_raw") or 0) /
                          (10 ** int(b.get("decimals") or 0)) if b.get("decimals") is not None else 0))
                break
    except Exception:
        pass
    token_amount = raw_ui if (raw_ui and raw_ui > 0) else float(h.get("amount_ui") or 0)
    if token_amount <= 0:
        await write_signal_response(sid, "rejected", error="wallet holds none of this mint"); return
    est_usd = h.get("est_usd") or 0
    if est_usd and est_usd < 10 and not sig.get("force"):
        await write_signal_response(sid, "rejected",
                                    error=f"bag is ~${est_usd} — too small to promote; harvest or "
                                          f"watch instead (pass force=true to override)")
        return
    mark = h.get("est_price")
    cost_basis_sol = sig.get("cost_basis_sol")
    basis_unknown = cost_basis_sol is None
    _solusd = None
    try:
        _solusd = await get_sol_price_usd()
    except Exception:
        pass
    if cost_basis_sol and token_amount > 0 and _solusd:
        entry_price = (float(cost_basis_sol) * _solusd) / token_amount
        amount_sol  = float(cost_basis_sol)
    else:
        entry_price = mark
        amount_sol  = (est_usd / _solusd) if (est_usd and _solusd) else 0.0
    params = dict(sig.get("params") or {})
    if mode == "flip":
        params.setdefault("stop_loss_pct", 25)
        params.setdefault("trail_activate_pct", get_override_sync("DEFAULT_TRAIL_ACTIVATE_PCT", DEFAULT_TRAIL_ACTIVATE_PCT))
        params.setdefault("trail_drop_pct",    get_override_sync("DEFAULT_TRAIL_DROP_PCT", DEFAULT_TRAIL_DROP_PCT))
        params.setdefault("max_hold_minutes",  get_override_sync("DEFAULT_MAX_HOLD_MINUTES", DEFAULT_MAX_HOLD_MINUTES))
    else:
        params.setdefault("trail_activate_pct", get_override_sync("DEFAULT_HOLD_TRAIL_ACTIVATE_PCT", DEFAULT_HOLD_TRAIL_ACTIVATE_PCT))
        params.setdefault("trail_drop_pct", get_override_sync("DEFAULT_HOLD_TRAIL_DROP_PCT", DEFAULT_HOLD_TRAIL_DROP_PCT))
    position = {
        "mint": mint, "ticker": h.get("ticker", "?"), "name": h.get("ticker", "?"),
        "entry_price": entry_price,
        "entry_price_source": ("cost_basis_sol" if not basis_unknown else "mark_at_promote"),
        "basis_unknown": basis_unknown,
        "amount_sol": round(amount_sol, 6),
        "token_amount": token_amount,
        "opened_at": _now_iso(), "opened_at_ts": _now_ts(),
        "params": params, "mode": mode,
        "peak_price": entry_price or mark, "peak_pnl_pct": 0, "drawdown_from_peak_pct": 0,
        "trail_armed": False, "partial_taken": False,
        "promoted_from_holding": True,
        "thesis": sig.get("thesis"), "falsifier": sig.get("falsifier"),
        "reasoning_at_buy": str(sig.get("reason") or "promoted from treasury")[:500],
    }
    upsert_position(mint, position)
    h["class"] = "promoted"; h["promoted_at"] = _now_iso(); d[mint] = h; _save_holdings(d)
    _log(f"treasury: PROMOTED {h.get('ticker','?')} → {mode} position "
         f"(basis_unknown={basis_unknown}, tokens={token_amount:.0f})", prefix="treasury")
    await write_signal_response(sid, "executed", details={
        "mint": mint, "mode": mode, "entry_price": entry_price,
        "basis_unknown": basis_unknown, "token_amount": token_amount})
    try:
        await send_telegram(
            f"⬆️ <b>PROMOTED {h.get('ticker','?')}</b> → {mode} position"
            + ("\n⚠ cost basis unknown — PnL advisory until you set it" if basis_unknown else ""))
    except Exception:
        pass

# ── TREASURY MTM ALERTS (2026-08-08) ────────────────────────────────────────
# Treasury bags mark quietly. gork sits class=treasury with last_event=null, and
# the only holding_events that exist are new / residual / pop / dump - all keyed
# off FIRST-SEEN or PEAK price. A bag can move +$250 on the day and produce
# nothing, because nothing here ever looked at a DAY. The owner called a ~$250 day and
# The agent had no feed for it.
#
# FEED ONLY. No auto-sell, no reclass, no harvest, and never an X surface - bag
# size is confidential and only goes to the private chat.
TREASURY_MTM_PCT_LEVELS = (10.0, 25.0)     # up and down
TREASURY_MTM_USD_LEVELS = (250.0,)         # up only - a $250 down move is covered by pct


def _treasury_day_key() -> str:
    """America/New_York calendar day. The baseline is a DAY boundary, not a
    rolling window, so 'the day' means the same thing to the bot and to the owner."""
    return datetime.now(EST).strftime("%Y-%m-%d")


def _treasury_mtm_check(mint: str, h: dict, st: dict) -> list:
    """Return [(event, detail)] for newly-crossed MTM thresholds. Mutates h with
    today's baseline on first mark of the day, and st with the dedupe keys.

    Each threshold fires ONCE PER DAY per mint (key `mint:event:YYYY-MM-DD`), so a
    bag chopping across +10% all afternoon pings once, not every poll tick.
    """
    out = []
    try:
        px = h.get("est_price")
        usd = float(h.get("est_usd") or 0)
        if not px or px <= 0:
            return out
        day = _treasury_day_key()

        # First successful mark of the day sets the baseline. Stored on the holding
        # row so it survives a restart mid-day.
        if h.get("mtm_day_key") != day or not h.get("mtm_day_open_price"):
            h["mtm_day_key"] = day
            h["mtm_day_open_price"] = px
            h["mtm_day_open_usd"] = usd
            return out          # no delta to measure against yet

        open_px = float(h.get("mtm_day_open_price") or 0)
        open_usd = float(h.get("mtm_day_open_usd") or 0)
        if open_px <= 0:
            return out
        pct = (px - open_px) / open_px * 100.0
        dusd = usd - open_usd

        def _fire(ev):
            k = f"{mint}:{ev}:{day}"
            if st.get(k):
                return False
            st[k] = _now_ts()
            return True

        for lvl in sorted(TREASURY_MTM_PCT_LEVELS, reverse=True):
            if pct >= lvl and _fire(f"mtm_up_pct_{int(lvl)}"):
                out.append((f"mtm_up_pct_{int(lvl)}", f"{pct:+.1f}% on the day"))
                break
        for lvl in sorted(TREASURY_MTM_PCT_LEVELS, reverse=True):
            if pct <= -lvl and _fire(f"mtm_down_pct_{int(lvl)}"):
                out.append((f"mtm_down_pct_{int(lvl)}", f"{pct:+.1f}% on the day"))
                break
        for lvl in sorted(TREASURY_MTM_USD_LEVELS, reverse=True):
            if dusd >= lvl and _fire(f"mtm_up_usd_{int(lvl)}"):
                out.append((f"mtm_up_usd_{int(lvl)}", f"{dusd:+,.0f} USD on the day"))
                break
    except Exception:
        pass
    return out


TREASURY_MTM_SUMMARY_HOUR = int(_envv("TREASURY_MTM_SUMMARY_HOUR", "21"))


async def _treasury_mtm_day_summary(cur: dict, st: dict) -> None:
    """One end-of-day treasury PnL line, ~21:00 ET. Rides the existing holdings
    loop rather than adding a scheduler - the loop already runs continuously, so
    "has the hour passed and have we not sent today" is the whole trigger.

    Sends even on a FLAT day. The threshold pings only fire on movement, so
    without this a quiet day is indistinguishable from a dead feed - which is the
    same absent-vs-neutral problem this codebase keeps finding.
    """
    try:
        now = datetime.now(EST)
        if now.hour < TREASURY_MTM_SUMMARY_HOUR:
            return
        day = _treasury_day_key()
        key = f"_treasury:mtm_day_summary:{day}"
        if st.get(key):
            return
        rows = []
        tot_now = tot_open = 0.0
        for mint, h in (cur or {}).items():
            if (h.get("class") or "") != "treasury":
                continue
            usd = float(h.get("est_usd") or 0)
            open_usd = float(h.get("mtm_day_open_usd") or 0)
            if usd <= 0 and open_usd <= 0:
                continue
            tot_now += usd
            tot_open += open_usd
            d = usd - open_usd
            p = (d / open_usd * 100.0) if open_usd else 0.0
            rows.append(f"{h.get('ticker','?')}: ${usd:,.2f} ({d:+,.2f} / {p:+.1f}%)")
        if not rows:
            return
        st[key] = _now_ts()
        d_tot = tot_now - tot_open
        p_tot = (d_tot / tot_open * 100.0) if tot_open else 0.0
        await send_telegram(
            f"📒 <b>treasury day summary</b> {day}\n"
            + "\n".join(rows)
            + f"\n<b>total: ${tot_now:,.2f} ({d_tot:+,.2f} / {p_tot:+.1f}%)</b>"
            + "\nfeed only - no action taken, nothing sold.")
        _log(f"treasury: day summary sent ({len(rows)} bags, {d_tot:+,.2f})", prefix="treasury")
    except Exception as e:
        _log(f"treasury day summary err: {e!r}", prefix="treasury")


async def _treasury_mtm_notify(mint: str, h: dict, ev: str, detail: str) -> None:
    """Private telegram only. Option A: ONE ping per economic bag, hot + ledger
    lines together, because the same price move marks both and two pings for one
    move is noise. home_base is already cached by the treasury loop, so the ledger
    line costs no new RPC path."""
    try:
        px = h.get("est_price") or 0
        usd = float(h.get("est_usd") or 0)
        amt = float(h.get("amount_ui") or 0)
        open_usd = float(h.get("mtm_day_open_usd") or 0)
        open_px = float(h.get("mtm_day_open_price") or 0)
        dusd = usd - open_usd
        dpct = ((px - open_px) / open_px * 100.0) if open_px else 0.0

        ledger_line = "ledger note: n/a"
        try:
            hb = _TREASURY_CACHE.get("home_base") or {}
            for row in (hb.get("holdings") or []):
                if row.get("mint") == mint:
                    _lu = float(row.get("est_usd") or row.get("usd") or 0)
                    _la = float(row.get("amount_ui") or row.get("amount") or 0)
                    ledger_line = f"ledger: {_la:,.0f} @ {px:.8f} = ${_lu:,.2f}"
                    break
        except Exception:
            pass

        await send_telegram(
            f"💰 <b>treasury mtm | {h.get('ticker','?')}</b>\n"
            f"hot: {amt:,.0f} @ {px:.8f} = ${usd:,.2f}\n"
            f"day: {dusd:+,.2f} ({dpct:+.1f}%)\n"
            f"event: {ev} - {detail}\n"
            f"{ledger_line}")
    except Exception as e:
        _log(f"treasury mtm notify err: {e!r}", prefix="treasury")


async def _emit_holding_events(prev: dict, cur: dict) -> None:
    """Fire holding_event packets (new/pop/dump/residual/thesis_missing) between
    the 12h reports, with a per-mint per-tier cooldown so choppy bags don't spam.
    Stablecoins are skipped. This is the treasury's missing interrupt surface."""
    try:
        st = {}
        try:
            with open(HOLDING_EVENT_STATE, encoding="utf-8-sig") as f:
                st = json.load(f) or {}
        except Exception:
            st = {}
        now = _now_ts()
        def _cooled(m, tier): return now - int(st.get(f"{m}:{tier}", 0)) >= HOLDING_EVENT_COOLDOWN_S
        def _mark(m, tier):   st[f"{m}:{tier}"] = now
        for mint, h in cur.items():
            if (h.get("class") == "stablecoin") or (mint in _STABLECOIN_MINTS):
                continue
            fp, pk, px = h.get("first_seen_price"), h.get("peak_price"), h.get("est_price")
            usd = h.get("est_usd") or 0
            fired = []
            if mint not in prev and _cooled(mint, "new"):
                fired.append("new_holding"); _mark(mint, "new")
            if fp and px and fp > 0:
                chg = (px - fp) / fp * 100
                for lvl in (200, 100, 50):
                    if chg >= lvl and _cooled(mint, f"pop{lvl}"):
                        fired.append("pop"); _mark(mint, f"pop{lvl}"); break
            if pk and px and pk > 0:
                dd = (px - pk) / pk * 100
                for lvl in (70, 40):
                    if dd <= -lvl and _cooled(mint, f"dump{lvl}"):
                        fired.append("dump"); _mark(mint, f"dump{lvl}"); break
            _residual_worthy = (
                (h.get("mark_fail_streak", 0) >= 3) or (fp and px and px <= 0.05 * fp)
            )
            if _residual_worthy and _cooled(mint, "residual"):
                # Suppress residual spam: already-classed residual with no material
                # amount change and no re-death after a mark recovery stays silent.
                prev_h = prev.get(mint) or {}
                if h.get("class") == "residual":
                    prev_amt = float(prev_h.get("amount_ui") or 0) or 0.0
                    cur_amt = float(h.get("amount_ui") or 0) or 0.0
                    if prev_amt > 0:
                        _amt_delta_pct = abs(cur_amt - prev_amt) / prev_amt
                    else:
                        _amt_delta_pct = 1.0 if abs(cur_amt - prev_amt) > 0 else 0.0
                    _amt_changed = (_amt_delta_pct > 0.05) or (abs(cur_amt - prev_amt) >= 1.0)
                    prev_fail = int(prev_h.get("mark_fail_streak", 0) or 0)
                    cur_fail = int(h.get("mark_fail_streak", 0) or 0)
                    # re-death: mark recovered (fail streak healthy) then died again
                    _redeath = prev_fail < 3 and cur_fail >= 3
                    if _amt_changed or _redeath:
                        fired.append("residual_detected"); _mark(mint, "residual")
                    # else: residual + still unmarkable/unchanged → skip silently
                else:
                    # first transition into residual-worthy state
                    fired.append("residual_detected"); _mark(mint, "residual")
            # ── TREASURY MTM (2026-08-08) - treasury class only ─────────────
            # Deliberately scoped: trade inventory does not get day-move pings, or
            # every chopping bag becomes a notification. Treasury is the bag the owner
            # actually wants a feed on.
            if (h.get("class") or "") == "treasury":
                for _ev, _detail in _treasury_mtm_check(mint, h, st):
                    fired.append(_ev)
                    try:
                        await _treasury_mtm_notify(mint, h, _ev, _detail)
                    except Exception:
                        pass

            _age_h = (now - int(h.get("first_seen_ts") or now)) / 3600
            if (_age_h > 24 and (h.get("class") or "watch_bag") == "watch_bag"
                    and usd >= 5 and _cooled(mint, "thesis_missing")):
                fired.append("thesis_missing"); _mark(mint, "thesis_missing")
            for ev in fired:
                _tk = h.get("ticker") if h.get("ticker") not in (None, "", "?") else mint[:8]
                _amt = float(h.get("amount_ui") or 0)
                if px:
                    _val = f"${usd:,.2f}" if usd is not None else "value ?"
                    _hl = f"{ev.replace('_', ' ')}: {_tk} - {_amt:,.0f} tokens @ {px:.8g} = {_val}"
                else:
                    _hl = (f"{ev.replace('_', ' ')}: {_tk} - {_amt:,.0f} tokens, NO PRICE "
                           f"(no pool on DexScreener after {h.get('mark_fail_streak', 0)} marks; likely dead/unsellable)")
                pkt = {
                    "_type": "holding_event", "lane": "queue", "generated_at": _now_iso(),
                    "headline": _hl,
                    "event": ev, "mint": mint, "ticker": _tk,
                    "class": h.get("class") or "watch_bag",
                    "amount_ui": h.get("amount_ui"), "est_usd": usd, "est_price": px,
                    "first_seen_price": fp, "peak_price": pk,
                    "chg_from_first_pct": (round((px - fp) / fp * 100, 1) if fp and px else None),
                    "chg_from_peak_pct":  (round((px - pk) / pk * 100, 1) if pk and px else None),
                    "thesis": h.get("thesis", ""),
                    "suggested_actions": ["set_holding_thesis", "classify_holding",
                                          "harvest_holding", "promote_holding"],
                    "ask": "one line: still bag / skim to ammo / promote to managed / residual cleanup",
                }
                # livefix: drop unknown/empty fields instead of showing ?/$0/null
                if not px:
                    pkt["est_usd"] = None
                pkt = {k: v for k, v in pkt.items() if v not in (None, "", "?")}
                try:
                    # Readable subject in filename (not hashed meme_sniper_sha8_ts)
                    path = _holding_event_inbox_path(ev, h.get("ticker"), mint)
                    _save_json_atomic(path, pkt)
                    h["last_event"] = ev; h["last_event_at"] = _now_iso()
                    _log(f"treasury: holding_event {ev} {h.get('ticker','?')} (${usd})", prefix="treasury")
                except Exception:
                    pass
        # End-of-day treasury line. Fires at most once per calendar day.
        try:
            await _treasury_mtm_day_summary(cur, st)
        except Exception:
            pass

        # Persist the day baselines written onto the holding rows above, or the
        # first mark of every poll re-seeds and no threshold can ever cross.
        try:
            _save_holdings(cur)
        except Exception as _sh:
            _log(f"treasury mtm baseline save err: {_sh!r}", prefix="treasury")
        with open(HOLDING_EVENT_STATE, "w", encoding="utf-8") as f:
            json.dump(st, f, indent=2)
    except Exception as e:
        _log(f"holding_events err: {e!r}", prefix="treasury")


# ─── ARCHETYPE PROSPECTIVE VALIDATION (2026-07-23, the owner's ruling) ────────────
# The archetype clusters are built FROM tokens that already rugged — so a label
# like "rugfast: 100%" is true BY CONSTRUCTION and predictive of NOTHING (the
# cluster is 100% rugs because rugging was the membership requirement). This
# machinery answers the question that matters: when the matcher stamps an
# archetype on a NEW token, what actually happens next? Rug rate, time-to-rug,
# and — the owner's key metric — EXTRACTABILITY: how often the token ran ≥1.5x/2x
# from the label price BEFORE the rug (i.e., could a disciplined flip have paid?).
# Labels become measured priors that adjust PARAMETERS (flip-default, tighter
# trail, smaller size), never vetoes. Obvious rugs by DATA (rugcheck/safety/LP)
# still die at the safety gates — that lane is untouched.
ARCHETYPE_PROSPECTIVE_FILE = _BOT_LOGS / "archetype_prospective.jsonl"
ARCHETYPE_WATCH_FILE = _BOT_LOGS / "archetype_watch.json"
ARCHETYPE_WATCH_HOURS = 48
ARCHETYPE_RUG_DROP_PCT = 70.0     # drop from peak that counts as the rug event

def _record_archetype_match(mint: str, ticker: str, archetype: str, pair: dict) -> None:
    """Called when the matcher stamps an archetype on a live candidate —
    registers the mint for prospective outcome tracking."""
    try:
        price = _safe_num(pair.get("priceUsd"))
        if not price:
            return
        watch = {}
        try:
            with open(ARCHETYPE_WATCH_FILE, encoding="utf-8") as f:
                watch = json.load(f) or {}
        except Exception:
            pass
        if mint in watch:
            return   # one prospective row per mint per label era
        watch[mint] = {"archetype": archetype, "ticker": ticker,
                        "matched_at": _now_iso(), "matched_at_ts": _now_ts(),
                        "price_at_match": price,
                        "mcap_at_match": _safe_num(pair.get("marketCap") or pair.get("fdv")),
                        "peak_ratio": 1.0, "rugged": False, "resolved": False}
        ARCHETYPE_WATCH_FILE.parent.mkdir(parents=True, exist_ok=True)
        with open(ARCHETYPE_WATCH_FILE, "w", encoding="utf-8") as f:
            json.dump(watch, f, indent=2)
        _log(f"archetype_val: watching {ticker} ({_short_mint(mint)}) as '{archetype}' "
             f"from ${price}", prefix="archval")
    except Exception as e:
        _log(f"archetype_val record err: {e}", prefix="archval")

async def archetype_validation_loop() -> None:
    """Every 10 min: advance watched archetype-labeled mints; resolve at rug or 48h."""
    _log("archetype_validation: starting (labels must earn their authority)", prefix="archval")
    while True:
        if await _rpc_pause_if_unhealthy("archetype_validation"):   # 2026-10-14
            continue
        try:
            watch = {}
            try:
                with open(ARCHETYPE_WATCH_FILE, encoding="utf-8") as f:
                    watch = json.load(f) or {}
            except Exception:
                pass
            changed = False
            for mint, w in list(watch.items()):
                if w.get("resolved"):
                    if _now_ts() - (w.get("matched_at_ts") or 0) > ARCHETYPE_WATCH_HOURS * 3600 * 2:
                        watch.pop(mint, None); changed = True
                    continue
                age_s = _now_ts() - (w.get("matched_at_ts") or 0)
                try:
                    pairs = await fetch_dex_search(mint)
                except Exception:
                    continue
                pair = pairs[0] if pairs else None
                price = _safe_num(pair.get("priceUsd")) if pair else None
                base = w.get("price_at_match") or 0
                if price and base:
                    ratio = price / base
                    if ratio > (w.get("peak_ratio") or 1.0):
                        w["peak_ratio"] = round(ratio, 3); changed = True
                    peak = w.get("peak_ratio") or 1.0
                    dd_from_peak = (1 - ratio / peak) * 100 if peak else 0
                    rug_now = dd_from_peak >= ARCHETYPE_RUG_DROP_PCT
                else:
                    rug_now = price is None and age_s > 3600   # vanished pair after 1h = dead
                if rug_now or age_s > ARCHETYPE_WATCH_HOURS * 3600:
                    outcome = {
                        "mint": mint, "ticker": w.get("ticker"),
                        "archetype": w.get("archetype"),
                        "matched_at": w.get("matched_at"),
                        "resolved_at": _now_iso(),
                        "rugged": bool(rug_now),
                        "hours_to_resolution": round(age_s / 3600, 1),
                        "peak_ratio_before_resolution": w.get("peak_ratio"),
                        "extractable_1_5x": (w.get("peak_ratio") or 1.0) >= 1.5,
                        "extractable_2x":   (w.get("peak_ratio") or 1.0) >= 2.0,
                    }
                    try:
                        with open(ARCHETYPE_PROSPECTIVE_FILE, "a", encoding="utf-8") as f:
                            f.write(json.dumps(outcome) + "\n")
                    except Exception as e:
                        _log(f"archetype_val outcome write err: {e}", prefix="archval")
                    w["resolved"] = True; w["rugged"] = bool(rug_now); changed = True
                    _log(f"archetype_val: {w.get('ticker')} '{w.get('archetype')}' resolved — "
                         f"rugged={rug_now}, peak {w.get('peak_ratio')}x, {outcome['hours_to_resolution']}h",
                         prefix="archval")
                await asyncio.sleep(1.0)
            if changed:
                with open(ARCHETYPE_WATCH_FILE, "w", encoding="utf-8") as f:
                    json.dump(watch, f, indent=2)
        except Exception as e:
            _log(f"archetype_validation err: {e}", prefix="archval")
        await asyncio.sleep(get_override_sync("ARCHVAL_TICK_SECONDS", 600))

def archetype_validation_read(archetype: str) -> dict:
    """The MEASURED meaning of a label — prospective outcomes only. This is what
    rides in the packet next to every archetype_match so the label arrives with
    its earned authority (or its honest thinness)."""
    try:
        rows = []
        with open(ARCHETYPE_PROSPECTIVE_FILE, encoding="utf-8") as f:
            for ln in f:
                try:
                    r = json.loads(ln)
                    if r.get("archetype") == archetype:
                        rows.append(r)
                except Exception:
                    continue
    except Exception:
        rows = []
    n = len(rows)
    if n == 0:
        return {"prospective_n": 0,
                "read": ("no prospective record — this label has NEVER been validated forward. "
                          "Its cluster stats are true by construction (built from rugs) and "
                          "predict nothing. Treat as unproven folklore: flip-mode default, "
                          "tight params, let the record accumulate.")}
    rugged = [r for r in rows if r.get("rugged")]
    ex15 = sum(1 for r in rows if r.get("extractable_1_5x"))
    ex2 = sum(1 for r in rows if r.get("extractable_2x"))
    rug_hours = sorted(r.get("hours_to_resolution", 0) for r in rugged)
    med_rug_h = rug_hours[len(rug_hours)//2] if rug_hours else None
    return {
        "prospective_n": n,
        "rug_rate_pct": round(100 * len(rugged) / n, 1),
        "median_hours_to_rug": med_rug_h,
        "extractable_1_5x_pct": round(100 * ex15 / n, 1),
        "extractable_2x_pct": round(100 * ex2 / n, 1),
        "read": (f"measured forward: {len(rugged)}/{n} rugged"
                  + (f" (median {med_rug_h}h)" if med_rug_h is not None else "")
                  + f"; ran ≥1.5x from label first in {round(100*ex15/n)}% — "
                  + ("flip-extractable more often than not; the label means TIGHTEN, not skip"
                     if ex15 / n >= 0.5 else
                     "extraction is the minority case; the label deserves real caution")),
    }


# ─── IGNORED-RUNNER RE-FIRE (2026-07-23, the agent's jimothy audit #2) ──────────
# "once i pass, no forced reopen on 2x / $1M / clean pullback. ignore is a dead
# end; should be a watch that can reopen." Doctrine: an ignore is a JUDGMENT
# about a moment, not a verdict about a mint. When the moment changes — the
# runner keeps running — the judgment gets a second look, delivered, not hoped.
# The agent's operational note (2026-07-23): the canary tripfile got walked by a
# log iteration — a false positive alarm. Central exclusion: any file iteration
# in this bot skips canary-named paths. Other bots' walkers need their own.
def _path_excluded(p) -> bool:
    try:
        return "canary" in str(getattr(p, "name", p)).lower()
    except Exception:
        return False

IGNORED_WATCH_FILE = _BOT_LOGS / "ignored_runner_watch.json"
IGNORED_WATCH_MAX = 40            # bounded registry
IGNORED_WATCH_HOURS = 48          # a mint watches for 2 days after ignore
_REFIRE_TRIGGERS = ("2x_since_ignore", "crossed_1M_mcap", "5x_since_ignore")

def _load_ignored_watch() -> dict:
    try:
        with open(IGNORED_WATCH_FILE, encoding="utf-8") as f:
            return json.load(f) or {}
    except Exception:
        return {}

def _save_ignored_watch(state: dict) -> None:
    try:
        IGNORED_WATCH_FILE.parent.mkdir(parents=True, exist_ok=True)
        with open(IGNORED_WATCH_FILE, "w", encoding="utf-8") as f:
            json.dump(state, f, indent=2)
    except Exception as e:
        _log(f"ignored_watch save err: {e}", prefix="refire")

async def _capture_ignore_baseline(mint: str, decline: dict) -> None:
    """Snapshot the mint's price/mcap AT ignore time so the watcher has a
    baseline. Fire-and-forget from the ignore handler."""
    try:
        pairs = await fetch_dex_search(mint)
        pair = pairs[0] if pairs else None
        if not pair:
            return
        price = _safe_num(pair.get("priceUsd"))
        mcap = _safe_num(pair.get("marketCap") or pair.get("fdv"))

        # ── BASELINE FIX 2026-08-08 (the TOAD receipt) ──────────────────────
        # This snapshotted the mcap AT IGNORE TIME. TOAD was first scanned at
        # $71.5k and ignored again at $6.2M, so the refire lane measured 2x from
        # $6.2M - an alert that could only ever arrive after the window it was
        # meant to catch. The desk sees a token when it SCANS it; that is the
        # price the miss should be measured from.
        #
        # Prefer the watchlist's first-scan value whenever one exists. Fall back
        # to the ignore-time mark only when the mint was never scanned.
        _scan_mcap = _scan_price = None
        _wl_entry = {}
        try:
            _wl_entry = (load_watchlist() or {}).get(mint) or {}
            _scan_mcap = _safe_num(_wl_entry.get("scan_mcap_usd") or _wl_entry.get("scan_mcap"))
            _scan_price = _safe_num(_wl_entry.get("scan_price"))
        except Exception:
            pass
        _price_fallback = not ((_scan_price or 0) > 0)
        _mcap_fallback = not ((_scan_mcap or 0) > 0)
        _base_mcap = _scan_mcap if not _mcap_fallback else mcap
        _base_price = _scan_price if not _price_fallback else price
        _base_src = ("watchlist_first_scan" if not (_price_fallback or _mcap_fallback)
                     else ("watchlist_first_scan_partial" if not _mcap_fallback or not _price_fallback
                           else "ignore_time"))
        _fallback_tag = "ignore_time" if _price_fallback else None

        state = _load_ignored_watch()
        state[mint] = {
            "ignored_at": _now_iso(), "ignored_at_ts": _now_ts(),
            "ticker": (pair.get("baseToken") or {}).get("symbol", "?"),
            "base_price": _base_price, "base_mcap": _base_mcap,
            "scan_price": _scan_price, "scan_mcap": _scan_mcap,
            "baseline_source": _base_src,
            "fallback": _fallback_tag,   # ignore_time when scan_price missing
            "mcap_at_ignore": mcap,      # kept for the record, NOT the baseline
            "price_at_ignore": price,
            "decline_reason": decline.get("decline_reason", "unspecified"),
            "would_have_bought_if": decline.get("would_have_bought_if", ""),
            "refires": [],
        }
        # bound the registry: oldest out
        if len(state) > IGNORED_WATCH_MAX:
            for k in sorted(state, key=lambda m: state[m].get("ignored_at_ts", 0))[:len(state) - IGNORED_WATCH_MAX]:
                state.pop(k, None)
        _save_ignored_watch(state)
        # ── ignore-path potential tag (spec section: ignore-path wiring) ────
        # An ignore with structure is exactly what the tier is for: ensure the mint
        # is on the watchlist, tag it, and carry his decline reasoning - WITHOUT
        # moving the baseline, which _potential_tag enforces on its own.
        try:
            _wl_all = load_watchlist() or {}
            if mint not in _wl_all:
                watchlist_add(mint, {"ticker": (pair.get("baseToken") or {}).get("symbol"),
                                     "mcap": _base_mcap, "liquidity_usd":
                                         _safe_num(((pair.get("liquidity") or {}) or {}).get("usd")),
                                     "price_usd": _base_price})
                _wl_all = load_watchlist() or {}
            _e = _wl_all.get(mint)
            if _e is not None:
                _edge_ctx = (decline.get("edge_filter")
                             or (decline.get("context") or {}).get("edge_filter") or {})
                if _potential_tag(mint, _e, _edge_ctx, None,
                                  source="auto_ignore", ignore_sig=decline):
                    _wl_all[mint] = _e
                    _save_json_atomic(WATCHLIST_FILE, _wl_all)
        except Exception as _pie:
            _log(f"potential tag on ignore err {_short_mint(mint)}: {_pie}", prefix="refire")

        _log(f"refire: watching ignored {_short_mint(mint)} from ${_base_price} / "
             f"mcap ${_base_mcap:,.0f} (baseline: {_base_src}"
             + (f", fallback={_fallback_tag}" if _fallback_tag else "") + ")"
             if _base_price and _base_mcap else
             f"refire: watching ignored {_short_mint(mint)}", prefix="refire")
    except Exception as e:
        _log(f"refire baseline err {_short_mint(mint)}: {e}", prefix="refire")

async def _write_refire_packet(mint: str, w: dict, pair: dict, trigger: str,
                                ratio: float, mcap: float) -> None:
    ticker = w.get("ticker") or (pair.get("baseToken") or {}).get("symbol", "?")
    packet = {
        "_type": "opportunity",
        "subtype": "ignored_runner_refire",
        "generated_at": _now_iso(),
        "mint": mint, "ticker": ticker,
        "trigger": trigger,
        "you_ignored_at": {"when": w.get("ignored_at"), "price": w.get("price_at_ignore") or w.get("base_price"),
                            "mcap": w.get("mcap_at_ignore") or w.get("base_mcap"),
                            "baseline_first_scan": {"price": w.get("base_price"), "mcap": w.get("base_mcap"),
                                                    "note": "ratio is measured from this frozen first-scan baseline"},
                            "your_reason": w.get("decline_reason"),
                            "your_would_have_bought_if": w.get("would_have_bought_if")},
        "now": {"price": _safe_num(pair.get("priceUsd")),
                 "mcap": mcap, "ratio_since_ignore": round(ratio, 2),
                 "vol_24h": _safe_num((pair.get("volume") or {}).get("h24")),
                 "liq": _safe_num((pair.get("liquidity") or {}).get("usd")),
                 "price_change_1h": _safe_num((pair.get("priceChange") or {}).get("h1"))},
        "ask": (f"{ticker} moved after you passed — {trigger.replace('_', ' ')}. "
                 f"Your condition at ignore time is quoted above (would_have_bought_if). "
                 f"Re-affirming the pass is the DEFAULT and costs nothing: an ignore is "
                 f"about a moment, not a mint, and a pass that looks wrong in hindsight "
                 f"was often right at the time. Only revisit if your stated condition "
                 f"has actually been met."),
        # ── OWNER/AGENT RULING 2026-07-27: REFIRES DO NOT BAIT A CHASE ──────
        # "2x refires push chase energy." The old packet led with "it KEPT
        # RUNNING" and invited re-evaluation as a continuation trade — which is
        # an invitation to buy something for the reason that it already went up.
        #
        # The buy option now requires an ACTUAL pullback/reclaim structure,
        # computed from real price action: it must have pulled back over 6h AND
        # be reclaiming on the 1h. Vertical continuation is not structure, it's
        # a chase. If the data is missing, the answer is NO — absent evidence
        # of structure, there is no structure.
        "structure_check": (lambda _pc: {
            "pulled_back_6h": _pc.get("h6"),
            "reclaiming_1h": _pc.get("h1"),
            "has_pullback_reclaim": bool(
                _pc.get("h6") is not None and _pc.get("h1") is not None
                and float(_pc["h6"]) < 0 and float(_pc["h1"]) > 0
            ),
            "rule": ("buy option requires pullback (6h negative) AND reclaim (1h positive). "
                     "Vertical continuation is a chase, not a structure. Missing data = no."),
        })(pair.get("priceChange") or {}),
    }
    _pcx = pair.get("priceChange") or {}
    _has_structure = bool(
        _pcx.get("h6") is not None and _pcx.get("h1") is not None
        and _safe_num(_pcx.get("h6")) is not None and _safe_num(_pcx.get("h1")) is not None
        and float(_safe_num(_pcx["h6"])) < 0 and float(_safe_num(_pcx["h1"])) > 0
    )
    packet["decision_inputs"] = _decision_inputs(
        [
            {"action_type": "reaffirm_pass", "when_this_fits": "the original reason still holds"},
            {"action_type": "log_lesson",    "when_this_fits": "the condition you named was actually met and you missed it"},
        ] + ([
            {"action_type": "fire_buy_signal",
             "when_this_fits": "it pulled back and is reclaiming, and your stated condition is met"},
        ] if _has_structure else []),
        note=("Re-affirming the pass is the default and is not a failure. "
              + ("A pullback/reclaim structure is present, so a buy option is shown."
                 if _has_structure else
                 "No pullback/reclaim structure — no buy option. Buying a vertical "
                 "because it already ran is the definition of a chase."))
    )
    try:
        _INBOX.mkdir(parents=True, exist_ok=True)
        fname = (f"meme_sniper - opportunity_refire_{ticker}_{mint[:8]}_"
                 f"{datetime.now().strftime('%Y%m%d_%H%M%S')}.json")
        with open(_INBOX / fname, "w", encoding="utf-8") as f:
            json.dump(packet, f, indent=2)
        _log(f"REFIRE: {ticker} ({_short_mint(mint)}) {trigger} — ratio {ratio:.1f}x, "
             f"mcap ${mcap:,.0f} — packet fired", prefix="refire")
    except Exception as e:
        _log(f"refire packet write err: {e}", prefix="refire")

RECLAIM_WATCH_FILE = _BOT_LOGS / "reclaim_watch.json"
RECLAIM_WATCH_MAX = 60
RECLAIM_MIN_AGE_S = 6 * 3600
RECLAIM_MAX_AGE_S = 7 * 24 * 3600
RECLAIM_MIN_LIQ = 25_000
RECLAIM_MIN_MCAP = 80_000
RECLAIM_MAX_MCAP = 8_000_000
RECLAIM_DIP_PCT = 0.35
RECLAIM_OFF_LOW = 1.15
RECLAIM_UNDER_PEAK = 0.75
RECLAIM_DEV_MAX = 15.0
RECLAIM_SEED_FETCHES = 8


def _load_reclaim_watch() -> dict:
    try:
        with open(RECLAIM_WATCH_FILE, encoding="utf-8") as f:
            data = json.load(f) or {}
            return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _save_reclaim_watch(state: dict) -> None:
    try:
        RECLAIM_WATCH_FILE.parent.mkdir(parents=True, exist_ok=True)
        tmp = RECLAIM_WATCH_FILE.with_suffix(".json.tmp")
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(state, f, indent=2)
        tmp.replace(RECLAIM_WATCH_FILE)
    except Exception as e:
        _log(f"reclaim_watch save err: {e}", prefix="reclaim")


def _reclaim_prune(state: dict, now_ts: int) -> None:
    meta = state.get("_meta") if isinstance(state.get("_meta"), dict) else {}
    rows = {k: v for k, v in state.items() if k != "_meta" and isinstance(v, dict)}
    if len(rows) > RECLAIM_WATCH_MAX:
        ranked = sorted(rows.items(), key=lambda kv: kv[1].get("updated_ts") or 0)
        for mint, _row in ranked[: len(rows) - RECLAIM_WATCH_MAX]:
            rows.pop(mint, None)
    state.clear()
    state.update(rows)
    state["_meta"] = meta


def _reclaim_pair_ok(pair: dict, now_ts: int) -> tuple:
    born_ms = pair.get("pairCreatedAt") or 0
    born_ts = int(born_ms / 1000) if born_ms else 0
    age = now_ts - born_ts if born_ts else 0
    mcap = _safe_num(pair.get("marketCap") or pair.get("fdv")) or 0
    liq = _safe_num((pair.get("liquidity") or {}).get("usd")) or 0
    if not (RECLAIM_MIN_AGE_S <= age <= RECLAIM_MAX_AGE_S):
        return None
    if liq < RECLAIM_MIN_LIQ or not (RECLAIM_MIN_MCAP <= mcap <= RECLAIM_MAX_MCAP):
        return None
    vol_h1 = _safe_num((pair.get("volume") or {}).get("h1")) or 0
    txns = (pair.get("txns") or {}).get("h1") or {}
    return {
        "born_ts": born_ts,
        "mcap": mcap,
        "liq": liq,
        "vol_h1": vol_h1,
        "buys_h1": _safe_num(txns.get("buys")) or 0,
        "sells_h1": _safe_num(txns.get("sells")) or 0,
        "ticker": (pair.get("baseToken") or {}).get("symbol") or "?",
    }


def _reclaim_add(state: dict, mint: str, snap: dict, now_ts: int, source: str) -> None:
    if mint in state:
        return
    state[mint] = {
        "ticker": snap["ticker"],
        "source": source,
        "born_ts": snap["born_ts"],
        "peak_mcap": snap["mcap"],
        "trough_mcap": snap["mcap"],
        "last_mcap": snap["mcap"],
        "dip_vol_h1": None,
        "phase": "watching",
        "dip_id": 0,
        "last_ping_dip": 0,
        "updated_ts": now_ts,
        "samples": [{"ts": now_ts, "mcap": snap["mcap"], "liq": snap["liq"], "vol_h1": snap["vol_h1"]}],
    }


async def _reclaim_fetch_pair(mint: str) -> dict:
    pairs = await fetch_dex_search(mint)
    return next((c for c in (pairs or []) if c.get("chainId") == SOLANA_CHAIN_ID), None)


async def _reclaim_try_add(state: dict, mint: str, now_ts: int, source: str) -> bool:
    if not mint or mint in state or mint == "_meta":
        return False
    try:
        pair = await _reclaim_fetch_pair(mint)
    except Exception:
        return False
    if not pair:
        return False
    snap = _reclaim_pair_ok(pair, now_ts)
    if not snap:
        return False
    _reclaim_add(state, mint, snap, now_ts, source)
    return True


def _reclaim_seed_ids(now_ts: int, cursor: int) -> tuple:
    ids = []
    # dex top only if the scraper snapshot is fresh
    try:
        if DEX_TOP_SNAPSHOT_FILE.exists():
            age = now_ts - DEX_TOP_SNAPSHOT_FILE.stat().st_mtime
            if age <= DEX_TOP_SNAPSHOT_MAX_AGE_S:
                blob = json.loads(DEX_TOP_SNAPSHOT_FILE.read_text(encoding="utf-8"))
                for row in (blob.get("tokens") or [])[:40]:
                    ca = row.get("ca") or row.get("mint") or ""
                    if ca:
                        ids.append((ca, "dex_top"))
    except Exception:
        pass
    scanned = []
    try:
        raw = json.loads(SCANNED_MINTS_FILE.read_text(encoding="utf-8")) if SCANNED_MINTS_FILE.exists() else {}
        if isinstance(raw, dict):
            for mint, row in raw.items():
                if not isinstance(row, dict):
                    continue
                seen = row.get("first_seen_ts") or 0
                try:
                    seen = float(seen)
                except Exception:
                    continue
                age = now_ts - seen
                if RECLAIM_MIN_AGE_S <= age <= RECLAIM_MAX_AGE_S:
                    scanned.append(mint)
    except Exception:
        scanned = []
    scanned.sort()
    if scanned:
        start = cursor % len(scanned)
        rotated = scanned[start:] + scanned[:start]
        for mint in rotated[: RECLAIM_SEED_FETCHES]:
            ids.append((mint, "scanned"))
        cursor = (start + RECLAIM_SEED_FETCHES) % len(scanned)
    return ids, cursor


async def _reclaim_seed(state: dict, now_ts: int) -> None:
    meta = state.get("_meta") if isinstance(state.get("_meta"), dict) else {}
    fetches = 0
    boosts = await fetch_dex_boosts()
    for boost in boosts[:25]:
        if fetches >= RECLAIM_SEED_FETCHES:
            break
        mint = boost.get("tokenAddress") or boost.get("address") or ""
        if await _reclaim_try_add(state, mint, now_ts, "boost"):
            fetches += 1
        await asyncio.sleep(0.25)
    ids, cursor = _reclaim_seed_ids(now_ts, int(meta.get("scan_cursor") or 0))
    meta["scan_cursor"] = cursor
    state["_meta"] = meta
    for mint, source in ids:
        if fetches >= RECLAIM_SEED_FETCHES * 2:
            break
        if await _reclaim_try_add(state, mint, now_ts, source):
            fetches += 1
        await asyncio.sleep(0.25)
    _reclaim_prune(state, now_ts)


async def _reclaim_rug_line(mint: str, liq: float, trough_liq: float) -> dict:
    line = {
        "liq_held": bool(trough_liq and liq >= trough_liq * 0.8 and liq >= 20_000),
        "dev_holding_pct": None,
        "dev_dump": None,
        "note": "rug line unavailable",
    }
    try:
        holders = await get_holders_top10(mint)
    except Exception:
        holders = None
    if holders:
        dev = holders.get("dev_holding_pct")
        line["dev_holding_pct"] = dev
        line["dev_dump"] = dev is not None and dev > RECLAIM_DEV_MAX
        if line["dev_dump"]:
            line["note"] = f"dev heavy {dev}%. not a clean rerun"
        elif line["liq_held"]:
            line["note"] = f"liq held, dev {dev}%"
        else:
            line["note"] = "liq did not hold the dip"
    elif not line["liq_held"]:
        line["note"] = "liq did not hold the dip"
    # 2026-10-23: unreadable dev holdings = no clean rerun (RECLAIM_DEV_FAIL_CLOSED).
    if not holders and _guard is not None and _guard.reclaim_dev_fail_closed():
        line["dev_dump"] = True
        line["note"] = "dev holdings unreadable. fail closed"
    return line


async def _reclaim_ping(mint: str, row: dict, pair: dict, mcap: float, trough: float, peak: float, rug: dict, vol_h1: float) -> None:
    ticker = row.get("ticker") or (pair.get("baseToken") or {}).get("symbol") or "?"
    liq = _safe_num((pair.get("liquidity") or {}).get("usd")) or 0
    h1 = _safe_num((pair.get("priceChange") or {}).get("h1"))
    packet = {
        "_type": "opportunity",
        "subtype": "reclaim_watch",
        "generated_at": _now_iso(),
        "mint": mint,
        "ticker": ticker,
        "phase": "rerun",
        "auto_buy": False,
        "source": row.get("source"),
        "ask": (f"{ticker} dipped, based, volume came back, still under the old peak. "
                "watch only. not a buy."),
        "structure": {
            "peak_mcap": round(peak),
            "trough_mcap": round(trough),
            "now_mcap": round(mcap),
            "off_peak_pct": round((1 - mcap / peak) * 100, 1) if peak else None,
            "off_low_pct": round((mcap / trough - 1) * 100, 1) if trough else None,
            "liq": liq,
            "h1": h1,
            "vol_h1": vol_h1,
            "dip_vol_h1": row.get("dip_vol_h1"),
        },
        "rug_line": rug,
        "words": "dip, bottom, rerun. not drawdown.",
        "second_wind": (row.get("sw") or {}).get("detail"),
        "plan": (row.get("sw") or {}).get("plan"),
        "community_formation": (row.get("sw") or {}).get("community"),
        "holder_bundle": (row.get("sw") or {}).get("rug"),
    }
    _INBOX.mkdir(parents=True, exist_ok=True)
    fname = (f"meme_sniper - reclaim_{ticker}_{mint[:8]}_"
             f"{datetime.now().strftime('%Y%m%d_%H%M%S')}.json")
    with open(_INBOX / fname, "w", encoding="utf-8") as f:
        json.dump(packet, f, indent=2)
    _log(f"RECLAIM ping {ticker} mcap {mcap:.0f} vol {vol_h1:.0f} rug {rug.get('note')}", prefix="reclaim")
    if _guard is not None:
        _guard.record_ping(mint, ticker, mcap, (row.get("sw") or {}).get("plan") or {})


async def _sw_fetch_mcap(mint: str):
    pair = await _reclaim_fetch_pair(mint)
    return (_safe_num(pair.get("marketCap") or pair.get("fdv")) if pair else None)


async def _second_wind_v2(mint: str, row: dict, pair: dict, mcap: float) -> dict:
    """2026-10-23 (SECOND_WIND_V2): true peak from price history, 1-3h base with volume
    dry-up then return, skip >80% off peak, holder + bundle checks, community, plan."""
    if _guard is None or not _guard._on("SECOND_WIND_V2", "true"):
        return {}
    try:
        price = _safe_num(pair.get("priceUsd")) or 0
        candles = await _guard.fetch_hourly(pair.get("pairAddress") or "")
        seen_px = (row.get("peak_mcap") or 0) * price / mcap if (mcap and price) else 0
        chk = _guard.second_wind_check(candles, price, seen_px)
        if not chk.get("ok"):
            return {"skip": True, "why": chk.get("why")}
        rc = await smart_rug_check(mint)
        if rc.get("smart_check_verdict") == "block":
            return {"skip": True, "why": f"rug block {rc.get('block_reason')}"}
        if (rc.get("bundle_score") or 0) >= 85:
            return {"skip": True, "why": f"bundled holders (score {rc.get('bundle_score')})"}
        cf = compute_community_formation({**pair, "candles": candles})
        plan = _guard.trade_plan(chk["base_low"], chk["base_high"], chk["peak_price"], price, mcap)
        return {"skip": False, "detail": chk, "plan": plan, "community": cf,
                "rug": {"verdict": rc.get("smart_check_verdict"), "bundle_score": rc.get("bundle_score"),
                        "holder_gate": (rc.get("holder_clusters") or {}).get("gate")}}
    except Exception as e:
        return {"skip": True, "why": f"second wind check err {type(e).__name__}"}


async def reclaim_watch_loop() -> None:
    """Matured dip-bottom-rerun watch. Ping only. Never a buy."""
    _log("reclaim_watch: starting (ping only, no buy, scanned+dex_top seed)", prefix="reclaim")
    while True:
        if await _rpc_pause_if_unhealthy("reclaim_watch"):   # 2026-10-14
            continue
        try:
            await write_heartbeat("reclaim_watch", "polling")
            now_ts = _now_ts()
            state = _load_reclaim_watch()
            await _reclaim_seed(state, now_ts)
            for mint, row in list(state.items()):
                if mint == "_meta" or not isinstance(row, dict):
                    continue
                try:
                    pair = await _reclaim_fetch_pair(mint)
                except Exception:
                    continue
                if not pair:
                    continue
                mcap = _safe_num(pair.get("marketCap") or pair.get("fdv")) or 0
                liq = _safe_num((pair.get("liquidity") or {}).get("usd")) or 0
                h1 = _safe_num((pair.get("priceChange") or {}).get("h1"))
                vol_h1 = _safe_num((pair.get("volume") or {}).get("h1")) or 0
                txns = (pair.get("txns") or {}).get("h1") or {}
                buys = _safe_num(txns.get("buys")) or 0
                sells = _safe_num(txns.get("sells")) or 0
                if mcap <= 0:
                    continue
                peak = max(row.get("peak_mcap") or 0, mcap)
                trough = row.get("trough_mcap") or mcap
                samples = row.get("samples") or []
                samples.append({"ts": now_ts, "mcap": mcap, "liq": liq, "vol_h1": vol_h1})
                row["samples"] = samples[-18:]
                row["peak_mcap"] = peak
                row["last_mcap"] = mcap
                row["updated_ts"] = now_ts
                if liq < 20_000:
                    row["phase"] = "liq_gone"
                    await asyncio.sleep(0.3)
                    continue
                dipped = peak > 0 and mcap <= peak * (1 - RECLAIM_DIP_PCT)
                prev = samples[-2]["mcap"] if len(samples) >= 2 else mcap
                making_low = mcap < prev * 0.92
                if dipped and making_low:
                    row["phase"] = "knife"
                    row["trough_mcap"] = min(trough, mcap)
                    row["dip_vol_h1"] = vol_h1
                    row["trough_liq"] = liq
                elif dipped:
                    row["trough_mcap"] = min(row.get("trough_mcap") or mcap, mcap)
                    trough = row["trough_mcap"]
                    if row.get("dip_vol_h1") is None:
                        row["dip_vol_h1"] = vol_h1
                    if not row.get("trough_liq"):
                        row["trough_liq"] = liq
                    two_held = len(samples) >= 3 and samples[-1]["mcap"] >= samples[-2]["mcap"] * 0.98 and samples[-2]["mcap"] >= samples[-3]["mcap"] * 0.98
                    row["phase"] = "bottom" if two_held else "dipped"
                    off_low = trough > 0 and mcap >= trough * RECLAIM_OFF_LOW
                    under_peak = mcap <= peak * RECLAIM_UNDER_PEAK
                    h1_green = h1 is not None and h1 > 0
                    dip_vol = row.get("dip_vol_h1") or 0
                    vol_back = vol_h1 >= max(dip_vol * 1.25, 10_000) and buys > sells
                    if row["phase"] == "bottom" and off_low and under_peak and h1_green and vol_back:
                        rug = await _reclaim_rug_line(mint, liq, row.get("trough_liq") or liq)
                        if rug.get("dev_dump") or not rug.get("liq_held"):
                            row["phase"] = "rug_skip"
                            row["last_rug"] = rug
                        else:
                            dip_id = int(row.get("dip_id") or 0)
                            if row.get("last_ping_dip") != dip_id or dip_id == 0:
                                if dip_id == 0:
                                    dip_id = now_ts
                                    row["dip_id"] = dip_id
                                _sw = await _second_wind_v2(mint, row, pair, mcap)
                                if _sw.get("skip"):
                                    row["phase"] = "sw_skip"
                                    row["last_sw"] = _sw.get("why")
                                    _log(f"reclaim skip {row.get('ticker')}: {_sw.get('why')}", prefix="reclaim")
                                    await asyncio.sleep(0.3)
                                    continue
                                row["sw"] = _sw
                                await _reclaim_ping(mint, row, pair, mcap, trough, peak, rug, vol_h1)
                                row["last_ping_dip"] = dip_id
                                row["phase"] = "pinged"
                elif mcap >= peak * 0.9:
                    row["phase"] = "extension"
                    row["trough_mcap"] = mcap
                    row["dip_id"] = 0
                    row["dip_vol_h1"] = None
                else:
                    row["phase"] = "watching"
                await asyncio.sleep(0.3)
            _save_reclaim_watch(state)
            if _guard is not None:
                _n_sc = await _guard.score_due(_sw_fetch_mcap)
                if _n_sc:
                    _log(f"second wind: scored {_n_sc} ping horizons", prefix="reclaim")
        except Exception as e:
            _log(f"reclaim_watch err: {e}", prefix="reclaim")
        await asyncio.sleep(600)


async def ignored_runner_watch_loop() -> None:
    """Every 5 min: check watched ignored mints; fire each trigger once."""
    _log("ignored_runner_watch: starting (ignore is a watch now, not a dead end)", prefix="refire")
    while True:
        if await _rpc_pause_if_unhealthy("ignored_runner_watch"):   # 2026-10-14
            continue
        try:
            state = _load_ignored_watch()
            now_ts = _now_ts()
            changed = False
            for mint, w in list(state.items()):
                if now_ts - (w.get("ignored_at_ts") or 0) > IGNORED_WATCH_HOURS * 3600:
                    state.pop(mint, None); changed = True
                    continue
                # 2x/5x/$1m from FROZEN first-scan, never ignore-time
                base_p = _safe_num(w.get("scan_price")) or _safe_num(w.get("base_price"))
                base_m = _safe_num(w.get("scan_mcap")) or _safe_num(w.get("base_mcap"))
                if not base_p and not base_m:
                    continue
                try:
                    pairs = await fetch_dex_search(mint)
                except Exception:
                    continue
                pair = pairs[0] if pairs else None
                if not pair:
                    continue
                price = _safe_num(pair.get("priceUsd"))
                mcap = _safe_num(pair.get("marketCap") or pair.get("fdv")) or 0
                if base_p and price:
                    ratio = price / base_p
                elif base_m and mcap:
                    ratio = mcap / base_m
                else:
                    continue
                fired = set(w.get("refires") or [])
                trig = None
                # 2026-10-14: the multiple stays measured from the frozen first scan, but a "since
                # ignore" refire also needs the price to be ABOVE where the agent passed. Without
                # this, a mint that had already 2x'd before the pass re-fired on the next tick
                # ("moved after you passed") while trading below the pass price.
                _p_ign = _safe_num(w.get("price_at_ignore"))
                _moved_since_pass = (not _p_ign) or (price and price > _p_ign)
                if "2x_since_ignore" not in fired and ratio >= 2.0 and _moved_since_pass:
                    trig = "2x_since_ignore"
                elif "crossed_1M_mcap" not in fired and mcap >= 1_000_000 and (base_m or 0) < 1_000_000:
                    trig = "crossed_1M_mcap"
                elif "5x_since_ignore" not in fired and ratio >= 5.0 and _moved_since_pass:
                    trig = "5x_since_ignore"
                if trig:
                    await _write_refire_packet(mint, w, pair, trig, ratio, mcap)
                    w.setdefault("refires", []).append(trig)
                    changed = True
                await asyncio.sleep(1.0)   # gentle on the API
            if changed:
                _save_ignored_watch(state)
        except Exception as e:
            _log(f"ignored_runner_watch err: {e}", prefix="refire")
        await asyncio.sleep(get_override_sync("REFIRE_TICK_SECONDS", 300))


# ─── Sprint 53: X CHATTER (via agent_scraper) + BOT/ORGANIC CLASSIFICATION ───
SCRAPER_TASK_FILE   = Path(WS_JSON_RELAY) / "scraper_task.json"
SCRAPER_RESPONSE_DIR = Path(WS_JSON_RELAY)


def _looks_like_bot_post(post: dict) -> tuple[bool, str]:
    """Classify a post as bot-like vs organic. This is the filter that makes social
    data usable instead of poisonous.

    Memecoin cashtags are the single most botted surface on the internet — raid bots,
    paid shill farms, and engagement pods all target exactly the query we're running.
    If we hand the agent raw chatter counts, we hand him a number an attacker controls.
    So: classify, and report BOTH counts separately. He should see 40 posts and know
    35 of them are bots — that's the actual signal.

    Heuristics (deliberately conservative — better to under-call bots than to silently
    discard real people):
      - zero engagement on a post in a live search = nobody saw or cared
      - wall of cashtags/emojis = a raid template, not a person
      - near-duplicate text across posts is handled by the caller (needs the full set)
    """
    text = (post.get("text") or "").strip()
    likes = post.get("likes") or 0
    reposts = post.get("reposts") or 0
    replies = post.get("replies") or 0
    engagement = likes + reposts + replies

    if not text:
        return True, "empty_text"
    # a raid template: many cashtags stuffed in one post
    cashtags = text.count("$")
    if cashtags >= 4:
        return True, f"cashtag_spam ({cashtags} tickers in one post)"
    # pure hype with zero engagement — the signature of a farm account
    hype_words = ("100x", "1000x", "moon", "send it", "ape", "next gem", "lfg", "pump it",
                  "dont miss", "don't miss", "early", "gem", "🚀", "🔥")
    hype_hits = sum(1 for w in hype_words if w.lower() in text.lower())
    if engagement == 0 and hype_hits >= 2:
        return True, "zero_engagement_hype"
    if engagement == 0 and len(text) < 40:
        return True, "zero_engagement_low_effort"
    return False, "organic"


def _classify_chatter(posts: list) -> dict:
    """Split a post set into organic vs bot, and surface the ratio. The RATIO is the
    real signal: heavy volume + heavy bot share = a raid (avoid). Modest volume + high
    organic share = a real community (interesting)."""
    organic, bots = [], []
    # near-duplicate detection: raid bots post the same copy with tiny variations
    seen_norm = {}
    for p in posts or []:
        text = (p.get("text") or "").strip()
        norm = "".join(ch.lower() for ch in text if ch.isalnum())[:60]
        is_bot, why = _looks_like_bot_post(p)
        if not is_bot and norm and norm in seen_norm:
            is_bot, why = True, "duplicate_copypasta"
        if norm:
            seen_norm[norm] = True
        (bots if is_bot else organic).append({**p, "_bot_reason": why})
    total = len(organic) + len(bots)
    return {
        "total": total,
        "organic_count": len(organic),
        "bot_count": len(bots),
        "organic_pct": round(len(organic) / total * 100, 1) if total else 0.0,
        "organic": organic,
        "bots": bots,
        "read": (
            "no chatter at all — nobody is talking about this" if total == 0 else
            (f"MOSTLY BOTS ({len(bots)}/{total}) — this is a raid, not a community. "
             "Volume here is manufactured; treat the hype as noise."
             if total and len(bots) / total >= 0.7 else
             (f"MIXED ({len(organic)} organic / {len(bots)} bot) — some real interest under the spam."
              if total and len(bots) / total >= 0.35 else
              f"MOSTLY ORGANIC ({len(organic)}/{total}) — real people are actually talking about this."))
        ),
    }


async def fetch_x_chatter(ticker: str, mint: str, per_query: int = 5,
                          timeout_s: int = 90) -> dict:
    """Request X chatter on a token via agent_scraper: FIVE posts on the $TICKER and
    FIVE on the raw CA, kept SEPARATE because they surface different populations.

      $TICKER  — broad, loud, heavily botted (raid bots spam cashtags).
      CA       — far fewer posts, but someone posting a raw contract address is almost
                 always actually holding or tracking it. Much higher organic density.

    Comparing the two IS a signal: loud cashtag + dead CA = manufactured hype. Quiet
    cashtag + active CA = people who actually own it are talking.
    """
    out = {"ticker": ticker, "mint": mint, "ticker_chatter": None, "ca_chatter": None,
           "requested_at": _now_iso(), "error": None}
    try:
        tasks = []
        tq = f"${ticker.lstrip('$')}" if ticker and ticker != "?" else None
        if tq:
            tasks.append({
                "task_id": f"snipe_x_ticker_{mint[:8]}_{int(_now_ts())}",
                "scrape_type": "x_search", "target": tq,
                "max_results": per_query, "requested_by": "meme_sniper",
            })
        tasks.append({
            "task_id": f"snipe_x_ca_{mint[:8]}_{int(_now_ts())}",
            "scrape_type": "x_search", "target": mint,
            "max_results": per_query, "requested_by": "meme_sniper",
        })
        # ── Sprint 55: APPEND, DO NOT CLOBBER ──────────────────────────────────
        # This used mode "w" — it OVERWROTE the entire task file. But scraper_task.json is
        # a SHARED relay: flow queues presweep tasks (etf_flows, liquidations,
        # keyword_search) into the same file. So every time the sniper asked for X chatter,
        # it DESTROYED whatever flow had queued and not yet had scraped. And two sniper
        # calls landing close together would destroy each other's requests.
        #
        # Read-merge-write, keeping anything already queued. Same lesson as the shared
        # tempfile race: a shared resource written with a naive overwrite is a data-loss
        # bug waiting for concurrency to find it.
        SCRAPER_TASK_FILE.parent.mkdir(parents=True, exist_ok=True)
        _existing = []
        try:
            if SCRAPER_TASK_FILE.exists():
                with open(SCRAPER_TASK_FILE, encoding="utf-8") as f:
                    _existing = (json.load(f) or {}).get("tasks") or []
        except Exception:
            _existing = []
        _have = {t.get("task_id") for t in _existing if isinstance(t, dict)}
        _merged = list(_existing) + [t for t in tasks if t["task_id"] not in _have]
        _save_json_atomic(SCRAPER_TASK_FILE, {"tasks": _merged})
        _log(f"x_chatter: queued {len(tasks)} searches for {ticker} ({_short_mint(mint)}) "
             f"[{len(_merged)} total in relay]", prefix="social")

        # ── Sprint 55: READ THE SCRAPER'S REPLY. THREE BUGS, ALL FATAL. ─────────
        #
        # BUG 1 — WRONG FILE. The old code globbed `*{task_id}*.json`, expecting one file
        #   per task with the id in the FILENAME. The scraper writes ONE SHARED FILE —
        #   agent_scraper_response.json — with a `responses` array, and the task_id lives
        #   INSIDE the JSON. The glob matched NOTHING. Ever. Not once.
        #
        # BUG 2 — WRONG KEY. The old code read resp["result"]["posts"]. There is no
        #   `result` key. The payload is at findings[0]["raw_result"]. (There's also a
        #   `summary` string — but it's TRUNCATED to ~500 chars. A preview, not the data.)
        #
        # BUG 3 — SHARED FILE, MULTIPLE PRODUCERS. FLOW writes presweep_* tasks to this
        #   same file. They ACCUMULATE. The owner's file had 17 responses from 4 sniper fires
        #   and 3 flow sweeps, none consumed. We must NOT delete it — flow needs it too.
        #
        # NET RESULT: fetch_x_chatter returned EMPTY on every call since it was written.
        # "chatter organic=0 on CA" was never a quiet token — there were 5 real posts
        # sitting in that file and the sniper could not see them.
        deadline = _now_ts() + timeout_s
        want = {t["task_id"] for t in tasks}
        got = {}
        _resp_file = Path(WS_JSON_RELAY) / "agent_scraper_response.json"
        while _now_ts() < deadline and len(got) < len(want):
            await asyncio.sleep(3)
            try:
                if not _resp_file.exists():
                    continue
                with open(_resp_file, encoding="utf-8") as f:
                    payload = json.load(f)
                for resp in (payload.get("responses") or []):
                    tid = resp.get("task_id")
                    if not tid or tid not in want or tid in got:
                        continue
                    if resp.get("status") != "success":
                        got[tid] = {"error": resp.get("error") or "scrape_failed"}
                        continue
                    raw = None
                    for fi in (resp.get("findings") or []):
                        if isinstance(fi, dict) and isinstance(fi.get("raw_result"), dict):
                            raw = fi["raw_result"]
                            break
                    got[tid] = raw or {"error": "no raw_result in findings"}
            except Exception as _re:
                _log(f"scraper response read err: {_re}", prefix="social")

        if len(got) < len(want):
            _log(f"x_chatter: only {len(got)}/{len(want)} scraper replies arrived "
                 f"in {timeout_s}s — the rest are MISSING, not empty", prefix="social")

        # ── CONSUME OURS, LEAVE THEIRS (Sprint 55) ──────────────────────────────
        # FLOW polls this same file. Its old consumer read the whole thing and then
        # os.remove'd the ENTIRE file — including OUR replies, before we'd collected
        # them. That is why x_chatter was always empty: not "no chatter", but MAIL
        # DELETED BEFORE DELIVERY. (Flow is fixed too — it now leaves other bots' mail.)
        #
        # We do the same courtesy: pull out only the task_ids we asked for, write the
        # rest back, and only remove the file when nothing is left for anybody.
        # A shared channel is not yours to scorch just because you're done reading.
        try:
            # ── TTL SWEEP (2026-07-27) ──────────────────────────────────────
            # "Consume yours, leave theirs" only works if every requester comes
            # back. They don't: a reply that lands after its caller stopped
            # waiting belongs to a task_id nobody will ever ask for again, and
            # nothing in the design could ever discard it. Measured 2026-07-27:
            # 655 responses, 1.7MB, oldest 13 DAYS old, 600 of them flow's
            # abandoned presweeps. This file was being json.load()'d every 3s
            # inside the wait loop below.
            #
            # A TTL is OWNER-AGNOSTIC on purpose. Past the cutoff there is no
            # live claimant by definition, so sweeping other bots' rows is not
            # scorching the channel — it is taking out mail addressed to nobody.
            # This runs even when `got` is empty (a timed-out call used to prune
            # nothing at all, which is exactly how the pile grew).
            _ttl_h = float(_envv("RELAY_RESPONSE_TTL_HOURS", "6"))
            _fail_ttl_h = float(_envv("RELAY_FAILED_TTL_HOURS", "1"))
            def _is_stale(_r):
                _ts = _r.get("completed_at")
                if not _ts:
                    return False          # can't age what isn't stamped
                try:
                    _age_h = (datetime.now() - datetime.fromisoformat(str(_ts).replace("Z", ""))
                              ).total_seconds() / 3600.0
                except Exception:
                    return False
                # a failed scrape carries no usable payload — expire it sooner
                _lim = _fail_ttl_h if _r.get("status") != "success" else _ttl_h
                return _age_h > _lim

            if _resp_file.exists():
                with open(_resp_file, encoding="utf-8") as f:
                    _payload = json.load(f) or {}
                _all = _payload.get("responses") or []
                _remaining = [r for r in _all
                              if r.get("task_id") not in got and not _is_stale(r)]
                _swept = len(_all) - len(_remaining) - len(got)
                if _swept > 0:
                    _log(f"relay TTL sweep: dropped {_swept} response(s) past TTL "
                         f"(success {_ttl_h}h / failed {_fail_ttl_h}h) — no live claimant",
                         prefix="social")
                if _remaining:
                    if len(_remaining) != len(_all):
                        _save_json_atomic(_resp_file, {"responses": _remaining})
                        _log(f"x_chatter: consumed {len(got)}, left {len(_remaining)} "
                             f"response(s) for other bots", prefix="social")
                else:
                    try:
                        _resp_file.unlink()
                    except OSError:
                        pass
        except Exception as _ce:
            _log(f"scraper relay cleanup err: {_ce}", prefix="social")

        for tid, res in got.items():
            posts = (res or {}).get("posts") or []
            # v14.2: log every handle seen promoting this token (time + mcap filled later)
            for _p in posts:
                try:
                    if isinstance(_p, dict) and _p.get("handle"):
                        record_promoter_mention(_p["handle"], mint, ticker=ticker,
                                                source=("x_ticker" if "x_ticker" in tid else "x_ca"),
                                                posted_at=_p.get("posted_at"), url=_p.get("url"))
                except Exception:
                    pass
            block = _classify_chatter(posts)
            block["_scrape_ok"] = bool((res or {}).get("ok"))
            block["_scrape_error"] = (res or {}).get("error")
            if "x_ticker" in tid:
                out["ticker_chatter"] = block
            else:
                out["ca_chatter"] = block

        # the cross-read: cashtag noise vs CA conviction
        t_org = (out.get("ticker_chatter") or {}).get("organic_count", 0)
        c_org = (out.get("ca_chatter") or {}).get("organic_count", 0)
        t_bot = (out.get("ticker_chatter") or {}).get("bot_count", 0)
        out["cross_read"] = (
            "No chatter on either the ticker or the CA. Nobody is talking about this — "
            "which for a token that's RUNNING is itself strange. Price without people."
            if (t_org + c_org + t_bot) == 0 else
            ("Loud cashtag, dead CA — the hype is manufactured. Bots spam a ticker; they "
             "don't post contract addresses. The people who actually hold this aren't talking."
             if t_bot >= 3 and c_org == 0 else
             ("Real CA chatter — people posting the raw contract are almost always actually "
              "holding or tracking it. This is the higher-quality signal of the two."
              if c_org >= 2 else
              "Thin but present. Not enough to conclude much either way."))
        )
    except Exception as e:
        out["error"] = str(e)[:200]
        _log(f"x_chatter err: {e}", prefix="social")
    return out


def _flip_history(mint: str) -> dict:
    """Did we FLIP this mint (buy AND sell it)? Reads pnl.json for our exit(s) on this
    mint and returns the round-trip history. Returns {flipped: bool, ...}.

    This is the core of the owner's insight: a token we bought and SOLD, that is STILL
    running strong on DEX at/above our exit, is not a closed win — it's a CONTINUING
    miss. The run isn't over; we left the table early. The agent should re-engage it as a
    HOLDING candidate, not misread it as a fresh scan. That requires knowing we were
    already in it, and at what levels."""
    try:
        pnl = load_pnl()
        ours = [r for r in pnl if isinstance(r, dict) and r.get("mint") == mint
                and r.get("action") == "sell" and r.get("exit_price")]
        if not ours:
            return {"flipped": False}
        # earliest entry, latest exit — the round trip
        entries = [r.get("entry_price") for r in ours if r.get("entry_price")]
        exits = [(r.get("timestamp"), r.get("exit_price"), r.get("pnl_pct")) for r in ours]
        exits.sort(key=lambda t: t[0] or "")
        first_entry = min(entries) if entries else None
        last_exit_ts, last_exit_price, last_exit_pnl = exits[-1]
        return {
            "flipped": True,
            "n_sells": len(ours),
            "entry_price": first_entry,
            "exit_price": last_exit_price,
            "exit_at": last_exit_ts,
            "realized_pnl_pct": last_exit_pnl,
            "all_exits": [{"at": t, "price": p, "pnl_pct": pp} for t, p, pp in exits],
        }
    except Exception as e:
        _log(f"_flip_history err: {e}")
        return {"flipped": False, "error": str(e)[:120]}


async def _write_flip_reengagement_packet(mint: str, pair: dict, flip: dict,
                                          current_price: float, current_mcap: float) -> None:
    """Thread B — the FLIPPED-BUT-STILL-ALIVE re-engagement packet (the owner's insight).

    Fires when a token we already FLIPPED (bought + sold) is still alive on DEX at or
    above our exit. This is DELIBERATELY a different packet from a fresh scan and from
    the missed_runner autopsy: it carries the round-trip HISTORY up top so the agent reads
    it as 'you were in this, you left early, it kept going' — a re-engagement decision,
    NOT a new token. Because we already vetted it (we bought it once), the natural
    action isn't 'evaluate from scratch' — it's 'should this be pushed to HOLDING?'"""
    base = pair.get("baseToken") or {}
    ticker = base.get("symbol") or flip.get("ticker") or "?"
    entry = flip.get("entry_price")
    our_exit = flip.get("exit_price")
    # how far past our exit is it now? (the "we left money on the table" number)
    past_exit_pct = ((current_price - our_exit) / our_exit * 100) if (our_exit and current_price) else None

    chatter = await fetch_x_chatter(ticker, mint, per_query=5)
    _native = {}
    try:
        _native = await _build_social_sentiment(mint, ticker) or {}
    except Exception as _ne:
        _native = {"error": str(_ne)[:120]}

    pc = pair.get("priceChange") or {}
    liq = _safe_num((pair.get("liquidity") or {}).get("usd")) or 0
    vol = _safe_num((pair.get("volume") or {}).get("h24")) or 0

    packet = {
        "id": f"x_evt_flip_reengage_{mint[:8]}",
        "type": "flip_reengagement",   # DISTINCT type — not meme_candidate, not missed_runner
        "received_at": _now_iso(),
        **_lane_fields("flip_reengagement"),
        "from_user": {"username": "@meme_sniper", "friendship_tier": "system", "user_id": "meme_sniper_bot"},
        "_doctrine": (
            "⚠ THIS IS NOT A FRESH SCAN. We already FLIPPED this token — bought it, sold "
            "it. It is STILL ALIVE and running at/above where we exited. That means the "
            "run wasn't over when we left; this is a CONTINUING miss, not a closed win. "
            "You already vetted this token once (you owned it), so don't re-evaluate it "
            "from zero — the question is narrower and sharper: is this a HOLD you exited "
            "too early? If it's stabilizing above our exit with real community/lore "
            "(the Gork Standard), the move is to PUSH IT TO HOLDING with a thesis, not "
            "to snipe it again like a new coin. Social INFORMS; the numbers and the lore DECIDE."
        ),
        "flip_history": {
            "we_were_in_this": True,
            "entry_price": entry,
            "our_exit_price": our_exit,
            "our_exit_at": flip.get("exit_at"),
            "realized_pnl_pct": flip.get("realized_pnl_pct"),
            "n_sells": flip.get("n_sells"),
            "all_exits": flip.get("all_exits"),
            "current_price": current_price,
            "now_vs_our_exit_pct": round(past_exit_pct, 1) if past_exit_pct is not None else None,
            "read": (
                f"You entered ~${entry:.8f}, exited ${our_exit:.8f} "
                f"({flip.get('realized_pnl_pct')}%), it's now ${current_price:.8f} "
                f"({past_exit_pct:+.0f}% past your exit) and still alive. "
                f"{'It kept running hard after you left — a clear early exit.' if (past_exit_pct or 0) >= 30 else 'Holding around your exit level — stabilizing, not dead.'}"
            ) if (entry and our_exit and current_price) else "round-trip history incomplete",
        },
        "context": {
            "mint": mint, "ticker": ticker, "name": base.get("name"),
            "current_mcap_usd": current_mcap,
            "liquidity_usd": liq, "volume_24h": vol,
            "vol_liq_ratio": round(vol / liq, 2) if liq else None,
            "price_change": {"m5": pc.get("m5"), "h1": pc.get("h1"), "h6": pc.get("h6"), "h24": pc.get("h24")},
            "chart": f"https://dexscreener.com/solana/{mint}",
            "x_chatter": chatter,
            "native_community": _native,
        },
        "decision_inputs": _decision_inputs([
            {"action_type": "push_to_holding", "when_this_fits": "we exited too early and it has lore/community — own it with a thesis"},
            {"action_type": "watch", "when_this_fits": "stabilizing but thesis not proven yet — put it on the hold watchlist"},
            {"action_type": "re_enter_flip", "when_this_fits": "still just a chart, no lore — trade it again on the same flip logic, size small"},
            {"action_type": "pass", "when_this_fits": "our exit was right, the continuation is noise — log and move on"},
        ]),
        "actions_taken": [],
    }
    write_inbox_packet_generic(packet, prefix=f"flip_reengage_{mint[:8]}", identifier=mint[:8])
    append_miss_book("flip_reengage", mint, {"ticker": ticker})
    _log(f"flip_reengage: ${ticker} still alive {past_exit_pct:+.0f}% past our exit — re-engagement packet written ({_short_mint(mint)})"
         if past_exit_pct is not None else f"flip_reengage: ${ticker} packet written ({_short_mint(mint)})", prefix="mra")


async def _write_new_wallet_packet(address: str, matched_rec: dict, track: dict) -> None:
    """Sprint 65 — 'New Wallet Found'. A wallet has recurred enough to promote to
    tracking. The agent reviews its profile and NAMES it. Deliberately lightweight — it's
    a review request, not a trade signal. The wallet's edge is UNPROVEN here (it hasn't
    cleared the 5-trade floor yet), so the packet says exactly that."""
    packet = {
        "id": f"x_evt_new_wallet_{address[:8]}",
        "type": "new_wallet_found",
        "received_at": _now_iso(),
        **_lane_fields("new_wallet_found"),
        "from_user": {"username": "@meme_sniper", "friendship_tier": "system", "user_id": "meme_sniper_bot"},
        "_doctrine": (
            "A wallet keeps showing up in the top holders of tokens we scan — it FOUND US, "
            "we didn't go hunting it. That's all this is so far: a recurrence, not a proven "
            "edge. Review its profile and, if it's worth watching, NAME it so it's memorable. "
            "Tracking of its PnL starts NOW (old wins don't count) and it needs "
            f"{WALLET_TRACK_MIN_TRADES} trades before its hit rate means anything. This is "
            "DATA to reason with — a named wallet buying later is a lead, never an order."
        ),
        "wallet": {
            "address": address,
            "times_seen": matched_rec.get("tally"),
            "first_seen_at": _iso_from_ts(matched_rec.get("first_seen")),
            "tokens_seen_in": [_short_mint(t) for t in (matched_rec.get("tokens") or [])[-10:]],
            "current_stats": {
                "trades_since_tracking": track.get("trades", 0),
                "hit_rate": track.get("hit_rate"),
                "avg_pnl_pct": track.get("avg_pnl_pct"),
                "status": "unproven — under the 5-trade floor" if not track.get("ready") else "has a read",
            },
            "chart_context": f"https://solscan.io/account/{address}",
        },
        "decision_inputs": _decision_inputs([
            {"action_type": "name_and_track", "when_this_fits": "worth watching — give it a name, keep tracking its PnL"},
            {"action_type": "keep_tracking_unnamed", "when_this_fits": "watch its PnL build before deciding"},
            {"action_type": "ignore", "when_this_fits": "not interesting — let it fall back to the matched pool"},
        ]),
        "how_to_name_it": {
            "file": "bots/json_relay/wallet_command.json",
            "shape": {"name": {address: "<your chosen name>"}},
            "note": "also accepts {\"untrack\": [addr]} to stop tracking, {\"track\": [addr]} to force-track",
        },
        "actions_taken": [],
    }
    write_inbox_packet_generic(packet, prefix=f"new_wallet_{address[:8]}", identifier=address[:8])
    _log(f"new_wallet packet: {_short_mint(address)} (seen {matched_rec.get('tally')}x)", prefix="wallet")


async def _write_wallet_tracker_packet(address: str, matched_rec: dict, move: dict, track: dict) -> None:
    """Sprint 65 — 'Wallet Tracker'. A tracked wallet just BOUGHT something. We enrich
    the bought token through the sniper's FULL pipeline (the same treatment a fresh
    candidate gets) AND attach the wallet's profile. So the agent sees both: what the token
    IS, and who's buying it + their track record. The two together are the signal — and
    it's still a signal to REASON with, not obey."""
    mint = move.get("mint")
    name = matched_rec.get("name") or _short_mint(address)
    # enrich the bought token through the sniper (GREENBULL treatment)
    enriched = None
    try:
        enriched = await build_meme_candidate_packet({"tokenAddress": mint},
                                                     surfaced_via="wallet_tracker")
    except Exception as e:
        _log(f"wallet_tracker enrich failed for {_short_mint(mint)}: {e}", prefix="wallet")

    packet = {
        "id": f"x_evt_wallet_move_{address[:8]}_{mint[:6]}",
        "type": "wallet_tracker",
        "received_at": _now_iso(),
        **_lane_fields("wallet_tracker"),
        "from_user": {"username": "@meme_sniper", "friendship_tier": "system", "user_id": "meme_sniper_bot"},
        "_doctrine": (
            f"A wallet you track ({name}) just BOUGHT {_short_mint(mint)}. Below is the "
            "sniper's full read on that token AND this wallet's track record. Weigh them "
            "together: a proven wallet buying a token that also passes our filters is a "
            "strong lead; a proven wallet buying something our filters HATE is a flag worth "
            "a look (they may know something, or be about to get rugged). The wallet's "
            "ARCHETYPE colors the read — a 'sniper' buying means a fast flip is likely "
            "coming (don't expect a hold), a 'holder'/'accumulator' buying suggests "
            "conviction, a 'rugger' buying is a WARNING not an invite. Either way it's a "
            "lead to reason with, not an order to copy. Make money; don't just mirror."
        ),
        "wallet": {
            "address": address,
            "name": matched_rec.get("name"),
            "times_seen": matched_rec.get("tally"),
            "anchor": (matched_rec.get("anchor_info") or {}).get("anchor"),
            "anchor_confidence": (matched_rec.get("anchor_info") or {}).get("confidence"),
            "track_record": {
                "trades_since_tracking": track.get("trades"),
                "hit_rate": track.get("hit_rate"),
                "avg_pnl_pct": track.get("avg_pnl_pct"),
                "total_sol_pnl": track.get("total_sol_pnl"),
                "archetype": track.get("archetype"),
                "proven": bool(track.get("ready")),
            },
            "this_move": {
                "direction": "buy",
                "sol_amount": move.get("sol_amount"),
                "token_amount": move.get("token_amount"),
                "at": _iso_from_ts(move.get("ts")),
            },
        },
        "token_enrichment": enriched or {"note": "enrichment unavailable — token may be too new/illiquid to score"},
        "decision_inputs": _decision_inputs([
            {"action_type": "consider_entry", "when_this_fits": "token passes our read AND a tracked wallet is in — strong lead"},
            {"action_type": "watch", "when_this_fits": "interesting but wait for confirmation"},
            {"action_type": "note_divergence", "when_this_fits": "wallet's in but our filters don't like it — log the divergence, watch what happens"},
            {"action_type": "pass", "when_this_fits": "not for us regardless of who's buying"},
        ]),
        "actions_taken": [],
    }
    write_inbox_packet_generic(packet, prefix=f"wallet_move_{address[:8]}", identifier=f"{address[:8]}_{mint[:6]}")
    _log(f"wallet_tracker packet: {name} bought {_short_mint(mint)} "
         f"({move.get('sol_amount')} SOL)", prefix="wallet")


def _record_tracked_buy(mint: str, address: str, name: Optional[str], ts: float) -> list:
    """Log a tracked wallet's buy into the recent-buys ledger and return the list of
    OTHER tracked wallets that bought the same mint within the cluster window. This is
    what powers cluster detection — smart money converging on one token."""
    try:
        ledger = _wallet_load(WALLET_RECENT_BUYS_FILE)
        now = time.time()
        cutoff = now - WALLET_CLUSTER_WINDOW_MIN * 60
        # prune stale entries across all mints, keep this mint's fresh ones
        pruned = {}
        for m, buys in ledger.items():
            fresh = [b for b in buys if b.get("ts", 0) >= cutoff]
            if fresh:
                pruned[m] = fresh
        entry = {"wallet": address, "name": name, "ts": ts}
        mint_buys = pruned.setdefault(mint, [])
        # dedup same wallet
        if not any(b.get("wallet") == address for b in mint_buys):
            mint_buys.append(entry)
        _save_json_atomic(WALLET_RECENT_BUYS_FILE, pruned)
        # others (not us) on this mint in-window
        return [b for b in mint_buys if b.get("wallet") != address]
    except Exception as e:
        _log(f"_record_tracked_buy err: {e}", prefix="wallet")
        return []


async def _write_cluster_packet(mint: str, buyers: list) -> None:
    """Sprint 65 — CLUSTER alert. Multiple tracked wallets bought the same token inside
    the window. This is the strongest wallet signal we produce — independent proven
    wallets converging is far more than any single buy. Enriched through the sniper so
    The agent sees the token AND who converged. Still REFERENCE — convergence can also be a
    coordinated dump. Reason, don't obey."""
    enriched = None
    try:
        enriched = await build_meme_candidate_packet({"tokenAddress": mint},
                                                     surfaced_via="wallet_cluster")
    except Exception as e:
        _log(f"cluster enrich failed {_short_mint(mint)}: {e}", prefix="wallet")

    names = [b.get("name") or _short_mint(b.get("wallet", "")) for b in buyers]
    packet = {
        "id": f"x_evt_wallet_cluster_{mint[:8]}",
        "type": "wallet_cluster",
        "received_at": _now_iso(),
        **_lane_fields("wallet_cluster"),
        "from_user": {"username": "@meme_sniper", "friendship_tier": "system", "user_id": "meme_sniper_bot"},
        "_doctrine": (
            f"{len(buyers)} wallets you track just converged on {_short_mint(mint)} within "
            f"{WALLET_CLUSTER_WINDOW_MIN} minutes. Independent proven wallets landing on the "
            "same token at once is the STRONGEST read this system makes — much more than any "
            "single buy. But convergence cuts both ways: it can be smart money early, or a "
            "coordinated pump-and-dump you're seeing from the inside. The sniper's full read "
            "on the token is below — use it to tell which. A lead to reason with, hard."
        ),
        "cluster": {
            "mint": mint,
            "buyer_count": len(buyers),
            "buyers": [{"name": b.get("name"), "wallet": b.get("wallet"),
                        "at": _iso_from_ts(b.get("ts"))} for b in buyers],
            "names": names,
        },
        "token_enrichment": enriched or {"note": "enrichment unavailable"},
        "decision_inputs": _decision_inputs([
            {"action_type": "consider_entry", "when_this_fits": "multiple proven wallets converged AND token reads well — strongest lead we make"},
            {"action_type": "watch_closely", "when_this_fits": "convergence is real but verify it's not a coordinated dump"},
            {"action_type": "pass", "when_this_fits": "convergence noted but the token itself doesn't fit us"},
        ]),
        "actions_taken": [],
    }
    write_inbox_packet_generic(packet, prefix=f"wallet_cluster_{mint[:8]}", identifier=mint[:8])
    _log(f"CLUSTER: {len(buyers)+1} tracked wallets on {_short_mint(mint)} — packet written", prefix="wallet")


# ═══════════════════════════════════════════════════════════════════════════
#     DEX TOP DIGEST (Sprint 65) — top Solana tokens on DexScreener, one packet
# ═══════════════════════════════════════════════════════════════════════════

DEX_TOP_DIGEST_QUERY_FILE    = Path(WS_JSON_RELAY) / "dex_digest_enrich_request.json"
DEX_TOP_DIGEST_QUERY_RESP    = Path(WS_JSON_RELAY) / "dex_digest_enrich_response.json"


DEX_TOP_SNAPSHOT_FILE = _BOT_LOGS / "dex_solana_top_latest.json"  # written by agent_scraper every dex_solana_top scrape
DEX_TOP_SNAPSHOT_MAX_AGE_S = 45 * 60  # if the scraper's snapshot is older than this, the digest marks itself STALE (scraper likely down)


def _trigger_dex_top_scrape() -> None:
    # FIX 7 (2026-08-16): ORPHAN. Verified zero callers , the digest path fetches
    # the Dex API directly in `_request_dex_solana_top` and the only other mention
    # is a comment noting this was removed because the scraper's browser is
    # CF-blocked. Left in place rather than deleted (a sibling module may import
    # it), but nothing on the research or digest path may call it: a second
    # writer into scraper_task.json would compete with fetch_x_chatter for the
    # same queue and produce a second, staler digest product.
    """Fire-and-forget: drop a dex_solana_top request into the scraper's task file at
    the TOP of the sniper's scan cycle. The scrape runs during the ~60s sweep, so the
    fresh snapshot is ready by the time we read it at cycle end. Append (never clobber)
    — flow and the sniper share this task file. Non-blocking: we don't wait here."""
    try:
        task_id = f"snipe_dextop_{int(_now_ts())}"
        task = {"task_id": task_id, "scrape_type": "dex_solana_top",
                "target": "solana", "max_results": DEX_TOP_DIGEST_COUNT + 20,
                "requested_by": "meme_sniper"}
        SCRAPER_TASK_FILE.parent.mkdir(parents=True, exist_ok=True)
        existing = []
        try:
            if SCRAPER_TASK_FILE.exists():
                existing = (json.loads(SCRAPER_TASK_FILE.read_text(encoding="utf-8")) or {}).get("tasks") or []
        except Exception:
            existing = []
        # don't stack duplicate dex_top requests if one's already queued
        if any(t.get("scrape_type") == "dex_solana_top" and t.get("requested_by") == "meme_sniper"
               for t in existing if isinstance(t, dict)):
            return
        _save_json_atomic(SCRAPER_TASK_FILE, {"tasks": list(existing) + [task]})
    except Exception as e:
        _log(f"_trigger_dex_top_scrape err: {e}", prefix="dex_top")


async def _request_dex_solana_top(max_results: int, timeout_s: int = 90) -> list:
    """Fetch the trending Solana board DIRECTLY from the DexScreener API — no scraper, no
    Cloudflare, no snapshot file. The scraper's browser is hard-blocked by DexScreener's
    Cloudflare, so we bypass it entirely: merge three fresh feeds (top boosts + latest
    boosts + latest profiles), enrich with full pair data, filter SOL/stable + age-cap +
    liq floor, momentum-rank. Proven to match the website's Trending 6H board.
    Runs in a thread (urllib is blocking) so it doesn't stall the event loop."""
    def _blocking_fetch():
        import urllib.request
        base = "https://api.dexscreener.com"
        hdrs = {"User-Agent": "Mozilla/5.0", "Accept": "application/json"}
        NON_TOKEN = {"SOL", "WSOL", "USDC", "USDT", "USDH", "MSOL", "STSOL", "JITOSOL", "JLP"}
        MAX_AGE_DAYS, MIN_LIQ = 90, 10000

        def _get(url):
            try:
                req = urllib.request.Request(url, headers=hdrs)
                with urllib.request.urlopen(req, timeout=12) as r:
                    return json.loads(r.read().decode("utf-8"))
            except Exception as e:
                if getattr(e, "code", None) != 429:   # 429s are logged once by the limiter
                    _log(f"dex api {_dx_short(url)} err: {type(e).__name__} {getattr(e, 'code', '') or ''}", prefix="dex_top")
                return None

        sol_cas, seen_ca = [], set()
        for feed in ("token-boosts/top/v1", "token-boosts/latest/v1", "token-profiles/latest/v1"):
            data = _get(f"{base}/{feed}")
            if isinstance(data, list):
                for b in data:
                    if b.get("chainId") == "solana":
                        ca = b.get("tokenAddress")
                        if ca and ca not in seen_ca:
                            seen_ca.add(ca)
                            sol_cas.append(ca)
        if not sol_cas:
            return []

        seen, toks = set(), []
        for i in range(0, len(sol_cas), 30):
            batch = sol_cas[i:i + 30]
            data = _get(f"{base}/tokens/v1/solana/{','.join(batch)}")
            if not isinstance(data, list):
                continue
            for pair in data:
                bt = pair.get("baseToken") or {}
                sym = (bt.get("symbol") or "").upper()
                ca = bt.get("address")
                if not ca or ca in seen or sym in NON_TOKEN:
                    continue
                seen.add(ca)
                liq = (pair.get("liquidity") or {}).get("usd") or 0
                if liq < MIN_LIQ:
                    continue
                created = pair.get("pairCreatedAt")
                if created:
                    try:
                        if (time.time() - float(created) / 1000.0) / 86400.0 > MAX_AGE_DAYS:
                            continue
                    except Exception:
                        pass
                txns = pair.get("txns") or {}
                h24t = txns.get("h24") or {}
                h1 = (pair.get("priceChange") or {}).get("h1")
                h6 = (pair.get("priceChange") or {}).get("h6")
                h24 = (pair.get("priceChange") or {}).get("h24")
                vol24 = (pair.get("volume") or {}).get("h24") or 0
                tx24 = (h24t.get("buys") or 0) + (h24t.get("sells") or 0)
                score = (vol24 ** 0.5) + max(0, h6 or 0) * 50 + max(0, h1 or 0) * 30 + (tx24 ** 0.4) * 5
                toks.append({
                    "ca": ca, "symbol": bt.get("symbol"), "name": bt.get("name"),
                    "url": pair.get("url") or f"https://dexscreener.com/solana/{ca}",
                    "price_usd": pair.get("priceUsd"), "liquidity_usd": liq, "volume_24h": vol24,
                    "price_change_h1": h1, "price_change_h6": h6, "price_change_24h": h24,
                    "pair_created_at": created,
                    "market_cap": pair.get("marketCap") or pair.get("fdv"),
                    "chain": "solana", "_score": score,
                })
        toks.sort(key=lambda x: x["_score"], reverse=True)
        for t in toks:
            t.pop("_score", None)
        return toks[:max_results]

    try:
        return await asyncio.to_thread(_blocking_fetch)
    except Exception as e:
        _log(f"_request_dex_solana_top (direct API) err: {e}", prefix="dex_top")
        return []


def _dex_top_snapshot_meta() -> dict:
    """The board is now fetched live from the API each build, so it's never stale and the
    source is always the trending API. Kept for packet-shape compatibility."""
    from datetime import datetime as _dt
    return {"scraped_at": _dt.now(EST).isoformat(), "age_seconds": 0,
            # FIX 4: this said "trending_api" and the board is built from BOOSTS +
            # PROFILES, ranked - not from a trending endpoint. A reader chasing the
            # trending API to explain a row would find nothing that produced it.
            "stale": False, "source": "boosts_plus_profiles_ranked"}


async def build_dex_top_digest() -> None:
    """Sprint 65 — ONE digest packet of the top Solana tokens on DexScreener. Light per
    token (symbol, price, 24h vol, mcap, chart) — enough to judge interest, NOT full
    enrichment (that would bloat 42 tokens into a wall). If a token catches the agent's eye
    he REQUESTS the full sniper breakdown (see the enrich-request handler) and gets a
    normal candidate packet back, flagged as requested. Hardcoded 10k mcap floor."""
    try:
        # Over-fetch HARD: the scraper sorts by 24h volume, which surfaces wSOL/USDC/USDT
        # pairs at the top (they have the most volume). After we strip those out, we need
        # enough real memes left to fill the board — so pull far more than we'll show.
        tokens = await _request_dex_solana_top(DEX_TOP_DIGEST_COUNT * 4)  # 4x, filter trims to 42
        meta = _dex_top_snapshot_meta()
        if not tokens:
            if meta.get("scraped_at") is None:
                _log("dex_top: no snapshot yet (scraper hasn't produced one) — skipping", prefix="dex_top")
            return
        rows = []
        for t in tokens:
            ca = t.get("ca") or t.get("contract") or t.get("address")
            if not ca:
                continue
            # EXCLUDE the SOL/stable/wrapper pairs — they dominate volume but they're not
            # memes. Without this the whole board is wSOL/USDC/USDT (the agent's "19/19 SOL").
            if ca in _NON_TOKEN_MINTS:
                continue
            sym = (t.get("symbol") or "").upper()
            if sym in {"SOL", "WSOL", "USDC", "USDT", "USDH", "MSOL", "STSOL", "JITOSOL", "JLP"}:
                continue
            mc = _safe_num(t.get("market_cap") or t.get("mcap") or t.get("marketCap") or t.get("fdv")) or 0
            # FIX 7: digest-floor skips are now logged too - a mint dropped here was
            # invisible to skip_log, which is the file that exists to say why.
            # require a REAL mcap at/above the floor. A null/zero mcap no longer sails
            # through — "if mc and mc < floor" let null pass; now null is skipped outright.
            if mc < DEX_TOP_DIGEST_MCAP_FLOOR:
                continue
            # age from pair_created_at (ms epoch) → human "2h", "3d" for the early/late read
            age_str = None
            _created = t.get("pair_created_at")
            if _created:
                try:
                    age_s = _now_ts() - (float(_created) / 1000.0)
                    if age_s < 3600:
                        age_str = f"{int(age_s/60)}m"
                    elif age_s < 86400:
                        age_str = f"{int(age_s/3600)}h"
                    else:
                        age_str = f"{int(age_s/86400)}d"
                except Exception:
                    pass
            # ── FIX 4 (2026-08-15): DIGEST ROWS NEVER REACHED THE LEDGER ─────
            # scanned_mints.json is the empire's answer to "have we seen this
            # before?" - it feeds dedupe, the missed-runner autopsy and every
            # "scanner showed it" claim. Digest rows were never recorded there, so a
            # token could sit on the board for hours and still read as NEVER SEEN to
            # everything downstream.
            #
            # That is how "the scanner showed it" and "we never saw it" end up both
            # being true in the same conversation about the same mint.
            try:
                record_seen_mint(ca, source="dex_top_digest",
                                 ticker=(t.get("symbol") or None), mcap=mc)
            except Exception:
                pass
            rows.append({
                "ca": ca,
                "symbol": t.get("symbol") or "?",
                "name": t.get("name"),
                "price_usd": t.get("price_usd") or t.get("priceUsd"),
                "mcap": mc or None,
                "liquidity": _safe_num(t.get("liquidity_usd")),      # real vol vs exit-trap tell
                "age": age_str,                                       # early vs late
                "volume_24h": _safe_num(t.get("volume_24h")),
                "price_change_24h": t.get("price_change_24h"),
                "price_change_h1": t.get("price_change_h1"),         # moving NOW vs lagging 24h
                "price_change_h6": t.get("price_change_h6"),         # the 6h trending window
                "chart": t.get("url") or f"https://dexscreener.com/solana/{ca}",
            })
            if len(rows) >= DEX_TOP_DIGEST_COUNT:
                break
        if not rows:
            return
        packet = {
            "id": f"x_evt_dex_top_digest_{int(_now_ts())}",
            "type": "dex_top_digest",
            "received_at": _now_iso(),
            **_lane_fields("dex_top_digest"),
            "from_user": {"username": "@meme_sniper", "friendship_tier": "system", "user_id": "meme_sniper_bot"},
            "_doctrine": (
                "The top Solana tokens on DexScreener right now — a MENU, not candidates. "
                "Each row is light on purpose but carries the fields that decide 'worth a "
                "closer look?': mcap + 24h volume (size), LIQUIDITY (real volume vs an "
                "exit-trap — high vol + thin liq is a warning), AGE (early vs late — a 2h "
                "token in the top 42 is a different bet than a 3d one), and h1 price change "
                "(moving NOW vs the lagging 24h number — +200% on 24h but -40% on h1 is "
                "dumping). Scan the board on those. If one earns depth, REQUEST the full "
                "breakdown: write its CA to dex_digest_enrich_request.json (with why) and "
                "the sniper enriches it through the full pipeline — holders, rug check, dev, "
                "socials — and delivers a candidate packet back flagged as YOUR request. "
                "The row tells you whether to order; the enrichment is the meal."
            ),
            "count": len(rows),
            "last_refreshed": meta.get("scraped_at"),
            "refreshed_age_seconds": meta.get("age_seconds"),
            "stale": meta.get("stale", False),
            "source": meta.get("source"),
            "source_warning": None,   # page scrape only; no fallback board in this build
            "stale_warning": (
                f"⚠ STALE — this board was last refreshed {int((meta.get('age_seconds') or 0)/60)}min ago; "
                "the scraper may be down. Don't trust it as live."
            ) if meta.get("stale") else None,
            "tokens": rows,
            "how_to_request_enrichment": {
                "file": "bots/json_relay/dex_digest_enrich_request.json",
                "shape": {"ca": "<contract address>", "reason": "<why you want a full read>"},
            },
            "actions_taken": [],
        }
        write_inbox_packet_generic(packet, prefix="dex_top_digest", identifier=str(int(_now_ts())))
        _log(f"dex_top digest: {len(rows)} tokens surfaced", prefix="dex_top")
    except Exception as e:
        _log(f"build_dex_top_digest err: {e}", prefix="dex_top")


async def dex_top_digest_loop() -> None:
    """Drains DEX-digest enrichment requests: when the agent asks for a full read on a CA
    from the digest, enrich it and deliver a candidate packet flagged as requested. The
    digest itself is now built inside the scan cycle (sequenced with the sweep), so this
    loop no longer builds it — it only handles the pull-back requests."""
    _log("dex_top_digest: starting (enrichment-request handler)", prefix="dex_top")
    while True:
        try:
            # drain enrichment requests (the agent pulling depth on a digest token)
            #
            # 2026-08-08 SHAPE + CLOSEOUT FIX. This read only a TOP-LEVEL `ca`, so a
            # batch request - {"source":..., "requests":[{"ca":..,"why":..}]} - had no
            # top-level ca, `if ca:` was false, and the whole block fell through:
            # no enrich, no ack, AND NO UNLINK, because the unlink lived INSIDE the
            # `if ca:`. The request file then sat on the wire forever. A live batch
            # from 08:19 (NORD/goon/SHIT/BLAKJAK) orphaned exactly this way.
            #
            # Two rules now: accept BOTH shapes, and ALWAYS close the wire - success,
            # empty enrich, bad shape, partial batch, parse error. A live-wire file
            # must never be a silent no-op; the worst outcome here is not a failed
            # enrich, it is a request that neither runs nor reports nor clears.
            if DEX_TOP_DIGEST_QUERY_FILE.exists():
                _raw_txt = None
                try:
                    _raw_txt = DEX_TOP_DIGEST_QUERY_FILE.read_text(encoding="utf-8") or "{}"
                    raw_req = json.loads(_raw_txt)
                except Exception as _pe:
                    raw_req = {"_parse_error": str(_pe)}

                def _item(it):
                    """(ca, reason) from a request entry, or None."""
                    if not isinstance(it, dict) or not it.get("ca"):
                        return None
                    return (it.get("ca"),
                            it.get("reason") or it.get("why")
                            or "requested from the DEX top digest")

                items = []
                if isinstance(raw_req, list):                      # bare list root
                    items = [x for x in (_item(i) for i in raw_req) if x]
                elif isinstance(raw_req, dict):
                    one = _item(raw_req)                           # single {ca, reason}
                    if one:
                        items = [one]
                    elif isinstance(raw_req.get("requests"), list):  # batch {requests:[...]}
                        items = [x for x in (_item(i) for i in raw_req["requests"]) if x]

                MAX_PER_CYCLE = 5
                _deferred = items[MAX_PER_CYCLE:]

                if not items:
                    # Unreadable / empty / unknown shape. Ack ONCE so a malformed
                    # request is visible rather than vanishing, then close the wire.
                    try:
                        write_inbox_packet_generic({
                            "id": f"x_evt_dex_enrich_badshape_{int(_now_ts())}",
                            "type": "dex_digest_enriched",
                            "received_at": _now_iso(),
                            **_lane_fields("dex_digest_enriched"),
                            "requested_by_agent": True,
                            "request_reason": "bad_or_empty_enrich_request_shape",
                            "_doctrine": (
                                "dex_digest_enrich_request was present but unreadable, empty, or "
                                "an unknown shape, so nothing could be enriched. Accepted shapes: "
                                '{"ca": "<mint>", "reason": "why"} or '
                                '{"requests": [{"ca": "<mint>", "why": "..."}]}. '
                                "The wire has been closed so it cannot orphan - re-send if you "
                                "still want the read."
                            ),
                            "context": {"raw_preview": (_raw_txt or "")[:400],
                                        "parse_error": (raw_req or {}).get("_parse_error")
                                        if isinstance(raw_req, dict) else None},
                            "actions_taken": [],
                        }, prefix="dex_enrich_badshape", identifier=str(int(_now_ts())))
                        _log("dex_top: enrich request unreadable/empty - acked and wire closed",
                             prefix="dex_top")
                    except Exception as _ae:
                        _log(f"dex_top badshape ack err: {_ae}", prefix="dex_top")
                else:
                    for ca, reason in items[:MAX_PER_CYCLE]:
                        try:
                            enriched = await build_meme_candidate_packet(
                                {"tokenAddress": ca}, surfaced_via="dex_digest_request")
                            if enriched:
                                # flag it as a pull, not a push - the key difference the owner wanted
                                enriched["requested_by_agent"] = True
                                enriched["request_reason"] = reason
                                enriched["type"] = "dex_digest_enriched"
                                enriched["priority"] = "high"
                                enriched["requested_at"] = _now_iso()
                                enriched["_doctrine"] = (
                                    "YOU requested this full breakdown from the DEX top digest "
                                    f"(reason: {reason}). It's the same enrichment any candidate "
                                    "gets - the only difference is you pulled it, it didn't fire "
                                    "on its own. Judge it on its merits."
                                )
                                # Deliver DIRECTLY, bypassing the candidate writer's dedup +
                                # dismissed-mint suppression: a token the agent explicitly asked
                                # about must always come back. UNIQUE timestamped identifier so
                                # repeat requests each deliver a FRESH packet.
                                write_inbox_packet_generic(
                                    enriched, prefix=f"dex_enriched_{ca[:8]}",
                                    identifier=f"{ca[:8]}_{int(_now_ts())}")
                                _log(f"dex_top: enriched {_short_mint(ca)} on request -> delivered",
                                     prefix="dex_top")
                            else:
                                write_inbox_packet_generic({
                                    "id": f"x_evt_dex_enrich_fail_{ca[:8]}_{int(_now_ts())}",
                                    "type": "dex_digest_enriched",
                                    "received_at": _now_iso(),
                                    **_lane_fields("dex_digest_enriched"),
                                    "requested_by_agent": True,
                                    "request_reason": reason,
                                    "_doctrine": (
                                        f"You asked for a full read on {_short_mint(ca)} from the DEX "
                                        "digest, but enrichment came back empty - usually means the "
                                        "token's too new, too illiquid, or not on a tracked DEX yet. "
                                        "Nothing to score. Not a red flag by itself, just no data."
                                    ),
                                    "context": {"mint": ca,
                                                "chart": f"https://dexscreener.com/solana/{ca}"},
                                    "actions_taken": [],
                                }, prefix=f"dex_enrich_fail_{ca[:8]}", identifier=ca[:8])
                                _log(f"dex_top: enrich {_short_mint(ca)} empty - told the agent",
                                     prefix="dex_top")
                        except Exception as _ee:
                            _log(f"dex_top enrich-request err {_short_mint(ca)}: {_ee}",
                                 prefix="dex_top")

                    # A batch bigger than the cap: say so rather than dropping the tail
                    # silently. The wire still closes - re-send the remainder.
                    if _deferred:
                        try:
                            write_inbox_packet_generic({
                                "id": f"x_evt_dex_enrich_overflow_{int(_now_ts())}",
                                "type": "dex_digest_enriched",
                                "received_at": _now_iso(),
                                **_lane_fields("dex_digest_enriched"),
                                "requested_by_agent": True,
                                "request_reason": "batch_over_cap",
                                "_doctrine": (
                                    f"That batch held {len(items)} mints; {MAX_PER_CYCLE} were "
                                    "enriched this cycle and the rest were NOT. The wire is closed "
                                    "either way - re-send the remainder if you still want them."
                                ),
                                "context": {"enriched": [c for c, _ in items[:MAX_PER_CYCLE]],
                                            "not_enriched": [c for c, _ in _deferred]},
                                "actions_taken": [],
                            }, prefix="dex_enrich_overflow", identifier=str(int(_now_ts())))
                        except Exception:
                            pass

                # ALWAYS close the live wire - every path above, including a throw.
                try:
                    DEX_TOP_DIGEST_QUERY_FILE.unlink()
                except Exception:
                    pass
        except Exception as e:
            _log(f"dex_top_digest_loop err: {e}", prefix="dex_top")
        await asyncio.sleep(60)


async def _write_opportunity_packet(mint: str, pair: dict, ledger_entry: dict,
                                     ratio: float) -> None:
    """Sprint 53 — THE OPPORTUNITY PACKET (the owner's call).

    THE FLAW IT FIXES: the missed_runner autopsy only fires at 80% drawdown from peak —
    it tells the agent about a runner AFTER it's dead. The lesson arrives when the door is
    already shut. But a token that just 4x'd and is STILL RUNNING is live intelligence,
    not a eulogy. The autopsy system treated every missed runner as a closed door; some
    doors are wide open.

    So: when something in our ledger runs and is still ALIVE, fire THIS instead of an
    autopsy. Full token data + real X chatter (ticker AND CA, bot-filtered). The agent
    decides: chase, watch, or pass.

    And this doubles as the HOLD on-ramp. If a token has run and then STABILIZED —
    holding its level rather than bleeding — that's the market saying this isn't a flip;
    something about it (community, dev, lore) is holding a floor. That's precisely when
    he should stop thinking in flip terms and go research whether it's worth OWNING. The
    $GORK standard is the benchmark: is there real lore here, or just a chart?
    """
    base = pair.get("baseToken") or {}
    ticker = base.get("symbol") or "?"
    mcap = _safe_num(pair.get("marketCap") or pair.get("fdv")) or 0
    liq  = _safe_num((pair.get("liquidity") or {}).get("usd")) or 0
    vol  = _safe_num((pair.get("volume") or {}).get("h24")) or 0
    pc   = pair.get("priceChange") or {}
    txns = pair.get("txns") or {}
    created = pair.get("pairCreatedAt")
    age_h = ((_now_ts() * 1000 - created) / 3_600_000) if created else None

    # the real chatter — 5 on the ticker, 5 on the CA, bot-filtered
    chatter = await fetch_x_chatter(ticker, mint, per_query=5)

    # AND the native community (coincomms / pump.fun chat). For a STABILIZING runner —
    # the moment the hold question gets asked — this is the number that matters most.
    # X tells you who's shouting about it. coincomms tells you who's actually IN it.
    _native = {}
    try:
        _native = await _build_social_sentiment(mint, ticker) or {}
    except Exception as _ne:
        _native = {"error": str(_ne)[:120]}

    def _tx(w):
        d = txns.get(w) or {}
        return {"buys": d.get("buys"), "sells": d.get("sells")}

    packet = {
        "_type": "opportunity",
        "_doctrine": (
            "A token we SAW is running and is STILL ALIVE. This is not an autopsy — the "
            "door is open. Decide: chase, watch, or pass. And read the stabilization: if "
            "it ran and is now HOLDING its level rather than bleeding, the market is "
            "telling you this might not be a flip at all. Something is holding a floor — "
            "community, dev, lore. That's when you stop thinking in flip terms and go "
            "research whether it's worth OWNING (promote to hold with a thesis). Use the "
            "Gork Standard as the bar: is there real lore here, or just a chart? "
            "Social INFORMS this call; the numbers DECIDE it."
        ),
        "mint": mint,
        "ticker": ticker,
        "written_at": _now_iso(),
        "run": {
            "ratio_from_our_scan": round(ratio, 2),
            "scan_mcap": ledger_entry.get("first_mcap"),
            "current_mcap": mcap,
            "first_seen": ledger_entry.get("first_seen"),
        },
        "token_data": {
            "price_usd": pair.get("priceUsd"),
            "mcap": mcap,
            "liquidity_usd": liq,
            "volume_24h": vol,
            "vol_liq_ratio": round(vol / liq, 2) if liq else None,
            "age_hours": round(age_h, 1) if age_h else None,
            "price_change": {"m5": pc.get("m5"), "h1": pc.get("h1"),
                             "h6": pc.get("h6"), "h24": pc.get("h24")},
            "txns": {"m5": _tx("m5"), "h1": _tx("h1"), "h24": _tx("h24")},
            "chart": f"https://dexscreener.com/solana/{mint}",
        },
        # STABILIZATION READ — the hold on-ramp. A runner that stops bleeding is a
        # different animal from one that's still vertical or already dumping.
        "stabilization": {
            "h1_change": pc.get("h1"),
            "h6_change": pc.get("h6"),
            "read": (
                "STILL VERTICAL — the move is in progress. Chasing a vertical is how you "
                "buy someone else's exit. If you want in, wait for it to stop going up."
                if _safe_num(pc.get("h1")) and _safe_num(pc.get("h1")) > 20 else
                ("BLEEDING — it ran and is now giving it back. This is the tail of the move, "
                 "not the start. Pass unless you have a reason the bleed stops."
                 if _safe_num(pc.get("h1")) and _safe_num(pc.get("h1")) < -10 else
                 "STABILIZING — it ran and is now HOLDING its level rather than bleeding. "
                 "This is the interesting case. Something is defending this floor. Go find "
                 "out WHAT: real community? dev shipping? actual lore? If yes, this is a "
                 "HOLD candidate, not a flip. If you can't find a reason, the floor is an "
                 "illusion and it will break.")
            ),
        },
        "x_chatter": chatter,
        "native_community": {
            "coincomms_ca": (_native.get("coincomms_ca") or {}),
            "coincomms_ticker": (_native.get("coincomms_ticker") or {}),
            "pvp_flag": _native.get("pvp_flag"),
            "summary": _native.get("summary"),
            "_why_this_matters": (
                "coincomms is the token's OWN chat — the holders talking IN it, not the outside "
                "world talking ABOUT it. If you are considering a HOLD, this is the number that "
                "grades the thesis. X can be raided by anyone with a bot farm; NOBODY bots the "
                "pump.fun chat of a coin they don't hold. So a loud cashtag with a dead native "
                "chat is a MARKETING BUDGET, not a community — and there is nothing there to own. "
                "A quiet cashtag with a live native chat is the opposite, and far more interesting."
            ),
        },
        # The GORK standard, injected. A STABILIZING runner is the exact moment the
        # hold question gets asked — so the rubric is right here, not re-derived from
        # memory. Note the C1 hard cap: a token this young almost certainly CANNOT be a
        # hold no matter how good it looks. That is deliberate. Snipe it if you want;
        # do not give it patience capital.
        "market_weather": build_market_weather(),
        "gork_standard": load_gork_standard(),
        "hold_score_note": (
            "If you are thinking about HOLDING this: score it against the GORK standard "
            "(above). LOAD-BEARING = c1 (time under fire), c2 (red-tape output), c4 (origin "
            "integrity). Fail any one and it is NOT-A-HOLD regardless of everything else — "
            "you do not average away a kill switch. And note C1 honestly: a young token "
            "CANNOT score high on time-under-fire, so it CANNOT be a hold yet. That is the "
            "point. The snipe lane is open; the hold lane stays closed until the bag has "
            "lived through fire."
        ),
        "questions_for_agent": [
            "Is this still an entry, or am I looking at someone else's exit?",
            "Is the chatter organic or a raid? (check bot_count vs organic_count, and "
            "whether ANYONE is posting the raw CA — bots don't post contract addresses)",
            "Has it STABILIZED? If it ran and is now holding, why? What's defending the floor?",
            "Is there real lore/community here, or just a chart? (score it against $GORK)",
            "If I take this: is it a FLIP (chase the continuation) or a HOLD (I actually "
            "want to own this)? They are different trades with different rules.",
        ],
    }
    try:
        _INBOX.mkdir(parents=True, exist_ok=True)
        fname = (f"meme_sniper - opportunity_{ticker}_{mint[:8]}_"
                 f"{datetime.now().strftime('%Y%m%d_%H%M%S')}.json")
        with open(_INBOX / fname, "w", encoding="utf-8") as f:
            json.dump(packet, f, indent=2)
        append_miss_book("opportunity", mint, {"ticker": ticker, "mcap": mcap, "ratio": ratio})
        _log(f"OPPORTUNITY: {ticker} ({_short_mint(mint)}) ran {ratio:.1f}x and is STILL ALIVE "
             f"| mcap=${mcap:,.0f} | chatter organic="
             f"{(chatter.get('ca_chatter') or {}).get('organic_count', 0)} on CA",
             prefix="opportunity")
    except Exception as e:
        _log(f"opportunity packet write err: {e}", prefix="opportunity")


async def hold_full_rescan(mint: str, position: dict) -> dict:
    """Sprint 53 — a HELD token gets the FULL PICTURE, freshly fetched, every update.

    THE PROBLEM THIS FIXES: the hold doc was being fed ~8 fields scraped off the monitor
    tick, and several of them (`last_holder_count`, `last_top10_pct`, `last_dev_pct`) are
    STALE SNAPSHOTS taken at entry — they don't move. So a "living doc" was recording a
    dead picture: the price moved, nothing else did. You cannot re-underwrite a hold on
    numbers that are frozen at the moment you bought.

    A held token is the ONE thing that deserves the most data, not the least. He isn't
    flipping it — he's OWNING it, over days, and the whole point is to watch the thesis
    hold or break. So: re-run the FULL candidate enrichment (all 33 blocks — holders,
    rug_check, lp_lock, deployer, narrative, social, trade_pressure, pattern, brand
    resolution, the lot), live, every update.

    Returns the full context dict, or a minimal fallback if the enrichment fails (e.g.
    the token dumped below the $10K scan floor, which the builder rejects — that itself
    is a signal worth recording, not an error to swallow).
    """
    try:
        pkt = await build_meme_candidate_packet(
            {"tokenAddress": mint, "chainId": "solana"},
            surfaced_via="hold_rescan",
        )
        if pkt and pkt.get("context"):
            return pkt["context"]
    except Exception as e:
        _log(f"hold_full_rescan err {_short_mint(mint)}: {e}", prefix="hold")

    # Enrichment failed or the builder rejected it. The most common reason is the token
    # fell BELOW the $10K scan floor — which for a token you're HOLDING is not a null
    # result, it's an alarm. Record it as such.
    try:
        pair = await fetch_token_data(mint)
    except Exception:
        pair = None
    mcap = _safe_num((pair or {}).get("marketCap") or (pair or {}).get("fdv")) or 0
    return {
        "_rescan_degraded": True,
        "_rescan_note": (
            f"Full enrichment unavailable. Current mcap ${mcap:,.0f}. "
            + ("⚠ THIS TOKEN IS BELOW THE $10K SCAN FLOOR — it has fallen out of the "
               "universe we even scan. For a token you chose to HOLD, that is not a data "
               "gap, it is a verdict. Re-underwrite immediately."
               if mcap and mcap < 10_000 else
               "Could not fetch full detail this cycle; numbers below are partial.")
        ),
        "mcap": mcap,
        "dex_data": pair or {},
    }


# ─── THE HOLD FOLDER (per-bag memory system, the agent's spec) ───────────────────
# ONLY hold-lane bags get a folder. A flip already has the autopsy record.
# This is for PATIENCE CAPITAL. If it never earned a hold-score, it does not get a
# shrine.
#
#   holds/<TICKER>_<mint8>/
#     entry_card.md    FROZEN at promotion. Never edited. History needs a clean BEFORE.
#     live_card.md     Mutable. Current scores, last rescore, why.
#     evidence.md      Pointable proof only. "If it isn't pointable, it didn't happen."
#     timeline.md      Append-only: date | event | score delta | action.
#     moonbag.md       On exit only. Entry vs exit, load-bearing axes, the lesson.
#
# THE PROOF RULE: the folder stores only what can be RE-CHECKED. Links, windows, CA
# checks, roster notes. Never "CT said it was organic." That rule is what fixes the
# problem of not having been there for the tokens you didn't live through.

def _hold_series_append(mint: str, row: dict, ticker: str = None) -> None:
    """Sprint 53 — THE NUMBERS, STORED AS DATA. One compact JSONL row per update.

    THE PROBLEM THIS SOLVES: the live card is markdown prose. Beautiful to read, useless
    to query. Over a two-week hold at a 30-min cadence that's ~670 formatted blocks, and
    the numbers are TRAPPED IN TEXT. The agent cannot ask "has liquidity been bleeding for
    three days straight?" because the answer is smeared across 144 paragraphs. And the
    file grows without bound.

    So: every update ALSO writes one flat row to series.jsonl. Numbers only, no prose.
    ~200 bytes each — a month of holding is ~300KB, nothing. But now the whole history is
    QUERYABLE: trend it, diff it, spot the slow bleed that no single snapshot reveals.

    A hold lives or dies on TRAJECTORY, not on any one reading. The thing that kills a
    hold is rarely a single bad number — it's holders leaking 2% a day for a week while
    every individual update looks "fine." Only the series shows you that.
    """
    try:
        with open(_hold_file(mint, "series.jsonl", ticker), "a", encoding="utf-8") as f:
            f.write(json.dumps(row, separators=(",", ":")) + "\n")
    except Exception as e:
        _log(f"hold series append err {_short_mint(mint)}: {e}", prefix="hold")


def hold_series_load(mint: str, ticker: str = None, limit: int = 500) -> list:
    """Read the numeric history back. This is what the agent investigates when he starts
    doubting a hold."""
    p = _hold_file(mint, "series.jsonl", ticker)
    if not p.exists():
        return []
    rows = []
    try:
        with open(p, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    rows.append(json.loads(line))
                except Exception:
                    continue
    except Exception:
        return []
    return rows[-limit:]


def hold_series_trends(mint: str, ticker: str = None) -> dict:
    """Compute the TRAJECTORY from the series. This is the read a single snapshot cannot
    give you, and it's the one that actually decides a hold.

    A hold rarely dies from one bad number. It dies from a slow bleed where every
    individual update looks acceptable — holders leaking, liquidity thinning, volume
    fading — until one day the thing is hollow and you're the exit liquidity. The series
    is the only place that's visible.
    """
    rows = hold_series_load(mint, ticker)
    if len(rows) < 3:
        return {"enough_data": False, "n": len(rows)}

    def _first_last(key, hours):
        cutoff = _now_ts() - hours * 3600
        window = [r for r in rows if (r.get("ts") or 0) >= cutoff and r.get(key) is not None]
        if len(window) < 2:
            return None
        a, b = window[0].get(key), window[-1].get(key)
        if not a:
            return None
        return round((b - a) / a * 100, 1)

    out = {"enough_data": True, "n": len(rows), "trends": {}}
    for key in ("mcap", "liq", "holders", "vol_24h", "price", "cc_msgs"):
        out["trends"][key] = {
            "6h":  _first_last(key, 6),
            "24h": _first_last(key, 24),
            "72h": _first_last(key, 72),
        }

    # THE SLOW BLEED DETECTOR — the failure mode a snapshot cannot see.
    warnings = []
    h24 = out["trends"]["holders"]["24h"]
    h72 = out["trends"]["holders"]["72h"]
    l72 = out["trends"]["liq"]["72h"]
    v72 = out["trends"]["vol_24h"]["72h"]
    # -7% over 72h with no single day looking bad is EXACTLY the kill pattern: ~2-3%/day
    # is invisible in any one reading, and compounds into an empty bag. Tuned deliberately
    # tight — a false alarm costs a re-read; a missed slow bleed costs the position.
    if h72 is not None and h72 <= -7 and (h24 is None or h24 > -5):
        warnings.append({
            "signal": "slow_holder_bleed",
            "detail": f"holders {h72:+.1f}% over 72h — but only {h24:+.1f}% in the last 24h",
            "read": ("This is the one a snapshot CANNOT see. No single update looks alarming; "
                     "the bag is quietly emptying out. People are leaving steadily and the daily "
                     "number never screams. By the time it does, you're the exit liquidity."),
        })
    if l72 is not None and l72 <= -25:
        warnings.append({
            "signal": "liquidity_thinning",
            "detail": f"liquidity {l72:+.1f}% over 72h",
            "read": "The pool is draining. Your exit gets worse every day you wait.",
        })
    if v72 is not None and v72 <= -50:
        warnings.append({
            "signal": "volume_death",
            "detail": f"24h volume {v72:+.1f}% over 72h",
            "read": ("Attention is gone. A memecoin with no volume is a memecoin with no bid. "
                     "Check C2 — is the community still speaking, or did they leave too?"),
        })

    # ── THE NATIVE COMMUNITY GOING SILENT (the strongest hold-breaking signal) ───
    # coincomms is the token's OWN chat. A hold thesis IS a community thesis — you bought
    # it because people were there. If they stop talking in their own house, they left.
    #
    # This outranks every other social signal. X can be raided, cashtags can be botted,
    # a paid KOL can make anything look alive. But nobody bots the pump.fun chat of a
    # coin they don't hold — there's no reason to. So when THIS number goes to zero, the
    # community you underwrote is gone, and you are holding a ghost town.
    cc24 = _first_last("cc_msgs", 24)
    cc72 = _first_last("cc_msgs", 72)
    cc_now = next((r.get("cc_msgs") for r in reversed(rows) if r.get("cc_msgs") is not None), None)
    if cc72 is not None and cc72 <= -60:
        warnings.append({
            "signal": "native_community_dying",
            "detail": f"coincomms messages {cc72:+.1f}% over 72h (now {cc_now})",
            "read": ("⚠ THE COMMUNITY IS LEAVING ITS OWN CHAT. This is the strongest hold-breaking "
                     "signal available and it outranks everything else on this page. X can be "
                     "raided; cashtags can be botted; a paid KOL can make a corpse look alive. But "
                     "NOBODY bots the pump.fun chat of a coin they don't hold — there is no reason "
                     "to. So this number is the one that cannot be faked at you. Your hold thesis "
                     "WAS the community. Go re-read C2 (red-tape output) and C9 (holder doctrine) "
                     "in your own scorecard, then ask honestly whether the thing you underwrote "
                     "still exists."),
        })
    elif cc_now is not None and cc_now == 0 and len(rows) > 6:
        warnings.append({
            "signal": "native_community_silent",
            "detail": "zero messages in the token's own chat",
            "read": ("Nobody is talking in the coin's own house. Whatever the price is doing, the "
                     "community you bought is not there anymore. Price without people is a chart, "
                     "not a thesis."),
        })
    out["warnings"] = warnings
    out["degrading"] = bool(warnings)
    return out


def _hold_posts_append(mint: str, chatter: dict, ticker: str = None) -> None:
    """Archive EVERY X post we pull — ticker and CA searches both, organic and bot.

    The live card quotes 3 organic CA posts. The rest evaporate. That's a mistake: when
    The agent starts doubting a hold, the FIRST thing he needs is the record of what the
    community was actually saying over time — including what the bots were saying, since
    a raid pattern IS the signal.

    Kept as JSONL, one post per line, deduped by tweet_id. Cheap, complete, greppable.
    """
    try:
        seen_p = _hold_file(mint, "posts.jsonl", ticker)
        seen = set()
        if seen_p.exists():
            with open(seen_p, "r", encoding="utf-8") as f:
                for line in f:
                    try:
                        seen.add(json.loads(line).get("tweet_id"))
                    except Exception:
                        continue
        rows = []
        for src_key, src in (("ticker", chatter.get("ticker_chatter") or {}),
                             ("ca", chatter.get("ca_chatter") or {})):
            for bucket, is_bot in (("organic", False), ("bots", True)):
                for p_ in (src.get(bucket) or []):
                    tid = p_.get("tweet_id")
                    if not tid or tid in seen:
                        continue
                    seen.add(tid)
                    rows.append({
                        "ts": _now_ts(), "at": _now_iso(),
                        "query": src_key,          # was it found by $TICKER or by CA?
                        "bot": is_bot,
                        "bot_reason": p_.get("_bot_reason"),
                        "tweet_id": tid,
                        "handle": p_.get("handle"),
                        "text": (p_.get("text") or "")[:500],
                        "likes": p_.get("likes"), "reposts": p_.get("reposts"),
                        "replies": p_.get("replies"),
                        "posted_at": p_.get("posted_at"),
                        "url": p_.get("url"),
                    })
        if rows:
            with open(seen_p, "a", encoding="utf-8") as f:
                for r in rows:
                    f.write(json.dumps(r, separators=(",", ":")) + "\n")
    except Exception as e:
        _log(f"hold posts append err {_short_mint(mint)}: {e}", prefix="hold")


async def hold_grok_digest(mint: str, ticker: str, ctx: dict, trends: dict,
                           chatter: dict, thesis: dict) -> dict:
    """Sprint 53 — GROK READS THE HOLD BEFORE AGENT DOES.

    Same pattern as the scan path: Grok pre-digests the raw material so the agent gets a
    READ, not a data dump. But the question here is different, and harder.

    On a scan, the question is "is this worth buying?" — a snap judgment on a fresh
    token. On a HOLD, the question is "does the thesis still stand?" — which requires
    looking at TRAJECTORY (the series), the COMMUNITY'S BEHAVIOR UNDER PRESSURE (the
    posts, especially on red days), and whether the specific falsifier he wrote has been
    tripped. That's a synthesis job, and it's exactly what Grok is for.

    Doctrine enforced in the prompt: SOCIAL INFORMS, NUMBERS ACT. Grok is explicitly told
    it may not recommend a sell on vibes alone.
    """
    try:
        _tc = (chatter.get("ticker_chatter") or {})
        _cc = (chatter.get("ca_chatter") or {})
        posts_sample = [
            f"[{'BOT' if p.get('_bot_reason') not in (None,'organic') else 'ORGANIC'}] "
            f"@{p.get('handle','?')}: {(p.get('text') or '')[:200]}"
            for p in ((_cc.get("organic") or []) + (_tc.get("organic") or []))[:8]
        ]
        prompt = f"""You are reading a token the agent is HOLDING (not flipping). Your job is to answer ONE question: DOES THE THESIS STILL STAND?

HIS ORIGINAL THESIS: {thesis.get('thesis','(none)')}
HIS FALSIFIER (what he said would make him sell): {thesis.get('falsifier','(none)')}
HOLD-SCORE AT PROMOTE: {thesis.get('raw_avg','?')}/10 ({thesis.get('band','?')})

LIVE NUMBERS:
- mcap ${_safe_num(ctx.get('mcap')) or 0:,.0f} | liquidity ${_safe_num(ctx.get('liquidity_usd')) or 0:,.0f}
- holders {(ctx.get('holders') or {}).get('holder_count')} | top10 {(ctx.get('holders') or {}).get('top10_pct')}% | dev {(ctx.get('holders') or {}).get('dev_holding_pct')}%
- vol24h ${_safe_num(ctx.get('volume_24h')) or 0:,.0f}

TRAJECTORY (this is the part a single snapshot cannot show):
{json.dumps(trends.get('trends', {}), indent=1)}
Slow-bleed warnings: {json.dumps(trends.get('warnings', []), indent=1)}

NATIVE COMMUNITY (coincomms / pump.fun chat — THE ONE THAT GRADES A HOLD THESIS):
messages on CA: {ctx.get('message_count') or (ctx.get('social_sentiment') or {}).get('coincomms_ca', {}).get('message_count')} | spam ratio: {(ctx.get('social_sentiment') or {}).get('coincomms_ca', {}).get('spam_ratio')}
(X is the outside talking ABOUT it. coincomms is the holders talking IN it. Nobody bots the pump.fun chat of a coin they don't hold — so this is the number that cannot be faked at you.)

X CHATTER — $TICKER: {_tc.get('organic_count',0)} organic / {_tc.get('bot_count',0)} bot. CA: {_cc.get('organic_count',0)} organic / {_cc.get('bot_count',0)} bot.
Cross-read: {chatter.get('cross_read','')}
Sample posts:
{chr(10).join(posts_sample) if posts_sample else '(none)'}

ANSWER, briefly:
1. HAS THE FALSIFIER TRIPPED? Quote his own falsifier and say plainly yes/no/approaching.
2. TRAJECTORY READ — is this bleeding slowly? The killer is the slow bleed no single update reveals.
3. COMMUNITY UNDER PRESSURE — if the price is red, are they still speaking? (Green can fake lore; RED AUDITS IT.) WEIGH THE NATIVE CHAT (coincomms) ABOVE X: X can be raided by anyone with a bot farm, but nobody bots the pump.fun chat of a coin they don't hold. If the native chat is dying while the cashtag is loud, that is a MARKETING BUDGET, not a community — and the hold thesis is already dead.
4. VERDICT: HOLD / RE-UNDERWRITE / DEMOTE-TO-FLIP — and the ONE number that drives it.

HARD RULE: social INFORMS, numbers ACT. You may NOT recommend a sell on vibes alone — name the metric. If the numbers are fine and only the mood is off, say "hold, but watch X."
Be blunt. If he's holding a corpse, say so."""
        out = await grok_generate(prompt, max_tokens=700)
        return {"digest": out, "at": _now_iso()}
    except Exception as e:
        return {"digest": None, "error": str(e)[:200]}


ROTATION_STATE_FILE_FLOW = (FLOW_DATA_DIR / "rotation_state.json") if PIPE_FLOW_ENABLED else _PIPE_DISABLED_FILE
PATTERN_MATCHES_FILE_FLOW = (FLOW_DATA_DIR / "pattern_matches_live.json") if PIPE_FLOW_ENABLED else _PIPE_DISABLED_FILE
MACRO_JSON_FILE_FLOW = (FLOW_DATA_DIR / "macro.json") if PIPE_FLOW_ENABLED else _PIPE_DISABLED_FILE


def build_market_weather() -> dict:
    """Sprint 54 — THE MARKET WEATHER. Context to REASON with, not a gate to obey.

    THE PROBLEM: the sniper reads exactly four things from flow_cycle —
    regime_break_signal, sniper_aggression, current_phase, no_buy_zone — and uses all
    four as GATES. Block, allow, or (until Sprint 53) silently shrink. Meanwhile flow is
    sitting on a rotation engine whose stages are literally named MEME_SEASON and
    ALT_SEASON, and the memecoin sniper has never once seen it.

    THE DOCTRINE (the owner's, and it's the right one):
      Flow tells you WHERE IN THE MARKET CYCLE we are. That is a WEATHER REPORT, not an
      order. There is ALWAYS money to be made — the cycle position dictates HOW, not
      WHETHER. A Panic-phase memecoin market is not a closed market; it's a market where
      the winners look different (smaller, faster, meaner) and the losers rug harder.
      Euphoria is not a green light; it's the phase where everything runs AND everything
      is a trap.

      AND — the part that keeps this honest — a memecoin can run on PURE ABSURDITY,
      completely uncorrelated to any of this. Some things are funny and dumb and moon
      because they're funny and dumb. That is not a bug in the model, it is THE THESIS of
      the entire asset class. Which is exactly WHY the token-specific info (community,
      dev, brand, lore) matters more than the macro: the macro tells you the odds, the
      token tells you the story, and the story is what actually runs.

      So: reason with it. Never obey it. If a token is genuinely funny and the community
      is real, Panic doesn't make it not funny. But Panic DOES mean fewer buyers, thinner
      liquidity, faster rugs — so size accordingly and be quicker to leave.
    """
    out = {
        "_doctrine": (
            "WEATHER, NOT ORDERS. Flow tells you where in the market cycle we are. There is "
            "ALWAYS money to be made — the cycle dictates HOW, not WHETHER. Reason with this; "
            "never obey it. And remember: a memecoin can run on pure absurdity, completely "
            "uncorrelated to any of this. Some things are funny and dumb and moon BECAUSE "
            "they're funny and dumb — that is not noise in the model, it IS the asset class. "
            "Which is exactly why the TOKEN-SPECIFIC info (community, dev, brand, lore) "
            "outranks the macro: the macro gives you the odds, the token gives you the story, "
            "and the story is what actually runs."
        ),
    }

    # ── ROTATION: the single most relevant flow signal for a MEMECOIN sniper ──
    try:
        rot = load_json_with_staleness(ROTATION_STATE_FILE_FLOW, max_age_seconds=86400,
                                       default={}, alert_on_stale=False) or {}
        stage = rot.get("stage")
        out["rotation"] = {
            "stage": stage,
            "sol_btc_21d": rot.get("sol_btc_divergence_pct"),
            "eth_btc_21d": rot.get("eth_btc_divergence_pct"),
            "read": rot.get("read"),
            "what_it_means_for_YOU": {
                "MEME_SEASON": (
                    "🔥 CAPITAL IS ROTATING INTO EXACTLY WHAT YOU TRADE. SOL is outperforming BTC "
                    "and ETH hasn't followed yet — historically the leg where memecoins run "
                    "hardest. This is your season. It does NOT mean buy everything; it means the "
                    "tape is BEHIND you instead of against you, so a good setup has more room to "
                    "work and a mediocre one might still pay. Be more willing to take the shot."
                ),
                "ALT_SEASON": (
                    "Capital is broadly down the risk curve — memecoins still work, but attention "
                    "is being SHARED with alts now. Mid-to-late rotation. The easy money in this "
                    "leg has usually been made \u2014 historically, late-rotation entries have needed "
                    "tighter selection and shorter holds to pay."
                ),
                "BLOWOFF_RISK": (
                    "⚠ LATE-CYCLE. Everything runs AND everything is a trap. This is the phase "
                    "where memecoins print the biggest numbers and rug the hardest, often in the "
                    "same week. Trade it, but treat every position as borrowed. Tighten stops. "
                    "Do NOT promote anything to hold here — you cannot underwrite a community "
                    "that was assembled during a mania."
                ),
                "BTC_LED": (
                    "No rotation into risk yet. BTC is leading and alts aren't diverging — the "
                    "memecoin tape is running on its own energy, not on a capital tailwind. That "
                    "does NOT mean nothing runs. It means what runs will run on its OWN merits: "
                    "a genuinely funny/viral/real-community token can still moon in a BTC-led "
                    "tape, because absurdity doesn't need permission from the macro. But there is "
                    "no tide lifting you, so the token itself has to carry the whole trade. "
                    "Demand more from the setup."
                ),
                "COOLING": (
                    "Rotation is unwinding — risk is coming OFF the curve. Buyers are leaving the "
                    "far end of the risk spectrum, and memecoins ARE the far end. Thinner "
                    "liquidity, faster exits, meaner rugs. Smaller size, quicker to leave. Still "
                    "tradeable — just don't confuse a bounce for a trend."
                ),
                "ETH_LED": (
                    "ETH outperforming with SOL lagging — atypical. Probably an ETH-specific "
                    "catalyst rather than broad rotation into risk. Little direct read-through to "
                    "the memecoin tape. Judge tokens on their own."
                ),
            }.get(stage, "Rotation state unavailable — judge tokens on their own merits."),
        }
    except Exception as e:
        out["rotation"] = {"error": str(e)[:100]}

    # ── MACRO: the retail-appetite read (this is what actually moves memecoin volume) ──
    try:
        macro = load_json_with_staleness(MACRO_JSON_FILE_FLOW, max_age_seconds=86400,
                                         default={}, alert_on_stale=False) or {}
        blow = macro.get("blowoff") or {}
        fg = _safe_num(macro.get("fear_greed"))
        out["macro"] = {
            "flow_score": blow.get("score"),
            "phase": macro.get("phase"),
            "signal": blow.get("signal"),
            "fear_greed": fg,
            "btc_price": macro.get("btc_price"),
            "sol_price": macro.get("sol_price"),
            "btc_dom": macro.get("btc_dom"),
            "retail_appetite_read": (
                None if fg is None else
                ("EXTREME FEAR — retail is gone. Memecoin volume dries up here, which cuts both "
                 "ways: fewer bag-holders to sell into you, but also fewer buyers to sell TO. "
                 "The tokens that run in extreme fear run on pure novelty/absurdity, because "
                 "nothing else is pulling money in. Size small, exit fast, and demand that the "
                 "token be genuinely interesting on its own."
                 if fg <= 25 else
                 "FEAR — thin retail participation. Selective tape. Quality of the token matters "
                 "more than usual because there's no crowd to carry a mediocre one."
                 if fg <= 45 else
                 "NEUTRAL — normal participation. The tape is neither helping nor hurting you."
                 if fg <= 55 else
                 "GREED — retail is engaged and chasing. Memecoin volume is high; this is when "
                 "mediocre tokens can still run on momentum alone. Good for flips. DANGEROUS for "
                 "holds — a community that formed during greed has never been tested."
                 if fg <= 75 else
                 "EXTREME GREED — everything runs and everyone is a genius. This is the most "
                 "dangerous tape there is, precisely because it feels the easiest. Rugs are "
                 "maximally profitable for the rugger right now. Trade it, but assume every "
                 "counterparty is smarter than you.")
            ),
        }
    except Exception as e:
        out["macro"] = {"error": str(e)[:100]}

    # ── the honest caveat, stated every single time ──
    out["how_to_use_this"] = (
        "This is CONTEXT, not a decision. It changes HOW you size and HOW fast you leave — it "
        "does not decide WHETHER a token is good. The token's own facts (community, dev, brand, "
        "lore, structure) outrank all of this, because a memecoin's thesis is the TOKEN, not the "
        "market. A genuinely funny coin with a real community can run in Panic. A perfectly-timed "
        "entry into a soulless token will still go to zero in Euphoria. "
        "USE THE WEATHER TO PICK YOUR CLOTHES, NOT YOUR DESTINATION."
    )
    return out


def _hold_folder(mint: str, ticker: str = None):
    """The folder for a held bag. One per hold, lives as long as the hold does."""
    tk = (ticker or "TOKEN").replace("/", "_").replace("\\", "_")[:16]
    d = HOLDS_DIR / f"{tk}_{mint[:8]}"
    d.mkdir(parents=True, exist_ok=True)
    return d


def _hold_file(mint: str, name: str, ticker: str = None):
    return _hold_folder(mint, ticker) / name


def _hold_append(mint: str, fname: str, block: str, ticker: str = None) -> None:
    try:
        with open(_hold_file(mint, fname, ticker), "a", encoding="utf-8") as f:
            f.write(block.rstrip() + "\n\n")
    except Exception as e:
        _log(f"hold folder append err {_short_mint(mint)}/{fname}: {e}", prefix="hold")


def _hold_doc_path(mint: str, ticker: str = None):
    """Back-compat: the 'doc' is now the live card inside the folder."""
    return _hold_file(mint, "live_card.md", ticker)


def _hold_doc_append(mint: str, block: str, ticker: str = None) -> None:
    _hold_append(mint, "live_card.md", block, ticker)


def hold_folder_open(mint: str, position: dict, thesis: dict) -> None:
    """Create the folder and FREEZE the entry card at promotion.

    THE ENTRY CARD IS WRITTEN ONCE AND NEVER EDITED. This is not fussiness — it is the
    whole point. If the entry score can be quietly revised after the fact, then every
    future comparison is against a moving target, and the system can never tell you
    "you were wrong at entry." A memory system whose past can be edited is not a memory
    system, it's a story you tell yourself. History needs a clean BEFORE.
    """
    ticker = position.get("ticker", "?")
    d = _hold_folder(mint, ticker)
    scores = thesis.get("hold_score") or {}
    entry = d / "entry_card.md"

    if not entry.exists():
        card = [
            f"# ENTRY CARD — {ticker}",
            f"",
            f"**FROZEN AT PROMOTION. NEVER EDIT THIS FILE.**",
            f"History needs a clean *before*. If this can be revised, nothing after it means anything.",
            f"",
            f"- **CA:** `{mint}`",
            f"- **Promoted:** {_now_iso()}",
            f"- **Entry price:** ${_safe_num(position.get('entry_price')) or 0:.8f}",
            f"- **Mcap at promote:** ${_safe_num(thesis.get('mcap_at_promote')) or 0:,.0f}",
            f"- **Liq at promote:** ${_safe_num(thesis.get('liq_at_promote')) or 0:,.0f}",
            f"",
            f"## Hold-score vs $GORK",
            f"",
            f"| criterion | score |",
            f"|---|---|",
        ]
        std = load_gork_standard()
        for c in std["criteria"]:
            v = scores.get(c["id"], "—")
            lb = " **(load-bearing)**" if c["load_bearing"] else ""
            card.append(f"| {c['id']} · {c['name']}{lb} | **{v}**/10 |")
        card += [
            f"",
            f"- **Raw average:** {thesis.get('raw_avg')}/10",
            f"- **Band:** **{str(thesis.get('band','?')).upper()}**",
            f"- **Rope:** {thesis.get('rope')}",
            f"",
            f"## The thesis",
            f"",
            f"{thesis.get('thesis') or '(none)'}",
            f"",
            f"## The falsifier (what makes me sell)",
            f"",
            f"{thesis.get('falsifier') or '(NONE SET — that was a mistake)'}",
            f"",
            f"## Leash contract",
            f"",
            f"- **Band:** {thesis.get('band')}",
            f"- **Rope:** {thesis.get('rope')}",
            f"- **Forced rescore:** every {thesis.get('rescore_hours','—')}h, AND immediately on any storm",
            f"- **Demote triggers:** band drop on rescore · load-bearing (C1/C2/C4) fail · falsifier hit",
            f"",
            f"> This contract exists to stop *\"I like it so I gave it more rope.\"* The rope was",
            f"> decided when you were calm. Honor it when you are not.",
        ]
        entry.write_text("\n".join(card), encoding="utf-8")

        # seed the other files
        (d / "live_card.md").write_text(
            f"# LIVE CARD — {ticker}\n\nCurrent state. Mutable. Updated every rescan.\n\n"
            f"Entry band: **{str(thesis.get('band','?')).upper()}** ({thesis.get('raw_avg')}/10)\n\n---\n",
            encoding="utf-8")
        (d / "evidence.md").write_text(
            f"# EVIDENCE — {ticker}\n\n"
            f"**THE PROOF RULE: only what can be RE-CHECKED goes in here.**\n"
            f"Links, windows, CA checks, roster notes, screenshots. Never \"CT said it was organic.\"\n"
            f"If it isn't pointable, it didn't happen.\n\n"
            f"## Red-tape samples (chat/X during dumps)\n\n_(the most important section — green can fake lore, red audits it)_\n\n"
            f"## Named core (handles that kept showing up)\n\n"
            f"## Cabal attempts + how the community responded\n\n"
            f"## Origin snapshots (top10 / authorities)\n\n"
            f"- at entry: _(fill)_\n",
            encoding="utf-8")
        (d / "timeline.md").write_text(
            f"# TIMELINE — {ticker}\n\nAppend-only. Storms, silence, narrative capture, whale dumps, dev moves.\n\n"
            f"| date | event | score delta | action |\n|---|---|---|---|\n"
            f"| {_now_iso()[:16]} | promoted to hold ({thesis.get('band')}) | — | hold |\n",
            encoding="utf-8")
        _log(f"HOLD FOLDER opened: {d.name}", prefix="hold")
    else:
        _hold_append(mint, "timeline.md",
                     f"| {_now_iso()[:16]} | RE-promoted to hold | — | hold |", ticker)


def hold_timeline_add(mint: str, event: str, action: str,
                      score_delta: str = "—", ticker: str = None) -> None:
    """Append-only event log. Demotions teach as much as sells — write them down."""
    _hold_append(mint, "timeline.md",
                 f"| {_now_iso()[:16]} | {event} | {score_delta} | {action} |", ticker)


# back-compat alias — the promotion path calls this
def hold_doc_open(mint: str, position: dict, thesis: dict) -> None:
    hold_folder_open(mint, position, thesis)


async def write_moonbag_packet(mint: str, position: dict, exit_data: dict) -> None:
    """Sprint 53 — THE MOONBAG PACKET. Fires when a HOLD-lane bag is fully exited.

    This is the closed loop: hold-score at entry → the folder lives the whole hold →
    on sell, an autopsy that compares what you BELIEVED to what HAPPENED, and produces
    ONE LINE that goes into LEARNINGS.

    Green or red, both get written. A hold that worked and a hold that broke teach the
    same rubric — and the loss teaches it harder. The point is not the PnL; it's whether
    the AXES held. Did C1 (time under fire) predict? Did C2 (red-tape output) predict?
    Over enough bags, this is what tells you which criteria are load-bearing in reality
    rather than in theory — and that is how GORK stops being the only 10 out of faith
    and starts being the only 10 out of EVIDENCE.

    Only hold-lane bags. A flip already has the standard autopsy record. If it
    never earned a hold-score, it doesn't get a shrine.
    """
    thesis = get_hold_thesis(mint)
    if not thesis or str(position.get("mode") or "flip").lower() != "hold":
        return   # not a hold-lane bag (or demoted back to flip: reported as a normal flip close) — no moonbag, no shrine

    ticker = position.get("ticker", "?")
    entry_scores = thesis.get("hold_score") or {}
    entry_band   = thesis.get("band")
    entry_avg    = thesis.get("raw_avg")
    falsifier    = thesis.get("falsifier")

    pnl_pct  = _safe_num(exit_data.get("pnl_pct"))
    pnl_sol  = _safe_num(exit_data.get("realized_pnl_sol"))
    reason   = exit_data.get("exit_reason") or exit_data.get("trigger") or "manual"
    held_h   = None
    try:
        _p = thesis.get("promoted_at")
        if _p:
            held_h = round((_now_ts() - datetime.fromisoformat(_p).timestamp()) / 3600, 1)
    except Exception:
        pass

    # outcome class — pattern, not PnL brag. LEARNINGS wants the class, not the dollars.
    if reason in ("liq_drain", "rug", "honeypot") or (pnl_pct is not None and pnl_pct <= -80):
        outcome = "rug-class"
    elif pnl_pct is not None and pnl_pct >= 100:
        outcome = "full win"
    elif pnl_pct is not None and pnl_pct > 0:
        outcome = "partial"
    elif reason in ("thesis_break", "demoted", "falsifier_hit"):
        outcome = "thesis fail"
    elif reason in ("max_hold", "timeout", "boredom"):
        outcome = "boredom exit"
    else:
        outcome = "loss"

    packet = {
        "_type": "moonbag",
        "_doctrine": (
            "A HOLD-lane bag is closed. This is not a PnL report — it is a RUBRIC audit. "
            "Compare what you BELIEVED at entry (the frozen entry card) to what HAPPENED. "
            "Which axes held? Which broke? Did the falsifier fire, and did you honor it? "
            "Green or red, the lesson is the same shape: the hold-score either predicted "
            "or it didn't, and the only way GORK stays the 10/10 is if the bags you LIVED "
            "keep proving it. Skip the dollar flex — LEARNINGS wants the PATTERN."
        ),
        "mint": mint,
        "ticker": ticker,
        "closed_at": _now_iso(),
        "hold_duration_hours": held_h,
        "outcome_class": outcome,
        "pnl_pct": pnl_pct,
        "pnl_sol": pnl_sol,
        "exit_reason": reason,

        "entry": {
            "band": entry_band, "raw_avg": entry_avg, "scores": entry_scores,
            "thesis": thesis.get("thesis"),
            "falsifier": falsifier,
            "promoted_at": thesis.get("promoted_at"),
        },
        "band_journey": thesis.get("band_journey") or [entry_band],

        "the_audit": {
            "load_bearing_axes": {
                cid: {"entry_score": entry_scores.get(cid),
                      "question": f"Did {cid} hold, or did it break?"}
                for cid in ("c1", "c2", "c4")
            },
            "falsifier_check": (
                f"Your falsifier was: '{falsifier}'. Did it FIRE? And if it fired — "
                f"did you HONOR it, or did you find a reason to stay? A falsifier you "
                f"talk yourself out of is worse than no falsifier at all, because it "
                f"launders the decision."
            ),
            "worst_red_window": (
                "What did the community DO on the worst red window of this hold? That is "
                "the single highest-signal fact available about them, and it is the one "
                "you can only observe by having been there. Write it down — this is what "
                "you could never reconstruct for the tokens you didn't live through."
            ),
        },

        "questions_for_agent": [
            "Which axes HELD and which BROKE? Be specific — this is the rubric's report card.",
            "Did the falsifier fire? Did you honor it, or talk yourself out of it?",
            "What did the community do on the WORST red day? (the highest-signal fact there is)",
            "Was the entry score honest, or were you grading soft because you liked the chart?",
            "ONE LINE for LEARNINGS — the pattern, not the trade. No PnL brag.",
            "near_gork_axes: which criteria did this bag actually rival GORK on? (or 'none')",
        ],
        "learnings_template": (
            "# one fact per line. pattern only. examples of the right energy:\n"
            "#   'hold bags that went dark on first -40% demote same day, no second chance'\n"
            "#   'c4 fail after entry (insider cluster wake-up) = exit thesis, not hope'\n"
            "# NOT a trade-by-trade diary. NOT a PnL brag."
        ),
        "folder": str(_hold_folder(mint, ticker)),
    }

    # write the moonbag INTO the folder (the shrine's final page)
    try:
        std = load_gork_standard()
        mb = [
            f"# MOONBAG — {ticker}",
            f"",
            f"**Closed {_now_iso()}** · held {held_h}h · **{outcome.upper()}** · "
            f"{pnl_pct:+.1f}% ({pnl_sol:+.4f} SOL)" if pnl_pct is not None else f"**Closed {_now_iso()}**",
            f"",
            f"## Entry vs exit",
            f"",
            f"- **Entry band:** {str(entry_band).upper()} ({entry_avg}/10)",
            f"- **Band journey:** {' → '.join(str(x) for x in (thesis.get('band_journey') or [entry_band]))}",
            f"- **Exit reason:** {reason}",
            f"",
            f"## The load-bearing axes — held or broke?",
            f"",
        ]
        for cid in ("c1", "c2", "c4"):
            c = next((x for x in std["criteria"] if x["id"] == cid), {})
            mb.append(f"- **{cid} · {c.get('name')}** — entry {entry_scores.get(cid, '—')}/10 · "
                      f"_held or broke? →_")
        mb += [
            f"",
            f"## The falsifier",
            f"",
            f"> {falsifier or '(none set)'}",
            f"",
            f"Did it fire? Did you honor it? _→_",
            f"",
            f"## What the community did on the worst red window",
            f"",
            f"_(the highest-signal fact available — you can only know this by having been there)_",
            f"",
            f"## The lesson (one line, LEARNINGS-ready)",
            f"",
            f"_→_",
            f"",
            f"## near_gork_axes",
            f"",
            f"_(which criteria did this bag actually rival GORK on? or 'none')_",
        ]
        (_hold_folder(mint, ticker) / "moonbag.md").write_text("\n".join(mb), encoding="utf-8")
        hold_timeline_add(mint, f"EXITED — {outcome} ({reason})", "closed",
                          ticker=ticker)
    except Exception as e:
        _log(f"moonbag folder write err: {e}", prefix="hold")

    # ANTI-SHRINE RULE: the hold is over. Freeze the folder so it stops being groomed.
    try:
        d = _hold_folder(mint, ticker)
        (d / "_CLOSED").write_text(
            f"Closed {_now_iso()} — {outcome}.\n"
            f"This hold is over. The folder is FROZEN. Do not keep grooming a dead bag.\n"
            f"Active holds only in the live tree.\n", encoding="utf-8")
    except Exception:
        pass

    try:
        _INBOX.mkdir(parents=True, exist_ok=True)
        fname = (f"meme_sniper - moonbag_{ticker}_{mint[:8]}_"
                 f"{datetime.now().strftime('%Y%m%d_%H%M%S')}.json")
        with open(_INBOX / fname, "w", encoding="utf-8") as f:
            json.dump(packet, f, indent=2)
        _log(f"MOONBAG: {ticker} closed — {outcome} "
             f"({pnl_pct:+.1f}% over {held_h}h)" if pnl_pct is not None
             else f"MOONBAG: {ticker} closed — {outcome}", prefix="hold")
        await send_telegram(
            f"📕 <b>MOONBAG: {ticker}</b>\n"
            f"{outcome.upper()} · {pnl_pct:+.1f}% · held {held_h}h\n"
            f"Entry: {str(entry_band).upper()} ({entry_avg}/10)\n\n"
            f"The rubric gets its report card. Write the lesson."
            if pnl_pct is not None else f"📕 <b>MOONBAG: {ticker}</b> — {outcome}")
    except Exception as e:
        _log(f"moonbag packet write err: {e}", prefix="hold")

    # close out the score log so we can later ask: DOES THE RUBRIC PREDICT?
    try:
        _append_jsonl(HOLD_SCORE_LOG_FILE, {
            "mint": mint, "ticker": ticker, "closed_at": _now_iso(),
            "entry_band": entry_band, "entry_avg": entry_avg, "entry_scores": entry_scores,
            "outcome_class": outcome, "pnl_pct": pnl_pct, "pnl_sol": pnl_sol,
            "hold_hours": held_h, "exit_reason": reason,
        })
    except Exception:
        pass


def _hold_health(detail: dict, thesis: dict) -> dict:
    """Score the HARD NUMBERS vs where they were at promote. This is what ACTS.
    Social informs; numbers decide."""
    degr = []
    mcap0 = _safe_num(thesis.get("mcap_at_promote"))
    liq0  = _safe_num(thesis.get("liq_at_promote"))
    hold0 = _safe_num(thesis.get("holders_at_promote"))
    mcap  = _safe_num(detail.get("mcap"))
    liq   = _safe_num(detail.get("liq"))
    hold_n = _safe_num(detail.get("holder_count"))
    dev   = _safe_num(detail.get("dev_holding_pct"))
    top10 = _safe_num(detail.get("top10_pct"))

    if liq0 and liq is not None and liq < liq0 * 0.5:
        degr.append({"signal": "liquidity_halved", "severity": "high",
                     "detail": f"liq ${liq:,.0f} vs ${liq0:,.0f} at promote (-{(1-liq/liq0)*100:.0f}%)"})
    if mcap0 and mcap is not None and mcap < mcap0 * 0.5:
        degr.append({"signal": "mcap_halved", "severity": "medium",
                     "detail": f"mcap ${mcap:,.0f} vs ${mcap0:,.0f} at promote"})
    if hold0 and hold_n is not None and hold_n < hold0 * 0.7:
        degr.append({"signal": "holder_exodus", "severity": "high",
                     "detail": f"holders {hold_n:,.0f} vs {hold0:,.0f} at promote"})
    if dev is not None and dev >= 15:
        degr.append({"signal": "dev_concentration", "severity": "high",
                     "detail": f"dev holds {dev:.1f}%"})
    if top10 is not None and top10 >= 85:
        degr.append({"signal": "whale_concentration", "severity": "medium",
                     "detail": f"top10 hold {top10:.1f}%"})
    return {"degradations": degr, "degraded": bool(degr),
            "high_severity": any(d["severity"] == "high" for d in degr)}


async def hold_doc_update(mint: str, position: dict, ctx: dict) -> dict:
    """Append the FULL token picture + social presence to the living doc; compute health.

    `ctx` is the FULL candidate context from hold_full_rescan() — all 33 blocks, live.
    A held token gets MORE data than a scan candidate, not less: he isn't flipping it,
    he's owning it, and the entire job is watching the thesis hold or break.

    DOCTRINE (locked with the owner):
      - EVERY number goes in, every update, so he can micro-watch them move.
      - SOCIAL INFORMS, NUMBERS ACT. X chatter is the most manipulable input there is
        (bots, shills, raids). Recorded for his read; a sell must be justifiable on the
        token detail. Social can support a hold or add urgency to an exit — never be the
        sole reason for either.
      - HARD RUG EXITS FIRE REGARDLESS OF MODE (liq drain, dev dump, honeypot).
    """
    thesis = get_hold_thesis(mint)

    # flatten what we need out of the full context
    dex      = ctx.get("dex_data") or {}
    holders  = ctx.get("holders") or {}
    lp       = ctx.get("lp_lock") or {}
    rug      = ctx.get("rug_check") or {}
    deployer = ctx.get("deployer_history") or {}
    narr     = ctx.get("narrative_intelligence") or ctx.get("narrative") or {}
    trade    = ctx.get("trade_pressure") or {}
    pattern  = ctx.get("pattern") or {}
    brand    = ctx.get("brand_resolution") or {}
    edge     = ctx.get("edge_filter") or {}
    meta     = ctx.get("current_meta") or {}
    trend    = ctx.get("trending_track") or {}
    pvp      = ctx.get("pvp_flag")

    price = _safe_num(dex.get("priceUsd")) or _safe_num(ctx.get("price"))
    mcap  = _safe_num(ctx.get("mcap")) or _safe_num(dex.get("marketCap") or dex.get("fdv"))
    liq   = _safe_num(ctx.get("liquidity_usd")) or _safe_num((dex.get("liquidity") or {}).get("usd"))
    entry = _safe_num(position.get("entry_price"))
    pnl   = round((price - entry) / entry * 100, 1) if (price and entry) else None

    detail_for_health = {
        "price": price, "pnl_pct": pnl, "mcap": mcap, "liq": liq,
        "holder_count": holders.get("holder_count") or ctx.get("holder_count"),
        "top10_pct": holders.get("top10_pct") or ctx.get("top10_pct"),
        "dev_holding_pct": holders.get("dev_holding_pct"),
    }
    health = _hold_health(detail_for_health, thesis)

    # ── THE TWO SOCIAL LAYERS (they are NOT interchangeable) ────────────────────
    # X is the OUTSIDE world talking ABOUT the token. coincomms (pump.fun chat) is the
    # token's OWN community talking IN it. For a HOLD, that distinction is everything:
    # the thesis is the COMMUNITY, and coincomms IS the community. X can be raided by
    # anyone with a bot farm; the pump.fun chat is where the actual holders live.
    #
    # I nearly threw this away: the hold doc was rendering only fetch_x_chatter while
    # coincomms sat unused inside the ctx that hold_full_rescan already fetched. That
    # would have been a real loss — grading a community thesis on the loudest possible
    # surface while ignoring the native one.
    social = {}
    try:
        social = await fetch_x_chatter(position.get("ticker", "?"), mint, per_query=5) or {}
    except Exception as e:
        social = {"error": str(e)[:120]}

    # coincomms comes free with the rescan — the ctx already has it
    _cc_social = ctx.get("social_sentiment") or ctx.get("social") or {}
    _cc_ca     = _cc_social.get("coincomms_ca") or {}
    _cc_ticker = _cc_social.get("coincomms_ticker") or {}
    _cc_msgs   = _cc_ca.get("message_count") or 0
    _cc_spam   = _cc_ca.get("spam_ratio")
    _cc_pvp    = _cc_social.get("pvp_flag")

    # ── STORE THE NUMBERS AS DATA (not prose) ───────────────────────────────────
    # One flat row per update. ~200 bytes. A month of holding is ~300KB — nothing — but
    # now the history is QUERYABLE. The live card is for reading; the series is for
    # THINKING. A hold dies from trajectory, not from any single reading.
    _series_row = {
        "ts": _now_ts(), "at": _now_iso(),
        "price": price, "pnl_pct": pnl, "mcap": mcap, "liq": liq,
        "vol_24h": _safe_num(ctx.get("volume_24h")),
        "vol_1h": _safe_num(ctx.get("volume_1h")),
        "holders": detail_for_health.get("holder_count"),
        "top10_pct": detail_for_health.get("top10_pct"),
        "dev_pct": detail_for_health.get("dev_holding_pct"),
        "chg_1h": _safe_num(ctx.get("price_change_1h")),
        "chg_24h": _safe_num(ctx.get("price_change_24h")),
        "organic_ca": (social.get("ca_chatter") or {}).get("organic_count"),
        "bot_ca": (social.get("ca_chatter") or {}).get("bot_count"),
        "organic_ticker": (social.get("ticker_chatter") or {}).get("organic_count"),
        "bot_ticker": (social.get("ticker_chatter") or {}).get("bot_count"),
        # coincomms = the token's NATIVE community (pump.fun chat). This is the number
        # that actually grades a hold thesis: X is the outside talking ABOUT it,
        # coincomms is the holders talking IN it. A community that goes quiet in its own
        # chat has left, whatever the cashtag says.
        "cc_msgs": _cc_msgs,
        "cc_spam_ratio": _cc_spam,
        "cc_distinct_cas": _cc_ca.get("distinct_cas"),
    }
    _hold_series_append(mint, _series_row, position.get("ticker"))
    # archive EVERY post (organic AND bot — a raid pattern IS the signal)
    _hold_posts_append(mint, social, position.get("ticker"))
    # the trajectory read — the thing no single snapshot can give
    _trends = hold_series_trends(mint, position.get("ticker"))

    # ── GROK READS IT FIRST ─────────────────────────────────────────────────────
    # Same as the scan path: Grok pre-digests so the agent gets a READ, not a data dump.
    # But the question is harder here — not "is this worth buying" but "does the thesis
    # still stand", which needs trajectory + community-under-pressure + the falsifier.
    _digest = {}
    try:
        _digest = await hold_grok_digest(mint, position.get("ticker", "?"), ctx,
                                         _trends, social, thesis)
    except Exception as _de:
        _digest = {"error": str(_de)[:120]}

    def _f(v, fmt="{:,.0f}", dash="—"):
        n = _safe_num(v)
        return fmt.format(n) if n is not None else dash

    b = [f"### {_now_iso()}\n"]
    if _digest.get("digest"):
        b.append("**🧠 GROK READ** (numbers + trajectory + community, pre-digested)\n")
        b.append("> " + str(_digest["digest"]).replace("\n", "\n> "))
        b.append("")
    else:
        # A MISSING READ IS NOT AN "ALL CLEAR". Say so loudly. The worst failure mode in
        # this whole system is a check that silently doesn't run and looks like a pass.
        b.append("**⚠ NO GROK READ THIS CYCLE** "
                 f"({_digest.get('error') or 'xAI at capacity / call failed'})\n")
        b.append("> The synthesis did NOT run. **This is not an all-clear.** The numbers "
                 "below are raw — nobody has read them against your thesis this cycle. "
                 "Read them yourself, or wait for the next update.\n")
    if _trends.get("degrading"):
        b.append("**📉 TRAJECTORY WARNINGS** (what a single snapshot cannot show)\n")
        for w in _trends.get("warnings", []):
            b.append(f"- **{w['signal']}**: {w['detail']}")
            b.append(f"  - *{w['read']}*")
        b.append("")
    if ctx.get("_rescan_degraded"):
        b.append(f"> ⚠ {ctx.get('_rescan_note')}\n")

    b.append("**THE NUMBERS**\n")
    b.append("| metric | value |\n|---|---|")
    b.append(f"| price | ${price:.8f} |" if price else "| price | — |")
    b.append(f"| pnl | {_f(pnl, '{:+.1f}')}% |")
    b.append(f"| mcap | ${_f(mcap)} |")
    b.append(f"| liquidity | ${_f(liq)} |")
    b.append(f"| vol 5m / 1h / 24h | ${_f(ctx.get('volume_5m'))} / ${_f(ctx.get('volume_1h'))} / ${_f(ctx.get('volume_24h'))} |")
    b.append(f"| price chg 5m / 1h / 24h | {_f(ctx.get('price_change_5m'),'{:+.1f}')}% / {_f(ctx.get('price_change_1h'),'{:+.1f}')}% / {_f(ctx.get('price_change_24h'),'{:+.1f}')}% |")
    b.append(f"| holders | {_f(detail_for_health['holder_count'])} |")
    b.append(f"| top10 % | {_f(detail_for_health['top10_pct'],'{:.1f}')}% |")
    b.append(f"| dev % | {_f(detail_for_health['dev_holding_pct'],'{:.1f}')}% |")
    b.append(f"| age | {_f(ctx.get('age_minutes'),'{:.0f}')} min |")
    b.append(f"| boosts | {_f(ctx.get('boost_count'))} |")
    b.append("")

    b.append("**SAFETY / STRUCTURE**\n")
    b.append(f"- rug_check: **{rug.get('verdict') or rug.get('risk_level') or '—'}** {rug.get('note') or ''}")
    b.append(f"- LP: locked {_f(lp.get('lp_locked_pct'),'{:.0f}')}% · burned {lp.get('lp_burned')} · program `{lp.get('token_program') or '—'}`")
    b.append(f"- deployer: {deployer.get('rep') or '—'} ({deployer.get('prior_launches') or 0} prior launches)")
    b.append(f"- trade pressure: {trade.get('read') or trade.get('buy_ratio') or '—'}")
    b.append(f"- pattern: {pattern.get('name') or pattern if isinstance(pattern,str) else pattern.get('name') or '—'}")
    if pvp:
        b.append(f"- ⚠ PVP flag: {ctx.get('pvp_note') or 'another CA is hotter'}")
    b.append("")

    b.append("**IDENTITY / BRAND**\n")
    if brand.get("is_canonical") is False:
        b.append(f"- ⚠ **CLONE** — {brand.get('note')}")
    elif brand.get("is_canonical"):
        b.append(f"- ✅ canonical (the OG) · {brand.get('clone_count', 0)} clone(s) alive")
    b.append(f"- narrative: {narr.get('narrative') or '—'} · meta aligned: {ctx.get('meta_alignment')}")
    b.append(f"- band: **{edge.get('band') or '—'}**")
    if trend.get("consecutive_top_10_hours"):
        b.append(f"- trending: {trend.get('consecutive_top_10_hours')}h consecutive top-10")
    b.append(f"- X: @{ctx.get('twitter_handle') or '—'} · {_f(ctx.get('twitter_followers'))} followers · account {_f(ctx.get('x_account_age_days'),'{:.0f}')}d old · dex_paid: {ctx.get('x_dex_paid')}")
    b.append(f"- telegram: {_f(ctx.get('telegram_members'))} members")
    b.append("")

    _tc = (social.get("ticker_chatter") or {})
    _cc = (social.get("ca_chatter") or {})

    b.append("**🏠 THE NATIVE COMMUNITY** (coincomms / pump.fun chat — *this is the one that grades the thesis*)\n")
    b.append(f"- messages on the CA: **{_cc_msgs}**"
             + (f" · spam ratio {_cc_spam:.0%}" if isinstance(_cc_spam, (int, float)) else ""))
    if _cc_ticker.get("message_count"):
        b.append(f"- messages on the ticker: {_cc_ticker.get('message_count')}"
                 + (f" · {_cc_ticker.get('distinct_cas')} distinct CAs seen" if _cc_ticker.get("distinct_cas") else ""))
    if _cc_pvp:
        b.append("- ⚠ **PVP FLAG** — another CA is hotter under this ticker. The attention "
                 "you think you own may be going to a clone.")
    if _cc_social.get("summary"):
        b.append(f"- read: {_cc_social.get('summary')}")
    b.append("")
    b.append("> **X is the outside world talking ABOUT the token. coincomms is the holders talking "
             "IN it.** For a hold, that distinction is everything — the thesis IS the community, and "
             "this is where the community actually lives. A cashtag can be raided by anyone with a "
             "bot farm. **A community that goes quiet in its OWN chat has left**, whatever the "
             "cashtag says. If `cc_msgs` is trending to zero while X is loud, you are holding a "
             "ghost town with a marketing budget.\n")

    b.append("**SOCIAL PRESENCE — X** (informs, does NOT decide)\n")
    b.append(f"- `$TICKER`: {_tc.get('organic_count',0)} organic / {_tc.get('bot_count',0)} bot — {_tc.get('read','no data')}")
    b.append(f"- `CA`: {_cc.get('organic_count',0)} organic / {_cc.get('bot_count',0)} bot — {_cc.get('read','no data')}")
    b.append(f"- cross-read: {social.get('cross_read','—')}")
    _ca_org = (_cc.get("organic") or [])[:3]
    if _ca_org:
        b.append("\n*What real holders are saying (organic CA posts — bots don't post contract addresses):*")
        for p_ in _ca_org:
            _t = (p_.get("text") or "").replace("\n", " ")[:180]
            b.append(f"- @{p_.get('handle','?')}: {_t}")
    b.append("")

    # ── RESCORE DISCIPLINE (the GORK standard's own rule) ───────────────────────
    # "Rescore on storms / cabal waves / core silence / insider moves — NOT vibes."
    # Two triggers, both mandatory:
    #   1. TIME — each band carries its own cadence (hawkish 60h, conditional 168h,
    #      patient 336h, gork-class 720h). A shakier thesis gets audited more often.
    #   2. A STORM — any degradation IS a storm, and a storm is precisely when the
    #      rubric earns its keep: green can fake lore, RED AUDITS IT. C2/C9/C10 are all
    #      scored during a drawdown for exactly this reason. So when the numbers move
    #      against him, we don't just note it — we DEMAND the rescore, because right now
    #      is the only moment the community's real character is visible.
    _rescore_due = False
    _rescore_why = None
    _next_rs = thesis.get("next_rescore_ts")
    if _next_rs and _now_ts() >= _next_rs:
        _rescore_due, _rescore_why = True, f"scheduled ({thesis.get('band')} band cadence)"
    if health["high_severity"]:
        _rescore_due, _rescore_why = True, "A STORM IS HERE (high-severity degradation)"

    if health["degraded"]:
        b.append("**⚠ DEGRADATION vs your promote baseline**\n")
        for d in health["degradations"]:
            b.append(f"- **{d['severity'].upper()}** {d['signal']}: {d['detail']}")
        b.append("\n> The numbers moved against the thesis. **Re-underwrite.** Does the original "
                 "reason to hold still stand? If yes, write WHY here. If no, demote to flip and "
                 "exit on flip rules. Don't let a hold drift into a bag.")
        b.append(f"\n> Your falsifier was: *{thesis.get('falsifier') or '(none set — that was a mistake)'}*")
    else:
        b.append("**Health:** numbers still consistent with the thesis.")

    if _rescore_due:
        b.append(f"\n---\n\n## 🔁 RESCORE REQUIRED — {_rescore_why}\n")
        b.append(f"Scored **{thesis.get('raw_avg')}/10 ({thesis.get('band')})** at promote. "
                 f"Re-run the GORK standard NOW and fire a `rescore_hold` signal with the new card.\n")
        b.append("**This is the moment the rubric was built for.** Green can fake lore — "
                 "**red audits it.** Go look at C2 (does the community still post when the price "
                 "is dead?), C9 (what do they say the bag is FOR, now that it hurts?), and C10 "
                 "(do their actions still match their claimed values?). Those three are only "
                 "honestly checkable during a storm, and there's one happening right now.\n")
        b.append("If the new score drops a band, that is a DEMOTION signal. If it fails a "
                 "load-bearing criterion (C1/C2/C4), the thing you bought is not the thing "
                 "you thought it was \u2014 the original read no longer describes it.\n")

    _hold_doc_append(mint, "\n".join(b))
    return {"health": health, "social": social, "ctx": ctx}


