# ─────────────────────────────────────────────────────────────────────────────
# STRUCTURAL DETECTORS (Sprint 33+)
# These do deep-resolution analysis (Fib levels, linear regression, wick math)
# to refine simple heuristic classifications. They overlay on top of
# classify_chart_heuristic — that function picks the broad shape, these add
# precision tags when applicable.
# ─────────────────────────────────────────────────────────────────────────────

def _pe_pct_change(a: float, b: float) -> float:
    """Pattern engine pct change helper (a→b)."""
    if a == 0:
        return 0
    return ((b - a) / a) * 100


def _pe_perfect_dip(closes: list, highs: list, lows: list) -> dict:
    """Detect mathematically-clean retrace to Fibonacci levels with smooth linear
    descent and tight wicks. Signature of an algorithmic / AI-driven dip-buy
    setup (vs random retail volatility).
    Returns: {"detected": bool, "fib_level": float, "linearity": float,
              "tight_wicks": bool, "confidence": float}
    """
    result = {"detected": False, "fib_level": 0.0, "linearity": 0.0,
              "tight_wicks": False, "confidence": 0.0}
    if len(closes) < 5 or len(highs) < 5 or len(lows) < 5:
        return result
    
    swing_high = max(highs)
    swing_low  = min(lows)
    if swing_high == 0 or swing_low >= swing_high:
        return result
    
    total_range = swing_high - swing_low
    current = closes[-1]
    retrace_pct = (swing_high - current) / total_range if total_range > 0 else 0
    
    FIB_LEVELS = [0.236, 0.382, 0.500, 0.618]
    TOLERANCE  = 0.005
    
    fib_hit = 0.0
    for fib in FIB_LEVELS:
        if abs(retrace_pct - fib) <= TOLERANCE:
            fib_hit = fib
            break
    
    if not fib_hit:
        return result
    
    # linearity check
    recent_closes = closes[-min(8, len(closes)):]
    n = len(recent_closes)
    if n < 3:
        return result
    
    xs = list(range(n))
    x_mean = sum(xs) / n
    y_mean = sum(recent_closes) / n
    numerator   = sum((xs[i] - x_mean) * (recent_closes[i] - y_mean) for i in range(n))
    denominator = sum((xs[i] - x_mean) ** 2 for i in range(n))
    if denominator == 0:
        return result
    
    slope     = numerator / denominator
    intercept = y_mean - slope * x_mean
    residuals = [abs(recent_closes[i] - (slope * xs[i] + intercept)) for i in range(n)]
    avg_price = max(y_mean, 0.0000001)
    rel_residuals = [r / avg_price for r in residuals]
    linearity_score = max(0.0, 1.0 - (sum(rel_residuals) / n) * 20)
    
    # wick deviation
    recent_highs = highs[-min(5, len(highs)):]
    recent_lows  = lows[-min(5, len(lows)):]
    sample_n = min(5, len(recent_highs), len(recent_lows), len(recent_closes))
    if sample_n == 0:
        return result
    avg_wick_dev = sum(
        abs(recent_highs[i] - recent_closes[-(sample_n - i)]) +
        abs(recent_closes[-(sample_n - i)] - recent_lows[i])
        for i in range(sample_n)
    ) / (sample_n * max(avg_price, 0.0000001))
    tight_wicks = avg_wick_dev < 0.03
    
    confidence = 0.0
    confidence += 0.4 if fib_hit in (0.382, 0.618) else 0.25  # golden ratios
    confidence += linearity_score * 0.35
    confidence += 0.25 if tight_wicks else 0.0
    
    detected = confidence >= 0.55 and linearity_score > 0.4
    
    return {
        "detected":    detected,
        "fib_level":   fib_hit,
        "linearity":   round(linearity_score, 3),
        "tight_wicks": tight_wicks,
        "confidence":  round(confidence, 3),
    }


def _pe_floor_holder(lows: list, volumes: list, tolerance: float = 0.003) -> dict:
    """Detect mechanical floor defense — 3+ bounces off same level with LOW
    consistent volume. Algorithmic, not retail.
    """
    result = {"detected": False, "floor_price": 0.0, "bounces": 0,
              "vol_consistency": 0.0, "vol_ratio": 0.0, "confidence": 0.0}
    if len(lows) < 5 or len(volumes) < 5:
        return result
    
    floor_price = min(lows)
    if floor_price == 0:
        return result
    
    bounce_indices = [
        i for i, l in enumerate(lows)
        if abs(_pe_pct_change(floor_price, l)) <= tolerance * 100
    ]
    if len(bounce_indices) < 3:
        return result
    
    defense_vols = [volumes[i] for i in bounce_indices if i < len(volumes)]
    if not defense_vols:
        return result
    
    avg_defense_vol = sum(defense_vols) / len(defense_vols)
    avg_total_vol   = sum(volumes) / len(volumes) if volumes else 1
    vol_ratio = avg_defense_vol / max(avg_total_vol, 1)
    
    if len(defense_vols) > 1:
        mean_dv = avg_defense_vol
        std_dv  = (sum((v - mean_dv) ** 2 for v in defense_vols) / len(defense_vols)) ** 0.5
        vol_consistency = max(0.0, 1.0 - (std_dv / max(mean_dv, 1)))
    else:
        vol_consistency = 0.5
    
    detected = (
        len(bounce_indices) >= 3
        and vol_ratio < 0.70
        and vol_consistency > 0.4
    )
    
    return {
        "detected":        detected,
        "floor_price":     round(floor_price, 12),
        "bounces":         len(bounce_indices),
        "vol_ratio":       round(vol_ratio, 3),
        "vol_consistency": round(vol_consistency, 3),
        "confidence":      round(min(1.0, len(bounce_indices) / 3 * vol_consistency * (1 - vol_ratio)), 3),
    }


def _pe_smooth_criminal_exit(closes: list, highs: list, lows: list, volumes: list) -> dict:
    """Detect algorithmic dump with NO panic wicks. Signature: volume spike +
    linear price drop + zero follow-through wicks. Highest danger flag when
    paired with dev/sniper wallet behavior.
    """
    result = {"detected": False, "vol_spike": 0.0, "linearity": 0.0,
              "clean_drop": False, "drop_pct": 0.0, "confidence": 0.0}
    if len(closes) < 5 or len(volumes) < 5:
        return result
    
    recent_vols  = volumes[-3:]
    baseline_vol = sum(volumes[:-3]) / max(len(volumes[:-3]), 1)
    peak_vol     = max(recent_vols)
    vol_spike    = peak_vol / max(baseline_vol, 1)
    if vol_spike < 2.0:
        return result
    
    price_start = closes[-min(6, len(closes))]
    price_end   = closes[-1]
    if price_end >= price_start:
        return result
    
    drop_pct = _pe_pct_change(price_start, price_end)
    if drop_pct > -5:
        return result
    
    recent_closes = closes[-min(6, len(closes)):]
    n = len(recent_closes)
    xs = list(range(n))
    x_mean = sum(xs) / n
    y_mean = sum(recent_closes) / n
    num = sum((xs[i] - x_mean) * (recent_closes[i] - y_mean) for i in range(n))
    den = sum((xs[i] - x_mean) ** 2 for i in range(n))
    if den == 0:
        return result
    
    slope     = num / den
    intercept = y_mean - slope * x_mean
    residuals = [abs(recent_closes[i] - (slope * xs[i] + intercept)) for i in range(n)]
    linearity = max(0.0, 1.0 - (sum(residuals) / n / max(y_mean, 0.0000001)) * 15)
    
    recent_highs = highs[-min(5, len(highs)):]
    recent_lows_ = lows[-min(5, len(lows)):]
    recent_cls   = closes[-min(5, len(closes)):]
    wicks = []
    sample_n = min(len(recent_highs), len(recent_lows_), len(recent_cls))
    for i in range(sample_n):
        body  = abs(recent_cls[i] - (recent_cls[i-1] if i > 0 else recent_cls[i]))
        upper = abs(recent_highs[i] - max(recent_cls[i], recent_cls[i-1] if i > 0 else recent_cls[i]))
        lower = abs(min(recent_cls[i], recent_cls[i-1] if i > 0 else recent_cls[i]) - recent_lows_[i])
        if body > 0:
            wicks.append((upper + lower) / body)
    avg_wick_ratio = sum(wicks) / len(wicks) if wicks else 1.0
    clean_drop = avg_wick_ratio < 0.3
    
    detected = (
        vol_spike >= 2.5
        and linearity >= 0.55
        and clean_drop
        and drop_pct <= -8
    )
    
    return {
        "detected":   detected,
        "vol_spike":  round(vol_spike, 2),
        "linearity":  round(linearity, 3),
        "clean_drop": clean_drop,
        "drop_pct":   round(drop_pct, 2),
        "confidence": round(min(1.0, (vol_spike / 5) * linearity * (1.5 if clean_drop else 0.5)), 3),
    }


def _pe_is_staircase(closes: list, min_steps: int = 3) -> bool:
    """Detect programmatic step-up accumulation."""
    if len(closes) < min_steps * 2:
        return False
    steps_up   = 0
    pullbacks  = 0
    prev       = closes[0]
    direction  = None
    for c in closes[1:]:
        change = _pe_pct_change(prev, c)
        if change > 3:
            if direction == "up":
                steps_up += 1
            direction = "up"
        elif change < -1.5:
            if direction == "up":
                pullbacks += 1
            direction = "down"
        prev = c
    return steps_up >= min_steps and pullbacks >= (min_steps - 1)


def _pe_is_vertical(closes: list, highs: list) -> bool:
    """Detect vertical rug — straight spike, no pullbacks, sharp drop after peak."""
    if len(closes) < 3:
        return False
    peak_idx = highs.index(max(highs))
    if peak_idx == 0:
        return False
    pre_peak  = closes[:peak_idx + 1]
    pullbacks = sum(1 for i in range(1, len(pre_peak)) if _pe_pct_change(pre_peak[i-1], pre_peak[i]) < -3)
    if peak_idx < len(closes) - 1:
        post_peak_drop = _pe_pct_change(closes[peak_idx], closes[-1])
        return pullbacks <= 1 and post_peak_drop < -40
    return False


def _pe_is_chop(closes: list, window: int = 6) -> bool:
    """Detect distribution chop — alternating equal green/red candles. AI selling
    into every buy.
    """
    if len(closes) < window:
        return False
    recent = closes[-window:]
    changes = [_pe_pct_change(recent[i-1], recent[i]) for i in range(1, len(recent))]
    alternating = sum(
        1 for i in range(1, len(changes))
        if (changes[i] > 0) != (changes[i-1] > 0)
    )
    abs_changes = [abs(c) for c in changes if c != 0]
    if not abs_changes:
        return False
    mean_change = sum(abs_changes) / len(abs_changes)
    similar = sum(1 for c in abs_changes if abs(c - mean_change) < mean_change * 0.5)
    return alternating >= window - 2 and similar >= len(abs_changes) - 1


def _pe_structural_overlay(name: str, confidence: float, ohlcv: list) -> tuple[str, float, dict]:
    """Sprint 33+ — run structural detectors and refine the heuristic name.
    
    Takes the simple-heuristic result (name, confidence) and OHLCV, then runs
    deep structural detectors. If a detector matches strongly, returns a
    refined name like 'perfect_dip_fib_618' or 'smooth_criminal_dump' with
    bumped confidence. Otherwise returns (name, confidence) unchanged.
    
    The third return is a dict of detector outputs for the packet so the agent
    can see WHY the refinement happened.
    """
    detectors_fired = {}
    if not ohlcv or len(ohlcv) < 5:
        return name, confidence, detectors_fired
    
    closes  = [c.get("close", 0) for c in ohlcv]
    highs   = [c.get("high", 0)  for c in ohlcv]
    lows    = [c.get("low", 0)   for c in ohlcv]
    volumes = [c.get("volume", 0) for c in ohlcv]
    
    # 1. Perfect dip with Fib refinement
    if name in ("perfect_dip", "unknown", "pure_organic"):
        pd = _pe_perfect_dip(closes, highs, lows)
        detectors_fired["perfect_dip"] = pd
        if pd["detected"]:
            fib = pd["fib_level"]
            refined_name = f"perfect_dip_fib_{int(fib * 1000)}"  # e.g., perfect_dip_fib_618
            refined_conf = max(confidence, pd["confidence"])
            return refined_name, refined_conf, detectors_fired
    
    # 2. Floor holder — algorithmic defense
    if name in ("pure_organic", "meme_trend", "unknown"):
        fh = _pe_floor_holder(lows, volumes)
        detectors_fired["floor_holder"] = fh
        if fh["detected"]:
            return "floor_holder", max(confidence, fh["confidence"]), detectors_fired
    
    # 3. Smooth criminal exit — silent rug
    if name in ("vertical_rug", "unknown", "pure_organic", "meme_trend"):
        sc = _pe_smooth_criminal_exit(closes, highs, lows, volumes)
        detectors_fired["smooth_criminal_exit"] = sc
        if sc["detected"]:
            return "smooth_criminal_exit", max(confidence, sc["confidence"]), detectors_fired
    
    # 4. Boolean detectors — refine staircase / vertical / chop classifications
    if name == "staircase_pump":
        detectors_fired["is_staircase_confirmed"] = _pe_is_staircase(closes)
    if name == "vertical_rug":
        detectors_fired["is_vertical_confirmed"] = _pe_is_vertical(closes, highs)
    if name in ("pure_organic", "meme_trend"):
        if _pe_is_chop(closes):
            detectors_fired["is_chop_confirmed"] = True
            return "distribution_chop", max(confidence, 0.55), detectors_fired
    
    return name, confidence, detectors_fired


def classify_chart_heuristic(ohlcv: list, token_meta: dict) -> tuple[str, float]:
    """
    Heuristic pattern classifier from raw OHLCV. Returns (pattern_name, confidence).
    Returns ('unknown', 0.0) when no clear match , caller should call Ollama.
    
    Works on both:
      - 30-bar 1m streams (Birdeye / Helius)
      - 5-bar DexScreener-synthesized series (24h/6h/1h/5m/now coarse)
    
    Uses session-level features that are meaningful at both granularities.
    """
    if not ohlcv:
        return "unknown", 0.0
    
    # Coarse mode = 5-bar DexScreener synthesis. Fine mode = 30-bar 1m stream.
    is_coarse_synth = len(ohlcv) <= 6
    
    if len(ohlcv) < 2:
        return "unknown", 0.0
    
    closes = [c.get("close", 0) for c in ohlcv]
    highs = [c.get("high", 0) for c in ohlcv]
    lows = [c.get("low", 0) for c in ohlcv]
    volumes = [c.get("volume", 0) for c in ohlcv]
    
    if not closes[0] or closes[0] <= 0:
        return "unknown", 0.0
    
    # Session-level features
    pct_change_session = ((closes[-1] - closes[0]) / closes[0]) * 100
    max_drawdown_pct = ((min(lows) - closes[0]) / closes[0]) * 100
    
    # Bar-by-bar trend (works on coarse + fine)
    green_candles = sum(1 for c in ohlcv if c.get("close", 0) > c.get("open", 0))
    red_candles = sum(1 for c in ohlcv if c.get("close", 0) < c.get("open", 0))
    total_candles = len(ohlcv)
    
    # Recent vs early performance (last 40% vs first 40% of bars)
    pivot = max(1, total_candles * 4 // 10)
    early_avg = sum(closes[:pivot]) / pivot
    recent_avg = sum(closes[-pivot:]) / pivot
    recent_vs_early_pct = ((recent_avg - early_avg) / early_avg) * 100 if early_avg > 0 else 0
    
    avg_volume = sum(volumes) / len(volumes) if volumes else 0
    age_min = token_meta.get("age_minutes", 9999) or 9999
    
    state = load_pattern_state()
    bc = state["base_confidence"]
    
    # ── Coarse (5-bar) classifier ──
    # Different thresholds because we're looking at session-level shape, not micro structure
    if is_coarse_synth:
        # vertical_rug: down hard across multiple bars, recent close near low
        if pct_change_session < -50 and recent_vs_early_pct < -30:
            return "vertical_rug", bc.get("vertical_rug", 0.10)
        
        # full_ai_cycle: massive session gain (>500%) , catches +3326% moves like TRUMPINATOR
        if pct_change_session > 500:
            return "full_ai_cycle", bc.get("full_ai_cycle", 0.72)
        
        # viral_narrative: big gain with sustained volume (>100% session, >50% recent vs early)
        if pct_change_session > 100 and recent_vs_early_pct > 50:
            return "viral_narrative", bc.get("viral_narrative", 0.65)
        
        # post_graduation_pump: fresh token (<2h) with positive session + recent strength
        if age_min < 120 and pct_change_session > 30 and recent_vs_early_pct > 0:
            return "post_graduation_pump", bc.get("post_graduation_pump", 0.62)
        
        # perfect_dip: positive session but recent weakness (the classic dip-buy entry)
        if pct_change_session > 20 and recent_vs_early_pct < -10:
            return "perfect_dip", bc.get("perfect_dip", 0.55)
        
        # instant_bond_fakerug: very fresh (<30m) + currently down but recovering off lows
        if age_min < 30 and pct_change_session < -10 and closes[-1] > min(closes) * 1.2:
            return "instant_bond_fakerug", bc.get("instant_bond_fakerug", 0.50)
        
        # staircase_pump: most bars green + sustained climb
        if green_candles >= total_candles - 1 and pct_change_session > 30:
            return "staircase_pump", bc.get("staircase_pump", 0.68)
        
        # meme_trend: modestly positive, mostly green
        if 0 < pct_change_session < 50 and green_candles > red_candles:
            return "meme_trend", bc.get("meme_trend", 0.48)
        
        # dump_in_progress: moderately down, mostly red, recent weakness , the falling knife
        if pct_change_session < -20 and red_candles >= green_candles:
            # Treat as a vertical_rug variant with adjusted confidence
            return "vertical_rug", bc.get("vertical_rug", 0.10)
        
        # pure_organic: low conviction, sideways
        if abs(pct_change_session) < 20:
            return "pure_organic", bc.get("pure_organic", 0.38)
        
        # unmatched coarse pattern → caller should fall through to Ollama naming
        return "unknown", 0.0
    
    # ── Fine (30+ bar) classifier ──
    # vertical_rug: deep drawdown >70%, low recovery
    if max_drawdown_pct < -70 and pct_change_session < -50:
        return "vertical_rug", bc.get("vertical_rug", 0.10)
    
    # staircase_pump: 5+ consecutive greens, each gaining 10%+
    consec_green = 0
    max_consec = 0
    for c in ohlcv:
        if c.get("close", 0) > c.get("open", 0):
            consec_green += 1
            max_consec = max(max_consec, consec_green)
        else:
            consec_green = 0
    if max_consec >= 5 and pct_change_session > 50:
        return "staircase_pump", bc.get("staircase_pump", 0.68)
    
    # post_graduation_pump: just bonded (age <1h) + retraced + recovered
    if age_min < 60 and max_drawdown_pct < -20 and pct_change_session > 30:
        return "post_graduation_pump", bc.get("post_graduation_pump", 0.62)
    
    # perfect_dip: drew down 30-50% then bounced
    if -50 < max_drawdown_pct < -30 and pct_change_session > 0:
        return "perfect_dip", bc.get("perfect_dip", 0.55)
    
    # instant_bond_fakerug: bonded recently, dumped fast, recovered
    if age_min < 30 and max_drawdown_pct < -40 and closes[-1] > closes[len(closes)//2]:
        return "instant_bond_fakerug", bc.get("instant_bond_fakerug", 0.50)
    
    # viral_narrative: gain >100% with high volume
    if pct_change_session > 100 and avg_volume > 0:
        return "viral_narrative", bc.get("viral_narrative", 0.65)
    
    # full_ai_cycle: pumped >200%, came back, going again
    if pct_change_session > 50 and max_drawdown_pct < -30:
        return "full_ai_cycle", bc.get("full_ai_cycle", 0.72) * 0.9
    
    # meme_trend: positive but unclear pattern

    if 0 < pct_change_session < 50 and green_candles > total_candles * 0.5:
        return "meme_trend", state["base_confidence"].get("meme_trend", 0.48)
    
    # pure_organic: low conviction, mixed candles
    if abs(pct_change_session) < 20:
        return "pure_organic", state["base_confidence"].get("pure_organic", 0.38)
    
    return "unknown", 0.0


async def classify_pattern(ohlcv: list, token_meta: dict) -> dict:
    """
    Main pattern classification entry point.
    
    Returns:
      {
        tier, tier_label, classification, confidence, is_novel, llm_named,
        llm_observation, matched_against_library
      }
    """
    name, confidence = classify_chart_heuristic(ohlcv, token_meta)
    
    is_novel = False
    llm_named = False
    llm_observation = None
    matched_against = f"PATTERN_BASE_CONFIDENCE.{name}" if name != "unknown" else None
    
    # Sprint 33+ — structural overlay: run deep detectors (Fib, linearity,
    # wick math, floor-defense, smooth-criminal-exit) on top of the simple
    # heuristic. If a structural pattern is confirmed with high confidence,
    # refine the name (e.g., perfect_dip → perfect_dip_fib_618) and bump
    # confidence. Always non-destructive — falls back to heuristic on no match.
    structural_evidence = {}
    try:
        refined_name, refined_conf, structural_evidence = _pe_structural_overlay(
            name, confidence, ohlcv
        )
        if refined_name != name:
            # Structural refinement — record it
            matched_against = f"structural_overlay.{refined_name} (from heuristic {name})"
            name = refined_name
            confidence = refined_conf
    except Exception as e:
        # Overlay errors must NEVER break the classification pipeline
        structural_evidence = {"_overlay_error": str(e)}
    
    # If unknown OR weak confidence, fall through to Ollama (Sprint 32: skippable via meeting override)
    if name == "unknown" or confidence < PATTERN_CONFIDENCE_THRESHOLD:
        if await get_override("BRAIN_PATTERN_LLM_ENABLED", True):
            llm_result = await llm_name_novel_pattern(ohlcv, token_meta)
            if llm_result and llm_result.get("name") and not llm_result["name"].startswith("llm_"):
                is_novel = True
                llm_named = True
                name = llm_result["name"]
                confidence = float(llm_result.get("confidence_in_name", 0.5))
                llm_observation = llm_result.get("description")
                matched_against = "ollama_named_novel"
                
                # Save snapshot for clustering / discovery later
                await save_novel_pattern_snapshot(ohlcv, token_meta, llm_result)
        else:
            llm_observation = "pattern LLM skipped per active meeting directive"
    
    # Determine tier
    tier_label = _infer_tier_label(token_meta)
    tier_num = {"pump_fun_graduate": 2, "moonshot_graduate": 2, "raydium_direct": 3, "long_term": 4, "organic": 1}.get(tier_label, 2)
    
    return {
        "tier": tier_num,
        "tier_label": tier_label,
        "classification": name,
        "confidence": round(confidence, 2),
        "track_record": pattern_track_record(name),  # Sprint 45+: the W-L scoreboard behind the confidence
        "is_novel": is_novel,
        "llm_named": llm_named,
        "llm_observation": llm_observation,
        "matched_against_library": matched_against,
        "structural_evidence": structural_evidence,  # Sprint 33+ — overlay detector outputs
    }


def _infer_tier_label(token_meta: dict) -> str:
    """Infer tier label from bonded_from + age."""
    bonded_from = (token_meta.get("bonded_from") or "").lower()
    age_min = token_meta.get("age_minutes", 9999)
    
    if "pump.fun" in bonded_from or "pump_fun" in bonded_from:
        return "pump_fun_graduate"
    if "moonshot" in bonded_from:
        return "moonshot_graduate"
    if "raydium" in bonded_from and age_min > 1440:
        return "long_term"
    if age_min > 1440:
        return "long_term"
    return "raydium_direct"


async def save_novel_pattern_snapshot(ohlcv: list, token_meta: dict, llm_result: dict) -> None:
    """Save chart shape + metadata for later clustering / pattern discovery."""
    sha = _sha8(f"{token_meta.get('mint')}_{_now_iso()}")

    # Sprint 45+: also capture the rendered chart PNG (not just candles) so novel
    # patterns can be eyeballed + clustered visually later. Best-effort , a render
    # failure must never block the snapshot json.
    chart_png = None
    try:
        chart_png = await render_custom_chart_png(
            token_meta.get("mint") or "", token_meta.get("ticker") or "?", ohlcv,
            out_path=str(_NOVEL_PATTERNS_DIR / f"novel_{sha}.png"),
        )
    except Exception as e:
        _log(f"save_novel_pattern_snapshot: chart render failed: {e}")

    snapshot = {
        "snapshot_at": _now_iso(),
        "mint": token_meta.get("mint"),
        "ticker": token_meta.get("ticker"),
        "ohlcv": ohlcv[-60:],  # last 60 candles
        "chart_png": chart_png,        # NEW: rendered visual for cluster review
        "token_meta": token_meta,
        "llm_proposed_name": llm_result.get("name"),
        "llm_description": llm_result.get("description"),
        "llm_why_degens_buy": llm_result.get("why_degens_buy"),
        "llm_confidence": llm_result.get("confidence_in_name"),
        "cluster_id": None,           # to be filled by discovery cron
        "promoted_to_library": False,
    }
    path = _NOVEL_PATTERNS_DIR / f"novel_{sha}.json"
    _save_json_atomic(path, snapshot)


def record_pattern_outcome(pattern: str, won: bool, pnl_pct: float, mint: str, ticker: str) -> None:
    """
    Append outcome to pattern_outcomes.json + update pattern_state confidence.
    Called by autopsy writer after each closed position.
    """
    outcomes = load_json_with_staleness(PATTERN_OUTCOMES_FILE, max_age_seconds=86400 * 365, default=[], alert_on_stale=False)
    if not isinstance(outcomes, list):
        outcomes = []
    
    outcomes.append({
        "timestamp": _now_iso(),
        "pattern": pattern,
        "won": won,
        "pnl_pct": pnl_pct,
        "mint": mint,
        "ticker": ticker,
    })
    _save_json_atomic(PATTERN_OUTCOMES_FILE, outcomes)
    
    # Update state confidence (smooth weighted update)
    state = load_pattern_state()
    seen = state["outcomes_seen"].setdefault(pattern, {"wins": 0, "losses": 0, "total": 0})
    if won:
        seen["wins"] += 1
    else:
        seen["losses"] += 1
    seen["total"] += 1
    
    if seen["total"] >= 3:
        observed_wr = seen["wins"] / seen["total"]
        # Soft EWMA update
        prior = state["base_confidence"].get(pattern, 0.5)
        alpha = 0.1  # how much weight to give new observations
        new_conf = prior * (1 - alpha) + observed_wr * alpha
        state["base_confidence"][pattern] = round(new_conf, 3)
    
    # Sprint 45+: novel-pattern promotion , outcome-triggered, self-rate-limiting.
    _maybe_fire_novel_promotion(pattern, state)
    
    save_pattern_state(state)


def pattern_track_record(pattern: str) -> dict:
    """The historical scoreboard for a pattern, read from pattern_outcomes.json.

    This is what the agent sees at decision time , the explicit W-L, expectancy, and
    recent form BEHIND the confidence float. REFERENCE, not a gate: a strong record
    is a tailwind, a thin/cold/stale one is a caution , neither is a ruling.
    """
    try:
        outcomes = load_json_with_staleness(
            PATTERN_OUTCOMES_FILE, max_age_seconds=86400 * 365, default=[], alert_on_stale=False
        )
    except Exception:
        outcomes = []
    if not isinstance(outcomes, list):
        outcomes = []
    rows = [o for o in outcomes if isinstance(o, dict) and o.get("pattern") == pattern]
    if not rows:
        return {"sample_size": 0,
                "read": "no track record yet , first sightings of this shape; trust the read, not stats"}

    wins   = [o for o in rows if o.get("won")]
    losses = [o for o in rows if not o.get("won")]
    n = len(rows)
    wr = len(wins) / n * 100
    avg_pnl  = sum(float(o.get("pnl_pct", 0) or 0) for o in rows) / n
    avg_win  = (sum(float(o.get("pnl_pct", 0) or 0) for o in wins) / len(wins)) if wins else 0.0
    avg_loss = (sum(float(o.get("pnl_pct", 0) or 0) for o in losses) / len(losses)) if losses else 0.0
    recent_form = "".join("W" if o.get("won") else "L" for o in rows[-5:])

    days_since = None
    try:
        # ── Sprint 55 BUGFIX: THIS WARNING HAS NEVER FIRED, NOT ONCE ────────────
        # The old code did:  fromisoformat(ts.replace("Z","").split("+")[0])
        # intending to strip the timezone and compare against a naive utcnow().
        #
        # But `split("+")` only strips a POSITIVE offset. Our timestamps are ET —
        # "-04:00" — so the offset SURVIVED, the parsed datetime stayed TZ-AWARE, and
        # `utcnow() - aware_dt` raised TypeError... which the bare `except` swallowed.
        #
        # Result: days_since was ALWAYS None, so the "STALE: last fired Xd ago, meta may
        # have moved" warning could never appear. A dead feature that looked alive, and
        # the only reason anyone noticed is a deprecation warning pointing at a line that
        # never worked in the first place.
        #
        # Compare tz-aware to tz-aware. Always.
        ts = str(rows[-1].get("timestamp") or "")
        last_dt = datetime.fromisoformat(ts.replace("Z", "+00:00"))
        if last_dt.tzinfo is None:
            last_dt = last_dt.replace(tzinfo=EST)
        days_since = round((datetime.now(EST) - last_dt).total_seconds() / 86400, 1)
    except Exception as _pe:
        _log(f"pattern staleness calc err: {_pe}", prefix="pattern")
        days_since = None

    # Synthesized read , adapts to sample size + expectancy. Raw, reference-framed.
    if n < 3:
        read = f"thin sample (n={n}) , trust the shape, not these stats"
    elif avg_pnl <= 0:
        read = f"{wr:.0f}% WR but NEGATIVE expectancy (avg {avg_pnl:+.0f}%) , losers outrun winners; WR is a trap here"
    elif wr >= 65:
        read = f"proven , {wr:.0f}% over {n}, avg {avg_pnl:+.0f}% (win {avg_win:+.0f}/loss {avg_loss:+.0f})"
    elif wr >= 45:
        read = f"coin-flip ({wr:.0f}% over {n}) but +EV (avg {avg_pnl:+.0f}%) , edge is in exits/sizing, not the shape"
    else:
        read = f"weak ({wr:.0f}% over {n}, avg {avg_pnl:+.0f}%) , shape hasnt paid; needs a non-pattern reason"
    if days_since is not None and days_since > 21 and n >= 3:
        read += f" | STALE: last fired {days_since:.0f}d ago, meta may have moved"

    return {
        "record": f"{len(wins)}-{len(losses)}",
        "win_rate_pct": round(wr, 1),
        "sample_size": n,
        "avg_pnl_pct": round(avg_pnl, 1),
        "avg_win_pct": round(avg_win, 1),
        "avg_loss_pct": round(avg_loss, 1),
        "recent_form": recent_form,
        "days_since_last": days_since,
        "read": read,
    }


NOVEL_PROMOTION_THRESHOLD = 3  # closed trades before a novel shape earns a promotion look


def _gather_novel_snapshots(pattern: str) -> list:
    """Saved novel-pattern snapshots whose LLM-proposed name matches `pattern`."""
    out = []
    try:
        if not _NOVEL_PATTERNS_DIR.exists():
            return out
        for f in sorted(_NOVEL_PATTERNS_DIR.glob("novel_*.json")):
            try:
                snap = load_json_with_staleness(f, max_age_seconds=86400 * 365, default=None, alert_on_stale=False)
                if isinstance(snap, dict) and snap.get("llm_proposed_name") == pattern:
                    out.append(snap)
            except Exception:
                continue
    except Exception:
        pass
    return out


def _maybe_fire_novel_promotion(pattern: str, state: dict) -> None:
    """One-shot promotion packet when an LLM-named (novel) shape crosses the closed-
    trade threshold. Novel = NOT in the seed library. Idempotent via state['promotion
    _fired']. Reuses pattern_track_record() , the same scoreboard the agent reads at
    decision time , and the novel_*.png charts captured at first sighting. Best-effort:
    a failure here must never break the autopsy/outcome write."""
    try:
        # Seed-library patterns are already promoted , nothing to review.
        if pattern in PATTERN_BASE_CONFIDENCE:
            return
        seen = state.get("outcomes_seen", {}).get(pattern, {})
        if seen.get("total", 0) < NOVEL_PROMOTION_THRESHOLD:
            return
        fired = state.setdefault("promotion_fired", [])
        if pattern in fired:
            return

        tr = pattern_track_record(pattern)
        snaps = _gather_novel_snapshots(pattern)
        sha = _sha8(f"promote_{pattern}_{_now_iso()}")
        packet = {
            "id": f"x_evt_pattern_promotion_{sha}",
            "type": "pattern_promotion_review",
            "received_at": _now_iso(),
            **_lane_fields("pattern_promotion_review"),
            "from_user": {"username": "@pattern_engine", "friendship_tier": "system", "user_id": "meme_sniper_bot"},
            "context": {
                "novel_pattern": pattern,
                "track_record": tr,
                "examples_count": len(snaps),
                "first_seen": (snaps[0].get("snapshot_at") if snaps else None),
                "example_charts": [s.get("chart_png") for s in snaps if s.get("chart_png")][:5],
                "llm_thesis": next((s.get("llm_description") for s in snaps if s.get("llm_description")), None),
                "why_degens_buy": next((s.get("llm_why_degens_buy") for s in snaps if s.get("llm_why_degens_buy")), None),
                "summary": (
                    f"You've been calling this shape '{pattern}' , it's now {tr.get('record', '?')} "
                    f"({tr.get('win_rate_pct', '?')}% over {tr.get('sample_size', '?')}, "
                    f"avg {tr.get('avg_pnl_pct', '?')}%). {len(snaps)} example chart(s) attached. Worth keeping?"
                ),
            },
            "decision_inputs": _decision_inputs([
                {"action_type": "promote_pattern", "when_this_fits": "fold into the seed library so it scores future tokens , route the add through code_tuner (PATTERN_BASE_CONFIDENCE + classify_chart_heuristic)"},
                {"action_type": "merge_pattern", "when_this_fits": "really an existing shape under a new name , route a merge via code_tuner; supply merge_into=<known_pattern>"},
                {"action_type": "keep_tracking", "when_this_fits": "leave it as a tracked novel for now , revisit when it grows"},
                {"action_type": "kill_pattern", "when_this_fits": "noise, not a real shape , have the engine stop naming it (code_tuner)"},
            ]),
            "actions_taken": [],
        }
        write_inbox_packet_generic(packet, prefix="pattern_promotion", identifier=sha)
        fired.append(pattern)
        _log(f"pattern promotion packet fired: '{pattern}' at {tr.get('record')} "
             f"({tr.get('win_rate_pct')}% / n={tr.get('sample_size')})", prefix="pattern")
    except Exception as e:
        _log(f"_maybe_fire_novel_promotion error for {pattern}: {e}", prefix="pattern")


# ═══════════════════════════════════════════════════════════════════════════
#                       CHART BUILDER (in-process module)
# ═══════════════════════════════════════════════════════════════════════════
#
# On-demand only. Saves Helius bill. Renders TWO outputs when triggered:
#   1. DexScreener live screenshot (via agent_scraper task , optional)
#   2. Custom matplotlib render with pattern overlays + entry markers
# Then optionally runs Ollama vision pass on both, returns text description.
#
# Telegram-silent on boot (no flood). Telegram only fires on actual trade exec.
# ═══════════════════════════════════════════════════════════════════════════

async def fetch_ohlcv(mint: str, *, interval: str = "1m", limit: int = 60, pair: Optional[dict] = None) -> list:
    """
    Fetch OHLCV history with 3-source cascade:
      1. Birdeye (true 1m candles) , used only if BIRDEYE_API_KEY is set
      2. DexScreener-synthesized (5 bars from m5/h1/h6/h24) , primary fallback, free
      3. Helius transaction history (last resort) , slow, expensive on RPC
    
    Returns [{ts, open, high, low, close, volume}, ...] sorted ascending,
    or [] on total failure.
    
    Pass `pair` if you already have it (saves a DexScreener call).
    """
    # ── Source 1: Birdeye (true 1m candles) ──
    birdeye_key = os.getenv("BIRDEYE_API_KEY", "")
    if birdeye_key:
        try:
            ohlcv = await _fetch_ohlcv_birdeye(mint, interval, limit, birdeye_key)
            if ohlcv:
                return ohlcv
        except Exception as e:
            _log(f"birdeye OHLCV error: {e}")
    
    # ── Source 2: DexScreener-synthesized (free, primary workhorse) ──
    try:
        ohlcv = await _fetch_ohlcv_from_dex(mint, pair=pair)
        if ohlcv and len(ohlcv) >= 2:  # need at least 2 bars to detect a shape
            return ohlcv
    except Exception as e:
        _log(f"dex-synth OHLCV error: {e}")
    
    # ── Source 3: Helius transaction history (slow, last resort) ──
    if HELIUS_API_KEY:
        try:
            ohlcv = await _fetch_ohlcv_from_helius(mint, limit)
            if ohlcv:
                return ohlcv
        except Exception as e:
            _log(f"helius OHLCV error: {e}")
    
    return []


# Backwards-compat alias for any caller still using the old name
fetch_ohlcv_from_birdeye = fetch_ohlcv


async def _fetch_ohlcv_birdeye(mint: str, interval: str, limit: int, api_key: str) -> list:
    """Birdeye OHLCV fetch , true 1m candles when API key present."""
    client = await _get_dex_client()
    now_unix = int(_now_ts())
    from_unix = now_unix - (60 * limit)
    r = await client.get(
        "https://public-api.birdeye.so/defi/ohlcv",
        params={
            "address": mint,
            "type": interval,
            "time_from": from_unix,
            "time_to": now_unix,
        },
        headers={"X-API-KEY": api_key, "x-chain": "solana"},
    )
    if r.status_code != 200:
        return []
    data = r.json() or {}
    items = (data.get("data") or {}).get("items") or []
    return [
        {
            "ts": int(item.get("unixTime") or 0),
            "open": float(item.get("o") or 0),
            "high": float(item.get("h") or 0),
            "low": float(item.get("l") or 0),
            "close": float(item.get("c") or 0),
            "volume": float(item.get("v") or 0),
        }
        for item in items if item.get("c")
    ]


async def _fetch_ohlcv_from_dex(mint: str, *, pair: Optional[dict] = None) -> list:
    """
    Synthesize 5 OHLCV bars from DexScreener's multi-timeframe data.
    
    DexScreener gives us:
      - priceUsd (close at "now")
      - priceChange.{m5, h1, h6, h24} (% change over each window)
      - volume.{m5, h1, h6, h24}
    
    From this we build 5 bars at distinct windows:
      bar 0: 24h ago    (close = price 24h ago,  vol = vol 24h - vol 6h)
      bar 1: 6h ago     (close = price 6h ago,   vol = vol 6h - vol 1h)
      bar 2: 1h ago     (close = price 1h ago,   vol = vol 1h - vol 5m)
      bar 3: 5min ago   (close = price 5m ago,   vol = vol 5m / 2)
      bar 4: now        (close = price now,      vol = vol 5m / 2)
    
    Window-shape is enough for pattern_engine to detect:
      - Vertical rugs (deep red across multiple bars)
      - Staircase pumps (consecutive green with rising volume)
      - Perfect dips (down-then-up)
      - Post-graduation pumps (recent green after retrace)
    
    Returns [] if pair data unusable (price=0).
    """
    if pair is None:
        pair = await fetch_token_data(mint)
    if not pair:
        return []
    
    price_now = float(pair.get("priceUsd") or 0)
    if price_now <= 0:
        return []
    
    pc = pair.get("priceChange") or {}
    vol = pair.get("volume") or {}
    now_ts = int(_now_ts())
    
    def _price_at(pct_change) -> float:
        """Reverse a priceChange% to get the price at that point in the past."""
        if pct_change is None:
            return 0.0
        try:
            multiplier = 1.0 + (float(pct_change) / 100.0)
            if multiplier <= 0:
                return 0.0
            return price_now / multiplier
        except (ValueError, ZeroDivisionError, TypeError):
            return 0.0
    
    price_5m_ago  = _price_at(pc.get("m5"))
    price_1h_ago  = _price_at(pc.get("h1"))
    price_6h_ago  = _price_at(pc.get("h6"))
    price_24h_ago = _price_at(pc.get("h24"))
    
    v_5m  = float(vol.get("m5")  or 0)
    v_1h  = float(vol.get("h1")  or 0)
    v_6h  = float(vol.get("h6")  or 0)
    v_24h = float(vol.get("h24") or 0)
    
    vol_24h_to_6h = max(0.0, v_24h - v_6h)
    vol_6h_to_1h  = max(0.0, v_6h - v_1h)
    vol_1h_to_5m  = max(0.0, v_1h - v_5m)
    
    bars = []
    
    if price_24h_ago > 0:
        bars.append({
            "ts": now_ts - 86400,
            "open": price_24h_ago,
            "high": price_24h_ago,
            "low": price_24h_ago,
            "close": price_24h_ago,
            "volume": vol_24h_to_6h,
        })
    
    if price_6h_ago > 0:
        prev_close = bars[-1]["close"] if bars else price_6h_ago
        bars.append({
            "ts": now_ts - 21600,
            "open": prev_close,
            "high": max(prev_close, price_6h_ago),
            "low": min(prev_close, price_6h_ago),
            "close": price_6h_ago,
            "volume": vol_6h_to_1h,
        })
    
    if price_1h_ago > 0:
        prev_close = bars[-1]["close"] if bars else price_1h_ago
        bars.append({
            "ts": now_ts - 3600,
            "open": prev_close,
            "high": max(prev_close, price_1h_ago),
            "low": min(prev_close, price_1h_ago),
            "close": price_1h_ago,
            "volume": vol_1h_to_5m,
        })
    
    if price_5m_ago > 0:
        prev_close = bars[-1]["close"] if bars else price_5m_ago
        bars.append({
            "ts": now_ts - 300,
            "open": prev_close,
            "high": max(prev_close, price_5m_ago),
            "low": min(prev_close, price_5m_ago),
            "close": price_5m_ago,
            "volume": v_5m * 0.5,
        })
    
    # bar 4: now (always include , even if all priceChange were null)
    prev_close = bars[-1]["close"] if bars else price_now
    bars.append({
        "ts": now_ts,
        "open": prev_close,
        "high": max(prev_close, price_now),
        "low": min(prev_close, price_now),
        "close": price_now,
        "volume": v_5m * 0.5,
    })
    
    return bars


async def _fetch_ohlcv_from_helius(mint: str, limit: int = 60) -> list:
    """
    Last-resort OHLCV: pull recent swap transactions for the mint via Helius
    enhanced API and aggregate into 1-minute buckets.
    
    Slow but works on tokens too new for DexScreener.
    Returns up to `limit` 1-minute bars sorted ascending.
    """
    if not HELIUS_API_KEY:
        return []
    
    client = await _get_rpc_client()
    url = f"https://api.helius.xyz/v0/addresses/{mint}/transactions"
    if helius_budget_restricted() or not _enhanced_allow("_fetch_ohlcv_from_helius"):
        return []
    helius_meter("enhanced", "_fetch_ohlcv_from_helius")
    
    try:
        r = await client.get(
            url,
            params={"api-key": HELIUS_API_KEY, "limit": 100, "type": "SWAP"},
        )
    except Exception:
        return []
    
    if r.status_code != 200:
        return []
    
    txs = r.json() or []
    if not isinstance(txs, list) or not txs:
        return []
    
    now_ts = int(_now_ts())
    cutoff_ts = now_ts - (60 * limit)
    
    buckets: dict = {}
    for tx in txs:
        try:
            ts = int(tx.get("timestamp") or 0)
            if ts < cutoff_ts:
                continue
            
            bucket_ts = (ts // 60) * 60
            
            token_xfers = tx.get("tokenTransfers") or []
            sol_xfers = tx.get("nativeTransfers") or []
            
            token_amount = 0.0
            sol_amount = 0.0
            for xfer in token_xfers:
                if xfer.get("mint") == mint:
                    token_amount = float(xfer.get("tokenAmount") or 0)
            for xfer in sol_xfers:
                sol_amount += abs(float(xfer.get("amount") or 0)) / 1_000_000_000
            
            if token_amount <= 0 or sol_amount <= 0:
                continue
            
            # Relative price (SOL per token) , fine for shape detection
            price = sol_amount / token_amount
            
            b = buckets.setdefault(bucket_ts, {
                "ts": bucket_ts,
                "open": price,
                "high": price,
                "low": price,
                "close": price,
                "volume": 0.0,
            })
            b["high"] = max(b["high"], price)
            b["low"] = min(b["low"], price)
            b["close"] = price  # last-seen wins
            b["volume"] += sol_amount
        except Exception:
            continue
    
    return sorted(buckets.values(), key=lambda b: b["ts"])


# ════════════════════════════════════════════════════════════════════════════
# CHART V2 + 30s REPLAY (2026-08-10)
# Ratified: "gif replay is perfect, watch anytime." Phase 1 only -
# the continuous live-watch loop is explicitly NOT wanted and stays unbuilt.
#
# What was wrong with v1: light theme, open-close drawn as a thick stick rather
# than a real body, no mcap anywhere (the desk manages by mcap floors all day),
# and no armed-zone or floor lines - so the one number the agent is actually
# deciding against was the one number the chart never showed.
#
# Nothing here touches a capital knob, a filter, or the dead dexscreener scrape.
# ════════════════════════════════════════════════════════════════════════════
CHART_V2_BG      = "#0b0e14"
CHART_V2_GRID    = "#1c2230"
CHART_V2_UP      = "#22c55e"
CHART_V2_DOWN    = "#ef4444"
CHART_V2_TEXT    = "#c9d4e5"
CHART_V2_MUTED   = "#6b7a90"
REPLAY_SECONDS   = 30
REPLAY_FRAMES    = 30


def _chart_v2_overlays(mint: str, position: Optional[dict] = None) -> dict:
    """Collect every overlay we can actually source. Absent keys are simply not
    drawn - a chart that invents a level is worse than one that omits it.

    The buy-zone and floor come from the edge_map phase work: base_mcap_zone is
    where the token is holding, invalidation_under_base is where the thesis dies.
    Those are the levels the desk already reasons in, so the chart draws THOSE
    rather than a second set of numbers nobody uses.
    """
    ov = {}
    try:
        pos = position or {}
        ep = float(pos.get("entry_price") or 0)
        if ep > 0:
            ov["entry_price"] = ep
            # v14.2 chart fix (2026-10-14): The agent's armed levels are the live ones;
            # params.stop_loss_pct is only the pre-v14.2 fallback.
            ap = pos.get("armed_protection") or {}
            sl_pct = float(ap.get("sl_pct") or (pos.get("params") or {}).get("stop_loss_pct") or 0)
            if sl_pct > 0:
                ov["sl_price"] = ep * (1 - sl_pct / 100.0)
                ov["sl_pct"] = sl_pct
            # the take-profit line (now the agent's armed TP)
            tp_pct = float(ap.get("tp_pct") or 0)
            if tp_pct > 0:
                ov["tp_price"] = ep * (1 + tp_pct / 100.0)
                ov["tp_pct"] = tp_pct
        # pattern + sell-flag badges, when the position has them
        _pat = pos.get("pattern")
        if isinstance(_pat, dict):
            if _pat.get("pattern") and _pat.get("pattern") != "unknown":
                ov["pattern_name"] = str(_pat.get("pattern"))
            _fl = [f.get("flag", "") if isinstance(f, dict) else str(f) for f in (_pat.get("sell_flags") or [])]
            if any(_fl):
                ov["sell_flags"] = [f for f in _fl if f][:3]
        pk = float(pos.get("peak_price") or 0)
        if pk > 0:
            ov["peak_price"] = pk

        em = pos.get("edge_map") or {}
        if not em:
            try:
                _wl = (load_watchlist() or {}).get(mint) or {}
                em = (_wl.get("potential_watch") or {})
                if em.get("baseline_mcap"):
                    ov["baseline_mcap"] = em.get("baseline_mcap")
            except Exception:
                em = {}
        zone = em.get("base_mcap_zone") or {}
        if zone.get("low") and zone.get("high"):
            ov["buy_zone_mcap"] = [zone["low"], zone["high"]]
        if em.get("invalidation_under_base"):
            ov["floor_mcap"] = em["invalidation_under_base"]
        if em.get("resolution_target_mcap"):
            ov["target_mcap"] = em["resolution_target_mcap"]

        # a hold's ratcheted floor outranks a static one - it is the live level
        fr = (pos.get("_floor_ratchet") or {})
        if fr.get("current_floor_mcap_usd"):
            ov["floor_mcap"] = fr["current_floor_mcap_usd"]
    except Exception:
        pass
    return ov


async def render_chart_v2_png(mint: str, ticker: str, ohlcv: list, *,
                              position: Optional[dict] = None,
                              overlays: Optional[dict] = None,
                              token_meta: Optional[dict] = None,
                              out_path: Optional[str] = None) -> Optional[str]:
    """Dark multi-panel chart with real candle bodies, volume and mcap overlays."""
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        import matplotlib.dates as mdates
        from matplotlib.patches import Rectangle
        from datetime import datetime as dt
    except ImportError:
        _log("matplotlib not available, skipping chart_v2")
        return None
    if not ohlcv:
        return None

    try:
        ov = overlays or {}
        meta = token_meta or {}
        ts = [dt.fromtimestamp(c.get("ts", 0)) for c in ohlcv]
        o = [float(c.get("open", 0)) for c in ohlcv]
        h = [float(c.get("high", 0)) for c in ohlcv]
        l = [float(c.get("low", 0)) for c in ohlcv]
        cl = [float(c.get("close", 0)) for c in ohlcv]
        v = [float(c.get("volume", 0)) for c in ohlcv]

        # mcap per price unit, so a price axis can carry an mcap twin
        now_mcap = float(meta.get("mcap") or 0)
        mcap_per_price = (now_mcap / cl[-1]) if (now_mcap > 0 and cl[-1]) else 0

        fig, (ax1, ax2) = plt.subplots(
            2, 1, figsize=(12, 7.6), gridspec_kw={"height_ratios": [3.2, 1]},
            sharex=True, facecolor=CHART_V2_BG)
        for ax in (ax1, ax2):
            ax.set_facecolor(CHART_V2_BG)
            ax.grid(True, color=CHART_V2_GRID, linewidth=0.6, alpha=0.9)
            ax.tick_params(colors=CHART_V2_MUTED, labelsize=8)
            for sp in ax.spines.values():
                sp.set_color(CHART_V2_GRID)

        # REAL bodies. v1 drew open-close as a thick line, which loses the body
        # edges - the thing you read a candle by.
        span = (ts[1] - ts[0]).total_seconds() / 86400.0 if len(ts) > 1 else 1 / 1440.0
        w = span * 0.62
        for i in range(len(ohlcv)):
            up = cl[i] >= o[i]
            col = CHART_V2_UP if up else CHART_V2_DOWN
            ax1.plot([ts[i], ts[i]], [l[i], h[i]], color=col, linewidth=0.9, zorder=2)
            lo_b, hi_b = (o[i], cl[i]) if up else (cl[i], o[i])
            ax1.add_patch(Rectangle((mdates.date2num(ts[i]) - w / 2, lo_b), w,
                                    max(hi_b - lo_b, (max(h) - min(l)) * 0.0015),
                                    facecolor=col, edgecolor=col, zorder=3))
            ax2.bar(ts[i], v[i], width=w, color=col, alpha=0.55)

        applied = []
        if ov.get("entry_price"):
            ax1.axhline(ov["entry_price"], color="#3b82f6", ls="--", lw=1.1, alpha=0.85, zorder=4)
            ax1.annotate(f"entry {ov['entry_price']:.8f}".rstrip("0"), (ts[0], ov["entry_price"]),
                         color="#3b82f6", fontsize=7.5, va="bottom")
            applied.append("entry_price")
        if ov.get("sl_price"):
            ax1.axhline(ov["sl_price"], color=CHART_V2_DOWN, ls=":", lw=1.1, alpha=0.85, zorder=4)
            ax1.annotate(f"SL -{ov['sl_pct']:.0f}%" if ov.get("sl_pct") else "SL",
                         (ts[0], ov["sl_price"]), color=CHART_V2_DOWN, fontsize=7.5, va="top")
            applied.append("sl_price")
        if ov.get("tp_price"):
            ax1.axhline(ov["tp_price"], color="#ffc107", ls="--", lw=0.9, alpha=0.75, zorder=4)
            ax1.annotate(f"TP +{ov.get('tp_pct', 0):.0f}%", (ts[0], ov["tp_price"]),
                         color="#ffc107", fontsize=7.5, va="bottom")
            applied.append("tp_price")
        if ov.get("pattern_name"):
            ax1.text(0.01, 0.97, f" {ov['pattern_name'].upper().replace('_', ' ')} ",
                     transform=ax1.transAxes, fontsize=8, color="white", fontweight="bold",
                     va="top", ha="left", zorder=6,
                     bbox=dict(boxstyle="round,pad=0.3", facecolor="#9c27b0", edgecolor="#9c27b0", alpha=0.9))
            applied.append("pattern_badge")
        for _i, _f in enumerate(ov.get("sell_flags") or []):
            ax1.text(0.99, 0.97 - _i * 0.08, f" {str(_f).upper().replace('_', ' ')} ",
                     transform=ax1.transAxes, fontsize=7, color="white", va="top", ha="right", zorder=6,
                     bbox=dict(boxstyle="round,pad=0.25", facecolor="#ff5722", edgecolor="#ff5722", alpha=0.85))
            if _i == 0:
                applied.append("sell_flags")
        if ov.get("peak_price"):
            ax1.axhline(ov["peak_price"], color="#eab308", ls="-", lw=0.7, alpha=0.5, zorder=4)
            ax1.annotate("peak", (ts[-1], ov["peak_price"]), color="#eab308",
                         fontsize=7.5, ha="right", va="bottom")
            applied.append("peak_price")
        # mcap levels -> price space, only when we can convert honestly
        if mcap_per_price:
            if ov.get("buy_zone_mcap"):
                lo_p = ov["buy_zone_mcap"][0] / mcap_per_price
                hi_p = ov["buy_zone_mcap"][1] / mcap_per_price
                ax1.axhspan(lo_p, hi_p, color="#22c55e", alpha=0.10, zorder=1)
                ax1.annotate(f"buy zone ${ov['buy_zone_mcap'][0]/1000:.0f}k-"
                             f"${ov['buy_zone_mcap'][1]/1000:.0f}k",
                             (ts[0], hi_p), color=CHART_V2_UP, fontsize=7.5, va="bottom")
                applied.append("buy_zone_mcap")
            if ov.get("floor_mcap"):
                fp = ov["floor_mcap"] / mcap_per_price
                ax1.axhline(fp, color="#f97316", ls="-.", lw=1.2, alpha=0.9, zorder=4)
                ax1.annotate(f"floor ${ov['floor_mcap']/1000:.0f}k", (ts[-1], fp),
                             color="#f97316", fontsize=7.5, ha="right", va="top")
                applied.append("floor_mcap")
            if ov.get("target_mcap"):
                tp = ov["target_mcap"] / mcap_per_price
                if min(l) * 0.5 <= tp <= max(h) * 3:
                    ax1.axhline(tp, color="#a78bfa", ls="--", lw=0.9, alpha=0.7, zorder=4)
                    ax1.annotate(f"target ${ov['target_mcap']/1000:.0f}k", (ts[-1], tp),
                                 color="#a78bfa", fontsize=7.5, ha="right", va="bottom")
                    applied.append("target_mcap")

        # mcap twin axis - the number the desk actually manages by
        if mcap_per_price:
            axm = ax1.twinx()
            axm.set_ylim(ax1.get_ylim()[0] * mcap_per_price, ax1.get_ylim()[1] * mcap_per_price)
            axm.set_ylabel("mcap $", color=CHART_V2_MUTED, fontsize=8)
            axm.tick_params(colors=CHART_V2_MUTED, labelsize=7.5)
            axm.yaxis.set_major_formatter(
                matplotlib.ticker.FuncFormatter(lambda x, _p: f"${x/1000:.0f}k"))
            for sp in axm.spines.values():
                sp.set_color(CHART_V2_GRID)

        chip = f"${ticker}  {mint[:4]}..{mint[-4:]}"
        bits = []
        if now_mcap:
            bits.append(f"mcap ${now_mcap/1000:.1f}k")
        if meta.get("liquidity_usd"):
            bits.append(f"liq ${float(meta['liquidity_usd'])/1000:.1f}k")
        if meta.get("age_minutes") is not None:
            bits.append(f"age {float(meta['age_minutes'])/60:.1f}h")
        if meta.get("phase_guess"):
            bits.append(str(meta["phase_guess"]))
        ax1.set_title(chip + ("   |   " + "  ·  ".join(bits) if bits else ""),
                      color=CHART_V2_TEXT, fontsize=11, loc="left", pad=12)
        ax2.set_ylabel("vol", color=CHART_V2_MUTED, fontsize=8)
        ax1.xaxis.set_major_formatter(mdates.DateFormatter("%H:%M"))
        fig.autofmt_xdate(rotation=0, ha="center")
        fig.tight_layout()

        out = out_path or str(_BOT_LOGS / "charts" / f"{ticker}_{mint[:8]}_v2.png")
        os.makedirs(os.path.dirname(out), exist_ok=True)
        fig.savefig(out, dpi=110, facecolor=CHART_V2_BG)
        plt.close(fig)
        _CHART_V2_LAST_OVERLAYS[mint] = applied
        return out
    except Exception as e:
        _log(f"chart_v2 render err {_short_mint(mint)}: {e}", prefix="chart")
        try:
            plt.close("all")
        except Exception:
            pass
        return None


_CHART_V2_LAST_OVERLAYS: dict = {}


async def collect_replay_marks(mint: str, seconds: int = REPLAY_SECONDS) -> tuple:
    """(marks, source_tag) - the last ~30s of price action, best effort.

    Cascade, most faithful first. The source is ALWAYS reported on the packet:
    a replay stitched from 1m candles is a different object from one sampled live,
    and labelling it 'replay' without saying which would be the same false-success
    problem that has bitten this codebase all week.
    """
    marks = []
    # 1. live sampling - the real thing. ~1s marks straight off the pair feed.
    try:
        step = max(0.5, seconds / float(REPLAY_FRAMES))
        for _i in range(REPLAY_FRAMES):
            pair = await fetch_token_data(mint)
            if not pair:
                break
            px = float(pair.get("priceUsd") or 0)
            if px > 0:
                marks.append({"ts": _now_ts(), "price": px,
                              "mcap": float(pair.get("marketCap") or pair.get("fdv") or 0)})
            await asyncio.sleep(step)
        if len(marks) >= 8:
            return marks, "1s_marks"
    except Exception as e:
        _log(f"replay live-sample err {_short_mint(mint)}: {e}", prefix="chart")

    # 2. fall back to zooming the tail of the finest candles we have
    try:
        oh = await fetch_ohlcv(mint, interval="1m", limit=12)
        if oh:
            zoom = []
            for c in oh[-6:]:
                base_ts = float(c.get("ts") or 0)
                o_, h_, l_, c_ = (float(c.get("open") or 0), float(c.get("high") or 0),
                                  float(c.get("low") or 0), float(c.get("close") or 0))
                # walk the candle o->h->l->c so the shape survives the zoom
                for k, p in enumerate((o_, h_, l_, c_)):
                    if p > 0:
                        zoom.append({"ts": base_ts + k * 15, "price": p})
            if len(zoom) >= 8:
                return zoom, "ohlcv_zoom"
    except Exception:
        pass
    return [], "unavailable"


async def render_replay_30s_gif(mint: str, ticker: str, marks: list, *,
                                overlays: Optional[dict] = None,
                                source: str = "unknown",
                                out_path: Optional[str] = None) -> Optional[str]:
    """Animated GIF of the last ~30s. Returns path or None - NEVER raises into
    the chart path, because the PNG must land even when the replay cannot."""
    if not marks or len(marks) < 4:
        return None
    try:
        import io as _bio          # meme_sniper does not import io at module level
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        from PIL import Image
    except ImportError:
        _log("PIL/matplotlib missing - no replay gif", prefix="chart")
        return None
    try:
        ov = overlays or {}
        px = [float(m.get("price") or 0) for m in marks if m.get("price")]
        if len(px) < 4:
            return None
        lo, hi = min(px), max(px)
        pad = max((hi - lo) * 0.25, hi * 0.002)
        frames = []
        for i in range(2, len(px) + 1):
            fig, ax = plt.subplots(figsize=(6.4, 3.2), facecolor=CHART_V2_BG)
            ax.set_facecolor(CHART_V2_BG)
            ax.grid(True, color=CHART_V2_GRID, lw=0.5, alpha=0.8)
            seg = px[:i]
            rising = seg[-1] >= seg[0]
            col = CHART_V2_UP if rising else CHART_V2_DOWN
            ax.plot(range(len(seg)), seg, color=col, lw=1.9)
            ax.fill_between(range(len(seg)), lo - pad, seg, color=col, alpha=0.12)
            ax.scatter([len(seg) - 1], [seg[-1]], color=col, s=28, zorder=5)
            if ov.get("entry_price") and lo - pad <= ov["entry_price"] <= hi + pad:
                ax.axhline(ov["entry_price"], color="#3b82f6", ls="--", lw=0.9, alpha=0.8)
            ax.set_xlim(0, max(len(px) - 1, 1))
            ax.set_ylim(lo - pad, hi + pad)
            ax.tick_params(colors=CHART_V2_MUTED, labelsize=7)
            for sp in ax.spines.values():
                sp.set_color(CHART_V2_GRID)
            _mv = ((seg[-1] - px[0]) / px[0] * 100) if px[0] else 0
            ax.set_title(f"${ticker}  last {REPLAY_SECONDS}s   {seg[-1]:.8f}".rstrip("0")
                         + f"   {_mv:+.2f}%",
                         color=CHART_V2_TEXT, fontsize=9, loc="left")
            # the source is ON the frame - a replay you cannot audit is decoration
            ax.annotate(f"source={source}", (0.99, 0.03), xycoords="axes fraction",
                        color=CHART_V2_MUTED, fontsize=6.5, ha="right")
            buf = _bio.BytesIO()
            fig.tight_layout()
            fig.savefig(buf, format="png", dpi=90, facecolor=CHART_V2_BG)
            plt.close(fig)
            buf.seek(0)
            frames.append(Image.open(buf).convert("P", palette=Image.ADAPTIVE))
        if not frames:
            return None
        out = out_path or str(_BOT_LOGS / "charts" / f"{ticker}_{mint[:8]}_replay30s.gif")
        os.makedirs(os.path.dirname(out), exist_ok=True)
        frames[0].save(out, format="GIF", save_all=True, append_images=frames[1:],
                       duration=int(REPLAY_SECONDS * 1000 / max(1, len(frames))),
                       loop=0, optimize=True)
        return out
    except Exception as e:
        _log(f"replay gif err {_short_mint(mint)}: {e}", prefix="chart")
        try:
            plt.close("all")
        except Exception:
            pass
        return None


_CJK_FONT_CHECKED = False


def _cjk_font_ready(sample_text: str = "") -> bool:
    """2026-08-15: make CJK token names renderable instead of tofu+warning spam.

    matplotlib's DejaVu Sans has no CJK coverage. Rather than ship a font or
    mangle the ticker, look for one Windows already has and prepend it to the
    sans-serif stack. Runs its search ONCE per process - font_manager enumeration
    is slow and this is called per chart.

    Also silences the per-glyph UserWarning regardless of whether a font is found:
    the warning tells us nothing actionable after the first time, and ~10 lines per
    chart buries the log lines that matter.
    """
    global _CJK_FONT_CHECKED
    if _CJK_FONT_CHECKED:
        return True
    _CJK_FONT_CHECKED = True
    try:
        import warnings as _w
        _w.filterwarnings("ignore", message=r"Glyph \d+ .* missing from font")
    except Exception:
        pass
    try:
        import matplotlib
        from matplotlib import font_manager as _fm
        _have = {f.name for f in _fm.fontManager.ttflist}
        for _cand in ("Microsoft YaHei", "MS Gothic", "Yu Gothic", "Meiryo",
                      "SimHei", "SimSun", "Malgun Gothic", "Noto Sans CJK SC",
                      "Arial Unicode MS"):
            if _cand in _have:
                _cur = list(matplotlib.rcParams.get("font.sans-serif") or [])
                if _cand not in _cur:
                    matplotlib.rcParams["font.sans-serif"] = [_cand] + _cur
                matplotlib.rcParams["axes.unicode_minus"] = False
                _log(f"chart font: using {_cand} for CJK tickers", prefix="chart")
                return True
        _log("chart font: no CJK font found - non-latin tickers will draw as boxes "
             "(the mint still identifies the token). Warnings suppressed.",
             prefix="chart")
    except Exception:
        pass
    return False


async def render_custom_chart_png(mint: str, ticker: str, ohlcv: list, *, position: Optional[dict] = None, out_path: Optional[str] = None) -> Optional[str]:
    """
    Render OHLCV + entry/exit overlays as PNG.
    Lightweight matplotlib render. Returns PNG path or None on failure.
    """
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        import matplotlib.dates as mdates
        from datetime import datetime as dt
    except ImportError:
        _log("matplotlib not available, skipping custom chart")
        return None
    
    if not ohlcv:
        return None
    
    try:
        # Build series
        timestamps = [dt.fromtimestamp(c.get("ts", 0)) for c in ohlcv]
        opens = [c.get("open", 0) for c in ohlcv]
        highs = [c.get("high", 0) for c in ohlcv]
        lows = [c.get("low", 0) for c in ohlcv]
        closes = [c.get("close", 0) for c in ohlcv]
        volumes = [c.get("volume", 0) for c in ohlcv]
        
        fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(12, 7), gridspec_kw={"height_ratios": [3, 1]}, sharex=True)
        
        # Price chart
        for i in range(len(ohlcv)):
            color = "#22c55e" if closes[i] >= opens[i] else "#ef4444"
            ax1.plot([timestamps[i], timestamps[i]], [lows[i], highs[i]], color=color, linewidth=0.8)
            ax1.plot([timestamps[i], timestamps[i]], [opens[i], closes[i]], color=color, linewidth=3)
        
        # Entry/exit overlays
        if position:
            entry_price = position.get("entry_price", 0)
            if entry_price > 0:
                ax1.axhline(y=entry_price, color="#3b82f6", linestyle="--", alpha=0.6, label=f"Entry @ \\${entry_price:.6f}")
            stop_loss_pct = position.get("params", {}).get("stop_loss_pct", 20)
            if entry_price > 0:
                sl_price = entry_price * (1 - stop_loss_pct / 100)
                ax1.axhline(y=sl_price, color="#ef4444", linestyle=":", alpha=0.5, label=f"SL @ -{stop_loss_pct}%")
        
        # parse_math=False: ticker names start with "$" (and some are "$$KING"),
        # which matplotlib otherwise treats as LaTeX mathtext and crashes on
        # ("ParseException: Expected end of text, found '$'"). Render literally.
        # ── 2026-08-15: CJK TICKERS DRAW AS TOFU AND SPAM THE LOG ───────────
        # DejaVu Sans (matplotlib's default) has no CJK glyphs, so 孫悟空 / ユキ
        # render as empty boxes AND emit a UserWarning PER GLYPH PER SAVE. On the
        # 2026-08-15 tape that was ~10 warning lines for two tokens, which is how a
        # cosmetic font issue turns into an observability problem: real errors get
        # buried in font noise.
        #
        # Stripping the characters was my first fix and it was worse - it turned
        # 孫悟空 into "[non-latin]" and threw the name away. Windows ships CJK fonts,
        # so use one when present and keep the real ticker either way. The tofu is
        # cosmetic; losing the name is not.
        _cjk_font_ready(ticker)
        _title = f"${ticker} ({_short_mint(mint)}) , Custom Render"
        try:
            ax1.set_title(_title, fontsize=14, fontweight="bold", parse_math=False)
        except TypeError:
            # older matplotlib without parse_math kwarg — escape the $ instead
            ax1.set_title(_title.replace("$", r"\$"), fontsize=14, fontweight="bold")
        ax1.set_ylabel("Price USD")
        ax1.grid(True, alpha=0.2)
        if position:
            ax1.legend(loc="upper left", fontsize=9)
        
        # Volume bars
        ax2.bar(timestamps, volumes, color="#64748b", alpha=0.7, width=0.0007)
        ax2.set_ylabel("Volume")
        ax2.grid(True, alpha=0.2)
        ax2.xaxis.set_major_formatter(mdates.DateFormatter("%H:%M"))
        
        plt.tight_layout()
        
        out_path = out_path or (_CHART_DIR / f"{ticker}_{_sha8(mint + str(_now_ts()))}.png")
        plt.savefig(out_path, dpi=100, bbox_inches="tight")
        plt.close(fig)
        
        return str(out_path)
    except Exception as e:
        _log(f"render_custom_chart_png error: {e}")
        return None


# v1.1.0 (2026-08-06, LENS ship set): request_dexscreener_screenshot DELETED.
# It queued scrape_type='dex_token_screenshot', which agent_scraper's SCRAPERS
# dict has never contained, and then waited 15s on json_relay/browser_response.json
# - a channel nothing has written since the scraper moved to its own response
# files. Dead on both ends: an unsupported request waiting on an unwritten reply.
# It burned 15s of every chart build on a loop that could not close.
# Ratified as DELETE, not gate (agent_scraper lens Q6). Charts keep the custom
# render + the Ollama vision pass; chart_path_dexscreener stays in the contract
# as None so every downstream consumer of that key is untouched.


async def run_chart_vision_analysis(png_paths: list[str], token_meta: dict, pattern: dict, edge_filter: dict) -> Optional[str]:
    """Run Ollama vision pass on chart PNG(s). Returns 4-5 line text analysis."""
    paths_to_analyze = [p for p in png_paths if p and os.path.exists(p)]
    if not paths_to_analyze:
        return None
    
    prompt = f"""You are analyzing a memecoin chart. {len(paths_to_analyze)} image(s) attached.

Token: {token_meta.get('ticker')} (mint: {_short_mint(token_meta.get('mint', ''))})
Pattern engine classification: {pattern.get('classification')} (confidence: {pattern.get('confidence')})
The owner's edge filter: {edge_filter.get('owner_edge_verdict', 'no verdict')}

Tell the owner in 4-5 lines what you see. Be honest. Be specific. Use degen language.

Cover:
1. What shape is this? (degen pattern terms , pump, dip, fakeout, scam wick, etc.)
2. Where is it in its lifecycle? (early, middle, late, dead)
3. What's the volume profile telling us?
4. Buy / wait / skip , your call, with reason
5. If buy: rough param suggestion (the owner sets exact numbers, you give starting point)

Return only the 5 lines, no preamble. No JSON. Just the read."""
    
    return await ollama_generate_with_image(prompt, paths_to_analyze, max_tokens=400)


async def build_chart_for_agent(mint: str, ticker: str, position: Optional[dict] = None,
                                 *, style: str = "v2", replay_30s: bool = True,
                                 overlays_on: bool = True) -> dict:
    """
    Main entry point for view_chart action.
    Builds: custom render + (optional) DexScreener screenshot + Ollama vision text.
    
    Writes:
      - inbox/x_evt_chart_packet_<mint8>.json , the agent surface
      - bot_logs/chart_history.jsonl , the audit trail

    FIX 4 (2026-08-16): this used to claim a second write to
    json_relay/chart_response.json. Nothing here writes that file and nothing
    reads it. Meanwhile the meme-hunter skill tells the agent "chart_response.json
    does not exist" , which was true of the file and false of this docstring, so
    the two documents disagreed and both were partly wrong. The audit trail is
    chart_history.jsonl.
    
    Sprint 32: respects CHART_BUILD_ENABLED meeting override. When disabled,
    returns a minimal stub so callers don't break.
    """
    if not await get_override("CHART_BUILD_ENABLED", True):
        _log(f"chart: SKIPPED for {ticker} ({_short_mint(mint)}) per meeting override")
        return {
            "chart_path_custom": None,
            "chart_path_dexscreener": None,
            "vision_text": "(chart build skipped per active meeting directive)",
            "mint": mint,
            "ticker": ticker,
            "built_at": _now_iso(),
            "ohlcv_candles": 0,
            "skipped": "disabled_via_meeting",
        }
    
    _log(f"chart: building chart for {ticker} ({_short_mint(mint)})")
    
    # 1. Fetch OHLCV (3-source cascade: Birdeye → DexScreener-synth → Helius)
    ohlcv = await fetch_ohlcv(mint, limit=60)
    
    # 2. Render custom chart
    # ── CHART V2 (2026-08-10) ───────────────────────────────────────────────
    # Overlays are sourced, not invented: entry/SL/peak from the open position,
    # buy-zone and floor from the edge_map phase work. When a level has no source
    # it is simply not drawn - a chart that guesses a floor is worse than one that
    # omits it, because the desk would trade against the guess.
    _ov = _chart_v2_overlays(mint, position) if overlays_on else {}
    _meta = {}
    try:
        _p = await fetch_token_data(mint)
        if _p:
            _meta = {"mcap": _p.get("marketCap") or _p.get("fdv"),
                     "liquidity_usd": ((_p.get("liquidity") or {}) or {}).get("usd")}
            try:
                _wl = (load_watchlist() or {}).get(mint) or {}
                _meta["age_minutes"] = _wl.get("age_minutes")
                _meta["phase_guess"] = (_wl.get("potential_watch") or {}).get("tier")
            except Exception:
                pass
    except Exception:
        pass

    if str(style).lower() == "v1":
        custom_png = await render_custom_chart_png(mint, ticker, ohlcv, position=position)
    else:
        custom_png = await render_chart_v2_png(mint, ticker, ohlcv, position=position,
                                               overlays=_ov, token_meta=_meta)
        if not custom_png:
            # v2 failed - fall back rather than return no chart at all
            _log(f"chart_v2 failed for {ticker}, falling back to v1", prefix="chart")
            custom_png = await render_custom_chart_png(mint, ticker, ohlcv, position=position)

    # ── 30s REPLAY ──────────────────────────────────────────────────────────
    # NEVER blocks the PNG. A failed replay reports WHY, because "no gif" and
    # "gif unavailable because the feed was dead" are different facts.
    replay_gif, replay_source, replay_frames = None, "disabled", 0
    if replay_30s:
        try:
            _marks, replay_source = await collect_replay_marks(mint)
            replay_frames = len(_marks)
            if _marks:
                replay_gif = await render_replay_30s_gif(mint, ticker, _marks,
                                                         overlays=_ov, source=replay_source)
                if not replay_gif:
                    replay_source = f"{replay_source}_render_failed"
        except Exception as _re:
            replay_source = "unavailable"
            _log(f"replay err {_short_mint(mint)}: {_re}", prefix="chart")
    
    # 3. DexScreener screenshot: retired 2026-08-06 (see the note above
    #    run_chart_vision_analysis). Kept as an explicit None so the
    #    chart_path_dexscreener contract key and every reader of it survive.
    dex_png = None
    
    # 4. Ollama vision pass on both
    vision_text = None
    if custom_png or dex_png:
        # Need pattern + edge_filter for context , fetch fresh
        token_data = await fetch_token_data(mint)
        token_meta = {
            "mint": mint,
            "ticker": ticker,
            "mcap": (token_data.get("marketCap") or token_data.get("fdv")) if token_data else 0,
            "liquidity_usd": (token_data.get("liquidity") or {}).get("usd") if token_data else 0,
            "volume_24h": (token_data.get("volume") or {}).get("h24") if token_data else 0,
            "price_change_1h": (token_data.get("priceChange") or {}).get("h1") if token_data else 0,
        } if token_data else {"mint": mint, "ticker": ticker}
        
        pattern = await classify_pattern(ohlcv, token_meta)
        edge_filter = compute_edge_filter(token_meta) if token_data else {}
        
        png_list = [p for p in [custom_png, dex_png] if p]
        # Sprint 32: vision analysis skippable via meeting override
        if await get_override("BRAIN_VISION_ENABLED", True):
            vision_text = await run_chart_vision_analysis(png_list, token_meta, pattern, edge_filter)
        else:
            vision_text = "(vision analysis skipped per active meeting directive)"
    
    # 5. Build the response dict
    response = {
        "chart_path_custom": custom_png,
        "chart_path_replay_gif": replay_gif,
        "replay_source": replay_source,      # 1s_marks | ohlcv_zoom | unavailable | disabled
        "replay_frames": replay_frames,
        "overlays_applied": _CHART_V2_LAST_OVERLAYS.get(mint, []),
        "chart_style": ("v1" if str(style).lower() == "v1" else "v2"),
        "chart_path_dexscreener": dex_png,
        "vision_text": vision_text,
        "mint": mint,
        "ticker": ticker,
        "built_at": _now_iso(),
        "ohlcv_candles": len(ohlcv),
    }
    
    # 6. Sniper-internal audit (append to bot_logs JSONL)
    try:
        _append_jsonl(CHART_HISTORY_LOG, {
            **response,
            "logged_at": _now_iso(),
        })
    except Exception as e:
        _log(f"chart: history log write failed: {e}")
    
    # 7. Sprint 28.4.3: write inbox packet so the agent sees the chart result
    try:
        chart_packet = {
            "id": f"x_evt_chart_packet_{mint[:8]}_{int(_now_ts())}",
            "type": "chart_packet",
            "received_at": _now_iso(),
            **_lane_fields("chart_packet"),
            "from_user": {
                "username": "@meme_sniper",
                "friendship_tier": "system",
                "user_id": "meme_sniper_bot",
            },
            "context": {
                "mint": mint,
                "ticker": ticker,
                "chart_path_custom": custom_png,
                "chart_path_dexscreener": dex_png,
                "vision_text": vision_text,
                "ohlcv_candles": len(ohlcv),
                "built_at": _now_iso(),
                "summary": (
                    f"Chart built for {ticker}. Vision says: " +
                    (vision_text[:200] + "..." if vision_text and len(vision_text) > 200 else (vision_text or "no vision text"))
                ),
            },
            "decision_inputs": _decision_inputs([
                {"action_type": "review_chart", "when_this_fits": "look at the rendered chart + vision text, decide on entry"},
                {"action_type": "fire_buy_signal", "when_this_fits": "chart confirms entry , proceed with sizing"},
                {"action_type": "ignore", "when_this_fits": "chart says skip"},
            ]),
            "actions_taken": [],
        }
        write_inbox_packet_generic(chart_packet, prefix="chart_packet", identifier=f"{mint[:8]}_{int(_now_ts())}")
    except Exception as e:
        _log(f"chart: inbox packet write failed: {e}")
    
    return response


# ═══════════════════════════════════════════════════════════════════════════
#                          EDGE FILTER (the owner's edge)
# ═══════════════════════════════════════════════════════════════════════════
#
# Hybrid filter per the owner's decision: every bonded token ≥$10k flows to inbox,
# but each packet carries an edge_filter block showing pass/fail per criterion.
# Advisory, not gating , the agent still decides.
# ═══════════════════════════════════════════════════════════════════════════

EDGE_LIQ_MIN_USD          = float(_envv("EDGE_LIQ_MIN_USD", "20000"))   # v14: env-tunable (filter override still wins)
EDGE_LIQ_MAX_USD          = float(_envv("EDGE_LIQ_MAX_USD", "50000"))   # v14: env-tunable (filter override still wins)
EDGE_MCAP_MIN_USD         = 30_000
EDGE_MCAP_MAX_USD         = 1_000_000
EDGE_VOL_LIQ_RATIO_MIN    = 6.0
EDGE_PRICE_CHANGE_1H_MIN  = 0.0
EDGE_META_AVOID           = ("political", "food")
EDGE_X_QUALITY_AVOID      = ("established",)


# ── FIX 2 (2026-08-15): ONE NUMBER, ONE PLACE ───────────────────────────────
# Most TUNABLE_PARAMS entries now write `"default": SOME_CONST`. Ten cannot:
# their consts (EDGE_*, TELEGRAM_ON_*) are defined BELOW the schema dict, so a
# reference inside the literal would be a NameError at import. Those ten kept
# hand-typed copies of the same number.
#
# That is the exact shape of the bug this whole pass exists for. TRENDING_TICK
# sat at 1h/2h in the schema while the const said 15min, the filter file was
# GENERATED from the schema, and the loops read the file — so Sprint 54's
# 15-minute cadence never went live and everyone kept quoting the const.
#
# This runs once at import, after every const exists, and makes the const the
# single source for any knob that shares its name. It is a no-op the day it
# ships (all ten agree right now — that was verified before it was written).
# It earns its keep on the day someone edits a const and forgets the schema:
# the schema follows, the boot drift-detector then sees the filter file's
# code_default fall behind, and the stale default gets STAMPED instead of
# quietly winning. A binder without the detector would hide the change; the
# detector without the binder has nothing to detect.
#
# It never touches a knob's `value` — that lives in the filter file and only a
# deliberate promotion moves it.
def _bind_schema_defaults_to_consts() -> list:
    """Rebind TUNABLE_PARAMS[name]['default'] to the module const of the same
    name where one exists. Returns [(name, old, new)] for anything it moved."""
    moved = []
    _g = globals()
    for _name, _spec in TUNABLE_PARAMS.items():
        if _name not in _g:
            continue
        _const = _g[_name]
        if not isinstance(_const, (int, float, bool)):
            continue                      # tuples/paths/clients are not knobs
        _cur = _spec.get("default")
        if _cur == _const and type(_cur) is type(_const):
            continue
        _spec["default"] = _const
        moved.append((_name, _cur, _const))
    return moved


# ── FIX 3 (2026-08-15): CAPTIONS DO NOT GET TO NAME THE NUMBER ─────────────
# Twenty-seven schema captions carried a "Default N" or "was N" clause. Every
# one of them was a second copy of a number that already lives in the knob's
# `value`, and a copy that nothing updates is a copy that goes wrong: the trail
# captions still advertised 15 and 25 ten days after the values moved to 12 and
# 20. That prose is not decoration - boot sync pushes it into the filter file,
# the tune invitation quotes it, and the meeting interpreter matches the owner's
# directives against `description`. A stale caption makes a tune argue with a
# caption instead of the knob.
#
# Semantics stay ('0 = no filter'), guidance stays ('raise to 70+'), companion
# thresholds stay ('within +/-2% of entry'), and history goes where history
# lives - the knob's `history` array. Only the self-duplicating default goes.
#
# This lint exists because the sweep is worthless without it. Fixing 27 captions
# by hand fixes today; the 28th gets typed next sprint and nobody notices until
# a tune argues with it. It logs, never raises - a caption is not worth a boot.
def _lint_schema_captions() -> list:
    """Return [(knob, caption)] for any description that names its own default."""
    import re as _re
    _pat = _re.compile(r"\b(default|was|hard-locked)\s+~?\$?[\d]", _re.I)
    return [(_n, _s.get("description") or "")
            for _n, _s in TUNABLE_PARAMS.items()
            if _pat.search(_s.get("description") or "")]


for _n, _cap in _lint_schema_captions():
    _log(f"schema caption lint: TUNABLE_PARAMS['{_n}'].description names a default in "
         f"prose. That number is a second copy of the knob's value and will go stale. "
         f"Put it in the knob's history, not the caption: {_cap[:120]!r}",
         prefix="filter")

_SCHEMA_CONST_REBINDS = _bind_schema_defaults_to_consts()
for _n, _o, _c in _SCHEMA_CONST_REBINDS:
    _log(f"schema: TUNABLE_PARAMS['{_n}'].default was {_o}, module const says {_c} — "
         f"const wins. The filter file still holds the OLD code_default until boot "
         f"sync stamps the drift; the loops read the FILE, so {_c} is not live yet.",
         prefix="filter")


def _classify_x_quality(twitter_followers: int, x_account_age_days: Optional[int]) -> str:
    if not twitter_followers:
        return "no_x"
    if x_account_age_days is None:
        x_account_age_days = 0
    if twitter_followers > 5000 and x_account_age_days > 1825:  # >5y old + 5k+ followers
        return "established"
    if x_account_age_days < 7:
        return "brand_new"
    if twitter_followers < 100:
        return "micro"
    if twitter_followers < 5000:
        return "growing"
    return "mid"


# ── FIX 4 (2026-08-15): KNOB ROLES ──────────────────────────────────────────
# Four different blocks in a candidate packet say "pass" or "fail" about a token
# and NONE of them mean the same thing. `hardcoded_checks` is display.
# `drop2_filter_results` is advisory. `edge_filter` mostly stamps. Exactly one
# knob in this entire schema can stop a packet from existing: MCAP_FLOOR_USD.
#
# The agent has been reading four mouths and getting four different answers to
# "what blocked it." The role tag travels with the knob so the answer is on the
# knob itself instead of inferred from which block it appeared in.
_KNOB_ROLES = {
    "MCAP_FLOOR_USD": "hard_prepacket",
}
_KNOB_ROLE_PREFIX = (
    ("SCAN_TICK", "cadence"), ("REDUCED_THROUGHPUT", "cadence"),
    ("TRENDING_TICK", "cadence"), ("WATCHLIST_RECHECK_S", "cadence"),
    ("DEX_PAID_WATCH_TICK", "cadence"), ("META_REFRESH_INTERVAL", "cadence"),
    ("MISSED_RUNNER_AUTOPSY_TICK", "cadence"),
    ("EDGE_", "edge_reference"),
    ("SIZE_CAP", "size_or_exit"), ("DYNAMIC_SIZE_CAP", "size_or_exit"),
    ("DEFAULT_", "size_or_exit"),
    ("MEETING_", "meeting"),
    ("BRAIN_", "brain"), ("CHART_BUILD", "brain"),
    ("TELEGRAM_ON_", "notification"),
)
_KNOB_ROLES_EXACT = {
    "HOLDERS_MIN_COUNT": "advisory_drop2", "TOP10_MAX_PCT": "advisory_drop2",
    "DEV_MAX_HOLDING_PCT": "advisory_drop2", "TIME_BONDED_MIN_MINUTES": "advisory_drop2",
    "TIME_BONDED_MAX_MINUTES": "advisory_drop2", "LP_LOCKED_MIN_PCT": "advisory_drop2",
    "VOL_LIQ_5M_MIN": "advisory_drop2", "VOL_LIQ_1H_MIN": "advisory_drop2",
    "PRICE_CHANGE_5M_MIN": "advisory_drop2", "PRICE_CHANGE_24H_MIN": "advisory_drop2",
    "TWITTER_FOLLOWERS_MIN": "advisory_drop2", "TELEGRAM_MEMBERS_MIN": "advisory_drop2",
    "X_ACCOUNT_AGE_MIN_DAYS": "advisory_drop2", "REQUIRE_META_ALIGNMENT": "advisory_drop2",
    "META_ALIGNMENT_WEIGHT": "advisory_drop2",
    "WALLET_FLOOR_SOL": "wallet_floor",
}


def _knob_role(name: str) -> str:
    if name in _KNOB_ROLES:
        return _KNOB_ROLES[name]
    if name in _KNOB_ROLES_EXACT:
        return _KNOB_ROLES_EXACT[name]
    if name.endswith("_PAUSED"):
        return "pause"
    for pref, role in _KNOB_ROLE_PREFIX:
        if name.startswith(pref):
            return role
    return "scanner_threshold"


_DRIFT_SENTINEL = object()


def compute_current_filter_state() -> dict:
    """Drift card for a meme_candidate packet: what config is the bot ACTUALLY
    running, and do its four books agree?

    ── FIX 4 (2026-08-15): THIS FUNCTION USED TO BE THE DRIFT ──────────────────
    It read the filter FILE, reported the file's numbers, and its docstring said
    that was "exactly what config the bot is running under." It is not. It is
    exactly what the file says. Those differ whenever the file has not been
    reloaded into _ACTIVE_OVERRIDES, and `is_overridden` (file value !=
    file code_default) was a lie in BOTH directions once code_default went
    stale: a knob nobody had ever touched read as untouched while running a
    number nobody chose, and a real the owner override could read as a default.

    A knob's value now lives in four books and they can all disagree:

      file_value    - bots/tuner/meme_sniper_filter.json, "value"
      runtime_value - _ACTIVE_OVERRIDES, what get_override_sync ACTUALLY returns
                      to the loops right now. This is the one that moves money.
      schema_default- TUNABLE_PARAMS[name]["default"]
      module_const  - the same-named module constant, if one exists

    Every mismatch is named in `drift`. `is_overridden` is now runtime vs schema
    default, because that is the question the agent is really asking: is this knob
    running something other than what the code ships?

    Top-level `drift_count` is the headline. `_retired` knobs are shown, not
    hidden - a retired knob still carries tuning history someone can misread as
    live, and the honest fix is to label it, not to disappear it.

    Shape:
      {
        "snapshot_at": iso, "knob_count": int, "overridden_count": int,
        "drift_count": int, "drifted": [names],
        "knobs": {"NAME": {file_value, runtime_value, schema_default,
                           module_const, is_overridden, drift[], role,
                           expires_at, unit}},
        "retired": {"NAME": {value, retired_at, note}},
      }
    """
    snapshot: dict = {
        "snapshot_at": _now_iso(),
        "knob_count": 0,
        "overridden_count": 0,
        "drift_count": 0,
        "drifted": [],
        "knobs": {},
        "_doc": ("file_value is what is written down. runtime_value is what the loops "
                 "get. When they differ, runtime_value is the truth and the file has "
                 "not been reloaded. Only MCAP_FLOOR_USD (role hard_prepacket) can stop "
                 "a packet existing; every other role here grades, it does not block."),
    }

    data = load_filter_file()
    if data is None:
        snapshot["error"] = "filter_file_missing_or_invalid"
        return snapshot

    knobs = data.get("knobs") or {}
    snapshot["knob_count"] = len(knobs)
    _g = globals()

    for knob_name, knob in knobs.items():
        if not isinstance(knob, dict):
            continue
        file_value = knob.get("value")
        spec = TUNABLE_PARAMS.get(knob_name) or {}
        schema_default = spec.get("default", None)
        has_schema = knob_name in TUNABLE_PARAMS

        runtime_value = get_override_sync(knob_name, _DRIFT_SENTINEL)
        runtime_missing = runtime_value is _DRIFT_SENTINEL
        if runtime_missing:
            # No entry in _ACTIVE_OVERRIDES: the loops fall through to whatever
            # fallback the callsite passes, which is the module const.
            runtime_value = _g.get(knob_name)

        _const = _g.get(knob_name)
        module_const = _const if isinstance(_const, (int, float, bool)) else None

        drift = []
        if file_value != runtime_value:
            drift.append("file_vs_runtime" + ("_not_loaded" if runtime_missing else ""))
        if has_schema and runtime_value != schema_default:
            drift.append("runtime_vs_schema_default")
        if module_const is not None and has_schema and schema_default != module_const:
            drift.append("schema_default_vs_module_const")
        if module_const is not None and file_value != module_const:
            drift.append("file_vs_module_const")
        _cdd = knob.get("code_default_drift")
        if isinstance(_cdd, dict) and not _cdd.get("resolved"):
            drift.append("stale_code_default_in_file")

        is_overridden = bool(has_schema and runtime_value != schema_default)
        if is_overridden:
            snapshot["overridden_count"] += 1
        if drift:
            snapshot["drift_count"] += 1
            snapshot["drifted"].append(knob_name)

        snapshot["knobs"][knob_name] = {
            "file_value": file_value,
            "runtime_value": runtime_value,
            "runtime_loaded": not runtime_missing,
            "schema_default": schema_default if has_schema else None,
            "module_const": module_const,
            "is_overridden": is_overridden,
            "drift": drift,
            "role": _knob_role(knob_name),
            "expires_at": knob.get("expires_at"),
            "unit": knob.get("unit"),
        }

    # Retired knobs stay visible. _retired.SCAN_TICK_OFFHOURS_SECONDS still
    # describes "off-hours and weekends" behaviour the code deleted, and any
    # reader walking the whole json without skipping this block reads it as live.
    _ret = data.get("_retired") or {}
    if isinstance(_ret, dict) and _ret:
        snapshot["retired"] = {
            k: {
                "value": (v.get("value") if isinstance(v, dict) else None),
                "retired_at": (v.get("retired_at") if isinstance(v, dict) else None),
                "note": ("RETIRED - the code no longer has this knob. History kept as "
                         "evidence. It is NOT live and must never be quoted as config."),
            }
            for k, v in _ret.items()
        }

    return snapshot


def compute_hardcoded_checks(token_data: dict, *, wallet_floor_active: bool = False) -> dict:
    """v13.1 Drop 2: per-token hardcoded floor check block for packet context.

    This is a DISPLAY block. It rejects nothing. The builder decides what gets a
    packet; this tells the agent what the floors said about the token in front of him.
    `rejects_packet: false` is stamped on the block so nobody reads a fail here as
    "the scanner blocked it."

    Floors:
      1. bonded_dexid: dexId in BONDED_DEXIDS_ALLOWED
      2. freeze_authority_null: token's freeze authority is null
      3. mint_authority_null:   token's mint authority is null
      4. wallet_floor_active:   if True, no buy can fire regardless of token quality

    ── FIX 5 (2026-08-15): A SHRUG WEARING A BADGE ─────────────────────────────
    Checks 2 and 3 read `fa is None` and called it a PASS. But `None` is what you
    get when the rug_check never ran, when the RPC call failed, and when the key
    simply is not in the dict — the same value that means "verified null, no
    freeze authority, safe." So a token nobody had checked displayed identically
    to a token that had been checked and cleared, and `all_pass` went true on
    both. That is not a floor. Absence of evidence was being rendered as evidence
    of absence, on the two checks that exist to stop honeypots and mint-rugs.

    Now: pass requires an EXPLICIT null (the authority was looked at and was
    empty). No key, or a key nobody populated, returns status `not_evaluated`
    with `pass: null` — a third state, not a fake pass — and `all_pass` is false
    while any check is unevaluated. `evaluated_count` and `not_evaluated` are
    surfaced so the gap is countable rather than inferred.

    The tell is NOT key presence — smart_check always ships both keys, defaulted
    to None before the RPC is even attempted. The receipt is
    rug_check.layers.token_2022: "pass"/"block" means the mint account was read,
    "error" (or no rug_check at all) means it was not. See the note at the check.

    ── FIX 7 (2026-08-15) ──────────────────────────────────────────────────────
    The old docstring called all four "NEVER tunable." Three are. The wallet floor
    NUMBER is a knob (WALLET_FLOOR_SOL, in TUNABLE_PARAMS, resolved through
    get_override_sync at every read site). What cannot be turned off is that a
    floor exists at all — sells must always be fundable.

    Returns:
      {
        "all_pass": bool,
        "rejects_packet": False,
        "evaluated_count": int, "not_evaluated": [str, ...],
        "checks": {
          "<name>": {"pass": bool|None, "status": "pass"|"fail"|"not_evaluated",
                     "value": ..., "blocker": str|None},
          ...
        }
      }
    """
    checks: dict = {}
    
    # Check 1: bonded dexId
    dex_id = (token_data.get("dexId") or "").lower() if isinstance(token_data, dict) else ""
    if not dex_id:
        # Try nested pair location
        pair = (token_data.get("pair") or {}) if isinstance(token_data, dict) else {}
        dex_id = (pair.get("dexId") or "").lower()
    bonded_pass = bool(dex_id) and dex_id in BONDED_DEXIDS_ALLOWED
    checks["bonded_dexid"] = {
        "pass": bonded_pass,
        "status": "pass" if bonded_pass else ("fail" if dex_id else "not_evaluated"),
        "value": dex_id or "unknown",
        "blocker": None if bonded_pass else (
            f"dexId '{dex_id}' not in allowed set {sorted(BONDED_DEXIDS_ALLOWED)}"
            if dex_id else
            "no dexId on this token — the venue was never read, so 'graduated to a real "
            "DEX' is unverified rather than failed"
        ),
    }
    
    # Check 2 & 3: freeze + mint authorities (read from token_data if present)
    # These come from get_mint_account_info() upstream and are usually nested
    # in a rug_check block or set directly on token_data.
    # FIX 5: _MISSING separates "we looked and it was null" (a real pass) from
    # "the key was not there" (nothing was checked). Both used to arrive as None.
    # WHERE THE TELL ACTUALLY IS. The obvious fix — "missing key means unchecked"
    # — would have fixed nothing here, because the key is NEVER missing.
    # smart_check() initialises `freeze_authority = None` and `mint_authority =
    # None` at the top, calls get_mint_account_info(mint), and only overwrites
    # them if that call returned something. When the RPC fails it returns falsy,
    # both stay None, and the result dict still ships both keys. So a token whose
    # authorities were never read is byte-identical, at this layer, to a token
    # that was read and came back clean.
    #
    # The one place the difference survives is `rug_check["layers"]["token_2022"]`,
    # which smart_check sets to "pass" / "block" when mint_info came back and to
    # "error" when it did not. That layer is the receipt for the read. Absent
    # rug_check, absent layers, or an "error" layer all mean the same thing:
    # nobody looked.
    td = token_data if isinstance(token_data, dict) else {}
    rc = td.get("rug_check") if isinstance(td.get("rug_check"), dict) else {}
    _layers = rc.get("layers") if isinstance(rc.get("layers"), dict) else {}
    _mint_layer = _layers.get("token_2022")

    def _authority(key):
        if key in td and td[key] is not None:
            return td[key]
        return rc.get(key)

    def _authority_check(val, label):
        # A truthy authority is self-proving: you cannot read a real pubkey off a
        # call that never happened. Everything else needs the receipt.
        _read = bool(val) or _mint_layer in ("pass", "block")
        if not _read:
            return {
                "pass": None,
                "status": "not_evaluated",
                "value": None,
                "blocker": (f"{label} was never read for this token — the mint-account "
                            f"lookup did not return (rug_check layer token_2022="
                            f"{_mint_layer!r}). This is UNKNOWN, not null. It used to "
                            f"display as a pass."),
                "evidence": {"token_2022_layer": _mint_layer},
            }
        ok = (val is None or val == "null" or val == "" or val is False)
        return {
            "pass": ok,
            "status": "pass" if ok else "fail",
            "value": val,
            "blocker": None if ok else f"{label} present: {val}",
            "evidence": {"token_2022_layer": _mint_layer},
        }

    checks["freeze_authority_null"] = _authority_check(_authority("freeze_authority"),
                                                        "freeze_authority")
    checks["mint_authority_null"] = _authority_check(_authority("mint_authority"),
                                                      "mint_authority")
    
    # Check 4: wallet floor — passed-in by caller from is_wallet_above_floor
    checks["wallet_floor_active"] = {
        "pass": not wallet_floor_active,
        "status": "fail" if wallet_floor_active else "pass",
        "value": wallet_floor_active,
        "blocker": None if not wallet_floor_active else "wallet at or below WALLET_FLOOR_SOL — buys suppressed",
    }

    # FIX 5: an unevaluated check is not a passing check. `all_pass` is only true
    # when every floor was actually looked at AND cleared.
    _unevaluated = [k for k, c in checks.items() if c.get("status") == "not_evaluated"]
    all_pass = (not _unevaluated) and all(c["pass"] is True for c in checks.values())

    return {
        "all_pass": all_pass,
        "rejects_packet": False,
        "evaluated_count": len(checks) - len(_unevaluated),
        "not_evaluated": _unevaluated,
        "checks": checks,
        "_doc": (
            "DISPLAY ONLY — nothing here rejects a packet; the builder already decided. "
            "Bonded dexId enforces 'graduated to a real DEX' (excludes pre-graduation "
            "launchpads). Authority nulls prevent honeypots and mint-rugs. The wallet "
            "floor protects sell-side liquidity: the floor's EXISTENCE is immovable, its "
            "NUMBER is the tunable WALLET_FLOOR_SOL. A check reading `not_evaluated` was "
            "never run — treat it as unknown, never as clean."
        ),
    }


def compute_drop2_filter_results(token: dict, holders_data: Optional[dict] = None,
                                   lp_lock_data: Optional[dict] = None,
                                   age_minutes: Optional[float] = None) -> dict:
    """v13.1 Drop 2: evaluate every Drop 2 tunable against the token data.
    
    Returns a dict of {knob_name: {pass: bool, actual: value, threshold: value,
    blocker: str|None}} for ALL Drop 2 knobs. Used by build_meme_candidate_packet
    to populate the per-packet drop2_filters block.
    
    NOTE: this is advisory. The PRE-PACKET hard filter is still just MCAP_FLOOR_USD.
    These knobs surface per-token pass/fail without blocking the packet.
    """
    results: dict = {}
    
    # Holder distribution
    holder_count = (holders_data or {}).get("holder_count")
    top10_pct = (holders_data or {}).get("top10_pct")
    dev_pct = (holders_data or {}).get("dev_holding_pct")
    
    hmin = get_override_sync("HOLDERS_MIN_COUNT", HOLDERS_MIN_COUNT)
    h_pass = (holder_count is None) or (holder_count >= hmin)
    results["HOLDERS_MIN_COUNT"] = {
        "pass": h_pass, "actual": holder_count, "threshold": hmin,
        "blocker": None if h_pass else f"holder_count {holder_count} < {hmin}",
    }
    
    t10_max = get_override_sync("TOP10_MAX_PCT", TOP10_MAX_PCT)
    t10_pass = (top10_pct is None) or (top10_pct <= t10_max)
    results["TOP10_MAX_PCT"] = {
        "pass": t10_pass, "actual": top10_pct, "threshold": t10_max,
        "blocker": None if t10_pass else f"top10_pct {top10_pct} > {t10_max}",
    }
    
    dev_max = get_override_sync("DEV_MAX_HOLDING_PCT", DEV_MAX_HOLDING_PCT)
    dev_pass = (dev_pct is None) or (dev_pct <= dev_max)
    results["DEV_MAX_HOLDING_PCT"] = {
        "pass": dev_pass, "actual": dev_pct, "threshold": dev_max,
        "blocker": None if dev_pass else f"dev_holding_pct {dev_pct} > {dev_max}",
    }
    
    # Time bonded window
    tb_min = get_override_sync("TIME_BONDED_MIN_MINUTES", TIME_BONDED_MIN_MINUTES)
    tb_max = get_override_sync("TIME_BONDED_MAX_MINUTES", TIME_BONDED_MAX_MINUTES)
    if age_minutes is None:
        tb_pass = True
        tb_blocker = None
    elif age_minutes < tb_min:
        tb_pass = False
        tb_blocker = f"age {age_minutes:.1f}min < min {tb_min}min"
    elif age_minutes > tb_max:
        tb_pass = False
        tb_blocker = f"age {age_minutes:.1f}min > max {tb_max}min"
    else:
        tb_pass = True
        tb_blocker = None
    results["TIME_BONDED_WINDOW"] = {
        "pass": tb_pass,
        "actual": age_minutes,
        "threshold": {"min": tb_min, "max": tb_max},
        "blocker": tb_blocker,
    }
    
    # LP lock (advisory)
    lp_pct = (lp_lock_data or {}).get("lp_locked_pct")
    lp_min = get_override_sync("LP_LOCKED_MIN_PCT", LP_LOCKED_MIN_PCT)
    lp_pass = (lp_pct is None) or (lp_pct >= lp_min) or (lp_min == 0.0)
    results["LP_LOCKED_MIN_PCT"] = {
        "pass": lp_pass, "actual": lp_pct, "threshold": lp_min,
        "blocker": None if lp_pass else f"lp_locked_pct {lp_pct} < {lp_min}",
    }
    
    # Volume / liquidity ratios
    liq = float(token.get("liquidity_usd", 0) or 0)
    vol_5m = float(token.get("volume_5m", 0) or 0)
    vol_1h = float(token.get("volume_1h", 0) or 0)
    
    vl5_ratio = (vol_5m / liq) if liq > 0 else 0
    vl5_min = get_override_sync("VOL_LIQ_5M_MIN", VOL_LIQ_5M_MIN)
    vl5_pass = vl5_ratio >= vl5_min
    results["VOL_LIQ_5M_MIN"] = {
        "pass": vl5_pass, "actual": round(vl5_ratio, 2), "threshold": vl5_min,
        "blocker": None if vl5_pass else f"vol_liq_5m {vl5_ratio:.2f} < {vl5_min}",
    }
    
    vl1h_ratio = (vol_1h / liq) if liq > 0 else 0
    vl1h_min = get_override_sync("VOL_LIQ_1H_MIN", VOL_LIQ_1H_MIN)
    vl1h_pass = vl1h_ratio >= vl1h_min
    results["VOL_LIQ_1H_MIN"] = {
        "pass": vl1h_pass, "actual": round(vl1h_ratio, 2), "threshold": vl1h_min,
        "blocker": None if vl1h_pass else f"vol_liq_1h {vl1h_ratio:.2f} < {vl1h_min}",
    }
    
    # Price-change windows
    pc_5m = float(token.get("price_change_5m", 0) or 0)
    pc5_min = get_override_sync("PRICE_CHANGE_5M_MIN", PRICE_CHANGE_5M_MIN)
    pc5_pass = pc_5m >= pc5_min
    results["PRICE_CHANGE_5M_MIN"] = {
        "pass": pc5_pass, "actual": pc_5m, "threshold": pc5_min,
        "blocker": None if pc5_pass else f"price_change_5m {pc_5m} < {pc5_min}",
    }
    
    pc_24h = float(token.get("price_change_24h", 0) or 0)
    pc24_min = get_override_sync("PRICE_CHANGE_24H_MIN", PRICE_CHANGE_24H_MIN)
    pc24_pass = pc_24h >= pc24_min
    results["PRICE_CHANGE_24H_MIN"] = {
        "pass": pc24_pass, "actual": pc_24h, "threshold": pc24_min,
        "blocker": None if pc24_pass else f"price_change_24h {pc_24h} < {pc24_min}",
    }
    
    # Social floors
    tw_followers = int(token.get("twitter_followers", 0) or 0)
    tw_min = get_override_sync("TWITTER_FOLLOWERS_MIN", TWITTER_FOLLOWERS_MIN)
    tw_pass = tw_followers >= tw_min
    results["TWITTER_FOLLOWERS_MIN"] = {
        "pass": tw_pass, "actual": tw_followers, "threshold": tw_min,
        "blocker": None if tw_pass else f"twitter_followers {tw_followers} < {tw_min}",
    }
    
    tg_members = int(token.get("telegram_members", 0) or 0)
    tg_min = get_override_sync("TELEGRAM_MEMBERS_MIN", TELEGRAM_MEMBERS_MIN)
    tg_pass = tg_members >= tg_min
    results["TELEGRAM_MEMBERS_MIN"] = {
        "pass": tg_pass, "actual": tg_members, "threshold": tg_min,
        "blocker": None if tg_pass else f"telegram_members {tg_members} < {tg_min}",
    }
    
    x_age_days = token.get("x_account_age_days")
    x_age_min = get_override_sync("X_ACCOUNT_AGE_MIN_DAYS", X_ACCOUNT_AGE_MIN_DAYS)
    x_age_pass = (x_age_days is None and x_age_min == 0) or (x_age_days is not None and x_age_days >= x_age_min)
    results["X_ACCOUNT_AGE_MIN_DAYS"] = {
        "pass": x_age_pass, "actual": x_age_days, "threshold": x_age_min,
        "blocker": None if x_age_pass else f"x_account_age_days {x_age_days} < {x_age_min}",
    }
    
    # Meta alignment
    require_meta = get_override_sync("REQUIRE_META_ALIGNMENT", REQUIRE_META_ALIGNMENT)
    meta_aligned = bool(token.get("meta_alignment", False))
    meta_pass = (not require_meta) or meta_aligned
    results["REQUIRE_META_ALIGNMENT"] = {
        "pass": meta_pass, "actual": meta_aligned, "threshold": require_meta,
        "blocker": None if meta_pass else "REQUIRE_META_ALIGNMENT=True but token not meta-aligned",
    }
    
    # Overall summary
    all_pass = all(r["pass"] for r in results.values())
    pass_count = sum(1 for r in results.values() if r["pass"])
    
    return {
        "all_pass": all_pass,
        "pass_count": pass_count,
        "total_count": len(results),
        "results": results,
        "_doc": (
            "Per-token Drop 2 filter results. ADVISORY ONLY — the only pre-packet "
            "hard filter is MCAP_FLOOR_USD. These knobs surface per-token state "
            "without blocking the packet. The agent reads this to weigh which gates "
            "matter for his decision."
        ),
    }


def compute_edge_filter(token: dict) -> dict:
    """
    Compute edge_filter block for a meme_candidate packet.
    Returns the full structure documented in architecture doc section 2.1.
    """
    liq = float(token.get("liquidity_usd", 0) or 0)
    mcap = float(token.get("mcap", 0) or 0)
    vol_24h = float(token.get("volume_24h", 0) or 0)
    price_change_1h = float(token.get("price_change_1h", 0) or 0)
    meta = (token.get("narrative") or "").lower()
    twitter_followers = int(token.get("twitter_followers", 0) or 0)
    x_account_age_days = token.get("x_account_age_days")
    boost_count = int(token.get("boost_count", 0) or 0)
    tg_members = token.get("telegram_members") or 0
    x_dex_paid = bool(token.get("x_dex_paid", False))
    meta_alignment = bool(token.get("meta_alignment", False))
    
    x_quality = _classify_x_quality(twitter_followers, x_account_age_days)
    
    # Sprint 32: edge thresholds tunable via meeting overrides
    edge_liq_min = get_override_sync("EDGE_LIQ_MIN_USD", EDGE_LIQ_MIN_USD)
    edge_liq_max = get_override_sync("EDGE_LIQ_MAX_USD", EDGE_LIQ_MAX_USD)
    edge_mcap_min = get_override_sync("EDGE_MCAP_MIN_USD", EDGE_MCAP_MIN_USD)
    edge_mcap_max = get_override_sync("EDGE_MCAP_MAX_USD", EDGE_MCAP_MAX_USD)
    edge_vol_liq_min = get_override_sync("EDGE_VOL_LIQ_RATIO_MIN", EDGE_VOL_LIQ_RATIO_MIN)
    
    # Hard gates
    gate_liq = edge_liq_min <= liq <= edge_liq_max
    gate_mcap = edge_mcap_min <= mcap <= edge_mcap_max
    vol_liq_ratio = (vol_24h / liq) if liq > 0 else 0
    gate_vol_liq = vol_liq_ratio >= edge_vol_liq_min
    # FIX 2026-07-27: this read the MODULE CONSTANT (0.0), never the filter file.
    # The agent tuned this knob twice — 0.0 -> -5.0 (2026-07-17) -> -15.0 (2026-07-21)
    # — and the file recorded both as applied while the gate kept using 0.0. His
    # own second entry says "meeting no-op at -5": he watched the first change do
    # nothing and concluded he hadn't gone far enough, when the pipe was never
    # connected. Every other edge knob here resolves via get_override_sync; this
    # one was missed.
    edge_pc1h_min = get_override_sync("EDGE_PRICE_CHANGE_1H_MIN", EDGE_PRICE_CHANGE_1H_MIN)
    gate_price = price_change_1h >= edge_pc1h_min
    gate_meta = meta not in EDGE_META_AVOID
    # The agent's jimothy audit #4 (2026-07-23): "under geo heat that gate is too
    # blunt — geo/war memes can print in panic; hard FAIL is too blunt when
    # structure is clean." SOFT-GATE: in a fear tape (Panic/Capitulation phase),
    # a political/food meta becomes a FLAGGED PASS — the packet says loudly that
    # the frozen edge gate objects, structure decides, override lane is his.
    _meta_softened = False
    if not gate_meta:
        try:
            _dr = load_daily_read_sniper() or {}
            _phase = (_dr.get("current_phase") or "").lower()
            if _phase in ("panic", "capitulation", "anger", "depression"):
                gate_meta = True
                _meta_softened = True
        except Exception:
            pass
    gate_x_quality = x_quality not in EDGE_X_QUALITY_AVOID
    
    # ── A1 (2026-08-08): LIQUIDITY IS OFF THE HARD-GATE PATH ────────────────
    # TOAD receipt: liq $18.6K against a $20K min - a $1.4K miss - scored the
    # whole token 2.0 and stamped it below_edge_floor. It printed ~143x.
    #
    # The 20-50k band was never the owner's rule. His ONLY hard floor is
    # MCAP_FLOOR_USD $10k. The band is autopsy fossil from a March-April
    # reference table that got labelled "the owner's edge filter" and hardened into a
    # gate nobody authorised. The code's own comments call edge advisory; the
    # scorer and the vibe copy treated it as a floor, and the desk believed the
    # stamp.
    #
    # Values are NOT widened - deliberately. An earlier draft proposed 15k-250k
    # and the spec's own correction says that was the agent's draft, not an owner
    # order. Swapping one unauthorised number for another would repeat the
    # mistake. Liq simply stops being able to fail anything.
    hard_gates = {
        "mcap_in_range_30k_1M": {"pass": gate_mcap, "value": f"${mcap/1000:.1f}K" if mcap < 1_000_000 else f"${mcap/1_000_000:.2f}M"},
        "vol_liq_ratio_6x": {"pass": gate_vol_liq, "value": f"{vol_liq_ratio:.1f}x"},
        "price_change_1h_pos": {"pass": gate_price, "value": f"{price_change_1h:+.1f}%"},
        "meta_not_political_food": {"pass": gate_meta,
                                      "value": ((meta or "unknown") + (" ⚠ SOFT-FLAGGED: political/food in a fear tape — "
                                                 "the frozen edge gate objects but does NOT auto-kill (geo memes print in panic). "
                                                 "Structure decides; this is your override lane, use it or decline it in words.")
                                                 if _meta_softened else (meta or "unknown")),
                                      "soft_flagged": _meta_softened},
        "x_quality_not_established": {"pass": gate_x_quality, "value": x_quality},
    }

    # Liquidity, demoted to information. Kept visible because it is real
    # structure the agent should weigh - it just never votes.
    soft_signals = {
        "liq_usd": liq,
        "liq_display": (f"${liq/1000:.1f}K" if liq > 0 else "$0"),
        "liq_note": ("info only - not a pass/fail gate. The owner's only hard floor is "
                     "mcap >= MCAP_FLOOR_USD. A thin book is an exit-physics "
                     "question, not a veto."),
        "legacy_autopsy_liq_band_20_50k": {
            "in_band": bool(edge_liq_min <= liq <= edge_liq_max),
            "value": (f"${liq/1000:.1f}K" if liq > 0 else "$0"),
            "band": f"${edge_liq_min/1000:.0f}K-${edge_liq_max/1000:.0f}K",
            "_note": ("legacy autopsy reference, soft / unused for FAIL. Retained for "
                      "display stats only so historical comparisons still line up."),
        },
    }
    
    # RELOCATED (2026-07-23 field fix — KeyError 'pass': this block lived INSIDE
    # hard_gates, whose every entry must carry a "pass" key for the gate
    # iterators; an info block is not a gate. Blocked every candidate packet
    # until caught. A dict's shape is a contract; siblings, not tenants.
    extended_early_block = (lambda _h24: (
            {"detected": True,
              "trigger": f"early band + {_h24:+.0f}% 24h — already vertical",
              "doctrine": ("the agent's jimothy audit #5 (2026-07-23): mcap still early-band but "
                            "the move already happened. This is NEITHER a fresh snipe NOR an "
                            "auto-ignore — it's a THIRD trade with its own rules:"),
              "reclaim_rules": [
                  "do NOT chase the vertical — no market entry into a live god-candle",
                  "wait for the first real pullback (≥25-35% off the local high)",
                  "entry = RECLAIM of the pullback high, or a confirmed higher-low",
                  "invalidation = clean break below the pullback low — tight, honored",
                  "flip-mode default, small size; hold only if it keeps proving itself",
              ],
              "note": "an offer, not a verdict — the edge gates below still speak; this lane "
                       "exists so 'already +500%' stops meaning 'pretend you never saw it'"}
            if (_h24 is not None and _h24 >= 300 and mcap < 1_000_000) else {"detected": False}
        ))(_safe_num(token.get("price_change_24h")))
    # ── FIX 6 (2026-08-15): THE NAME IS A LIE THE CONSUMERS DEPEND ON ────────
    # These are reference gates. None of them rejects a packet — the sole hard
    # pre-packet floor in this bot is MCAP_FLOOR_USD, and the builder applies it
    # long before here. But `hard_gates` is read by name in five places
    # (entry_context.scan_hard_gates is written into position history and read
    # back by the autopsy comparators), so renaming the key would break history
    # that already exists on disk. A dict's shape is a contract.
    #
    # So the correction goes INSIDE each entry instead of on the dict: every gate
    # says out loud that it does not block. `blocks_packet` is additive — the
    # iterators read `pass` and are untouched.
    for _g in hard_gates.values():
        _g["blocks_packet"] = False
    hard_gates_doc = (
        "REFERENCE gates, not kill switches. A False here is a grade, not a rejection: "
        "the packet you are reading exists BECAUSE nothing here can stop it. The only "
        "hard pre-packet floor is MCAP_FLOOR_USD. Liquidity is not in this dict at all "
        "(A1, 2026-08-08) — see soft_signals."
    )
    passes_full_filter = all(g["pass"] for g in hard_gates.values())

    # A4: an mcap band miss is advisory, not a kill frame. `pass` stays False so
    # autopsy stats remain honest - the graded score carries the quality.
    if not hard_gates["mcap_in_range_30k_1M"]["pass"]:
        hard_gates["mcap_in_range_30k_1M"]["soft_flagged"] = True
        hard_gates["mcap_in_range_30k_1M"]["note"] = (
            "advisory band miss - structure may still be tradeable; the agent weighs, "
            "not auto-kill. The owner's only hard floor is MCAP_FLOOR_USD.")
    
    # Bonuses
    bonuses = []
    if boost_count >= 100:
        bonuses.append({"name": "boost_count_100+", "value": boost_count, "weight_multiplier": 1.5})
    elif boost_count >= 30:
        bonuses.append({"name": "boost_count_30+", "value": boost_count, "weight_multiplier": 1.2})
    if 50 <= tg_members <= 199:
        bonuses.append({"name": "tg_50_199_members", "value": tg_members, "weight_multiplier": 1.15})
    
    # Unicorn combo (4/4 wins per autopsy data)
    unicorn = x_dex_paid and meta_alignment
    
    # Time-of-day window
    now = datetime.now(EST)
    hour = now.hour
    if 14 <= hour < 16:
        time_window = "best"
    elif 3 <= hour < 6:
        time_window = "worst"
    else:
        time_window = "neutral"
    
    # ── A2 (2026-08-08): GRADED SCORE REPLACES THE BINARY CLIFF ─────────────
    # Was: pass-everything -> 7.0, otherwise 2.0. So one gate short of perfect
    # scored the same as total garbage, and a near-miss scored the same as a
    # hard fail. TOAD went 5/6 with elite 11.7x vol/liq and got 2.0.
    #
    # The owner's law: memes are never 10/10 pretty. The gates are a SIZE LADDER, not
    # a buy veto. 3/6 and 5/6 can still be buys; 6/6 is size-up, not permission.
    # So the score has to carry structure QUALITY continuously instead of
    # collapsing it to two values.
    NEAR_MISS_FRAC = 0.15      # within 15% of a boundary = near miss, 0.6 credit

    def _gate_credit(passed: bool, near_miss: bool) -> float:
        if passed:
            return 1.0
        return 0.6 if near_miss else 0.0

    # Per-gate near-miss tests. meta and x_quality are categorical - there is no
    # "almost the right meta", so they stay binary rather than inventing a
    # fractional credit that would mean nothing.
    _nm_mcap = (not gate_mcap) and (
        edge_mcap_min * (1 - NEAR_MISS_FRAC) <= mcap <= edge_mcap_max * (1 + NEAR_MISS_FRAC))
    _nm_vol_liq = (not gate_vol_liq) and (vol_liq_ratio >= edge_vol_liq_min * 0.85)
    # price: near-miss only when the threshold is non-zero. With min 0 the gate is
    # "is it green at all", and there is no meaningful almost-green.
    _nm_price = (not gate_price) and edge_pc1h_min != 0 and (
        price_change_1h >= edge_pc1h_min - abs(edge_pc1h_min) * NEAR_MISS_FRAC)

    credits = {
        "mcap_in_range_30k_1M":     _gate_credit(gate_mcap, _nm_mcap),
        "vol_liq_ratio_6x":         _gate_credit(gate_vol_liq, _nm_vol_liq),
        "price_change_1h_pos":      _gate_credit(gate_price, _nm_price),
        "meta_not_political_food":  _gate_credit(gate_meta, False),
        "x_quality_not_established": _gate_credit(gate_x_quality, False),
    }
    near_misses = [k for k, (g, nm) in {
        "mcap_in_range_30k_1M": (gate_mcap, _nm_mcap),
        "vol_liq_ratio_6x": (gate_vol_liq, _nm_vol_liq),
        "price_change_1h_pos": (gate_price, _nm_price),
    }.items() if (not g) and nm]

    credit_sum = sum(credits.values())
    credit_frac = (credit_sum / float(len(credits))) if credits else 0.0

    # 5/5 -> 7.0 base, 0/5 -> 1.0. A near-miss lands between, which is the point.
    edge_score = 1.0 + 6.0 * credit_frac
    if unicorn:
        edge_score += 2.0 if credit_frac >= 0.99 else 1.0
    for b in bonuses:
        # Bonuses scale with structure so a bonus cannot carry a weak book, but a
        # mixed book still gets partial credit for one.
        edge_score += (b["weight_multiplier"] - 1.0) * max(credit_frac, 0.5)
    if time_window == "best":
        edge_score += 0.5
    elif time_window == "worst":
        edge_score -= 1.0

    structure_quality = ("full" if credit_frac >= 0.99 else
                         "strong" if credit_frac >= 0.8 else
                         "mixed" if credit_frac >= 0.5 else
                         "weak")

    # META_ALIGNMENT_WEIGHT — FINISHED 2026-07-27. The knob shipped in the filter
    # file describing itself as an "edge-score multiplier for meta-aligned tokens"
    # and NOTHING read it: the bonus was specced, exposed as tunable, and never
    # applied. Default 1.0 is a no-op, so this changes nothing until the owner or
    # The agent raises it — which is exactly what the knob always claimed to do.
    _meta_w = float(get_override_sync("META_ALIGNMENT_WEIGHT", META_ALIGNMENT_WEIGHT) or 1.0)
    if _meta_w != 1.0 and bool(token.get("meta_alignment", False)):
        edge_score = min(10.0, edge_score * _meta_w)

    edge_score = max(0.0, min(10.0, edge_score))
    
    # Verdict
    if passes_full_filter and unicorn:
        verdict = "STRONG PASS , all gates clean + unicorn combo (x_dex_paid + meta_alignment)"
    elif passes_full_filter:
        bonus_summary = f", +{len(bonuses)} bonuses" if bonuses else ""
        verdict = f"PASS , all gates clean{bonus_summary}"
    else:
        failed = [k for k, g in hard_gates.items() if not g["pass"]]
        # A3: PARTIAL is a real verdict. A 5/6 near-miss is not a FAIL, and
        # stamping it as one is what trained the desk to read advisory structure
        # as a kill. FAIL is reserved for genuinely weak books.
        if credit_frac >= 0.5:
            _fon = failed + [f"{k} (near)" for k in near_misses if k not in failed]
            verdict = (f"PARTIAL {credit_sum:.1f}/{len(credits)} , "
                       f"{', '.join(_fon[:3])}"
                       + (f" +{len(_fon)-3} more" if len(_fon) > 3 else ""))
        else:
            verdict = f"FAIL , {', '.join(failed[:3])}" + (f" +{len(failed)-3} more" if len(failed) > 3 else "")
    
    # ── Sprint 53: THE CONTINUATION BAND (the agent's #4) ──────────────────────────
    # The early band (30k-1M) stays STRICT and unchanged — that's the snipe edge and
    # loosening it would wreck it. But a token at 1M-10M isn't automatically garbage;
    # it's a DIFFERENT trade: a continuation/midcap play with a slower thesis, smaller
    # size, and its own rules. Previously these just failed mcap_in_range and fell out
    # of the funnel entirely, which is why branded runners (the $febu class) were never
    # even considered.
    #
    # So: classify the band. A midcap does NOT "pass the early filter" (it can't, by
    # design) — it gets its own verdict and its own playbook. Watch-first, never a
    # reflex snipe. This adds a lane; it does not raise the ceiling.
    CONTINUATION_MCAP_MIN = get_override_sync("CONTINUATION_MCAP_MIN_USD", 1_000_000)
    CONTINUATION_MCAP_MAX = get_override_sync("CONTINUATION_MCAP_MAX_USD", 10_000_000)

    if edge_mcap_min <= mcap <= edge_mcap_max:
        band = "early"
    elif CONTINUATION_MCAP_MIN <= mcap <= CONTINUATION_MCAP_MAX:
        band = "continuation"
    elif mcap < edge_mcap_min:
        band = "sub_early"      # below the floor — too small/unformed
    else:
        band = "post_runner"    # above continuation — the trade already happened

    # Continuation-band quality: the early gates that STILL matter for a midcap
    # (liquidity depth, real volume, not a dead chart), minus the ones that only make
    # sense for an early snipe (mcap band, x_quality-not-established — a real branded
    # midcap SHOULD have an established account; that's a feature, not a red flag).
    continuation_gates = None
    continuation_ok = False
    if band == "continuation":
        c_liq_ok  = liq >= edge_liq_min                     # depth floor only (no ceiling)
        c_vol_ok  = vol_liq_ratio >= edge_vol_liq_min       # real volume still required
        c_price_ok = price_change_1h >= get_override_sync(
            "EDGE_PRICE_CHANGE_1H_MIN", EDGE_PRICE_CHANGE_1H_MIN)   # was the raw constant
        c_meta_ok = meta not in EDGE_META_AVOID
        continuation_gates = {
            "liq_depth_floor":   {"pass": c_liq_ok,  "value": f"${liq/1000:.1f}K"},
            "vol_liq_ratio":     {"pass": c_vol_ok,  "value": f"{vol_liq_ratio:.1f}x"},
            "price_change_1h":   {"pass": c_price_ok,"value": f"{price_change_1h:+.1f}%"},
            "meta_ok":           {"pass": c_meta_ok, "value": meta or "unknown"},
        }
        continuation_ok = all(g["pass"] for g in continuation_gates.values())

    return {
        "_source": "owners_edge_v1",
        "_backtested_on": "100 autopsies, March-April 2026",
        "passes_full_filter": passes_full_filter,   # unchanged meaning: all hard gates pass
        "edge_score": round(edge_score, 1),
        # ── A3 graded fields (2026-08-08) ───────────────────────────────────
        # The binary pass/fail stays for back-compat, but these carry the truth a
        # single boolean cannot: HOW MUCH structure is there. potential_watch keys
        # off credit_sum, and the size ladder reads structure_quality.
        "gate_credits": {k: round(v, 2) for k, v in credits.items()},
        "credit_sum": round(credit_sum, 2),
        "credit_frac": round(credit_frac, 3),
        "near_misses": near_misses,
        "structure_quality": structure_quality,
        "soft_signals": soft_signals,
        "_size_ladder": (
            "6/6 full = SIZE-UP eligible (still needs dual-gate + map), not permission to buy. "
            "5/6 or strong = buy-eligible, probe/normal by map clarity. "
            "3/6 mixed = still buy-eligible if no non-edge hard kill; default probe; "
            "potential-watch it if you pass. <3/6 weak = skip on edge alone is reasonable. "
            "Liquidity NEVER auto-fails and is never a sole ignore thesis."),
        "hard_gates": hard_gates,
        "hard_gates_doc": hard_gates_doc,
        "extended_early": extended_early_block,
        "treasury": (_TREASURY_CACHE.get("summary") if _now_ts() - (_TREASURY_CACHE.get("at") or 0) < 7200 else None),
        "home_base": (_TREASURY_CACHE.get("home_base") if _now_ts() - (_TREASURY_CACHE.get("at") or 0) < 7200 else None),
        "bonuses_active": bonuses,
        "unicorn_combo": unicorn,
        "time_of_day_window": time_window,
        "owner_edge_verdict": verdict,
        # ── the band + continuation lane ──
        "band": band,
        "continuation_gates": continuation_gates,
        "continuation_ok": continuation_ok,
        "band_playbook": (
            "EARLY SNIPE — the strict edge band. Full gates apply. Normal probe sizing."
            if band == "early" else
            ("CONTINUATION / MIDCAP — a DIFFERENT trade, not a late snipe. WATCH-FIRST: "
             "do not reflex-buy. Requires brand proof (is this the canonical token, not a "
             "clone?), clean structure, and real liquidity depth. Size SMALLER than a probe, "
             "slower thesis, wider stop. The early-band gates (mcap range, x_quality) do NOT "
             "apply here — an established X account is a POSITIVE for a branded midcap. "
             "Under a panic regime: research + watch only, hard-block chase entries unless "
             "there's a clean reclaim + liquidity + brand proof."
             if band == "continuation" else
             ("SUB-EARLY — below the mcap floor. Unformed; no edge band applies."
              if band == "sub_early" else
              "POST-RUNNER — above the continuation ceiling. The move already happened; "
              "this is not an entry, it's a chase. Observe only."))
        ),
    }


# ═══════════════════════════════════════════════════════════════════════════
#                  COMMUNITY FORMATION DETECTION (Sprint 37 restore)
# ═══════════════════════════════════════════════════════════════════════════
# `is_community_formation` was once a hardcoded False in smart_rug_check's
# return. Restored as a proper signal in v12.2.
#
# What it detects: chart bottoming + sideways consolidation after a pump.
# Pattern signature:
#   - Pump occurred (price was at least 2x the current price recently)
#   - Current price is bottoming/consolidating (within 30% range over recent candles)
#   - Volume is NOT zero (humans still trading)
#   - Pattern sustained for at least 6 candles (sideways action, not just dump)
#
# Read: "the pump dumpers are out but a community is forming around the
# remaining holders." A bag-formation signal. Used by missed_runner observer
# to mark a missed runner as "community survived" — that's an even worse
# miss because the coin has staying power, not just hype.

def compute_community_formation(pair_data: dict) -> dict:
    """
    Detect community formation pattern from DexScreener pair data.

    Returns:
      {
        "is_community_formation": bool,
        "confidence":             float (0-1),
        "evidence":               list[str] (reasons that fired)
      }

    Conservative — false positives are bad here. Need multiple signals to fire.
    """
    evidence = []
    confidence = 0.0

    if not isinstance(pair_data, dict):
        return {
            "is_community_formation": False,
            "confidence": 0.0,
            "evidence":   ["no_pair_data"],
        }

    price_change = pair_data.get("priceChange") or {}
    volume = pair_data.get("volume") or {}
    liq_data = pair_data.get("liquidity") or {}
    liq_usd = liq_data.get("usd") or 0

    # ── Signal 1: bottomed from a recent pump ──
    # price_change_24h significantly negative = dumped from a high
    pc_24h = price_change.get("h24", 0) or 0
    pc_6h = price_change.get("h6", 0) or 0
    pc_1h = price_change.get("h1", 0) or 0
    pc_5m = price_change.get("m5", 0) or 0

    if pc_24h <= -50:
        evidence.append("dumped_50pct_plus_24h")
        confidence += 0.3
    elif pc_24h <= -30:
        evidence.append("dumped_30pct_plus_24h")
        confidence += 0.15

    # ── Signal 2: recent action is sideways (consolidation, not still dumping) ──
    # Last hour change within ±15%, last 5min within ±5% = stabilized
    if abs(pc_1h) <= 15 and abs(pc_5m) <= 5:
        evidence.append("sideways_1h_recent")
        confidence += 0.3
    elif abs(pc_6h) <= 30 and abs(pc_1h) <= 20:
        evidence.append("sideways_6h_loose")
        confidence += 0.15

    # ── Signal 3: still alive (volume not collapsed) ──
    vol_24h = volume.get("h24", 0) or 0
    vol_1h = volume.get("h1", 0) or 0
    if vol_24h >= COMMUNITY_FORMATION_MIN_VOLUME_24H_USD and vol_1h > 0:
        evidence.append("volume_alive")
        confidence += 0.2

    # ── Signal 4: liquidity hasn't been pulled ──
    if liq_usd >= 5000:
        evidence.append("liquidity_intact")
        confidence += 0.2

    # 2026-10-23: candles (attached by second wind) use the range/bottom-candle settings.
    _cd = pair_data.get("candles") or []
    if len(_cd) >= COMMUNITY_FORMATION_MIN_CANDLES_AT_BOTTOM:
        try:
            _tail = _cd[-COMMUNITY_FORMATION_MIN_CANDLES_AT_BOTTOM:]
            _lo = min(float(r[3]) for r in _tail)
            _hi = max(float(r[2]) for r in _tail)
            if _lo > 0 and (_hi - _lo) / _lo <= COMMUNITY_FORMATION_PRICE_RANGE_PCT:
                evidence.append(f"sideways_{COMMUNITY_FORMATION_MIN_CANDLES_AT_BOTTOM}h_base")
                confidence += 0.2
        except Exception:
            pass

    # Lock confidence to 0-1
    confidence = min(1.0, confidence)

    # Need 2+ signals AND at least one pump-bottom signal to call it
    is_formation = (
        confidence >= 0.5 and
        any(e.startswith("dumped_") for e in evidence) and
        any(e.startswith("sideways_") for e in evidence)
    )

    return {
        "is_community_formation": is_formation,
        "confidence":             round(confidence, 2),
        "evidence":               evidence,
    }


# ═══════════════════════════════════════════════════════════════════════════
#                       SMART RUG CHECK (in-process module)
# ═══════════════════════════════════════════════════════════════════════════

async def cluster_top_holders(mint: str, holders_data: Optional[dict]) -> dict:
    """Group top token accounts by owner, then by shared non-exchange funder.

    getTokenLargestAccounts returns token accounts, not wallets. Scoring those
    one by one is how a 4-wallet cluster looks clean. COINPUTER 2026-10-05:
    rug score 1, bundle 0, Trench 4 clusters / 71%.
    """
    empty = {
        "status": "unavailable", "clusters": [], "clustered_pct": 0.0,
        "largest_cluster_pct": 0.0, "cluster_count": 0, "gate": "unavailable",
        "owners_checked": 0,
    }
    if not holders_data or not holders_data.get("top_holders"):
        return empty
    rows = [h for h in (holders_data.get("top_holders") or [])[:20] if isinstance(h, dict)]
    addrs = [h.get("address") for h in rows if h.get("address")]
    if not addrs:
        return empty
    parsed = await helius_rpc("getMultipleAccounts", [addrs, {"encoding": "jsonParsed"}])
    values = (parsed or {}).get("value") if isinstance(parsed, dict) else None
    if not isinstance(values, list):
        return empty
    skip = {
        "1nc1nerator11111111111111111111111111111111",
        "11111111111111111111111111111111",
    }
    by_owner = {}
    for h, acc in zip(rows, values):
        try:
            info = (((acc or {}).get("data") or {}).get("parsed") or {}).get("info") or {}
            owner = info.get("owner")
        except Exception:
            owner = None
        if not owner or owner in skip or owner in _EXCHANGE_ANCHOR_BLOCKLIST:
            continue
        slot = by_owner.setdefault(owner, {"owner": owner, "pct": 0.0})
        slot["pct"] += float(h.get("pct") or 0)
    big = [v for v in by_owner.values() if v["pct"] >= 1.0]
    big.sort(key=lambda x: x["pct"], reverse=True)
    big = big[:6]
    if len(big) < 2:
        return {
            "status": "ok", "clusters": [], "clustered_pct": 0.0,
            "largest_cluster_pct": 0.0, "cluster_count": 0, "gate": "pass",
            "owners_checked": len(big),
            "note": "fewer than 2 owners above 1pct after dropping burn, pool, and cex",
        }
    for row in big:
        try:
            row["funder"] = await _identify_funder(row["owner"])
        except Exception:
            row["funder"] = None
    groups = {}
    for row in big:
        funder = row.get("funder")
        if not funder or funder in _EXCHANGE_ANCHOR_BLOCKLIST or funder in skip:
            continue
        groups.setdefault(funder, []).append(row)
    clusters = []
    for funder, members in groups.items():
        if len(members) < 2:
            continue
        pct = round(sum(m["pct"] for m in members), 2)
        clusters.append({
            "funder": funder,
            "pct": pct,
            "wallets": [{"owner": m["owner"], "pct": round(m["pct"], 2)} for m in members],
        })
    clusters.sort(key=lambda c: c["pct"], reverse=True)
    clustered = round(sum(c["pct"] for c in clusters), 2)
    largest = clusters[0]["pct"] if clusters else 0.0
    if clustered >= 60 or largest >= 60:
        gate = "block"
    elif clustered >= 40 or largest >= 25:
        gate = "caution"
    else:
        gate = "pass"
    return {
        "status": "ok",
        "clusters": clusters[:6],
        "clustered_pct": clustered,
        "largest_cluster_pct": largest,
        "cluster_count": len(clusters),
        "gate": gate,
        "owners_checked": len(big),
        "note": "shared non-exchange funder among top owners. cex funders are not clustered.",
    }


async def smart_rug_check(mint: str, holders_data: Optional[dict] = None, *, age_minutes: Optional[int] = None) -> dict:
    """
    Multi-layer rug check. Layered as DATA in packets.
    
    Verdict semantics (v11.1):
      - "block"   = TIER 4 SAFETY FAIL , never override (freeze_authority active,
                    honeypot detected, or rugcheck honeypot risk flagged)
      - "caution" = multiple WARN signals , the agent should think hard before entry
      - "clean"   = no significant safety issues
      - "data_unavailable" = too many layers errored out
    
    Age-aware: thresholds for top10_pct + bundler_mev scale with token age,
    because fresh tokens naturally have concentrated holders (everyone bought
    in the same first 5min).
    
    Layers:
      1. rugcheck     , api.rugcheck.xyz
      2. velocity     , price/volume/liq decay over 5min
      3. wallet_graph , top10 concentration (age-scaled)
      4. social_v_price , placeholder
      5. bundler_mev  , bundle detection (heuristic on similar holdings)
      6. dev_history  , placeholder
      7. token_2022   , freeze/mint authority (Tier 4 hard block)
    """
    layers = {
        "rugcheck": "pending",
        "velocity": "pending",
        "wallet_graph": "pending",
        "holder_clusters": "pending",
        "social_v_price": "pending",
        "bundler_mev": "pending",
        "dev_history": "pending",
        "token_2022": "pending",
    }
    
    rugcheck_score = 0
    is_token_2022 = False
    freeze_authority = None
    mint_authority = None
    bundle_score = 0
    bundle_wallets = 0
    
    # ── Layer 7 (run first , it can immediately produce a Tier 4 BLOCK) ──
    mint_info = await get_mint_account_info(mint)
    if mint_info:
        freeze_authority = mint_info.get("freezeAuthority")
        mint_authority = mint_info.get("mintAuthority")
        # Tier 4 hard fail: freeze_authority active = honeypot
        if freeze_authority:
            layers["token_2022"] = "block"
        # mint_authority active = dev can mint infinite supply
        elif mint_authority:
            layers["token_2022"] = "block"
        else:
            layers["token_2022"] = "pass"
    else:
        layers["token_2022"] = "error"
    
    # ── Layer 1: rugcheck.xyz ──
    # Age-aware: fresh tokens score high naturally; only treat as hard signal
    # for tokens past their initial chaos window (>2h old).
    # Sprint 29.7: thresholds now READ from dynamic_thresholds.json (written
    # by the rug-season pass every 6h). Bull → tight, rug_season → loose.
    # Fallback preserves old hardcoded behavior if file missing/stale.
    try:
        dyn = load_dynamic_thresholds()
        thr_hard        = int(dyn.get("rug_score_hard", 1500))
        thr_caution     = int(dyn.get("rug_score_caution", 700))
        # Fresh-token block scales with hard threshold (matches old 5000/1500 ratio)
        thr_fresh_block = max(thr_hard * 3, 5000)
        
        client = await _get_dex_client()
        r = await client.get(f"https://api.rugcheck.xyz/v1/tokens/{mint}/report/summary")
        if r.status_code == 200:
            data = r.json()
            rugcheck_score = data.get("score", 0)
            risks = data.get("risks", []) or []
            
            # Honeypot risk = always Tier 4 block (regardless of regime)
            has_honeypot = any("honeypot" in str(rk).lower() for rk in risks)
            
            if has_honeypot:
                layers["rugcheck"] = "block"
            elif age_minutes is not None and age_minutes < 120:
                # Fresh token: relax thresholds (concentration is normal here)
                if rugcheck_score > thr_fresh_block:
                    layers["rugcheck"] = "caution"
                else:
                    layers["rugcheck"] = "pass"
            else:
                # Mature token: dynamic thresholds based on market regime
                if rugcheck_score > thr_hard:
                    layers["rugcheck"] = "caution"  # downgraded from "block" , score alone shouldn't block
                elif rugcheck_score > thr_caution:
                    layers["rugcheck"] = "caution"
                else:
                    layers["rugcheck"] = "pass"
        elif r.status_code in (400, 404):
            # rugcheck has not indexed this fresh mint yet - not an outage (2026-10-15)
            layers["rugcheck"] = "pending_index"
        else:
            layers["rugcheck"] = "error"
            _log(f"rugcheck: {_short_mint(mint)} summary returned {r.status_code}", prefix="rugcheck")
    except Exception as _rc_e:
        layers["rugcheck"] = "error"
        _log(f"rugcheck: {_short_mint(mint)} summary err: {type(_rc_e).__name__} {_rc_e}", prefix="rugcheck")
    
    # ── Layer 2: velocity (price + liq movement) ──
    pair = await fetch_token_data(mint)
    if pair:
        price_change_5m = (pair.get("priceChange") or {}).get("m5", 0) or 0
        liq_now = (pair.get("liquidity") or {}).get("usd", 0) or 0
        if liq_now > 0 and price_change_5m < -30:
            layers["velocity"] = "caution"
        else:
            layers["velocity"] = "pass"
    else:
        layers["velocity"] = "error"
    
    # ── Layer 3: wallet_graph (age-aware) ──
    if holders_data is None:
        holders_data = await get_holders_top10(mint)
    if holders_data:
        top10_pct = holders_data.get("top10_pct", 0) or 0
        # Age-aware thresholds:
        #   <30min:   80%+ = caution, 90%+ = block
        #   30-120m:  70%+ = caution, 85%+ = block
        #   >120min:  60%+ = caution, 75%+ = block
        if age_minutes is not None and age_minutes < 30:
            block_threshold, caution_threshold = 90, 80
        elif age_minutes is not None and age_minutes < 120:
            block_threshold, caution_threshold = 85, 70
        else:
            block_threshold, caution_threshold = 75, 60
        
        if top10_pct >= block_threshold:
            layers["wallet_graph"] = "caution"  # downgraded from "block" , concentration alone shouldn't be Tier 4
        elif top10_pct >= caution_threshold:
            layers["wallet_graph"] = "caution"
        else:
            layers["wallet_graph"] = "pass"
    else:
        layers["wallet_graph"] = "error"
    
    # ── Layer 4: social_v_price (placeholder) ──
    layers["social_v_price"] = "pass"
    
    # ── Layer 5: bundler_mev ──
    # Heuristic: top 10 wallets with similar 3-8% holdings = likely bundle
    if holders_data and holders_data.get("top_holders"):
        top_holders = holders_data["top_holders"]
        pcts = [h.get("pct", 0) for h in top_holders[:10]]
        if pcts:
            similar_holdings = sum(1 for p in pcts if 3 <= p <= 8)
            if similar_holdings >= 8:
                bundle_score = 90
                bundle_wallets = similar_holdings
                layers["bundler_mev"] = "caution"  # very strong bundle pattern
            elif similar_holdings >= 7:
                bundle_score = 85
                bundle_wallets = similar_holdings
                layers["bundler_mev"] = "caution"
            elif similar_holdings >= 5:
                bundle_score = 70
                bundle_wallets = similar_holdings
                layers["bundler_mev"] = "pass"  # 70 alone doesn't block per fix report
            else:
                layers["bundler_mev"] = "pass"
    else:
        layers["bundler_mev"] = "error"
    
    # ── Layer 6: dev_history (placeholder) ──
    layers["dev_history"] = "pass"

    # Holder clusters. Rug score 1 does not clear a shared-funder bag.
    holder_clusters = await cluster_top_holders(mint, holders_data)
    _cg = holder_clusters.get("gate")
    if _cg == "block":
        layers["holder_clusters"] = "block"
    elif _cg == "caution":
        layers["holder_clusters"] = "caution"
    elif _cg == "pass":
        layers["holder_clusters"] = "pass"
    else:
        layers["holder_clusters"] = "error"
    
    # ── Overall verdict ──
    # Per ca-intel skill v2.0 hard rules: only Tier 4 conditions can produce "block"
    # Tier 4 = freeze_authority active, mint_authority active, honeypot detected,
    #         or no LP at all (we don't check LP lock here, but liq=0 is implicit)
    
    if layers["token_2022"] == "block":
        verdict = "block"
        block_reason = "tier_4_token_2022_authority"
    elif layers["rugcheck"] == "block":
        verdict = "block"
        block_reason = "tier_4_honeypot_detected"
    elif layers.get("holder_clusters") == "block":
        verdict = "block"
        block_reason = "holder_cluster_controls_float"
    else:
        # Count cautions across all layers
        cautions = sum(1 for v in layers.values() if v == "caution")
        errors = sum(1 for v in layers.values() if v == "error")
        
        if cautions >= 3:
            verdict = "caution"
            block_reason = None
        elif errors >= 4:
            verdict = "data_unavailable"
            block_reason = None
        elif cautions >= 1:
            verdict = "caution"
            block_reason = None
        else:
            verdict = "clean"
            block_reason = None
    
    # Sprint 37 — community formation detection restored.
    # Compute from pair data fetched above. Falls back to False/empty if pair missing.
    # 2026-10-23: too many layers unreadable = block, not a shrug (RUG_FAIL_CLOSED).
    if _guard is not None and verdict != "block" and _guard.rug_fail_closed(layers):
        verdict = "block"
        block_reason = "data_unavailable_fail_closed"

    if pair:
        community_formation = compute_community_formation(pair)
    else:
        community_formation = {
            "is_community_formation": False,
            "confidence":             0.0,
            "evidence":               ["no_pair_data"],
        }

    result = {
        "smart_check_verdict": verdict,
        "block_reason": block_reason,
        "rugcheck_score": rugcheck_score,
        "freeze_authority": freeze_authority,
        "mint_authority": mint_authority,
        "is_token_2022": is_token_2022,
        "layers": layers,
        "is_community_formation": community_formation["is_community_formation"],
        "community_formation_confidence": community_formation["confidence"],
        "community_formation_evidence": community_formation["evidence"],
        "bundle_score": bundle_score,
        "bundle_wallets": bundle_wallets,
        "holder_clusters": holder_clusters,
    }
    
    # Sprint 28.7.3: append to rolling rugcheck history so we can detect
    # "caution → clean" verdict flips (suspicious , may indicate dev burning
    # lock right before rugging). Best-effort, never raises.
    try:
        with open(RUGCHECK_HISTORY_LOG, "a", encoding="utf-8") as f:
            f.write(json.dumps({
                "ts": _now_iso(),
                "ts_unix": _now_ts(),
                "mint": mint,
                "verdict": verdict,
                "rugcheck_score": rugcheck_score,
                "layers": layers,
            }, default=str) + "\n")
    except Exception:
        pass
    
    return result


# ═══════════════════════════════════════════════════════════════════════════
#                       X CHATTER CACHE (1h staleness)
# ═══════════════════════════════════════════════════════════════════════════

def load_x_chatter_cache() -> dict:
    data = load_json_with_staleness(X_CHATTER_CACHE_FILE, max_age_seconds=86400 * 7, default={}, alert_on_stale=False)
    if isinstance(data, dict):
        data.pop("_meta", None)
        return data
    return {}


def save_x_chatter_cache(cache: dict) -> None:
    _save_json_atomic(X_CHATTER_CACHE_FILE, cache)


def get_cached_x_chatter(ticker: str) -> Optional[dict]:
    """Return cached chatter for ticker if <1h old, else None."""
    cache = load_x_chatter_cache()
    entry = cache.get(ticker.lower())
    if not entry:
        return None
    cached_at = entry.get("cached_at_ts", 0)
    age_min = (_now_ts() - cached_at) / 60
    if age_min > X_CHATTER_STALENESS_MIN:
        return None
    return entry


def cache_x_chatter(ticker: str, summary: str, mention_count_24h: int = 0, vip_engaged: list = None) -> None:
    cache = load_x_chatter_cache()
    cache[ticker.lower()] = {
        "ticker": ticker,
        "summary": summary,
        "mention_count_24h": mention_count_24h,
        "vip_engaged": vip_engaged or [],
        "cached_at": _now_iso(),
        "cached_at_ts": _now_ts(),
    }
    # Prune entries older than 24h
    cutoff = _now_ts() - 86400
    cache = {k: v for k, v in cache.items() if v.get("cached_at_ts", 0) > cutoff}
    save_x_chatter_cache(cache)


async def fetch_x_chatter_for_ticker(ticker: str) -> dict:
    """
    Fetch X chatter , placeholder. In production this would route via
    an X search backend.
    For now, returns cached or empty.
    """
    cached = get_cached_x_chatter(ticker)
    if cached:
        return {
            "summary": cached["summary"],
            "mention_count_24h": cached.get("mention_count_24h", 0),
            "vip_engaged": cached.get("vip_engaged", []),
            "cache_age_minutes": (_now_ts() - cached.get("cached_at_ts", _now_ts())) / 60,
        }
    
    # Placeholder result , no data fetched yet
    return {
        "summary": "no_chatter_data_yet",
        "mention_count_24h": 0,
        "vip_engaged": [],
        "cache_age_minutes": None,
    }


# ═══════════════════════════════════════════════════════════════════════════
#                       PRIOR-LAUNCHES LOOKUP (autopsy-driven)
# ═══════════════════════════════════════════════════════════════════════════

def find_prior_launches(ticker: str, name: str = None) -> list[dict]:
    """
    Search autopsy_reports.json for prior launches of same/similar ticker/name.
    Returns up to 5 most recent prior trades.
    """
    autopsies = load_json_with_staleness(AUTOPSY_REPORTS_FILE, max_age_seconds=86400 * 365, default=[], alert_on_stale=False)
    if not isinstance(autopsies, list):
        return []
    
    ticker_lower = (ticker or "").lower()
    name_lower = (name or "").lower()
    
    matches = []
    for record in autopsies:
        if not isinstance(record, dict):
            continue
        rec_ticker = (record.get("ticker") or "").lower()
        rec_name = (record.get("name") or "").lower()
        
        if ticker_lower and ticker_lower == rec_ticker:
            matches.append(record)
        elif name_lower and name_lower == rec_name:
            matches.append(record)
    
    # Sort by timestamp desc, return top 5
    matches.sort(key=lambda r: r.get("closed_at", "") or r.get("timestamp", ""), reverse=True)
    
    return [
        {
            "timestamp": m.get("closed_at") or m.get("timestamp"),
            "outcome": _format_outcome(m),
            "ticker": m.get("ticker"),
            "name": m.get("name"),
            "ca": m.get("mint"),
            "pnl_pct": m.get("pnl_pct"),
        }
        for m in matches[:5]
    ]


def _format_outcome(record: dict) -> str:
    pnl = record.get("pnl_pct")
    if pnl is None:
        return "unknown_outcome"
    if pnl >= 100:
        return f"ran_{pnl/100:.1f}x"
    if pnl >= 0:
        return f"won_{pnl:.0f}pct"
    if pnl < -50:
        return f"rugged_at_{abs(pnl):.0f}pct"
    return f"lost_{abs(pnl):.0f}pct"


# ═══════════════════════════════════════════════════════════════════════════
#                     PACKET BUILDER (full meme_candidate)
# ═══════════════════════════════════════════════════════════════════════════

# ═══════════════════════════════════════════════════════════════════════════
#              COIN COMMUNITIES , per-token social sentiment
# ═══════════════════════════════════════════════════════════════════════════
# Primary per-token chatter source. CA reads via x-api-key; same-ticker firehose
# via x-server-key+secret (falls back to public feed if the pair isn't set).
# Everything here is BEST-EFFORT: any failure returns empty so it NEVER blocks a
# candidate packet, and it only runs for tokens that already passed the filters.
# Uses Grok for the summary (not local Ollama).

_coincomms_client: Optional[httpx.AsyncClient] = None


async def _get_coincomms_client() -> httpx.AsyncClient:
    global _coincomms_client
    if _coincomms_client is None or _coincomms_client.is_closed:
        _coincomms_client = httpx.AsyncClient(
            base_url=COINCOMMS_BASE_URL,
            timeout=15,
            # Cloudflare on api.coin-communities.xyz bans non-browser client
            # signatures with error 1010. A custom UA ("AgentEmpire/1.0") was
            # silently 403'ing EVERY call. These browser headers test 200 OK on
            # health + feed + server endpoints. Per-call auth headers (x-api-key /
            # x-server-*) merge on top of these. Do NOT revert to a custom UA.
            headers={
                "User-Agent": ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                               "AppleWebKit/537.36 (KHTML, like Gecko) "
                               "Chrome/124.0.0.0 Safari/537.36"),
                "Accept": "application/json, text/plain, */*",
                "Accept-Language": "en-US,en;q=0.9",
                "Origin": "https://coincommunities.org",
                "Referer": "https://coincommunities.org/",
            },
        )
    return _coincomms_client


def _cc_items(data) -> list:
    # Coin Communities wraps list payloads under a named key, and the generated
    # SDK additionally nests under "data". Handle bare list, {messages|items|feed}
    # and {data: <either>} so a real envelope never silently parses to empty.
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        inner = data.get("messages") or data.get("items") or data.get("feed")
        if inner:
            return inner
        if isinstance(data.get("data"), (list, dict)):
            return _cc_items(data["data"])
    return []


async def _coincomms_ca_messages(token_address: str, limit: int = 30) -> list:
    """Recent community messages for THIS exact mint (spam/harm filtered)."""
    if not COINCOMMS_API_KEY or not token_address:
        return []
    try:
        client = await _get_coincomms_client()
        r = await client.get(
            f"/api/v1/communities/{token_address}/messages",
            params={"limit": min(limit, 100), "sort": "time", "order": "desc",
                    "filterIsSpam": "true", "filterIsHarm": "true"},
            headers={"x-api-key": COINCOMMS_API_KEY},
        )
        return _cc_items(r.json()) if r.status_code == 200 else []
    except Exception as e:
        _log(f"coincomms_ca_messages error {_short_mint(token_address)}: {e}")
        return []


async def _coincomms_ticker_messages(ticker: str, limit: int = 200) -> list:
    """Same-ticker chatter across ALL communities , catches PvP/copycats.
    Uses the cross-community FEED: it is the only read that carries tokenSymbol
    (the global server-messages endpoint returns symbol-less Message objects, so
    symbol-filtering there drops everything). The API key alone authorizes it."""
    if not ticker or not COINCOMMS_API_KEY:
        return []
    sym = str(ticker).lstrip("$").upper()
    try:
        client = await _get_coincomms_client()
        r = await client.get(
            "/api/v1/feed/public",
            params={"limit": min(limit, 500)},
            headers={"x-api-key": COINCOMMS_API_KEY},
        )
        if r.status_code != 200:
            return []
        return [it for it in _cc_items(r.json())
                if str(it.get("tokenSymbol") or "").lstrip("$").upper() == sym]
    except Exception as e:
        _log(f"coincomms_ticker_messages error {ticker}: {e}")
        return []


def _coincomms_digest(msgs: list, our_ca: Optional[str] = None) -> dict:
    """Cheap mechanical digest , no LLM."""
    n = len(msgs)
    spam = sum(1 for m in msgs if m.get("isSpam"))
    cas: dict = {}
    for m in msgs:
        ca = m.get("tokenAddress")
        if ca:
            cas[ca] = cas.get(ca, 0) + 1
    pvp = False
    if our_ca and cas:
        hottest_ca = max(cas, key=cas.get)
        pvp = hottest_ca != our_ca and cas[hottest_ca] > cas.get(our_ca, 0)
    return {
        "message_count": n,
        "spam_ratio": round(spam / n, 2) if n else 0.0,
        "distinct_cas": len(cas),
        "pvp_other_ca_hotter": pvp,
    }


async def _build_social_sentiment(mint: str, ticker: str, x_chatter: Optional[dict] = None,
                                  brand: Optional[dict] = None) -> dict:
    """Cross-source social read for a token that PASSED the filters.
    coincomms primary (CA + ticker), x_chatter secondary, Grok summary."""
    try:
        ca_msgs, ticker_msgs = await asyncio.gather(
            _coincomms_ca_messages(mint, limit=30),
            _coincomms_ticker_messages(ticker, limit=200),
        )
    except Exception:
        ca_msgs, ticker_msgs = [], []

    ca_digest = _coincomms_digest(ca_msgs, our_ca=mint)
    ticker_digest = _coincomms_digest(ticker_msgs, our_ca=mint)
    x_found = bool(x_chatter) and bool(
        (x_chatter or {}).get("found") or (x_chatter or {}).get("summary") or (x_chatter or {}).get("tweets")
    )
    sources = []
    if ca_msgs: sources.append("coincomms_ca")
    if ticker_msgs: sources.append("coincomms_ticker")
    if x_found: sources.append("x_chatter")

    block = {
        "available": bool(sources),
        "sources_used": sources,
        "coincomms_ca": ca_digest,
        "coincomms_ticker": ticker_digest,
        # ── #4 (2026-08-12): BRAND CAN RAISE THE FLAG SOCIAL MISSED ─────────
        # On 2026-08-11 the BOT swarm had brand clone_count=12 and social
        # pvp_flag=FALSE, because coincomms had no chatter for that ticker - the
        # softer pipe, which the skill treats as the early warning, said all-clear
        # on a twelve-clone tape. Two pipes looking at the same swarm, one blind.
        #
        # Social silence is not evidence of no PvP. The flag is now an OR: either
        # source can raise it, and `pvp_flag_source` says which did so a false
        # negative from one pipe can never present as a clean read.
        "pvp_flag": bool(ticker_digest.get("pvp_other_ca_hotter", False)
                         or ticker_digest.get("distinct_cas", 0) > 1
                         or (brand or {}).get("clone_count", 0) >= 3),
        "pvp_flag_source": (
            "social+brand" if ((ticker_digest.get("distinct_cas", 0) > 1)
                               and (brand or {}).get("clone_count", 0) >= 3)
            else "brand_only" if (brand or {}).get("clone_count", 0) >= 3
            else "social_only" if (ticker_digest.get("pvp_other_ca_hotter", False)
                                   or ticker_digest.get("distinct_cas", 0) > 1)
            else None),
        "pvp_brand_clone_count": (brand or {}).get("clone_count"),
        "pvp_clone_grade": (brand or {}).get("clone_grade"),
        "overall_vibe": "unknown",
        "summary": None if sources else "no community chatter found yet",
        "notable": [],
        "pvp_note": None,
    }
    if not sources:
        return block

    def _snip(msgs, k=12):
        out = []
        for m in msgs[:k]:
            c = (m.get("content") or "").strip().replace("\n", " ")
            if c:
                out.append(f"- (@{m.get('username','?')}, {m.get('followerCount',0)} flwrs) {c[:160]}")
        return "\n".join(out)

    x_summary = (x_chatter or {}).get("summary") or (x_chatter or {}).get("text") or "(none)"
    prompt = (
        f"Reading social chatter on a Solana memecoin to gauge sentiment/noise. "
        f"Ticker ${str(ticker).lstrip('$')}, mint {mint}.\n\n"
        f"COMMUNITY chatter (this exact token):\n{_snip(ca_msgs) or '(none)'}\n\n"
        f"SAME-TICKER chatter (other tokens sharing the ticker , possible PvP/copycats):\n{_snip(ticker_msgs) or '(none)'}\n\n"
        f"X chatter (secondary): {x_summary}\n\n"
        f'Return ONLY JSON: {{"overall_vibe": one of [bullish, mixed, exit_liquidity_vibes, dead], '
        f'"summary": one tight sentence on the noise around this coin, '
        f'"notable": short list of standout mentions/KOLs (or []), '
        f'"pvp_note": one phrase if a same-ticker token is stealing attention, else null}}'
    )
    try:
        raw = await grok_generate(prompt, format_json=True, max_tokens=300)
        parsed = parse_llm_json(raw) if raw else None
        if parsed:
            block["overall_vibe"] = parsed.get("overall_vibe", "unknown")
            block["summary"] = parsed.get("summary") or block["summary"]
            block["notable"] = parsed.get("notable") or []
            block["pvp_note"] = parsed.get("pvp_note")
    except Exception as e:
        _log(f"_build_social_sentiment grok error {ticker}: {e}")
        block["summary"] = block["summary"] or "summary unavailable (see chatter counts)"
    return block


async def build_meme_candidate_packet(profile: dict, *, surfaced_via: str = "bonded") -> Optional[dict]:
    """
    Take a DexScreener token profile and build a full meme_candidate inbox packet.
    Returns None if filter rejects the token.
    
    Filters (in order of cheapness):
      1. No mint address
      2. No DEX pair data
      3. mcap < $10K (sole hard filter)
      4. liquidity = $0 (dead pool , can't enter even if the agent wanted to)
    
    Args:
      profile: DexScreener token profile/pair dict
      surfaced_via: which scanner surfaced this , "bonded" | "trending" | "boost" |
                    "watchlist_recheck" | "dex_paid_event" | "runner_alert"
    
    Sprint 28.3:
      - Acquires mint-level lock to prevent dupe enrichment from concurrent scanners
      - Logs skip reasons to skip_log.json (autoagent will mine later)
      - Records passed-filter to passed_filter_log (feeds missed-runner autopsy)
      - Auto-adds to watchlist on every passed packet
      - Auto-adds to dex_paid_watch if socials are completely thin
      - Sets hold_candidate flag if mint is on the trending track 8h+
      - Includes token image_url from DexScreener
    """
    mint = profile.get("tokenAddress")
    if not mint:
        return None
    
    # Acquire per-mint lock to prevent race between bonded scanner + trending scanner
    lock = await acquire_mint_lock(mint)
    async with lock:
        return await _build_meme_candidate_packet_locked(profile, mint, surfaced_via)


async def _build_meme_candidate_packet_locked(profile: dict, mint: str, surfaced_via: str) -> Optional[dict]:
    if is_own_launch(mint):   # v14.3: our own launch is never a candidate
        return None
    """The actual builder, called under mint lock."""
    # Step 1: fetch full pair data
    pair = await fetch_token_data(mint)
    if not pair:
        skip_log_record(profile, "no_dex_pair_data")
        return None
    
    base = pair.get("baseToken") or {}
    quote = pair.get("quoteToken") or {}

    # Oct 2026 upgrade gate: custom-pair quote, invalid/negative reserves, fee-sweep pending,
    # Meteora DAMM v2 / DBC drain, fake xStock, wash volume. Only ever skips or flags.
    _upg_sig = _upg_pre_gate(pair, mint)
    if _upg_sig.get("skip_reason"):
        skip_log_record(profile, _upg_sig["skip_reason"], mcap=_safe_num(pair.get("marketCap")) or 0)
        if _upg_sig.get("recheck"):
            _enqueue_heal_watch(
                mint,
                ticker=(base.get("symbol") if base else None) or profile.get("ticker") or profile.get("symbol"),
                scan_mcap=_safe_num(pair.get("marketCap") or pair.get("fdv")),
                scan_price=_safe_num(pair.get("priceUsd")),
                skip_reason=_upg_sig["skip_reason"],
            )
        _log(f"upgrade gate skip {_short_mint(mint)}: {_upg_sig['skip_reason']} - "
             f"{_upg_sig.get('detail') or ''}", prefix="gate")
        return None

    # ── FIX 8 (2026-08-15): THE "FINAL GATE" WAS NEVER CALLED ────────────────
    # is_bonded_dexid() documents itself as "the final gate" for bonded/graduated
    # tokens - and grep says it is defined at ~3495 and called NOWHERE. So a
    # surfaced_via="bonded" packet asserted bonding that nothing verified, and
    # `bonded_from` was cosmetic text next to an unchecked claim.
    #
    # That matters because "bonded" is the word the desk trusts to mean a token has
    # graduated off the bonding curve. A pump.fun prebond profile could ride that
    # label into a full meme_candidate.
    #
    # FAIL CLOSED, per the spec's own pick: an unverifiable dexId is a REJECT, not
    # a pass-through with a warning label. A gate that waves through what it cannot
    # read is the gate not existing.
    if surfaced_via == "bonded":
        _dex_id = (pair.get("dexId") or "").lower()
        if not _dex_id:
            skip_log_record(profile, "bonded_dexid_unknown", mcap=None)
            _log(f"bonded reject {_short_mint(mint)}: no dexId on the pair - cannot verify "
                 f"graduation, failing closed", prefix="bond")
            return None
        if not is_bonded_dexid(pair):
            skip_log_record(profile, "not_bonded_dexid", mcap=None)
            _log(f"bonded reject {_short_mint(mint)}: dexId '{_dex_id}' is not in the "
                 f"bonded whitelist - surfaced_via said bonded, the pair says otherwise",
                 prefix="bond")
            return None

    mcap = float(pair.get("marketCap") or pair.get("fdv") or 0)
    
    # ── THE ONLY HARD FILTER: mcap >= floor (Sprint 32: tunable via meeting override) ──
    mcap_floor = await get_override("MCAP_FLOOR_USD", MCAP_FLOOR_USD)
    if mcap < mcap_floor:
        skip_log_record(profile, "mcap_below_floor", mcap=mcap)
        _enqueue_heal_watch(
            mint,
            ticker=(base.get("symbol") if base else None) or profile.get("ticker") or profile.get("symbol"),
            scan_mcap=mcap,
            scan_price=_safe_num(pair.get("priceUsd")),
            skip_reason="mcap_below_floor",
        )
        return None
    
    liq = (pair.get("liquidity") or {}).get("usd", 0) or 0
    vol = pair.get("volume") or {}
    price_change = pair.get("priceChange") or {}
    
    # Early exit: liquidity = $0 means the pool is dead, can't enter even if the agent wanted to.
    # Skip enrichment entirely (saves Helius RPC + Ollama time).
    if liq < 1.0:  # less than $1 = effectively dead
        # AGENT'S PATCH #2 (2026-07-24, Jimothy2.0 17.8x miss): liq_zero with
        # mcap already ABOVE the floor is almost never a real death — it's a
        # bond/graduation indexing race or an API transient. Discovery failure,
        # not judgment failure. Queue a short recheck instead of permanent kill.
        if mcap and mcap >= 10_000:
            try:
                _lz = {}
                try:
                    with open(LIQ_ZERO_RECHECK_FILE, encoding="utf-8-sig") as _lf:
                        _lz = json.load(_lf) or {}
                except Exception:
                    pass
                if mint not in _lz and len(_lz) < LZRC_MAX_QUEUE:
                    _lz[mint] = {"first_seen": _now_iso(), "first_ts": _now_ts(),
                                  "mcap_at_skip": mcap, "attempts": 0,
                                  "ticker": (profile.get("ticker") or profile.get("symbol") or "?")}
                    LIQ_ZERO_RECHECK_FILE.parent.mkdir(parents=True, exist_ok=True)
                    with open(LIQ_ZERO_RECHECK_FILE, "w", encoding="utf-8") as _lf:
                        json.dump(_lz, _lf, indent=2)
                    _log(f"liq_zero + mcap ${mcap:,.0f} — queued for recheck (bond race?)", prefix="lzrc")
            except Exception as _lze:
                _log(f"liq_zero queue err: {_lze}", prefix="lzrc")
            skip_log_record(profile, "liq_zero_pending_recheck", mcap=mcap, liq=liq)
            _enqueue_heal_watch(
                mint,
                ticker=(base.get("symbol") if base else None) or profile.get("ticker") or profile.get("symbol"),
                scan_mcap=mcap,
                scan_price=_safe_num(pair.get("priceUsd")),
                skip_reason="liq_zero_pending_recheck",
            )
            return None
        skip_log_record(profile, "liq_zero", mcap=mcap, liq=liq)
        _enqueue_heal_watch(
            mint,
            ticker=(base.get("symbol") if base else None) or profile.get("ticker") or profile.get("symbol"),
            scan_mcap=mcap,
            scan_price=_safe_num(pair.get("priceUsd")),
            skip_reason="liq_zero",
        )
        return None
    
    # Compute age
    pair_created_at = pair.get("pairCreatedAt", 0) or 0
    age_minutes = (
        ((_now_ts() * 1000) - pair_created_at) / 60_000
        if pair_created_at > 0 else 9999
    )
    age_min_int = int(age_minutes) if age_minutes < 99999 else None
    
    # ── Steps 2 + 3 + ohlcv + deployer + lp_lock: parallelize independent fetches ──
    # v13.1 Drop 2: added lp_lock_task — independent fetch, can run in parallel.
    holders_task = asyncio.create_task(get_holders_top10(mint))
    ohlcv_task = asyncio.create_task(fetch_ohlcv(mint, limit=30, pair=pair))
    deployer_task = asyncio.create_task(get_deployer_history(mint))
    lp_lock_task = asyncio.create_task(fetch_rugcheck_lp_lock(mint))
    
    holders = await holders_task

    # Sprint 65: feed this token's top holders into the wallet net. Rides free on the
    # holder data we just fetched — no extra call. The wallets that recur across tokens
    # graduate to matched. DATA, not directives.
    try:
        if holders and holders.get("top_holders"):
            wallet_funnel_ingest(mint, (base.get("symbol") or "?"), holders["top_holders"])
    except Exception as _we:
        _log(f"wallet funnel ingest skipped: {_we}", prefix="wallet")

    # Sprint 65 ①: holder hold-time snapshot — a structure signal (diamond vs paper
    # hands). Costs a bounded token-history pull, so only for real candidates (we're
    # already deep in enrichment here). Stashed into holders for the packet builder.
    try:
        if holders:
            _ht = await compute_holder_hold_time(mint, holders.get("holder_count") or 0)
            if _ht:
                holders["holder_hold_time"] = _ht
    except Exception as _hte:
        _log(f"holder hold-time skipped {_short_mint(mint)}: {_hte}", prefix="wallet")

    # Rug check needs holders, can't parallelize fully , but it can overlap with the
    # ohlcv fetch which is still running
    rug_check = await smart_rug_check(mint, holders_data=holders, age_minutes=age_min_int)
    
    # Step 4: extract bonded source
    bonded_from = "unknown"
    dex_id = (pair.get("dexId") or "").lower()
    if "pump" in dex_id or "pumpfun" in dex_id:
        bonded_from = "pump.fun"
    elif "moonshot" in dex_id:
        bonded_from = "moonshot"
    elif "raydium" in dex_id:
        bonded_from = "raydium_direct"
    
    # Step 5: social info
    info = pair.get("info") or {}
    socials = info.get("socials") or []
    websites = info.get("websites") or []
    twitter_url = next((s.get("url") for s in socials if "twitter" in str(s.get("type", "")).lower() or "x.com" in str(s.get("url", "")).lower()), None)
    telegram_url = next((s.get("url") for s in socials if "telegram" in str(s.get("type", "")).lower()), None)
    website_url = websites[0].get("url") if websites else None
    
    # NEW: token image / header (DexScreener provides these on most tokens)
    image_url = info.get("imageUrl") or profile.get("icon")
    header_url = info.get("header")
    open_graph_url = info.get("openGraph")
    
    # Extract X handle / detect community link from the URL for clean packet display
    twitter_handle = None
    is_x_community = False
    is_status_link = False
    if twitter_url:
        # x.com/handle, x.com/i/communities/<id>, x.com/<handle>/status/<id>
        if "/i/communities/" in twitter_url:
            is_x_community = True
        elif "/status/" in twitter_url:
            is_status_link = True  # someone's tweet, not a token's actual X account
        else:
            # Extract handle from x.com/<handle> or twitter.com/<handle>
            try:
                parts = twitter_url.rstrip("/").split("/")
                if parts:
                    candidate = parts[-1]
                    # Strip leading @ if present, validate it's a plausible handle
                    candidate = candidate.lstrip("@")
                    if candidate and candidate not in ("x.com", "twitter.com", "i") and len(candidate) <= 30:
                        twitter_handle = candidate
            except Exception:
                pass
    
    # Step 6: enrichment for narrative_intelligence
    prior_launches = find_prior_launches(base.get("symbol"), base.get("name"))
    
    # v1.0.7 fix 5: X followers + account age via the bearer token (X_PROFILE_FILL, cached)
    _v107_xp = {}
    try:
        import v107_rules as _v107
        if twitter_handle and not is_x_community:
            _v107_xp = await asyncio.to_thread(_v107.x_profile, twitter_handle,
                                               _BOT_LOGS / "x_profile_cache.json")
    except Exception:
        _v107_xp = {}

    # Build the data we'll feed to LLM
    enrichment_input = {
        "mint": mint,
        "ticker": base.get("symbol"),
        "name": base.get("name"),
        "description": (info.get("description") or profile.get("description") or "")[:500],
        "bonded_from": bonded_from,
        "age_minutes": int(age_minutes) if age_minutes < 99999 else None,
        "twitter": twitter_url,
        "twitter_handle": twitter_handle,
        "is_x_community": is_x_community,
        "is_x_status_link": is_status_link,
        "twitter_followers": _v107_xp.get("followers"),   # v1.0.7: X API (bearer), cached
        "x_account_age_days": _v107_xp.get("age_days"),
        "mcap": mcap,
        "liquidity_usd": liq,
        "volume_5m": vol.get("m5", 0) or 0,
        "volume_1h": vol.get("h1", 0) or 0,
        "volume_24h": vol.get("h24", 0) or 0,
        "price_change_5m": price_change.get("m5", 0) or 0,
        "price_change_1h": price_change.get("h1", 0) or 0,
        "price_change_24h": price_change.get("h24", 0) or 0,
        "holder_count": (holders or {}).get("holder_count"),
        "top10_pct": (holders or {}).get("top10_pct"),
        "boost_count": 0,  # populated by separate boosts fetch if needed
        "telegram_members": None,
        "x_dex_paid": bool(info.get("dex_paid") or pair.get("dex_paid")),
        "meta_alignment": False,  # filled in after narrative is known
    }
    
    # Step 7: narrative intelligence (Ollama LLM). Sprint 32: skippable via meeting override
    if await get_override("BRAIN_NARRATIVE_ENABLED", True):
        narrative = await synthesize_narrative_intelligence(enrichment_input, prior_launches)
    else:
        narrative = {
            "narrative": "unknown",
            "skipped": "disabled_via_meeting",
            "summary": "narrative synthesis skipped per active meeting directive",
        }
    
    # Use LLM-suggested narrative for edge_filter meta-check
    enrichment_input["narrative"] = narrative.get("narrative", "unknown")
    
    # Sprint 28.4: meta_alignment now computed from current_meta (which is computed from
    # trending_track narratives). When token's narrative matches the dominant meta(s),
    # this flips true → enables unicorn_combo when x_dex_paid is also true.
    enrichment_input["meta_alignment"] = is_token_meta_aligned(narrative.get("narrative"))
    
    # Step 8: edge filter
    edge_filter = compute_edge_filter(enrichment_input)

    # Sprint 53 — Step 8b: BRAND / SAME-TICKER RESOLUTION. Clones spawn around any
    # runner and can look *better* on our metrics precisely because they're parasites
    # riding attention they didn't earn (fresh chart, tight structure). Resolve which
    # token actually owns the brand so we stop burning cycles on lookalikes while the
    # OG runs untouched. Non-fatal: if the search fails, the packet just carries None.
    _brand_resolution = None
    try:
        _brand_resolution = await resolve_ticker_brand(base.get("symbol") or "", mint)
    except Exception as _bre:
        _log(f"brand_resolution err {_short_mint(mint)}: {_bre}", prefix="brand")
    
    # v13.1 Drop 2: await lp_lock_task and compute the new packet blocks
    lp_lock_data = await lp_lock_task
    
    drop2_filter_results = compute_drop2_filter_results(
        token=enrichment_input,
        holders_data=holders,
        lp_lock_data=lp_lock_data,
        age_minutes=age_minutes if age_minutes < 99999 else None,
    )
    
    current_filter_state_block = compute_current_filter_state()
    
    # Determine wallet floor state at packet-build time
    try:
        _floor_above, _floor_current_sol = await is_wallet_above_floor()
        _wallet_floor_active = (not _floor_above) and _WALLET_READ["ok"]
    except Exception:
        _wallet_floor_active = False
    
    # Inject rug_check authority fields into a synthetic token_data so
    # compute_hardcoded_checks can read them. enrichment_input doesn't carry
    # freeze/mint authority by default; rug_check does.
    _hc_token_data = dict(enrichment_input)
    _hc_token_data["rug_check"] = rug_check
    _hc_token_data["dexId"] = (pair.get("dexId") if isinstance(pair, dict) else None)
    
    hardcoded_checks_block = compute_hardcoded_checks(
        token_data=_hc_token_data,
        wallet_floor_active=_wallet_floor_active,
    )
    
    # Step 9: pattern classification (use OHLCV from the parallel task we started above)
    ohlcv = await ohlcv_task
    pattern = await classify_pattern(ohlcv, enrichment_input) if ohlcv else {
        "tier": _infer_tier_label(enrichment_input).count("graduate") + 1,
        "tier_label": _infer_tier_label(enrichment_input),
        "classification": "no_ohlcv_data",
        "confidence": 0.0,
        "is_novel": False,
        "llm_named": False,
        "llm_observation": None,
        "matched_against_library": None,
    }
    
    # Step 10: X chatter (cached, may be stale)
    x_chatter = await fetch_x_chatter_for_ticker(base.get("symbol", ""))

    # Step 10b: social sentiment , coincomms primary + x_chatter secondary, Grok summary.
    # Runs ONLY here (post-filter survivors). Bounded so a hung call never stalls the scanner.
    try:
        social_sentiment = await asyncio.wait_for(
            # #4: brand is resolved above (Step 8b) - hand it over so a social
            # false-negative on a clone flood cannot present as all-clear
            _build_social_sentiment(mint, base.get("symbol", ""), x_chatter,
                                    brand=_brand_resolution), timeout=30)
    except Exception:
        social_sentiment = {"available": False, "sources_used": [],
                            "summary": "social fetch timed out/failed"}
    
    # Step 11: Wait on deployer history task (started in parallel earlier)
    try:
        deployer_history = await deployer_task
    except Exception as e:
        _log(f"deployer_history fetch error: {e}")
        deployer_history = {
            "address": None,
            "prior_launches": 0,
            "prior_rugs": 0,
            "prior_winners": 0,
            "rep": "unknown",
            "first_seen": None,
        }
    
    # Sprint 28.7 , Step 12: wallet snapshot (the agent sees actual budget on every packet)
    try:
        wallet_status = await get_wallet_status_block()
    except Exception as e:
        _log(f"wallet_status fetch error (non-fatal): {e}")
        wallet_status = {
            "wallet_sol": None,
            "wallet_usd": None,
            "sol_price_usd": None,
            "_price_source": "fetch_failed",
            "_error": str(e)[:100],
            "fetched_at": _now_iso(),
        }
    
    # Build the packet
    mint_first8 = mint[:8] if len(mint) >= 8 else mint
    packet_id = f"x_evt_meme_{mint_first8}"
    
    packet = {
        "id": packet_id,
        "type": "meme_candidate",
        "owner_rules": _owner_rules_ctx(),
        "received_at": _now_iso(),
        **_lane_fields("meme_candidate"),
        "from_user": {
            "username": "@meme_sniper",
            "friendship_tier": "system",
            "user_id": "meme_sniper_bot",
        },
        "context": {
            "mint": mint,
            "ticker": base.get("symbol"),
            "name": base.get("name"),
            "description": (info.get("description") or profile.get("description") or "")[:500],
            "chain": "solana",
            "bonded_from": bonded_from,
            "bonded_at": (
                datetime.fromtimestamp(pair_created_at / 1000, tz=EST).isoformat(timespec="seconds")
                if pair_created_at > 0 else None
            ),
            "scanned_at": _now_iso(),
            "age_minutes": int(age_minutes) if age_minutes < 99999 else None,
            
            "dex_data": {
                "mcap": mcap,
                "fdv": pair.get("fdv"),
                "liquidity_usd": liq,
                "volume_5m": vol.get("m5", 0) or 0,
                "volume_1h": vol.get("h1", 0) or 0,
                "volume_24h": vol.get("h24", 0) or 0,
                "price_usd": str(pair.get("priceUsd") or "0"),
                "price_change_5m": price_change.get("m5", 0) or 0,
                "price_change_1h": price_change.get("h1", 0) or 0,
                "price_change_24h": price_change.get("h24", 0) or 0,
                "pair_url": pair.get("url"),
                "dex": dex_id,
                "pair_address": pair.get("pairAddress"),
            },
            
            "upgrade_signals": await _upg_launch(mint, age_minutes if age_minutes < 99999 else None),
            "trade_pressure": _compute_trade_pressure(pair),
            
            "pattern": pattern,
            "archetype_match": (lambda _am: (
                _record_archetype_match(mint, (pair.get("baseToken") or {}).get("symbol", "?"),
                                         _am.get("archetype") or _am.get("name") or "unnamed", pair)
                or {**_am,
                     "validation": archetype_validation_read(_am.get("archetype") or _am.get("name") or "unnamed"),
                     "doctrine": ("the owner's ruling 2026-07-23: an archetype is a MEASURED PRIOR that adjusts "
                                   "PARAMETERS — flip-mode default, tighter trail, smaller size — never a veto. "
                                   "If edges + rugcheck pass, 'rugfast' means 'can I get out before the rug', "
                                   "and the validation numbers above answer that. Obvious rugs by DATA "
                                   "(safety gates) still die on their own lane.")}
            ) if isinstance(_am, dict) else _am)(_match_active_archetype(ohlcv, pair)),
            "narrative_intelligence": narrative,
            "social_sentiment": social_sentiment,
            
            "social": {
                "twitter": twitter_url,
                "twitter_handle": twitter_handle,
                "is_x_community": is_x_community,
                "is_x_status_link": is_status_link,
                # FIX 3 (2026-08-16): was "PENDING: who_shilling handoff" , a fossil.
                # who_shilling has been an alias for deep_research["x"] since Sprint
                # 28.4 and never touches the old handoff. Filled by deep_research[x]
                # if the research responder returns twitter_account_data; stays None otherwise.
                "twitter_followers": _v107_xp.get("followers"),
                "x_account_age_days": _v107_xp.get("age_days"),
                "x_verified": _v107_xp.get("verified"),
                "x_profile_source": _v107_xp.get("source"),
                "x_quality": _classify_x_quality(_v107_xp.get("followers") or 0, _v107_xp.get("age_days") or 0),
                "x_chatter_recent": x_chatter.get("summary"),
                "x_chatter_cache_age_minutes": x_chatter.get("cache_age_minutes"),
                "x_community": twitter_url if is_x_community else None,
                "telegram": telegram_url,
                "telegram_members": None,
                "website": website_url,
                "x_dex_paid": bool(info.get("dex_paid") or pair.get("dex_paid")),  # if DexScreener marks it
                "vip_engaged": x_chatter.get("vip_engaged", []),
            },
            
            # NEW v11.3: visual assets , the agent can read the token's image to gauge effort/originality
            "visual_assets": {
                "image_url": image_url,
                "header_url": header_url,
                "open_graph_url": open_graph_url,
            },
            
            "rug_check": rug_check,
            
            "holders": {
                "top10_pct": (holders or {}).get("top10_pct"),
                "dev_holding_pct": (holders or {}).get("dev_holding_pct"),
                "holder_count": (holders or {}).get("holder_count"),
            },
            
            # v13.1 Drop 2: LP lock data from rugcheck full-report endpoint
            "lp_lock": {
                "lp_locked_pct": (lp_lock_data or {}).get("lp_locked_pct"),
                "lp_burned": (lp_lock_data or {}).get("lp_burned"),
                "token_program": (lp_lock_data or {}).get("token_program"),
                "_source": (lp_lock_data or {}).get("_source"),
            },
            
            "deployer_history": deployer_history,

            # ── EDGE V2 phase 2 (2026-08-07, spec section D) ──────────────────
            # HUMAN memory of this wallet, separate from deployer_history above.
            # That one is automated PnL reputation ("did this wallet's tokens make
            # money"). This is what the agent CONCLUDED about the people last time -
            # stick / farm / failed - written on close from the map report.
            # A wallet can score clean on PnL and still be a farm, which is why the
            # two are never merged.
            # READ-ONLY AND NON-BINDING. Spec: "Never auto-block without the agent."
            # An unknown deployer returns {} and that is NOT a negative signal.
            "deployer_memory": _deployer_memory_note(
                (deployer_history or {}).get("address")
                or (deployer_history or {}).get("deployer")),

            "edge_filter": edge_filter,
            
            # Sprint 53 — BRAND / SAME-TICKER RESOLUTION (the agent's #2). When clones
            # spawn around a runner, this says plainly whether you're looking at the OG
            # or a parasite riding its attention. Informs, never vetoes — a clone can
            # still run, but you must KNOW it's a clone. Never mistake a copy for the brand.
            "brand_resolution": _brand_resolution,

            # ── EDGE V2 phase 3 (spec section E) - ADVISORY ONLY ──────────────
            # Shows the size band the map clarity implies. Explicitly non-binding:
            # The agent still writes amount_sol and reverse_size_kill_v1 still applies
            # on top. Nothing in this codebase reads this to size anything - it is
            # packet VISIBILITY, which is the whole of what the spec asked for.
            # Populated only once a PROJECTION exists; at candidate time it usually
            # reads null, which is itself the useful signal: no map written yet.
            "suggested_size_band_from_map_clarity": _suggested_size_band(None),

            # ── ACCUMULATION / RESOLUTION MAP (2026-08-08) ────────────────────
            # Which rung is this token on, and where is the NEXT one. The owner's Tusk
            # receipt: first spike = attention grabber (not the miss), base = the
            # entry, resolution spike = the exit pay, giveback = normal, moon not
            # required. Buys are preferred in base_accumulation once the path is
            # readable; scaleout biases resolution_spike, not base chop.
            # Heuristics v1 off a snapshot - "unknown" when the data won't support
            # a call. DISPLAY ONLY, gates nothing.
            **_phase_map_fields(_with_observer_peak(enrichment_input)),
            
            # v13.1 Drop 2: per-token Drop 2 tunable filter results (advisory)
            "drop2_filters": drop2_filter_results,
            
            # v13.1 Drop 2: snapshot of every active tunable's current state
            "current_filter_state": current_filter_state_block,
            
            # v13.1 Drop 2: the four immovable floors and whether each passed
            "hardcoded_checks": hardcoded_checks_block,
            
            # NEW v11.3: track surfacing source + hold-candidate status
            "surfaced_via": [surfaced_via],
            "hold_candidate": trending_is_hold_candidate(mint),
            "trending_track": _summarize_trending_for_packet(mint),
            "current_meta": load_current_meta(),  # what's the dominant narrative right now
            "meta_shift": load_meta_shift(),  # type share over 1h/4h/24h. never a buy.
            
            # NEW v11.3: shiller intel pulled from observed shillers (if any tracked)
            "shiller_intel": _gather_shiller_intel_for_mint(mint),
            
            # Sprint 28.7: wallet snapshot , the agent sees actual budget on every packet,
            # so sizing is concrete (0.05 SOL = $X), not blind percentages.
            "wallet_status": wallet_status,
            # Sprint 54 — THE MARKET WEATHER. Where we are in the cycle, as CONTEXT to
            # reason with, NOT a gate. The rotation stage matters most: MEME_SEASON means
            # capital is rotating into exactly what you trade. But remember — a memecoin
            # can run on pure absurdity regardless of any of this. The macro gives you the
            # odds; the TOKEN gives you the story, and the story is what runs.
            "market_weather": build_market_weather(),
            
            "vibe_assessment": _build_vibe_assessment(narrative, pattern, edge_filter),
            "signal_updates": [],
            "_packet_version": "v11.3",
        },
        
        "decision_inputs": _decision_inputs(_build_suggested_actions(edge_filter, pattern, narrative, rug_check, deployer_history)),
        "actions_taken": [],
    }

    # 0 to 100k in a few 1m candles is a coordinated pump. Strip the buy.
    try:
        from launch_spike import check_launch_spike as _check_launch_spike
        _spike = await asyncio.to_thread(_check_launch_spike, mint, pair)
    except Exception as _se:
        _spike = {"ok": False, "block": False, "reason": f"spike_check_error:{_se}"}
    packet.setdefault("context", {})["launch_spike"] = _spike
    # v1.0.3 fee-wallet vault: creator parked supply in its own fee wallet, not a bundle.
    if _spike.get("block"):
        try:
            import fee_vault as _fv
            _vv = await _fv.check_mint(mint, (deployer_history or {}).get("address"), helius_rpc)
            packet["context"]["fee_vault"] = _vv
            if _vv.get("vault"):
                _ft = _fv.float_top10_pct((holders or {}).get("top_holders") or [],
                                          _vv["vault_wallet"], _fv.TOTAL_SUPPLY_RAW_DEFAULT)
                packet["context"]["fee_vault"]["float_top10_pct"] = _ft
                _spike = {**_spike, "block": False, "vault_override": True,
                          "reason": f"{_spike.get('reason')} | overridden: fee-wallet vault "
                                    f"{_vv['vault_wallet'][:6]}… holds {_vv.get('vault_pct')}%"}
                packet["context"]["launch_spike"] = _spike
        except Exception as _fve:
            packet["context"]["fee_vault"] = {"vault": False, "reason": f"vault_check_error:{_fve}"}
    # 2026-10-15: the 1m-candle spike peak is truth; if it beats the observer/own
    # peak the provisional zone used, re-anchor the map on it (and remember it).
    try:
        _sp = float(_spike.get("peak_mcap") or 0)
        _ei = _with_observer_peak(enrichment_input)
        if _sp > float(_ei.get("peak_mcap") or 0):
            _card_peak_update(mint, _sp)
            packet["context"].update(_phase_map_fields({**_ei, "peak_mcap": _sp}))
    except Exception:
        pass
    if _spike.get("block"):
        _acts = [
            {"action_type": "avoid", "reasoning": _spike.get("reason") or "launch_spike"},
            {"action_type": "ignore", "reasoning": "too fast to 100k. bundle or coordinated pump. skip"},
            {"action_type": "view_chart", "reasoning": "the 1m candle is the tell"},
        ]
        packet["decision_inputs"] = _decision_inputs(_acts)
        packet["priority"] = "low"
    
    # Bump priority for high-edge tokens. A launch spike stays a skip.
    if not _spike.get("block"):
        if edge_filter.get("passes_full_filter") and edge_filter.get("unicorn_combo"):
            packet["priority"] = "high"
        elif edge_filter.get("edge_score", 0) >= 9:
            packet["priority"] = "high"
    
    # Sprint 28.3 post-packet bookkeeping (every passed-filter packet feeds these)
    
    # 1. Add to watchlist for 2h/24h re-evaluation
    watchlist_add(mint, {
        "ticker": base.get("symbol"),
        "name": base.get("name"),
        "mcap": mcap,
        "price_usd": _safe_num(pair.get("priceUsd")),
        "liquidity_usd": liq,
        "holder_count": (holders or {}).get("holder_count"),
        "edge_passed": edge_filter.get("passes_full_filter", False),
    })
    
    # 2. Log to passed_filter feed (missed-runner autopsy mines this)
    passed_filter_record(packet)
    
    # 3. If socials are completely thin → add to dex_paid watch
    has_any_social = bool(twitter_url or telegram_url or website_url)
    if not has_any_social:
        dex_paid_watch_add(mint, {
            "ticker": base.get("symbol"),
        })
    
    return packet


def _summarize_trending_for_packet(mint: str) -> dict:
    """Pull a compact trending_track summary for the packet's hold_candidate context."""
    tt = load_trending_track()
    entry = tt.get(mint)
    if not entry:
        return {"is_trending": False, "consecutive_top_10_hours": 0.0, "hold_threshold_hours": TRENDING_HOLD_THRESHOLD_HOURS}
    return {
        "is_trending": True,
        "consecutive_top_10_hours": entry.get("consecutive_top_10_hours", 0.0),
        "total_appearances": entry.get("total_appearances", 0),
        "hold_threshold_hours": TRENDING_HOLD_THRESHOLD_HOURS,
        "is_hold_candidate": entry.get("is_hold_candidate", False),
    }


def _gather_shiller_intel_for_mint(mint: str) -> dict:
    """
    Collect shiller-track intel for any handles already observed on this mint.
    Surfaces rug_rate + rug_pattern from the shiller_track file.
    """
    pending = load_shiller_pending()
    if mint not in pending:
        return {
            "tracked_shillers": [],
            "summary": "no_shillers_observed_yet",
        }
    
    shillers = pending[mint].get("shillers", [])
    if not shillers:
        return {"tracked_shillers": [], "summary": "no_shillers_observed_yet"}
    
    track = load_shiller_track()
    enriched = []
    rug_count = 0
    win_count = 0
    
    for handle in shillers:
        h = handle.lstrip("@").lower()
        s = track.get(h, {})
        rug_rate = s.get("rug_rate", 0.0)
        if rug_rate >= 0.6 and (s.get("rug_count", 0) >= 3):
            rug_count += 1
        if s.get("win_count", 0) >= 3 and rug_rate < 0.3:
            win_count += 1
        
        enriched.append({
            "handle": f"@{h}",
            "rug_rate": rug_rate,
            "rug_count": s.get("rug_count", 0),
            "win_count": s.get("win_count", 0),
            "rug_pattern": s.get("rug_pattern") or None,
            "tier_signal": (
                "frequent_rugger" if rug_rate >= 0.6 and s.get("rug_count", 0) >= 3
                else "frequent_winner" if s.get("win_count", 0) >= 3 and rug_rate < 0.3
                else "tracked"
            ),
        })
    
    if rug_count >= 1:
        summary = f"WARNING: {rug_count} of {len(shillers)} known shillers have rug pattern"
    elif win_count >= 1:
        summary = f"{win_count} of {len(shillers)} shillers have win pattern"
    else:
        summary = f"{len(shillers)} shillers observed, no strong pattern yet"
    
    return {
        "tracked_shillers": enriched,
        "summary": summary,
        "rugger_shiller_count": rug_count,
        "winner_shiller_count": win_count,
    }


def _build_vibe_assessment(narrative: dict, pattern: dict, edge_filter: dict) -> str:
    """Tag string summarizing the packet's overall vibe."""
    if narrative.get("is_first_launch") is False and narrative.get("prior_launch_summary"):
        return "relaunch_with_history"
    if pattern.get("classification") == "vertical_rug":
        return "rug_pattern_detected"
    if edge_filter.get("unicorn_combo"):
        return "unicorn_combo_active"
    if edge_filter.get("passes_full_filter"):
        return f"clean_{pattern.get('classification', 'pattern')}"
    # ── B (2026-08-08): "below_edge_floor" DELETED as the default ────────────
    # It stamped every non-perfect book as beneath a floor that does not exist -
    # The owner's only hard floor is mcap. TOAD went 5/6 with 11.7x vol/liq and wore
    # that label, and the desk read it as a kill. The label now reports how much
    # structure is actually present, which is the thing being measured.
    _cf = edge_filter.get("credit_frac")
    if _cf is None:
        return "edge_structure_unknown"
    if _cf >= 0.99:
        return "edge_structure_full"
    if _cf >= 0.8:
        return "edge_structure_strong"
    if _cf >= 0.5:
        return "edge_structure_mixed"
    return "edge_structure_weak"


def _compute_trade_pressure(pair: dict) -> dict:
    """
    Extract buy/sell pressure from DexScreener pair.txns counts.
    
    Returns a dict with buy/sell counts + ratios across timeframes,
    plus a derived `pressure_signal` tag for quick read.
    
    DexScreener provides:
      pair.txns.{m5, h1, h6, h24} = {buys, sells}
    """
    txns = pair.get("txns") or {}
    
    def _bucket(window_key: str) -> dict:
        bucket = txns.get(window_key) or {}
        buys = int(bucket.get("buys") or 0)
        sells = int(bucket.get("sells") or 0)
        total = buys + sells
        ratio = round(buys / sells, 2) if sells > 0 else (float(buys) if buys > 0 else 0.0)
        net_pct = round((buys - sells) / total * 100, 1) if total > 0 else 0
        return {
            "buys": buys,
            "sells": sells,
            "total_trades": total,
            "buy_ratio": ratio,  # >1 = more buys than sells
            "net_buy_pct": net_pct,  # +ve = buy-heavy, -ve = sell-heavy
        }
    
    m5 = _bucket("m5")
    h1 = _bucket("h1")
    h6 = _bucket("h6")
    h24 = _bucket("h24")
    
    # Derive an overall pressure signal
    # Look at recent windows (5m + 1h) primarily , they're the leading indicator
    if m5["total_trades"] >= 5:
        if m5["buy_ratio"] >= 2.0:
            pressure_signal = "strong_buy_pressure"
        elif m5["buy_ratio"] >= 1.3:
            pressure_signal = "buy_pressure"
        elif m5["buy_ratio"] <= 0.5:
            pressure_signal = "strong_sell_pressure"
        elif m5["buy_ratio"] <= 0.77:  # 1/1.3
            pressure_signal = "sell_pressure"
        else:
            pressure_signal = "balanced"
    elif h1["total_trades"] >= 10:
        if h1["buy_ratio"] >= 1.5:
            pressure_signal = "buy_pressure_h1"
        elif h1["buy_ratio"] <= 0.67:
            pressure_signal = "sell_pressure_h1"
        else:
            pressure_signal = "balanced_h1"
    else:
        pressure_signal = "low_activity"
    
    # Distribution detection: massive 24h volume + recent sell pressure = distribution
    is_distributing = (
        h24["total_trades"] >= 100 and
        m5["buy_ratio"] < 0.8 and
        m5["total_trades"] >= 5
    )
    
    # Sprint 45+ , no-two-sided-flow PRIMITIVE: buys with near-zero sells across the
    # leading windows = a one-sided tape (the painted-climb / can't-sell tell). This is
    # a primitive for the brain + the autopsy fingerprint , NOT a verdict, it does not block.
    _buys_lead  = m5["buys"] + h1["buys"]
    _sells_lead = m5["sells"] + h1["sells"]
    no_two_sided_flow = bool(_buys_lead >= 20 and _sells_lead <= max(2, _buys_lead * 0.02))
    
    return {
        "m5": m5,
        "h1": h1,
        "h6": h6,
        "h24": h24,
        "pressure_signal": pressure_signal,
        "is_distributing": is_distributing,
        "no_two_sided_flow": no_two_sided_flow,
    }


def _build_suggested_actions(edge_filter: dict, pattern: dict, narrative: dict, rug_check: dict, deployer_history: Optional[dict] = None) -> list[dict]:
    """
    Build the suggested_action_options list for the packet.
    
    HARD RULES per ca-intel skill v2.0:
      1. If rug_check.smart_check_verdict == "block" → NO fire_buy_signal action
         (Tier 4 safety: freeze auth, mint auth, honeypot)
      2. If deployer_history.rep == "scammer" → NO fire_buy_signal action
         (deployer has 3+ prior rugs)
    
    Args:
      edge_filter:        the owner's edge filter result
      pattern:            Pattern engine classification
      narrative:          Narrative intelligence dict
      rug_check:          Smart rug check dict (must include smart_check_verdict)
      deployer_history:   Optional deployer reputation dict
    """
    actions = []
    deployer_history = deployer_history or {}
    
    # ── HARD SAFETY GATE 1: rug check ──
    is_safety_blocked = (rug_check or {}).get("smart_check_verdict") == "block"
    block_reason = (rug_check or {}).get("block_reason")
    
    # ── HARD SAFETY GATE 2: deployer rep ──
    is_scammer_deployer = deployer_history.get("rep") == "scammer"
    deployer_addr_short = (deployer_history.get("address") or "")[:8]
    prior_rugs = deployer_history.get("prior_rugs", 0)
    
    if is_safety_blocked or is_scammer_deployer:
        # Build reason
        reasons = []
        if is_safety_blocked:
            reasons.append(f"rug_check: {block_reason or 'failed'}")
        if is_scammer_deployer:
            reasons.append(f"deployer {deployer_addr_short} has {prior_rugs} prior rugs")
        reason_text = "; ".join(reasons)
        
        actions.append({
            "action_type": "avoid",
            "reasoning": f"TIER 4 SAFETY BLOCK: {reason_text} , fire_buy_signal stripped"
        })
        actions.append({"action_type": "ignore", "reasoning": "skip per safety failure"})
        actions.append({"action_type": "view_chart", "reasoning": "see what the rugged shape looks like (data only)"})
        actions.append({"action_type": "view_packet", "reasoning": "review safety findings in detail"})
        return actions
    
    # ── Normal flow (safety passed) ──
    if edge_filter.get("passes_full_filter"):
        # Add deployer context to reasoning when available
        deployer_note = ""
        if deployer_history.get("rep") == "clean" and deployer_history.get("prior_winners", 0) > 0:
            deployer_note = f" (deployer: {deployer_history['prior_winners']} prior winners)"
        elif deployer_history.get("rep") == "mixed":
            deployer_note = f" (deployer mixed history: {prior_rugs} rugs / {deployer_history.get('prior_winners', 0)} wins)"
        
        actions.append({
            "action_type": "fire_buy_signal",
            "reasoning": f"clears the autopsy baseline on all gates , size by conviction{deployer_note}"
        })
    else:
        # Sprint 45+: edge is a REFERENCE, not a gate (meme-hunter skill). Below the
        # autopsy baseline on >=1 gate, but the call is the agent's , offer BOTH directions,
        # reference-framed, neither pre-selected. Safety (rug_check, above) is the only
        # hard gate; this read is advisory. No more auto-"ignore" verdict.
        _verdict = (edge_filter.get("owner_edge_verdict") or "")[:80]
        actions.append({
            "action_type": "fire_buy_signal",
            "reasoning": f"below autopsy baseline ({_verdict}) , override only if you read an edge the reference misses; size small"
        })
        actions.append({
            "action_type": "ignore",
            "reasoning": f"below baseline ({_verdict}) , skip if you agree with the reference"
        })
    
    # Chart on demand (local matplotlib + DexScreener PNG, fast)
    actions.append({"action_type": "view_chart", "reasoning": "see the shape before committing (local render)"})
    
    # Watch , auto-tracked by watchlist already; this just acknowledges
    actions.append({"action_type": "watch", "reasoning": "queue for 30min recheck (already auto-watched on filter pass)"})
    
    # Sprint 28.4: deep_research scopes , the agent picks à la carte, research responder works async (~30s-5min)
    actions.append({
        "action_type": "deep_research",
        "scopes": ["x"],
        "reasoning": "X account research only: followers, age, recent shillers (~1-2min)",
    })
    actions.append({
        "action_type": "deep_research",
        "scopes": ["web"],
        "reasoning": "Brave web search: chatter, scam reports, broader CT attention (~30s)",
    })
    actions.append({
        "action_type": "deep_research",
        "scopes": ["x", "web"],
        "reasoning": "X + web combined , full social/web check (~2-3min)",
    })
    # FIX 6: only offered when the vision pipeline actually answered the boot
    # smoke test. A button that is guaranteed to return scopes_failed is an
    # invitation to burn a research slot on a known-dead backend.
    if _VISION_HEALTH.get("ok", True):
        actions.append({
            "action_type": "deep_research",
            "scopes": ["chart_vision"],
            "reasoning": "Vision read on DexScreener UI screenshot , order book, recent trades, holder dist (~1min)",
        })
    actions.append({
        "action_type": "deep_research",
        "scopes": ["vibe_check"],
        "reasoning": "Vision read on token's website , check for low-effort 1-pager scams (~1min)",
    })
    if _VISION_HEALTH.get("ok", True):
        actions.append({
            "action_type": "deep_research",
            "scopes": ["x", "web", "chart_vision", "vibe_check"],
            "reasoning": "FULL: all 4 scopes , use when this might be the one (~3-5min)",
        })
    else:
        # Vision down: FULL drops the two vision scopes rather than promising four.
        actions.append({
            "action_type": "deep_research",
            "scopes": ["x", "web"],
            "reasoning": (f"FULL (reduced): vision pipeline is down "
                          f"({_VISION_HEALTH.get('why', '?')}), so chart_vision/vibe_check "
                          f"would return scopes_failed. X + web only (~2-3min)"),
        })
    
    # PvP check
    actions.append({"action_type": "pvp_check", "reasoning": "check if other tokens with similar ticker are also active"})
    
    # If unicorn combo (and not blocked), push fire_buy to top
    if edge_filter.get("unicorn_combo"):
        actions.insert(0, {
            "action_type": "fire_buy_signal",
            "reasoning": "UNICORN: x_dex_paid + meta_alignment (4/4 wins per backtest)",
        })
    
    return actions


# ═══════════════════════════════════════════════════════════════════════════
# ═══════════════════════════════════════════════════════════════════════════
#   CHAIN BIRTH LISTENER (fleet 2026-09-29)
# ═══════════════════════════════════════════════════════════════════════════
# DexScreener token-profiles is a social add-on. It is not a birth feed: a
# new mint that never buys a profile never shows up there. This listener
# hears creates on the programs below.
#
# Transport: logsSubscribe on the websocket for the RPC this bot already
# has (RPC_URL, https -> wss, same Helius key). That is not a new paid
# service. There is no separate websocket client in this file. If the
# socket cannot stay up, a cursor poll of getSignaturesForAddress +
# getTransaction walks the gap without skipping signatures inside the
# replay window. The poll is paced by helius_rpc. It does not read
# suggestions.json and it does not buy.
#
# Buys stay on agent_signals.json action=buy, rejected at the wallet
# floor inside execute_buy_signal. This loop still fetches when the
# wallet is at or under WALLET_FLOOR_SOL.
#
# Token-2022 creates are included (pump create_v2, LaunchLab
# initialize_with_token_2022, Meteora initialize_virtual_pool*). A birth
# packet uses surfaced_via=chain_birth so the graduation whitelist does
# not fail-closed a pre-bond result.

_BIRTH_CURSOR_FILE = _BOT_LOGS / "birth_listener_cursor.json"
_BIRTH_PROGRAMS = (
    {
        "program": "6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P",
        "label": "pump_fun",
        "tails": frozenset({"create", "createv2", "create_v2"}),
    },
    {
        "program": "pAMMBay6oceH9fJKBRHGP5D4bD4sWpmSwMn52FMfXEA",
        "label": "pumpswap",
        "tails": frozenset({"migrate", "create_pool", "createpool"}),
    },
    {
        "program": "LanMV9sAd7wArD4vJFi2qDdfnVhFxYSUg6eADduJ3uj",
        "label": "launchlab",
        "tails": frozenset({
            "initialize_v2", "initializev2",
            "initialize_with_token_2022", "initializewithtoken2022",
        }),
    },
    {
        "program": "dbcij3LWUppWqq96dh6gJWwBifmcGfLSB5D4DuSMaqN",
        "label": "meteora_dbc",
        # prefix: initialize_virtual_pool and token-2022 variants of that name
        "tails": frozenset({"initialize_virtual_pool", "initializevirtualpool"}),
        "prefix": True,
    },
)
_BIRTH_WSOL = "So11111111111111111111111111111111111111112"
_BIRTH_REPLAY_CAP = 400  # signatures per program walked after a restart; not full history
_birth_cursors: dict = {}
_birth_seen_sigs: set = set()
_birth_packeted: set = set()
_birth_pending: dict = {}
_birth_sem: Optional[asyncio.Semaphore] = None
_BIRTH_TASKS: set = set()


def _birth_active_programs() -> list:
    """v14: which programs the Helius socket/poll covers. PumpSwap swap-log
    subscription is off by default (it streamed every swap; PumpPortal's
    migration feed covers graduations)."""
    out = []
    for spec in _BIRTH_PROGRAMS:
        if spec["label"] == "pumpswap" and not BIRTH_PUMPSWAP_SUB:
            continue
        if LAUNCH_FEED in ("pumpportal", "both") and spec["label"] not in BIRTH_HELIUS_PROGRAMS:
            if not (LAUNCH_FEED == "both" and spec["label"] == "pump_fun"):
                continue
        if LAUNCH_FEED == "helius" and BIRTH_HELIUS_PROGRAMS and spec["label"] not in BIRTH_HELIUS_PROGRAMS:
            continue
        out.append(spec)
    return out


def _birth_ws_url() -> str:
    url = (RPC_URL or "").strip()
    if url.startswith("https://"):
        return "wss://" + url[len("https://"):]
    if url.startswith("http://"):
        return "ws://" + url[len("http://"):]
    return ""


def _birth_load_cursors() -> dict:
    try:
        with open(_BIRTH_CURSOR_FILE, encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _birth_save_cursors() -> None:
    try:
        _save_json_atomic(_BIRTH_CURSOR_FILE, _birth_cursors)
    except Exception as e:
        _log(f"birth: cursor save err: {e}", prefix="birth")


def _birth_remember_sig(sig: str) -> bool:
    """True if this signature is new."""
    if not sig or sig in _birth_seen_sigs:
        return False
    _birth_seen_sigs.add(sig)
    if len(_birth_seen_sigs) > 20000:
        # drop an arbitrary chunk; the cursor file is the durability, not this set
        for _old in list(_birth_seen_sigs)[:5000]:
            _birth_seen_sigs.discard(_old)
    return True


def _birth_instruction_hit(logs, program_id: str, tails: frozenset, prefix: bool = False) -> bool:
    """True when the watched program's own Instruction log matches a create/init.
    Stack-scoped so an ATA CreateIdempotent on Token-2022 is not a birth."""
    stack = []
    for line in logs or []:
        if not isinstance(line, str):
            continue
        if line.startswith("Program ") and " invoke" in line and not line.startswith("Program log"):
            parts = line.split()
            if len(parts) >= 3 and parts[2] == "invoke":
                stack.append(parts[1])
            continue
        if line.startswith("Program ") and line.endswith(" success") and not line.startswith("Program log"):
            parts = line.split()
            if len(parts) >= 2 and stack and stack[-1] == parts[1]:
                stack.pop()
            continue
        if "Instruction:" not in line:
            continue
        if not stack or stack[-1] != program_id:
            continue
        tail = line.split("Instruction:", 1)[1].strip().lower().replace(" ", "")
        if tail in tails:
            return True
        if prefix and any(tail.startswith(t) for t in tails):
            return True
    return False


def _birth_mints_from_tx(tx: dict) -> list:
    """SPL and Token-2022 mints. initializeMint* wins; else postTokenBalances."""
    if not isinstance(tx, dict):
        return []
    found = []

    def _walk(ix: dict) -> None:
        if not isinstance(ix, dict):
            return
        parsed = ix.get("parsed")
        if isinstance(parsed, dict):
            typ = str(parsed.get("type") or "").lower().replace("_", "")
            info = parsed.get("info") or {}
            if typ in ("initializemint", "initializemint2", "mintto", "minttochecked"):
                mint = info.get("mint")
                if mint:
                    found.append(mint)
        for child in ix.get("instructions") or []:
            _walk(child)

    msg = ((tx.get("transaction") or {}).get("message") or {})
    for ix in msg.get("instructions") or []:
        _walk(ix)
    meta = tx.get("meta") or {}
    for inner in meta.get("innerInstructions") or []:
        for ix in (inner or {}).get("instructions") or []:
            _walk(ix)
    if not found:
        for bal in meta.get("postTokenBalances") or []:
            if isinstance(bal, dict) and bal.get("mint"):
                found.append(bal["mint"])
    out = []
    seen = set()
    for mint in found:
        if not mint or mint == _BIRTH_WSOL or mint in seen:
            continue
        if any(mint == spec["program"] for spec in _BIRTH_PROGRAMS):
            continue
        seen.add(mint)
        out.append(mint)
    return out


async def _birth_fetch_tx(sig: str, free_only: bool = False) -> Optional[dict]:
    tx = await helius_rpc(
        "getTransaction",
        [sig, {
            "encoding": "jsonParsed",
            "maxSupportedTransactionVersion": TX_MAX_VERSION,
            "commitment": "confirmed",
        }],
        free_only=free_only,
    )
    return tx if isinstance(tx, dict) else None


async def _birth_consider(mint: str, label: str, sig: str) -> None:
    """Record the mint even when DexScreener has no profile yet. Packet only
    when a pair exists. Never buys. surfaced_via is chain_birth, not bonded."""
    try:
        record_seen_mint(mint, source=f"birth:{label}")
    except Exception as e:
        _log(f"birth: seen-ledger err {mint[:8]}: {e}", prefix="birth")
    if mint in _birth_packeted:
        return
    try:
        pair = await fetch_token_data(mint)
    except Exception:
        pair = None
    if not pair:
        slot = _birth_pending.get(mint) or {"tries": 0, "first": _now_ts()}
        slot["label"] = label
        slot["sig"] = sig
        slot["tries"] = int(slot.get("tries") or 0) + 1
        slot["last_try"] = _now_ts()
        _birth_pending[mint] = slot
        if len(_birth_pending) > BIRTH_PENDING_MAX:   # v14: bound the no-pair queue
            for _old in sorted(_birth_pending, key=lambda m: _birth_pending[m].get("first") or 0)[:len(_birth_pending) - BIRTH_PENDING_MAX]:
                _birth_pending.pop(_old, None)
        return
    _birth_pending.pop(mint, None)
    _birth_packeted.add(mint)
    # 2026-10-15: a "birth" must be new. An old mint that shows up in a chain tx
    # (e.g. PUMP at $3.6B via a routed swap) is not a launch - no candidate card.
    try:
        _pca = pair.get("pairCreatedAt")
        _age_h = ((_now_ts() - float(_pca) / 1000.0) / 3600.0) if _pca else None
        _mc = float(pair.get("marketCap") or pair.get("fdv") or 0)
        if (_age_h is not None and _age_h > float(get_override_sync("BIRTH_MAX_AGE_H", 6))) or (_age_h is None and _mc > 50_000_000):
            _log(f"birth: skip {mint[:8]} - not a birth (age {_age_h if _age_h is None else round(_age_h, 1)}h, mcap ${_mc:,.0f})", prefix="birth")
            return
    except Exception:
        pass
    # livefix: collapsed same-ticker clone -> no packet build (that build runs the
    # funder/dev/holder RPC lookups, ~5 getTransaction/s during a YO-style flood)
    try:
        if not _ticker_clone_ok((pair.get("baseToken") or {}).get("symbol"), mint):
            return
    except Exception:
        pass
    if len(_birth_packeted) > 8000:
        for _old in list(_birth_packeted)[:2000]:
            _birth_packeted.discard(_old)
    try:
        packet = await build_meme_candidate_packet(
            {
                "tokenAddress": mint,
                "chainId": "solana",
                "description": f"chain_birth:{label}",
            },
            surfaced_via="chain_birth",
        )
    except Exception as e:
        _log(f"birth: packet err {mint[:8]}: {e}", prefix="birth")
        return
    if not packet:
        return
    ctx = packet.get("context") or {}
    ctx["discovery_source"] = f"birth:{label}"
    ctx["birth_feed"] = True
    ctx["birth_signature"] = sig
    # do not rewrite surfaced_via to bonded
    packet["context"] = ctx
    try:
        write_meme_candidate_packet(packet)
        _log(f"birth: candidate {label} {mint[:8]} (no auto-buy)", prefix="birth")
    except Exception as e:
        _log(f"birth: write err {mint[:8]}: {e}", prefix="birth")


async def _birth_retry_pending() -> None:
    if not _birth_pending:
        return
    now = _now_ts()
    for mint, slot in list(_birth_pending.items()):
        age = now - float(slot.get("first") or now)
        if slot.get("tries", 0) >= 20 or age > 20 * 60:
            _birth_pending.pop(mint, None)
            continue
        if now - float(slot.get("last_try") or 0) < BIRTH_PENDING_RETRY_S:
            continue
        await _birth_consider(mint, slot.get("label") or "birth", slot.get("sig") or "")


async def _birth_on_logs(logs, sig: str, err) -> None:
    try:
        await _birth_on_logs_inner(logs, sig, err)
    except Exception as e:
        _log(f"birth: log handler err: {e}", prefix="birth")


async def _birth_on_logs_inner(logs, sig: str, err) -> None:
    if err or not sig:
        return
    touched = []
    blob = "\n".join(line for line in (logs or []) if isinstance(line, str))
    for spec in _BIRTH_PROGRAMS:
        if spec["program"] not in blob:
            continue
        _birth_cursors[spec["program"]] = {"signature": sig, "at": _now_iso()}
        if _birth_instruction_hit(logs, spec["program"], spec["tails"], bool(spec.get("prefix"))):
            touched.append(spec)
    if not touched:
        return
    if not _birth_remember_sig(sig):
        return
    global _birth_sem
    if _birth_sem is None:
        _birth_sem = asyncio.Semaphore(3)
    async with _birth_sem:
        tx = await _birth_fetch_tx(sig)
        if not tx:
            return
        mints = _birth_mints_from_tx(tx)
        if not mints:
            _log(f"birth: create log but no mint on {sig[:12]}", prefix="birth")
            return
        for spec in touched:
            for mint in mints:
                await _birth_consider(mint, spec["label"], sig)


async def _birth_replay_gap() -> None:
    """After restart, walk a bounded window of signatures newer than the saved
    cursor. Pages use `before` so a full page does not skip the older half."""
    for spec in _birth_active_programs():
        saved = (_birth_cursors.get(spec["program"]) or {}).get("signature")
        if not saved:
            sigs = await helius_rpc(
                "getSignaturesForAddress",
                [spec["program"], {"limit": 1, "commitment": "confirmed"}],
            )
            if isinstance(sigs, list) and sigs and isinstance(sigs[0], dict):
                _birth_cursors[spec["program"]] = {
                    "signature": sigs[0].get("signature"),
                    "at": _now_iso(),
                    "seeded": True,
                }
                _log(f"birth: seeded {spec['label']} at chain tip (no history replay)", prefix="birth")
            continue
        before = None
        walked = 0
        reached = False
        tip_sig = None
        page = None
        while walked < _BIRTH_REPLAY_CAP:
            opts = {"limit": 25, "commitment": "confirmed", "until": saved}
            if before:
                opts["before"] = before
            page = await helius_rpc("getSignaturesForAddress", [spec["program"], opts])
            if page is None and _sig_cursor_dead():
                _log(f"birth: saved cursor for {spec['label']} not found; reseeding at tip", prefix="birth")
                _birth_cursors.pop(spec["program"], None)
                tip_sig = None
                break
            if not isinstance(page, list) or not page:
                reached = True
                break
            if tip_sig is None and isinstance(page[0], dict):
                tip_sig = page[0].get("signature")
            for row in reversed(page):
                if not isinstance(row, dict):
                    continue
                sig = row.get("signature")
                if not sig or row.get("err"):
                    continue
                if not _birth_remember_sig(sig):
                    continue
                tx = await _birth_fetch_tx(sig)
                if not tx:
                    continue
                logs = (tx.get("meta") or {}).get("logMessages") or []
                if _birth_instruction_hit(logs, spec["program"], spec["tails"], bool(spec.get("prefix"))):
                    for mint in _birth_mints_from_tx(tx):
                        await _birth_consider(mint, spec["label"], sig)
            walked += len(page)
            if len(page) < 25:
                reached = True
                break
            before = page[-1].get("signature")
            if not before:
                break
        if reached and tip_sig:
            _birth_cursors[spec["program"]] = {"signature": tip_sig, "at": _now_iso()}
        elif not reached:
            _log(
                f"birth: replay cap {_BIRTH_REPLAY_CAP} on {spec['label']} — "
                f"older than this window was not walked",
                prefix="birth",
            )
    _birth_save_cursors()


async def _birth_ws_session() -> None:
    import websockets
    url = _birth_ws_url()
    if not url.startswith("ws"):
        raise RuntimeError("no rpc websocket url")
    async with websockets.connect(
        url, ping_interval=20, ping_timeout=20, max_size=8_000_000, close_timeout=5,
    ) as ws:
        for i, spec in enumerate(_birth_active_programs(), start=1):
            await ws.send(json.dumps({
                "jsonrpc": "2.0",
                "id": i,
                "method": "logsSubscribe",
                "params": [{"mentions": [spec["program"]]}, {"commitment": "confirmed"}],
            }))
        _log(
            "birth: logsSubscribe up (pump create/create_v2, pumpswap migrate/create_pool, "
            "launchlab initialize_v2 + token-2022, meteora initialize_virtual_pool). "
            "no auto-buy",
            prefix="birth",
        )
        _birth_fail_streak[0] = 0   # 2026-10-14: socket is up, reset poll backoff
        last_save = _now_ts()
        while True:
            try:
                raw = await asyncio.wait_for(ws.recv(), timeout=8)
                helius_meter("ws_stream", "birth_ws", credits=len(raw) / 1_000_000 * HELIUS_WS_CREDITS_PER_MB)
            except asyncio.TimeoutError:
                await _birth_retry_pending()
                await write_heartbeat("birth_listener", "listening", {
                    "transport": "logsSubscribe",
                    "pending_no_pair": len(_birth_pending),
                    "wallet_floor_still_fetches": True,
                })
                if _now_ts() - last_save > 30:
                    _birth_save_cursors()
                    last_save = _now_ts()
                continue
            try:
                msg = json.loads(raw)
            except Exception:
                continue
            if msg.get("method") != "logsNotification":
                continue
            value = ((msg.get("params") or {}).get("result") or {}).get("value") or {}
            logs = value.get("logs") or []
            sig = value.get("signature")
            err = value.get("err")
            if err or not sig:
                continue
            blob = "\n".join(line for line in logs if isinstance(line, str))
            hit = False
            for spec in _birth_active_programs():
                if spec["program"] not in blob:
                    continue
                _birth_cursors[spec["program"]] = {"signature": sig, "at": _now_iso()}
                if _birth_instruction_hit(logs, spec["program"], spec["tails"], bool(spec.get("prefix"))):
                    hit = True
            if hit:
                _task = asyncio.create_task(_birth_on_logs(logs, sig, None))
                _BIRTH_TASKS.add(_task)
                _task.add_done_callback(_BIRTH_TASKS.discard)


async def _birth_poll_fallback_once(specs: Optional[list] = None, free_only: bool = False) -> None:
    """Socket is down. One page per program, bookmarked with `before`, so a
    full page is continued next cycle instead of skipping the older sigs.
    v14: free_only keeps the fallback poll off Helius credits."""
    for spec in (specs if specs is not None else _birth_active_programs()):
        state = _birth_cursors.get(spec["program"]) or {}
        saved = state.get("signature")
        before = state.get("poll_before")
        opts = {"limit": 25, "commitment": "confirmed"}
        if saved:
            opts["until"] = saved
        if before:
            opts["before"] = before
        page = await helius_rpc("getSignaturesForAddress", [spec["program"], opts], free_only=free_only)
        if page is None and _sig_cursor_dead():
            _log(f"birth: cursor sig for {spec['label']} not found on node; resetting cursor", prefix="birth")
            state.pop("signature", None); state.pop("poll_before", None); state.pop("poll_tip", None)
            _birth_cursors[spec["program"]] = state
            continue
        if before is None and isinstance(page, list) and page and isinstance(page[0], dict):
            state["poll_tip"] = page[0].get("signature") or state.get("poll_tip")
        if not isinstance(page, list) or not page:
            state.pop("poll_before", None)
            if page == [] and saved:
                state["signature"] = saved
            _birth_cursors[spec["program"]] = state
            continue
        for row in reversed(page):
            if not isinstance(row, dict) or row.get("err"):
                continue
            sig = row.get("signature")
            if not sig or not _birth_remember_sig(sig):
                continue
            tx = await _birth_fetch_tx(sig, free_only=free_only)
            if not tx:
                continue
            logs = (tx.get("meta") or {}).get("logMessages") or []
            if _birth_instruction_hit(logs, spec["program"], spec["tails"], bool(spec.get("prefix"))):
                for mint in _birth_mints_from_tx(tx):
                    await _birth_consider(mint, spec["label"], sig)
        if len(page) < 25:
            newest = state.get("poll_tip") or (page[0].get("signature") if isinstance(page[0], dict) else None)
            if newest:
                state["signature"] = newest
            state.pop("poll_before", None)
            state.pop("poll_tip", None)
        else:
            state["poll_before"] = page[-1].get("signature")
            _log(f"birth: poll {spec['label']} page full; bookmark held so the gap is not skipped", prefix="birth")
        state["at"] = _now_iso()
        _birth_cursors[spec["program"]] = state
    _birth_save_cursors()


_birth_fail_streak = [0]


async def _birth_pumpportal_loop() -> None:
    """v14 (2026-10-14): free PumpPortal websocket for pump.fun creates +
    migrations. No Helius credits. On disconnect, one free-RPC poll page of the
    pump program (LAUNCH_POLL_FALLBACK) and exponential reconnect."""
    import websockets
    fails = 0
    pump_spec = [s for s in _BIRTH_PROGRAMS if s["label"] == "pump_fun"]
    while True:
        try:
            async with websockets.connect(PUMPPORTAL_WS_URL, ping_interval=20, ping_timeout=20,
                                          max_size=2_000_000, close_timeout=5) as ws:
                if PUMPPORTAL_SUB_NEW_TOKENS:
                    await ws.send(json.dumps({"method": "subscribeNewToken"}))
                if PUMPPORTAL_SUB_MIGRATIONS:
                    await ws.send(json.dumps({"method": "subscribeMigration"}))
                _log("birth: PumpPortal feed up (new tokens + migrations, free). no auto-buy", prefix="birth")
                fails = 0
                seen = 0
                last_hb = 0.0
                while True:
                    try:
                        raw = await asyncio.wait_for(ws.recv(), timeout=30)
                    except asyncio.TimeoutError:
                        raw = None
                    if raw:
                        try:
                            msg = json.loads(raw)
                        except Exception:
                            msg = {}
                        mint = msg.get("mint") if isinstance(msg, dict) else None
                        if mint:
                            sig = str(msg.get("signature") or "")
                            if not sig or _birth_remember_sig(sig):
                                txt = str(msg.get("txType") or "").lower()
                                label = ("pumpportal_migrate" if txt == "migrate"
                                         else f"pumpportal_{msg.get('pool') or 'pump'}")
                                seen += 1
                                if txt == "migrate":
                                    _t = asyncio.create_task(_birth_consider(mint, label, sig))
                                    _BIRTH_TASKS.add(_t)
                                    _t.add_done_callback(_BIRTH_TASKS.discard)
                                else:
                                    # brand-new create: no Dex pair yet. Record + queue; the
                                    # paced pending retry asks Dex later instead of now.
                                    try:
                                        record_seen_mint(mint, source=f"birth:{label}")
                                    except Exception:
                                        pass
                                    if mint not in _birth_packeted and mint not in _birth_pending:
                                        _birth_pending[mint] = {"tries": 0, "first": _now_ts(),
                                                                "last_try": _now_ts(), "label": label, "sig": sig}
                                        if len(_birth_pending) > BIRTH_PENDING_MAX:
                                            _old = min(_birth_pending, key=lambda m: _birth_pending[m].get("first") or 0)
                                            _birth_pending.pop(_old, None)
                    if _now_ts() - last_hb > 15:
                        last_hb = _now_ts()
                        await _birth_retry_pending()
                        await write_heartbeat("birth_listener", "listening", {
                            "transport": "pumpportal_ws", "events_seen": seen,
                            "pending_no_pair": len(_birth_pending),
                            "wallet_floor_still_fetches": True,
                        })
        except Exception as e:
            fails += 1
            _log(f"birth: PumpPortal down ({type(e).__name__}: {e}); fallback={LAUNCH_POLL_FALLBACK}", prefix="birth")
            if LAUNCH_POLL_FALLBACK != "off" and pump_spec:
                try:
                    await _birth_poll_fallback_once(specs=pump_spec, free_only=(LAUNCH_POLL_FALLBACK == "free"))
                    await _birth_retry_pending()
                except Exception as pe:
                    _log(f"birth: poll err: {pe}", prefix="birth")
            await write_heartbeat("birth_listener", "polling", {"transport": "pumpportal_reconnect"})
            await asyncio.sleep(min(5 * (2 ** min(fails - 1, 5)), 120))


async def birth_listener_loop() -> None:
    """Chain birth feed. Fetches even when the wallet is at or under the floor.
    Does not buy. Does not poll suggestions.json.
    v14: LAUNCH_FEED=pumpportal (default, free) | helius | both."""
    _log(f"birth: listener starting feed={LAUNCH_FEED} helius_programs="
         f"{[s['label'] for s in _birth_active_programs()]} (fetch continues at wallet floor; buys do not)",
         prefix="birth")
    _birth_cursors.update(_birth_load_cursors())
    jobs = []
    if LAUNCH_FEED in ("pumpportal", "both"):
        jobs.append(_birth_pumpportal_loop())
    if LAUNCH_FEED in ("helius", "both") or _birth_active_programs():
        if _birth_active_programs():
            jobs.append(_birth_helius_loop())
    if not jobs:
        jobs.append(_birth_pumpportal_loop())
    await asyncio.gather(*jobs)


async def _birth_helius_loop() -> None:
    if LAUNCH_REPLAY_ON_BOOT:
        try:
            await _birth_replay_gap()
        except Exception as e:
            _log(f"birth: replay err (listener still starts): {e}", prefix="birth")
    while True:
        try:
            await write_heartbeat("birth_listener", "connecting", {"transport": "logsSubscribe"})
            await _birth_ws_session()
        except Exception as e:
            _log(f"birth: websocket down ({type(e).__name__}: {e}); polling program logs", prefix="birth")
            try:
                if LAUNCH_POLL_FALLBACK != "off":
                    await _birth_poll_fallback_once(free_only=(LAUNCH_POLL_FALLBACK == "free"))
                await _birth_retry_pending()
            except Exception as pe:
                _log(f"birth: poll err: {pe}", prefix="birth")
            await write_heartbeat("birth_listener", "polling", {"transport": "signature_poll"})
            # 2026-10-14: this loop was the top getSignaturesForAddress caller
            # (ws reconnect + poll every 5s straight into 429s). Back off while
            # the socket keeps failing, and longer while RPC is unhealthy.
            _birth_fail_streak[0] = min(_birth_fail_streak[0] + 1, 6)
            _wait = min(5 * (2 ** (_birth_fail_streak[0] - 1)), 60)
            if rpc_is_unhealthy():
                _wait = max(_wait, 60)
            await asyncio.sleep(_wait)


