async def scanner_loop() -> None:
    """
    Main scanner loop — bonded tokens -> meme_candidate packets.

    ── FIX 9 (2026-08-15): THIS DESCRIBED A DELETED DESIGN ─────────────────────
    It said "15min tick during active hours, 60min during off-hours". There is no
    off-hours cadence: clock-based switching was removed in Sprint 45 and
    SCAN_TICK_OFFHOURS_SECONDS was deleted 2026-07-27 as "old design". The live
    base is SCAN_TICK_SECONDS_DEFAULT = 15min, ADAPTIVE from there — the running
    log says "next scan in 45min (base=900s mode=reduced decline_rate=0.442)",
    which no reading of this docstring would have predicted.

    LIVE BEHAVIOUR:
      base cadence : SCAN_TICK_SECONDS_DEFAULT = 15min, one cadence, no clock split
      adaptive     : stretches on a declining tape (mode=reduced), the agent can raise it
      source       : DexScreener token-profiles as a social/bonded add-on, not the only birth feed
      sole filter  : mcap >= MCAP_FLOOR_USD ($10k) — plus the bonded dexId gate
                     (2026-08-15), which rejects a prebond profile claiming bonded
      cap          : SCAN_PACKETS_PER_CYCLE_CAP = None — every bonded token over the
                     floor fires, there is no per-cycle limit
      wallet floor : this DexScreener cycle is skipped. The old line said scanning continues; that was false. Buys are rejected in execute_buy_signal. The chain birth listener still fetches.

    Processes up to 5 profiles concurrently per cycle to keep cycle time short
    even when Ollama enrichment is slow (5-10s per call on CPU).
    """
    _log("scanner: starting", prefix="scan")
    
    SCANNER_CONCURRENCY = 5  # how many profiles to enrich in parallel
    sem = asyncio.Semaphore(SCANNER_CONCURRENCY)
    
    async def _process_profile(profile: dict) -> tuple[str, Optional[str]]:
        """Returns ('written'|'filtered'|'error', mint_or_error_str)."""
        async with sem:
            try:
                packet = await build_meme_candidate_packet(profile)
                if packet is None:
                    return ("filtered", profile.get("tokenAddress", "?")[:8])
                write_meme_candidate_packet(packet)
                return ("written", packet["context"]["mint"])
            except Exception as e:
                mint_short = profile.get("tokenAddress", "?")[:8]
                _log(f"scanner: error processing {mint_short}: {e}", prefix="scan")
                return ("error", f"{mint_short}: {e}")
    
    while True:
        # Sprint 32: respect SCANNER_PAUSED meeting override
        if await get_override("SCANNER_PAUSED", False):
            await write_heartbeat("scanner", "paused", {"paused_via": "meeting_override"})
            _log("scanner: PAUSED via meeting override, sleeping 60s before recheck", prefix="scan")
            await asyncio.sleep(60)
            continue
        
        # v13.0: wallet floor check (replaces the old should_halt_trading drawdown gate)
        if not await check_wallet_floor_or_skip("scanner"):
            await write_heartbeat("scanner", "paused", {"paused_via": "wallet_floor"})
            await asyncio.sleep(60)
            continue
        
        cycle_start = _now_ts()
        active = is_active_hours()
        await write_heartbeat("scanner", "scanning", {"active_hours": active})

        # Sprint 65: the DEX-top digest is now fetched DIRECTLY from the DexScreener API
        # at cycle end (build_dex_top_digest) — no scraper, no Cloudflare, no snapshot.
        # (The old _trigger_dex_top_scrape() is gone; the scraper's browser is CF-blocked.)
        
        try:
            profiles = await fetch_bonded_pairs()
            _log(f"scanner: fetched {len(profiles)} bonded profiles (active_hours={active})", prefix="scan")

            # Sprint 53 — DISCOVERY LEDGER. Record every mint that enters our field of
            # view, BEFORE any filtering. This is what makes "never seen" meaningful: a
            # runner absent from this ledger is a pure discovery blind spot (we never
            # looked at it), not a filter miss (we looked and declined). Without this,
            # the system can only ever learn that its filters were wrong — never that
            # its discovery was blind.
            for _p in profiles:
                try:
                    _pm = _p.get("tokenAddress") or _p.get("mint")
                    if _pm:
                        record_seen_mint(_pm, source="scanner_bonded")
                except Exception:
                    pass
            
            # Process all profiles concurrently with semaphore-bounded parallelism
            results = await asyncio.gather(
                *[_process_profile(p) for p in profiles],
                return_exceptions=True,
            )
            
            written = sum(1 for r in results if isinstance(r, tuple) and r[0] == "written")
            filtered_out = sum(1 for r in results if isinstance(r, tuple) and r[0] == "filtered")
            errors = sum(1 for r in results if isinstance(r, tuple) and r[0] == "error") + \
                     sum(1 for r in results if isinstance(r, Exception))
            
            elapsed = _now_ts() - cycle_start
            _log(
                f"scanner: cycle done in {elapsed:.1f}s , wrote {written} packets, "
                f"filtered {filtered_out}, errors {errors} "
                f"(concurrency={SCANNER_CONCURRENCY})",
                prefix="scan",
            )

            # Sprint 65: build the DEX-top digest now — the scrape fired at cycle top
            # has had the whole sweep to finish, so the snapshot is fresh. Backstop view
            # of the top Solana tokens in case the scanner filtered/missed one.
            try:
                await build_dex_top_digest()
            except Exception as _dte:
                _log(f"dex_top digest build skipped: {_dte}", prefix="dex_top")
            
            _tput_hb = {}
            try:
                _tput_hb = load_throughput_state() or {}
            except Exception:
                _tput_hb = {}
            await write_heartbeat("scanner", "idle", {
                "last_cycle_at": _now_iso(),
                "last_cycle_seconds": round(elapsed, 1),
                "last_cycle_packets_written": written,
                "last_cycle_filtered_out": filtered_out,
                "last_cycle_errors": errors,
                "active_hours": active,
                "reduced_mode": bool(_tput_hb.get("reduced_mode")),
                "trip_reason": _tput_hb.get("trip_reason") or _tput_hb.get("trip"),
                "scan_sleep_s": next_scan_interval_seconds(),
            })
            
            # Sprint 28.7: refresh wallet snapshot in heartbeat after each scan cycle.
            # Writes to "wallet" component so any heartbeat reader sees current SOL+USD.
            try:
                wallet_status_hb = await get_wallet_status_block()
                await write_heartbeat("wallet", "tracked", {
                    "wallet_sol": wallet_status_hb.get("wallet_sol"),
                    "wallet_usd": wallet_status_hb.get("wallet_usd"),
                    "sol_price_usd": wallet_status_hb.get("sol_price_usd"),
                    "size_scale_anchor_sol": wallet_status_hb.get("size_scale_anchor_sol"),
                    "drawdown_pct": wallet_status_hb.get("drawdown_pct"),
                    "current_max_entry_sol": wallet_status_hb.get("current_max_entry_sol"),
                    "halt_status": wallet_status_hb.get("halt_status"),
                    "_price_source": wallet_status_hb.get("_price_source"),
                })
            except Exception as e:
                _log(f"scanner: wallet heartbeat update error (non-fatal): {e}", prefix="scan")
        except Exception as e:
            _log(f"scanner: cycle error: {e}", prefix="scan")
            await write_heartbeat("scanner", "error", {"last_error": str(e)[:200]})
        
        # Sleep based on current active state (re-check after cycle completed)
        sleep_seconds = next_scan_interval_seconds()
        _tp = load_throughput_state()
        _mode = "reduced" if _tp.get("reduced_mode") else "normal"
        _log(f"scanner: next scan in {sleep_seconds // 60}min "
             f"(base={get_override_sync('SCAN_TICK_SECONDS', SCAN_TICK_SECONDS_DEFAULT)}s "
             f"mode={_mode} decline_rate={_tp.get('decline_rate')})", prefix="scan")
        await asyncio.sleep(sleep_seconds)


