async def apply_default_params_to_position(sig_id: str, req: dict) -> None:
    """1h grace period expired , apply fallback defaults to the position."""
    mint = req.get("mint")
    missing = req.get("missing_params") or []
    
    positions = load_positions()
    position = positions.get(mint)
    if not position:
        return
    
    # config-vs-code (fallback config-read cascade 2026-08-02): trail + max_hold must
    # resolve LIVE via override at write, never a stale FALLBACK twin, else grace-expired
    # positions inherit the old loose exits (the 20/25 lock the agent already patched once).
    _overlay = {
        "trail_drop_pct":     lambda: get_override_sync("DEFAULT_TRAIL_DROP_PCT", DEFAULT_TRAIL_DROP_PCT),
        "trail_activate_pct": lambda: get_override_sync("DEFAULT_TRAIL_ACTIVATE_PCT", DEFAULT_TRAIL_ACTIVATE_PCT),
        "max_hold_hours":     lambda: get_override_sync("DEFAULT_MAX_HOLD_MINUTES", DEFAULT_MAX_HOLD_MINUTES) / 60.0,
    }
    for p in missing:
        if p not in position.get("params", {}):
            if p in _overlay:
                position.setdefault("params", {})[p] = _overlay[p]()
            elif p in FALLBACK_DEFAULTS:
                position.setdefault("params", {})[p] = FALLBACK_DEFAULTS[p]
    position["params_pending_user_input"] = []
    upsert_position(mint, position)
    
    _log(f"executor: applied defaults to {position.get('ticker')} after grace expired", prefix="exec")
    await send_telegram(f"⏱️ Param defaults applied to {position.get('ticker')} after 1h grace")


# ═══════════════════════════════════════════════════════════════════════════
#                    POSITION MONITOR LOOP (60s / 30s tick)
# ═══════════════════════════════════════════════════════════════════════════

async def open_bag_price_loop() -> None:
    """Price-only watch for open bags. Idle book does nothing but sleep.

    Full position_monitor_loop stays on the 60s tick (rug, holders, quote).
    This loop only hits DexScreener. A 15pt move vs the last fast sample
    calls check_position now, so a wick is not invisible until the next
    full pass. No Jupiter quote unless that jump actually fires.
    """
    _log("open-bag price: starting", prefix="open-bag")
    last_mark: dict[str, float] = {}
    while True:
        try:
            positions = load_positions() or {}
            live = set(positions)
            for gone in list(last_mark):
                if gone not in live:
                    last_mark.pop(gone, None)
            if not positions:
                await asyncio.sleep(OPEN_BAG_PRICE_TICK_S)
                continue
            for mint, position in list(positions.items()):
                entry = float(position.get("entry_price") or 0)
                if entry <= 0:
                    continue
                pair = await fetch_token_data(mint)
                px = float((pair or {}).get("priceUsd") or 0)
                if px <= 0:
                    continue
                mark = ((px - entry) / entry) * 100
                prev = last_mark.get(mint)
                if prev is None:
                    last_mark[mint] = mark
                    continue
                if abs(mark - prev) < OPEN_BAG_JUMP_PCT:
                    continue
                ticker = position.get("ticker", "?")
                _log(
                    f"jump {ticker} mark {prev:+.1f}% -> {mark:+.1f}% "
                    f"(band {OPEN_BAG_JUMP_PCT:.0f}), checking now",
                    prefix="open-bag",
                )
                last_mark[mint] = mark
                try:
                    fresh = (load_positions() or {}).get(mint) or position
                    await check_position(mint, fresh)
                except Exception as e:
                    _log(f"open-bag check err {ticker}: {e}", prefix="open-bag")
        except Exception as e:
            _log(f"open-bag price loop err: {e}", prefix="open-bag")
        await asyncio.sleep(OPEN_BAG_PRICE_TICK_S)


def _position_tick_s() -> float:
    try:
        v = float(get_override_sync("POSITION_TICK_S", POSITION_TICK_S) or POSITION_TICK_S)
    except Exception:
        v = POSITION_TICK_S
    return max(5.0, min(300.0, v))


def _protection_card_block(position: dict, pnl_pct: Optional[float] = None) -> dict:
    """What the agent needs on every position card to size his own SL/TP."""
    ap = position.get("armed_protection") or {}
    now = _now_ts()
    last_check = float(position.get("last_agent_check_ts") or ap.get("set_at_ts") or 0)
    tick = _position_tick_s()
    buf = tick + AGENT_INBOX_CADENCE_S + PROTECT_EXEC_BUFFER_S
    armed = bool(ap) and (ap.get("sl_pct") is not None or ap.get("tp_pct") is not None)
    mins = round((now - last_check) / 60, 1) if last_check else None
    return {
        "armed": armed,
        "stop_loss_pct": ap.get("sl_pct"),
        "take_profit_pct": ap.get("tp_pct"),
        "take_profit_sell_pct": ap.get("tp_sell_pct"),
        "sl_fired_at": ap.get("sl_fired_at"),
        "tp_fired_at": ap.get("tp_fired_at"),
        "set_at": ap.get("set_at"),
        "minutes_since_last_agent_check": mins,
        "stale": bool(mins is not None and mins > PROTECT_STALE_MIN),
        "distance_to_sl_pts": (round(pnl_pct + abs(float(ap["sl_pct"])), 2)
                               if (armed and ap.get("sl_pct") is not None and pnl_pct is not None) else None),
        "position_check_cadence_s": tick,
        "inbox_cadence_s": AGENT_INBOX_CADENCE_S,
        "alert_buffer_s": round(buf, 1),
        "required": True,
        "how": ("send action=set_protection with stop_loss_pct + take_profit_pct (optional "
                "take_profit_sell_pct). Required on every position touch. Size the stop wider than "
                "a normal move over alert_buffer_s."),
        "missing": not armed,
    }


def _protect_parse(sig: dict, position: dict) -> dict:
    entry = float(position.get("entry_price") or 0)
    sl = sig.get("stop_loss_pct", sig.get("sl_pct"))
    tp = sig.get("take_profit_pct", sig.get("tp_pct"))
    if sl is None and sig.get("stop_price_usd") and entry > 0:
        sl = (entry - float(sig["stop_price_usd"])) / entry * 100
    if tp is None and sig.get("take_profit_price_usd") and entry > 0:
        tp = (float(sig["take_profit_price_usd"]) - entry) / entry * 100
    out = {}
    if sl is not None:
        out["sl_pct"] = round(abs(float(sl)), 2)
    if tp is not None:
        out["tp_pct"] = round(float(tp), 2)
    tsp = sig.get("take_profit_sell_pct", sig.get("tp_sell_pct"))
    out["tp_sell_pct"] = max(1.0, min(100.0, float(tsp))) if tsp is not None else 100.0
    return out


async def _arm_default_exits(sig: dict, mint: str, sig_id: str) -> bool:
    sl, tp = _knob_f("SNIPER_DEFAULT_SL_PCT"), _knob_f("SNIPER_DEFAULT_TP_PCT")
    if (sl <= 0 and tp <= 0) or _sig_has_protection(sig):
        return False
    pos = (load_positions() or {}).get(mint) or {}
    if not pos or pos.get("armed_protection"):
        return False
    d = {"signal_id": f"{sig_id}-default-exits", "mint": mint,
         "reasoning": "owner default exits (SNIPER_DEFAULT_SL_PCT / SNIPER_DEFAULT_TP_PCT)"}
    if sl > 0:
        d["stop_loss_pct"] = sl
    if tp > 0:
        d["take_profit_pct"] = tp
    return await execute_set_protection(d, respond=False)


def _sig_has_protection(sig: dict) -> bool:
    return any(sig.get(k) is not None for k in (
        "stop_loss_pct", "sl_pct", "take_profit_pct", "tp_pct", "stop_price_usd", "take_profit_price_usd"))


async def execute_set_protection(sig: dict, *, respond: bool = True, errors_out: Optional[list] = None) -> bool:
    """action=set_protection: The agent arms (or updates / disarms) his SL/TP.
    v1.0.8: errors_out (if given) collects the rejection reason so a respond=False caller can report it."""
    _eo = errors_out if errors_out is not None else []
    sig_id = sig.get("signal_id") or _now_iso()
    mint = sig.get("mint")
    positions = load_positions() or {}
    position = positions.get(mint) if mint else None
    if not position:
        _eo.append("no_position_for_mint")
        if respond:
            await write_signal_response(sig_id, "rejected", error="no_position_for_mint")
        return False
    if sig.get("disarm"):
        position.pop("armed_protection", None)
        position["last_agent_check_ts"] = _now_ts()
        upsert_position(mint, position)
        if respond:
            await write_signal_response(sig_id, "protection_disarmed", error=None)
        return True
    try:
        p = _protect_parse(sig, position)
    except Exception as e:
        _eo.append(f"bad_protection_values: {e}")
        if respond:
            await write_signal_response(sig_id, "rejected", error=f"bad_protection_values: {e}")
        return False
    errs = []
    if "sl_pct" in p and not (PROTECT_SL_MIN_PCT <= p["sl_pct"] <= PROTECT_SL_MAX_PCT):
        errs.append(f"stop_loss_pct must be {PROTECT_SL_MIN_PCT}-{PROTECT_SL_MAX_PCT}")
    if "tp_pct" in p and p["tp_pct"] < PROTECT_TP_MIN_PCT:
        errs.append(f"take_profit_pct must be >= {PROTECT_TP_MIN_PCT}")
    if "sl_pct" not in p and "tp_pct" not in p:
        errs.append("need stop_loss_pct and/or take_profit_pct")
    if errs:
        _eo.extend(errs)
        if respond:
            await write_signal_response(sig_id, "rejected", error="; ".join(errs))
        return False
    prev = position.get("armed_protection") or {}
    ap = {**prev, **p, "set_at": _now_iso(), "set_at_ts": _now_ts(), "signal_id": sig_id,
          "set_by": "agent", "reason": str(sig.get("reasoning") or sig.get("reason") or "")[:300]}
    if "sl_pct" in p:
        ap.pop("sl_fired_at", None); ap["sl_attempts"] = 0
    if "tp_pct" in p:
        ap.pop("tp_fired_at", None); ap["tp_attempts"] = 0
    position["armed_protection"] = ap
    position["last_agent_check_ts"] = _now_ts()
    position.pop("protection_missing_since", None)
    upsert_position(mint, position)
    _log(f"protect: {position.get('ticker','?')} armed by the agent SL -{ap.get('sl_pct')}% "
         f"TP +{ap.get('tp_pct')}% (sell {ap.get('tp_sell_pct')}%)", prefix="protect")
    if respond:
        await write_signal_response(sig_id, "protection_armed", error=None)
    return True


_PROTECT_LEVEL_KEYS = ("stop_loss_pct", "sl_pct", "take_profit_pct", "tp_pct", "take_profit_sell_pct",
                       "stop_price_usd", "take_profit_price_usd")


def write_protection_missing_packet(mint: str, sig: dict, errors: list, *, source: str = "buy") -> None:
    """v1.0.8: SL/TP sent with a buy (or another position touch) failed to arm. Tell the
    agent which levels and why, instead of leaving the bag on the alert-only default."""
    sig = sig or {}
    sig_id = sig.get("signal_id") or sig.get("id") or ""
    try:
        pos = (load_positions() or {}).get(mint) or {}
    except Exception:
        pos = {}
    ticker = pos.get("ticker") or sig.get("ticker") or "?"
    sent = {k: sig.get(k) for k in _PROTECT_LEVEL_KEYS if sig.get(k) is not None}
    reason = "; ".join(str(e) for e in (errors or [])) or "unknown"
    _mode = str(pos.get("mode") or (pos.get("params") or {}).get("mode") or "flip").lower()
    guard = ("default flip stop is guarding the bag and will sell" if (PROTECT_DEFAULT_STOP and _mode == "flip"
             and not pos.get("own_launch")) else "NO protective sell is armed")
    _log(f"protect: {ticker} SL/TP from {source} NOT armed ({reason}) sent={sent} - {guard}", prefix="protect")
    try:
        _append_jsonl(_BOT_LOGS / "protection_missing.jsonl",
                      {"ts": _now_iso(), "mint": mint, "ticker": ticker, "action": source,
                       "signal_id": sig_id, "sent_levels": sent, "reason": reason})
    except Exception:
        pass
    try:
        write_inbox_packet_generic({
            "id": f"x_evt_protection_missing_{(mint or '')[:8]}_{int(_now_ts())}",
            "type": "protection_missing",
            "received_at": _now_iso(),
            "priority": "high",
            "originating_signal_id": sig_id,
            "context": {"mint": mint, "ticker": ticker, "source": source, "originating_signal_id": sig_id,
                        "sent_levels": sent, "reason": reason,
                        "bounds": {"stop_loss_pct": [PROTECT_SL_MIN_PCT, PROTECT_SL_MAX_PCT],
                                   "take_profit_pct_min": PROTECT_TP_MIN_PCT},
                        "guard": guard,
                        "note": "Your SL/TP did not arm. Re-send set_protection with valid levels."},
        }, prefix="evt", identifier=f"protection_missing_{(mint or '')[:8]}")
    except Exception as e:
        _log(f"protection_missing packet err: {e}", prefix="protect")


async def _protect_exhausted_alert(mint: str, position: dict, kind: str, pnl_pct: float, state_key: str) -> None:
    """v1.0.8: an armed level is breached but PROTECT_MAX_RETRIES sells all failed. Say so once."""
    st = position.get(state_key) or {}
    if st.get(f"{kind}_exhausted_alerted_at"):
        return
    st[f"{kind}_exhausted_alerted_at"] = _now_iso()
    position[state_key] = st
    upsert_position(mint, position)
    ticker = position.get("ticker", "?")
    _log(f"protect: {ticker} {kind.upper()} breached at {pnl_pct:+.1f}% but {PROTECT_MAX_RETRIES} sell "
         f"attempts failed - alerting the agent", prefix="protect")
    try:
        write_inbox_packet_generic({
            "id": f"x_evt_protect_exhausted_{kind}_{mint[:8]}_{int(_now_ts())}",
            "type": "protective_order_exhausted",
            "received_at": _now_iso(),
            "priority": "high",
            "context": {"mint": mint, "ticker": ticker, "leg": kind, "pnl_pct": round(pnl_pct, 2),
                        "attempts": int(st.get(f"{kind}_attempts") or 0), "max_retries": PROTECT_MAX_RETRIES,
                        "source": "default_flip_stop" if state_key == "default_protection" else "agent_armed",
                        "note": "The armed sell failed every retry. Bag is still open. Decide: sell, re-arm or hold."},
        }, prefix="evt", identifier=f"protect_exhausted_{kind}_{mint[:8]}")
    except Exception as e:
        _log(f"protect exhausted packet err: {e}", prefix="protect")
    try:
        await send_telegram(f"🚨 <b>PROTECTIVE SELL FAILED — {ticker}</b>\n{kind.upper()} breached at "
                            f"{pnl_pct:+.1f}%, {PROTECT_MAX_RETRIES} sell attempts failed. Bag still open.")
    except Exception:
        pass


async def _check_armed_protection(mint: str, position: dict, pnl_pct: float,
                                  params: Optional[dict] = None, mcap_now: float = 0) -> bool:
    """Returns True if a agent-armed level (or, v1.0.8, the default flip stop) fired a sell this tick."""
    if not PROTECT_ENFORCE:
        return False
    ap = position.get("armed_protection") or {}
    state_key = "armed_protection"
    leg = None
    if ap.get("sl_pct") is not None and not ap.get("sl_fired_at") and pnl_pct <= -abs(float(ap["sl_pct"])):
        leg = ("sl", 100.0, "agent_armed_stop")
    elif ap.get("tp_pct") is not None and not ap.get("tp_fired_at") and pnl_pct >= float(ap["tp_pct"]):
        leg = ("tp", float(ap.get("tp_sell_pct") or 100.0), "agent_armed_take_profit")
    if not leg and ap.get("sl_pct") is None and PROTECT_DEFAULT_STOP and params is not None \
            and not position.get("own_launch") \
            and str(position.get("mode") or params.get("mode") or "flip").lower() == "flip":
        # v1.0.8: no valid agent stop -> the default flip stop (same number the sl_hit alert uses) sells.
        _dsl = abs(float(params.get("stop_loss_pct", 20)))
        try:
            _dsl = max(_dsl, float(higher_cap_stop_floors(mcap_now, "flip")[0]))
        except Exception:
            pass
        dp = position.get("default_protection") or {}
        if dp.get("sl_pct") != _dsl:
            dp["sl_pct"] = _dsl
        position["default_protection"] = dp
        if not dp.get("sl_fired_at") and pnl_pct <= -_dsl:
            ap, state_key, leg = dp, "default_protection", ("sl", 100.0, "default_flip_stop")
    if not leg:
        return False
    if has_inflight_sell(mint):
        return True
    kind, pct, reason = leg
    if int(ap.get(f"{kind}_attempts") or 0) >= PROTECT_MAX_RETRIES:
        await _protect_exhausted_alert(mint, position, kind, pnl_pct, state_key)
        return False
    ticker = position.get("ticker", "?")
    ap[f"{kind}_fired_at"] = _now_iso()
    ap[f"{kind}_fired_pnl_pct"] = round(pnl_pct, 2)
    ap[f"{kind}_attempts"] = int(ap.get(f"{kind}_attempts") or 0) + 1
    position[state_key] = ap
    position["exit_reason"] = reason
    upsert_position(mint, position)
    _who = "default flip stop" if state_key == "default_protection" else "the agent set"
    _log(f"protect: {ticker} {reason} at {pnl_pct:+.1f}% ({_who} "
         f"{'-' + str(ap.get('sl_pct')) if kind == 'sl' else '+' + str(ap.get('tp_pct'))}%), selling {pct:.0f}%",
         prefix="protect")
    _pre_amt = float(position.get("token_amount") or 0)
    sig = {"signal_id": f"armed_{kind}_{mint[:8]}_{int(_now_ts())}", "mint": mint,
           "amount_pct": pct, "reason": reason, "_armed": True}
    try:
        await execute_sell_signal(sig)
    except Exception as e:
        _log(f"protect: sell err {ticker}: {e}", prefix="protect")
    after = (load_positions() or {}).get(mint)
    landed = (after is None) or (float(after.get("token_amount") or 0) < _pre_amt * 0.99)
    if not landed and after is not None:
        _ap = after.get(state_key) or {}
        _ap.pop(f"{kind}_fired_at", None)     # retry next tick, up to PROTECT_MAX_RETRIES
        after[state_key] = _ap
        upsert_position(mint, after)
    _note = ("This ran because you armed it. If the bag is still open, re-arm SL/TP for the remainder."
             if state_key == "armed_protection" else
             "This ran on the default flip stop because no valid SL was armed. If the bag is still open, "
             "arm SL/TP for the remainder.")
    try:
        write_inbox_packet_generic({
            "id": f"x_evt_protect_{kind}_{mint[:8]}_{int(_now_ts())}",
            "type": "protective_order_fired",
            "received_at": _now_iso(),
            "priority": "high",
            "context": {"mint": mint, "ticker": ticker, "leg": kind, "reason": reason,
                        "pnl_pct_at_fire": round(pnl_pct, 2), "sell_pct": pct,
                        "landed": landed, "your_levels": {k: ap.get(k) for k in ("sl_pct", "tp_pct", "tp_sell_pct")},
                        "note": _note},
        }, prefix="evt", identifier=f"protect_{kind}_{mint[:8]}")
    except Exception:
        pass
    if state_key == "default_protection":
        try:   # keep the existing sl_hit-style Telegram for the default stop
            await send_telegram(f"🚨 EXIT TRIGGER: {ticker}\nTRIGGER: sl_hit (default flip stop -{ap.get('sl_pct')}%) | "
                                f"pnl {pnl_pct:+.1f}% | sold {pct:.0f}% | landed={landed}")
        except Exception:
            pass
    return True


def _levels_armed(position: dict) -> bool:
    ap = position.get("armed_protection") or {}
    return (ap.get("sl_pct") is not None and ap.get("tp_pct") is not None
            and not ap.get("sl_fired_at") and not ap.get("tp_fired_at"))


def _digest_absorbs_alert(position: dict, exit_trigger: dict) -> bool:
    if not PROTECT_DIGEST_COLLAPSE or not exit_trigger:
        return False
    if exit_trigger.get("type") in PROTECT_DIGEST_PASSTHRU:
        return False
    return _levels_armed(position)


def _position_needs_action(position: dict) -> Optional[str]:
    ap = position.get("armed_protection") or {}
    if ap.get("sl_fired_at"):
        return "stop_hit"
    if ap.get("tp_fired_at"):
        return "take_profit_hit_rearm_remainder"
    if ap.get("sl_pct") is None or ap.get("tp_pct") is None:
        return "no_levels"
    return None


_POSITIONS_DIGEST_LAST = [0.0]


def write_positions_digest(force: bool = False) -> Optional[Path]:
    """One card per inbox check: every open bag, its levels, and what (if
    anything) needs the agent. Stable filename, overwritten each cycle."""
    if not force and _now_ts() - _POSITIONS_DIGEST_LAST[0] < POSITIONS_DIGEST_S:
        return None
    _POSITIONS_DIGEST_LAST[0] = _now_ts()
    positions = load_positions() or {}
    rows = []
    for mint, p in positions.items():
        if not isinstance(p, dict):
            continue
        ap = p.get("armed_protection") or {}
        pnl = p.get("last_pnl_pct")
        sl, tp = ap.get("sl_pct"), ap.get("tp_pct")
        rows.append({
            "ticker": p.get("ticker"), "mint": mint, "mode": p.get("mode") or "flip",
            "price_usd": p.get("last_price_usd"), "pnl_pct": pnl, "peak_pnl_pct": p.get("peak_pnl_pct"),
            "stop_loss_pct": sl, "take_profit_pct": tp, "take_profit_sell_pct": ap.get("tp_sell_pct"),
            "to_stop_pts": round(float(pnl) + abs(float(sl)), 2) if (pnl is not None and sl is not None) else None,
            "to_tp_pts": round(float(tp) - float(pnl), 2) if (pnl is not None and tp is not None) else None,
            "levels_set_at": ap.get("set_at"),
            "hold_minutes": int((_now_ts() - float(p.get("opened_at_ts") or _now_ts())) / 60),
            "alerts_since_last_ack": p.get("digest_alerts") or [],
            "needs_action": _position_needs_action(p),
        })
    if not rows and not force:
        return None
    need = [r for r in rows if r["needs_action"]]
    tick = _position_tick_s()
    packet = {
        "id": "x_evt_positions_digest",
        "type": "positions_digest",
        "received_at": _now_iso(),
        "priority": "high" if need else "normal",
        "from_user": {"username": "@meme_sniper_position_monitor", "friendship_tier": "system", "user_id": "meme_sniper_bot"},
        "context": {
            "open_positions": len(rows),
            "needs_action": len(need),
            "rows": rows,
            "position_check_cadence_s": tick,
            "inbox_cadence_s": AGENT_INBOX_CADENCE_S,
            "alert_buffer_s": round(tick + AGENT_INBOX_CADENCE_S + PROTECT_EXEC_BUFFER_S, 1),
            "how": ("One pass per check. Levels persist until you change them. Only rows with needs_action "
                    "require a reply. Reply once with action=set_protection_batch {positions:[{mint, "
                    "stop_loss_pct, take_profit_pct, take_profit_sell_pct}], keep_others:true}; listing "
                    "nothing still acknowledges the alerts above."),
        },
    }
    path = _INBOX / "meme_sniper - positions_digest.json"
    try:
        _save_json_atomic(path, packet)
    except Exception as e:
        _log(f"positions digest write err: {e}", prefix="protect")
        return None
    return path


async def execute_set_protection_batch(sig: dict) -> None:
    """action=set_protection_batch: one reply per inbox check."""
    sig_id = sig.get("signal_id") or _now_iso()
    items = sig.get("positions") or sig.get("items") or []
    if not items and str(os.environ.get("PROTECTION_BATCH_EMPTY_REJECT", "1")).strip().lower() not in ("0", "false", "off", "no"):
        await write_signal_response(sig.get("signal_id") or sig.get("id"), "rejected",
                                    error="set_protection_batch: no rows (send \"positions\": [{\"mint\": ..., \"sl_pct\": ...}])")
        return
    keep_others = sig.get("keep_others", True) is not False
    results = []
    listed = set()
    for i, it in enumerate(items if isinstance(items, list) else []):
        if not isinstance(it, dict) or not it.get("mint"):
            results.append({"i": i, "ok": False, "error": "missing_mint"})
            continue
        listed.add(it["mint"])
        sub = {**it, "signal_id": f"{sig_id}#{i}", "reasoning": it.get("reasoning") or sig.get("reasoning")}
        ok = await execute_set_protection(sub, respond=False)
        results.append({"mint": it["mint"], "ok": bool(ok)})
    positions = load_positions() or {}
    unconfirmed = []
    for mint, p in positions.items():
        if not isinstance(p, dict):
            continue
        p["last_agent_check_ts"] = _now_ts()
        p.pop("digest_alerts", None)              # acknowledged by this pass
        if mint not in listed and not keep_others:
            unconfirmed.append(p.get("ticker") or mint[:8])
        upsert_position(mint, p)
    bad = [r for r in results if not r.get("ok")]
    _log(f"protect: batch {len(items)} rows, {len(bad)} rejected, acked {len(positions)} positions", prefix="protect")
    await write_signal_response(sig_id, "protection_batch_applied" if not bad else "protection_batch_partial",
                                error=(json.dumps({"rejected": bad, "unconfirmed": unconfirmed})[:400]
                                       if (bad or unconfirmed) else None))
    try:
        write_positions_digest(force=True)
    except Exception:
        pass


_POSITION_TOUCH_ACTIONS = {"sell", "tighten_trail", "loosen_trail", "convert_mode", "snooze_exit",
                           "dismiss_exit_trigger", "hold", "set_holding_thesis", "classify_holding",
                           "promote_holding", "update_params", "owner_position"}


def _panic_fee_cap(lamports: int) -> int:
    cap = PANIC_PRIORITY_FEE_CAP_LAMPORTS
    try:
        cap = int(get_override_sync("PANIC_PRIORITY_FEE_CAP_LAMPORTS", cap) or cap)
    except Exception:
        pass
    return int(min(lamports, cap)) if cap and cap > 0 else int(lamports)


async def _monitor_watchdog_loop() -> None:
    """v1.0.4: alert the owner if the position monitor goes stale with open bags."""
    from monitor_watchdog import watchdog_loop
    await watchdog_loop(_BOT_LOGS)


_LEAGUE_FLAT_ALERTED: dict = {}


async def league_flatten_loop() -> None:
    """LEAGUE_MODE only: flatten every bag to USDC before the snapshot (USDC only at start and end).
    Pauses buys (the buy gate) and sells 100% through the league executor; alerts the agent once per season."""
    if not LEAGUE_MODE:
        return
    while True:
        try:
            ph = _league.phase(LEAGUE_CFG)
            if ph["phase"] == "flatten":
                pos = load_positions() or {}
                orders = _league.flatten_orders(pos, has_inflight_sell, now_tag=str(int(_now_ts())))
                key = ph["season_end"]
                if orders and not _LEAGUE_FLAT_ALERTED.get(key):
                    _LEAGUE_FLAT_ALERTED[key] = True
                    try:
                        write_inbox_packet_generic({
                            "id": f"x_evt_league_flatten_{int(_now_ts())}", "type": "league_flatten",
                            "received_at": _now_iso(), "priority": "high",
                            "context": {"open_bags": len(orders), **ph,
                                        "note": "League snapshot is near: buys paused, selling every bag to USDC. "
                                                "No action needed unless a sell fails."}},
                            prefix="evt", identifier="league_flatten")
                        await send_telegram(f"🏁 LEAGUE: flattening {len(orders)} bag(s) to USDC before the snapshot "
                                            f"({ph['minutes_to_end']:.0f} min to end)")
                    except Exception:
                        pass
                for o in orders:
                    try:
                        await execute_sell_signal(o)
                    except Exception as e:
                        _log(f"league flatten sell err {o['mint'][:8]}: {e}", prefix="league")
                if orders and ph["minutes_to_end"] <= float(LEAGUE_CFG.get("flatten_buffer_min") or 120) / 2:
                    try:
                        write_inbox_packet_generic({
                            "id": f"x_evt_league_not_flat_{int(_now_ts())}", "type": "league_not_flat",
                            "received_at": _now_iso(), "priority": "high",
                            "context": {"open_bags": [o["mint"] for o in orders], **ph,
                                        "note": "Still holding non-USDC near the snapshot. Holding one at the "
                                                "snapshot voids the season. Sell now."}},
                            prefix="evt", identifier="league_not_flat")
                    except Exception:
                        pass
        except Exception as e:
            _log(f"league flatten loop err: {e}", prefix="league")
        await asyncio.sleep(60)


async def position_monitor_loop() -> None:
    """
    Per open position: price/dev/liq checks, exit conditions.
    NEVER auto-sells. Writes meme_exit_signal packet for the agent to decide.
    """
    _log("monitor: starting", prefix="monitor")
    
    while True:
        await write_heartbeat("position_monitor", "checking")
        
        try:
            positions = load_positions()
            if positions:
                _tick_balances = None
                try:
                    _tick_balances = await get_wallet_token_balances() or []
                except Exception:
                    _tick_balances = None
                for mint, position in list(positions.items()):
                    try:
                        await check_position(mint, position, tick_balances=_tick_balances)
                    except Exception as e:
                        _log(f"monitor: error checking {position.get('ticker', '?')}: {e}", prefix="monitor")
        except Exception as e:
            _log(f"monitor: loop error: {e}", prefix="monitor")
        try:
            write_positions_digest()
        except Exception as e:
            _log(f"monitor: positions digest err: {e}", prefix="monitor")
        
        await asyncio.sleep(_position_tick_s())


async def _heal_zero_entry(mint: str, position: dict) -> bool:
    """A buy that landed while dex was dark stored price 0 and mcap null.
    Rebuild the basis from SOL spent and tokens received so PnL is not fiction.
    """
    raw = float(position.get("token_amount") or 0)
    sol = float(position.get("amount_sol") or 0)
    if raw <= 0 or sol <= 0:
        return False
    dec = position.get("token_decimals")
    if not dec:
        dec = 6 if str(mint).endswith("pump") else 0
    if not dec:
        return False
    solp = await get_sol_price_usd()
    if not solp:
        return False
    ui = raw / (10 ** int(dec))
    if ui <= 0:
        return False
    px = (sol * float(solp)) / ui
    position["entry_price"] = px
    position["peak_price"] = max(float(position.get("peak_price") or 0), px)
    position["entry_price_source"] = "cost_derived_heal"
    position["token_decimals"] = int(dec)
    pair = await fetch_token_data(mint)
    mcap = float((pair or {}).get("marketCap") or (pair or {}).get("fdv") or 0)
    if not mcap:
        mcap = px * 1_000_000_000
        position["mcap_at_buy_source"] = "pump_supply_estimate"
    else:
        position["mcap_at_buy_source"] = "dex"
    position["mcap_at_buy"] = mcap
    upsert_position(mint, position)
    _log(f"[entry-heal] {position.get('ticker')} price {px:.8f} mcap ${mcap:,.0f} "
         f"from {sol:.4f} SOL / {ui:.2f} tokens",
         prefix="monitor")
    return True


async def check_position(mint: str, position: dict, tick_balances=None) -> None:
    """Check exit conditions for a single position. Write exit packet if triggered."""
    ticker = position.get("ticker", "?")
    entry_price = position.get("entry_price", 0)
    if entry_price <= 0:
        if not await _heal_zero_entry(mint, position):
            return
        entry_price = float(position.get("entry_price") or 0)
        if entry_price <= 0:
            return
    _held = None
    try:
        if tick_balances is not None:
            _held = float(next((b.get("amount_raw") for b in tick_balances
                                if b.get("mint") == mint), 0) or 0)
        else:
            _rows = await get_wallet_token_balances() or []
            _held = float(next((b.get("amount_raw") for b in _rows
                                if b.get("mint") == mint), 0) or 0)
    except Exception:
        _held = None
    _close, _why = book_should_close(mint, position, held_raw=_held)
    if _close:
        _log(f"fill-gate drop {ticker} ({_short_mint(mint)}) why={_why}", prefix="monitor")
        remove_position(mint)
        return
    
    # ── FIX 3 (2026-08-15): THE LAST UN-OVERLAID FALLBACK READ ──────────────
    # Every WRITE site now overlays trail/max_hold through get_override_sync (the
    # "MUST overlay" comments on FALLBACK_DEFAULTS exist because someone already
    # got burned - the 20/25 lock the agent patched himself). This is the last read
    # that can hand a position the raw seed dict, and only when a position has no
    # params at all, which the boot schema repair is supposed to prevent.
    #
    # Today seed == file == 12/20, so the bug is asleep. The next file-only trail
    # tune without an overlay wakes it, and it would wake silently. So it says so
    # once per position instead: a position exiting on seed numbers is a position
    # exiting on a book nobody tuned.
    params = position.get("params")
    if not params:
        params = FALLBACK_DEFAULTS
        if mint not in _FALLBACK_NOT_OVERLAID_SEEN:
            _FALLBACK_NOT_OVERLAID_SEEN.add(mint)
            _log(f"fallback_not_overlaid: {ticker} ({mint[:8]}) has NO params - exiting on "
                 f"raw FALLBACK_DEFAULTS seeds (trail {FALLBACK_DEFAULTS.get('trail_drop_pct')}/"
                 f"{FALLBACK_DEFAULTS.get('trail_activate_pct')}), NOT the live filter file. "
                 f"Live would be {get_override_sync('DEFAULT_TRAIL_DROP_PCT', DEFAULT_TRAIL_DROP_PCT)}/"
                 f"{get_override_sync('DEFAULT_TRAIL_ACTIVATE_PCT', DEFAULT_TRAIL_ACTIVATE_PCT)}. "
                 f"Schema repair should have filled these.", prefix="exit")
    
    # Fetch current state
    pair = await fetch_token_data(mint)
    if not pair:
        # No live data , position can't be evaluated
        return
    
    current_price = float(pair.get("priceUsd") or 0)
    if current_price <= 0:
        return
    
    liq_now = (pair.get("liquidity") or {}).get("usd", 0) or 0
    mcap_now = float(pair.get("marketCap") or pair.get("fdv") or 0)
    # holders_now: sibling of mcap_now/liq_now — was READ at the horizon-packet
    # call but never assigned (undefined name, found by pyflakes 2026-07-27).
    # That line sits outside a try, right after upsert_position, so the position
    # was written and the function then died — _write_horizon_decision_packet
    # has never fired once.
    holders_now = int(position.get("last_holder_count")
                      or position.get("holder_count") or 0)
    vol_5m_now = (pair.get("volume") or {}).get("m5", 0) or 0
    
    # ── MARK vs EXECUTABLE (2026-07-27, the KOMUGI gap) ──────────────────────
    # `priceUsd` is DexScreener's aggregate MARK — a lagging average across pools.
    # It is NOT what you would get. What you get is a Jupiter swap against real
    # liquidity, including price impact for YOUR size. On a deep book those agree.
    # On a thin memecoin mid-dump they do not, and they diverge in the direction
    # that hurts.
    #
    # KOMUGI: the exit trigger fired at -1.2% off a +16.8% peak. The fill came
    # back at -12.2%. ELEVEN POINTS. The agent decided to exit on a number that said
    # he had given back almost nothing, and got charged a real loss. He reacted to
    # the small number and paid the big one.
    #
    # So we now quote the exit the way we would actually take it. `pnl_pct` is the
    # EXECUTABLE number when a quote is available — that is the honest one and it
    # is what triggers fire on. The mark is kept beside it so the SPREAD is
    # visible: a wide spread is itself a signal that the book is thin and an exit
    # will cost more than the chart suggests.
    mark_pnl_pct = ((current_price - entry_price) / entry_price) * 100
    pnl_pct = mark_pnl_pct
    exec_pnl_pct = None
    exec_sol_out = None
    exit_spread_pts = None
    try:
        _raw_units = int(float(position.get("token_amount") or 0))
        _basis_sol = float(position.get("amount_sol") or 0)
        if _raw_units > 0 and _basis_sol > 0:
            _q = await jupiter_quote_fresh(mint, SOL_MINT, _raw_units, slippage_bps=1500)
            _out = int((_q or {}).get("outAmount", 0) or 0)
            if _out > 0:
                exec_sol_out = _out / 1e9
                exec_pnl_pct = (exec_sol_out - _basis_sol) / _basis_sol * 100
                exit_spread_pts = round(mark_pnl_pct - exec_pnl_pct, 2)
                pnl_pct = exec_pnl_pct          # decide on what you'd actually get
                if abs(exit_spread_pts) >= 5.0:
                    _log(f"{ticker}: mark {mark_pnl_pct:+.1f}% but EXECUTABLE "
                         f"{exec_pnl_pct:+.1f}% (spread {exit_spread_pts:+.1f} pts) — "
                         f"thin book, the chart is flattering the exit", prefix="monitor")
    except Exception as _qe:
        # A failed quote must never blind the monitor. Fall back to the mark and
        # say so, rather than silently reporting a number of unknown provenance.
        _log(f"{ticker}: exit quote failed ({_qe!r}) — falling back to DexScreener mark",
             prefix="monitor")
    
    # Update peak off the SAME series the trigger uses. The old peak was
    # mark-price only, so a card could say peak +48 while the quote (the
    # number TP actually fired on) was already +91 and giveback printed 0.
    peak_price = position.get("peak_price", entry_price)
    if current_price > peak_price:
        peak_price = current_price
        position["peak_price"] = peak_price
    mark_peak_pnl = ((peak_price - entry_price) / entry_price) * 100 if entry_price else 0
    if exec_pnl_pct is not None:
        peak_pnl = max(float(position.get("peak_pnl_pct") or pnl_pct), pnl_pct)
        drawdown_from_peak = max(0.0, peak_pnl - pnl_pct)
    else:
        peak_pnl = max(float(position.get("peak_pnl_pct") or mark_peak_pnl), mark_peak_pnl)
        drawdown_from_peak = ((peak_price - current_price) / peak_price * 100) if peak_price > 0 else 0
    position["peak_pnl_pct"] = round(peak_pnl, 2)
    position["drawdown_from_peak_pct"] = round(drawdown_from_peak, 2)
    position["last_pnl_pct"] = round(pnl_pct, 2)          # v14.1 digest
    position["last_price_usd"] = current_price
    position["last_tick_at"] = _now_iso()
    upsert_position(mint, position)
    
    # ─── Exit condition checks ───
    age_min = (_now_ts() - position.get("opened_at_ts", _now_ts())) / 60

    # ── v14 PROTECTIVE ORDERS (2026-10-14) ───────────────────────────────────
    # The agent's own armed SL/TP. The bot does not decide anything here: it runs
    # the exact levels the agent set on his last touch, on the executable number.
    if await _check_armed_protection(mint, position, pnl_pct, params, mcap_now):
        return
    if position.get("own_launch"):
        return   # v14.3: own launches sell only on the armed ladder / SL, no other exit packets
    
    exit_trigger = None
    # `severity = "warning"` lived here and was never read once — every consumer
    # uses exit_trigger["severity"]. Removed 2026-07-27. Dead code that reads as
    # live is the same trap as a stale daily_call or a phantom -100%: it looks
    # like it is doing something, so nobody checks whether it is.
    # INTERNAL SEVERITY HINT ONLY — never published, never sent, never logged.
    # Deleted from the packet/telegram/console 2026-07-27 (the KOMUGI fix): it
    # spoke in the imperative and the agent obeyed it. If you find yourself adding
    # this to any outbound payload, that is the bug returning. Trigger = fact.
    
    # Sprint 28.7.6: per-tick state log. The owner wanted live visibility into the
    # tracker, not just at exit triggers. One line per position per tick , at
    # 60s tick that's 1/min/position. Compact format optimized for grep.
    _ticker_short = position.get("ticker", "?")[:10]
    _mint_short = _short_mint(mint)
    _trail_state = "armed" if position.get("trail_armed") else "off"
    _partial_state = "✓" if position.get("partial_taken") else ","
    
    # Sprint 28.8.2: include snooze status in tick log if active
    _snooze_until_ts = position.get("exit_snooze_until_ts", 0)
    _is_snoozed = _snooze_until_ts and _now_ts() < _snooze_until_ts
    _snooze_str = ""
    if _is_snoozed:
        _snooze_remaining_min = (_snooze_until_ts - _now_ts()) / 60
        _snooze_str = f" | 🤫 snoozed {_snooze_remaining_min:.0f}min"
    
    _log(
        f"tick {_ticker_short:<10} ({_mint_short}) | "
        f"price=${current_price:.6f} | "
        f"pnl={pnl_pct:+6.1f}% | "
        f"peak={peak_pnl:+6.1f}% | "
        f"drawdown={drawdown_from_peak:5.1f}% | "
        f"liq=${liq_now:>8,.0f} | "
        f"mcap=${mcap_now:>10,.0f} | "
        f"age={age_min:5.1f}min | "
        f"trail={_trail_state} | "
        f"partial={_partial_state}{_snooze_str}",
        prefix="monitor"
    )
    
    # Sprint 53 — HOLD MODE: update the living doc. A held token gets its full detail
    # + social presence appended every update so the agent can micro-watch the numbers
    # move and continuously re-underwrite the hold. Flip positions skip this entirely
    # (they're a trade, not a thesis). Hard rug exits below still fire in EITHER mode.
    if (position.get("mode") or "flip") == "hold":
        try:
            # Sprint 53: a held token gets a FULL FRESH RE-SCAN, not a thin monitor tick.
            # The old path passed ~8 fields, several of which (last_holder_count,
            # last_top10_pct, last_dev_pct) were STALE SNAPSHOTS from entry — they never
            # moved. So the "living doc" recorded a dead picture: price changed, nothing
            # else did. You cannot re-underwrite a hold on frozen numbers.
            #
            # CADENCE: the monitor ticks every 60s, but a full rescan is expensive (dex +
            # rugcheck + holders + deployer + narrative + an X-chatter scrape that alone
            # takes ~90s). Running that per-minute would hammer every API we depend on and
            # the scrape would never finish before the next one started. A hold is a
            # DAYS-long thesis — it does not need minute-resolution. So: full rescan on a
            # slow cadence (default 30min), while the normal monitor keeps ticking every
            # 60s underneath for price/PnL and, crucially, for the HARD RUG EXITS — those
            # still fire in real time regardless of mode.
            _HOLD_RESCAN_S = get_override_sync("HOLD_RESCAN_SECONDS", 1800)
            _last_rs = position.get("_last_hold_rescan_ts") or 0
            if (_now_ts() - _last_rs) >= _HOLD_RESCAN_S:
                position["_last_hold_rescan_ts"] = _now_ts()
                _hold_ctx = await hold_full_rescan(mint, position)
                _hold_read = await hold_doc_update(mint, position, _hold_ctx)
                _hh = _hold_read.get("health", {})
                if _hh.get("high_severity"):
                    _log(f"HOLD DEGRADED {_ticker_short}: "
                         f"{', '.join(d['signal'] for d in _hh.get('degradations', []))} "
                         f"— re-underwrite or demote to flip",
                         prefix="hold")
                    await send_telegram(
                        f"⚠️ <b>HOLD DEGRADED: {position.get('ticker','?')}</b>\n"
                        + "\n".join(f"• {d['detail']}" for d in _hh.get("degradations", [])[:4])
                        + f"\n\nRe-underwrite or demote to flip. Doc: holds/{mint[:8]}….md")
        except Exception as e:
            _log(f"hold_doc update err {_short_mint(mint)}: {e}", prefix="hold")

    # 2026-07-30 (The agent's exit-path items #1+#2): snooze is a NOTIFICATION mute,
    # not a protection kill-switch. The old blanket `if _is_snoozed: return` sat
    # ABOVE the SL, trail-arm, trail-drop, liq and rug checks — so a snooze meant
    # to silence repeated tp_hit telegrams disabled the entire safety net for up
    # to 4h. That is the RIKA/ROBINDROP tape: a partial TP fires, the position is
    # snoozed, and the residual then rides down THROUGH its stop with trail_armed
    # still false — because the arm line below never ran while snoozed. Fix:
    # snooze now gates ONLY the warning-severity tp_hit re-fires; SL / trail /
    # liq / rug are ALWAYS evaluated. Holding through a dip is hold-mode or a
    # wider SL param — never a silently suppressed stop. `_is_snoozed` is read
    # below at the two tp_hit blocks and nowhere else in this evaluator.
    
    # 0. v1.0.3 fee-wallet vault moved: exit everything, beats every other trigger.
    _vault_trigger = None
    _fvp = (params or {}).get("fee_vault") if isinstance(params, dict) else None
    if _fvp and _fvp.get("wallet"):
        try:
            import fee_vault as _fv
            if _now_ts() - float(position.get("_vault_checked_ts") or 0) >= 20:
                position["_vault_checked_ts"] = _now_ts()
                _vt = _fv.vault_exit_trigger({"fee_vault": _fvp},
                                             await _fv.count_outgoing(_fvp["wallet"], helius_rpc))
                if _vt:
                    position["vault_moved"] = True
                    exit_trigger = _vault_trigger = _vt
        except Exception as _fve:
            _log(f"vault watch err {ticker}: {_fve}", prefix="exit")

    # 1. SL hit
    # Sprint 28.7.6: defensively normalize to positive magnitude. New buys are
    # normalized at signal-validation time, but pre-existing positions may have
    # been recorded with negative values. abs() handles either.
    sl_pct = abs(float(params.get("stop_loss_pct", 20)))
    _sl_floor, _tr_floor = higher_cap_stop_floors(mcap_now, position.get("mode") or "flip")
    if _sl_floor > sl_pct:
        sl_pct = _sl_floor
        position["higher_cap_sl_floor"] = _sl_floor
    if pnl_pct <= -sl_pct:
        exit_trigger = {
            "type": "sl_hit",
            "details": f"Price {pnl_pct:+.1f}% ≤ SL trigger -{sl_pct:.0f}%",
            "severity": "critical",
        }
    
    # 2. Trail drop (after trail activated at trail_activate_pct)
    trail_activate = float(params.get(
        "trail_activate_pct",
        get_override_sync("DEFAULT_TRAIL_ACTIVATE_PCT", DEFAULT_TRAIL_ACTIVATE_PCT)))
    trail_drop = abs(float(params.get(
        "trail_drop_pct",
        get_override_sync("DEFAULT_TRAIL_DROP_PCT", DEFAULT_TRAIL_DROP_PCT))))  # positive magnitude
    if _tr_floor > trail_drop:
        trail_drop = _tr_floor
        position["higher_cap_trail_floor"] = _tr_floor
    # v1.0.4: default positions trail on PnL points given back (TRAIL_GIVEBACK_PTS, 15)
    # once armed at +trail_activate (20). Fixed-rule entries (vault/celeb) keep % trail.
    _gb_pts = float((params or {}).get("trail_giveback_pts") or os.environ.get("TRAIL_GIVEBACK_PTS") or 15)
    _use_pts = _gb_pts > 0 and (params or {}).get("trail_mode") != "pct"
    if peak_pnl >= trail_activate and _use_pts:
        position["trail_armed"] = True
        if peak_pnl - pnl_pct >= _gb_pts:
            exit_trigger = {
                "type": "trail_drop",
                "details": f"Peak +{peak_pnl:.1f}%, now {pnl_pct:+.1f}% (gave back {peak_pnl - pnl_pct:.1f} pts, trigger {_gb_pts:.0f})",
                "severity": "critical",
            }
    elif peak_pnl >= trail_activate:
        position["trail_armed"] = True
        if drawdown_from_peak >= trail_drop:
            exit_trigger = {
                "type": "trail_drop",
                "details": f"Peak +{peak_pnl:.1f}%, dropped {drawdown_from_peak:.1f}% (trail trigger {trail_drop}%)",
                "severity": "critical",
            }
    
    # 3. Partial TP (single take, not yet taken). Snooze mutes THIS (a tp_hit
    #    re-fire is exactly the notification spam snooze exists to silence) — but
    #    it no longer mutes the SL/trail/liq/rug checks above and below it.
    partial_at = float(params.get("partial_take_at_pct", 35))
    if not position.get("partial_taken") and pnl_pct >= partial_at and not exit_trigger and not _is_snoozed:
        exit_trigger = {
            "type": "tp_hit",
            "details": f"Hit partial TP target +{partial_at}% (now +{pnl_pct:.1f}%)",
            "severity": "warning",
        }
    
    # 4. Full TP targets — also a tp_hit re-fire, so snooze mutes it too.
    tp_targets = params.get("tp_targets_pct", [50, 100])
    for tp in tp_targets:
        if pnl_pct >= float(tp) and not _is_snoozed:
            # Only fire packet for the highest TP hit on this tick
            exit_trigger = {
                "type": "tp_hit",
                "details": f"Hit TP target +{tp}% (now +{pnl_pct:.1f}%)",
                "severity": "warning",
            }

    # 4b. TIERED PROFIT ALERTS (2026-07-30 — the agent's partial_tp, as NOTIFICATION).
    # This monitor NEVER sells (see the docstring / KOMUGI ruling). partial_tp is a
    # ladder of profit LEVELS; each level the agent reaches fires ONE packet naming the
    # level and the fraction HE planned to trim there — a reference input, not an
    # order. He fires the % he wants. Each tier alerts exactly once (tracked on the
    # position); a distinct trigger type per tier keeps them from de-duping against
    # each other. Snooze mutes them like any tp_hit. Fires the LOWEST un-alerted
    # tier reached, so on a fast mover they arrive in order across ticks.
    _ptp = params.get("partial_tp")
    if _ptp and not _is_snoozed and not exit_trigger:
        _alerted = set(position.get("partial_tp_alerted") or [])
        for _tier in sorted(_ptp, key=lambda t: float(t.get("pct_gain", 0) or 0)):
            _lvl = float(_tier.get("pct_gain", 0) or 0)
            _frac = _tier.get("sell_fraction")
            if _lvl > 0 and pnl_pct >= _lvl and _lvl not in _alerted:
                exit_trigger = {
                    "type": f"tp_tier_{int(_lvl)}",
                    "details": (f"Tiered profit +{_lvl:.0f}% reached (now +{pnl_pct:.1f}%). "
                                f"Your plan was to trim {int((_frac or 0) * 100)}% here — "
                                f"fire the % you want; nothing sells on its own."),
                    "severity": "warning",
                    "tier_pct": _lvl,
                    "suggested_trim_fraction": _frac,
                }
                _alerted.add(_lvl)
                position["partial_tp_alerted"] = sorted(_alerted)
                upsert_position(mint, position)
                break

    # 5. Liquidity drain
    liq_at_entry = position.get("liq_at_entry") or liq_now
    if "liq_at_entry" not in position:
        position["liq_at_entry"] = liq_now
        upsert_position(mint, position)
    if liq_at_entry > 0 and liq_now < liq_at_entry * 0.4:
        exit_trigger = {
            "type": "liq_drain",
            "details": f"Liquidity ${liq_now:.0f} (was ${liq_at_entry:.0f}, -{(1 - liq_now/liq_at_entry)*100:.0f}%)",
            "severity": "critical",
        }
    
    # 6. Volume cutoff (no trades in 5m on a position past 30min hold)
    if age_min >= 30 and vol_5m_now < 100:
        exit_trigger = {
            "type": "vol_cutoff",
            "details": f"Volume cutoff: 5min vol ${vol_5m_now:.0f} on {age_min:.0f}min position",
            "severity": "warning",
        }
    
    # 6b. v13.2 Drop 3: TIME-DECAY EXIT TRIGGERS
    #     These fire BEFORE max_hold to catch dead-in-the-water positions earlier.
    #     All four are tunable; any can be disabled by setting to 0.
    
    # 6b.i: breakeven-move check — if position hasn't moved ±2% in N min, exit
    breakeven_minutes = get_override_sync("DEFAULT_BREAKEVEN_MOVE_MINUTES", DEFAULT_BREAKEVEN_MOVE_MINUTES)
    if breakeven_minutes > 0 and age_min >= breakeven_minutes and not exit_trigger:
        if abs(pnl_pct) < 2.0:
            exit_trigger = {
                "type": "breakeven_decay",
                "details": (
                    f"No movement (±2%) after {breakeven_minutes}min hold; "
                    f"current pnl {pnl_pct:+.1f}%. Thesis not activating."
                ),
                "severity": "warning",
            }
    
    # 6b.ii: flat-price check — within ±0.5% of entry for N continuous min = exit
    # We track this via a flat_since_ts field on the position. Resets when price
    # moves outside the flat range.
    flat_minutes = get_override_sync("DEFAULT_FLAT_PRICE_EXIT_MINUTES", DEFAULT_FLAT_PRICE_EXIT_MINUTES)
    if flat_minutes > 0 and not exit_trigger:
        is_flat_now = abs(pnl_pct) < 0.5
        flat_since_ts = position.get("flat_since_ts", 0)
        if is_flat_now:
            if not flat_since_ts:
                position["flat_since_ts"] = _now_ts()
                upsert_position(mint, position)
            else:
                flat_duration_min = (_now_ts() - flat_since_ts) / 60
                if flat_duration_min >= flat_minutes:
                    exit_trigger = {
                        "type": "flat_price_decay",
                        "details": (
                            f"Price within ±0.5% of entry for {flat_duration_min:.1f}min "
                            f"(threshold {flat_minutes}min). Position frozen."
                        ),
                        "severity": "warning",
                    }
        else:
            # Reset flat tracker — price has moved
            if flat_since_ts:
                position["flat_since_ts"] = 0
                upsert_position(mint, position)
    
    # 6b.iii: drawdown velocity — if losing > N%/min over the last 5min, panic
    # Compute velocity from the last_pnl_pct + last_pnl_ts snapshot, updated each tick.
    velocity_threshold = get_override_sync(
        "DEFAULT_DRAWDOWN_VELOCITY_EXIT_PCT_PER_MIN",
        DEFAULT_DRAWDOWN_VELOCITY_EXIT_PCT_PER_MIN,
    )
    if velocity_threshold > 0 and not exit_trigger:
        last_pnl_ts = position.get("last_pnl_ts", 0)
        last_pnl = position.get("last_pnl_pct", pnl_pct)
        if last_pnl_ts:
            elapsed_min = (_now_ts() - last_pnl_ts) / 60
            if elapsed_min >= 1.0:  # need at least 1min of distance to compute velocity
                pnl_change = pnl_pct - last_pnl
                velocity = pnl_change / elapsed_min  # %/min, negative when losing
                if velocity <= -velocity_threshold:
                    _runner = (
                        str(position.get("mode") or "").lower() in ("hold", "long", "runner")
                        or peak_pnl >= 100
                        or (age_min >= 90 and pnl_pct >= 20)
                    )
                    exit_trigger = {
                        "type": "drawdown_velocity",
                        "details": (
                            f"Drawdown accelerating: {velocity:.1f}%/min (threshold "
                            f"-{velocity_threshold}%/min). pnl {last_pnl:+.1f}% → {pnl_pct:+.1f}% "
                            f"in {elapsed_min:.1f}min."
                        ),
                        "sensor_note": "SENSOR, not a full cut. scale, do not flatten." if _runner else "",
                        "severity": "warning" if _runner else "critical",
                        "full_bag_fit": (not _runner),
                    }
                    # RENAMED 2026-07-27 (the owner): was "PANIC_SELL" — the only
                    # emotional label in a vocabulary of WATCH / EXIT_PARTIAL /
                    # EXIT_FULL. This string lands in the agent's packet and becomes
                    # part of his prompt: naming the FEELING instead of the
                    # MECHANISM gives him nothing to reason against, and primes
                    # the exact reaction we don't want. The trigger
                    # (drawdown_velocity) and the rate already carry the urgency,
                    # and severity is "critical" — he can now agree or disagree
                    # with a claim instead of obeying a mood.
        # Refresh velocity snapshot every tick
        position["last_pnl_pct"] = round(pnl_pct, 2)
        position["last_pnl_ts"] = _now_ts()
        upsert_position(mint, position)
    
    # 7. Max hold (mode-aware)
    # Flip mode: 6h default (DEFAULT_MAX_HOLD_MINUTES = 360 in v13.2 Drop 3)
    # Hold mode: 72h default , much wider since hold positions are 1-3 day plays
    mode = params.get("mode", "flip")
    default_max_hold_min = get_override_sync("DEFAULT_MAX_HOLD_MINUTES", DEFAULT_MAX_HOLD_MINUTES)
    default_max_hold_h_flip = default_max_hold_min / 60.0
    if mode == "hold":
        max_hold_h = float(params.get("max_hold_hours", FALLBACK_DEFAULTS_HOLD["max_hold_hours"]))
    else:
        max_hold_h = float(params.get("max_hold_hours", default_max_hold_h_flip))
    
    if age_min >= max_hold_h * 60 and not exit_trigger and not position.get("owner_no_time_exit"):
        if mode == "hold":
            # ── Sprint 53: A CLOCK RUNNING OUT IS NOT A THESIS BREAKING ──────────
            # A hold used to get the SAME forced EXIT_FULL as a flip when max_hold
            # expired. That is backwards. For a flip, the clock IS the thesis ("this
            # is a 6-hour trade") — so time running out means the trade failed to work
            # and you get out. But for a HOLD, the thesis is the COMMUNITY, the DEV,
            # the LORE. None of those expire on a timer. If the bag is 72h old and
            # everything he underwrote is still TRUE, an alarm clock should not be
            # allowed to sell it.
            #
            # So the horizon becomes a scheduled RE-UNDERWRITE, not an auto-exit. He
            # set the days; when the days are up, he DECIDES: extend (with a reason),
            # or exit. What he cannot do is drift — the position is frozen from new
            # entries and he has to actually answer.
            #
            # The genuine dangers (rug, liq drain, dev dump, holder exodus, volume
            # death, stop loss) all fire INDEPENDENTLY of this and are untouched. This
            # only stops the CLOCK from being an exit reason on a thesis that still holds.
            _hz = position.get("_horizon_decision") or {}
            if not _hz.get("pending"):
                position["_horizon_decision"] = {
                    "pending": True,
                    "due_at": _now_iso(),
                    "horizon_hours": max_hold_h,
                    "asked_count": (_hz.get("asked_count") or 0) + 1,
                }
                upsert_position(mint, position)
                _thesis = get_hold_thesis(mint) or {}
                try:
                    await _write_horizon_decision_packet(
                        mint, position, _thesis, pnl_pct, mcap_now, liq_now,
                        holders_now, max_hold_h)
                except Exception as _he:
                    _log(f"horizon packet err: {_he}", prefix="hold")
                await send_telegram(
                    f"⏳ <b>HOLD HORIZON REACHED: {position.get('ticker','?')}</b>\n"
                    f"You set {max_hold_h:.0f}h. It's up. PnL {pnl_pct:+.1f}%.\n\n"
                    f"<b>Decide: EXTEND or EXIT.</b> A clock running out is not a thesis "
                    f"breaking — but drifting isn't a decision either.")
                _log(f"HOLD HORIZON: {position.get('ticker','?')} hit {max_hold_h}h "
                     f"— re-underwrite required (NOT auto-exiting)", prefix="hold")
            # Do NOT force an exit. Surface it, demand a decision, keep holding until
            # he answers or a REAL exit trigger fires.
            exit_trigger = None
        else:
            exit_trigger = {
                "type": "max_hold",
                "details": f"Max hold {max_hold_h}h reached (mode={mode})",
                "severity": "warning",
            }
    
    # 7b. HOLD MODE EXTRA EXITS , only apply to mode=hold positions
    if mode == "hold" and not exit_trigger:
        # Mcap milestone partial (take 25% off at each $500K/$1M/$2.5M/$5M milestone)
        milestones = params.get("mcap_milestones_usd") or FALLBACK_DEFAULTS_HOLD["mcap_milestones_usd"]
        milestones_hit = position.get("mcap_milestones_hit") or []
        try:
            current_mcap_now = float(pair.get("marketCap") or pair.get("fdv") or 0)
        except Exception:
            current_mcap_now = 0
        for milestone in milestones:
            if current_mcap_now >= milestone and milestone not in milestones_hit:
                exit_trigger = {
                    "type": "mcap_milestone",
                    "details": f"Hit ${milestone:,.0f} mcap milestone , take 25% partial",
                    "severity": "info",
                    "milestone": milestone,
                }
                milestones_hit.append(milestone)
                position["mcap_milestones_hit"] = milestones_hit
                upsert_position(mint, position)
                break
        
        # Volume decay exit , if vol_5m drops below 10% of hold-period avg
        vol_decay_threshold = float(params.get("volume_decay_exit_pct", FALLBACK_DEFAULTS_HOLD["volume_decay_exit_pct"]))
        # Need vol_5m_avg_during_hold tracked across position lifetime
        vol_history = position.get("vol_5m_history", [])
        if isinstance(vol_history, list):
            vol_history.append(vol_5m_now)
            # Cap history at last 100 samples
            if len(vol_history) > 100:
                vol_history = vol_history[-100:]
            position["vol_5m_history"] = vol_history
            upsert_position(mint, position)
            
            # Only check decay after we have 10+ samples
            if len(vol_history) >= 10:
                avg_vol = sum(vol_history) / len(vol_history)
                threshold = avg_vol * (vol_decay_threshold / 100.0)
                if vol_5m_now < threshold and avg_vol > 100:  # ignore noise positions
                    if not exit_trigger:
                        exit_trigger = {
                            "type": "volume_decay",
                            "details": f"5min vol ${vol_5m_now:.0f} dropped below {vol_decay_threshold}% of avg ${avg_vol:.0f}",
                            "severity": "warning",
                        }
        
        # Holder exodus , if holder_count drops 30%+ from peak
        if not exit_trigger:
            holders_data = await get_holders_top10(mint)
            if holders_data:
                hc_now = holders_data.get("holder_count", 0) or 0
                hc_peak = position.get("holder_count_peak", hc_now) or hc_now
                if hc_now > hc_peak:
                    position["holder_count_peak"] = hc_now
                    upsert_position(mint, position)
                else:
                    exodus_threshold = float(params.get("holder_exodus_exit_pct", FALLBACK_DEFAULTS_HOLD["holder_exodus_exit_pct"]))
                    if hc_peak > 100:  # ignore tiny tokens
                        drop_pct = ((hc_peak - hc_now) / hc_peak) * 100
                        if drop_pct >= exodus_threshold:
                            exit_trigger = {
                                "type": "holder_exodus",
                                "details": f"Holders dropped {drop_pct:.1f}% from peak ({hc_peak} → {hc_now})",
                                "severity": "critical",
                            }
    
    # 8. Dev dump detection (top1 holder pct dropped substantially)
    holders_now = await get_holders_top10(mint)
    if holders_now and "dev_holding_at_entry_pct" not in position:
        position["dev_holding_at_entry_pct"] = holders_now.get("dev_holding_pct", 0)
        upsert_position(mint, position)
    elif holders_now:
        dev_at_entry = position.get("dev_holding_at_entry_pct", 0) or 0
        dev_now = holders_now.get("dev_holding_pct", 0) or 0
        if dev_at_entry > 5 and dev_now < dev_at_entry * 0.6:
            exit_trigger = {
                "type": "dev_dump_detected",
                "details": f"Dev wallet dropped {dev_at_entry:.1f}% → {dev_now:.1f}%",
                "severity": "critical",
            }

    # Sprint 65 ①+②: running holder hold-time → the token's folder, so the agent sees the
    # TREND while he holds (is hold time dropping = holders bailing?). Reference, not a
    # directive — a falling number is information about the token, not a sell order.
    try:
        if holders_now:
            _ht = await compute_holder_hold_time(mint, holders_now.get("holder_count") or 0)
            if _ht:
                token_folder_append(mint, position.get("ticker", "?"), _ht)
    except Exception as _hte:
        _log(f"position hold-time skipped {_short_mint(mint)}: {_hte}", prefix="wallet")

    # Sprint 65: market-event awareness on a HELD token — did it just get boosted /
    # dex_paid / add socials? Quiet-logged always; packet only on the strong combo
    # (event + a real 1h price move). The team pushing + price confirming = signal.
    try:
        _h1_move = _safe_num((pair.get("priceChange") or {}).get("h1")) or 0
        await evaluate_position_market_event(mint, position, pair, _h1_move)
    except Exception as _mee:
        _log(f"position market-event skipped {_short_mint(mint)}: {_mee}", prefix="dxpm")

    # 2026-10-11 unpaid-catalyst reclass. sensory is not a full sell.
    _SENSORY_TYPES = {"drawdown_velocity", "breakeven_decay", "flat_price_decay", "vol_cutoff", "max_hold"}
    _em = position.get("edge_map") or {}
    _cat_name = str(_em.get("catalyst") or _em.get("catalyst_name") or position.get("unpaid_catalyst") or "").strip()
    _cat_status = ""
    try:
        _cat_status = str(_edge_path_status_hint(_em) or "")
    except Exception:
        _cat_status = str(_em.get("path_status") or "")
    _unpaid = bool(_cat_name) and _cat_status.lower() not in ("dead", "paid")
    _runner_now = (
        str(position.get("mode") or params.get("mode") or "").lower() in ("hold", "long", "runner")
        or (peak_pnl >= 100)
        or (age_min >= 90 and pnl_pct >= 20)
        or _unpaid
    )
    if _vault_trigger:                 # v1.0.3: vault moved outranks every later trigger
        exit_trigger = _vault_trigger
    if exit_trigger and exit_trigger.get("type") in _SENSORY_TYPES and _runner_now:
        if str(position.get("mode") or params.get("mode") or "flip").lower() == "flip":
            position["mode"] = "hold"
            position["reclass_from"] = "flip"
            position["reclass_reason"] = "unpaid_catalyst" if _unpaid else "runner_evidence"
            position["reclass_at"] = _now_iso()
            try:
                upsert_position(mint, position)
            except Exception as _re:
                _log(f"reclass upsert skipped: {_re}", prefix="monitor")
        exit_trigger["full_bag_fit"] = False
        exit_trigger["severity"] = "warning"
        exit_trigger["sensor_note"] = (
            "SENSOR. unpaid catalyst is the 10x path, not a 2x scalp. scale or hold. do not flatten."
            if _unpaid else
            "SENSOR. runner evidence live. scale, do not flatten."
        )
        if exit_trigger.get("type") == "max_hold":
            exit_trigger = None

    # If no trigger, no packet
    if not exit_trigger:
        return
    position["last_monitor_trigger"] = exit_trigger.get("type")   # v1.0.4 exit-type fill

    # v14.1: The agent already armed both levels and none has fired, so a sensor
    # alert does not need its own card or reply. It rides the positions digest.
    if _digest_absorbs_alert(position, exit_trigger):
        _al = list(position.get("digest_alerts") or [])
        _al.append({"type": exit_trigger.get("type"), "at": _now_iso(), "pnl_pct": round(pnl_pct, 2)})
        position["digest_alerts"] = _al[-5:]
        upsert_position(mint, position)
        return
    
    # Don't spam the same exit trigger , check if recent packet exists.
    # Sprint 45: filename conforms to "botname - subject" doctrine. Kept STABLE (no
    # timestamp) because this name doubles as the dedup key. Also check the legacy
    # x_evt_meme_exit_ name so we still dedup against pre-migration packets.
    existing_path = _INBOX / f"meme_sniper - meme_exit_{mint[:8]}.json"
    _legacy_exit = _INBOX / f"x_evt_meme_exit_{mint[:8]}.json"
    _check_path = existing_path if existing_path.exists() else (_legacy_exit if _legacy_exit.exists() else existing_path)
    if _check_path.exists():
        existing = load_json_with_staleness(_check_path, max_age_seconds=86400, default=None, alert_on_stale=False)
        if isinstance(existing, dict):
            ctx = existing.get("context", {})
            existing_trigger_type = (ctx.get("exit_trigger") or {}).get("type")
            existing_age_min = (_now_ts() - position.get("opened_at_ts", 0)) / 60 - (ctx.get("position_age_minutes") or 0)
            # Don't re-fire same trigger within 5 minutes
            if existing_trigger_type == exit_trigger["type"] and abs(existing_age_min) < 5:
                return
    
    # Sprint 45+: render the position-overlay chart at the exit moment so the agent SEES
    # the shape behind the trigger , "trustworthy dip or a cliff?". Synthetic render
    # draws entry/SL lines on the candles (more useful for an exit than a raw shot),
    # is sub-second + local (never blocks the monitor loop), and is best-effort: a
    # fetch/render failure must NEVER block the exit packet. Real screenshot stays
    # reserved for autopsy/on-demand.
    exit_chart_path = None
    try:
        _exit_ohlcv = await asyncio.wait_for(fetch_ohlcv(mint, limit=60), timeout=8)
        if _exit_ohlcv:
            exit_chart_path = await render_custom_chart_png(mint, ticker, _exit_ohlcv, position=position)
    except Exception as e:
        _log(f"exit chart render failed for {ticker}: {e}", prefix="monitor")

    # Write exit packet
    sha = _sha8(f"exit_{mint}_{exit_trigger['type']}_{int(_now_ts())}")
    packet = {
        "id": f"x_evt_meme_exit_{mint[:8]}",
        "type": "meme_exit_signal",
        "received_at": _now_iso(),
        **_lane_fields("meme_exit_signal"),
        "from_user": {"username": "@meme_sniper_position_monitor", "friendship_tier": "system", "user_id": "meme_sniper_bot"},
        "context": {
            "mint": mint,
            "ticker": ticker,
            "originating_buy_signal_id": position.get("originating_signal_id"),
            "position_age_minutes": int(age_min),
            "hold_minutes": int(age_min),
            "mode": position.get("mode") or "flip",
            "entry_price_usd": str(entry_price),
            "current_price_usd": str(current_price),
            "current_pnl_pct": round(pnl_pct, 2),
            "peak_pnl_pct": round(peak_pnl, 2),
            "drawdown_from_peak_pct": round(drawdown_from_peak, 2),
            "exit_trigger": exit_trigger,
            "protective_orders": _protection_card_block(position, pnl_pct),
            "chart_path": exit_chart_path,  # Sprint 45+: position-overlay chart at the exit moment
            # ── EDGE V2 (2026-08-07, spec section B) - CONTEXT, NOT A RECOMMENDATION.
            # The map the agent wrote at entry, echoed back at the exit moment so the
            # decision is made against the thesis instead of against the chart.
            # Deliberately carries NO sell verb, NO EXIT_FULL, NO fire_sell, and
            # binding:false. path_status_hint derives ONLY from catalyst_ts age and
            # is a number-shaped FYI like every other sensor here - nothing in this
            # codebase may act on it.
            "edge_map_snapshot": (position.get("edge_map") or {}),
            "path_status_hint": _edge_path_status_hint(position.get("edge_map")),
            "edge_map_binding": False,
            # CATALYST CLOCK (spec rollout step 4). The age of the thing that was
            # supposed to make this work, surfaced at the moment of the decision.
            # Derived ONLY from catalyst_ts - no price, no sensor, no verb. A dead
            # catalyst is a reason to re-read the map, never an instruction.
            "catalyst_clock": {
                "catalyst_ts": (position.get("edge_map") or {}).get("catalyst_ts"),
                "status": _edge_path_status_hint(position.get("edge_map")),
                "binding": False,
                "_scale": "fresh <=24h | stale <=96h | dead >96h | unknown = no catalyst_ts written",
            },
            "suggested_size_band_from_map_clarity": _suggested_size_band(position.get("edge_map")),
            "edge_map_note": ("FYI only. The map you wrote at entry. Sensors, hints and "
                              "clocks never submit sells - you decide."),
            "live_state": {
                "liquidity_usd_now": liq_now,
                "liquidity_usd_at_entry": liq_at_entry,
                "mcap_now": mcap_now,
                "volume_5m_now": vol_5m_now,
                "holders_now": (holders_now or {}).get("holder_count"),
            },
            "entry_vs_exit": (lambda ec, hn, ln, mn: {
                "_doctrine": (
                    "THE ONLY QUESTION THAT MATTERS AT AN EXIT: was my READ wrong, or did the "
                    "token BETRAY a correct read? These demand OPPOSITE corrections. If the scan "
                    "was clean — rug_check clean, deployer clean, top10 healthy, LP locked — and "
                    "it rugged anyway, then TIGHTENING THE FILTER IS THE WRONG RESPONSE. The "
                    "filter was right; the thing was unknowable, and that is the cost of doing "
                    "business. But if top10 was 93% and dev held 65% AT SCAN and you bought it "
                    "anyway, that is a JUDGMENT failure and no filter tweak fixes it. "
                    "Compare the two columns before you touch a knob."
                ),
                "at_scan": {
                    "mcap": ec.get("scan_mcap"),
                    "liquidity": ec.get("scan_liq"),
                    "holders": ec.get("scan_holders"),
                    "top10_pct": ec.get("scan_top10_pct"),
                    "dev_pct": ec.get("scan_dev_pct"),
                    "rug_check": (ec.get("scan_rug_check") or {}).get("verdict")
                                 or (ec.get("scan_rug_check") or {}).get("risk_level"),
                    "lp_locked_pct": (ec.get("scan_lp_lock") or {}).get("lp_locked_pct"),
                    "deployer_rep": (ec.get("scan_deployer") or {}).get("rep"),
                    "pattern": ec.get("scan_pattern"),
                    "narrative": ec.get("scan_narrative"),
                    "band": ec.get("scan_band"),
                    "edge_passed": ec.get("scan_edge_passed"),
                    "edge_score": ec.get("scan_edge_score"),
                    "is_canonical": (ec.get("scan_brand") or {}).get("is_canonical"),
                },
                "at_exit": {
                    "mcap": mn, "liquidity": ln, "holders": hn,
                },
                "community_at_scan": {
                    "coincomms_messages": ((ec.get("scan_social") or {}).get("coincomms_ca") or {}).get("message_count"),
                    "spam_ratio": ((ec.get("scan_social") or {}).get("coincomms_ca") or {}).get("spam_ratio"),
                    "pvp_flag": (ec.get("scan_social") or {}).get("pvp_flag"),
                    "_note": ("The token's OWN chat when you bought it. If this was already thin at "
                              "scan and you bought anyway, the community case was never there — and "
                              "that is a judgment lesson, not a filter one. If it was ALIVE at scan "
                              "and is dead now, the people left before the price did, and the "
                              "question is whether you saw them go."),
                },
                "why_you_bought": position.get("reasoning_at_buy"),
                "conviction_at_buy": position.get("conviction_tier_at_buy"),
                "verdict_hint": (
                    "SCAN WAS CLEAN — this looks like a BETRAYAL, not a bad read. The signals "
                    "you had were good. Tightening the filter would cost you future winners for "
                    "no gain. Ask instead: was there ANY signal that would have caught this, or "
                    "is this simply the tax on playing?"
                    if ((ec.get("scan_rug_check") or {}).get("verdict") in ("clean", "safe", "pass")
                        and (ec.get("scan_top10_pct") or 100) < 60
                        and (ec.get("scan_dev_pct") or 100) < 15)
                    else
                    "⚠ THE SCAN WAS NOT CLEAN. Look at the at_scan column — the warning was "
                    "already there when you bought. This is a JUDGMENT failure, not a filter "
                    "failure. No amount of filter tuning fixes a decision to override a red flag. "
                    "What made you buy it anyway?"
                    if ec else
                    "No entry context available (pre-Sprint-53 position, or the originating "
                    "packet is gone). Cannot compare — judge on the numbers alone."
                ),
            })(position.get("_entry_context") or {}, (holders_now or {}).get("holder_count"), liq_now, mcap_now),
            # ── OWNER/AGENT RULING 2026-07-27: THE KOMUGI FIX ──────────────────
            # `monitor_recommendation` and `recommendation_reasoning` are DELETED.
            # They published a verdict (EXIT_FULL) in the same breath as the
            # trigger math, and the agent read it as written: "i treated EXIT_FULL
            # like an order instead of a reason input." He was +16.8% and closed
            # -12.2% on a 1.2min velocity dip.
            #
            # The rename to panic_sell was a HALF-FIX and half-fixes are worse
            # than none — it looked handled while the field carrying the
            # authority survived untouched.
            #
            # TRIGGER = FACT. ACTION = AGENT. The monitor is a sensor. It
            # reports what the numbers did. It does not name a move.
            "exit_trigger_facts": {
                "type":                exit_trigger.get("type"),
                "severity":            exit_trigger.get("severity"),
                "pnl_now_pct":         round(pnl_pct, 2),
                "pnl_basis":           ("executable — a live Jupiter quote for this exact "
                                        "position size, including price impact"
                                        if exec_pnl_pct is not None else
                                        "DexScreener mark — QUOTE UNAVAILABLE, the real exit "
                                        "may be materially worse"),
                "pnl_mark_pct":        round(mark_pnl_pct, 2),
                "pnl_executable_pct":  (round(exec_pnl_pct, 2) if exec_pnl_pct is not None else None),
                "exit_spread_pts":     exit_spread_pts,
                "spread_note":         (f"the chart shows {mark_pnl_pct:+.1f}% but you would "
                                        f"realise {exec_pnl_pct:+.1f}% — {exit_spread_pts:+.1f} "
                                        f"points of price impact on this book"
                                        if exit_spread_pts is not None and abs(exit_spread_pts) >= 2
                                        else None),
                "pnl_peak_pct":        round(peak_pnl, 2),
                "giveback_from_peak_pct": round(drawdown_from_peak, 2),
                "stop_loss_pct":       abs(float(params.get("stop_loss_pct", 20))),
                "trail_drop_pct":      abs(float(params.get("trail_drop_pct", 0)) or 0) or None,
                # any numeric the trigger itself measured (velocity, window, etc)
                **{k: v for k, v in exit_trigger.items()
                   if k not in ("type", "severity", "details") and isinstance(v, (int, float))},
                "details": exit_trigger.get("details"),
            },
        },
        # ── #1: MENU → INPUTS. These are not an action set. ──────────────────
        # Named options read like a multiple-choice test and the agent picks a row
        # instead of writing the real call. Same disease as EXIT_FULL. The verb
        # energy is stripped: "when_this_fits" describes a condition, it does not
        # issue an instruction. A blank page is always a valid answer.
        "decision_inputs": {
            "binding": False,
            "note": ("INPUTS ONLY — not a menu, not a recommendation. These describe "
                     "when each shape tends to fit. The agent writes the real action, and "
                     "writing none is valid. The monitor has no opinion on which."),
            "options": [
                {"action_type": "fire_sell_signal_full",    "when_this_fits": "thesis broken / dump confirmed"},
                {"action_type": "fire_sell_signal_partial", "when_this_fits": "conviction reduced but not gone"},
                {"action_type": "tighten_trail",            "when_this_fits": "dip inside thesis, want more locked"},
                {"action_type": "loosen_trail",             "when_this_fits": "structure intact, room to run"},
                {"action_type": "convert_mode",             "when_this_fits": "the hold/flip premise changed"},
                {"action_type": "dismiss_exit_trigger",     "when_this_fits": "noise; trust the structure"},
                {"action_type": "update_params",            "when_this_fits": "the levels themselves were wrong"},
            ],
        },
        "actions_taken": [],
    }
    
    _save_json_atomic(existing_path, packet)

    # passed-check rug box. clean scan plus a real nuke only. one case, not a rate.
    try:
        _ec = position.get("_entry_context") or {}
        _rug_v = str(((_ec.get("scan_rug_check") or {}).get("verdict") or "")).lower()
        _nuke = (
            exit_trigger.get("type") in ("liq_drain", "dev_dump_detected")
            or (pnl_pct is not None and pnl_pct <= -80)
        )
        if _rug_v in ("clean", "safe", "pass") and _nuke:
            _box_path = os.path.join(WS_BOT_LOGS, "passed_check_rug_boxes.jsonl")
            _shape = "clean_pass_then_nuke"
            if exit_trigger.get("type") == "liq_drain":
                _shape = "clean_pass_liq_drain"
            elif exit_trigger.get("type") == "dev_dump_detected":
                _shape = "clean_pass_dev_dump"
            _row = {
                "ts": _now_iso(),
                "mint": (mint or "")[:8],
                "ticker": ticker,
                "shape": _shape,
                "trigger": exit_trigger.get("type"),
                "pnl_pct": round(pnl_pct, 2) if pnl_pct is not None else None,
                "hold_minutes": int(age_min),
                "scan_rug": _rug_v,
                "n_note": "one case, not a rate",
            }
            with open(_box_path, "a", encoding="utf-8") as _bf:
                _bf.write(json.dumps(_row) + "\n")
    except Exception as _be:
        _log(f"passed-check box skipped: {_be}", prefix="monitor")

    
    # Sprint 28.7.6: log exit trigger to console too (telegram alone left no
    # console trace of triggers, so user couldn't grep when they happened).
    _log(
        f"🚨 EXIT TRIGGER: {ticker} ({_short_mint(mint)}) | "
        f"type={exit_trigger['type']} | "
        f"pnl={pnl_pct:+.1f}% (peak {peak_pnl:+.1f}%) | "
        f"{exit_trigger['details']}",
        prefix="monitor"
    )
    
    if TELEGRAM_ON_EXIT_TRIGGER:
        emoji = "🚨" if exit_trigger["severity"] == "critical" else "⚠️"
        await send_telegram(
            f"{emoji} EXIT TRIGGER: {ticker}\n"
            f"TRIGGER: {exit_trigger['type']} | "
            f"pnl {peak_pnl:+.1f}% → {pnl_pct:+.1f}% "
            f"(gave back {drawdown_from_peak:.1f}% off peak)\n"
            # Show the spread when it is wide enough to change a decision. The
            # whole KOMUGI failure was acting on a mark that was 11 points kinder
            # than the fill — if that gap exists again, it says so on the alert.
            + (f"⚠ chart says {mark_pnl_pct:+.1f}% — you'd realise {exec_pnl_pct:+.1f}% "
               f"({exit_spread_pts:+.1f} pts impact, thin book)\n"
               if (exit_spread_pts is not None and abs(exit_spread_pts) >= 2) else "")
            + (f"(price from DexScreener mark — no live quote, real exit may be worse)\n"
               if exec_pnl_pct is None else "")
            + f"{exit_trigger['details']}\n"
            f"— sensor reading. your call."
        )


# ═══════════════════════════════════════════════════════════════════════════
#                       WALLET TRACKER LOOP (owner-only)
# ═══════════════════════════════════════════════════════════════════════════

# ═══════════════════════════════════════════════════════════════════════════
#  v13.2 Drop 3 — WALLET PNL TRACKER (Option C hybrid)
# ═══════════════════════════════════════════════════════════════════════════
# 
# Tracks classified SOL deltas on the HOT TRADING WALLET (HOT_WALLET_ADDR).
# Note this is separate from wallet_tracker_loop which polls OWNER_OBSERVER
# (observer wallet) for general history. PnL tracker is hot-wallet-specific
# because that's where trades + transfers actually move money.
#
# Algorithm:
#  Every 5min (WALLET_PNL_TICK_S):
#    1. snapshot current wallet SOL balance + load WALLET_PNL_STATE_FILE
#    2. compute delta vs last snapshot
#    3. if |delta| < WALLET_PNL_SUSPICIOUS_DELTA_SOL → skip (dust/fees)
#    4. else classify the delta:
#         a) try to attribute to a recent trade (positions opened/closed in
#            last WALLET_PNL_TRADE_MATCH_WINDOW_MIN) — if found, classify
#            trade_buy or trade_sell (saves us an RPC call)
#         b) else fetch recent signatures via getSignaturesForAddress, scan
#            the last WALLET_PNL_RPC_SIG_LOOKBACK txs for SOL movements
#            involving HOT_WALLET_ADDR. Classify as external_transfer_in/out
#            or ledger_sweep_self.
#         c) else mark as "unknown" with the raw delta (the agent reviews)
#    5. append classified row to WALLET_PNL_HISTORY_LOG
#    6. update lifetime aggregates in WALLET_PNL_STATE_FILE
#
# Output schema (one row per classified delta):
#   {
#     "ts": iso, "delta_sol": float, "wallet_sol_before": float,
#     "wallet_sol_after": float, "classification": "trade_buy"|"trade_sell"|
#       "external_transfer_in"|"external_transfer_out"|"ledger_sweep_self"|
#       "unknown",
#     "tx_signature": str | None, "matched_position_mint": str | None,
#     "matched_position_ticker": str | None, "counterparty": str | None,
#     "_source": "trade_match" | "rpc_lookup" | "unknown"
#   }


def _load_wallet_pnl_state() -> dict:
    """Load WALLET_PNL_STATE_FILE with safe defaults.
    
    Schema:
      {
        "last_snapshot_sol": float,
        "last_snapshot_ts": int (epoch),
        "first_snapshot_ts": int (epoch, set on first write),
        "lifetime_trading_profit_sol": float,   # sum of trade_buy + trade_sell deltas
        "lifetime_external_in_sol": float,
        "lifetime_external_out_sol": float,
        "lifetime_ledger_sweep_sol": float,
        "lifetime_unknown_sol": float,
        "trade_count": int,
        "transfer_count": int,
        "sweep_count": int,
        "unknown_count": int,
        "last_classification_at_ts": int,
      }
    """
    default = {
        "last_snapshot_sol": 0.0,
        "last_snapshot_ts": 0,
        "first_snapshot_ts": 0,
        "lifetime_trading_profit_sol": 0.0,
        "lifetime_external_in_sol": 0.0,
        "lifetime_external_out_sol": 0.0,
        "lifetime_ledger_sweep_sol": 0.0,
        "lifetime_unknown_sol": 0.0,
        "trade_count": 0,
        "transfer_count": 0,
        "sweep_count": 0,
        "unknown_count": 0,
        "last_classification_at_ts": 0,
    }
    data = load_json_with_staleness(
        WALLET_PNL_STATE_FILE, max_age_seconds=86400 * 365,
        default=None, alert_on_stale=False,
    )
    if not isinstance(data, dict):
        return default
    # Fill missing fields with defaults (forward compat)
    for k, v in default.items():
        if k not in data:
            data[k] = v
    return data


def _save_wallet_pnl_state(state: dict) -> None:
    """Save WALLET_PNL_STATE_FILE atomically."""
    _save_json_atomic(WALLET_PNL_STATE_FILE, state)


def _wallet_pnl_history_trusted(state: dict) -> bool:
    """v13.2 Drop 3: returns True if wallet_pnl_history has enough age + entries
    to be trusted for ledger-sweep math. Returns False during the first
    WALLET_PNL_TRUST_MIN_AGE_HOURS of operation, when ledger_sweep should
    fall back to the older anchor-based math."""
    first_ts = state.get("first_snapshot_ts", 0)
    if not first_ts:
        return False
    age_hours = (_now_ts() - first_ts) / 3600.0
    return age_hours >= WALLET_PNL_TRUST_MIN_AGE_HOURS


def get_lifetime_trading_profit_sol() -> float:
    """v13.2 Drop 3: returns lifetime_trading_profit_sol from state, or 0 if
    no history yet. Used by ledger_sweep math (with trust check)."""
    state = _load_wallet_pnl_state()
    return float(state.get("lifetime_trading_profit_sol", 0) or 0)


def _match_delta_to_recent_trade(delta_sol: float) -> Optional[dict]:
    """v13.2 Drop 3: try to attribute a wallet SOL delta to a recent trade by
    scanning POSITIONS_FILE for opens/closes in the last
    WALLET_PNL_TRADE_MATCH_WINDOW_MIN that have a SOL amount within 1% of |delta|.
    
    Returns dict with {mint, ticker, side: "buy"|"sell", expected_sol} or None.
    """
    if abs(delta_sol) < WALLET_PNL_SUSPICIOUS_DELTA_SOL:
        return None
    
    positions = load_positions()
    now_ts = _now_ts()
    window_seconds = WALLET_PNL_TRADE_MATCH_WINDOW_MIN * 60
    expected_side = "sell" if delta_sol > 0 else "buy"   # positive delta = SOL in = sell
    
    best_match = None
    best_match_diff = float("inf")
    
    for mint, pos in positions.items():
        if not isinstance(pos, dict):
            continue
        
        if expected_side == "buy":
            # Look for an open event in the window
            opened_at_ts = pos.get("opened_at_ts", 0)
            if not opened_at_ts or (now_ts - opened_at_ts) > window_seconds:
                continue
            expected_sol = -abs(float(pos.get("entry_amount_sol", 0) or 0))  # outflow
        else:
            # Look for a close event in the window
            closed_at_ts = pos.get("closed_at_ts", 0)
            if not closed_at_ts or (now_ts - closed_at_ts) > window_seconds:
                continue
            expected_sol = abs(float(pos.get("exit_proceeds_sol", 0) or 0))  # inflow
        
        if expected_sol == 0:
            continue
        # Match if within 1% (allows for fees + slippage)
        diff = abs(abs(expected_sol) - abs(delta_sol))
        tolerance = max(0.005, abs(expected_sol) * 0.01)
        if diff <= tolerance and diff < best_match_diff:
            best_match = {
                "mint": mint,
                "ticker": pos.get("ticker", "?"),
                "side": expected_side,
                "expected_sol": expected_sol,
            }
            best_match_diff = diff
    
    return best_match


# OWNER'S RULING (2026-07-25, the Nenem proceeds): "it's technically not an
# external transfer, it's profit." A swap's output is TRADE money. The old
# classifier asked only "did SOL come in?" — so a sale that landed 0.1507 SOL
# (the entire Nenem stake back) was filed as an outside DEPOSIT, and deposits
# are EXCLUDED from lifetime_trading_profit_sol — the number the weekly ledger
# sweep pays home base from. Real wins would have been quietly withheld from
# the vault. A transfer is a wallet sending you SOL; a swap is a program
# handing you the other side of your own trade. Tell them apart.
_SWAP_PROGRAM_IDS = (
    "JUP6LkbZbjS1jKKwapdHNy74zcZ3tLUZoi5QNyVTaV4",   # Jupiter aggregator v6 (our router)
    "JUP4Fb2cqiRUcaTHdrPC8h2gNsA2ETXiPDD33WcGuJB",   # Jupiter v4 (legacy routes)
    "675kPX9MHTjS2zt1qfr1NYHuzeLXfQM9H24wFSUt1Mp8",  # Raydium AMM v4
    "whirLbMiicVdio4qvUfM5KAg6Ct8VwpYzGff3uctyCc",   # Orca Whirlpool
    "6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P",   # pump.fun bonding curve
    "pAMMBay6oceH9fJKBRHGP5D4bD4sWpmSwMn52FMfXEA",   # pump.fun AMM (post-graduation)
)
_SWAP_LOG_MARKERS = ("Instruction: Route", "SharedAccountsRoute", "Instruction: Swap",
                      "Instruction: Sell", "Instruction: Buy", "ray_log")


async def _classify_delta_via_rpc(delta_sol: float) -> dict:
    """v13.2 Drop 3: when a delta can't be matched to a recent trade, fetch
    the last WALLET_PNL_RPC_SIG_LOOKBACK signatures for HOT_WALLET_ADDR and
    classify by inspecting balance changes vs counterparties.
    
    Returns dict {classification, tx_signature, counterparty}:
      - "external_transfer_in":   SOL came in from an address that's NOT us
      - "external_transfer_out":  SOL went out to an address that's NOT the ledger
      - "ledger_sweep_self":      SOL went out to _HARDCODED_LEDGER_DESTINATION
      - "unknown":                couldn't classify after RPC scan
    """
    result = {
        "classification": "unknown",
        "tx_signature": None,
        "counterparty": None,
    }
    
    try:
        sigs = await helius_rpc(
            "getSignaturesForAddress",
            [HOT_WALLET_ADDR, {"limit": WALLET_PNL_RPC_SIG_LOOKBACK}],
        )
        if not sigs or not isinstance(sigs, list):
            return result
        
        # Walk sigs newest-first looking for one that explains our delta
        for sig_entry in sigs[:WALLET_PNL_RPC_SIG_LOOKBACK]:
            sig_str = sig_entry.get("signature") if isinstance(sig_entry, dict) else None
            if not sig_str:
                continue
            
            tx = await helius_rpc(
                "getTransaction",
                [sig_str, {"encoding": "jsonParsed", "maxSupportedTransactionVersion": TX_MAX_VERSION}],
            )
            if not tx or not isinstance(tx, dict):
                continue
            
            meta = tx.get("meta") or {}
            if meta.get("err"):
                continue  # failed tx — wouldn't change balance
            
            msg = (tx.get("transaction") or {}).get("message") or {}
            accounts = msg.get("accountKeys") or []
            pre_balances = meta.get("preBalances") or []
            post_balances = meta.get("postBalances") or []
            
            # Find HOT_WALLET_ADDR in accounts
            hot_idx = None
            for i, acc in enumerate(accounts):
                if isinstance(acc, dict):
                    pubkey = acc.get("pubkey", "")
                elif isinstance(acc, str):
                    pubkey = acc
                else:
                    continue
                if pubkey == HOT_WALLET_ADDR:
                    hot_idx = i
                    break
            
            if hot_idx is None or hot_idx >= len(pre_balances) or hot_idx >= len(post_balances):
                continue
            
            tx_delta_lamports = post_balances[hot_idx] - pre_balances[hot_idx]
            tx_delta_sol = tx_delta_lamports / 1_000_000_000
            
            # Does this tx delta match our snapshot delta (within tolerance)?
            tolerance = max(0.005, abs(delta_sol) * 0.05)
            if abs(tx_delta_sol - delta_sol) > tolerance:
                continue
            
            # Found a tx that explains our delta. Find counterparty:
            counterparty = None
            for i, acc in enumerate(accounts):
                if i == hot_idx:
                    continue
                if isinstance(acc, dict):
                    pubkey = acc.get("pubkey", "")
                elif isinstance(acc, str):
                    pubkey = acc
                else:
                    continue
                # Look for an account whose balance changed inversely
                if i < len(pre_balances) and i < len(post_balances):
                    other_delta = post_balances[i] - pre_balances[i]
                    if other_delta * tx_delta_lamports < 0 and abs(other_delta) > 1_000_000:  # >0.001 SOL change
                        counterparty = pubkey
                        break
            
            result["tx_signature"] = sig_str
            result["counterparty"] = counterparty
            
            # Is this tx a SWAP? (the owner's ruling — swap output is profit, not a
            # deposit.) Two independent tells: a known swap program among the
            # account keys, or a router/AMM instruction in the logs.
            _is_swap = False
            try:
                _keys_blob = json.dumps(accounts)[:12000]
                _logs_blob = " ".join((meta.get("logMessages") or [])[:60])[:12000]
                _is_swap = (any(pid in _keys_blob for pid in _SWAP_PROGRAM_IDS)
                             or any(m in _logs_blob for m in _SWAP_LOG_MARKERS))
            except Exception:
                pass
            result["is_swap"] = _is_swap
            
            # Classify by direction + counterparty
            if tx_delta_sol < 0:
                # Outflow
                if counterparty == _HARDCODED_LEDGER_DESTINATION:
                    result["classification"] = "ledger_sweep_self"
                elif _is_swap:
                    result["classification"] = "trade_buy"      # SOL spent INTO a swap
                else:
                    result["classification"] = "external_transfer_out"
            else:
                # Inflow
                if _is_swap:
                    result["classification"] = "trade_sell"     # swap PROCEEDS = trading profit
                    _log(f"wallet_pnl: inflow {delta_sol:+.4f} SOL is SWAP PROCEEDS "
                         f"(tx {sig_str[:8]}..) — booked as trade_sell, not a deposit", prefix="walletpnl")
                else:
                    result["classification"] = "external_transfer_in"
            
            return result
        
    except Exception as e:
        _log(f"wallet_pnl: rpc classification err: {e}", prefix="walletpnl")
    
    return result


async def wallet_pnl_tracker_loop() -> None:
    """v13.2 Drop 3: continuous + on-demand classification of hot-wallet SOL
    deltas. Writes WALLET_PNL_HISTORY_LOG + WALLET_PNL_STATE_FILE."""
    _log("wallet_pnl_tracker: starting", prefix="walletpnl")
    
    # Boot: take an initial snapshot if state is empty
    state = _load_wallet_pnl_state()
    if not state.get("last_snapshot_ts"):
        try:
            current = await get_wallet_sol_value(HOT_WALLET_ADDR)
            state["last_snapshot_sol"] = round(current, 6)
            state["last_snapshot_ts"] = _now_ts()
            state["first_snapshot_ts"] = _now_ts()
            _save_wallet_pnl_state(state)
            _log(
                f"wallet_pnl_tracker: first-boot snapshot taken at {current:.6f} SOL. "
                f"Trust window: {WALLET_PNL_TRUST_MIN_AGE_HOURS}h. "
                f"Ledger sweep math will fall back to anchor-based until then.",
                prefix="walletpnl",
            )
        except Exception as e:
            _log(f"wallet_pnl_tracker: boot snapshot err: {e}", prefix="walletpnl")
    
    while True:
        if await get_override("WALLET_PNL_TRACKER_PAUSED", False):
            await write_heartbeat("wallet_pnl_tracker", "paused", {"paused_via": "meeting_override"})
            await asyncio.sleep(60)
            continue
        
        try:
            state = _load_wallet_pnl_state()
            current_sol = await _wallet_sol_balance()
            if current_sol is None:
                _log("wallet_pnl_tracker: balance read failed, snapshot unchanged", prefix="walletpnl")
                await write_heartbeat("wallet_pnl_tracker", "read_failed", {"snapshot_kept": True})
                await asyncio.sleep(WALLET_TICK_S)
                continue
            last_sol = float(state.get("last_snapshot_sol", 0))
            # v14: fake-zero guard. A 0 read against a funded snapshot is almost
            # always a bad RPC answer; confirm once before booking it. A zero
            # snapshot (bad boot read) is reseeded silently instead of a "+N" row.
            if current_sol <= WALLET_PNL_ZERO_GUARD_SOL and last_sol > 0.01:
                await asyncio.sleep(5)
                _again = await _wallet_sol_balance()
                if _again is None or _again > WALLET_PNL_ZERO_GUARD_SOL:
                    _log(f"wallet_pnl_tracker: ignored suspicious zero read (snapshot {last_sol:.4f})", prefix="walletpnl")
                    await asyncio.sleep(WALLET_TICK_S)
                    continue
            if last_sol <= WALLET_PNL_ZERO_GUARD_SOL and current_sol > 0.01:
                state["last_snapshot_sol"] = round(current_sol, 6)
                state["last_snapshot_ts"] = _now_ts()
                _save_wallet_pnl_state(state)
                _log(f"wallet_pnl_tracker: reseeded zero snapshot at {current_sol:.4f} (no row)", prefix="walletpnl")
                await asyncio.sleep(WALLET_TICK_S)
                continue
            delta_sol = current_sol - last_sol
            
            await write_heartbeat("wallet_pnl_tracker", "polling", {
                "current_sol": round(current_sol, 6),
                "last_sol": round(last_sol, 6),
                "delta_sol": round(delta_sol, 6),
                "lifetime_trading_profit_sol": round(state.get("lifetime_trading_profit_sol", 0), 6),
            })
            
            if abs(delta_sol) < WALLET_PNL_SUSPICIOUS_DELTA_SOL:
                # Dust / fees — just update snapshot, no classification
                state["last_snapshot_sol"] = round(current_sol, 6)
                state["last_snapshot_ts"] = _now_ts()
                _save_wallet_pnl_state(state)
            else:
                # Classify the delta
                classification = "unknown"
                tx_signature = None
                counterparty = None
                matched_position_mint = None
                matched_position_ticker = None
                source = "unknown"
                
                # Step a: try to attribute to a recent trade
                trade_match = _match_delta_to_recent_trade(delta_sol)
                if trade_match:
                    classification = f"trade_{trade_match['side']}"
                    matched_position_mint = trade_match["mint"]
                    matched_position_ticker = trade_match["ticker"]
                    source = "trade_match"
                else:
                    # Step b: RPC lookup
                    rpc_result = await _classify_delta_via_rpc(delta_sol)
                    classification = rpc_result["classification"]
                    tx_signature = rpc_result["tx_signature"]
                    counterparty = rpc_result["counterparty"]
                    source = "rpc_lookup" if classification != "unknown" else "unknown"
                
                # Append classified row to history
                row = {
                    "ts": _now_iso(),
                    "delta_sol": round(delta_sol, 6),
                    "wallet_sol_before": round(last_sol, 6),
                    "wallet_sol_after": round(current_sol, 6),
                    "classification": classification,
                    "tx_signature": tx_signature,
                    "matched_position_mint": matched_position_mint,
                    "matched_position_ticker": matched_position_ticker,
                    "counterparty": counterparty,
                    "_source": source,
                }
                _append_jsonl(WALLET_PNL_HISTORY_LOG, row)
                
                # Update lifetime aggregates
                if classification in ("trade_buy", "trade_sell"):
                    state["lifetime_trading_profit_sol"] = round(
                        float(state.get("lifetime_trading_profit_sol", 0)) + delta_sol, 6
                    )
                    state["trade_count"] = int(state.get("trade_count", 0)) + 1
                elif classification == "external_transfer_in":
                    state["lifetime_external_in_sol"] = round(
                        float(state.get("lifetime_external_in_sol", 0)) + delta_sol, 6
                    )
                    state["transfer_count"] = int(state.get("transfer_count", 0)) + 1
                elif classification == "external_transfer_out":
                    state["lifetime_external_out_sol"] = round(
                        float(state.get("lifetime_external_out_sol", 0)) + abs(delta_sol), 6
                    )
                    state["transfer_count"] = int(state.get("transfer_count", 0)) + 1
                elif classification == "ledger_sweep_self":
                    state["lifetime_ledger_sweep_sol"] = round(
                        float(state.get("lifetime_ledger_sweep_sol", 0)) + abs(delta_sol), 6
                    )
                    state["sweep_count"] = int(state.get("sweep_count", 0)) + 1
                else:
                    state["lifetime_unknown_sol"] = round(
                        float(state.get("lifetime_unknown_sol", 0)) + delta_sol, 6
                    )
                    state["unknown_count"] = int(state.get("unknown_count", 0)) + 1
                
                # Update snapshot
                state["last_snapshot_sol"] = round(current_sol, 6)
                state["last_snapshot_ts"] = _now_ts()
                state["last_classification_at_ts"] = _now_ts()
                _save_wallet_pnl_state(state)
                
                _log(
                    f"wallet_pnl: classified delta {delta_sol:+.4f} SOL as {classification} "
                    f"(source={source}, lifetime_trading={state['lifetime_trading_profit_sol']:+.4f} SOL)",
                    prefix="walletpnl",
                )
                
                # Telegram alert on external transfers (informational)
                if classification in ("external_transfer_in", "external_transfer_out"):
                    direction_arrow = "←" if classification == "external_transfer_in" else "→"
                    cp_short = (counterparty[:8] + "..." + counterparty[-4:]) if counterparty else "?"
                    await send_telegram(
                        f"💸 hot wallet {direction_arrow} {abs(delta_sol):.4f} SOL "
                        f"({classification.replace('_', ' ')})\n"
                        f"counterparty: {cp_short}\n"
                        f"wallet now: {current_sol:.4f} SOL"
                    )
        except Exception as e:
            _log(f"wallet_pnl_tracker cycle err: {e}", prefix="walletpnl")
            await write_heartbeat("wallet_pnl_tracker", "error", {"last_error": str(e)[:200]})
        
        await asyncio.sleep(WALLET_TICK_S)


async def wallet_tracker_loop() -> None:
    """OBSERVER wallet history. NOT the hot wallet. Every 5min -> wallet_history.json.

    ── FIX 1 (2026-08-16): THE DOCSTRING NAMED THE WRONG ADDRESS ───────────────
    This said "Polls the owner's hot wallet." It does not and never did. The body
    reads OWNER_OBSERVER, and the snapshot it writes stamps `"wallet":
    OWNER_OBSERVER` - so the file has always been honest while the docstring, the
    function name, the log prefix and the skill's loop table all said "wallet",
    which anyone reasonably reads as the wallet that trades.

    That is how a desk reconciles the wrong SOL: someone sizes or checks a fill
    against wallet_history.json, gets a number from an address the bot cannot
    spend from, and it looks like a book discrepancy instead of a name collision.
    The comment above wallet_pnl_tracker_loop already spells the split out; the
    docstring on THIS function is where the wrong idea was being handed over.

    Three wallets, three jobs, and only one of them is money the bot can move:
      HOT_WALLET_ADDR  ammo + execution. Its history is wallet_pnl_tracker_loop.
      LEDGER (home base) vault only. Hardcoded sweep destination.
      OWNER_OBSERVER    watched, never signalled on, never spent from. THIS loop.

    The function name is left alone on purpose - it is referenced by the
    WALLET_TRACKER_PAUSED knob, by the supervised task roster and by the
    heartbeat filename the overseer checks by exact name, and renaming it to fix
    a docstring would break the monitor to fix a comment. The strings that
    mislead a reader are what changed.
    """
    _log("observer_history: starting , snapshots OWNER_OBSERVER (NOT the hot wallet; "
         "hot-wallet history is wallet_pnl_tracker_loop)", prefix="observer_history")
    
    while True:
        # Sprint 32: respect WALLET_TRACKER_PAUSED meeting override
        if await get_override("WALLET_TRACKER_PAUSED", False):
            await write_heartbeat("wallet_tracker", "paused", {"paused_via": "meeting_override"})
            await asyncio.sleep(60)
            continue
        
        await write_heartbeat("wallet_tracker", "polling")
        
        try:
            sol_balance = await get_wallet_sol_value(OWNER_OBSERVER)
            tokens = await get_wallet_token_balances(OWNER_OBSERVER)
            
            history = load_json_with_staleness(WALLET_HISTORY_FILE, max_age_seconds=86400 * 30, default={"snapshots": []}, alert_on_stale=False)
            if not isinstance(history, dict):
                history = {"snapshots": []}
            history.pop("_meta", None)
            
            snapshot = {
                "timestamp": _now_iso(),
                "wallet": OWNER_OBSERVER,
                # FIX 1: say it in the data too, so a reader who never opens the
                # code cannot mistake this file for the trading wallet.
                "wallet_role": "observer",
                "is_hot_wallet": False,
                "_doctrine": ("Observer address. The bot never signals on it and cannot "
                               "spend from it. Hot-wallet history lives in "
                               "wallet_pnl_state.json / wallet_pnl_history.jsonl."),
                "sol_balance": round(sol_balance, 6),
                "token_count": len(tokens),
                "tokens_summary": [
                    {"mint": t["mint"][:12], "ui_amount": t["ui_amount"]}
                    for t in tokens[:20]
                ],
            }
            
            history.setdefault("snapshots", []).append(snapshot)
            # Keep last 7 days of snapshots (assuming 5min intervals = 2016 snapshots)
            history["snapshots"] = history["snapshots"][-2100:]
            history["last_update"] = _now_iso()
            
            _save_json_atomic(WALLET_HISTORY_FILE, history)
        except Exception as e:
            _log(f"observer_history: error: {e}", prefix="observer_history")
        
        await asyncio.sleep(WALLET_TICK_S)


