#                       CA RESEARCH RESPONDER LOOP
# ═══════════════════════════════════════════════════════════════════════════
#
# Token Father auto-trigger. research responder writes a CA research request when it
# detects a CA mention anywhere (DM, X mention, web result). Sniper vets it
# and writes a ca_intel inbox packet.
# ═══════════════════════════════════════════════════════════════════════════

# ════════════════════════════════════════════════════════════════════════════
# v14.2 UNIFIED RANKING: KOL handles, dev wallets and tracked wallets share one
# stats shape (the wallet tracker's: trades, wins, hit_rate, avg_pnl_pct, ready)
# and one tier function. KOL/dev "trades" are TOKEN outcomes after the mention or
# launch (mcap at RANK_WINDOWS_H vs mention mcap, peak multiple, rug), whether or
# not the agent bought. Outcomes come from DexScreener only (no Helius credits).
# DATA ONLY: nothing here trades. KOL list changes auto-apply unless
# KOL_AUTO_APPLY=false; default true (agent-decided). kol_* signals apply directly.
# ════════════════════════════════════════════════════════════════════════════
RANK_STORE_FILE      = _BOT_LOGS / "entity_rank_store.json"
PROMOTER_MENTIONS_LOG = _BOT_LOGS / "promoter_mentions.jsonl"
DEV_WALLET_RANK_FILE = _BOT_LOGS / "dev_wallet_rank.json"
_RANK_TIER_ORDER = ["rugger", "T4", "T3", "T2", "T1", "T0"]
_RANK_STORE_CACHE: dict = {}


def _rank_load() -> dict:
    if _RANK_STORE_CACHE.get("data") is not None:
        return _RANK_STORE_CACHE["data"]
    d = {}
    try:
        with open(RANK_STORE_FILE, encoding="utf-8") as f:
            d = json.load(f) or {}
    except Exception:
        d = {}
    d.setdefault("entities", {})
    _RANK_STORE_CACHE["data"] = d
    return d


def _rank_save(force: bool = False) -> None:
    d = _RANK_STORE_CACHE.get("data")
    if d is None:
        return
    if not force and time.monotonic() - _RANK_STORE_CACHE.get("saved", 0) < 30:
        return
    _RANK_STORE_CACHE["saved"] = time.monotonic()
    ents = d.get("entities") or {}
    if len(ents) > RANK_MAX_ENTITIES:
        for k in sorted(ents, key=lambda k: ents[k].get("last_seen_ts") or 0)[:len(ents) - RANK_MAX_ENTITIES]:
            ents.pop(k, None)
    d["updated_at"] = _now_iso()
    try:
        _save_json_atomic(RANK_STORE_FILE, d)
    except Exception as e:
        _log(f"rank store save err: {e}", prefix="rank")


def _kol_seed_index() -> dict:
    """handle(lower) -> {tier, weight}; highest weight wins on duplicates."""
    c = _RANK_STORE_CACHE.get("seed")
    if c and time.monotonic() - c[0] < 300:
        return c[1]
    idx = {}
    try:
        with open(KOL_LIST_FILE, encoding="utf-8-sig") as f:
            kd = json.load(f) or {}
        for tname, tdata in (kd.get("tiers") or {}).items():
            if not isinstance(tdata, dict):
                continue
            w = tdata.get("shill_weight") or 0
            for k in tdata.get("kols") or []:
                h = str((k or {}).get("handle") or "").lstrip("@").lower()
                if h and (h not in idx or w > idx[h]["weight"]):
                    idx[h] = {"tier": tname, "weight": w}
        for s in kd.get("known_scammers") or []:
            h = str((s or {}).get("handle") or "").lstrip("@").lower()
            if h:
                idx[h] = {"tier": "known_scammer", "weight": RANK_TIER_WEIGHTS.get("rugger", -5)}
    except Exception:
        pass
    _RANK_STORE_CACHE["seed"] = (time.monotonic(), idx)
    return idx


def kol_seed_lookup(handle: str) -> dict:
    return _kol_seed_index().get(str(handle or "").lstrip("@").lower()) or {}


def _rank_key(kind: str, ident: str) -> str:
    ident = str(ident or "")
    return f"{kind}:{ident.lstrip('@').lower() if kind == 'kol' else ident}"


def _rank_entity(kind: str, ident: str, source: str) -> dict:
    d = _rank_load()
    k = _rank_key(kind, ident)
    e = d["entities"].get(k)
    if not e:
        e = {"kind": kind, "id": ident.lstrip("@") if kind == "kol" else ident, "source": source,
             "added_at": _now_iso(), "first_seen_ts": _now_ts(), "calls": [], "stats": {}}
        d["entities"][k] = e
    return e


def _rank_add_call(e: dict, mint: str, at_ts: float, mcap0, ticker=None, extra=None) -> bool:
    for c in e["calls"]:
        if c.get("mint") == mint:
            return False          # one call per entity per token
    c = {"mint": mint, "ticker": ticker, "at_ts": float(at_ts), "mcap0": float(mcap0) if mcap0 else None,
         "w": {}, "peak_mcap": float(mcap0) if mcap0 else None, "rugged": False, "resolved": False}
    if extra:
        c.update(extra)
    e["calls"].append(c)
    e["calls"] = e["calls"][-RANK_MAX_CALLS_PER_ENTITY:]
    e["last_seen_ts"] = _now_ts()
    e["last_seen_at"] = _now_iso()
    return True


def record_promoter_mention(handle: str, mint: str, *, ticker=None, source="x", posted_at=None,
                            url=None, mcap=None, at_ts=None) -> None:
    """Log one handle promoting one token. Feeds KOL scoring."""
    h = str(handle or "").lstrip("@").strip()
    if not h or not mint:
        return
    ts = at_ts
    if not ts and posted_at:
        try:
            ts = datetime.fromisoformat(str(posted_at).replace("Z", "+00:00")).timestamp()
        except Exception:
            ts = None
    ts = float(ts or _now_ts())
    e = _rank_entity("kol", h, source)
    if _rank_add_call(e, mint, ts, mcap, ticker, {"source": source}):
        try:
            _append_jsonl(PROMOTER_MENTIONS_LOG, {"ts": _now_iso(), "handle": h, "mint": mint, "ticker": ticker,
                                                  "posted_at": posted_at, "mcap": mcap, "source": source, "url": url})
        except Exception:
            pass
        _rank_save()


def record_dev_launch(dev: str, mint: str, *, ticker=None, mcap=None) -> None:
    if not RANK_DEV_TRACK or not dev or not mint:
        return
    e = _rank_entity("dev", dev, "scan")
    if _rank_add_call(e, mint, _now_ts(), mcap, ticker, {"source": "launch"}):
        _rank_save()


def _call_pnl(c: dict) -> Optional[float]:
    """Token outcome at the score window, as a percent vs mention/launch mcap."""
    if c.get("rugged"):
        return -100.0
    m0 = c.get("mcap0")
    if not m0:
        return None
    wkeys = sorted(c.get("w") or {}, key=lambda x: float(x))
    pick = None
    for wk in wkeys:
        if float(wk) <= RANK_SCORE_WINDOW_H:
            pick = c["w"][wk]
    if pick is None and wkeys:
        pick = c["w"][wkeys[-1]]
    if pick is None:
        return None
    return max(-100.0, min(5000.0, (float(pick) / float(m0) - 1) * 100))


def rank_stats(calls: list) -> dict:
    """Same keys as _compute_wallet_pnl, plus rug + peak, over RESOLVED-enough calls."""
    rows = []
    rugs = 0
    peaks = []
    for c in calls or []:
        p = _call_pnl(c)
        if p is None:
            continue
        rows.append(p)
        if c.get("rugged"):
            rugs += 1
        if c.get("mcap0") and c.get("peak_mcap"):
            peaks.append(float(c["peak_mcap"]) / float(c["mcap0"]))
    n = len(rows)
    wins = sum(1 for p in rows if p >= RANK_WIN_PCT)
    return {
        "trades": n, "wins": wins,
        "hit_rate": round(100 * wins / n, 1) if n else None,
        "avg_pnl_pct": round(sum(rows) / n, 1) if n else None,
        "total_pnl_pts": round(sum(rows), 1) if n else 0,
        "rug_count": rugs, "rug_rate": round(rugs / n, 3) if n else 0.0,
        "avg_peak_mult": round(sum(peaks) / len(peaks), 2) if peaks else None,
        "ready": n >= RANK_MIN_CALLS,
    }


def rank_tier(stats: dict, archetype: Optional[str] = None) -> str:
    """ONE tier function for KOLs, devs and wallets."""
    if archetype == "bot":
        return "bot"      # livefix: bot/bundler wallets never rank (weight 0)
    if not stats or not stats.get("ready"):
        return "unproven"
    if archetype == "rugger" or float(stats.get("rug_rate") or 0) >= RANK_RUG_RATE_BAD:
        return "rugger"
    hit = float(stats.get("hit_rate") or 0)
    avg = float(stats.get("avg_pnl_pct") or 0)
    if hit >= RANK_T1_HIT and avg >= RANK_T1_AVG:
        return "T1"
    if hit >= RANK_T2_HIT and avg >= 0:
        return "T2"
    if hit >= RANK_T3_HIT:
        return "T3"
    return "T4"


def entity_card(kind: str, ident: str) -> dict:
    """Tier / weight / track record block for cards. Short ids for wallets."""
    if not ident:
        return {}
    e = (_rank_load().get("entities") or {}).get(_rank_key(kind, ident)) or {}
    st = e.get("stats") or {}
    seed = kol_seed_lookup(ident) if kind == "kol" else {}
    tier = e.get("tier") or "unproven"
    shown = tier if (tier != "unproven" or not seed) else seed.get("tier")
    w = (seed.get("weight") if (tier == "unproven" and seed) else RANK_TIER_WEIGHTS.get(tier, 1))
    return {
        "kind": kind,
        "id": (f"@{ident.lstrip('@')}" if kind == "kol" else _short_mint(ident)),
        "tier": shown, "rank_tier": tier, "seed_tier": seed.get("tier"), "weight": w,
        "calls": st.get("trades", 0), "hit_rate": st.get("hit_rate"), "avg_pnl_pct": st.get("avg_pnl_pct"),
        "rug_rate": st.get("rug_rate"), "avg_peak_mult": st.get("avg_peak_mult"), "ready": bool(st.get("ready")),
        "score_window_h": RANK_SCORE_WINDOW_H,
    }


def _rank_enrich_candidate(packet: dict) -> None:
    ctx = packet.get("context") or {}
    mint = ctx.get("mint")
    mcap = (ctx.get("dex_data") or {}).get("mcap") or ctx.get("mcap")
    dev = (ctx.get("deployer_history") or {}).get("address")
    if dev:
        record_dev_launch(dev, mint, ticker=ctx.get("ticker"), mcap=mcap)
        ctx["dev_rank"] = entity_card("dev", dev)
    # stamp mention mcap where the mention was logged before we had a price
    proms = []
    for k, e in (_rank_load().get("entities") or {}).items():
        if e.get("kind") != "kol":
            continue
        for c in e.get("calls") or []:
            if c.get("mint") == mint:
                if not c.get("mcap0") and mcap:
                    c["mcap0"] = float(mcap)
                    c["peak_mcap"] = float(mcap)
                    c["mcap0_source"] = "first_scan"
                card = entity_card("kol", e["id"])
                card["mentioned_at"] = datetime.fromtimestamp(c["at_ts"]).isoformat(timespec="seconds")
                card["mcap_at_mention"] = c.get("mcap0")
                proms.append(card)
    if proms:
        proms.sort(key=lambda r: -(r.get("weight") or 0))
        ctx["promoters"] = proms[:10]
        ctx["promoter_weight_sum"] = sum((r.get("weight") or 0) for r in proms[:10])
    packet["context"] = ctx


def _rank_refresh_entity(e: dict) -> None:
    e["stats"] = rank_stats(e.get("calls"))
    e["tier"] = rank_tier(e["stats"])


async def _rank_check_outcomes() -> int:
    """One pass: sample DexScreener for unresolved calls at their windows."""
    d = _rank_load()
    now = _now_ts()
    maxw = max(RANK_WINDOWS_H) if RANK_WINDOWS_H else 24
    due = {}
    for e in d["entities"].values():
        for c in e.get("calls") or []:
            if c.get("resolved"):
                continue
            due.setdefault(c["mint"], []).append((e, c))
    fetched = 0
    for mint, refs in sorted(due.items(), key=lambda kv: min(c["at_ts"] for _, c in kv[1])):
        if fetched >= RANK_FETCH_PER_CYCLE:
            break
        try:
            pair = await fetch_token_data(mint)
        except Exception:
            pair = None
        fetched += 1
        mc = float((pair or {}).get("marketCap") or (pair or {}).get("fdv") or 0) if pair else 0.0
        liq = float(((pair or {}).get("liquidity") or {}).get("usd") or 0) if pair else 0.0
        touched = set()
        for e, c in refs:
            if not c.get("mcap0") and mc > 0:
                c["mcap0"] = mc
                c["peak_mcap"] = mc
                c["mcap0_source"] = "first_check"
            if mc > 0 and mc > float(c.get("peak_mcap") or 0):
                c["peak_mcap"] = mc
            age_h = (now - c["at_ts"]) / 3600
            for wh in RANK_WINDOWS_H:
                wk = f"{wh:g}"
                if age_h >= wh and wk not in c["w"]:
                    c["w"][wk] = mc
            if c.get("mcap0") and ((pair and liq < RANK_RUG_LIQ_USD) or
                                   (mc > 0 and mc < float(c["mcap0"]) * RANK_RUG_DROP_MULT)):
                c["rugged"] = True
            if age_h >= maxw or c.get("rugged"):
                c["resolved"] = True
            touched.add(id(e))
            _rank_refresh_entity(e)
        await asyncio.sleep(0.2)
    _rank_save(force=True)
    return fetched


def _kol_proposals_for(e: dict, seed: dict) -> list:
    """Compare a scored handle with kol_list.json and say what should change."""
    out = []
    st = e.get("stats") or {}
    tier = e.get("tier") or "unproven"
    cur = (seed.get("tier") or "")
    cur_short = cur.split("_")[0] if cur else None
    h = e["id"]
    stale = (_now_ts() - float(e.get("last_seen_ts") or _now_ts())) > RANK_STALE_DAYS * 86400
    base = {"handle": h, "stats": st, "rank_tier": tier, "from_tier": cur or None, "at": _now_iso()}
    if cur and stale:
        out.append({**base, "action": "kol_demote" if cur_short != "T4" else "kol_remove",
                    "why": f"unseen {RANK_STALE_DAYS:.0f}d"})
        return out
    if not st.get("ready"):
        return out
    if tier == "rugger":
        out.append({**base, "action": "kol_mark_scammer", "why": f"rug rate {st.get('rug_rate')}"})
        return out
    if not cur and tier in ("T1", "T2"):
        out.append({**base, "action": "kol_add", "to_tier": tier, "why": "auto-discovery: scored calls"})
        return out
    if cur and cur_short in _RANK_TIER_ORDER and cur_short != "T0":
        a, b = _RANK_TIER_ORDER.index(tier), _RANK_TIER_ORDER.index(cur_short)
        if a != b:
            if st.get("trades", 0) >= RANK_PRUNE_MIN_CALLS and (st.get("avg_pnl_pct") or 0) < 0 and cur_short == "T4":
                out.append({**base, "action": "kol_remove", "why": "net negative calls"})
            else:
                out.append({**base, "action": "kol_promote" if a > b else "kol_demote", "to_tier": tier,
                            "why": "scored calls disagree with seed tier"})
    return out


def _kol_full_tier_name(kd: dict, short: str) -> Optional[str]:
    for k in (kd.get("tiers") or {}):
        if k.split("_")[0] == short:
            return k
    return None


def _kol_apply_change(kd: dict, p: dict, approver: str) -> bool:
    h = p["handle"]
    act = p["action"]
    tiers = kd.setdefault("tiers", {})
    to_full = _kol_full_tier_name(kd, p.get("to_tier") or "") if p.get("to_tier") else None
    def _drop():
        for td in tiers.values():
            td["kols"] = [k for k in td.get("kols") or [] if str(k.get("handle", "")).lower() != h.lower()]
    if act in ("kol_add", "kol_promote", "kol_demote"):
        if not to_full:
            return False
        _drop()
        tiers[to_full].setdefault("kols", []).append({"handle": h, "name": h})
    elif act == "kol_remove":
        _drop()
    elif act == "kol_mark_scammer":
        _drop()
        kd.setdefault("known_scammers", []).append({"handle": h, "marked_at": _now_iso(), "reason": p.get("why")})
    else:
        return False
    kd.setdefault("_provenance", {}).setdefault("change_log", []).append(
        {"at": _now_iso(), "action": act, "target_handle": h, "from_tier": p.get("from_tier"),
         "to_tier": to_full, "reasoning": p.get("why"), "approver": approver, "stats": p.get("stats")})
    return True


def write_rank_outputs() -> dict:
    """kol_list_proposals.json + dev_wallet_rank.json from the shared store."""
    d = _rank_load()
    seed = _kol_seed_index()
    props = []
    devs = []
    for e in d["entities"].values():
        if e.get("kind") == "kol":
            props += _kol_proposals_for(e, seed.get(e["id"].lower()) or {})
        elif e.get("kind") == "dev" and (e.get("stats") or {}).get("trades"):
            devs.append({"dev": e["id"], "short": _short_mint(e["id"]), "tier": e.get("tier"),
                         "weight": RANK_TIER_WEIGHTS.get(e.get("tier") or "unproven", 1),
                         "launches": len(e.get("calls") or []), "stats": e.get("stats"),
                         "last_seen_at": e.get("last_seen_at")})
    wallets = []
    try:
        for addr, m in (_wallet_load(WALLET_MATCHED_FILE) or {}).items():
            tr = (m or {}).get("tracking") or {}
            if tr.get("trades"):
                wallets.append({"wallet": addr, "short": _short_mint(addr), "name": m.get("name"),
                                "tier": tr.get("rank") or rank_tier({**tr, "rug_rate": 0.0}, tr.get("archetype")),
                                "archetype": tr.get("archetype"),
                                "stats": {k: tr.get(k) for k in ("trades", "hit_rate", "avg_pnl_pct", "total_sol_pnl", "ready")}})
    except Exception:
        pass
    order = {t: i for i, t in enumerate(["T0", "T1", "T2", "T3", "T4", "unproven", "rugger"])}
    devs.sort(key=lambda r: (order.get(r["tier"], 9), -(r["stats"].get("avg_pnl_pct") or 0)))
    wallets.sort(key=lambda r: (order.get(r["tier"], 9), -(r["stats"].get("avg_pnl_pct") or 0)))
    applied = 0
    if KOL_AUTO_APPLY and props:
        try:
            with open(KOL_LIST_FILE, encoding="utf-8-sig") as f:
                kd = json.load(f) or {}
            for p in props:
                if _kol_apply_change(kd, p, "auto(KOL_AUTO_APPLY)"):
                    p["applied"] = True
                    applied += 1
            if applied:
                _save_json_atomic(KOL_LIST_FILE, kd)
                _RANK_STORE_CACHE.pop("seed", None)
        except Exception as ex:
            _log(f"kol auto-apply err: {ex}", prefix="rank")
    try:
        _save_json_atomic(KOL_PROPOSALS_FILE, {
            "updated_at": _now_iso(), "auto_apply": KOL_AUTO_APPLY, "applied_now": applied,
            "how_to_apply": ("auto when KOL_AUTO_APPLY=true (default), or the agent writes a kol_* signal "
                             "(action, target_handle, from_tier, to_tier). No owner sign-off."),
            "scoring": {"windows_h": RANK_WINDOWS_H, "score_window_h": RANK_SCORE_WINDOW_H,
                        "win_pct": RANK_WIN_PCT, "min_calls": RANK_MIN_CALLS},
            "proposals": props[:300]})
        _save_json_atomic(DEV_WALLET_RANK_FILE, {
            "updated_at": _now_iso(), "method": "rank_tier() shared with KOL scoring",
            "devs": devs[:2000], "wallets": wallets[:500],
            "dev_ruggers": [r["short"] for r in devs if r["tier"] == "rugger"][:200]})
    except Exception as ex:
        _log(f"rank outputs write err: {ex}", prefix="rank")
    return {"proposals": len(props), "devs": len(devs), "wallets": len(wallets), "applied": applied}


async def entity_rank_loop() -> None:
    """Score KOL mentions and dev launches on token outcomes (DexScreener)."""
    _log("rank: starting (KOL + dev + wallet unified ranking; outcomes via DexScreener)", prefix="rank")
    while True:
        try:
            n = await _rank_check_outcomes()
            out = write_rank_outputs()
            await write_heartbeat("entity_rank", "ok", {"fetched": n, **out})
        except Exception as e:
            _log(f"rank loop err: {e}", prefix="rank")
        await asyncio.sleep(RANK_OUTCOME_LOOP_S)


_WALLET_MOVES_SEEN: set = set()   # livefix: (sig, mint, side) already processed this run


async def wallet_tracking_loop() -> None:
    """Sprint 65 — the active-tracking engine. Every cycle:
      1. PROMOTE: matched wallets that hit the tally threshold get a tracking block +
         a 'New Wallet Found' packet so the agent can review + name them.
      2. POLL: refresh PnL/hit-rate for each actively-tracked wallet (from tracking
         start), and detect NEW moves → enrich through the sniper → Wallet Tracker packet.
      3. DROP: a tracked wallet that's cleared the 5-trade floor but gone net-negative
         loses its slot (and gets removed from polling).
    All of this is DATA for the agent — it never trades on its own.
    """
    _log("wallet_tracking: starting", prefix="wallet")
    while True:
        try:
            # 0. drain the agent's wallet commands (name / untrack) — the receiver that
            # makes name_and_track actually DO something instead of evaporating.
            try:
                if WALLET_COMMAND_FILE.exists():
                    try:
                        cmds = json.loads(WALLET_COMMAND_FILE.read_text(encoding="utf-8") or "{}")
                    except Exception as _wje:
                        cmds = None
                        _agent_memo("wallet_command", False, "wallet_command.json unreadable, dropped",
                                    reason=f"bad JSON: {type(_wje).__name__}")
                    if isinstance(cmds, dict):
                        _wres = _apply_wallet_commands(cmds)
                        _agent_memo("wallet_command", _wres is not False,
                                    f"wallet_command applied: name={len(cmds.get('name') or {})} "
                                    f"track={len(cmds.get('track') or [])} untrack={len(cmds.get('untrack') or [])}"
                                    if _wres is not False else "wallet_command failed",
                                    request_id=cmds.get("id"), reason="see meme_sniper log (wallet)")
                    try:
                        WALLET_COMMAND_FILE.unlink()
                    except Exception:
                        pass
            except Exception as _wce:
                _log(f"wallet command drain err: {_wce}", prefix="wallet")

            matched = _wallet_load(WALLET_MATCHED_FILE)
            if not matched:
                await asyncio.sleep(WALLET_POLL_INTERVAL_S)
                continue

            tracked = [a for a, m in matched.items() if (m.get("tracking") or {}).get("started_ts")]

            # 1. PROMOTE new qualifiers (respect the tracked cap)
            if len(tracked) < WALLET_TRACKED_MAX:
                for addr, m in matched.items():
                    if m.get("tracking") or (WALLET_BOT_FILTER and m.get("bot_flag")):
                        continue
                    if int(m.get("tally", 0)) >= WALLET_PROMOTE_MIN_TALLY:
                        track = await update_wallet_tracking(addr)  # seeds started_ts + first PnL read
                        if track.get("bot_like"):
                            _log(f"not promoting {_short_mint(addr)}: bot-like ({track['bot_like']})", prefix="wallet")
                            _mm = _wallet_load(WALLET_MATCHED_FILE)
                            if addr in _mm:
                                _mm[addr]["tracking"] = None
                                _mm[addr]["bot_flag"] = {"reason": track["bot_like"], "at": _now_iso()}
                                _save_json_atomic(WALLET_MATCHED_FILE, _mm)
                                matched[addr] = _mm[addr]
                            continue
                        await _write_new_wallet_packet(addr, m, track)
                        tracked.append(addr)
                        if len(tracked) >= WALLET_TRACKED_MAX:
                            break

            # 2. POLL the tracked set — refresh stats + detect new moves
            for addr in list(tracked):
                m = matched.get(addr)
                if not m:
                    continue
                def _mvk(_s):
                    return (_s.get("sig") or f"ts{_s.get('ts')}", _s.get("mint"), _s.get("direction"))
                prev_swaps = {_mvk(_s) for _s in (m.get("tracking") or {}).get("recent_swaps", [])}
                prev_swaps |= {(f"ts{_s.get('ts')}", _s.get("mint"), _s.get("direction"))
                               for _s in (m.get("tracking") or {}).get("recent_swaps", [])}   # pre-sig records
                track = await update_wallet_tracking(addr)
                # any brand-new move since last poll? (once per tx signature+mint+side)
                new_moves = []
                for s in track.get("recent_swaps", []):
                    k = _mvk(s)
                    if (k in prev_swaps or (f"ts{s.get('ts')}", s.get("mint"), s.get("direction")) in prev_swaps
                            or k in _WALLET_MOVES_SEEN):
                        continue
                    _WALLET_MOVES_SEEN.add(k)
                    # 2026-10-15: a move first seen now can still be days old (first
                    # poll after tracking, or a reload) - only a recent move is news.
                    try:
                        _mts = float(s.get("ts") or 0)
                        if _mts > 1e12:
                            _mts /= 1000.0
                        if _mts and _now_ts() - _mts > float(get_override_sync("WALLET_MOVE_MAX_AGE_S", 1800)):
                            continue
                    except (TypeError, ValueError):
                        pass
                    new_moves.append(s)
                if len(_WALLET_MOVES_SEEN) > 20000:
                    _WALLET_MOVES_SEEN.clear()
                if track.get("bot_like") and new_moves:
                    _log(f"tracked wallet {m.get('name') or _short_mint(addr)} is bot-like "
                         f"({track['bot_like']}); moves not packeted", prefix="wallet")
                    new_moves = []
                for mv in new_moves:
                    if mv.get("direction") == "buy":
                        await _write_wallet_tracker_packet(addr, m, mv, track)
                        # cluster check: did OTHER tracked wallets buy this same mint
                        # in-window? Convergence = the strongest signal we make.
                        try:
                            others = _record_tracked_buy(mv.get("mint"), addr,
                                                         m.get("name"), mv.get("ts") or time.time())
                            if len(others) + 1 >= WALLET_CLUSTER_MIN_WALLETS:
                                # include this buyer in the cluster
                                all_buyers = others + [{"wallet": addr, "name": m.get("name"),
                                                        "ts": mv.get("ts")}]
                                await _write_cluster_packet(mv.get("mint"), all_buyers)
                        except Exception as _ce:
                            _log(f"cluster check err: {_ce}", prefix="wallet")
                    else:
                        # sells are logged as data (a good wallet exiting is information)
                        _log(f"tracked wallet {m.get('name') or _short_mint(addr)} SOLD "
                             f"{_short_mint(mv.get('mint'))} for {mv.get('sol_amount')} SOL",
                             prefix="wallet")

                # 3. DROP if it's cleared the floor and gone bad
                if not wallet_should_stay_tracked(track):
                    _log(f"dropping tracked wallet {m.get('name') or _short_mint(addr)}: "
                         f"{track.get('trades')} trades, avg {track.get('avg_pnl_pct')}%, "
                         f"hit {track.get('hit_rate')}% — no longer earning its slot", prefix="wallet")
                    m["tracking"] = None  # demote back to matched (keeps history, stops polling)
                    matched[addr] = m
                    _save_json_atomic(WALLET_MATCHED_FILE, matched)

        except Exception as e:
            _log(f"wallet_tracking_loop err: {e}", prefix="wallet")
        await asyncio.sleep(WALLET_POLL_INTERVAL_S)


AGENT_STATUS_FILE = _BOT_LOGS / "agent_status.json"
AGENT_STATUS_INTERVAL_S = 15
_STATUS_FAIL_PREFIX = ("rejected", "failed", "error", "errored", "invalid", "blocked")
_WARDEN_FOLLOWS_ENGINE = True


def _status_tail_jsonl(path, n: int) -> list:
    try:
        with open(path, "rb") as f:
            f.seek(0, 2); size = f.tell(); f.seek(max(0, size - 200_000))
            lines = f.read().decode("utf-8", "replace").splitlines()[-max(n * 6, 60):]
    except Exception:
        return []
    out = []
    for ln in lines:
        try:
            out.append(json.loads(ln))
        except Exception:
            continue
    return out


def build_agent_status() -> dict:
    """One file the agent reads first (2026-10-14): what is open, what is pending, what came back."""
    now = _now_ts()
    pos_out = []
    try:
        for m, p in (load_positions() or {}).items():
            if not isinstance(p, dict):
                continue
            ap = p.get("armed_protection") or {}
            pos_out.append({"mint": m, "ticker": p.get("ticker"), "mode": p.get("mode", "flip"),
                            "amount_sol": p.get("amount_sol"), "entry_price": p.get("entry_price"),
                            "opened_at": p.get("opened_at"),
                            "armed_sl_pct": ap.get("sl_pct"), "armed_tp_pct": ap.get("tp_pct"),
                            "armed_tp_sell_pct": ap.get("tp_sell_pct"),
                            "params_sl_pct": (p.get("params") or {}).get("stop_loss_pct"),
                            "trail_armed": p.get("trail_armed")})
    except Exception as e:
        pos_out = [{"error": str(e)[:120]}]
    pending = []
    try:
        for f in sorted(_JSON_RELAY.glob("*.json")):
            try:
                d = json.loads(f.read_text(encoding="utf-8") or "null")
            except Exception:
                pending.append({"file": f.name, "state": "unreadable/partial"}); continue
            rows = d if isinstance(d, list) else next((d.get(k) for k in ("requests", "signals") if isinstance(d, dict) and isinstance(d.get(k), list)), None)
            if rows is None:
                continue
            ids = [r.get("request_id") or r.get("signal_id") or r.get("id") for r in rows
                   if isinstance(r, dict) and r.get("status") not in ("done", "failed")]
            if ids:
                pending.append({"file": f.name, "count": len(ids), "request_ids": ids[:10]})
    except Exception:
        pass
    acks = [{"ts": a.get("ts"), "request_id": (a.get("ack_of") or {}).get("request_id") or (a.get("ack_of") or {}).get("signal_id"),
              "kind": (a.get("ack_of") or {}).get("signal_type"), "stage": a.get("stage"), "result": a.get("result"),
              "summary": str(a.get("summary") or "")[:120]}
            for a in _status_tail_jsonl(_BOT_LOGS / "agent_acks.jsonl", 10)][-10:]
    fails = [{"at": r.get("executed_at"), "request_id": r.get("request_id") or r.get("signal_id"),
               "status": r.get("status"), "error": str(r.get("error") or "")[:160]}
             for r in _status_tail_jsonl(SIGNALS_RESPONSE_HISTORY_LOG, 40)
             if str(r.get("status") or "").lower().startswith(_STATUS_FAIL_PREFIX)][-10:]
    try:
        cap = _base_size_cap() if "_base_size_cap" in globals() else float(get_override_sync("SIZE_CAP_BASE_SOL", SIZE_CAP_BASE_SOL))
    except Exception:
        cap = None
    wb = None
    try:
        wc = json.loads((_BOT_LOGS / "warden_config.json").read_text(encoding="utf-8"))
        wb = ((wc.get("bounds") or {}).get("memes") or {}).get("max_buy_sol")
    except Exception:
        pass
    return {
        "schema": "agent_status_v1", "updated_at": _now_iso(), "updated_ts": now,
        "refresh_s": AGENT_STATUS_INTERVAL_S,
        "paper_mode": bool(globals().get("PAPER_MODE", False)), "trading": "paper" if globals().get("PAPER_MODE") else "live",
        "open_positions": pos_out,
        "pending_relay_requests": pending,
        "last_acks": acks,
        "last_failures": fails,
        "sizing": {"engine_base_cap_sol": cap,
                    "warden_meme_bound_sol": cap if _WARDEN_FOLLOWS_ENGINE else wb,
                    "warden_bound_source": ("engine buy size (warden reads the same setting)" if _WARDEN_FOLLOWS_ENGINE
                                            else "bot_logs/warden_config.json bounds.memes.max_buy_sol"),
                    "warden_alerts_above_x": 5},
        "paths": {"signals": "json_relay/agent_signals.json", "acks": "bot_logs/agent_acks.jsonl",
                   "responses": "bot_logs/signals_response_history.jsonl", "inbox": "inbox/", "done": "inbox_results/done/"},
    }


async def agent_status_loop() -> None:
    _log("agent_status: starting (bot_logs/agent_status.json every %ss)" % AGENT_STATUS_INTERVAL_S, prefix="status")
    while True:
        try:
            await write_heartbeat("agent_status", "writing")
            _save_json_atomic(AGENT_STATUS_FILE, build_agent_status())
        except Exception as e:
            _log(f"agent_status err: {e}", prefix="status")
        await asyncio.sleep(AGENT_STATUS_INTERVAL_S)


async def discovery_query_handler_loop() -> None:
    """Stage 3 — the agent actively inquires into a discovery finding's history + backtest.

    Instead of only seeing what surfaces in the tune brief, the agent writes a query to
    sniper_discovery_query.json and gets the full lineage + backtest verdict back. The
    active-inquiry half of the discovery system: when a recurring pattern surfaces, he
    can pull its complete story on demand ("show me every time decay:fading_star fired
    and whether it was right").

    Query shapes:
      {} or {"list": true}                         → all hot findings (what he CAN ask about)
      {"source": "decay", "key": "decay:fading_star"} → one finding's full lineage + backtest
    """
    _log("discovery_query_handler: starting", prefix="dqh")
    while True:
        try:
            if SNIPER_DISCOVERY_QUERY_FILE.exists():
                try:
                    q = json.loads(SNIPER_DISCOVERY_QUERY_FILE.read_text(encoding="utf-8") or "{}")
                except Exception:
                    q = {}
                source = q.get("source")
                key = q.get("key")
                if source and key:
                    lineage = _discovery_lineage(source, key)
                    if lineage:
                        resp = {
                            "mode": "detail", "source": source, "key": key,
                            "occurrences": len(lineage),
                            "first_seen": lineage[0].get("at"),
                            "last_seen": lineage[-1].get("at"),
                            "backtest": backtest_finding(source, key),
                            "full_history": [
                                {"at": r.get("at"), "finding": r.get("finding"),
                                 "status": r.get("status"), "occurrences": r.get("occurrences")}
                                for r in lineage
                            ],
                        }
                    else:
                        resp = {"error": f"no finding for {source}/{key}"}
                else:
                    hot = discovery_hot_findings()
                    resp = {
                        "mode": "list",
                        "hot_findings": [
                            {"source": f.get("source"), "key": f.get("key"),
                             "finding": f.get("finding"), "occurrences": f.get("occurrences"),
                             "first_seen_days_ago": f.get("_first_seen_days_ago")}
                            for f in hot
                        ],
                        "note": "pass {source, key} to pull one finding's full lineage + backtest",
                    }
                resp["_answered_at"] = _now_iso()
                try:
                    if isinstance(resp, dict) and isinstance(q, dict):
                        resp["request_id"] = q.get("request_id") or q.get("query_id") or q.get("id")
                except Exception:
                    pass
                _save_json_atomic(SNIPER_DISCOVERY_QUERY_RESP, resp)
                # consume the query so it doesn't reprocess
                try:
                    SNIPER_DISCOVERY_QUERY_FILE.unlink()
                except Exception:
                    pass
                _log(f"discovery_query: answered ({resp.get('mode', 'error')})", prefix="dqh")
        except Exception as e:
            _log(f"discovery_query_handler err: {e}", prefix="dqh")
        await asyncio.sleep(20)


def _normalize_ticker_query(raw) -> str:
    t = str(raw or "").strip()
    if t.startswith("$"):
        t = t[1:]
    return t.strip()


def _scanner_history_for_mint(mint: str) -> dict:
    """Bounded empire lookup: scanned_mints + positions + last decline + trades.

    Does NOT walk inbox_results. That folder is not the venue of record.
    """
    card = {
        "touched": False,
        "source": None,
        "first_seen": None,
        "last_seen": None,
        "seen_count": 0,
        "ticker_recorded": None,
        "first_mcap": None,
        "last_mcap": None,
        "in_positions": False,
        "declined": False,
        "decline_count": 0,
        "last_decline_reason": None,
        "last_declined_at": None,
        "traded": False,
    }
    if not mint:
        return card

    try:
        seen = load_scanned_mints() or {}
        entry = seen.get(mint) if isinstance(seen, dict) else None
        if isinstance(entry, dict) and entry:
            card["touched"] = True
            card["source"] = entry.get("source")
            card["first_seen"] = entry.get("first_seen")
            card["last_seen"] = entry.get("last_seen")
            card["seen_count"] = int(entry.get("seen_count") or 0)
            card["ticker_recorded"] = entry.get("ticker")
            card["first_mcap"] = entry.get("first_mcap")
            card["last_mcap"] = entry.get("last_mcap")
    except Exception as e:
        _log("scanner_history scanned_mints err: %s" % e, prefix="ca_res")

    try:
        positions = load_positions() or {}
        if mint in positions:
            card["in_positions"] = True
        else:
            for v in positions.values():
                if isinstance(v, dict) and v.get("mint") == mint:
                    card["in_positions"] = True
                    break
    except Exception as e:
        _log("scanner_history positions err: %s" % e, prefix="ca_res")

    try:
        if DECLINE_LOG_FILE.exists():
            with open(DECLINE_LOG_FILE, "r", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    if mint not in line:
                        continue
                    try:
                        r = json.loads(line)
                    except json.JSONDecodeError:
                        continue
                    if r.get("mint") != mint:
                        continue
                    card["declined"] = True
                    card["decline_count"] += 1
                    card["last_decline_reason"] = r.get("decline_reason")
                    card["last_declined_at"] = r.get("declined_at")
    except Exception as e:
        _log("scanner_history decline err: %s" % e, prefix="ca_res")

    try:
        if TRADES_LOG.exists():
            with open(TRADES_LOG, "r", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    if mint in line:
                        card["traded"] = True
                        break
    except Exception as e:
        _log("scanner_history trades err: %s" % e, prefix="ca_res")

    return card


def _scanned_mints_by_ticker(ticker: str) -> list:
    tl = _normalize_ticker_query(ticker).lower()
    if not tl:
        return []
    out = []
    try:
        seen = load_scanned_mints() or {}
        if not isinstance(seen, dict):
            return []
        for mint, e in seen.items():
            if not isinstance(e, dict):
                continue
            rec = _normalize_ticker_query(e.get("ticker")).lower()
            if rec and rec == tl:
                row = dict(e)
                row.setdefault("mint", mint)
                out.append(row)
        out.sort(key=lambda r: r.get("last_seen") or r.get("first_seen") or "", reverse=True)
    except Exception as e:
        _log("scanned_mints ticker lookup err: %s" % e, prefix="ca_res")
    return out


async def _resolve_ca_or_ticker(req: dict):
    """Return (mint_or_none, resolve_meta). Accepts ca/mint and/or ticker."""
    ca = str(req.get("ca") or req.get("mint") or "").strip()
    ticker = _normalize_ticker_query(req.get("ticker") or req.get("symbol") or "")
    meta = {
        "query_ca": ca or None,
        "query_ticker": ticker or None,
        "resolved_via": None,
        "candidates": [],
    }
    if ca:
        meta["resolved_via"] = "ca"
        return ca, meta
    if not ticker:
        return None, meta

    scanned = _scanned_mints_by_ticker(ticker)
    if scanned:
        meta["resolved_via"] = "scanned_mints"
        meta["candidates"] = [
            {
                "mint": r.get("mint"),
                "ticker": r.get("ticker"),
                "last_seen": r.get("last_seen"),
                "seen_count": r.get("seen_count"),
                "source": r.get("source"),
            }
            for r in scanned[:5]
        ]
        return scanned[0].get("mint"), meta

    pairs = await fetch_dex_search(ticker)
    ranked = []
    tl = ticker.lower()
    for p in pairs or []:
        if str(p.get("chainId") or "").lower() != "solana":
            continue
        base = p.get("baseToken") or {}
        sym = _normalize_ticker_query(base.get("symbol")).lower()
        mint = base.get("address")
        if not mint or sym != tl:
            continue
        liq = ((p.get("liquidity") or {}).get("usd") or 0) or 0
        ranked.append((float(liq), mint))
    ranked.sort(reverse=True)
    if ranked:
        meta["resolved_via"] = "dex_search"
        meta["candidates"] = [{"mint": m, "liq": liq} for liq, m in ranked[:5]]
        return ranked[0][1], meta

    loose = []
    for p in pairs or []:
        if str(p.get("chainId") or "").lower() != "solana":
            continue
        base = p.get("baseToken") or {}
        mint = base.get("address")
        if not mint:
            continue
        liq = ((p.get("liquidity") or {}).get("usd") or 0) or 0
        loose.append((float(liq), mint, base.get("symbol")))
    loose.sort(reverse=True)
    if loose:
        meta["resolved_via"] = "dex_search_loose"
        meta["candidates"] = [{"mint": m, "liq": liq, "ticker": t} for liq, m, t in loose[:5]]
        return loose[0][1], meta

    return None, meta


def _ack_ca_research(req: dict, packet: dict, ca: str = None, extra: dict = None) -> None:
    response_data = load_json_with_staleness(
        CA_RESEARCH_RES_FILE, max_age_seconds=86400,
        default={"responses": []}, alert_on_stale=False,
    )
    if not isinstance(response_data, dict):
        response_data = {"responses": []}
    response_data.pop("_meta", None)
    ctx = packet.get("context") or {}
    row = {
        "request_id": req.get("request_id"),
        "ca": ca,
        "ticker": req.get("ticker") or ctx.get("ticker"),
        "intent": req.get("intent") or "research",
        "responded_at": _now_iso(),
        "verdict": ctx.get("verdict"),
        "inbox_packet_id": packet.get("id"),
        "scanner_touched": (ctx.get("scanner_history") or {}).get("touched"),
    }
    if not (req.get("ca") or req.get("mint") or req.get("ticker") or req.get("symbol")):
        row["status"] = "failed"
        row["error"] = "invalid_request: need ca/mint or ticker/symbol (both empty)"
    if extra:
        row.update(extra)
    response_data.setdefault("responses", []).append(row)
    response_data["responses"] = response_data["responses"][-100:]
    _save_json_atomic(CA_RESEARCH_RES_FILE, response_data)
    _ca_history_append(req, row, ca)


CA_INTEL_HISTORY_FILE = _BOT_LOGS / "ca_intel_history.json"
CA_INTEL_HISTORY_MAX = 2000


def _ca_history_append(req: dict, row: dict, ca) -> None:
    """ca-intel skill Step 5 (2026-10-14): the engine appends one card per ca_research request to
    ca_intel_history.json (same schema the agent uses; list, newest last, capped, atomic write).
    operator_verdict stays null for the agent to fill; outcome_tracking starts pending."""
    try:
        try:
            hist = json.loads(CA_INTEL_HISTORY_FILE.read_text(encoding="utf-8") or "[]")
        except FileNotFoundError:
            hist = []
        if isinstance(hist, dict):          # tolerate a wrapped shape, keep it
            lst = hist.setdefault("cards", [])
        elif isinstance(hist, list):
            lst = hist
        else:
            _log("ca_intel_history: unexpected shape, not appending", prefix="ca_intel")
            return
        lst.append({
            "ts": row.get("responded_at") or _now_iso(),
            "request_id": row.get("request_id"),
            "ca": ca, "ticker": row.get("ticker"),
            "invoked_by": "inbox_request",
            "intent": row.get("intent"),
            "bot_verdict": row.get("verdict"),
            "operator_verdict": None,
            "inbox_packet_id": row.get("inbox_packet_id"),
            "error": row.get("error"),
            "layer_snapshots": {},
            "outcome_tracking": {"action_taken": "packet_delivered", "final_result": "pending",
                                 "closed_at": None, "evidence": None, "teaches_next": None},
        })
        del lst[:-CA_INTEL_HISTORY_MAX]
        _save_json_atomic(CA_INTEL_HISTORY_FILE, hist)
    except Exception as e:
        _log(f"ca_intel_history append err: {e}", prefix="ca_intel")


async def ca_research_responder_loop() -> None:
    """Polls ca_research_request.json every 5s. Vets CA or ticker, writes ca_intel packets."""
    _log("ca_research: starting", prefix="ca_res")

    processed_request_ids: set = set()

    while True:
        await write_heartbeat("ca_research", "polling")

        try:
            req_data = load_json_with_staleness(CA_RESEARCH_REQ_FILE, max_age_seconds=86400, default={"requests": []}, alert_on_stale=False)
            if isinstance(req_data, dict):
                requests = req_data.get("requests", [])
                dirty = False
                for req in requests:
                    if not isinstance(req, dict):
                        continue
                    if req.get("status") in ("done", "processed", "error"):
                        continue
                    req_id = req.get("request_id") or req.get("ca") or req.get("mint") or req.get("ticker")
                    if not req_id or req_id in processed_request_ids:
                        continue
                    try:
                        await process_ca_research_request(req)
                        processed_request_ids.add(req_id)
                        req["status"] = "done"
                        req["processed_at"] = _now_iso()
                        dirty = True
                    except Exception as err:
                        _log(f"ca_research: error processing {req_id}: {err}", prefix="ca_res")
                        req["status"] = "error"
                        req["error"] = str(err)[:240]
                        dirty = True
                if dirty:
                    req_data.pop("_meta", None)
                    req_data["requests"] = requests[-50:]
                    _save_json_atomic(CA_RESEARCH_REQ_FILE, req_data)
        except Exception as loop_err:
            _log(f"ca_research: loop error: {loop_err}", prefix="ca_res")

        await asyncio.sleep(CA_RES_TICK_S)


async def process_ca_research_request(req: dict) -> None:
    """Vet a CA or ticker, attach scanner_history, write ca_intel packet. No auto-buy."""
    ca, resolve_meta = await _resolve_ca_or_ticker(req)
    intent = req.get("intent") or "research"
    source_event_id = req.get("source_event_id")
    source_summary = req.get("source_summary", "(no summary)")
    query_ticker = resolve_meta.get("query_ticker")

    if not req.get("request_id"):
        stem = (ca or query_ticker or "lookup")[:8]
        req["request_id"] = f"ca_req_{stem}_{int(_now_ts())}"

    if not ca:
        packet = {
            "id": f"x_evt_ca_intel_{(query_ticker or 'unknown')[:8]}",
            "type": "ca_intel",
            "received_at": _now_iso(),
            **_lane_fields("ca_intel"),
            "from_user": {"username": "@meme_sniper", "friendship_tier": "system", "user_id": "meme_sniper_bot"},
            "context": {
                "ca": None,
                "ticker": query_ticker,
                "source_event_id": source_event_id,
                "source_summary": source_summary,
                "vetted_at": _now_iso(),
                "intent": intent,
                "is_known_token": False,
                "first_seen_in_system": None,
                "scanner_history": _scanner_history_for_mint(""),
                "resolve": resolve_meta,
                "verdict": "unresolved",
                "details": "Need a CA or a ticker I can resolve. Nothing matched scanned_mints or dex search.",
            },
            "decision_inputs": _decision_inputs([
                {"action_type": "ignore", "when_this_fits": "no resolvable token"},
            ]),
            "actions_taken": [],
        }
        write_inbox_packet_generic(packet, prefix=f"ca_intel_{(query_ticker or 'unknown')[:8]}", identifier=(query_ticker or "unknown")[:8])
        _ack_ca_research(req, packet, ca=None)
        return

    _log(f"ca_research: vetting {_short_mint(ca)} via {resolve_meta.get('resolved_via')} from {source_event_id}", prefix="ca_res")

    scanner_history = _scanner_history_for_mint(ca)

    autopsies = load_json_with_staleness(AUTOPSY_REPORTS_FILE, max_age_seconds=86400 * 365, default=[], alert_on_stale=False)
    is_known = bool(scanner_history.get("touched"))
    first_seen = scanner_history.get("first_seen")
    if isinstance(autopsies, list):
        for r in autopsies:
            if r.get("mint") == ca:
                is_known = True
                first_seen = first_seen or r.get("timestamp")
                break

    pair = await fetch_token_data(ca)
    if not pair:
        packet = {
            "id": f"x_evt_ca_intel_{ca[:8]}",
            "type": "ca_intel",
            "received_at": _now_iso(),
            **_lane_fields("ca_intel"),
            "from_user": {"username": "@meme_sniper", "friendship_tier": "system", "user_id": "meme_sniper_bot"},
            "context": {
                "ca": ca,
                "ticker": query_ticker or scanner_history.get("ticker_recorded"),
                "source_event_id": source_event_id,
                "source_summary": source_summary,
                "vetted_at": _now_iso(),
                "intent": intent,
                "is_known_token": is_known,
                "first_seen_in_system": first_seen,
                "scanner_history": scanner_history,
                "resolve": resolve_meta,
                "verdict": "no_dex_data",
                "details": "Token has no active DEX listing or pair data. Could be too new, dead, or unsupported chain.",
            },
            "decision_inputs": _decision_inputs([
                {"action_type": "ignore", "when_this_fits": "no actionable data"},
                {"action_type": "watch", "when_this_fits": "queue for retry in 1h"},
            ]),
            "actions_taken": [],
        }
        write_inbox_packet_generic(packet, prefix=f"ca_intel_{ca[:8]}", identifier=ca[:8])
        _ack_ca_research(req, packet, ca=ca)
        return

    base = pair.get("baseToken") or {}
    mcap = float(pair.get("marketCap") or pair.get("fdv") or 0)
    liq = (pair.get("liquidity") or {}).get("usd", 0) or 0
    vol = pair.get("volume") or {}
    price_change = pair.get("priceChange") or {}

    pair_created_at = pair.get("pairCreatedAt", 0) or 0
    age_minutes = (
        ((_now_ts() * 1000) - pair_created_at) / 60_000
        if pair_created_at > 0 else 9999
    )

    holders = await get_holders_top10(ca)
    age_min_int = int(age_minutes) if age_minutes < 99999 else None
    rug_check = await smart_rug_check(ca, holders_data=holders, age_minutes=age_min_int)

    enrichment = {
        "mint": ca,
        "ticker": base.get("symbol"),
        "name": base.get("name"),
        "mcap": mcap,
        "liquidity_usd": liq,
        "volume_24h": vol.get("h24", 0) or 0,
        "price_change_1h": price_change.get("h1", 0) or 0,
        "narrative": "unknown",
    }

    edge_filter = compute_edge_filter(enrichment)

    if rug_check["smart_check_verdict"] == "block":
        verdict = "avoid"
    elif edge_filter["passes_full_filter"] and rug_check["smart_check_verdict"] == "clean":
        verdict = "tradeable"
    elif rug_check["smart_check_verdict"] == "caution":
        verdict = "caution"
    else:
        verdict = "neutral"

    packet = {
        "id": f"x_evt_ca_intel_{ca[:8]}",
        "type": "ca_intel",
        "received_at": _now_iso(),
        **_lane_fields("ca_intel"),
        "from_user": {"username": "@meme_sniper", "friendship_tier": "system", "user_id": "meme_sniper_bot"},
        "context": {
            "ca": ca,
            "ticker": base.get("symbol"),
            "name": base.get("name"),
            "source_event_id": source_event_id,
            "source_summary": source_summary,
            "vetted_at": _now_iso(),
            "intent": intent,
            "is_known_token": is_known,
            "first_seen_in_system": first_seen,
            "scanner_history": scanner_history,
            "resolve": resolve_meta,
            "age_minutes": int(age_minutes) if age_minutes < 99999 else None,
            "dex_data": {
                "mcap": mcap,
                "liquidity_usd": liq,
                "volume_24h": vol.get("h24", 0) or 0,
                "price_change_1h": price_change.get("h1", 0) or 0,
                "price_usd": str(pair.get("priceUsd") or "0"),
                "pair_url": pair.get("url"),
            },
            "rug_check": rug_check,
            "edge_filter": edge_filter,
            "social": {
                "twitter": _extract_social(pair, "twitter"),
                "telegram": _extract_social(pair, "telegram"),
                "website": _extract_website(pair),
            },
            "holders": {
                "top10_pct": (holders or {}).get("top10_pct"),
                "dev_holding_pct": (holders or {}).get("dev_holding_pct"),
                "holder_count": (holders or {}).get("holder_count"),
            },
            "verdict": verdict,
        },
        "decision_inputs": _decision_inputs([
            {"action_type": "fire_buy_signal", "when_this_fits": f"vetted {verdict}, conviction your call"} if verdict == "tradeable" else
            {"action_type": "view_chart", "when_this_fits": "see the shape before deciding"},
            {"action_type": "view_chart", "when_this_fits": "see the shape"},
            {"action_type": "ignore", "when_this_fits": "noted the CA, no action"},
        ]),
        "actions_taken": [],
    }
    write_inbox_packet_generic(packet, prefix=f"ca_intel_{ca[:8]}", identifier=ca[:8])
    _ack_ca_research(req, packet, ca=ca)


def _extract_social(pair: dict, kind: str) -> Optional[str]:
    info = pair.get("info") or {}
    socials = info.get("socials") or []
    for s in socials:
        if kind.lower() in str(s.get("type", "")).lower() or kind.lower() in str(s.get("url", "")).lower():
            return s.get("url")
    return None


def _extract_website(pair: dict) -> Optional[str]:
    info = pair.get("info") or {}
    websites = info.get("websites") or []
    if websites:
        return websites[0].get("url")
    return None




def _assess_x_quality_from_data(twitter_data: dict) -> str:
    """
    Convert twitter_account_data dict to one of the x_quality tier strings:
      'no_x' | 'fresh' | 'building' | 'real' | 'established'
    
    Per the owner edge: established (>5y old + >5K followers) is OFTEN repurposed
    scams, so it's a yellow flag, not a green one.
    
    Order matters: check 'established' BEFORE 'real' since 'real' is the
    catch-all for the broad middle.
    """
    if not twitter_data:
        return "no_x"
    
    followers = twitter_data.get("followers", 0) or 0
    age_days = twitter_data.get("account_age_days", 0) or 0
    
    if age_days < 7:
        return "fresh"     # brand new account, unverified
    elif age_days < 90 and followers < 1000:
        return "building"  # young account building audience , neutral
    elif age_days >= 1825 and followers >= 5000:  # 5+ years
        return "established"  # YELLOW FLAG , often repurposed scam
    elif age_days >= 90 and followers >= 1000:
        return "real"      # established but normal size
    else:
        return "building"


# ═══════════════════════════════════════════════════════════════════════════
#               SPRINT 28.4 , META + DEEP RESEARCH LOOPS
# ═══════════════════════════════════════════════════════════════════════════
#
# Two new supervised loops:
#   - meta_refresh_loop: every 30min, recompute current_meta from trending_track.
#     Cheap (local read + light file write). Enables real meta_alignment for
#     unicorn combo, and gives the agent a "what's hot right now" signal.
#
#   - deep_research_response_handler_loop: polls deep_research_response.json,
#     amends original packets in-place with deep_research block when research responder
#     responds.
# ═══════════════════════════════════════════════════════════════════════════


async def meta_refresh_loop() -> None:
    """
    Every META_REFRESH_INTERVAL_S (30min), recompute current_meta from
    trending_track + their inbox packet narratives.
    
    Cheap operation , purely local file reads. No network calls.
    Output: bot_logs/current_meta.json
    """
    _log("meta_refresh: starting", prefix="meta")
    
    while True:
        # Sprint 32: respect META_REFRESH_PAUSED meeting override
        if await get_override("META_REFRESH_PAUSED", False):
            await write_heartbeat("meta_refresh", "paused", {"paused_via": "meeting_override"})
            await asyncio.sleep(60)
            continue
        
        try:
            await write_heartbeat("meta_refresh", "computing")
            meta = compute_current_meta()
            
            cats = meta.get("categories", [])
            sample = meta.get("sample_size", 0)
            
            if cats:
                _log(
                    f"meta_refresh: current meta = {cats} (sample={sample}, "
                    f"dominance={meta.get('dominance', {})})",
                    prefix="meta",
                )
            else:
                _log(f"meta_refresh: no dominant meta yet (sample={sample})", prefix="meta")
            
            await write_heartbeat("meta_refresh", "idle", {
                "last_computed_at": _now_iso(),
                "meta_categories": cats,
                "sample_size": sample,
            })
        except Exception as e:
            _log(f"meta_refresh: error: {e}", prefix="meta")
            await write_heartbeat("meta_refresh", "error", {"last_error": str(e)[:200]})
        
        sleep_s = await get_override("META_REFRESH_INTERVAL_S", META_REFRESH_INTERVAL_S)
        await asyncio.sleep(sleep_s)


async def deep_research_response_handler_loop() -> None:
    """
    Polls deep_research_response.json every 5s for research responder responses.
    
    For each completed response:
      1. Cache the result by (mint, scope) for re-use within TTL
      2. Amend the original packet IN-PLACE with a deep_research: {...} block
      3. Bump priority if findings are notable
      4. Send a Telegram notification to the agent
    
    Sprint 28.4.4: After processing, write back ONLY unprocessed responses.
    Each processed response appended to bot_logs/deep_research_response_history.jsonl
    as audit trail. File should normally be empty.
    """
    if not PIPE_RESEARCH_ENABLED:
        _log("deep_research_handler: research pipe off (PIPE_RESEARCH_ENABLED=0) - idle", prefix="dr")
        while True:
            await write_heartbeat("deep_research_handler", "disabled", {"pipe": "research", "enabled": False})
            await asyncio.sleep(300)
    _log("deep_research_handler: starting", prefix="dr")
    
    processed_request_ids: set = set()
    # FIX 1 (2026-08-16): per-request apply attempts, so a failing amend gets a
    # bounded retry instead of either one shot or an infinite spin.
    _apply_attempts: dict = {}
    
    while True:
        try:
            await write_heartbeat("deep_research_handler", "polling")
            
            if not DEEP_RESEARCH_RES_FILE.exists():
                await asyncio.sleep(DEEP_RESEARCH_RESPONSE_POLL_S)
                continue
            
            res_data = load_json_with_staleness(
                DEEP_RESEARCH_RES_FILE,
                max_age_seconds=86400 * 7,
                default={"responses": []},
                alert_on_stale=False,
            )
            if not isinstance(res_data, dict):
                await asyncio.sleep(DEEP_RESEARCH_RESPONSE_POLL_S)
                continue
            
            responses = res_data.get("responses", []) or []
            if not responses:
                await asyncio.sleep(DEEP_RESEARCH_RESPONSE_POLL_S)
                continue
            
            unprocessed_remaining = []
            cycle_processed = 0
            
            for resp in responses:
                if not isinstance(resp, dict):
                    continue
                req_id = resp.get("request_id")
                if not req_id:
                    # Malformed , drop silently
                    continue
                if req_id in processed_request_ids:
                    # Already processed in earlier batch , drop from file silently
                    continue
                
                # ── FIX 1 (2026-08-16): CONSUMED ON SIGHT ────────────────────
                # This used to mark the id processed BEFORE the apply ran, and the
                # error branch below said "failed processing won't succeed on retry"
                # and dropped the row. Both halves were wrong for the bug that was
                # actually happening: a non-x response NameError'd on a plain indent
                # slip, which absolutely would have succeeded on retry once fixed.
                # Apply first, consume after. A transient amend failure now gets a
                # bounded second look instead of a one-way trip to the bin.
                _attempts = _apply_attempts.get(req_id, 0)
                cycle_processed += 1

                try:
                    await _apply_deep_research_response(resp)
                    processed_request_ids.add(req_id)
                    _apply_attempts.pop(req_id, None)
                    # Audit trail
                    try:
                        _append_jsonl(DEEP_RESEARCH_HISTORY_LOG, {
                            "request_id": req_id,
                            "mint": resp.get("mint"),
                            "ticker": resp.get("ticker"),
                            "scopes_completed": resp.get("scopes_completed"),
                            "scopes_failed": resp.get("scopes_failed"),
                            "completed_at": resp.get("completed_at"),
                            "processed_at": _now_iso(),
                        })
                    except Exception:
                        pass
                except Exception as e:
                    _attempts += 1
                    _apply_attempts[req_id] = _attempts
                    if _attempts < _APPLY_MAX_ATTEMPTS:
                        # Keep it on the file for the next poll. Research that cost
                        # money gets more than one chance to land.
                        unprocessed_remaining.append(resp)
                        _log(f"deep_research_handler: apply error on {req_id} "
                             f"(attempt {_attempts}/{_APPLY_MAX_ATTEMPTS}), retrying next "
                             f"poll: {e}", prefix="dr")
                    else:
                        # Out of retries. The findings still must not evaporate -
                        # write them to the agent as a recovery packet carrying the
                        # apply error, then consume the id.
                        processed_request_ids.add(req_id)
                        _apply_attempts.pop(req_id, None)
                        _log(f"deep_research_handler: apply FAILED {_APPLY_MAX_ATTEMPTS}x on "
                             f"{req_id}; writing recovery packet: {e}", prefix="dr")
                        try:
                            _write_deep_research_apply_error_packet(resp, str(e))
                        except Exception as _pe:
                            _log(f"deep_research_handler: recovery packet failed too: {_pe}",
                                 prefix="dr")
                    try:
                        _append_jsonl(DEEP_RESEARCH_HISTORY_LOG, {
                            "request_id": req_id,
                            "mint": resp.get("mint"),
                            "status": "errored" if _attempts >= _APPLY_MAX_ATTEMPTS else "retrying",
                            "attempt": _attempts,
                            "error": str(e)[:300],
                            "processed_at": _now_iso(),
                        })
                    except Exception:
                        pass
            
            # Write back only unprocessed responses (file normally goes empty)
            try:
                res_data["responses"] = unprocessed_remaining
                res_data.pop("_meta", None)
                _save_json_atomic(DEEP_RESEARCH_RES_FILE, res_data)
            except Exception as e:
                _log(f"deep_research_handler: failed to write back cleaned responses: {e}", prefix="dr")
            
            if cycle_processed:
                _log(
                    f"deep_research_handler: batch done , processed {cycle_processed}, "
                    f"file now has {len(unprocessed_remaining)} pending",
                    prefix="dr",
                )
            
            # Bound dedup set
            if len(processed_request_ids) > 500:
                processed_request_ids = set(list(processed_request_ids)[-300:])
            if len(_apply_attempts) > 200:
                _apply_attempts = dict(list(_apply_attempts.items())[-100:])
            
            await write_heartbeat("deep_research_handler", "idle", {
                "last_poll_at": _now_iso(),
                "last_processed_count": cycle_processed,
                "total_processed_in_session": len(processed_request_ids),
            })
        except Exception as e:
            _log(f"deep_research_handler: cycle error: {e}", prefix="dr")
            await write_heartbeat("deep_research_handler", "error", {"last_error": str(e)[:200]})
        
        await asyncio.sleep(DEEP_RESEARCH_RESPONSE_POLL_S)


# FIX 1 (2026-08-16): how many times an amend may fail before the research is
# escalated to the agent as a packet instead of retried. Low on purpose - the point
# is to survive a transient write, not to hammer a structural bug forever.
_APPLY_MAX_ATTEMPTS = 3

# ── FIX 6 (2026-08-16): WHY THE chart_vision BUTTON IS STILL HERE ───────────
# The packet said to pull chart_vision off the candidate menu until "the research responder
# comment at ~27454 is deleted because it is fixed", reading that line as a
# standing known-break marker. It is not. That sentence lives INSIDE a boot-time
# Telegram branch that only fires when local Ollama is dead AND Grok has no key:
#
#     if ollama_dead and not vision_status["grok_ok"]:
#         ... "chart_vision deep_research will return scopes_failed until fixed."
#
# On any boot where either vision layer is up, chart_vision works. Deleting the
# button would have removed a working capability on most boots to fix a break
# that only exists on some - and it would have gone on being deleted after the
# vision pipeline came back, because a removed menu entry has no health check.
#
# So the menu follows the actual smoke test instead. The boot probe already
# computes this; it just never told anyone downstream. Costs one dict read.
_VISION_HEALTH: dict = {"ok": True, "why": "not probed yet (assume up until boot says otherwise)"}

# One capability_gap per process, not one per token. A stub is a property of the
# research responder, not of the mint - firing the same gap packet for every candidate
# The agent researches turns a real signal into inbox noise.
_STUB_GAP_REPORTED: dict = {"fired": False}


def _write_deep_research_apply_error_packet(resp: dict, error: str) -> None:
    """FIX 1 (2026-08-16): research that cannot be applied still reaches the agent.

    The old error branch logged and dropped the row on the reasoning that "failed
    processing won't succeed on retry". The failure it was actually swallowing was
    a one-character indent slip that would have succeeded on retry the moment it
    was fixed - and in the meantime every web-only, vibe-only and vision-only
    research was paid for, received, and binned with one log line.

    So when the retries are spent, the FINDINGS go to the inbox anyway. The agent
    reads the raw results and decides; the bot does not get to decide that
    research nobody could file is research nobody needed.

    Never raises - a packet failure must not take down the handler.
    """
    mint = resp.get("mint") or "?"
    packet = {
        "id": f"x_evt_deep_research_apply_error_{str(mint)[:8]}_{int(_now_ts())}",
        "type": "deep_research_recovery",
        "from": "meme_sniper",
        "to": "agent",
        "fired_at": _now_iso(),
        "status": "apply_error",
        "severity": "attention",
        "mint": mint,
        "ticker": resp.get("ticker", "?"),
        "request_id": resp.get("request_id"),
        "scopes_completed": resp.get("scopes_completed") or [],
        "scopes_failed": resp.get("scopes_failed") or [],
        "results": resp.get("results") or {},
        "apply_error": str(error)[:500],
        "attempts": _APPLY_MAX_ATTEMPTS,
        "headline": (f"Research came back for {resp.get('ticker', '?')} but could not be "
                      f"written onto the candidate packet after {_APPLY_MAX_ATTEMPTS} tries."),
        "_doctrine": ("The findings are in `results` - read them here. This is the "
                       "research you paid for; the failure was in filing it, not in "
                       "fetching it. The candidate packet does NOT contain this data, "
                       "so do not assume the token was enriched."),
        "actions_taken": [],
    }
    write_inbox_packet_generic(packet, prefix="deep_research_recovery",
                                identifier=str(mint)[:8])
    _log(f"deep_research_handler: apply_error recovery packet written for {str(mint)[:8]}",
         prefix="dr")


async def _apply_deep_research_response(resp: dict) -> None:
    """
    Take a single deep_research response and apply it:
      - Cache results per scope (only for completed scopes, not stubs)
      - Amend originating packet
      - Notify the agent via Telegram if findings warrant
    
    Sprint 28.4.5: handles _stub responses (research responder handler not yet implemented).
    Stub responses don't get cached (no real data), but the packet still gets
    amended with scopes_failed + a clear stub_notice so the agent knows research
    isn't available , not just that the research responder errored.
    """
    req_id = resp.get("request_id", "?")
    mint = resp.get("mint")
    ticker = resp.get("ticker", "?")
    scopes_completed = resp.get("scopes_completed", []) or []
    scopes_failed = resp.get("scopes_failed", []) or []
    results = resp.get("results", {}) or {}
    is_stub = bool(resp.get("_stub"))
    stub_reason = resp.get("_stub_reason")
    
    if not mint:
        _log(f"deep_research_handler: response {req_id} missing mint, skipping", prefix="dr")
        return
    
    # Cache each scope's result independently , but ONLY for completed scopes
    # (stubs have empty results, no point caching empty data)
    if not is_stub:
        for scope in scopes_completed:
            scope_data = results.get(scope)
            if isinstance(scope_data, dict):
                deep_research_cache_set(mint, scope, scope_data)

    # ── FIX 2 / FIX 6 (2026-08-16): NOTHING LEARNED, NOTHING LOCKED ─────────
    # A stub means the research responder has no handler yet - no fetch happened, and the
    # branch above deliberately does not cache it. A scope in `scopes_failed`
    # produced nothing either. Both used to sit behind the full 30min mint lock,
    # so the answer "we couldn't look" also meant "and you can't ask again".
    # Release exactly the scopes that came back empty; anything that actually
    # returned data stays locked and stays cached.
    _barren = list(scopes_failed)
    if is_stub:
        _barren = list({*_barren, *scopes_completed, *(resp.get("scopes") or [])})
    if _barren:
        deep_research_release_dedup(mint, _barren, why="stub" if is_stub else "scopes_failed")
    
    # Auto-record observed shillers (from x scope) into shiller_pending
    x_data = results.get("x") or {}
    shillers_observed = x_data.get("shillers_observed") or []
    if shillers_observed:
        handles = [s.get("handle") for s in shillers_observed if isinstance(s, dict) and s.get("handle")]
        if handles:
            shiller_pending_record(mint, handles)
    
    # Amend the originating packet
    packet_path = _inbox_path_for_mint(mint)
    bumped_priority = False
    notable_findings: list[str] = []
    
    if packet_path.exists():
        try:
            with open(packet_path, "r", encoding="utf-8") as f:
                packet = json.load(f)
            
            packet.pop("_meta", None)
            ctx = packet.setdefault("context", {})
            
            # Build the deep_research block
            deep_block = ctx.setdefault("deep_research", {})
            deep_block["request_id"] = req_id
            deep_block["completed_at"] = resp.get("completed_at") or _now_iso()
            deep_block["scopes_completed"] = scopes_completed
            deep_block["scopes_failed"] = scopes_failed
            deep_block["results"] = results
            if is_stub:
                deep_block["_stub"] = True
                deep_block["_stub_reason"] = stub_reason or "x_research_handler_not_implemented_yet"
                deep_block["stub_notice"] = (
                    "research responder responded with a stub , the actual research handler "
                    "(Brave/Playwright/vision) hasn't been implemented yet. "
                    "The owner has been pinged. Treat this token decision based on the "
                    "data already in the packet (no enrichment available)."
                )
                notable_findings.append(f"deep_research stub (handler missing)")
                # FIX 6: one gap packet per process. The research responder being unbuilt is
                # one fact, not one fact per token.
                if not _STUB_GAP_REPORTED["fired"]:
                    _STUB_GAP_REPORTED["fired"] = True
                    try:
                        write_inbox_packet_generic({
                            "id": f"x_evt_deep_research_stub_gap_{int(_now_ts())}",
                            "type": "capability_gap",
                            "from": "meme_sniper",
                            "to": "agent",
                            "fired_at": _now_iso(),
                            "severity": "attention",
                            "headline": ("The deep_research research responder answered with a stub , the "
                                          "research backend is not implemented."),
                            "first_seen_on": {"mint": mint, "ticker": ticker,
                                               "request_id": req_id},
                            "stub_reason": stub_reason or "x_research_handler_not_implemented_yet",
                            "_doctrine": ("Fired ONCE per sniper process. Every stub after this "
                                           "one is the same fact. Research requests will keep "
                                           "returning stubs and the dedup lock is released each "
                                           "time, so nothing is silently blocked , but nothing is "
                                           "being researched either. Treat candidates as "
                                           "un-enriched until this is built."),
                            "actions_taken": [],
                        }, prefix="capability_gap", identifier="deep_research_stub")
                    except Exception as _ge:
                        _log(f"deep_research: stub gap packet failed: {_ge}", prefix="dr")
            
            # Detect notable findings → priority bump + notification (skip for stubs)
            if not is_stub:
                # X scope: frequent_rugger shillers
                if "x" in scopes_completed:
                    rugger_count = sum(
                        1 for s in shillers_observed
                        if isinstance(s, dict) and s.get("tier_proposal") == "scammer"
                    )
                    if rugger_count > 0:
                        notable_findings.append(f"{rugger_count} known rugger shiller(s)")
                    
                    # Established X account = yellow flag
                    tw = x_data.get("twitter_account_data") or {}

                # ── FIX 1 (2026-08-16): AN INDENT THAT ATE EVERY NON-X RESEARCH ──
                # `tw` was assigned INSIDE `if "x" in scopes_completed` (indent 20)
                # and read here at indent 16, outside it. `tw` is function-local and
                # fresh on every call, so a response whose scopes_completed had no
                # "x" - a web-only scam-report check, a vibe_check, a chart_vision -
                # raised NameError right here.
                #
                # It never showed up as a crash. The enclosing try/except caught it
                # and logged "failed to amend packet", the outer handler had ALREADY
                # added request_id to processed_request_ids, and the response was
                # dropped from the file on write-back. So the expensive scopes were
                # the ones that silently never landed, and the only trace was one
                # log line that looked like an ordinary packet-write hiccup.
                #
                # `tw` now comes off `results` directly and defaults to {} - a
                # research with no X scope simply has no X account to judge.
                tw = (results.get("x") or {}).get("twitter_account_data") or {}
                followers = tw.get("followers", 0) or 0
                age_days = tw.get("account_age_days", 0) or 0
                if "x" in scopes_completed:
                    if age_days >= 1825 and followers >= 5000:
                        notable_findings.append("X account is established (likely repurposed)")

                    # No followers / fresh account on a token with social claim
                    if 0 < followers < 50 and age_days < 7:
                        notable_findings.append(f"X account fresh + tiny ({followers} followers, {age_days}d old)")
            
            # The following blocks only fire for real (non-stub) responses
            if not is_stub:
                # Web scope: Brave search results , look for scam reports
                web_data = results.get("web") or {}
                scam_hits = web_data.get("scam_report_count", 0) or 0
                if scam_hits >= 1:
                    notable_findings.append(f"{scam_hits} scam report(s) on web")
                    # Hard escalation: if Brave found scam reports, escalate deployer to scammer_web_flagged
                    deployer = (ctx.get("deployer_history") or {}).get("address")
                    if deployer:
                        cache = load_deep_research_cache()
                        # Mark this mint's deployer as web-flagged
                        if mint not in cache:
                            cache[mint] = {}
                        cache[mint]["_deployer_web_flagged"] = True
                        try:
                            _save_json_atomic(DEEP_RESEARCH_CACHE_FILE, cache)
                        except Exception:
                            pass
                        # Also update the packet's deployer_history rep
                        if "deployer_history" in ctx:
                            ctx["deployer_history"]["rep"] = "scammer"
                            ctx["deployer_history"]["rep_via"] = "web_search"
                
                # Vibe check: website was a scam-1pager or stolen-art
                vibe_data = results.get("vibe_check") or {}
                if vibe_data.get("verdict") in ("low_effort", "stolen_art", "1pager_scam"):
                    notable_findings.append(f"vibe_check: {vibe_data['verdict']}")
                
                # Chart vision: distribution top detected
                cv_data = results.get("chart_vision") or {}
                cv_verdict = cv_data.get("verdict")
                if cv_verdict in ("distribution_top", "vertical_rug", "exhausted_pump"):
                    notable_findings.append(f"chart_vision: {cv_verdict}")
            
            # If notable findings exist, bump priority + add a signal_updates entry
            if notable_findings:
                packet["priority"] = "high"
                bumped_priority = True
            
            ctx.setdefault("signal_updates", []).append({
                "amended_at": _now_iso(),
                "change_type": "deep_research_completed",
                "summary": (
                    f"Deep research completed: scopes={scopes_completed}; "
                    f"findings={notable_findings or 'none'}"
                ),
                "scopes_completed": scopes_completed,
                "notable_findings": notable_findings,
                "priority_bumped": bumped_priority,
            })
            ctx["last_amended_at"] = _now_iso()
            
            # Re-evaluate suggested_action_options if rep changed to scammer via web
            if (ctx.get("deployer_history") or {}).get("rep_via") == "web_search":
                packet["decision_inputs"] = _decision_inputs(_build_suggested_actions(
                    ctx.get("edge_filter") or {},
                    ctx.get("pattern") or {},
                    ctx.get("narrative_intelligence") or {},
                    ctx.get("rug_check") or {},
                    ctx.get("deployer_history") or {},
                ))
            
            _save_json_atomic(packet_path, packet)
            os.utime(packet_path, None)  # bump mtime, reset TTL
            
            _log(
                f"deep_research_handler: amended packet for {ticker} ({_short_mint(mint)}) , "
                f"scopes={scopes_completed}, findings={notable_findings or 'none'}",
                prefix="dr",
            )
            
            # ── FIX 6 (2026-08-16): "NO RED FLAGS" IS A CLAIM, NOT A DEFAULT ──
            # The else-branch fired whenever notable_findings was empty, which is
            # also exactly what an all-failed response looks like. "Deep research
            # done , no red flags" on a research that checked nothing is the
            # single most dangerous sentence this bot can send: it reads as a
            # clean bill of health on a token nobody looked at. A clean report is
            # only earned when at least one scope actually completed.
            if is_stub:
                await send_telegram(
                    f"⚠️ Deep research STUB for {ticker} , NOTHING WAS CHECKED\n"
                    f"Scopes asked: {', '.join(scopes_failed or scopes_completed) or '?'}\n"
                    f"research responder handler not implemented. This is a capability gap, not a result.\n"
                    f"Dedup released , you can re-ask once it works."
                )
            elif notable_findings:
                msg = (
                    f"🔍 <b>Deep research findings</b>: {ticker}\n"
                    f"Scopes: {', '.join(scopes_completed)}\n"
                    f"⚠️ {'; '.join(notable_findings)}"
                )
                if scopes_failed:
                    msg += f"\n⚠️ FAILED (not checked): {', '.join(scopes_failed)}"
                await send_telegram(msg)
            elif not scopes_completed:
                await send_telegram(
                    f"⚠️ Deep research for {ticker} returned NOTHING , "
                    f"every scope failed ({', '.join(scopes_failed) or '?'}).\n"
                    f"This is NOT a clean result. Nothing was checked. Dedup released."
                )
            else:
                # Earned: at least one scope really completed and found nothing bad.
                _tail = (f" , FAILED: {', '.join(scopes_failed)}" if scopes_failed else "")
                await send_telegram(
                    f"🔍 Deep research done for {ticker} "
                    f"({', '.join(scopes_completed)}) , no red flags{_tail}"
                )
        except Exception as e:
            # FIX 1: an amend that blew up used to end here - logged, and gone. The
            # caller had already consumed the request_id, so the research was paid
            # for, received, and thrown away. Re-raise so the handler can decide to
            # retry or to write a recovery packet; the research reaches the agent on
            # some path or it is loudly recorded, never quietly binned.
            _log(f"deep_research_handler: failed to amend packet for {mint[:8]}: {e}", prefix="dr")
            raise
    else:
        # Sprint 28.4.1: original packet was archived (TTL'd) before research returned.
        # Don't silently drop the research , create a deep_research_recovery packet
        # so the agent still sees the findings + can decide what to do.
        _log(f"deep_research_handler: original packet archived for {mint[:8]}, creating recovery packet", prefix="dr")
        try:
            # Pull whatever archive info exists
            archive_summary = None
            if PACKET_TTL_ARCHIVE_LOG.exists():
                with open(PACKET_TTL_ARCHIVE_LOG, "r", encoding="utf-8") as f:
                    for line in f:
                        line = line.strip()
                        if not line:
                            continue
                        try:
                            entry = json.loads(line)
                            if entry.get("mint") == mint:
                                archive_summary = entry  # last match wins (most recent archive)
                        except Exception:
                            continue
            
            # Build a synthetic recovery packet
            recovery_packet = {
                "id": f"x_evt_dr_recovery_{mint[:8]}_{int(_now_ts())}",
                "type": "deep_research_recovery",
                "received_at": _now_iso(),
                **_lane_fields("deep_research_recovery"),
                "from_user": {
                    "username": "@meme_sniper",
                    "friendship_tier": "system",
                    "user_id": "meme_sniper_bot",
                },
                "context": {
                    "mint": mint,
                    "ticker": ticker,
                    "originating_request_id": req_id,
                    "explanation": (
                        "Original packet was TTL'd before research responder responded. "
                        "Research arrived , surfaced here as recovery packet so "
                        "The agent still sees findings."
                    ),
                    "archive_summary": archive_summary,
                    "deep_research": {
                        "request_id": req_id,
                        "completed_at": resp.get("completed_at") or _now_iso(),
                        "scopes_completed": scopes_completed,
                        "scopes_failed": scopes_failed,
                        "results": results,
                    },
                    "notable_findings": notable_findings,
                },
                "decision_inputs": _decision_inputs([
                    {"action_type": "fire_buy_signal", "when_this_fits": "research clean , re-evaluate token now"},
                    {"action_type": "ignore", "when_this_fits": "research findings don't justify entry"},
                    {"action_type": "watch", "when_this_fits": "still tracked in watchlist; let it develop"},
                ]),
                "actions_taken": [],
            }
            write_inbox_packet_generic(recovery_packet, prefix="dr_recovery", identifier=req_id[-12:])
            _log(f"deep_research_handler: recovery packet written for {ticker} ({mint[:8]})", prefix="dr")
            
            # Telegram notify
            if notable_findings:
                await send_telegram(
                    f"🔍 <b>Late research finding</b> , {ticker} (was archived)\n"
                    f"Scopes: {', '.join(scopes_completed)}\n"
                    f"⚠️ {'; '.join(notable_findings)}\n"
                    f"Recovery packet in inbox"
                )
            else:
                await send_telegram(
                    f"🔍 Late research done for {ticker} ({', '.join(scopes_completed)}) , clean. Recovery packet in inbox."
                )
        except Exception as e:
            _log(f"deep_research_handler: failed to write recovery packet for {mint[:8]}: {e}", prefix="dr")


# ═══════════════════════════════════════════════════════════════════════════
#                       JUPITER SWAP IMPLEMENTATIONS
# ═══════════════════════════════════════════════════════════════════════════
#
# SL plumbing fix per Apr 2026 forensic:
#   - Priority fee burst on panic exits (top-5% recent fee, escalates per retry)
#   - Fresh quotes per attempt (don't reuse stale quotes)
#   - Retry escalation (1.5x priority fee per retry)
#   - Telemetry to bot_logs/sl_telemetry.log (analyze after 10 panic exits)
# ═══════════════════════════════════════════════════════════════════════════

SOL_MINT = "So11111111111111111111111111111111111111112"


async def get_recent_priority_fee_p95() -> int:
    """Get top-5% recent priority fee from Helius (lamports)."""
    result = await helius_rpc("getRecentPrioritizationFees", [])
    if not result or not isinstance(result, list):
        return 500_000  # 0.0005 SOL fallback
    
    fees = [item.get("prioritizationFee", 0) for item in result if isinstance(item, dict)]
    if not fees:
        return 500_000
    
    fees_sorted = sorted(fees)
    # 95th percentile
    idx = int(len(fees_sorted) * 0.95)
    p95 = fees_sorted[min(idx, len(fees_sorted) - 1)]
    return max(p95, 100_000)  # floor at 0.0001 SOL


async def jupiter_quote_fresh(input_mint: str, output_mint: str, amount: int, slippage_bps: int = 1000) -> Optional[dict]:
    """
    Get a fresh Jupiter quote. amount = raw smallest-unit (lamports for SOL, raw for tokens).
    
    Sprint 28.7.4: Migrated to api.jup.ag/swap/v1/quote (old quote-api.jup.ag/v6
    deprecated Oct 1 2025, DNS no longer resolves). Requires x-api-key header.
    
    Sprint 28.7.3: retry transient DNS/network errors (errno 11001 on Windows =
    getaddrinfo failed, errno -2/-3 on Linux = name resolution). These are flaky
    home-network or DNS hiccups, NOT Jupiter-side issues. Real API errors
    (4xx/5xx) skip retry , those mean the request itself is bad.
    """
    if LEAGUE_MODE:                      # no Jupiter in the league (mainnet quotes, unsupported route)
        return None
    params = {
        "inputMint": input_mint,
        "outputMint": output_mint,
        "amount": str(int(amount)),
        "slippageBps": str(slippage_bps),
        "onlyDirectRoutes": "false",
        "asLegacyTransaction": "false",
    }
    headers = {}
    if JUPITER_API_KEY:
        headers["x-api-key"] = JUPITER_API_KEY
    
    # Up to 3 attempts: original + 2 retries on transient network failures
    last_error = None
    for attempt in range(3):
        try:
            client = await _get_dex_client()
            r = await client.get(f"{JUPITER_BASE}/swap/v1/quote", params=params, headers=headers)
            if r.status_code != 200:
                # Real API error , do NOT retry, it'll just fail the same way
                # 401 = missing/invalid api key, 429 = rate limit, 4xx = bad request
                hint = ""
                if r.status_code == 401:
                    hint = " (check JUPITER_API_KEY env var , get one at portal.jup.ag)"
                elif r.status_code == 429:
                    hint = " (rate limited , paid tier may be needed)"
                _log(f"jupiter quote {r.status_code}: {r.text[:200]}{hint}", prefix="jup")
                return None
            return r.json()
        except Exception as e:
            last_error = e
            err_str = str(e).lower()
            # Detect transient network errors that are worth retrying:
            #   - 11001 = WSANOTFOUND (Windows DNS failure)
            #   - 'getaddrinfo failed' (Windows DNS string)
            #   - 'name or service not known' (Linux DNS string)
            #   - 'temporary failure in name resolution' (Linux DNS)
            #   - generic socket/connect timeouts
            is_transient = any(token in err_str for token in [
                "11001", "getaddrinfo", "name or service not known",
                "temporary failure", "connection reset", "connection aborted",
                "remote disconnected", "timeout"
            ])
            if not is_transient:
                _log(f"jupiter_quote_fresh error: {e}", prefix="jup")
                return None
            if attempt < 2:
                _log(f"jupiter_quote_fresh transient error (attempt {attempt+1}/3): {e} , retrying in 1s", prefix="jup")
                await asyncio.sleep(1)
                continue
            else:
                _log(f"jupiter_quote_fresh transient error (final attempt {attempt+1}/3): {e} , giving up", prefix="jup")
                return None
    
    return None  # unreachable, defensive


async def jupiter_swap_execute(quote: dict, *, priority_fee_lamports: int = 500_000,
                               skip_preflight: bool = False, track_meta: dict | None = None) -> dict:
    """Oct 2026: Swap API V2 when JUPITER_SWAP_V2=true (v1 fallback), fee-sweep recognition."""
    if LEAGUE_MODE:
        return {"success": False, "error": "league_mode: Jupiter execution disabled"}
    return await _upg_swap(_jupiter_swap_execute_v1, quote,
                           dict(priority_fee_lamports=priority_fee_lamports,
                                skip_preflight=skip_preflight, track_meta=track_meta))


@_meme_inflight
async def _jupiter_swap_execute_v1(quote: dict, *, priority_fee_lamports: int = 500_000,
                                skip_preflight: bool = False,
                                track_meta: dict | None = None) -> dict:
    """
    Execute a Jupiter swap with the given quote and priority fee.
    Returns {success, tx_signature, error, ...}.
    
    Sprint 28.7.4: Migrated to api.jup.ag/swap/v1/swap (old quote-api.jup.ag/v6
    deprecated Oct 1 2025). Requires x-api-key header.
    
    Sprint 28.8: REAL on-chain execution. Was a placeholder before this sprint
    (returned PLACEHOLDER_TX_SIG without submitting to chain). Now:
      1. Build swap tx via Jupiter swap API
      2. Decode base64 → VersionedTransaction
      3. Sign with hot wallet keypair
      4. Submit to Solana via Helius RPC
      5. Poll for confirmation (up to 30s)
      6. Return real tx signature
    
    Failure modes (returned as {success: False, error: ...}):
      - solders_not_installed: pip install solders base58
      - keypair_load_failed: HOT_WALLET_PRIVATE/PRIVATE_KEY env wrong format
      - keypair_pubkey_mismatch: key decodes but wrong wallet
      - swap_build_<status>: Jupiter swap API rejected the quote
      - tx_decode_failed: swapTransaction base64 invalid
      - tx_sign_failed: signing exception
      - rpc_no_url: RPC_URL env not set
      - rpc_send_failed: Solana RPC rejected the tx
      - confirmation_timeout: 30s waited, tx not confirmed
      - tx_failed_onchain: confirmed but tx errored (e.g. slippage exceeded)
    """
    if PAPER_MODE:
        return await _paper_swap_execute(quote, priority_fee_lamports=priority_fee_lamports,
                                         track_meta=track_meta)
    if not HOT_WALLET_PRIVATE:
        return {"success": False, "error": "no_hot_wallet_configured"}
    
    if not _SOLDERS_AVAILABLE:
        return {"success": False, "error": "solders_not_installed"}
    
    keypair = _load_keypair()
    if keypair is None:
        return {"success": False, "error": "keypair_load_failed"}
    
    if not RPC_URL:
        return {"success": False, "error": "rpc_no_url"}
    
    try:
        # ─── 1. Build swap transaction via Jupiter ───
        client = await _get_dex_client()
        body = {
            "quoteResponse": quote,
            "userPublicKey": HOT_WALLET_ADDR,
            "wrapAndUnwrapSol": True,
            "prioritizationFeeLamports": priority_fee_lamports,
            "dynamicComputeUnitLimit": True,
        }
        headers = {}
        if JUPITER_API_KEY:
            headers["x-api-key"] = JUPITER_API_KEY
        
        r = await client.post(f"{JUPITER_BASE}/swap/v1/swap", json=body, headers=headers)
        if r.status_code != 200:
            hint = ""
            if r.status_code == 401:
                hint = " (check JUPITER_API_KEY env var)"
            return {"success": False, "error": f"swap_build_{r.status_code}: {r.text[:200]}{hint}"}
        
        swap_data = r.json()
        tx_b64 = swap_data.get("swapTransaction")
        if not tx_b64:
            return {"success": False, "error": "swap_build_no_tx_in_response"}
        
        # ─── 2. Decode base64 → VersionedTransaction ───
        try:
            import base64
            tx_bytes = base64.b64decode(tx_b64)
            unsigned_tx = _SoldersVersionedTx.from_bytes(tx_bytes)
        except Exception as e:
            return {"success": False, "error": f"tx_decode_failed: {e}"}
        
        # ─── 3. Sign the transaction ───
        # solders VersionedTransaction needs to be re-built with the signature.
        # The pattern: get the message, sign it, then construct a new tx with the sig.
        try:
            message = unsigned_tx.message
            # populate() takes (message, signers_list) → returns signed VersionedTransaction
            signed_tx = _SoldersVersionedTx(message, [keypair])
            signed_tx_bytes = bytes(signed_tx)
        except Exception as e:
            return {"success": False, "error": f"tx_sign_failed: {e}"}
        
        # ─── 4. Submit via RPC ───
        # base64-encode for sendTransaction
        import base64 as _b64
        tx_b64_signed = _b64.b64encode(signed_tx_bytes).decode("ascii")
        
        # AGENT'S PATCH #3B: preflight is a SAFETY feature on entries and a
        # LIABILITY on exits — a full-size bag on a fast mover fails simulation
        # (slippage / compute / stale route / account lock) while half the bag
        # clears, which is exactly the Nenem tape (partial filled +47%, full
        # size died 5×). Exits > simulation purity when the bag is live.
        _send_opts = {
            "skipPreflight": bool(skip_preflight),
            "preflightCommitment": "processed",
            "encoding": "base64",
            "maxRetries": 0,  # we handle retry at the strategy layer
        }
        rpc_result = await helius_rpc("sendTransaction", [tx_b64_signed, _send_opts])
        _send_err = last_rpc_error_str()
        _landed_via = "primary"

        # AGENT'S PATCH #3C: send-path fallback — same signed bytes, one push
        # at the second endpoint. Never for reads, only for submits.
        if (not rpc_result or not isinstance(rpc_result, str)) and RPC_URL_FALLBACK:
            _log(f"swap: primary submit failed ({_send_err or 'no signature'}) — retrying on fallback RPC",
                 prefix="swap")
            rpc_result = await helius_rpc("sendTransaction", [tx_b64_signed, _send_opts],
                                           rpc_url=RPC_URL_FALLBACK)
            if rpc_result and isinstance(rpc_result, str):
                _landed_via = "fallback"
            else:
                _send_err = last_rpc_error_str() or _send_err

        if not rpc_result or not isinstance(rpc_result, str):
            # The real reason now travels with the failure instead of dying in
            # the wrapper — this is the whole point of patch #3A.
            return {"success": False,
                    "error": f"rpc_send_failed: {_send_err or 'no signature returned'}"
                              + (" (preflight ON — a forced exit would skip it)" if not skip_preflight else "")}
        if _landed_via == "fallback":
            _log("swap: submit landed on FALLBACK rpc (primary is degraded)", prefix="swap")
        
        tx_signature = rpc_result
        _log(
            f"swap: tx submitted, signature {tx_signature[:8]}...{tx_signature[-4:]} , awaiting confirmation",
            prefix="swap"
        )
        
        # ─── 5. Wait for confirmation (up to 30s) ───
        # 2026-07-26 (exit-path P1): 30s is not the chain's opinion, it's ours.
        # Give a real second look before declaring anything, then hand the
        # signature to the pending tracker instead of dropping it on the floor.
        landed = await wait_for_tx_landing(tx_signature, timeout_seconds=30)
        if not landed:
            landed = await wait_for_tx_landing(tx_signature, timeout_seconds=45)  # blockhash is still valid here
        if not landed:
            # BUG 2 FIX 2026-07-27 (SimonCat): this recorded side="swap" and
            # mint=outputMint. On a SELL the outputMint is SOL (So111...), so the
            # pending row named the wrong token AND the wrong side.
            # has_inflight_sell() looks for side=="sell" + the TOKEN mint, so it
            # could never match — the double-sell guard has never fired once, and
            # a second sell could stack on a first one still landing.
            # Callers now pass track_meta; _non_sol_mint(quote) is the fallback.
            _tm = track_meta or {}
            _q = quote or {}
            _side = _tm.get("side") or _tm.get("direction") or "swap"
            _mint = _tm.get("mint")
            if not _mint:
                _in, _out = _q.get("inputMint"), _q.get("outputMint")
                _SOL = "So11111111111111111111111111111111111111112"
                _mint = (_in if _in and _in != _SOL else None) or (_out if _out != _SOL else None) or _out
            _record_pending_confirmation(tx_signature, {
                "side": _side, "direction": _tm.get("direction") or _side,
                "mint": _mint, "ticker": _tm.get("ticker"),
                "reason": "confirmation_timeout_75s",
                # 2026-07-26 (The agent's item #2): keep the SIGNED BYTES so the
                # tracker can REBROADCAST. A tx that never reached a leader is
                # not a failed tx — it's an unheard one, and the same signature
                # re-pushed is idempotent (the chain dedupes it).
                "signed_tx_b64": tx_b64_signed})
            return {
                "success": False,
                "error": "confirmation_timeout",
                "tx_signature": tx_signature,
                "pending_confirmation": True,   # NOT a verdict — the tracker resolves it
            }
        
        # ─── 6. Verify the tx didn't error on-chain ───
        # A confirmed tx can still have errored (slippage exceeded, custom program error).
        # getTransaction returns meta.err = null on success, or an error object on failure.
        try:
            tx_detail = await helius_rpc(
                "getTransaction",
                [
                    tx_signature,
                    {"maxSupportedTransactionVersion": TX_MAX_VERSION, "encoding": "json"},
                ],
            )
            if tx_detail and isinstance(tx_detail, dict):
                meta = tx_detail.get("meta") or {}
                err = meta.get("err")
                if err is not None:
                    return {
                        "success": False,
                        "error": f"tx_failed_onchain: {err}",
                        "tx_signature": tx_signature,
                    }
        except Exception as e:
            # If we can't check status, log but don't fail , tx confirmed at this point
            _log(f"swap: post-confirm getTransaction failed (non-fatal): {e}", prefix="swap")
        
        _log(f"swap: ✅ tx confirmed {tx_signature[:8]}...{tx_signature[-4:]}", prefix="swap")
        
        return {
            "success": True,
            "tx_signature": tx_signature,
            "swap_data": swap_data,
            "priority_fee_lamports": priority_fee_lamports,
        }
    except Exception as e:
        _log(f"jupiter_swap_execute unhandled error: {e}\n{traceback.format_exc()}", prefix="swap")
        return {"success": False, "error": f"unhandled: {e}"}


# ── PAPER MODE wallet + simulated swaps ─────────────────────────────────────
_PAPER_SOL_MINT = "So11111111111111111111111111111111111111112"
_PAPER_BASE_FEE_LAMPORTS = 5000


def _paper_wallet_load() -> dict:
    try:
        w = json.loads(PAPER_WALLET_FILE.read_text(encoding="utf-8"))
        if isinstance(w, dict) and "sol" in w:
            w.setdefault("tokens", {})
            return w
    except Exception:
        pass
    w = {"sol": PAPER_START_SOL, "start_sol": PAPER_START_SOL, "tokens": {}, "created_at": _now_iso()}
    _paper_wallet_save(w)
    return w


def _paper_wallet_save(w: dict) -> None:
    try:
        _PAPER_DIR.mkdir(parents=True, exist_ok=True)
        tmp = PAPER_WALLET_FILE.with_suffix(".tmp")
        tmp.write_text(json.dumps(w, indent=1), encoding="utf-8")
        os.replace(tmp, PAPER_WALLET_FILE)
    except Exception as e:
        _log(f"paper wallet save err: {e}", prefix="paper")


def _paper_token_balances() -> list:
    out = []
    for mint, t in (_paper_wallet_load().get("tokens") or {}).items():
        raw = float(t.get("raw") or 0)
        if raw <= 0:
            continue
        dec = int(t.get("decimals") or 0)
        out.append({"mint": mint, "amount_raw": raw, "decimals": dec,
                    "ui_amount": raw / (10 ** dec) if dec else raw})
    return out


async def _paper_swap_execute(quote: dict, *, priority_fee_lamports: int = 0,
                              track_meta: dict | None = None) -> dict:
    """Simulated fill at the real quote: outAmount less SNIPER_PAPER_SLIPPAGE_PCT,
    base + priority fee charged in SOL. Never builds, signs or sends a transaction."""
    q = quote or {}
    in_mint, out_mint = q.get("inputMint"), q.get("outputMint")
    try:
        in_amt, out_amt = int(q.get("inAmount") or 0), int(q.get("outAmount") or 0)
    except Exception:
        return {"success": False, "error": "paper_bad_quote"}
    if not in_mint or not out_mint or in_amt <= 0 or out_amt <= 0:
        return {"success": False, "error": "paper_bad_quote"}
    fee_sol = (_PAPER_BASE_FEE_LAMPORTS + int(priority_fee_lamports or 0)) / 1e9
    filled = int(out_amt * (1 - PAPER_SLIPPAGE_PCT / 100.0))
    w = _paper_wallet_load()
    toks = w.setdefault("tokens", {})
    if in_mint == _PAPER_SOL_MINT:
        need = in_amt / 1e9 + fee_sol
        if w["sol"] < need:
            return {"success": False, "error": f"paper_insufficient_sol: have {w['sol']:.4f}, need {need:.4f}"}
        try:
            dec = int(await get_mint_decimals(out_mint) or 0)
        except Exception:
            dec = 6
        w["sol"] = round(w["sol"] - need, 9)
        t = toks.setdefault(out_mint, {"raw": 0, "decimals": dec})
        t["raw"] = float(t.get("raw") or 0) + filled
        side = "buy"
    else:
        t = toks.get(in_mint) or {}
        held = float(t.get("raw") or 0)
        if held <= 0:
            return {"success": False, "error": "paper_no_tokens"}
        if in_amt > held:
            frac = held / in_amt
            in_amt, filled = int(held), int(filled * frac)
        t["raw"] = held - in_amt
        if t["raw"] <= 0:
            toks.pop(in_mint, None)
        w["sol"] = round(w["sol"] + filled / 1e9 - fee_sol, 9)
        side = "sell"
    _paper_wallet_save(w)
    sig = "PAPER-" + hashlib.sha256(f"{_now_iso()}{in_mint}{out_mint}{in_amt}".encode()).hexdigest()[:40]
    row = {"ts": _now_iso(), "side": side, "mint": (track_meta or {}).get("mint") or
           (out_mint if side == "buy" else in_mint), "in_mint": in_mint, "out_mint": out_mint,
           "in_amount": in_amt, "quote_out": out_amt, "filled_out": filled,
           "slippage_pct": PAPER_SLIPPAGE_PCT, "price_impact_pct": q.get("priceImpactPct"),
           "fee_sol": fee_sol, "paper_sol_after": w["sol"], "tx_signature": sig}
    try:
        with open(PAPER_TRADES_LOG, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(row) + "\n")
    except Exception:
        pass
    _log(f"PAPER {side}: {row['mint'][:8]} in={in_amt} out={filled} fee={fee_sol:.6f} SOL "
         f"paper_sol={w['sol']:.4f}", prefix="paper")
    return {"success": True, "tx_signature": sig, "paper": True, "swap_data": {},
            "priority_fee_lamports": priority_fee_lamports}


async def wait_for_tx_landing(tx_signature: str, timeout_seconds: int = 30) -> bool:
    """Poll for transaction confirmation. Returns True if confirmed."""
    start = _now_ts()
    while (_now_ts() - start) < timeout_seconds:
        result = await helius_rpc("getSignatureStatuses", [[tx_signature]])
        if result and isinstance(result, dict):
            statuses = result.get("value", [])
            if statuses and statuses[0]:
                conf = statuses[0].get("confirmationStatus")
                if conf in ("confirmed", "finalized"):
                    return True
        await asyncio.sleep(1)
    return False


async def jupiter_swap_buy(mint: str, amount_sol: float, slippage_bps: int = 1500) -> dict:
    """
    Buy `mint` with `amount_sol` SOL. Standard priority fee.
    Returns {success, tx_signature, buy_price_usd, token_amount, slippage_pct, ...}.
    """
    if LEAGUE_MODE:
        return await _league.execute_buy(LEAGUE_CFG, mint, _LEAGUE_PENDING_USDC.pop(mint, 0.0)
                                         or _league.buy_size_usdc(LEAGUE_CFG))
    lamports = int(amount_sol * 1_000_000_000)
    
    # v13.3 — CHAIN-TRUTH FILLS. The position used to record the QUOTE's outAmount
    # as its token_amount. When the fill delivered fewer tokens (15% slippage
    # tolerance on memecoins!), the position believed it held phantom tokens — and
    # a later 100% sell would quote MORE than the wallet holds and FAIL. That is a
    # plausible root feeder of the historical 306-failed-sells epidemic. Truth is
    # the wallet's token balance delta around the swap; the quote is the fallback.
    pre_raw, _pre_dec = await _wallet_token_raw(mint)
    
    quote = await jupiter_quote_fresh(SOL_MINT, mint, lamports, slippage_bps)
    if not quote:
        return {"success": False, "error": "quote_failed"}
    
    out_amount = int(quote.get("outAmount", 0))
    price_impact_pct = float(quote.get("priceImpactPct", 0))
    
    priority_fee = await get_recent_priority_fee_p95()
    
    result = await jupiter_swap_execute(quote, priority_fee_lamports=priority_fee,
                                        track_meta={"side": "buy", "direction": "buy", "mint": mint})
    if not result.get("success"):
        return result
    
    token_amount = out_amount
    token_source = "quote"
    token_decimals = 0
    for _attempt in range(2):                      # RPC state can lag the landing
        await asyncio.sleep(2)
        post_raw, post_dec = await _wallet_token_raw(mint)
        _delta = post_raw - pre_raw
        if _delta > 0:
            token_amount = _delta
            token_source = "chain_delta"
            token_decimals = post_dec
            break
    
    # v13.3 — entry price from COST, not from a dexscreener snapshot taken after
    # the buy. cost-per-token = (SOL spent × SOL/USD) / tokens actually received.
    # The old buy_price_usd (market price post-buy) stays as the fallback.
    pair = await fetch_token_data(mint)
    buy_price_usd = float((pair or {}).get("priceUsd") or 0)
    entry_price_source = "dexscreener_snapshot"
    # decimals 0 is missing, not a real scale. pump tokens are 6. a 0 here used
    # to skip the cost price and store entry 0 whenever dex was also dark.
    if not token_decimals and str(mint).endswith("pump"):
        token_decimals = 6
    if token_amount > 0 and token_decimals:
        _solp = await get_sol_price_usd()
        if _solp:
            _ui = token_amount / (10 ** int(token_decimals))
            if _ui > 0:
                buy_price_usd = (amount_sol * _solp) / _ui
                entry_price_source = "cost_derived"
    
    return {
        "success": True,
        "tx_signature": result.get("tx_signature"),
        "buy_price_usd": buy_price_usd,
        "token_amount": token_amount,
        "token_amount_source": token_source,
        "entry_price_source": entry_price_source,
        "slippage_pct": round(price_impact_pct * 100, 2),
        "priority_fee_lamports": priority_fee,
        "retries": 0,
    }


async def jupiter_swap_sell(mint: str, token_amount: float, slippage_bps: int = 1500,
                             *, force: bool = False) -> dict:
    """Standard sell. Sells `token_amount` raw units of `mint` for SOL.
    v13.3 — sol_received is the WALLET SOL DELTA around the swap when readable
    (the actual money that landed, net of tx + priority fees), not the quote's
    outAmount. On memecoins with 15% slippage tolerance, the quote was fiction
    exactly when it mattered — sells into draining liquidity. The April forensics
    measured SL exits at -30.4% actual vs -20% config; the quote-based ledger
    could not even SEE that gap. Quote remains the fallback, tagged as such."""
    if LEAGUE_MODE:
        return await _league.execute_sell(LEAGUE_CFG, mint, token_amount)
    pre_sol = await _wallet_sol_balance()
    quote = await jupiter_quote_fresh(mint, SOL_MINT, int(token_amount), slippage_bps)
    if not quote:
        return {"success": False, "error": "quote_failed"}
    
    sol_out = int(quote.get("outAmount", 0))
    sol_received = sol_out / 1_000_000_000
    sol_received_source = "quote"
    price_impact_pct = float(quote.get("priceImpactPct", 0))
    
    priority_fee = await get_recent_priority_fee_p95()
    # AGENT'S PATCH #3B: `force` = this is an EXIT that must land (SL, trail,
    # forced full exit). Normal sells keep preflight's cheap safety net.
    result = await jupiter_swap_execute(quote, priority_fee_lamports=priority_fee,
                                        skip_preflight=bool(force),
                                        track_meta={"side": "sell", "direction": "sell", "mint": mint})
    if not result.get("success"):
        return result
    
    if pre_sol is not None:
        for _attempt in range(2):
            await asyncio.sleep(2)
            post_sol = await _wallet_sol_balance()
            if post_sol is not None and post_sol > pre_sol:
                sol_received = post_sol - pre_sol   # true money, all fees netted
                sol_received_source = "chain_delta"
                break
    
    pair = await fetch_token_data(mint)
    sell_price_usd = float((pair or {}).get("priceUsd") or 0)
    
    return {
        "success": True,
        "tx_signature": result.get("tx_signature"),
        "sell_price_usd": sell_price_usd,
        "sol_received": sol_received,
        "sol_received_source": sol_received_source,
        "slippage_pct": round(price_impact_pct * 100, 2),
        "priority_fee_lamports": priority_fee,
        "retries": 0,
    }


# ════════════════════════════════════════════════════════════════════════════
# EXIT ESCALATION STACK — 2026-07-26, the agent's exit-path crisis brief
# ════════════════════════════════════════════════════════════════════════════
# "meme sniper can enter fine. it cannot reliably exit." 5 landed / 17 failed.
# His diagnosis of the panic path was exact: it retries THE SAME BROKEN PATH
# three times — same 20% slip, same FULL size — escalating only the priority
# fee. If full size is what's dying in a thin/hot pool, a bigger tip changes
# nothing. Nenem only got out because the owner's MANUAL PARTIALS eventually worked,
# and Venus filled its remainder in halves. The tape has been telling us the
# answer for two days: SMALLER PIECES LAND.
#
# So a failed exit now ESCALATES instead of repeating:
#   1. normal panic (unchanged — full size, 20% slip, fee burst)
#   2. wider slippage at full size
#   3. CHUNKED 50/25/25 at wide slippage      ← what actually worked by hand
#   4. dust sweep: whatever the wallet really still holds, max slip
# Anything that lands is real money out; partial success is SUCCESS, because a
# half-empty bag beats a full one you can't sell.
SELL_FAILURE_FILE = _BOT_LOGS / "sell_failures.json"
STUCK_SELL_ALERT_AFTER = 3          # failures on one mint before hard escalation
STUCK_SELL_WINDOW_MIN = 30

def _load_sell_failures() -> dict:
    try:
        with open(SELL_FAILURE_FILE, encoding="utf-8-sig") as f:
            return json.load(f) or {}
    except Exception:
        return {}

def _save_sell_failures(d: dict) -> None:
    try:
        SELL_FAILURE_FILE.parent.mkdir(parents=True, exist_ok=True)
        with open(SELL_FAILURE_FILE, "w", encoding="utf-8") as f:
            json.dump(d, f, indent=2)
    except Exception as e:
        _log(f"sell_failures save err: {e}", prefix="exitesc")

def _record_sell_failure(mint: str, ticker: str, reason: str) -> int:
    """Track consecutive exit failures per mint. Returns the count inside the
    window. A bag we cannot sell is the most expensive state in the system —
    it must never be held silently."""
    try:
        d = _load_sell_failures()
        row = d.get(mint) or {"ticker": ticker, "failures": [], "alerted_at": 0}
        cutoff = _now_ts() - STUCK_SELL_WINDOW_MIN * 60
        row["failures"] = [f for f in row.get("failures", []) if f > cutoff]
        row["failures"].append(_now_ts())
        row["ticker"] = ticker or row.get("ticker")
        row["last_reason"] = str(reason)[:200]
        d[mint] = row
        _save_sell_failures(d)
        return len(row["failures"])
    except Exception:
        return 0

def _clear_sell_failures(mint: str) -> None:
    try:
        d = _load_sell_failures()
        if mint in d:
            d.pop(mint, None)
            _save_sell_failures(d)
    except Exception:
        pass


@_meme_inflight
async def _sell_chunked(mint: str, total_amount: float, position: dict,
                         splits=(0.5, 0.25, 0.25), slippage_bps: int = 3500,
                         priority_fee_lamports: int = 1_500_000) -> dict:
    """Sell a bag in pieces. Item #4 of the agent's brief: a full 100% dump dies on
    thin/hot pools while halves clear — proven twice in the field (Nenem manual
    partials, Venus remainder). Every landed chunk is banked; a partial exit is
    a real result, not a failure."""
    ticker = position.get("ticker", "?")
    landed, sold_units, sigs = 0, 0, []
    for i, frac in enumerate(splits, 1):
        piece = int(total_amount * frac)
        if piece <= 0:
            continue
        try:
            quote = await jupiter_quote_fresh(mint, SOL_MINT, piece, slippage_bps=slippage_bps)
            if not quote:
                _log(f"chunked exit {ticker} piece {i}/{len(splits)}: no quote", prefix="exitesc")
                continue
            res = await jupiter_swap_execute(quote, priority_fee_lamports=priority_fee_lamports,
                                             track_meta={"side": "sell", "direction": "sell", "mint": mint,
                                                         "ticker": ticker, "leg": "chunked"},
                                              skip_preflight=True)   # forced exit
            sig = res.get("tx_signature") if isinstance(res, dict) else None
            if res.get("success") and sig:
                ok = await wait_for_tx_landing(sig, timeout_seconds=30)
                if ok:
                    landed += 1; sold_units += piece; sigs.append(sig)
                    _log(f"chunked exit {ticker} piece {i} LANDED ({frac:.0%}) {sig[:8]}..", prefix="exitesc")
                    continue
            _log(f"chunked exit {ticker} piece {i} failed: {res.get('error') if isinstance(res, dict) else res}",
                 prefix="exitesc")
        except Exception as e:
            _log(f"chunked exit {ticker} piece {i} err: {e!r}", prefix="exitesc")
        await asyncio.sleep(1.5)
    return {"success": landed > 0, "chunks_landed": landed, "chunks_total": len(splits),
             "units_sold": sold_units, "tx_signatures": sigs,
             "partial": 0 < landed < len(splits),
             # RULER FIX: if no chunk landed but a submitted piece is still
             # unconfirmed, this is pending, not a settled failure.
             "pending_confirmation": (landed == 0 and _mint_has_live_pending_sell(mint))}


@_meme_inflight
async def _dust_sweep(mint: str, position: dict) -> dict:
    """Last rung: forget the book, sell what the WALLET actually holds. If the
    bag was partly sold by a late-landing tx, the booked amount is wrong and
    every quote built from it will fail. Chain truth, max slippage."""
    ticker = position.get("ticker", "?")
    try:
        bals = await get_wallet_token_balances() or []
        raw = 0
        for b in bals:
            if b.get("mint") == mint:
                raw = int(float(b.get("amount_raw") or 0))
                break
        if raw <= 0:
            _log(f"dust sweep {ticker}: wallet holds NOTHING — the bag is already gone "
                 f"(a prior sell landed late). Nothing to exit.", prefix="exitesc")
            # BUG 4 FIX 2026-07-27 (SimonCat): this returned success with no tx
            # and no sol_received, so execute_sell_signal booked pnl -100% off a
            # $0 exit price and wiped the book. An empty wallet read is NOT a
            # fill — it is either a late-landed prior sell (ghost reconcile) or a
            # bad balance read (Token-2022 / RPC lag). Never a -100% loss.
            return {"success": False, "error": "wallet_empty_on_dust_sweep",
                    "already_empty": True, "needs_ghost_reconcile": True}
        piece = int(raw * 0.98)   # leave rounding room
        quote = await jupiter_quote_fresh(mint, SOL_MINT, piece, slippage_bps=5000)
        if not quote:
            return {"success": False, "error": "dust_sweep_no_quote"}
        res = await jupiter_swap_execute(quote, priority_fee_lamports=2_000_000, skip_preflight=True,
                                         track_meta={"side": "sell", "direction": "sell", "mint": mint,
                                                     "leg": "dust_sweep"})
        sig = res.get("tx_signature") if isinstance(res, dict) else None
        if res.get("success") and sig and await wait_for_tx_landing(sig, timeout_seconds=40):
            _log(f"dust sweep {ticker} LANDED {sig[:8]}..", prefix="exitesc")
            return {"success": True, "tx_signature": sig, "dust_sweep": True}
        return {"success": False, "error": f"dust_sweep_failed: {res.get('error') if isinstance(res, dict) else res}"}
    except Exception as e:
        return {"success": False, "error": f"dust_sweep_err: {e!r}"}


@_meme_inflight
async def jupiter_swap_sell_panic_escalated(mint: str, token_amount: float, position: dict) -> dict:
    """Item #3: after the normal panic path fails, ESCALATE rather than repeat.
    Wider slip → chunked → dust sweep. The original panic function is untouched
    (its telemetry contract is load-bearing); this wraps it."""
    ticker = position.get("ticker", "?")
    res = await jupiter_swap_sell_panic(mint, token_amount, position)
    if isinstance(res, dict) and res.get("success"):
        _clear_sell_failures(mint)
        return res

    _log(f"EXIT ESCALATION for {ticker}: normal panic failed — widening, then chunking", prefix="exitesc")
    fee = max(await get_recent_priority_fee_p95(), 1_500_000)

    # rung 2 — full size, wider slippage
    try:
        quote = await jupiter_quote_fresh(mint, SOL_MINT, int(token_amount), slippage_bps=3500)
        if quote:
            r2 = await jupiter_swap_execute(quote, priority_fee_lamports=_panic_fee_cap(int(fee * 1.5)), skip_preflight=True,
                                            track_meta={"side": "sell", "direction": "sell", "mint": mint,
                                                        "leg": "escalated"})
            sig = r2.get("tx_signature") if isinstance(r2, dict) else None
            if r2.get("success") and sig and await wait_for_tx_landing(sig, timeout_seconds=30):
                _log(f"EXIT ESCALATION {ticker}: landed at wider slip {sig[:8]}..", prefix="exitesc")
                _clear_sell_failures(mint)
                return {"success": True, "tx_signature": sig, "escalation_rung": "wider_slippage"}
    except Exception as e:
        _log(f"escalation rung2 err: {e!r}", prefix="exitesc")

    # rung 3 — chunked (the thing that worked by hand)
    r3 = await _sell_chunked(mint, token_amount, position, priority_fee_lamports=_panic_fee_cap(int(fee * 1.5)))
    if r3.get("success"):
        _clear_sell_failures(mint)
        r3["escalation_rung"] = "chunked"
        try:
            await send_telegram(
                f"🪓 <b>CHUNKED EXIT WORKED — {ticker}</b>\n"
                f"{r3['chunks_landed']}/{r3['chunks_total']} pieces landed after the full-size "
                f"exit failed.\n"
                f"{'PARTIAL — bag not fully cleared, watchdog continues.' if r3.get('partial') else 'Bag cleared.'}")
        except Exception:
            pass
        return r3

    # rung 4 — dust sweep against chain truth
    r4 = await _dust_sweep(mint, position)
    if r4.get("success"):
        _clear_sell_failures(mint)
        r4["escalation_rung"] = "dust_sweep"
        return r4

    if _mint_has_live_pending_sell(mint):
        # RULER FIX: the rungs exhausted, but a submit is still unconfirmed and may
        # land late. Do NOT record a stuck-bag failure or return a settled failure
        # — the pending tracker owns the verdict and writes the terminal event.
        _log(f"EXIT ESCALATION for {ticker}: rungs exhausted but a submit is still "
             f"unconfirmed — deferring to the pending tracker (not calling it failed)",
             prefix="exitesc")
        return {"success": False, "pending_confirmation": True,
                "error": "escalation_pending_confirmation"}
    n = _record_sell_failure(mint, ticker, "all escalation rungs failed")
    _log(f"EXIT ESCALATION EXHAUSTED for {ticker} — failure #{n} in {STUCK_SELL_WINDOW_MIN}min", prefix="exitesc")
    return {"success": False, "error": "exit_escalation_exhausted", "failures_in_window": n}


# UI health metrics (drop): the supervisor's console reads bot_logs/sniper_health.json.
_UI_HEALTH: dict = {}
_UI_HEALTH_AT = [0.0]


def _health_note(key: str, val: dict) -> None:
    _UI_HEALTH[key] = val
    if time.time() - _UI_HEALTH_AT[0] < 5:
        return
    _UI_HEALTH_AT[0] = time.time()
