async def missed_runner_autopsy_loop() -> None:
    """
    Sprint 37 v12.2 NOTE: this is the LEGACY 2x detection loop. Still useful as
    the first signal — finds tokens that 2x'd that we passed on. But the FULL
    autopsy with rich context (community formation, drawdown timing, etc) now
    fires from missed_runner_observer_loop() once the runner peaks and drops
    ≥80%. Think of this loop as "detection" and observer as "full coroner."
    
    Daily cron-ish (every 4h): find tokens that passed the filter 24-48h ago,
    that we never traded, that ran 2x+ from scan_mcap.
    
    For each: subscribe to observer (Sprint 37) AND write missed_runner_alert
    packet for the agent (legacy behavior). Observer then watches until full
    autopsy threshold.
    """
    _log("missed_runner_autopsy: starting", prefix="mra")
    
    while True:
        if await _rpc_pause_if_unhealthy("missed_runner_autopsy"):   # 2026-10-14
            continue
        # Sprint 32: respect MISSED_RUNNER_AUTOPSY_PAUSED meeting override
        if await get_override("MISSED_RUNNER_AUTOPSY_PAUSED", False):
            await write_heartbeat("missed_runner_autopsy", "paused", {"paused_via": "meeting_override"})
            _log("missed_runner_autopsy: PAUSED via meeting override, sleeping 60s before recheck", prefix="mra")
            await asyncio.sleep(60)
            continue
        
        cycle_start = _now_ts()
        await write_heartbeat("missed_runner_autopsy", "scanning", {})
        
        try:
            # Sprint 53 — THE AUTOPSY NOW HAS FREE RANGE FROM THE $10K SCAN FLOOR.
            #
            # It used to draw ONLY from passed_filter — tokens that cleared the scan
            # checks and became packets. Which means it could only ever judge what the
            # FILTER ALREADY APPROVED OF. A token at $15K that we skipped, which then
            # 50x'd, was structurally invisible: it sat in skip_log.json with its
            # scan_mcap right there and nothing ever asked whether it ran.
            #
            # That bias is backwards. "My filter was wrong about a token I liked enough
            # to show the agent" is the CHEAP mistake. "My filter threw away a rocket
            # before anyone saw it" is the EXPENSIVE one — and it was the one we
            # couldn't see. The autopsy should judge everything we LOOKED at, not just
            # everything we LIKED.
            #
            # So: passed_filter (shown to the agent) + skip_log (dropped at scan) — every
            # token above the $10K scan floor, whether it rugged or mooned.
            passed = passed_filter_load_recent(lookback_hours=MISSED_RUNNER_LOOKBACK_HOURS)
            skipped = skip_log_load_recent(lookback_hours=MISSED_RUNNER_LOOKBACK_HOURS)
            for _s in skipped:
                _s["_source"] = "skip_log"          # so the autopsy can say WHY it never showed
                _s["_skip_reason"] = _s.get("skip_reason")
            for _p in passed:
                _p.setdefault("_source", "passed_filter")
            entries = passed + skipped
            
            # Filter: only check entries that are >24h old (give time for runner to develop)
            min_age_ts = _now_ts() - (24 * 3600)
            old_enough = [e for e in entries if e.get("scan_at_ts", _now_ts()) < min_age_ts]
            
            # Drop dupes (same mint can appear multiple times in passed_filter log)
            seen = set()
            unique = []
            for e in old_enough:
                m = e.get("mint")
                if m and m not in seen:
                    unique.append(e)
                    seen.add(m)
            
            _n_skip = sum(1 for e in unique if e.get("_source") == "skip_log")
            _log(f"missed_runner_autopsy: checking {len(unique)} mints from last "
                 f"{MISSED_RUNNER_LOOKBACK_HOURS}h "
                 f"({len(unique) - _n_skip} shown to the agent, {_n_skip} skipped at scan "
                 f"— the autopsy now sees BOTH)", prefix="mra")
            
            # Skip mints we EVER touched — a token we bought is not a "missed"
            # runner, even while we still hold it. Build the exclusion set from
            # THREE sources, not just close-autopsies:
            #   1. autopsy_reports.json   — tokens we traded AND closed (legacy)
            #   2. positions.json         — tokens we bought and STILL HOLD (gap:
            #      an open position has no close-autopsy yet, so the old logic
            #      flagged tokens we were literally holding as "missed")
            #   3. signals_history.jsonl — every buy signal we executed (covers
            #      the window between buy landing and position/autopsy write)
            traded_mints = set()

            autopsies = load_json_with_staleness(AUTOPSY_REPORTS_FILE, max_age_seconds=86400 * 365, default=[], alert_on_stale=False)
            if isinstance(autopsies, list):
                traded_mints |= {r.get("mint") for r in autopsies if isinstance(r, dict) and r.get("mint")}
            try:
                if EXEC_LEDGER_FILE.exists():
                    with open(EXEC_LEDGER_FILE, "r", encoding="utf-8") as _lf:
                        for _ll in _lf:
                            try:
                                _lr = json.loads(_ll)
                            except Exception:
                                continue
                            if not isinstance(_lr, dict):
                                continue
                            _ev = str(_lr.get("event") or "")
                            if _ev in ("buy", "sell", "sell_failed", "sell_pending", "partial_sell"):
                                _lm = _lr.get("mint")
                                if _lm:
                                    traded_mints.add(_lm)
            except Exception as _le:
                _log(f"missed_runner: ledger exclusion read err: {_le}", prefix="mra")

            try:
                open_positions = load_positions()
                if isinstance(open_positions, dict):
                    traded_mints |= {m for m in open_positions.keys() if m}
            except Exception as _pe:
                _log(f"missed_runner: open-position exclusion read err: {_pe}", prefix="mra")

            try:
                if SIGNALS_HISTORY_LOG.exists():
                    with open(SIGNALS_HISTORY_LOG, "r", encoding="utf-8") as _sf:
                        for _line in _sf:
                            _line = _line.strip()
                            if not _line:
                                continue
                            try:
                                _rec = json.loads(_line)
                            except Exception:
                                continue
                            if not isinstance(_rec, dict):
                                continue
                            _act = (_rec.get("action") or "").lower()
                            if _act in ("buy", "snipe", "ape", "enter"):
                                _m = (_rec.get("signal_data") or {}).get("mint") or _rec.get("mint")
                                if _m:
                                    traded_mints.add(_m)
            except Exception as _se:
                _log(f"missed_runner: signal-history exclusion read err: {_se}", prefix="mra")

            untraded = [e for e in unique if e.get("mint") not in traded_mints]
            
            misses_found = 0
            
            sem = asyncio.Semaphore(3)
            
            async def _check_miss(entry: dict) -> bool:
                async with sem:
                    mint = entry.get("mint")
                    scan_mcap = entry.get("scan_mcap") or 0
                    if not mint or scan_mcap <= 0:
                        return False
                    try:
                        pair = _mra_pairs.get(mint)   # 2026-10-15: 30-mint DexScreener batches
                        if not pair:
                            return False
                        current_mcap = float(pair.get("marketCap") or pair.get("fdv") or 0)
                        if current_mcap <= 0:
                            return False
                        ratio = current_mcap / scan_mcap
                        if ratio < MISSED_RUNNER_THRESHOLD_X:
                            return False
                        # 2026-10-15: detection runs every 90 min, but a mint reports at
                        # most once per MISSED_RUNNER_REPORT_COOLDOWN_S (the old 4h rate).
                        if not _mra_should_report(mint):
                            return False
                        # Sprint 53 — IS THE DOOR STILL OPEN? The old code fired a
                        # missed_runner packet (a post-mortem) regardless of whether the
                        # token was still alive. But a 4x that's STILL RUNNING is live
                        # intelligence, not a eulogy — and treating it as a closed door
                        # is how you watch opportunity walk past. So fork on liveness:
                        # still alive -> OPPORTUNITY packet (chase / watch / pass, with
                        # full data + real X chatter). Already dead -> the autopsy.
                        _pc = (pair.get("priceChange") or {})
                        _h6 = _safe_num(_pc.get("h6"))
                        _h24 = _safe_num(_pc.get("h24"))
                        _liq_now = _safe_num((pair.get("liquidity") or {}).get("usd")) or 0
                        # "dead" = liquidity gone, or it has round-tripped hard
                        _is_dead = (_liq_now < 5_000) or (_h24 is not None and _h24 < -60)
                        _wrote_opportunity = False
                        if not _is_dead:
                            # Thread B (the owner): before the generic opportunity packet,
                            # check if we FLIPPED this mint. If we bought+sold it and it's
                            # still alive at/above our exit, that's a CONTINUING miss — fire
                            # the flip re-engagement packet (carries round-trip history so
                            # The agent reads it as 'you left early', not a fresh scan) instead.
                            _flip = _flip_history(mint)
                            _cur_price = _safe_num(pair.get("priceUsd")) or 0
                            _fired_flip = False
                            if _flip.get("flipped") and _flip.get("exit_price") and _cur_price:
                                # still alive AND at/above ~90% of our exit = the run we left
                                if _cur_price >= _flip["exit_price"] * 0.9:
                                    try:
                                        await _write_flip_reengagement_packet(
                                            mint, pair, _flip, _cur_price, current_mcap)
                                        _fired_flip = True
                                    except Exception as _fe:
                                        _log(f"flip_reengage err {_short_mint(mint)}: {_fe}", prefix="mra")
                                    # Sprint 65: a FLIPPED token that's still alive AND just
                                    # got a market event (boost/paid) is the 'left too early'
                                    # flag at its loudest — surface it on the strong combo.
                                    try:
                                        _flip_pos = {"ticker": (pair.get("baseToken") or {}).get("symbol", "?"),
                                                     "_is_flip": True}
                                        _h1 = _safe_num((pair.get("priceChange") or {}).get("h1")) or 0
                                        await evaluate_position_market_event(mint, _flip_pos, pair, _h1)
                                    except Exception as _fme:
                                        _log(f"flip market-event skipped {_short_mint(mint)}: {_fme}", prefix="dxpm")
                            if not _fired_flip:
                                try:
                                    await _write_opportunity_packet(mint, pair, entry, ratio)
                                    _wrote_opportunity = True
                                except Exception as _oe:
                                    _log(f"opportunity err {_short_mint(mint)}: {_oe}",
                                         prefix="opportunity")
                        # Live opportunity already wrote the lesson-in-time packet.
                        # Do not also fire the 4h missed_runner packet for the same mint.
                        if not _wrote_opportunity and ratio >= float(get_override_sync(
                                "MISSED_RUNNER_MIN_PEAK_MULTIPLE", 2.0)):
                            await _write_missed_runner_packet(entry, current_mcap, ratio, pair)
                        # Sprint 37 v12.2 — also subscribe to observer for FULL
                        # autopsy at 80% drawdown from peak. Legacy packet is
                        # the alert; observer fires the rich post-mortem later.
                        try:
                            subscribe_missed_runner(mint, entry, current_mcap)
                        except Exception as sub_e:
                            _log(f"observer subscribe err for {mint[:8]}: {sub_e}", prefix="mra")
                        return True
                    except Exception as e:
                        _log(f"missed_runner check error on {mint[:8]}: {e}", prefix="mra")
                        return False
            
            _tok = _DEX_ONLY_PATH.set("missed_runner")
            try:
                _mra_pairs = await _dex_batch_pairs(
                    [e.get("mint") for e in untraded if e.get("mint") and (e.get("scan_mcap") or 0) > 0],
                    "missed_runner")
            finally:
                _DEX_ONLY_PATH.reset(_tok)
            results = await asyncio.gather(*[_check_miss(e) for e in untraded], return_exceptions=True)
            misses_found = sum(1 for r in results if r is True)
            
            elapsed = _now_ts() - cycle_start
            _log(f"missed_runner_autopsy: cycle done in {elapsed:.1f}s , found {misses_found} missed runners", prefix="mra")
            
            await write_heartbeat("missed_runner_autopsy", "idle", {
                "last_cycle_at": _now_iso(),
                "last_cycle_seconds": round(elapsed, 1),
                "candidates_checked": len(untraded),
                "missed_runners_found": misses_found,
            })
        except Exception as e:
            _log(f"missed_runner_autopsy: cycle error: {e}", prefix="mra")
            await write_heartbeat("missed_runner_autopsy", "error", {"last_error": str(e)[:200]})
        
        sleep_s = await get_override("MISSED_RUNNER_AUTOPSY_TICK_S", MISSED_RUNNER_AUTOPSY_TICK_S)
        await asyncio.sleep(sleep_s)


async def _missed_runner_recheck(mint: str, passed_entry: dict, pair: dict) -> dict:
    """Sprint 54 — THE AUTOPSY IS NOT A EULOGY. GO BACK AND LOOK.

    The owner's point, and it's a good one: DexScreener still shows the token. So a missed
    runner is not a closed book — it's a token we can go RE-EXAMINE with everything we
    have. And the story since we last looked may be more interesting than the miss.

    A token can launch → rug → RECOVER. It can get scanned when it had nothing and now
    have a real community. The dev could have been dumping at scan and be gone now.
    Whatever the reason it ran, THE REASON IS STILL VISIBLE, and it is the actual lesson —
    "it went up 4x" tells you nothing; "it went up 4x because the dev renounced and the
    chat went from 3 messages to 400" tells you what to look for next time.

    And the second question, which the old autopsy never asked at all:
        IS THERE STILL AN ENTRY HERE?
    A higher mcap is NOT automatically disqualifying. If we missed something real, the
    thing that made it real is probably still there — and a 2x from here on a token with
    a genuine community beats a 10x lottery ticket on a fresh rug. The band system
    already gives us a lane for exactly this (continuation, 1M-10M, watch-first).
    """
    out = {"_doctrine": (
        "The autopsy is NOT a eulogy. DexScreener still shows this token, so we can go back "
        "and LOOK — with everything we have, not just what we had at scan. Two questions "
        "matter: (1) WHAT CHANGED that made it run? That's the lesson, and it's still visible. "
        "(2) IS THERE STILL AN ENTRY? A higher mcap does not disqualify it — if we missed "
        "something REAL, the thing that made it real is probably still there."
    )}

    # Full re-scan: everything we know how to check, run against the token AS IT IS NOW.
    try:
        ctx = None
        pkt = await build_meme_candidate_packet(
            {"tokenAddress": mint, "chainId": "solana"}, surfaced_via="missed_runner_recheck")
        if pkt:
            ctx = pkt.get("context")
        if not ctx:
            out["recheck_failed"] = "could not rebuild the packet (token may be below the $10k floor now)"
            return out
    except Exception as e:
        out["recheck_failed"] = str(e)[:150]
        return out

    holders_now = ctx.get("holders") or {}
    edge_now = ctx.get("edge_filter") or {}
    social_now = ctx.get("social_sentiment") or {}
    cc_now = (social_now.get("coincomms_ca") or {}).get("message_count")

    # what did we KNOW at scan? (may be nothing if it was a scan_miss / never_seen)
    scan_top10 = _safe_num(passed_entry.get("top10_pct"))
    scan_dev   = _safe_num(passed_entry.get("dev_holding_pct"))
    scan_cc    = _safe_num(passed_entry.get("coincomms_messages"))
    scan_mcap  = _safe_num(passed_entry.get("scan_mcap"))

    now_top10 = _safe_num(holders_now.get("top10_pct"))
    now_dev   = _safe_num(holders_now.get("dev_holding_pct"))
    now_mcap  = _safe_num(ctx.get("mcap"))

    # ── WHAT CHANGED? this is the lesson ──
    changed = []
    if scan_dev is not None and now_dev is not None and now_dev < scan_dev - 5:
        changed.append(f"DEV SOLD/RENOUNCED — dev holding {scan_dev:.1f}% → {now_dev:.1f}%. "
                       f"The concentration that (correctly) scared us OFF is GONE. That is often "
                       f"the exact unlock: the thing that made it un-buyable stopped being true.")
    if scan_top10 is not None and now_top10 is not None and now_top10 < scan_top10 - 10:
        changed.append(f"WHALES DISTRIBUTED — top10 {scan_top10:.1f}% → {now_top10:.1f}%. "
                       f"The float opened up. It became a real market after we passed on it.")
    if scan_cc is not None and cc_now is not None and cc_now > max(10, scan_cc * 3):
        changed.append(f"THE COMMUNITY ARRIVED — coincomms {scan_cc} → {cc_now} messages. "
                       f"There was nothing there when we looked. There is now. This is the single "
                       f"most important kind of change to notice, because a community forming is "
                       f"the only thing that turns a chart into a token.")
    if not changed:
        changed.append("Nothing structural changed that we can measure — it may simply have run on "
                       "narrative/absurdity, which is a legitimate and unpredictable way for a "
                       "memecoin to work. Not every runner has a reason you could have found.")
    out["what_changed_since_scan"] = changed

    # ── IS THERE STILL AN ENTRY? ──
    band = edge_now.get("band")
    rug = ctx.get("rug_check") or {}
    rug_ok = (rug.get("verdict") or rug.get("risk_level")) in ("clean", "safe", "pass")
    liq_now = _safe_num(ctx.get("liquidity_usd")) or 0
    pc = ctx.get("price_change_1h")
    still_alive = liq_now >= 15_000 and rug_ok

    out["is_there_still_an_entry"] = {
        "band_now": band,
        "mcap_now": now_mcap,
        "mcap_at_scan": scan_mcap,
        "multiple_from_scan": (round(now_mcap / scan_mcap, 2)
                              if (now_mcap and scan_mcap) else None),
        "liquidity_now": liq_now,
        "rug_check_now": rug.get("verdict") or rug.get("risk_level"),
        "coincomms_now": cc_now,
        "brand": ctx.get("brand_resolution"),
        "verdict": (
            "❌ NO — the token is dead or unsafe now (liquidity gone, or rug_check failing). "
            "The window closed. Take the lesson and move on."
            if not still_alive else
            f"✅ POSSIBLY — it is still ALIVE (liq ${liq_now:,.0f}, rug_check "
            f"{rug.get('verdict') or 'n/a'}) and it now sits in the **{band}** band. "
            + ("A higher mcap is NOT automatically disqualifying. If we missed something REAL, "
               "the thing that made it real is probably still there — and a clean 2x from here on "
               "a token with a genuine community beats a 10x lottery ticket on a fresh rug. "
               "The CONTINUATION lane exists for exactly this: watch-first, brand proof required, "
               "smaller size, slower thesis. Judge it as a continuation trade, NOT as a late snipe."
               if band == "continuation" else
               "It is back inside the EARLY band — treat it as a normal candidate and judge it on "
               "the current packet, not on the fact that we missed it. The past is a sunk cost; "
               "the only question is whether the setup is good NOW."
               if band == "early" else
               "It is a POST-RUNNER (above the continuation ceiling). The move already happened. "
               "This is a chase, not an entry. Observe only.")
        ),
        "current_1h": pc,
        "still_running_warning": (
            "⚠ It is STILL VERTICAL (1h > +20%). Chasing a vertical is how you buy someone "
            "else's exit. If you want in, wait for it to stop going up."
            if _safe_num(pc) and _safe_num(pc) > 20 else None
        ),
    }
    out["full_current_context"] = ctx
    return out


async def _write_missed_runner_packet(passed_entry: dict, current_mcap: float, ratio: float, pair: dict) -> None:
    """Write a missed_runner autopsy packet so the agent can learn what was missing.

    Sprint 53: the pool now includes tokens SKIPPED AT SCAN (below the edge bar but
    above the $10K scan floor), not just tokens shown to the agent. Those are a DIFFERENT
    class of miss and demand a different question, so the packet says which one it is.
    """
    mint = passed_entry.get("mint")
    ticker = passed_entry.get("ticker") or "?"
    base = pair.get("baseToken") or {}
    _plaus, _pwhy = _runner_plausible(ratio, passed_entry.get("scan_mcap"), current_mcap)
    if not _plaus:
        _log(f"missed_runner: {ticker} suppressed as impossible peak ({_pwhy})", prefix="miss")
        return

    _src = passed_entry.get("_source") or "passed_filter"
    _was_shown = (_src != "skip_log")
    _skip_reason = passed_entry.get("_skip_reason") or passed_entry.get("skip_reason")

    _miss_class = {
        "class": "filter_miss" if _was_shown else "scan_miss",
        "was_shown_to_agent": _was_shown,
        "skip_reason": _skip_reason,
        # ── OWNER/AGENT RULING 2026-07-27: LESSON MODE, NOT GUILT MODE ──────
        # "autopsies and 2x refires push chase energy. 'you saw it and passed'
        # starts sounding like i was wrong, even when the pass was correct."
        #
        # A CORRECT PASS IS NOT A MISS. Most passes on tokens that later ran
        # were the gate doing its job — the gate is priced for the whole
        # distribution, not for the one that mooned. Asking "was YOUR read
        # wrong?" by default indicts him for outcomes rather than process, and
        # a forecaster who gets indicted for correct process starts chasing.
        #
        # So the packet no longer asks whether HE was wrong. It states which
        # gate fired and leaves the verdict blank for him to fill.
        "question": (
            f"Gate `{_skip_reason or 'filter'}` declined this one. It later ran. "
            f"The only question worth asking: was that GATE correct for the "
            f"whole distribution it governs — not just for this token? A gate "
            f"that correctly rejects nine and misses the tenth is a working "
            f"gate. Only a WRONG gate is a lesson."
            if _was_shown else
            # He NEVER saw it — the scan dropped it before it became a packet.
            f"⚠ YOU NEVER SAW THIS. It was dropped at SCAN (`{_skip_reason}`) and never "
            f"became a packet — it never reached your inbox at all. This is NOT a filter "
            f"lesson, it's a SCAN lesson, and it's the more expensive kind: the filter can "
            f"only reject what the scan surfaces. Ask: was the scan-level rule that killed "
            f"this correct? If a token above the $10K floor can 2x+ after we threw it away "
            f"unseen, the throwing-away is the bug, not the judging."
        ),
    }

    packet_id = f"x_evt_missed_runner_{mint[:8]}"

    # Sprint 54 — GO BACK AND LOOK. The token is still on DexScreener; the story since
    # the miss is often the actual lesson, and the door may still be open.
    _recheck = {}
    try:
        _recheck = await _missed_runner_recheck(mint, passed_entry, pair)
    except Exception as _re:
        _recheck = {"recheck_failed": str(_re)[:150]}

    # The owner ruling 2026-07-27: the buy option is GATED, not offered by default.
    # It appears only when the door is provably still open, the miss is fresh,
    # and it hasn't already run away. Otherwise the action space is lesson-only.
    _entry_now = (_recheck.get("is_there_still_an_entry") or {})
    _still_has_entry = str(_entry_now.get("verdict") or "").startswith("✅")
    _age_h = round((_now_ts() - passed_entry.get("scan_at_ts", _now_ts())) / 3600.0, 1)
    _chase_allowed = bool(_still_has_entry and _age_h < 6 and ratio < 3.0)

    if (not _was_shown) or _src == "skip_log" or (_miss_class.get("class") == "scan_miss"):
        _lesson_prompt = (
            f"Token {ticker} was skipped/filtered at scan (`{_skip_reason or 'skip_log'}`) "
            f"at ${passed_entry.get('scan_mcap', 0):,.0f} mcap and later ran "
            f"{ratio:.1f}x to ${current_mcap:,.0f}. We did NOT pass filter on this. "
            f"This is a scan/skip miss. Ask whether the scan-level rule that dropped it was correct."
        )
    else:
        _lesson_prompt = (
            f"Token {ticker} passed filter at ${passed_entry.get('scan_mcap', 0):,.0f} mcap and ran "
            f"{ratio:.1f}x to ${current_mcap:,.0f} but we didn't trade it. "
            f"Review original packet ({passed_entry.get('packet_id')}) , what signal did we lack? "
            f"narrative? KOL endorsement? volume profile? unicorn combo?"
        )

    packet = {
        "id": packet_id,
        "type": "missed_runner_alert",
        # ── LESSON MODE HEADER ──────────────────────────────────────────────
        "mode": "lesson_only",
        "chase_allowed": _chase_allowed,
        "doctrine": ("A correct pass is not a miss. Only wrong gates are lessons. "
                     "This packet exists to test the GATE, not to relitigate the "
                     "decision. Never interrupts. Never a same-session chase."),
        "chase_gate": {
            "still_has_entry": _still_has_entry,
            "age_hours": _age_h,
            "ratio_from_scan": round(ratio, 2),
            "rule": "buy option shown only if still_has_entry AND age_hours < 6 AND ratio < 3.0",
            "why_blocked": (None if _chase_allowed else
                            ("door closed — token dead or unsafe now" if not _still_has_entry
                             else f"stale — {_age_h}h since scan (limit 6h)" if _age_h >= 6
                             else f"already ran {ratio:.1f}x (limit 3x) — that is chasing")),
        },
        "gate_at_pass": _skip_reason or "filter",
        "gate_still_correct": None,   # AGENT FILLS. The bot does not get a vote.
        "miss_class": _miss_class,
        "recheck": _recheck,
        "received_at": _now_iso(),
        **_lane_fields("missed_runner_alert"),
        "from_user": {"username": "@meme_sniper", "friendship_tier": "system", "user_id": "meme_sniper_bot"},
        "context": {
            "mint": mint,
            "ticker": ticker,
            "name": base.get("name"),
            "scan_mcap_usd": passed_entry.get("scan_mcap"),
            "scan_at": passed_entry.get("scan_at"),
            "scan_packet_id": passed_entry.get("packet_id"),
            "current_mcap_usd": current_mcap,
            "ratio": round(ratio, 2),
            "edge_passed_at_scan": passed_entry.get("edge_passed"),
            "elapsed_hours": round((_now_ts() - passed_entry.get("scan_at_ts", _now_ts())) / 3600.0, 1),
            "lesson_prompt": _lesson_prompt,
        },
        "decision_inputs": _decision_inputs(
            [
                {"action_type": "log_lesson",  "when_this_fits": "the gate was wrong and should change"},
                {"action_type": "ignore",      "when_this_fits": "the gate was right; this was variance"},
                {"action_type": "view_packet", "when_this_fits": "want to see what the gate saw"},
            ] + ([
                {"action_type": "fire_buy_signal",
                 "when_this_fits": "door still open, miss is fresh, and it has NOT run away yet"},
            ] if _chase_allowed else []),
            note=("LESSON ONLY. This is not a trade prompt — it is a gate test. "
                  "'Ignore' is the correct answer most of the time, because a gate "
                  "that rejects nine and misses the tenth is working as designed. "
                  + ("The buy option is shown because the door is provably still "
                     "open, the miss is under 6h old, and it hasn't run 3x."
                     if _chase_allowed else
                     "No buy option: chasing is gated off for this one."))
        ),
        "actions_taken": [],
    }
    
    write_inbox_packet_generic(packet, prefix=f"missed_runner_{mint[:8]}", identifier=mint[:8])
    append_miss_book("missed_runner_alert", mint, {
        "ticker": ticker, "ratio": ratio, "source": passed_entry.get("_source"),
    })
    _log(f"missed_runner: ${ticker} ran {ratio:.1f}x, packet written ({_short_mint(mint)})", prefix="mra")


async def social_research_response_handler_loop() -> None:
    """
    Watch json_relay/social_research_response.json for research responder replies to
    our who_shilling requests. For each completed response:
      1. Update enrichment_input X-account data (followers, age, etc)
      2. Record observed shillers in shiller_pending for that mint
      3. Write a shiller_intelligence packet to inbox
    
    Sprint 28.4.4: After processing, write back ONLY unprocessed responses.
    Each processed response → bot_logs/social_research_response_history.jsonl

    ── FIX 3 (2026-08-16): THIS IS A DRAIN, NOT A PIPE ─────────────────────────
    Nothing writes DEAD_SOCIAL_RESEARCH_RES_FILE any more. `who_shilling` has
    aliased to deep_research scopes ["x"] since Sprint 28.4, and
    `execute_who_shilling` , the only writer of the request side , has no live
    caller. This loop kept its supervised heartbeat, so the task roster showed a
    healthy social research pipe that had not carried a message in months.

    It stays running only to drain a leftover file if one is still on disk. It
    now says so ONCE on the first poll instead of impersonating live plumbing,
    and the cadence note is honest: it sleeps 10s, not the 5s the skill table
    claims.
    """
    _log("social_research_handler: starting , DEAD PIPE drain only "
         "(who_shilling is an alias for deep_research[x]; nothing writes this file). "
         "Polls every 10s.", prefix="srh")
    if not PIPE_RESEARCH_ENABLED:
        _log("social_research_handler: research pipe off (PIPE_RESEARCH_ENABLED=0) - idle", prefix="dr")
        while True:
            await write_heartbeat("social_research_handler", "disabled", {"pipe": "research", "enabled": False})
            await asyncio.sleep(300)
    
    seen_request_ids: set = set()
    _dead_pipe_logged = False
    
    while True:
        try:
            await write_heartbeat("social_research_handler", "polling", {
                "pipe_status": "dead_drain_only",
                "live_replacement": "deep_research scopes=[x]",
            })
            
            if not DEAD_SOCIAL_RESEARCH_RES_FILE.exists():
                await asyncio.sleep(10)
                continue
            
            if not _dead_pipe_logged:
                _dead_pipe_logged = True
                _log("social_research_handler: dead_pipe_ignored , a "
                     "social_research_response.json exists but this pipe is retired. "
                     "Draining it once; the live path is deep_research scopes=[x].",
                     prefix="srh")
            
            data = load_json_with_staleness(SOCIAL_RESEARCH_RES_FILE, max_age_seconds=86400 * 7, default={"responses": []}, alert_on_stale=False)
            if not isinstance(data, dict):
                data = {"responses": []}
            data.pop("_meta", None)
            
            responses = data.get("responses") or []
            if not responses:
                await asyncio.sleep(10)
                continue
            
            unprocessed_remaining = []
            cycle_processed = 0
            
            for r in responses:
                if not isinstance(r, dict):
                    continue
                req_id = r.get("request_id")
                mint = r.get("mint")
                if not req_id or not mint:
                    continue  # malformed, drop
                if req_id in seen_request_ids:
                    continue  # already processed, drop
                
                seen_request_ids.add(req_id)
                cycle_processed += 1
                
                try:
                    # Record shillers observed
                    shillers = r.get("shillers_observed") or []
                    if shillers:
                        handles = [s.get("handle") for s in shillers if s.get("handle")]
                        shiller_pending_record(mint, handles)
                    
                    # Build a shiller_intelligence packet
                    await _write_shiller_intelligence_packet(r)
                    
                    # Audit
                    try:
                        _append_jsonl(SOCIAL_RESEARCH_HISTORY_LOG, {
                            "request_id": req_id,
                            "mint": mint,
                            "shillers_count": len(shillers),
                            "processed_at": _now_iso(),
                        })
                    except Exception:
                        pass
                except Exception as e:
                    _log(f"social_research_handler: error processing {req_id}: {e}", prefix="srh")
                    try:
                        _append_jsonl(SOCIAL_RESEARCH_HISTORY_LOG, {
                            "request_id": req_id,
                            "mint": mint,
                            "status": "errored",
                            "error": str(e)[:300],
                            "processed_at": _now_iso(),
                        })
                    except Exception:
                        pass
            
            # Write back only unprocessed
            try:
                data["responses"] = unprocessed_remaining
                _save_json_atomic(SOCIAL_RESEARCH_RES_FILE, data)
            except Exception as e:
                _log(f"social_research_handler: failed to write back cleaned responses: {e}", prefix="srh")
            
            if cycle_processed:
                _log(
                    f"social_research_handler: batch done , processed {cycle_processed}, "
                    f"file now has {len(unprocessed_remaining)} pending",
                    prefix="srh",
                )
            
            # Trim seen_request_ids if it grows too big
            if len(seen_request_ids) > 500:
                seen_request_ids = set(list(seen_request_ids)[-200:])
        except Exception as e:
            _log(f"social_research_handler: poll error: {e}", prefix="srh")
        
        await asyncio.sleep(10)  # poll every 10s


async def _write_shiller_intelligence_packet(response: dict) -> None:
    """Convert a research responder response into an inbox shiller_intelligence packet."""
    mint = response.get("mint")
    if not mint:
        return
    
    twitter_data = response.get("twitter_account_data") or {}
    shillers = response.get("shillers_observed") or []
    
    # Look up KOL list to tier the shillers
    kol_list = load_json_with_staleness(KOL_LIST_FILE, max_age_seconds=86400 * 7, default={}, alert_on_stale=False)
    if not isinstance(kol_list, dict):
        kol_list = {}
    
    # Enrich each shiller with KOL tier + shiller_track
    enriched_shillers = []
    for s in shillers:
        handle = (s.get("handle") or "").lstrip("@").lower()
        if not handle:
            continue
        
        # KOL tier lookup (v14.2 fix: the file nests tiers -> kols -> handle; the old
        # loop read top-level keys + a "handles" field that never existed, so every
        # shiller was "unranked").
        kol_tier = kol_seed_lookup(handle).get("tier") or "unranked"
        
        # Shiller track lookup
        track = shiller_track_get(handle)
        
        enriched_shillers.append({
            "handle": f"@{handle}",
            "follower_count": s.get("follower_count"),
            "kol_tier": kol_tier,
            "rank": entity_card("kol", handle),
            "shiller_track_rug_rate": track.get("rug_rate", 0.0),
            "shiller_track_rug_count": track.get("rug_count", 0),
            "shiller_track_win_count": track.get("win_count", 0),
            "shiller_track_rug_pattern": track.get("rug_pattern") or None,
            "tweet_excerpt": s.get("tweet_excerpt"),
        })
    
    packet_id = f"x_evt_shiller_intel_{mint[:8]}_{int(_now_ts())}"
    packet = {
        "id": packet_id,
        "type": "shiller_intelligence",
        "received_at": _now_iso(),
        **_lane_fields("shiller_intelligence"),
        "from_user": {"username": "@meme_sniper", "friendship_tier": "system", "user_id": "meme_sniper_bot"},
        "context": {
            "mint": mint,
            "ticker": response.get("ticker") or "?",
            "twitter_account_data": twitter_data,
            "shillers_observed": enriched_shillers,
            "originating_request_id": response.get("request_id"),
            "completed_at": response.get("completed_at"),
        },
        "decision_inputs": _decision_inputs([
            {"action_type": "view_packet", "when_this_fits": "review shiller details"},
            {"action_type": "ignore", "when_this_fits": "no actionable signal"},
        ]),
        "actions_taken": [],
    }
    
    write_inbox_packet_generic(packet, prefix=f"shiller_intel_{mint[:8]}", identifier=mint[:8])
    _log(f"shiller_intel packet written for {_short_mint(mint)} ({len(enriched_shillers)} shillers)", prefix="srh")


# ═══════════════════════════════════════════════════════════════════════════
# SPRINT 32 v2.7: 6:05AM ET MORNING PACKET (sequenced after flow_cycle's 6:00am)
# ═══════════════════════════════════════════════════════════════════════════
# Each morning at 6:05am ET, sniper composes and writes a state snapshot to
# the agent's inbox. If the optional flow feed is on (PIPE_FLOW_ENABLED), it reads
# flow_cycle's morning state first so the packet carries that regime context.
#
# Sniper's morning packet contains:
#   - Overnight autopsy summary (what positions resolved while we slept)
#   - Current watchlist state (what's being tracked)
#   - Active positions snapshot
#   - Regime reference (from flow_morning_thesis_request.json)
#   - Pattern engine status
#   - agent-prompt-question for the day's strategy

def _is_sniper_morning_packet_due() -> bool:
    """6:05am ET cron, once per day."""
    state = {}
    try:
        if SNIPER_MORNING_STATE_FILE.exists():
            state = json.loads(SNIPER_MORNING_STATE_FILE.read_text(encoding="utf-8"))
    except Exception:
        state = {}
    
    now = datetime.now(EST)
    today_str = now.strftime("%Y-%m-%d")
    today_605am = now.replace(hour=6, minute=5, second=0, microsecond=0)
    
    if now < today_605am:
        return False
    
    if state.get("last_fired_date") == today_str:
        return False  # already fired today
    
    return True


def _record_sniper_morning_packet_fired() -> None:
    now = datetime.now(EST)
    state = {
        "last_fired_at":   _now_iso(),
        "last_fired_date": now.strftime("%Y-%m-%d"),
        "next_fire_eligible_after": (now + timedelta(days=1)).replace(hour=6, minute=5, second=0, microsecond=0).isoformat(),
    }
    try:
        SNIPER_MORNING_STATE_FILE.write_text(json.dumps(state, indent=2), encoding="utf-8")
    except Exception as e:
        _log(f"morning packet state write err: {e}", prefix="morning")


def _read_flow_morning_thesis() -> dict:
    """
    Read flow_cycle's morning packet (which fired at 6:00am, 5min before this).
    Returns the macro snapshot, regime, horse race state for context.
    Empty dict if flow's packet isn't there yet (sniper fired too early or flow is down).
    """
    if not FLOW_MORNING_PACKET_FILE.exists():
        return {}
    try:
        return json.loads(FLOW_MORNING_PACKET_FILE.read_text(encoding="utf-8"))
    except Exception as e:
        _log(f"flow morning thesis read err: {e}", prefix="morning")
        return {}


async def fire_sniper_morning_packet() -> None:
    """Compose and write sniper's morning packet to the agent's inbox."""
    flow_packet = _read_flow_morning_thesis()
    flow_macro = flow_packet.get("macro_snapshot", {})
    flow_brain = flow_packet.get("brain_consensus", {})
    flow_horse = flow_packet.get("horse_race_standings", {})
    
    # Snapshot sniper's current state
    try:
        positions_data = json.loads(POSITIONS_FILE.read_text(encoding="utf-8")) if POSITIONS_FILE.exists() else []
    except Exception:
        positions_data = []
    
    try:
        watchlist_data = json.loads(WATCHLIST_FILE.read_text(encoding="utf-8")) if WATCHLIST_FILE.exists() else {}
    except Exception:
        watchlist_data = {}
    
    open_positions_count = len([p for p in positions_data if p.get("status") == "open"]) if isinstance(positions_data, list) else 0
    watchlist_count = len(watchlist_data) if isinstance(watchlist_data, dict) else 0
    
    # Recent autopsies (overnight resolution summary)
    autopsies_recent = []
    try:
        if AUTOPSY_REPORTS_FILE.exists():
            with open(AUTOPSY_REPORTS_FILE, "r", encoding="utf-8") as f:
                autopsies_data = json.load(f)
            if isinstance(autopsies_data, list):
                autopsies_recent = autopsies_data[-10:]
            elif isinstance(autopsies_data, dict):
                autopsies_recent = list(autopsies_data.values())[-10:] if autopsies_data else []
    except Exception:
        autopsies_recent = []
    
    # BUGFIX (Sprint 54): autopsy_reports.json writes `pnl_sol`, not `realized_pnl_sol`.
    # The morning brief was reporting 0.0 overnight PnL and 0 wins / 0 losses on EVERY
    # trade — a silent blank that looked like a quiet night instead of a broken read.
    def _pnl_of(a):
        return float(a.get("pnl_sol", a.get("realized_pnl_sol", 0)) or 0)
    overnight_pnl = sum(_pnl_of(a) for a in autopsies_recent)
    overnight_wins = len([a for a in autopsies_recent if _pnl_of(a) > 0])
    overnight_losses = len([a for a in autopsies_recent if _pnl_of(a) < 0])
    
    packet = {
        "id":          f"sniper_morning_{datetime.now().strftime('%Y%m%d_%H%M%S')}",
        "from":        "meme_sniper",
        "to":          "agent",
        "type":        "morning_state_snapshot",
        "fired_at":    _now_iso(),
        "regime_context_from_flow_cycle": {
            "flow_packet_present":  bool(flow_packet),
            "blowoff_signal":       flow_brain.get("signal", "?"),
            "blowoff_phase":        flow_brain.get("phase", "?"),
            "horse_race_state":     flow_horse.get("state", "?"),
            "horse_race_explanation": flow_horse.get("explanation", "?"),
            "leverage_recommendation": flow_horse.get("leverage_recommendation", "?"),
            "btc_price":            flow_macro.get("btc_price"),
            "blowoff_score":        flow_macro.get("blowoff_score"),
        },
        "sniper_state": {
            "open_positions":       open_positions_count,
            "watchlist_size":       watchlist_count,
            "overnight_autopsies":  len(autopsies_recent),
            "overnight_pnl_sol":    round(overnight_pnl, 4),
            "overnight_wins":       overnight_wins,
            "overnight_losses":     overnight_losses,
            "win_rate_overnight":   round(overnight_wins / max(1, overnight_wins + overnight_losses) * 100, 1),
            "_overnight_note": ("Overnight counts EXIT LEGS, not positions — a scale-out "
                                "shows as several. For the true record see realized_pnl below."),
        },
        # 2026-07-27: The agent could not see his own PnL anywhere. Overnight legs
        # were the only number, and they over-count scale-outs. This is the real
        # one: positions, scratch-banded, lifetime — same rules as the scoreboard.
        "realized_pnl": realized_summary(),
        "agent_prompt_question": (
            "Given flow_cycle's regime read above and sniper's overnight performance, "
            "what's your strategy for today? Should sniper tighten/loosen filters? "
            "Pause scanning given regime? Hunt aggressively? "
            "If you want to tune sniper, write directives to sniper_meeting.json. "
            "If you want to halt trading, write to agent_signals.json with action=halt."
        ),
        "doctrine": "Daily 6:05am ritual. Sniper's state delivered to the agent with flow_cycle's regime context already layered in. Sequenced architecture (flow first at 6:00am, sniper at 6:05am).",
    }
    
    try:
        # Sprint 45 inbox doctrine: conforming, timestamped filename so each
        # morning packet is unique (a fixed name collided in inbox_results/done/,
        # overwriting prior snapshots). Internal "id" already carries the date.
        _sm_ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        _sm_path = _INBOX / f"meme_sniper - morning_snapshot_{_sm_ts}.json"
        _sm_path.write_text(json.dumps(packet, indent=2), encoding="utf-8")
        _record_sniper_morning_packet_fired()
        _log(f"6:05AM RITUAL: morning packet fired (open_positions={open_positions_count}, "
             f"overnight_pnl={overnight_pnl:.4f} SOL, wr={packet['sniper_state']['win_rate_overnight']}%)",
             prefix="morning")
    except Exception as e:
        _log(f"morning packet write err: {e}", prefix="morning")


async def morning_packet_loop() -> None:
    """
    Sniper's morning packet supervised task. Polls every 60s; when 6:05am ET
    arrives and we haven't fired today, composes and writes the packet.
    Cheap polling, work only fires once per day.
    """
    if not PIPE_FLOW_ENABLED:
        _log("morning_packet_loop: flow pipe off (PIPE_FLOW_ENABLED=0) - morning packet skipped", prefix="morning")
        while True:
            await write_heartbeat("morning_packet", "disabled", {"pipe": "flow", "enabled": False})
            await asyncio.sleep(3600)
    _log("morning_packet_loop: starting (will fire at 6:05am ET daily)", prefix="morning")
    while True:
        try:
            if _is_sniper_morning_packet_due():
                await fire_sniper_morning_packet()
        except Exception as e:
            _log(f"morning_packet_loop cycle err: {e}", prefix="morning")
        
        await asyncio.sleep(60)


