def _start_trench_news() -> None:
    """Trench News runs INSIDE Sniper: daemon thread, starts and stops with the engine.
    TRENCH_NEWS_ENABLED=false turns it off. An OS lock (bot_logs/trench_news.lock) stops a
    second copy. Any failure here is logged and ignored - it can never affect trading."""
    try:
        if os.environ.get("TRENCH_NEWS_ENABLED", "true").strip().lower() in ("0", "false", "no", "off"):
            _log("[boot] trench_news: disabled (TRENCH_NEWS_ENABLED=false)", prefix="boot")
            return
        _here = os.path.dirname(os.path.abspath(__file__))
        for _d in (_here, os.path.join(_here, "sub-bots")):
            if os.path.isfile(os.path.join(_d, "trench_news.py")) and _d not in sys.path:
                sys.path.insert(0, _d)
        import trench_news as _tn
        _log(f"[boot] trench_news: {_tn.start_background()}", prefix="boot")
    except Exception as _e:
        _log(f"[boot] trench_news not started (non-fatal): {type(_e).__name__}: {str(_e)[:120]}", prefix="boot")


